final_template:
data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

resource "aws_kms_key" "sqs" {
  description             = "Customer-managed KMS key for SQS queue encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow SQS Service to Use Key"
        Effect = "Allow"
        Principal = {
          Service = "sqs.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
        Condition = {
          ArnLike = {
            "kms:EncryptionContext:aws:sqs:arn" = "arn:${data.aws_partition.current.partition}:sqs:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:notificationQueue"
          }
        }
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "sqs" {
  name          = "alias/sqs-notificationQueue"
  target_key_id = aws_kms_key.sqs.key_id
}

resource "aws_sqs_queue" "notification" {
  name                      = "notificationQueue"
  delay_seconds             = 0
  max_message_size          = 2048
  visibility_timeout_seconds = 30
  message_retention_seconds = 345600

  kms_master_key_id                 = aws_kms_key.sqs.arn
  kms_data_key_reuse_period_seconds = 300

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "queue" {
  statement {
    sid    = "AllowCurrentAccountQueueActions"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions = [
      "sqs:SendMessage",
      "sqs:ReceiveMessage",
      "sqs:DeleteMessage",
      "sqs:GetQueueAttributes",
    ]

    resources = [aws_sqs_queue.notification.arn]
  }
}

resource "aws_sqs_queue_policy" "notification" {
  queue_url = aws_sqs_queue.notification.id
  policy    = data.aws_iam_policy_document.queue.json
}

variable "framework_name" {
  description = "Name for the AWS Backup framework"
  type        = string
  default     = "benchmark"
}

variable "framework_description" {
  description = "Description for the AWS Backup framework"
  type        = string
  default     = "benchmark"
}

variable "tag_key" {
  description = "Tag key for the Backup framework"
  type        = string
  default     = "BenchmarkTag"
}

resource "null_resource" "this" {
  # Trivial null resource used to generate a unique ID for framework tagging
}

resource "aws_backup_framework" "this" {
  name        = var.framework_name
  description = var.framework_description

  control {
    name = "BACKUP_RESOURCES_PROTECTED_BY_BACKUP_PLAN"

    scope {
      compliance_resource_types = ["EBS"]
    }
  }

  tags = {
    (var.tag_key) = null_resource.this.id
  }
}

resource "aws_kms_key" "main" {
  description             = "Symmetric KMS key for general encryption and decryption"
  deletion_window_in_days = 10
  enable_key_rotation     = false

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "*"
        }
        Action   = "*"
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "main" {
  name          = "alias/bar"
  target_key_id = aws_kms_key.main.id
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "main"
  }
}

resource "aws_security_group" "alb" {
  name        = "alb"
  description = "Security group for the ALB"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "alb"
  }
}

resource "aws_vpc_security_group_ingress_rule" "alb_http" {
  security_group_id = aws_security_group.alb.id
  cidr_ipv4         = "0.0.0.0/0"
  from_port         = 80
  to_port           = 80
  ip_protocol       = "tcp"
}

resource "aws_vpc_security_group_egress_rule" "alb_vpc_out" {
  security_group_id = aws_security_group.alb.id
  cidr_ipv4         = aws_vpc.main.cidr_block
  ip_protocol       = "-1"
}

resource "aws_security_group" "allow_alb" {
  name        = "allow_alb"
  description = "Security group for backend instances allowing traffic from ALB"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "allow_alb"
  }
}

resource "aws_vpc_security_group_ingress_rule" "allow_alb_http" {
  security_group_id            = aws_security_group.allow_alb.id
  referenced_security_group_id = aws_security_group.alb.id
  from_port                    = 80
  to_port                      = 80
  ip_protocol                  = "tcp"
}

resource "aws_vpc_security_group_egress_rule" "allow_alb_vpc_out" {
  security_group_id = aws_security_group.allow_alb.id
  cidr_ipv4         = aws_vpc.main.cidr_block
  ip_protocol       = "-1"
}

data "aws_partition" "current" {}
data "aws_caller_identity" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
}

# IAM role for Lambda execution with VPC and EFS access
resource "aws_iam_role" "lambda_vpc_efs_role" {
  name               = "lambda-vpc-efs-execution-role"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json

  tags = {
    Name = "Lambda VPCEFS Execution Role"
  }
}

data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    effect  = "Allow"

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

# AWS-managed policy: AWSLambdaVPCAccessExecutionRole
resource "aws_iam_role_policy_attachment" "vpc_access" {
  role       = aws_iam_role.lambda_vpc_efs_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSLambdaVPCAccessExecutionRole"
}

# AWS-managed policy: AmazonElasticFileSystemClientFullAccess
resource "aws_iam_role_policy_attachment" "efs_client_full_access" {
  role       = aws_iam_role.lambda_vpc_efs_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/AmazonElasticFileSystemClientFullAccess"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "public-networking-vpc"
  }
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "public-networking-subnet"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "public-networking-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "public-networking-route-table"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

variable "instance_id" {
  description = "Instance ID to associate the Elastic IP with"
  type        = string
  default     = ""
}

resource "aws_eip" "main" {
  instance = var.instance_id != "" ? var.instance_id : null
  domain   = "vpc"

  tags = {
    Name = "public-networking-eip"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

variable "resource_name_prefix" {
  description = "Prefix for resource names"
  type        = string
  default     = "test"
}

locals {
  name_prefix = var.resource_name_prefix
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block                       = "10.0.0.0/16"
  assign_generated_ipv6_cidr_block = true
  enable_dns_support               = true
  enable_dns_hostnames             = true

  tags = {
    Name = "${local.name_prefix}-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-igw"
  }
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]
  ipv6_cidr_block   = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, 0)

  tags = {
    Name = "${local.name_prefix}-public-subnet"
  }
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "${local.name_prefix}-private-subnet"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${local.name_prefix}-public-route-table"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

locals {
  account_id = data.aws_caller_identity.current.account_id

  # List of additional bucket suffixes
  additional_bucket_list = ["bucket101", "bucket102", "bucket103", "bucket104"]

  # Map derived from the list, defines additional buckets using map and list collections
  additional_bucket_map = {
    for suffix in local.additional_bucket_list : suffix => suffix
  }
}

data "aws_caller_identity" "current" {}

# Single shared KMS key for SSE-KMS encryption
resource "aws_kms_key" "sse" {
  description             = "Shared KMS key for S3 bucket SSE-KMS encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "sse" {
  name          = "alias/s3-sse-kms-key"
  target_key_id = aws_kms_key.sse.key_id
}

# Standalone bucket with suffix "bucket2"
resource "aws_s3_bucket" "bucket2" {
  bucket = "${local.account_id}-bucket2"
}

resource "aws_s3_bucket_public_access_block" "bucket2" {
  bucket = aws_s3_bucket.bucket2.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "bucket2" {
  bucket = aws_s3_bucket.bucket2.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.sse.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# Count-based buckets: bucket3 and bucket4
resource "aws_s3_bucket" "count_buckets" {
  count  = 2
  bucket = "${local.account_id}-bucket${count.index + 3}"
}

resource "aws_s3_bucket_public_access_block" "count_buckets" {
  count  = 2
  bucket = aws_s3_bucket.count_buckets[count.index].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "count_buckets" {
  count  = 2
  bucket = aws_s3_bucket.count_buckets[count.index].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.sse.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# Additional buckets defined via local map (derived from list): bucket101 through bucket104
resource "aws_s3_bucket" "additional" {
  for_each = local.additional_bucket_map
  bucket   = "${local.account_id}-${each.key}"
}

resource "aws_s3_bucket_public_access_block" "additional" {
  for_each = local.additional_bucket_map
  bucket   = aws_s3_bucket.additional[each.key].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "additional" {
  for_each = local.additional_bucket_map
  bucket   = aws_s3_bucket.additional[each.key].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.sse.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# Terraform configuration for AWS Budget with SNS notifications

data "aws_caller_identity" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
}

# KMS key for SNS topic encryption
resource "aws_kms_key" "budget" {
  description              = "KMS key for SNS topic encryption"
  deletion_window_in_days  = 7
  key_usage                = "ENCRYPT_DECRYPT"
  customer_master_key_spec = "SYMMETRIC_DEFAULT"
}

locals {
  kms_key_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable Root Account Access"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow Budgets Service to Use Key"
        Effect = "Allow"
        Principal = {
          Service = "budgets.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey",
          "kms:DescribeKey",
        ]
        Resource = "*"
      },
    ]
  })
}

# Assign the policy to the KMS key
resource "aws_kms_key_policy" "budget" {
  key_id = aws_kms_key.budget.id
  policy = local.kms_key_policy
}

# SNS topic for budget notifications
resource "aws_sns_topic" "budget" {
  name              = "budget"
  kms_master_key_id = aws_kms_key.budget.arn
}

# SNS topic policy allowing AWS Budgets to publish
resource "aws_sns_topic_policy" "budget" {
  arn = aws_sns_topic.budget.arn
  policy = jsonencode({
    Version = "2008-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "budgets.amazonaws.com"
        }
        Action   = "SNS:Publish"
        Resource = aws_sns_topic.budget.arn
      },
    ]
  })
}

# SMS subscription on the topic
resource "aws_sns_topic_subscription" "sms" {
  topic_arn = aws_sns_topic.budget.arn
  protocol  = "sms"
  endpoint  = "+447828835419"
}

# Monthly cost budget with notifications
resource "aws_budgets_budget" "budget" {
  name              = "budget"
  budget_type       = "COST"
  limit_amount      = "25.0"
  limit_unit        = "USD"
  time_unit         = "MONTHLY"
  time_period_start = "2021-07-01_00:00"

  notification {
    comparison_operator        = "GREATER_THAN"
    threshold                  = 100
    threshold_type             = "PERCENTAGE"
    notification_type          = "ACTUAL"
    subscriber_email_addresses = ["hello@chriswilding.co.uk"]
    subscriber_sns_topic_arns  = [aws_sns_topic.budget.arn]
  }
}

terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
  }
}

data "aws_partition" "current" {}

# ECR repository for the React application container images.
resource "aws_ecr_repository" "reactjs_app" {
  name                 = "reactjs-app-repo"
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  encryption_configuration {
    encryption_type = "AES256"
  }

  tags = {
    Name = "reactjs-app-repo"
  }
}

# IAM role assumed by ECS tasks to pull images and write logs.
resource "aws_iam_role" "ecs_task_execution" {
  name = "ecsTaskExecutionRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "ecsTaskExecutionRole"
  }
}

# Attach the AWS-managed AmazonECSTaskExecutionRolePolicy to the execution role.
resource "aws_iam_role_policy_attachment" "ecs_task_execution" {
  role       = aws_iam_role.ecs_task_execution.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_iam_role" "role" {
  name = "role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "allow_policy_1" {
  name = "allow-policy-1"
  role = aws_iam_role.role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "iam:PassRole"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy" "allow_policy_2" {
  name = "allow-policy-2"
  role = aws_iam_role.role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "lambda:CreateFunction",
          "lambda:InvokeFunction",
          "lambda:InvokeAsync"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_efs_file_system" "main" {
  creation_token = "efs-not-secure"
  encrypted      = true

  tags = {
    Name = "NotSecure"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_efs_file_system_policy" "main" {
  file_system_id = aws_efs_file_system.main.id

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "ExamplePolicy01"
    Statement = [
      {
        Sid    = "ExampleStatement01"
        Effect = "Allow"
        Principal = {
          AWS = "*"
        }
        Action = [
          "elasticfilesystem:*"
        ]
      }
    ]
  })
}

# KMS key for S3 bucket encryption
resource "aws_kms_key" "s3_encryption" {
  description             = "KMS key for S3 bucket encryption - terraform-remote-state-storage-s3-kjg"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "key-default-1"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
    ]
  })

  tags = {
    Name = "terraform-remote-state-s3-kms-key"
  }
}

resource "aws_kms_alias" "s3_encryption" {
  name          = "alias/terraform-remote-state-s3-key"
  target_key_id = aws_kms_key.s3_encryption.key_id
}

# S3 bucket for remote state storage
resource "aws_s3_bucket" "remote_state" {
  bucket        = "terraform-remote-state-storage-s3-kjg"
  force_destroy = false

  tags = {
    Name = "terraform-remote-state-storage-s3-kjg"
  }
}

# Block all public access
resource "aws_s3_bucket_public_access_block" "remote_state" {
  bucket = aws_s3_bucket.remote_state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Enable versioning
resource "aws_s3_bucket_versioning" "remote_state" {
  bucket = aws_s3_bucket.remote_state.id
  versioning_configuration {
    status = "Enabled"
  }
}

# Default server-side encryption with KMS
resource "aws_s3_bucket_server_side_encryption_configuration" "remote_state" {
  bucket = aws_s3_bucket.remote_state.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.s3_encryption.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

# DynamoDB table for state locking
resource "aws_dynamodb_table" "state_lock" {
  name           = "terraform-state-lock-dynamo"
  billing_mode   = "PROVISIONED"
  hash_key       = "LockID"
  read_capacity  = 20
  write_capacity = 20

  attribute {
    name = "LockID"
    type = "S"
  }

  tags = {
    Name = "terraform-state-lock-dynamo"
  }
}

# Data source for current AWS account ID
data "aws_caller_identity" "current" {}

resource "random_pet" "name" {
  length    = 2
  separator = "-"
}

resource "aws_cloudwatch_log_group" "main" {
  name              = "log-group-${random_pet.name.id}"
  retention_in_days = 30

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route53_delegation_set" "website_dns" {
  reference_name = "WebsiteDNS"
}

resource "aws_ssm_parameter" "delegation_set_id" {
  name  = "/WebsiteCv/production/Route53/DelegationSetId"
  type  = "String"
  value = aws_route53_delegation_set.website_dns.id

  tags = {
    project     = "Website CV"
    environment = "production"
  }
}

variable "bucket_name" {
  description = "Name of the S3 benchmarking bucket"
  type        = string
  default     = "benchmark-bucket-tf5x"
}

variable "name_tag" {
  description = "Value of the Name tag"
  type        = string
  default     = "benchmark"
}

variable "force_destroy" {
  description = "Force destroy the bucket even if it contains objects"
  type        = bool
  default     = true
}

locals {
  bucket_name = var.bucket_name
  name_tag    = var.name_tag
}

# Account-level S3 public access block - explicitly disable all blocks
resource "aws_s3_account_public_access_block" "this" {
  block_public_acls       = false
  block_public_policy     = false
  ignore_public_acls      = false
  restrict_public_buckets = false
}

# Customer-managed KMS key for SSE-KMS
resource "aws_kms_key" "this" {
  description             = "KMS key for S3 benchmarking bucket SSE-KMS encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.this.partition}:iam::${data.aws_caller_identity.this.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
  tags = {
    Name = local.name_tag
  }
}

resource "aws_kms_alias" "this" {
  name          = "alias/${var.bucket_name}-key"
  target_key_id = aws_kms_key.this.key_id
}

# S3 bucket
resource "aws_s3_bucket" "this" {
  bucket        = local.bucket_name
  force_destroy = var.force_destroy

  tags = {
    Name = local.name_tag
  }
}

# Bucket-level public access block - all enabled
resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# SSE-KMS server-side encryption configuration
resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.this.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# Data sources for account info
data "aws_caller_identity" "this" {}
data "aws_partition" "this" {}

variable "base_name" {
  description = "Base name used to construct the CloudTrail bucket name"
  type        = string
  default     = "benchmark"
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

locals {
  bucket_name = "${var.base_name}-cloudtrail-${data.aws_region.current.region}"
}

# KMS key for S3 SSE-KMS encryption
resource "aws_kms_key" "cloudtrail" {
  description             = "KMS key for CloudTrail S3 bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow S3 to use the key for SSE-KMS"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey",
          "kms:Decrypt"
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow CloudTrail to use the key"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey",
          "kms:Decrypt"
        ]
        Resource = "*"
      }
    ]
  })
}

data "aws_partition" "current" {}

resource "aws_kms_alias" "cloudtrail" {
  name          = "alias/${local.bucket_name}"
  target_key_id = aws_kms_key.cloudtrail.key_id
}

# S3 bucket for CloudTrail logs
resource "aws_s3_bucket" "cloudtrail" {
  bucket = local.bucket_name
  force_destroy = true
}

# Block all public access
resource "aws_s3_bucket_public_access_block" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Default SSE-KMS encryption
resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.cloudtrail.arn
    }
  }
}

# Bucket policy for CloudTrail
resource "aws_s3_bucket_policy" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id
  policy = data.aws_iam_policy_document.cloudtrail.json
}

data "aws_iam_policy_document" "cloudtrail" {
  statement {
    sid    = "CloudTrailAclCheck"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.cloudtrail.arn]
  }

  statement {
    sid    = "CloudTrailWrite"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.cloudtrail.arn}/*"]
    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
