    {
      name  = "first"
      image = "service-first"
      cpu   = 10
      memory = 512
      portMappings = [
        {
          containerPort = 80
          hostPort      = 80
        }
      ]
    },
    {
      name  = "second"
      image = "service-second"
      cpu   = 10
      memory = 256
      portMappings = [
        {
          containerPort = 443
          hostPort      = 443
        }
      ]
    }
  ])

  volume {
    name = "service-storage"
    efs_volume_configuration {
      file_system_id     = aws_efs_file_system.main.id
