}

variable "repository_name" {
  description = "Name of the Amazon ECR repository"
  type        = string
  default     = "illumidesk"
}

variable "tags" {
  description = "Map of resource tags applied to the ECR repository"
  type        = map(string)
  default = {
    Name        = "illumidesk-eks"
    Environment = "dev"
  }
}

resource "aws_ecr_repository" "this" {
  name                 = var.repository_name
  image_tag_mutability = "IMMUTABLE"
  force_delete         = false

  image_scanning_configuration {
    scan_on_push = true
  }

  tags = var.tags
}

resource "aws_ecr_lifecycle_policy" "this" {
  repository = aws_ecr_repository.this.name

  policy = jsonencode({
    rules = [
      {
        rulePriority = 1
        description  = "Expire untagged images older than 14 days since they were pushed"
        selection = {
          tagStatus   = "untagged"
          countType   = "sinceImagePushed"
          countUnit   = "days"
          countNumber = 14
        }
        action = {
          type = "expire"
        }
      },
      {
        rulePriority = 2
        description  = "Expire images when the total image count exceeds 30 for any tag status"
        selection = {
          tagStatus   = "any"
          countType   = "imageCountMoreThan"
          countNumber = 30
        }
        action = {
          type = "expire"
        }
      }
    ]
  })
}

variable "region" {
  description = "AWS region included in the secret payload"
