variable "aws_region" {
  description = "AWS region where the networking stack is deployed."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the main VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "vpc_name" {
  description = "Value of the Name tag applied to the main VPC."
  type        = string
  default     = "main-vpc"
}

variable "availability_zones" {
  description = "Availability zones in which subnets are provisioned. When not supplied, defaults to the first two availability zones available in the region."
  type        = list(string)
  default     = null
}

variable "subnet_cidr_blocks" {
  description = "CIDR blocks assigned to the subnets, one per availability zone."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "subnet_name_prefix" {
  description = "Prefix used for the index-based Name tag of each subnet."
  type        = string
  default     = "main-subnet"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  # Availability zones where subnets are created. If the caller does not pass an
  # explicit list, fall back to the first two AZs available in the region.
  azs = var.availability_zones != null ? var.availability_zones : slice(data.aws_availability_zones.available.names, 0, 2)

  # Create one subnet per availability zone, but never more than the number of
  # supplied CIDR blocks (and never exceed the number of requested AZs).
  subnet_count = min(length(local.azs), length(var.subnet_cidr_blocks))
  subnet_azs   = slice(local.azs, 0, local.subnet_count)
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true
  instance_tenancy     = "default"

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_subnet" "main" {
  count             = local.subnet_count
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_cidr_blocks[count.index]
  availability_zone = local.subnet_azs[count.index]

  tags = {
    Name = "${var.subnet_name_prefix}-${count.index + 1}"
  }
}

