resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = data.aws_iam_policy_document.bucket_policy.json
}

data "aws_iam_policy_document" "bucket_policy" {
  statement {
    sid       = "AllowFullS3AccessToAccount"
    effect    = "Allow"
    actions   = ["s3:*"]
    resources = [
      aws_s3_bucket.this.arn,
      "${aws_s3_bucket.this.arn}/*",
    ]
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${var.allowed_account_id}:root"]
    }
  }
}

# ------------------------------------------------------------------------------
# Terraform Remote State Backend
#
# Creates the AWS resources used as a Terraform remote state backend:
#   * a KMS-encrypted, versioned S3 bucket with all public access blocked
#   * a DynamoDB table (string hash key "LockID") used for state locking
# ------------------------------------------------------------------------------

locals {
  bucket_name = var.bucket_name != "" ? var.bucket_name : "terraform-remote-state-${data.aws_caller_identity.current.account_id}"

  common_tags = {
    Name        = "Terraform Remote State Backend"
    Environment = "Management"
    ManagedBy   = "Terraform"
  }
}

variable "bucket_name" {
  description = "Globally unique name for the Terraform state S3 bucket. Leave empty to generate a unique name based on the AWS account ID."
  type        = string
  default     = ""
}

variable "lock_table_name" {
  description = "Name of the DynamoDB table used for Terraform state locking."
  type        = string
  default     = "terraform-state-locks"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

# Policy granting the account root principal administrative and cryptographic
# access to the KMS key. Individual IAM users and roles in the account can then
# be granted scoped access through their own IAM policies.
data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid    = "AllowRootAccountAdministration"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions = [
      "kms:CancelKeyDeletion",
      "kms:CreateGrant",
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:DisableKey",
      "kms:EnableKey",
      "kms:EnableKeyRotation",
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:GetKeyPolicy",
      "kms:GetKeyRotationStatus",
      "kms:ListResourceTags",
      "kms:PutKeyPolicy",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
      "kms:ScheduleKeyDeletion",
      "kms:TagResource",
      "kms:UntagResource",
    ]
    resources = ["*"]
  }
}

resource "aws_kms_key" "state" {
  description             = "KMS key used to encrypt Terraform remote state stored in S3."
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json
  tags                    = local.common_tags
}

resource "aws_s3_bucket" "state" {
  bucket        = local.bucket_name
  force_destroy = false
  tags          = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.state.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket                  = aws_s3_bucket.state.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_dynamodb_table" "state_lock" {
  name         = var.lock_table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.state.arn
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_caller_identity" "current" {}

resource "aws_kms_key" "sns" {
  description             = "KMS key for SNS topic incident-response"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "key-default-1"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow SNS to use the key"
        Effect = "Allow"
        Principal = {
          Service = "sns.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey*"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "sns" {
  name          = "alias/incident-response-sns"
  target_key_id = aws_kms_key.sns.key_id
}

resource "aws_sns_topic" "incident_response" {
  name              = "incident-response"
  kms_master_key_id = aws_kms_key.sns.arn
}

resource "aws_sns_topic_policy" "incident_response" {
  arn = aws_sns_topic.incident_response.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "__default_policy_ID"
    Statement = [
      {
        Sid    = "__default_statement_ID"
        Effect = "Allow"
        Principal = {
          AWS = "*"
        }
        Action = [
          "SNS:Subscribe",
          "SNS:SetTopicAttributes",
          "SNS:RemovePermission",
          "SNS:Receive",
          "SNS:Publish",
          "SNS:ListSubscriptionsByTopic",
          "SNS:GetTopicAttributes",
          "SNS:DeleteTopic",
          "SNS:AddPermission"
        ]
        Resource = aws_sns_topic.incident_response.arn
        Condition = {
          StringEquals = {
            "AWS:SourceOwner" = data.aws_caller_identity.current.account_id
          }
        }
      },
      {
        Sid    = "AllowAWSEvents"
        Effect = "Allow"
        Principal = {
          Service = "events.amazonaws.com"
        }
        Action = [
          "SNS:Publish"
        ]
        Resource = aws_sns_topic.incident_response.arn
      }
    ]
  })
}

variable "aws_service_name" {
  description = "AWS service principal for OpenSearch/Elasticsearch"
  type        = string
  default     = "es.amazonaws.com"
}

resource "aws_iam_service_linked_role" "opensearch" {
  aws_service_name = var.aws_service_name
  description      = "Service-linked role for Amazon OpenSearch/Elasticsearch service"
}

resource "aws_cloudwatch_log_resource_policy" "elasticsearch_log_publishing" {
  policy_name     = "elasticsearch-log-publishing-policy"
  policy_document = data.aws_iam_policy_document.elasticsearch_log_publishing.json
}

data "aws_iam_policy_document" "elasticsearch_log_publishing" {
  statement {
    sid = "ElasticsearchLogPublishing"

    principals {
      identifiers = ["es.amazonaws.com"]
      type        = "Service"
    }

    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:PutLogEventsBatch",
    ]

    resources = ["*"]
  }
}

resource "aws_cognito_user_pool" "this" {
  name = "identity pool"
}

data "aws_iam_policy_document" "user_group_role_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]
    principals {
      type        = "Federated"
      identifiers = ["cognito-identity.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "cognito-identity.amazonaws.com:aud"
      values   = ["us-east-1:12345678-dead-beef-cafe-123456790ab"]
    }
    condition {
      test     = "ForAnyValue:StringLike"
      variable = "cognito-identity.amazonaws.com:amr"
      values   = ["authenticated"]
    }
  }
}

resource "aws_iam_role" "user_group_role" {
  name               = "user-group-role"
  assume_role_policy = data.aws_iam_policy_document.user_group_role_trust.json
}

resource "aws_cognito_user_group" "this" {
  user_pool_id = aws_cognito_user_pool.this.id
  name         = "user-group"
  description  = "Managed by Terraform"
  precedence   = 42
  role_arn     = aws_iam_role.user_group_role.arn
}

terraform {
  required_version = ">= 1.3"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  alias = "alt-tags"

  default_tags {
    tags = {
      ManagedBy     = "Terraform"
      ProviderAlias = "alt-tags"
      Environment   = "alternate"
    }
  }
}

resource "aws_dynamodb_table" "basic" {
  name         = "default-and-alternate-tags-module-basic"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "KeyId"

  attribute {
    name = "KeyId"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  point_in_time_recovery {
    enabled = true
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dynamodb_table" "alternate" {
  provider     = aws.alt-tags
  name         = "default-and-alternate-tags-module-alternate"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "KeyId"

  attribute {
    name = "KeyId"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  point_in_time_recovery {
    enabled = true
  }

  lifecycle {
    prevent_destroy = true
  }
}

variable "api_name" {
  description = "Name of the API Gateway REST API"
  type        = string
  default     = "terraform-api-gateway-example"
}

data "aws_region" "current" {}
data "aws_caller_identity" "current" {}

resource "aws_api_gateway_rest_api" "this" {
  name        = var.api_name
  description = "Example REST API for testing mock responses"
}

resource "aws_api_gateway_resource" "movies" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  parent_id   = aws_api_gateway_rest_api.this.root_resource_id
  path_part   = "movies"
}

resource "aws_api_gateway_method" "movies_get" {
  rest_api_id   = aws_api_gateway_rest_api.this.id
  resource_id   = aws_api_gateway_resource.movies.id
  http_method   = "GET"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "movies_get_mock" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  resource_id = aws_api_gateway_resource.movies.id
  http_method = aws_api_gateway_method.movies_get.http_method
  type        = "MOCK"

  request_templates = {
    "application/json" = jsonencode({
      statusCode = 200
    })
  }
}

resource "aws_api_gateway_method_response" "movies_get_200" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  resource_id = aws_api_gateway_resource.movies.id
  http_method = aws_api_gateway_method.movies_get.http_method
  status_code = "200"
}

resource "aws_api_gateway_integration_response" "movies_get_mock_200" {
  rest_api_id = aws_api_gateway_rest_api.this.id
  resource_id = aws_api_gateway_resource.movies.id
  http_method = aws_api_gateway_method.movies_get.http_method
  status_code = aws_api_gateway_method_response.movies_get_200.status_code

  response_templates = {
    "application/json" = jsonencode({
      message = "Hello from the movies API!"
    })
  }
}

variable "alias_name" {
  description = "Suffix used for the KMS key alias (prefixed with 'alias/')"
  type        = string
  default     = "kms-cmk-example"
}

data "aws_caller_identity" "current" {}

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid    = "EnableRootAccess"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "GrantFullAccessToCaller"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = [data.aws_caller_identity.current.arn]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }
}

resource "aws_kms_key" "this" {
  description             = "Test CMK created by Terraform"
  deletion_window_in_days = 7
  enable_key_rotation     = false
  policy                  = data.aws_iam_policy_document.kms_key_policy.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "this" {
  target_key_id = aws_kms_key.this.key_id
  name          = "alias/${var.alias_name}"
}

# Provider configurations for multi-region VPC deployment

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  alias  = "us-east-nv"
  region = "us-east-1"
  default_tags {
    tags = {
      Terraform = "yes"
      Region    = "N.Virginia"
    }
  }
}

provider "aws" {
  alias  = "ap-south-mumbai"
  region = "ap-south-1"
  default_tags {
    tags = {
      Terraform = "yes"
      Region    = "Mumbai"
    }
  }
}

# North Virginia VPC
resource "aws_vpc" "north_virginia" {
  provider = aws.us-east-nv

  cidr_block = "10.1.0.0/16"

  tags = {
    Name = "North-Virginia-VPC"
  }
}

# Mumbai VPC
resource "aws_vpc" "mumbai" {
  provider = aws.ap-south-mumbai

  cidr_block = "10.2.0.0/16"

  tags = {
    Name = "Mumbai-VPC"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "outbound-traffic-test-vpc"
  }
}

resource "aws_security_group" "allow_tcp" {
  name        = "allow_tcp"
  description = "Allow TCP traffic"
  vpc_id      = aws_vpc.main.id

  egress {
    from_port   = 10000
    to_port     = 10000
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "allow_tcp"
  }
}

resource "aws_security_group" "allow_udp" {
  name        = "allow_udp"
  description = "Allow UDP traffic"
  vpc_id      = aws_vpc.main.id

  egress {
    from_port   = 10000
    to_port     = 10000
    protocol    = "udp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "allow_udp"
  }
}

resource "aws_security_group" "allow_icmp" {
  name        = "allow_icmp"
  description = "Allow ICMP traffic"
  vpc_id      = aws_vpc.main.id

  egress {
    from_port   = -1
    to_port     = -1
    protocol    = "icmp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "allow_icmp"
  }
}

resource "aws_security_group" "allow_all" {
  name        = "allow_all"
  description = "Allow ALL traffic"
  vpc_id      = aws_vpc.main.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "allow_all"
  }
}

locals {
  name_prefix = "terraform-state"
  common_tags = {
    Environment = "terraform-state-backend"
  }
}

resource "random_id" "bucket_suffix" {
  byte_length = 4
}

resource "aws_kms_key" "state_backend" {
  description             = "Customer-managed KMS key used to encrypt Terraform state files stored in S3"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-key"
  })
}

resource "aws_kms_alias" "state_backend" {
  name          = "alias/${local.name_prefix}-key"
  target_key_id = aws_kms_key.state_backend.id
}

resource "aws_s3_bucket" "state_backend" {
  bucket = "${local.name_prefix}-${random_id.bucket_suffix.hex}"
  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-${random_id.bucket_suffix.hex}"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "state_backend" {
  bucket = aws_s3_bucket.state_backend.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state_backend" {
  bucket = aws_s3_bucket.state_backend.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.state_backend.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "state_backend" {
  bucket                  = aws_s3_bucket.state_backend.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_dynamodb_table" "terraform_lock" {
  name         = "terraform-lock"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  point_in_time_recovery {
    enabled = true
  }

  tags = merge(local.common_tags, {
    Name = "terraform-lock"
  })

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_caller_identity" "current" {}

variable "powerscale_node_regions" {
  description = "List of AWS regions to scope the PowerScale node runtime policy to"
  type        = list(string)
  default     = ["*"]
}

locals {
  account_id = data.aws_caller_identity.current.account_id
  name_prefix = local.account_id
}

resource "aws_iam_policy" "powerscale_node_runtime" {
  name        = "${local.name_prefix}-powerscale-node-runtime-policy"
  description = "Policy for PowerScale node runtime operations"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:AssignPrivateIpAddresses"
        ]
        Resource = [
          for r in var.powerscale_node_regions :
          "arn:aws:ec2:${r}:${local.account_id}:network-interface/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role" "powerscale_node_runtime" {
  name               = "${local.name_prefix}-powerscale-node-runtime-role"
  description        = "Role for PowerScale node runtime operations"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "powerscale_node_runtime" {
  role       = aws_iam_role.powerscale_node_runtime.name
  policy_arn = aws_iam_policy.powerscale_node_runtime.arn
}

resource "aws_iam_instance_profile" "powerscale_node_runtime" {
  name = "${local.name_prefix}-powerscale-node-runtime-instance-profile"
  role = aws_iam_role.powerscale_node_runtime.name
}

variable "vpc_cidr_block" {
  description = "CIDR block for the custom VPC."
  type        = string
  default     = "192.168.0.0/16"
}

variable "project" {
  description = "Project name used for resource naming and tagging."
  type        = string
  default     = "tiered-app"
}

variable "environment" {
  description = "Deployment environment used for resource tagging."
  type        = string
  default     = "dev"
}

locals {
  azs = data.aws_availability_zones.available.names
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "${var.project}-vpc"
    Project     = var.project
    Environment = var.environment
  }
}

# web subnet: first /24 of the VPC range, availability zone 1
resource "aws_subnet" "web" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, 0)
  availability_zone = local.azs[0]

  tags = {
    Name        = "${var.project}-subnet-web"
    Tier        = "web"
    Project     = var.project
    Environment = var.environment
  }
}

# app subnet: second /24 of the VPC range, availability zone 2
resource "aws_subnet" "app" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, 1)
  availability_zone = local.azs[1]

  tags = {
    Name        = "${var.project}-subnet-app"
    Tier        = "app"
    Project     = var.project
    Environment = var.environment
  }
}

# db subnet: third /24 of the VPC range, availability zone 3
resource "aws_subnet" "db" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, 2)
  availability_zone = local.azs[2]

  tags = {
    Name        = "${var.project}-subnet-db"
    Tier        = "db"
    Project     = var.project
    Environment = var.environment
  }
}

# mgmt subnet: fourth /24 of the VPC range, shares availability zone 1 with web
resource "aws_subnet" "mgmt" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, 3)
  availability_zone = local.azs[0]

  tags = {
    Name        = "${var.project}-subnet-mgmt"
    Tier        = "mgmt"
    Project     = var.project
    Environment = var.environment
  }
}

variable "role_name" {
  description = "Name of the IAM role for EC2 instances"
  type        = string
  default     = "ec2-instance-role"
}

variable "description" {
  description = "Description of the IAM role"
  type        = string
  default     = "IAM role for EC2 instances, serving as an instance profile"
}

variable "inline_policies" {
  description = "A map of inline policy names to policy JSON documents to attach to the role"
  type        = map(string)
  default     = {}
}

variable "managed_policy_arns" {
  description = "A list of ARNs for managed IAM policies to attach to the role"
  type        = list(string)
  default     = []
}

data "aws_partition" "current" {}

locals {
  ec2_service_principal = "ec2.${data.aws_partition.current.dns_suffix}"
}

data "aws_iam_policy_document" "ec2_trust" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = [local.ec2_service_principal]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "ec2" {
  name               = var.role_name
  description        = var.description
  assume_role_policy = data.aws_iam_policy_document.ec2_trust.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy" "inline" {
  for_each = var.inline_policies

  name   = each.key
  role   = aws_iam_role.ec2.name
  policy = each.value
}

resource "aws_iam_role_policy_attachment" "managed" {
  for_each = toset(var.managed_policy_arns)

  role       = aws_iam_role.ec2.name
  policy_arn = each.value
}

locals {
  cluster_name = "Fast-App"
  vpc_cidr     = "10.0.0.0/16"
}

# ---------------------------------------------------------------------------
# Data sources – static provider metadata only
# ---------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------
# VPC
# ---------------------------------------------------------------------------
resource "aws_vpc" "this" {
  cidr_block           = local.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = local.cluster_name
  }
}

# ---------------------------------------------------------------------------
# Internet Gateway
# ---------------------------------------------------------------------------
resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id

  tags = {
    Name = "${local.cluster_name}-igw"
  }
}

# ---------------------------------------------------------------------------
# Public subnets
# ---------------------------------------------------------------------------
resource "aws_subnet" "public" {
  count = length(data.aws_availability_zones.available.names)

  vpc_id                  = aws_vpc.this.id
  cidr_block              = cidrsubnet(local.vpc_cidr, 4, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.cluster_name}-public-${count.index + 1}"
    Tier = "public"
  }
}

# ---------------------------------------------------------------------------
# Private subnets
# ---------------------------------------------------------------------------
resource "aws_subnet" "private" {
  count = length(data.aws_availability_zones.available.names)

  vpc_id            = aws_vpc.this.id
  cidr_block        = cidrsubnet(local.vpc_cidr, 4, count.index + length(data.aws_availability_zones.available.names))
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${local.cluster_name}-private-${count.index + 1}"
    Tier = "private"
  }
}

# ---------------------------------------------------------------------------
# Public route table – internet access
# ---------------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.this.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.this.id
  }

  tags = {
    Name = "${local.cluster_name}-public"
  }
}

# ---------------------------------------------------------------------------
# Associate public subnets with the public route table
# ---------------------------------------------------------------------------
resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

locals {
  grafana_name = var.grafana_workspace_name
  role_name    = "${local.grafana_name}-MonitoringRole"
  policy_name  = "${local.grafana_name}-MonitoringPolicy"
}

variable "grafana_workspace_name" {
  description = "Name of the AWS Managed Grafana workspace"
  type        = string
  default     = "Grafana"
}

variable "monitoring_account_ids" {
  description = "List of AWS account IDs allowed to assume the monitoring role"
  type        = list(string)
  default     = []
}

# IAM policy document for the trust relationship
data "aws_iam_policy_document" "grafana_trust_policy" {
  statement {
    sid    = "AllowAssumeRoleFromMonitoringAccounts"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [for account_id in var.monitoring_account_ids : "arn:aws:iam::${account_id}:root"]
    }

    actions = ["sts:AssumeRole"]
  }
}

# IAM policy document for Grafana permissions (AMP + CloudWatch)
data "aws_iam_policy_document" "grafana_permissions_policy" {
  statement {
    sid    = "AllowQueryAmazonManagedPrometheus"
    effect = "Allow"

    actions = [
      "aps:QueryMetrics",
      "aps:GetSeries",
      "aps:GetLabels",
      "aps:GetMetricMetadata",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowReadCloudWatchMetrics"
    effect = "Allow"

    actions = [
      "cloudwatch:GetMetricData",
      "cloudwatch:GetMetricStatistics",
      "cloudwatch:ListMetrics",
      "cloudwatch:DescribeAlarms",
    ]

    resources = ["*"]
  }
}

# IAM role that can be assumed by monitoring accounts
resource "aws_iam_role" "grafana_monitoring_role" {
  name               = local.role_name
  assume_role_policy = data.aws_iam_policy_document.grafana_trust_policy.json

  description = "IAM role for AWS Managed Grafana workspace ${local.grafana_name} to query AMP and CloudWatch"

  tags = {
    Name = local.role_name
  }
}

# IAM policy with Grafana permissions
resource "aws_iam_policy" "grafana_monitoring_policy" {
  name        = local.policy_name
  description = "Custom policy for AWS Managed Grafana workspace ${local.grafana_name} to query AMP and CloudWatch"
  policy      = data.aws_iam_policy_document.grafana_permissions_policy.json

  tags = {
    Name = local.policy_name
  }
}

# Attach the policy to the role
resource "aws_iam_role_policy_attachment" "grafana_monitoring_attachment" {
  role       = aws_iam_role.grafana_monitoring_role.name
  policy_arn = aws_iam_policy.grafana_monitoring_policy.arn
}

output "grafana_monitoring_role_arn" {
  description = "ARN of the IAM role for Grafana monitoring"
  value       = aws_iam_role.grafana_monitoring_role.arn
}

output "grafana_monitoring_policy_arn" {
  description = "ARN of the IAM policy for Grafana monitoring"
  value       = aws_iam_policy.grafana_monitoring_policy.arn
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "test-vpc"
  }
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "test-subnet-private-${count.index + 1}"
  }
}

output "vpc_id" {
  description = "ID of the created VPC"
  value       = aws_vpc.main.id
}

output "private_subnet_1_id" {
  description = "ID of the first private subnet"
  value       = aws_subnet.private[0].id
}

output "private_subnet_2_id" {
  description = "ID of the second private subnet"
  value       = aws_subnet.private[1].id
}

output "private_subnet_1_cidr" {
  description = "CIDR block of the first private subnet"
  value       = aws_subnet.private[0].cidr_block
}

output "private_subnet_2_cidr" {
  description = "CIDR block of the second private subnet"
  value       = aws_subnet.private[1].cidr_block
}

output "private_subnet_ids" {
  description = "Aggregated list of private subnet IDs"
  value       = aws_subnet.private[*].id
}

output "private_subnet_cidrs" {
  description = "Aggregated list of private subnet CIDR blocks"
  value       = aws_subnet.private[*].cidr_block
}

output "public_subnet_ids" {
  description = "Aggregated list of public subnet IDs (mirrors the private subnets)"
  value       = aws_subnet.private[*].id
}

output "public_subnet_cidrs" {
  description = "Aggregated list of public subnet CIDR blocks (mirrors the private subnets)"
  value       = aws_subnet.private[*].cidr_block
}

locals {
  vpc_cidr = "10.0.0.0/16"
  name_prefix = "trade-tariff-dev"
}

# Data source for available AZs
data "aws_availability_zones" "available" {
  state = "available"
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "trade-tariff-development-vpc"
  }
}

# Public subnets (one per AZ, 2 AZs)
resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(local.vpc_cidr, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${local.name_prefix}-public-${count.index + 1}"
  }
}

# Private subnets (one per AZ, 2 AZs)
resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(local.vpc_cidr, 8, count.index + 2)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${local.name_prefix}-private-${count.index + 1}"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-igw"
  }
}

# Elastic IP for NAT Gateway
resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "${local.name_prefix}-nat-eip"
  }
}

# NAT Gateway in the first public subnet
resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "${local.name_prefix}-nat"
  }
}

# Public route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${local.name_prefix}-public-rt"
  }
}

# Private route table with NAT gateway default route
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "${local.name_prefix}-private-rt"
  }
}

# Route table associations for public subnets
resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Route table associations for private subnets
resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# Security group: allow-ssh
resource "aws_security_group" "allow_ssh" {
  name        = "allow-ssh"
  description = "Allows inbound SSH and outbound traffic within VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from within VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    description = "Outbound traffic within VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "allow-ssh"
  }
}

# --------------------------------------------------------------------
# Variables
# --------------------------------------------------------------------

variable "repository_name" {
  description = "Name of the ECR repository"
  type        = string
}

variable "encryption_type" {
  description = "Encryption type for the repository: AES256 (default) or KMS"
  type        = string
  default     = "AES256"

  validation {
    condition     = contains(["AES256", "KMS"], var.encryption_type)
    error_message = "Encryption type must be \"AES256\" or \"KMS\"."
  }
}

variable "kms_key_id" {
  description = "ARN of a customer-managed KMS symmetric key. Only used when encryption_type is KMS."
  type        = string
  default     = null
}

variable "repository_policy" {
  description = "Optional JSON string defining a repository access policy (e.g. restricting pull access to specific AWS principals)."
  type        = string
  default     = null
}

variable "lifecycle_policy" {
  description = "Optional JSON string defining a lifecycle policy for automatic image cleanup."
  type        = string
  default     = null
}

# --------------------------------------------------------------------
# Local computed values
# --------------------------------------------------------------------

locals {
  # Determine the effective KMS key ARN only when KMS encryption is selected.
  kms_key_arn = var.encryption_type == "KMS" ? (
    var.kms_key_id != null ? var.kms_key_id : aws_kms_key.this[0].arn
  ) : null
}

# --------------------------------------------------------------------
# KMS key – created only when KMS encryption is requested without a key ID
# --------------------------------------------------------------------

resource "aws_kms_key" "this" {
  count       = var.encryption_type == "KMS" && var.kms_key_id == null ? 1 : 0
  description = "Symmetric KMS key for ECR repository ${var.repository_name}"
}

# --------------------------------------------------------------------
# ECR Repository
# --------------------------------------------------------------------

resource "aws_ecr_repository" "this" {
  name = var.repository_name

  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  encryption_configuration {
    encryption_type = var.encryption_type
    kms_key         = local.kms_key_arn
  }
}

# --------------------------------------------------------------------
# Repository access policy (optional)
# --------------------------------------------------------------------

resource "aws_ecr_repository_policy" "this" {
  count      = var.repository_policy != null ? 1 : 0
  repository = aws_ecr_repository.this.name
  policy     = var.repository_policy
}

# --------------------------------------------------------------------
# Lifecycle policy (optional)
# --------------------------------------------------------------------

resource "aws_ecr_lifecycle_policy" "this" {
  count      = var.lifecycle_policy != null ? 1 : 0
  repository = aws_ecr_repository.this.name
  policy     = var.lifecycle_policy
}

variable "queue_name" {
  description = "Name of the SQS queue"
  type        = string
  default     = "my-application-queue"
}

variable "is_fifo_queue" {
  description = "Whether to create a FIFO queue"
  type        = bool
  default     = false
}

variable "fifo_queue_content_based_deduplication" {
  description = "Enable content-based deduplication for FIFO queues"
  type        = bool
  default     = false
}

variable "enable_access_policy" {
  description = "Whether to attach an access policy granting send-message permissions"
  type        = bool
  default     = false
}

variable "allowed_principal_arn" {
  description = "ARN of the AWS principal allowed to send messages (IAM role/user ARN). Required when enable_access_policy is true."
  type        = string
  default     = ""
}

variable "tags" {
  description = "A map of tags to apply to all resources"
  type        = map(string)
  default = {
    Terraform   = "true"
    Environment = "production"
    ManagedBy   = "iacgod"
  }
}

locals {
  # FIFO queue names must end with .fifo
  queue_name = var.is_fifo_queue ? "${var.queue_name}.fifo" : var.queue_name

  # Standardised tags that can be referenced elsewhere
  tags = merge(var.tags, {
    Name = local.queue_name
  })
}

resource "aws_sqs_queue" "this" {
  name                               = local.queue_name
  fifo_queue                         = var.is_fifo_queue
  content_based_deduplication        = var.is_fifo_queue ? var.fifo_queue_content_based_deduplication : null
  sqs_managed_sse_enabled            = true
  visibility_timeout_seconds         = 30
  message_retention_seconds          = 345600
  max_message_size                   = 262144
  delay_seconds                      = 0
  receive_wait_time_seconds          = 0
  deduplication_scope                = var.is_fifo_queue ? "queue" : null
  fifo_throughput_limit              = var.is_fifo_queue ? "perQueue" : null
  redrive_policy                     = null
  redrive_allow_policy               = null

  tags = local.tags
}

resource "aws_sqs_queue_policy" "this" {
  count     = var.enable_access_policy ? 1 : 0
  queue_url = aws_sqs_queue.this.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowSendMessage"
        Effect = "Allow"
        Principal = {
          AWS = var.allowed_principal_arn
        }
        Action   = "sqs:SendMessage"
        Resource = aws_sqs_queue.this.arn
      }
    ]
  })
}

terraform {
  required_version = ">= 1.1"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    null = {
      source  = "hashicorp/null"
      version = ">= 3.0"
    }
  }
}

variable "name_prefix" {
  type        = string
  default     = "aurora-dsql"
  description = "Prefix used for resource naming and tagging."
}

variable "create_cluster" {
  type        = bool
  default     = true
  description = "Whether to create the Aurora DSQL cluster itself."
}

variable "delete_protection_enabled" {
  type        = bool
  default     = true
  description = "Whether deletion protection is enabled on the Aurora DSQL cluster."
}

variable "kms_key_id" {
  type        = string
  default     = ""
  description = "ARN of an existing KMS key to encrypt the cluster. Leave empty to use the default AWS-managed key (aws/dsql)."
}

variable "create_kms_key" {
  type        = bool
  default     = false
  description = "Whether to create a dedicated customer-managed KMS key for the cluster."
}

variable "kms_key_deletion_window_in_days" {
  type        = number
  default     = 30
  description = "Deletion window (days) for the customer-managed KMS key when it is created."
}

variable "kms_key_enable_rotation" {
  type        = bool
  default     = true
  description = "Whether automatic key rotation is enabled for the customer-managed KMS key."
}

variable "force_destroy" {
  type        = bool
  default     = false
  description = "Whether to force the cluster's deletion even when deletion protection is enabled."
}

variable "enable_multi_region" {
  type        = bool
  default     = false
  description = "Whether to enable multi-region support by configuring a witness region on the cluster."
}

variable "multi_region_witness_region" {
  type        = string
  default     = "us-east-2"
  description = "Witness region used for the cluster's multi-region configuration."
}

variable "linked_cluster_arns" {
  type        = list(string)
  default     = []
  description = "ARNs of additional linked clusters (in other AWS Regions) to attach to the multi-region configuration."
}

variable "enable_peering" {
  type        = bool
  default     = false
  description = "Whether to provision a DSQL cluster peering relationship to other clusters. Requires peer_cluster_identifiers to be non-empty."
}

variable "peer_cluster_identifiers" {
  type        = list(string)
  default     = []
  description = "List of DSQL cluster identifiers to peer this cluster with (only used when enable_peering is true)."
}

variable "peering_witness_region" {
  type        = string
  default     = ""
  description = "Optional witness region for the cluster peering relationship. Defaults to the current Region when left empty."
}

variable "peering_create_timeout" {
  type        = string
  default     = "10m"
  description = "Configurable timeout for the cluster peering create operation (e.g. '5m', '10m')."
}

variable "tags" {
  type        = map(string)
  default     = {}
  description = "Additional tags to apply to created resources."
}

data "aws_region" "current" {}

locals {
  tags = merge(
    { Name = var.name_prefix },
    var.tags,
  )

  kms_key_id = var.create_kms_key ? (
    var.kms_key_id != "" ? var.kms_key_id : aws_kms_key.this[0].arn
    ) : (
    var.kms_key_id != "" ? var.kms_key_id : null
  )
}

# ---------------------------------------------------------------------------
# Optional customer-managed KMS key used to encrypt the DSQL cluster
# ---------------------------------------------------------------------------
resource "aws_kms_key" "this" {
  count                   = var.create_kms_key && var.create_cluster ? 1 : 0
  description             = "Customer-managed KMS key for Aurora DSQL cluster ${var.name_prefix}"
  deletion_window_in_days = var.kms_key_deletion_window_in_days
  enable_key_rotation     = var.kms_key_enable_rotation
  tags                    = local.tags
}

resource "aws_kms_alias" "this" {
  count         = var.create_kms_key && var.create_cluster ? 1 : 0
  name          = "alias/${var.name_prefix}-dsql"
  target_key_id = aws_kms_key.this[0].key_id
}

# ---------------------------------------------------------------------------
# Aurora DSQL cluster
# ---------------------------------------------------------------------------
resource "aws_dsql_cluster" "this" {
  count                       = var.create_cluster ? 1 : 0
  deletion_protection_enabled = var.delete_protection_enabled
  kms_encryption_key          = local.kms_key_id
  tags                        = local.tags

  dynamic "multi_region_properties" {
    for_each = var.enable_multi_region ? [1] : []
    content {
      witness_region = var.multi_region_witness_region != "" ? var.multi_region_witness_region : data.aws_region.current.region
      clusters       = var.linked_cluster_arns
    }
  }
}

# ---------------------------------------------------------------------------
# Cluster peering relationship (optional)
# ---------------------------------------------------------------------------
resource "aws_dsql_cluster_peering" "this" {
  count = var.create_cluster && var.enable_peering && length(var.peer_cluster_identifiers) > 0 ? 1 : 0

  identifier     = aws_dsql_cluster.this[0].identifier
  clusters       = var.peer_cluster_identifiers
  witness_region = var.peering_witness_region != "" ? var.peering_witness_region : data.aws_region.current.region

  timeouts {
    create = var.peering_create_timeout
  }
}

# ---------------------------------------------------------------------------
# Force-destroy: disable deletion protection immediately before destroying the
# cluster so it can be removed even when protection is enabled.
# ---------------------------------------------------------------------------
resource "null_resource" "force_destroy" {
  count = var.create_cluster && var.force_destroy ? 1 : 0

  triggers = {
    cluster_id = aws_dsql_cluster.this[0].identifier
    region     = data.aws_region.current.region
  }

  provisioner "local-exec" {
    when    = destroy
    command = "aws dsql update-cluster --identifier ${self.triggers.cluster_id} --no-deletion-protection-enabled --region ${self.triggers.region} 2>/dev/null || true"
  }
}

output "cluster_id" {
  description = "Identifier of the created Aurora DSQL cluster."
  value       = try(aws_dsql_cluster.this[0].identifier, null)
}

output "cluster_arn" {
  description = "ARN of the created Aurora DSQL cluster."
  value       = try(aws_dsql_cluster.this[0].arn, null)
}

output "cluster_vpc_endpoint_service_name" {
  description = "VPC endpoint service name of the created Aurora DSQL cluster."
  value       = try(aws_dsql_cluster.this[0].vpc_endpoint_service_name, null)
}

output "kms_key_arn" {
  description = "ARN of the customer-managed KMS key, if created."
  value       = try(aws_kms_key.this[0].arn, null)
}

terraform {
  required_providers {
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "bucket_name" {
  description = "Name of the S3 bucket. If null, a unique name is generated."
  type        = string
  default     = null
}

resource "random_id" "bucket_suffix" {
  byte_length = 4
}

locals {
  bucket_name = var.bucket_name != null ? var.bucket_name : "tf-s3-bucket-${random_id.bucket_suffix.hex}"
  has_policies = length(var.bucket_policies) > 0
}

variable "object_lock_enabled" {
  description = "Enable S3 Object Lock on the bucket"
  type        = bool
  default     = false
}

variable "tags" {
  description = "Tags to apply to the bucket and associated resources"
  type        = map(string)
  default     = {}
}

variable "force_destroy" {
  description = "Force destroy the bucket even if it contains objects"
  type        = bool
  default     = false
}

variable "bucket_policies" {
  description = "Map of custom bucket policy configurations"
  type = map(object({
    policy_id = optional(string)
    version   = optional(string, "2012-10-17")
    statements = list(object({
      sid         = optional(string)
      actions     = list(string)
      effect      = optional(string, "Allow")
      resources   = list(string)
      principals = optional(map(list(string)))
    }))
  }))
  default = {}
  validation {
    condition = alltrue([
      for pk, p in var.bucket_policies : alltrue([
        for s in p.statements : contains(["Allow", "Deny"], s.effect)
      ])
    ])
    error_message = "Policy statement effect must be either 'Allow' or 'Deny'."
  }
}

data "aws_partition" "current" {}
data "aws_region" "current" {}
data "aws_caller_identity" "current" {}

resource "aws_kms_key" "this" {
  description             = "Customer-managed KMS key for S3 bucket ${local.bucket_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowS3ServiceAccess"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey",
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:ViaService" = "s3.${data.aws_region.current.region}.amazonaws.com"
          }
        }
      },
    ]
  })

  tags = var.tags
}

resource "aws_kms_alias" "this" {
  name          = "alias/${local.bucket_name}-s3-key"
  target_key_id = aws_kms_key.this.key_id
}

resource "aws_s3_bucket" "this" {
  bucket              = local.bucket_name
  force_destroy       = var.force_destroy
  object_lock_enabled = var.object_lock_enabled
  tags                = var.tags
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.this.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = var.object_lock_enabled ? 1 : 0

  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode = "GOVERNANCE"
      days = 30
    }
  }
}

data "aws_iam_policy_document" "combined" {
  count = local.has_policies ? 1 : 0

  dynamic "statement" {
    for_each = {
      for idx, stmt in flatten([
        for pk, p in var.bucket_policies : [
          for s in p.statements : s
        ]
      ]) : idx => stmt
    }

    content {
      sid       = statement.value.sid
      effect    = statement.value.effect
      actions   = statement.value.actions
      resources = statement.value.resources

      dynamic "principals" {
        for_each = statement.value.principals != null ? statement.value.principals : {}
        content {
          type        = principals.key
          identifiers = principals.value
        }
      }
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  count  = local.has_policies ? 1 : 0
  bucket = aws_s3_bucket.this.id
  policy = data.aws_iam_policy_document.combined[0].json
}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  # Determine if we should use name vs name_prefix
  use_name_prefix = var.create && var.name == null && var.name_prefix != null
  use_name        = var.create && var.name != null

  # Default owner-access policy statement
  owner_statement = {
    Sid    = "TopicOwnerAccess"
    Effect = "Allow"
    Principal = {
      AWS = "arn:${local.partition}:iam::${local.account_id}:root"
    }
    Action = [
      "SNS:GetTopicAttributes",
      "SNS:SetTopicAttributes",
      "SNS:AddPermission",
      "SNS:RemovePermission",
      "SNS:DeleteTopic",
      "SNS:Subscribe",
      "SNS:ListSubscriptionsByTopic",
      "SNS:Publish",
      "SNS:Receive",
    ]
    Resource = try(aws_sns_topic.this[0].arn, "")
  }

  # Combine all policy statements
  topic_policy_statements = concat(
    var.create_topic_policy ? [local.owner_statement] : [],
    var.policy_source_statements,
    var.policy_override_statements,
    var.policy_user_statements,
  )

  # Build the topic policy document
  topic_policy_json = length(local.topic_policy_statements) > 0 ? jsonencode({
    Version   = "2012-10-17"
    Statement = local.topic_policy_statements
  }) : null
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

# SNS Topic — conditionally created with all feedback and delivery settings inline
resource "aws_sns_topic" "this" {
  count = var.create ? 1 : 0

  name        = local.use_name ? var.name : null
  name_prefix = local.use_name_prefix ? var.name_prefix : null
  display_name = var.display_name

  fifo_topic                 = var.fifo_topic
  content_based_deduplication = var.fifo_topic ? var.content_based_deduplication : null
  kms_master_key_id          = var.kms_master_key_id

  # Delivery policy
  delivery_policy = var.fifo_topic ? null : jsonencode({
    http = {
      defaultHealthyRetryPolicy = {
        minDelayTarget    = try(var.delivery_policy.http.defaultHealthyRetryPolicy.minDelayTarget, 20)
        maxDelayTarget    = try(var.delivery_policy.http.defaultHealthyRetryPolicy.maxDelayTarget, 20)
        numRetries        = try(var.delivery_policy.http.defaultHealthyRetryPolicy.numRetries, 3)
        numMaxDelayRetries = try(var.delivery_policy.http.defaultHealthyRetryPolicy.numMaxDelayRetries, 0)
        numNoDelayRetries  = try(var.delivery_policy.http.defaultHealthyRetryPolicy.numNoDelayRetries, 0)
        numMinDelayRetries = try(var.delivery_policy.http.defaultHealthyRetryPolicy.numMinDelayRetries, 0)
        backoffFunction   = try(var.delivery_policy.http.defaultHealthyRetryPolicy.backoffFunction, "linear")
      }
      disableSubscriptionOverrides = try(var.delivery_policy.http.disableSubscriptionOverrides, false)
      defaultThrottlePolicy = {
        maxReceivesPerSecond = try(var.delivery_policy.http.defaultThrottlePolicy.maxReceivesPerSecond, 10)
      }
    }
  })

  # SQS feedback
  sqs_success_feedback_role_arn    = var.feedback_sqs != null ? try(var.feedback_sqs.success_feedback_role_arn, null) : null
  sqs_success_feedback_sample_rate = var.feedback_sqs != null ? try(var.feedback_sqs.success_feedback_sample_rate, null) : null
  sqs_failure_feedback_role_arn    = var.feedback_sqs != null ? try(var.feedback_sqs.failure_feedback_role_arn, null) : null

  # Lambda feedback
  lambda_success_feedback_role_arn    = var.feedback_lambda != null ? try(var.feedback_lambda.success_feedback_role_arn, null) : null
  lambda_success_feedback_sample_rate = var.feedback_lambda != null ? try(var.feedback_lambda.success_feedback_sample_rate, null) : null
  lambda_failure_feedback_role_arn    = var.feedback_lambda != null ? try(var.feedback_lambda.failure_feedback_role_arn, null) : null

  # HTTP/HTTPS feedback
  http_success_feedback_role_arn    = var.feedback_http != null ? try(var.feedback_http.success_feedback_role_arn, null) : null
  http_success_feedback_sample_rate = var.feedback_http != null ? try(var.feedback_http.success_feedback_sample_rate, null) : null
  http_failure_feedback_role_arn    = var.feedback_http != null ? try(var.feedback_http.failure_feedback_role_arn, null) : null

  # Firehose feedback
  firehose_success_feedback_role_arn    = var.feedback_firehose != null ? try(var.feedback_firehose.success_feedback_role_arn, null) : null
  firehose_success_feedback_sample_rate = var.feedback_firehose != null ? try(var.feedback_firehose.success_feedback_sample_rate, null) : null
  firehose_failure_feedback_role_arn    = var.feedback_firehose != null ? try(var.feedback_firehose.failure_feedback_role_arn, null) : null

  # Application feedback
  application_success_feedback_role_arn    = var.feedback_application != null ? try(var.feedback_application.success_feedback_role_arn, null) : null
  application_success_feedback_sample_rate = var.feedback_application != null ? try(var.feedback_application.success_feedback_sample_rate, null) : null
  application_failure_feedback_role_arn    = var.feedback_application != null ? try(var.feedback_application.failure_feedback_role_arn, null) : null

  tags = var.tags
}

# SNS Topic Policy — conditionally created if statements exist
resource "aws_sns_topic_policy" "this" {
  count = var.create && local.topic_policy_json != null ? 1 : 0

  arn    = aws_sns_topic.this[0].arn
  policy = local.topic_policy_json
}

# Delivery feedback IAM role — conditionally created
resource "aws_iam_role" "delivery_feedback" {
  count = var.create && var.create_delivery_feedback_role ? 1 : 0

  name = var.delivery_feedback_role_name != null ? var.delivery_feedback_role_name : (
    "sns-delivery-feedback-${aws_sns_topic.this[0].name}"
  )

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SNSTopicDeliveryFeedback"
        Effect = "Allow"
        Principal = {
          Service = "sns.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

# Attach the AWS managed SNS success feedback policy to the role
resource "aws_iam_role_policy_attachment" "delivery_feedback_sns" {
  count = var.create && var.create_delivery_feedback_role ? 1 : 0

  role       = aws_iam_role.delivery_feedback[0].name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/SNSSuccessFeedbackRolePolicy"
}

# SNS Topic Subscriptions — conditionally created for each entry in the map
resource "aws_sns_topic_subscription" "this" {
  for_each = var.create ? var.subscriptions : {}

  topic_arn            = aws_sns_topic.this[0].arn
  protocol             = each.value.protocol
  endpoint             = each.value.endpoint
  endpoint_auto_confirms = try(each.value.endpoint_auto_confirms, false)
  confirmation_timeout_in_minutes = try(each.value.confirmation_timeout_in_minutes, null)
  raw_message_delivery = try(each.value.raw_message_delivery, false)
  filter_policy        = try(each.value.filter_policy, null)
  filter_policy_scope  = try(each.value.filter_policy_scope, null)
  subscription_role_arn = try(each.value.subscription_role_arn, null)
  delivery_policy      = try(each.value.delivery_policy, null)
  redrive_policy       = try(each.value.redrive_policy, null)
}

################################################################################
# Variables
################################################################################

variable "create" {
  description = "Whether to create all SNS topic resources"
  type        = bool
  default     = true
}

variable "name" {
  description = "The name of the SNS topic. For FIFO topics, the name must end with .fifo."
  type        = string
  default     = null
}

variable "name_prefix" {
  description = "The prefix for the SNS topic name. Ignored if name is specified."
  type        = string
  default     = "sns-topic"
}

variable "display_name" {
  description = "The display name for the SNS topic"
  type        = string
  default     = null
}

variable "fifo_topic" {
  description = "Whether to create a FIFO SNS topic"
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Whether to enable content-based deduplication for FIFO topics"
  type        = bool
  default     = false
}

variable "kms_master_key_id" {
  description = "The ID of an AWS-managed customer master key (CMK) for SNS topic encryption"
  type        = string
  default     = null
}

variable "delivery_policy" {
  description = "Delivery policy configuration for HTTP/S endpoints (retry and throttle settings)"
  type = object({
    http = optional(object({
      defaultHealthyRetryPolicy = optional(object({
        minDelayTarget     = optional(number, 20)
        maxDelayTarget     = optional(number, 20)
        numRetries         = optional(number, 3)
        numMaxDelayRetries = optional(number, 0)
        numNoDelayRetries  = optional(number, 0)
        numMinDelayRetries = optional(number, 0)
        backoffFunction    = optional(string, "linear")
      }), {})
      disableSubscriptionOverrides = optional(bool, false)
      defaultThrottlePolicy = optional(object({
        maxReceivesPerSecond = optional(number, 10)
      }), {})
    }), {})
  })
  default = {
    http = {
      defaultHealthyRetryPolicy = {
        minDelayTarget     = 20
        maxDelayTarget     = 20
        numRetries         = 3
        numMaxDelayRetries = 0
        numNoDelayRetries  = 0
        numMinDelayRetries = 0
        backoffFunction    = "linear"
      }
      disableSubscriptionOverrides = false
      defaultThrottlePolicy = {
        maxReceivesPerSecond = 10
      }
    }
  }
}

variable "subscriptions" {
  description = "A map of subscriptions to create for the SNS topic"
  type = map(object({
    protocol                       = string
    endpoint                       = string
    endpoint_auto_confirms         = optional(bool, false)
    confirmation_timeout_in_minutes = optional(number)
    raw_message_delivery           = optional(bool, false)
    filter_policy                  = optional(string)
    filter_policy_scope            = optional(string)
    subscription_role_arn          = optional(string)
    delivery_policy                = optional(string)
    redrive_policy                 = optional(string)
  }))
  default = {}
}

variable "feedback_sqs" {
  description = "Feedback configuration for SQS deliveries (success/failure role ARNs and sample rate)"
  type = object({
    success_feedback_role_arn    = optional(string)
    success_feedback_sample_rate = optional(number)
    failure_feedback_role_arn    = optional(string)
  })
  default = null
}

variable "feedback_lambda" {
  description = "Feedback configuration for Lambda deliveries"
  type = object({
    success_feedback_role_arn    = optional(string)
    success_feedback_sample_rate = optional(number)
    failure_feedback_role_arn    = optional(string)
  })
  default = null
}

variable "feedback_http" {
  description = "Feedback configuration for HTTP/HTTPS deliveries"
  type = object({
    success_feedback_role_arn    = optional(string)
    success_feedback_sample_rate = optional(number)
    failure_feedback_role_arn    = optional(string)
  })
  default = null
}

variable "feedback_firehose" {
  description = "Feedback configuration for Firehose deliveries"
  type = object({
    success_feedback_role_arn    = optional(string)
    success_feedback_sample_rate = optional(number)
    failure_feedback_role_arn    = optional(string)
  })
  default = null
}

variable "feedback_application" {
  description = "Feedback configuration for Application (mobile push) deliveries"
  type = object({
    success_feedback_role_arn    = optional(string)
    success_feedback_sample_rate = optional(number)
    failure_feedback_role_arn    = optional(string)
  })
  default = null
}

variable "create_topic_policy" {
  description = "Whether to include the default owner-access statement in the topic policy"
  type        = bool
  default     = true
}

variable "policy_source_statements" {
  description = "Additional IAM policy statements to include (e.g., for cross-account publish access)"
  type = list(object({
    Sid       = optional(string)
    Effect    = string
    Principal = any
    Action    = any
    Resource  = optional(any)
    Condition = optional(any)
  }))
  default = []
}

variable "policy_override_statements" {
  description = "IAM policy statements that replace the default owner-access statement"
  type = list(object({
    Sid       = optional(string)
    Effect    = string
    Principal = any
    Action    = any
    Resource  = optional(any)
    Condition = optional(any)
  }))
  default = []
}

variable "policy_user_statements" {
  description = "User-defined IAM policy statements appended after all other statements"
  type = list(object({
    Sid       = optional(string)
    Effect    = string
    Principal = any
    Action    = any
    Resource  = optional(any)
    Condition = optional(any)
  }))
  default = []
}

variable "create_delivery_feedback_role" {
  description = "Whether to create an IAM role for SNS delivery status feedback"
  type        = bool
  default     = false
}

variable "delivery_feedback_role_name" {
  description = "Name for the delivery feedback IAM role"
  type        = string
  default     = null
}

variable "tags" {
  description = "Tags to apply to all resources"
  type        = map(string)
  default     = {}
}

################################################################################
# Outputs
################################################################################

output "topic_arn" {
  description = "The ARN of the SNS topic"
  value       = try(aws_sns_topic.this[0].arn, null)
}

output "topic_id" {
  description = "The ID of the SNS topic"
  value       = try(aws_sns_topic.this[0].id, null)
}

output "topic_name" {
  description = "The name of the SNS topic"
  value       = try(aws_sns_topic.this[0].name, null)
}

output "topic_owner" {
  description = "The AWS account ID of the SNS topic owner"
  value       = try(aws_sns_topic.this[0].owner, null)
}

output "subscription_arns" {
  description = "Map of subscription ARNs keyed by subscription key"
  value = {
    for k, s in aws_sns_topic_subscription.this : k => s.arn
  }
}

output "subscription_ids" {
  description = "Map of subscription IDs keyed by subscription key"
  value = {
    for k, s in aws_sns_topic_subscription.this : k => s.id
  }
}

output "delivery_feedback_role_arn" {
  description = "The ARN of the delivery feedback IAM role"
  value       = try(aws_iam_role.delivery_feedback[0].arn, null)
}

output "delivery_feedback_role_name" {
  description = "The name of the delivery feedback IAM role"
  value       = try(aws_iam_role.delivery_feedback[0].name, null)
}

output "topic_policy_arn" {
  description = "The ARN of the topic policy (if created)"
  value       = try(aws_sns_topic_policy.this[0].arn, null)
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "ansible_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "ansible-vpc"
  }
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.ansible_vpc.id
  cidr_block        = "10.0.0.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "ansible-vpc-private-subnet-1"
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.ansible_vpc.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "ansible-vpc-public-subnet-1"
  }
}

resource "aws_internet_gateway" "ansible_vpc_igw" {
  vpc_id = aws_vpc.ansible_vpc.id

  tags = {
    Name = "ansible-vpc-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.ansible_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.ansible_vpc_igw.id
  }

  tags = {
    Name = "ansible-vpc-public-rt"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.ansible_vpc.id

  tags = {
    Name = "ansible-vpc-private-rt"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

# ------------------------------------------------------------------------------
# AWS Transit Gateway - centralized inter-VPC network routing
#
# This configuration either creates a new Transit Gateway or attaches VPCs to
# an existing one, and centrally connects one or more VPCs to it using a map of
# subnet IDs. A single Transit Gateway route table is used (default route table
# association and propagation) so that every attached VPC exchanges routes with
# every other attached VPC through one central hub.
# ------------------------------------------------------------------------------

variable "create_transit_gateway" {
  description = "Whether to create a new Transit Gateway. Set to false and provide existing_transit_gateway_id to attach to an existing gateway instead."
  type        = bool
  default     = true
}

variable "existing_transit_gateway_id" {
  description = "ID of an already existing Transit Gateway to attach VPCs to when create_transit_gateway is false."
  type        = string
  default     = null

  validation {
    condition     = var.create_transit_gateway || (var.existing_transit_gateway_id != null && length(var.existing_transit_gateway_id) > 0)
    error_message = "When create_transit_gateway is false, existing_transit_gateway_id must be set to a valid Transit Gateway ID."
  }
}

variable "transit_gateway_config" {
  description = "Configuration options for the Transit Gateway."
  type = object({
    name                            = string
    description                     = string
    amazon_side_asn                 = number
    auto_accept_shared_attachments  = string
    dns_support                     = string
    vpn_ecmp_support                = string
    default_route_table_association = string
    default_route_table_propagation = string
  })
  default = {
    name                            = "central-transit-gateway"
    description                     = "Central Transit Gateway for inter-VPC network routing"
    amazon_side_asn                 = 64512
    auto_accept_shared_attachments  = "disable"
    dns_support                     = "enable"
    vpn_ecmp_support                = "enable"
    default_route_table_association = "enable"
    default_route_table_propagation = "enable"
  }

  validation {
    condition     = contains(["enable", "disable"], var.transit_gateway_config.default_route_table_association)
    error_message = "transit_gateway_config.default_route_table_association must be either 'enable' or 'disable'."
  }

  validation {
    condition     = contains(["enable", "disable"], var.transit_gateway_config.default_route_table_propagation)
    error_message = "transit_gateway_config.default_route_table_propagation must be either 'enable' or 'disable'."
  }

  validation {
    condition     = contains(["enable", "disable"], var.transit_gateway_config.dns_support)
    error_message = "transit_gateway_config.dns_support must be either 'enable' or 'disable'."
  }

  validation {
    condition     = contains(["enable", "disable"], var.transit_gateway_config.vpn_ecmp_support)
    error_message = "transit_gateway_config.vpn_ecmp_support must be either 'enable' or 'disable'."
  }

  validation {
    condition     = contains(["enable", "disable"], var.transit_gateway_config.auto_accept_shared_attachments)
    error_message = "transit_gateway_config.auto_accept_shared_attachments must be either 'enable' or 'disable'."
  }
}

variable "transit_gateway_tags" {
  description = "Additional tags applied to the Transit Gateway and all related resources."
  type        = map(string)
  default     = {}
}

variable "vpcs" {
  description = <<-EOT
    Map of VPCs to create and attach to the Transit Gateway. Each map key is used
    as both the VPC name and the Transit Gateway attachment name. subnet_cidrs is
    the ordered list of subnet CIDR blocks created in the VPC and used for the
    attachment. Subnets are spread across availability zones in order, wrapping
    around if more subnets than zones are listed.
  EOT
  type = map(object({
    cidr_block   = string
    subnet_cidrs = list(string)
  }))
  default = {
    "vpc-alpha" = {
      cidr_block   = "10.0.0.0/16"
      subnet_cidrs = ["10.0.1.0/24", "10.0.2.0/24"]
    }
    "vpc-beta" = {
      cidr_block   = "10.1.0.0/16"
      subnet_cidrs = ["10.1.1.0/24", "10.1.2.0/24"]
    }
  }
}

variable "existing_vpc_attachments" {
  description = <<-EOT
    Optional map of extra Transit Gateway attachments for VPCs that are not
    created by this configuration (for example pre-existing VPCs). Each key is
    the attachment name and each value holds the VPC ID plus the map of subnet
    IDs to attach. Defaults to an empty map so no external infrastructure is
    required to deploy.
  EOT
  type = map(object({
    vpc_id     = string
    subnet_ids = list(string)
  }))
  default = {}
}

# Static provider metadata used to spread created subnets across availability
# zones without hardcoding zone names.
data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  # ID of the Transit Gateway used by every attachment and route below. When a
  # new gateway is created the resource attribute is used; otherwise the
  # supplied existing gateway ID is used unchanged.
  transit_gateway_id = var.create_transit_gateway ? aws_ec2_transit_gateway.this[0].id : var.existing_transit_gateway_id

  # Flatten every VPC/subnet pair into one addressable map keyed by
  # "<vpc_key>:<subnet_index>" so a single aws_subnet resource creates them all.
  subnet_flat_map = {
    for pair in flatten([
      for vpc_key, vpc_config in var.vpcs : [
        for index, cidr_block in vpc_config.subnet_cidrs : {
          vpc_key    = vpc_key
          index      = index
          cidr_block = cidr_block
        }
      ]
    ]) : "${pair.vpc_key}:${pair.index}" => {
      vpc_key     = pair.vpc_key
      cidr_block  = pair.cidr_block
      subnet_name = "${pair.vpc_key}-subnet-${pair.index + 1}"
      az_index    = pair.index % length(data.aws_availability_zones.available.names)
    }
  }

  # Map of subnet IDs (per VPC) used to attach the created VPCs to the Transit
  # Gateway. This is later merged with any externally supplied attachments.
  vpc_attachments = {
    for vpc_key, vpc_config in var.vpcs : vpc_key => {
      vpc_id = aws_vpc.this[vpc_key].id
      subnet_ids = [
        for index, _cidr_block in vpc_config.subnet_cidrs :
        aws_subnet.this["${vpc_key}:${index}"].id
      ]
    }
  }

  # Union of attachments created from the VPC map above and any attachments
  # supplied directly for pre-existing VPCs.
  all_attachments = merge(
    local.vpc_attachments,
    {
      for name, config in var.existing_vpc_attachments :
      name => {
        vpc_id     = config.vpc_id
        subnet_ids = config.subnet_ids
      }
    }
  )

  # Routes from every created VPC towards every other created VPC through the
  # Transit Gateway, centralizing inter-VPC routing.
  inter_vpc_routes = {
    for route in flatten([
      for src_key, _src_config in var.vpcs : [
        for dst_key, dst_config in var.vpcs :
        {
          route_key        = "${src_key}-to-${dst_key}"
          route_table_id   = aws_vpc.this[src_key].default_route_table_id
          destination_cidr = dst_config.cidr_block
        } if src_key != dst_key
      ]
    ]) : route.route_key => route
  }
}

resource "aws_ec2_transit_gateway" "this" {
  count = var.create_transit_gateway ? 1 : 0

  description                     = var.transit_gateway_config.description
  amazon_side_asn                 = var.transit_gateway_config.amazon_side_asn
  auto_accept_shared_attachments  = var.transit_gateway_config.auto_accept_shared_attachments
  dns_support                     = var.transit_gateway_config.dns_support
  vpn_ecmp_support                = var.transit_gateway_config.vpn_ecmp_support
  default_route_table_association = var.transit_gateway_config.default_route_table_association
  default_route_table_propagation = var.transit_gateway_config.default_route_table_propagation

  tags = merge(
    { Name = var.transit_gateway_config.name },
    var.transit_gateway_tags,
  )
}

resource "aws_vpc" "this" {
  for_each = var.vpcs

  cidr_block           = each.value.cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    { Name = each.key },
    var.transit_gateway_tags,
  )
}

resource "aws_subnet" "this" {
  for_each = local.subnet_flat_map

  vpc_id            = aws_vpc.this[each.value.vpc_key].id
  cidr_block        = each.value.cidr_block
  availability_zone = data.aws_availability_zones.available.names[each.value.az_index]

  tags = merge(
    { Name = each.value.subnet_name },
    var.transit_gateway_tags,
  )
}

resource "aws_ec2_transit_gateway_vpc_attachment" "this" {
  for_each = local.all_attachments

  transit_gateway_id = local.transit_gateway_id
  vpc_id             = each.value.vpc_id
  subnet_ids         = each.value.subnet_ids

  transit_gateway_default_route_table_association = true
  transit_gateway_default_route_table_propagation = true

  tags = merge(
    { Name = each.key },
    var.transit_gateway_tags,
  )
}

resource "aws_route" "inter_vpc" {
  for_each = local.inter_vpc_routes

  route_table_id         = each.value.route_table_id
  destination_cidr_block = each.value.destination_cidr
  transit_gateway_id     = local.transit_gateway_id
}

data "aws_availability_zones" "available" {}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "dragondrop-vpc"
  }
}

resource "aws_subnet" "main" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.0.0/24"
  map_public_ip_on_launch = false
  availability_zone       = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "dragondrop-subnet"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "dragondrop-igw"
  }
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "dragondrop-route-table"
  }
}

resource "aws_route_table_association" "main" {
  subnet_id      = aws_subnet.main.id
  route_table_id = aws_route_table.main.id
}

resource "aws_security_group" "ecs_fargate" {
  name        = "dragondrop-compute-ecs-fargate-sg"
  description = "Security group for ECS Fargate tasks allowing outbound traffic within VPC CIDR"
  vpc_id      = aws_vpc.main.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "dragondrop-compute-ecs-fargate-sg"
  }
}

locals {
  table_prefix = ""
}

resource "aws_dynamodb_table" "raw_metrics" {
  name             = "${local.table_prefix}raw_metrics"
  billing_mode     = "PAY_PER_REQUEST"
  hash_key         = "uuid"
  stream_enabled   = true
  stream_view_type = "NEW_IMAGE"

  attribute {
    name = "uuid"
    type = "S"
  }

  ttl {
    enabled        = true
    attribute_name = "expdate"
  }

  server_side_encryption {
    enabled = true
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dynamodb_table" "aggregate_metrics" {
  name                        = "${local.table_prefix}aggregate_metrics"
  billing_mode                = "PAY_PER_REQUEST"
  hash_key                    = "pk"
  range_key                   = "sk"
  point_in_time_recovery {
    enabled = true
  }

  attribute {
    name = "pk"
    type = "S"
  }

  attribute {
    name = "sk"
    type = "S"
  }

  attribute {
    name = "identifier"
    type = "S"
  }

  global_secondary_index {
    name            = "IdentifierIndex"
    hash_key        = "identifier"
    projection_type = "ALL"
  }

  server_side_encryption {
    enabled = true
  }

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

variable "instance_type" {
  description = "EC2 instance type for the Apache test server"
  type        = string
  default     = "t3.micro"
}

variable "server_name" {
  description = "Name tag for the Apache test server"
  type        = string
  default     = "demo"
}

variable "ami_owners" {
  description = "Owner of the Amazon Linux 2 AMI"
  type        = list(string)
  default     = ["amazon"]
}

# VPC with CIDR 10.0.0.0/16
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.server_name}-vpc"
  }
}

# Internet gateway to route traffic to the internet
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.server_name}-igw"
  }
}

# Single public subnet that does not auto-assign public IPs
resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.0.0/24"
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.server_name}-public-subnet"
  }
}

# Route table that routes internet-bound traffic via the IGW
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.server_name}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# Security group: inbound HTTP from anywhere, egress restricted to VPC CIDR
resource "aws_security_group" "web" {
  name        = "${var.server_name}-web-sg"
  description = "Allow inbound HTTP from anywhere, egress to VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow outbound traffic to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${var.server_name}-web-sg"
  }
}

# Customer-managed KMS key for encrypting the root volume
resource "aws_kms_key" "ebs" {
  description             = "KMS key for EC2 root volume encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = {
    Name = "${var.server_name}-ebs-key"
  }
}

resource "aws_kms_alias" "ebs" {
  name          = "alias/${var.server_name}-ebs"
  target_key_id = aws_kms_key.ebs.key_id
}

# Latest Amazon Linux 2 AMI
data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = var.ami_owners

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }
}

# EC2 instance running Apache (Amazon Linux 2), IMDSv2 required, encrypted root volume
resource "aws_instance" "web" {
  ami                         = data.aws_ami.amazon_linux_2.id
  instance_type               = var.instance_type
  subnet_id                   = aws_subnet.public.id
  vpc_security_group_ids      = [aws_security_group.web.id]
  associate_public_ip_address = false

  user_data = <<-EOF
    #!/bin/bash
    yum update -y
    yum install -y httpd
    systemctl enable httpd
    systemctl start httpd
  EOF

  root_block_device {
    encrypted   = true
    kms_key_id  = aws_kms_key.ebs.arn
    volume_type = "gp3"
    volume_size = 20
  }

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1
    instance_metadata_tags      = "enabled"
  }

  tags = {
    Name = var.server_name
  }
}

# Elastic IP attached to the instance
resource "aws_eip" "web" {
  domain = "vpc"

  tags = {
    Name = "${var.server_name}-eip"
  }
}

resource "aws_eip_association" "web" {
  instance_id   = aws_instance.web.id
  allocation_id = aws_eip.web.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
  required_version = ">= 1.0"
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

# ---------------------------------------------------------------------------
# KMS key shared by all three SNS topics
# ---------------------------------------------------------------------------
resource "aws_kms_key" "sns" {
  description              = "Customer-managed KMS key for SNS topics"
  key_usage                = "ENCRYPT_DECRYPT"
  customer_master_key_spec = "SYMMETRIC_DEFAULT"
  enable_key_rotation      = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow SNS to use the key"
        Effect = "Allow"
        Principal = {
          Service = "sns.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey*"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "sns" {
  name          = "alias/sns-topics"
  target_key_id = aws_kms_key.sns.id
}

# ---------------------------------------------------------------------------
# SNS topics
# ---------------------------------------------------------------------------
resource "aws_sns_topic" "my_topic_with_policy" {
  name              = "my-topic-with-policy"
  kms_master_key_id = aws_kms_key.sns.arn
}

resource "aws_sns_topic" "my_topic_with_policy2" {
  name              = "my-topic-with-policy2"
  kms_master_key_id = aws_kms_key.sns.arn
}

resource "aws_sns_topic" "user_updates_topic" {
  name              = "user-updates-topic"
  kms_master_key_id = aws_kms_key.sns.arn

  delivery_policy = jsonencode({
    http = {
      defaultHealthyRetryPolicy = {
        minDelayTarget     = 1
        maxDelayTarget     = 20
        numRetries         = 5
        numMaxDelayRetries = 2
        numNoDelayRetries  = 2
        backoffFunction    = "linear"
      }
    }
  })
}

# ---------------------------------------------------------------------------
# Topic policy shared by my-topic-with-policy and my-topic-with-policy2
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "topic_policy" {
  statement {
    sid    = "AllowAllPrincipalsFullSNSAccess"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["*"]
    }
    actions   = [
      "SNS:GetTopicAttributes",
      "SNS:SetTopicAttributes",
      "SNS:AddPermission",
      "SNS:RemovePermission",
      "SNS:DeleteTopic",
      "SNS:Subscribe",
      "SNS:ListSubscriptionsByTopic",
      "SNS:Publish",
    ]
    resources = [aws_sns_topic.my_topic_with_policy.arn]
  }
}

resource "aws_sns_topic_policy" "my_topic_with_policy" {
  arn    = aws_sns_topic.my_topic_with_policy.arn
  policy = data.aws_iam_policy_document.topic_policy.json
}

resource "aws_sns_topic_policy" "my_topic_with_policy2" {
  arn    = aws_sns_topic.my_topic_with_policy2.arn
  policy = data.aws_iam_policy_document.topic_policy.json
}

locals {
  name_prefix = "test-vpc"
}

data "aws_availability_zones" "available" {
  state = "available"
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "192.168.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.name_prefix}-vpc"
  }
}

# Public subnet
resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "192.168.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "${local.name_prefix}-public"
  }
}

# Private subnet
resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "192.168.4.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "${local.name_prefix}-private"
  }
}

