  }
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

# Standalone Elastic IP (not associated with any resource)
resource "aws_eip" "standalone" {
  domain = "vpc"

  tags = {
    Name = "${local.name_prefix}-standalone-eip"
  }
}

locals {
  vpc_cidr        = "10.0.0.0/16"
  azs             = data.aws_availability_zones.available.names
  public_subnets  = [for i in range(2) : cidrsubnet(local.vpc_cidr, 8, i)]
  private_subnets = [for i in range(2) : cidrsubnet(local.vpc_cidr, 8, i + 2)]
}

data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------
# VPC
# ---------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

# ---------------------------------------------------------------------------
# Internet Gateway
# ---------------------------------------------------------------------------
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw"
  }
}

# ---------------------------------------------------------------------------
# Public Subnets
# ---------------------------------------------------------------------------
resource "aws_subnet" "public" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.public_subnets[count.index]
  availability_zone = local.azs[count.index]

  tags = {
    Name = "public-${local.azs[count.index]}"
  }
}

# ---------------------------------------------------------------------------
# Private Subnets
# ---------------------------------------------------------------------------
resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnets[count.index]
  availability_zone = local.azs[count.index]

  tags = {
    Name = "private-${local.azs[count.index]}"
  }
}

# ---------------------------------------------------------------------------
# Elastic IP for NAT Gateway
# ---------------------------------------------------------------------------
resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "nat-eip"
  }
}

# ---------------------------------------------------------------------------
# NAT Gateway (single, placed in the first public subnet)
# ---------------------------------------------------------------------------
resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "main-nat"
  }

  depends_on = [aws_internet_gateway.main]
}

# ---------------------------------------------------------------------------
# Public Route Table
# ---------------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# Private Route Table
# ---------------------------------------------------------------------------
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# ---------------------------------------------------------------------------
# Security Group
# ---------------------------------------------------------------------------
resource "aws_security_group" "app" {
  name        = "app-sg"
  description = "Security group for containerized applications"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "app-sg"
  }
}

# Ingress: SSH from VPC CIDR only
resource "aws_vpc_security_group_ingress_rule" "ssh" {
  security_group_id = aws_security_group.app.id
  description       = "SSH from VPC CIDR"
  cidr_ipv4         = local.vpc_cidr
  from_port         = 22
  to_port           = 22
  ip_protocol       = "tcp"
}

# Ingress: HTTP from anywhere
resource "aws_vpc_security_group_ingress_rule" "http" {
  security_group_id = aws_security_group.app.id
  description       = "HTTP from anywhere"
  cidr_ipv4         = "0.0.0.0/0"
  from_port         = 80
  to_port           = 80
  ip_protocol       = "tcp"
}

# Ingress: HTTPS from anywhere
resource "aws_vpc_security_group_ingress_rule" "https" {
  security_group_id = aws_security_group.app.id
  description       = "HTTPS from anywhere"
  cidr_ipv4         = "0.0.0.0/0"
  from_port         = 443
  to_port           = 443
  ip_protocol       = "tcp"
}

# Ingress: Application port 3000 from anywhere
resource "aws_vpc_security_group_ingress_rule" "app_3000" {
  security_group_id = aws_security_group.app.id
  description       = "Application port 3000 from anywhere"
  cidr_ipv4         = "0.0.0.0/0"
  from_port         = 3000
  to_port           = 3000
  ip_protocol       = "tcp"
}

# Ingress: PostgreSQL port 5432 from anywhere
resource "aws_vpc_security_group_ingress_rule" "app_5432" {
  security_group_id = aws_security_group.app.id
  description       = "PostgreSQL port 5432 from anywhere"
  cidr_ipv4         = "0.0.0.0/0"
  from_port         = 5432
  to_port           = 5432
  ip_protocol       = "tcp"
}

# Egress: limited to VPC CIDR only
resource "aws_vpc_security_group_egress_rule" "all" {
  security_group_id = aws_security_group.app.id
  description       = "Outbound to VPC CIDR only"
  cidr_ipv4         = local.vpc_cidr
  ip_protocol       = "-1"
  from_port         = 0
  to_port           = 0
}

# ---------------------------------------------------------------------------
# Service Discovery Private DNS Namespace
# ---------------------------------------------------------------------------
resource "aws_service_discovery_private_dns_namespace" "main" {
  name        = "service.local"
  description = "Private DNS namespace for containerized services"
  vpc         = aws_vpc.main.id
}

terraform {
  required_providers {
    aws = {
      source = "hashicorp/aws"
    }
  }
}

# -----------------------------------------------------------------------------
# AWS Backup solution
# - KMS-encrypted backup vault with a vault lock enforcing a retention period
#   between 7 and 90 days
# - Backup plan with a scheduled rule targeting the vault
# - Backup selection that automatically backs up all resources tagged with
#   benchmark-backup=true
# -----------------------------------------------------------------------------

locals {
  backup_tag_key        = "benchmark-backup"
  backup_tag_value      = "true"
  vault_name            = "benchmark-backup-vault"
  plan_name             = "benchmark-backup-plan"
  selection_name        = "benchmark-backup-all-tagged"
  rule_name             = "benchmark-daily-backup"
  kms_key_alias         = "alias/benchmark-backup-key"
  backup_role_name      = "benchmark-backup-role"
  backup_daily_hour_utc = 5
  retention_max_days    = 90
  retention_min_days    = 7
}

data "aws_partition" "current" {}

# -----------------------------------------------------------------------------
# KMS key used to encrypt recovery points stored in the backup vault
# -----------------------------------------------------------------------------
resource "aws_kms_key" "backup" {
  description             = "KMS customer managed key that encrypts AWS Backup recovery points"
  enable_key_rotation     = true
  deletion_window_in_days = 30
}

resource "aws_kms_alias" "backup" {
  name          = local.kms_key_alias
  target_key_id = aws_kms_key.backup.key_id
}

# -----------------------------------------------------------------------------
# Backup vault: KMS-encrypted and protected with a vault lock
# -----------------------------------------------------------------------------
resource "aws_backup_vault" "main" {
  name        = local.vault_name
  kms_key_arn = aws_kms_key.backup.arn
}

resource "aws_backup_vault_lock_configuration" "main" {
  backup_vault_name   = aws_backup_vault.main.name
  min_retention_days  = local.retention_min_days
  max_retention_days  = local.retention_max_days
  changeable_for_days = 3
}

# -----------------------------------------------------------------------------
# IAM role assumed by AWS Backup to perform backups and restores
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "backup_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "backup" {
  name               = local.backup_role_name
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role.json
}

resource "aws_iam_role_policy_attachment" "backup_service_role" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

# -----------------------------------------------------------------------------
# Backup plan: scheduled daily rule writing recovery points to the lock-enabled
# vault with recovery points retained for 90 days
# -----------------------------------------------------------------------------
resource "aws_backup_plan" "main" {
  name = local.plan_name

  rule {
    rule_name         = local.rule_name
    target_vault_name = aws_backup_vault.main.name
    schedule          = "cron(0 ${local.backup_daily_hour_utc} * * ? *)"
    start_window      = 60
    completion_window = 120

    lifecycle {
      delete_after = local.retention_max_days
    }
  }
}

# -----------------------------------------------------------------------------
# Backup selection: automatically back up every resource that carries the
# benchmark-backup=true tag
# -----------------------------------------------------------------------------
resource "aws_backup_selection" "main" {
  name         = local.selection_name
  plan_id      = aws_backup_plan.main.id
  iam_role_arn = aws_iam_role.backup.arn
  resources    = ["*"]

  selection_tag {
    type  = "STRINGEQUALS"
    key   = local.backup_tag_key
    value = local.backup_tag_value
  }
}

# -----------------------------------------------------------------------------
# Cognito User Pool
# -----------------------------------------------------------------------------
resource "aws_cognito_user_pool" "main" {
  name = "main-user-pool"

  auto_verified_attributes = ["email"]

  password_policy {
    minimum_length    = 8
    require_lowercase = true
    require_numbers   = true
    require_symbols   = true
    require_uppercase = true
  }

  mfa_configuration = "OFF"

  schema {
    attribute_data_type      = "String"
    developer_only_attribute = false
    mutable                  = true
    name                     = "email"
    required                 = true

    string_attribute_constraints {
      min_length = 1
      max_length = 256
    }
  }

}

# -----------------------------------------------------------------------------
# User Pool App Client
# -----------------------------------------------------------------------------
resource "aws_cognito_user_pool_client" "app" {
  name                                 = "app-client"
  user_pool_id                         = aws_cognito_user_pool.main.id
  generate_secret                      = false
  explicit_auth_flows                  = ["ALLOW_USER_SRP_AUTH", "ALLOW_REFRESH_TOKEN_AUTH"]
  prevent_user_existence_errors        = "ENABLED"
  callback_urls                        = ["https://example.com/callback"]
  logout_urls                          = ["https://example.com/logout"]
  allowed_oauth_flows                  = ["code"]
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_scopes                 = ["openid", "email", "profile"]
  supported_identity_providers         = ["COGNITO"]
}

# -----------------------------------------------------------------------------
# Identity Pool
# -----------------------------------------------------------------------------
resource "aws_cognito_identity_pool" "main" {
  identity_pool_name               = "main-identity-pool"
  allow_unauthenticated_identities = false

  cognito_identity_providers {
    client_id               = aws_cognito_user_pool_client.app.id
    provider_name           = aws_cognito_user_pool.main.endpoint
    server_side_token_check = false
  }
}

# -----------------------------------------------------------------------------
# IAM Role for Authenticated Identities
# -----------------------------------------------------------------------------
resource "aws_iam_role" "authenticated" {
  name = "cognito-authenticated-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = "cognito-identity.amazonaws.com"
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          "ForAnyValue:StringLike" = {
            "cognito-identity.amazonaws.com:amr" = "authenticated"
          }
          "StringEquals" = {
            "cognito-identity.amazonaws.com:aud" = aws_cognito_identity_pool.main.id
          }
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# IAM Policy: Cognito Sync + Mobile Analytics access
# -----------------------------------------------------------------------------
resource "aws_iam_policy" "cognito_sync_mobile_analytics" {
  name        = "cognito-sync-mobile-analytics"
  description = "Allows Cognito Sync and Mobile Analytics access for authenticated identities"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "cognito-sync:ListDatasets",
          "cognito-sync:DescribeDataset",
          "cognito-sync:SubscribeToDataset",
          "cognito-sync:UnsubscribeFromDataset",
          "cognito-sync:UpdateRecords",
          "cognito-sync:QueryRecords",
          "cognito-sync:GetCognitoEvents",
          "cognito-sync:SetCognitoEvents"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "mobileanalytics:PutEvents",
          "mobileanalytics:GetReports",
          "mobileanalytics:GetFinancialReports"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "authenticated_cognito_sync" {
  role       = aws_iam_role.authenticated.name
  policy_arn = aws_iam_policy.cognito_sync_mobile_analytics.arn
}

# -----------------------------------------------------------------------------
# Attach the authenticated role to the Identity Pool
# -----------------------------------------------------------------------------
resource "aws_cognito_identity_pool_roles_attachment" "main" {
  identity_pool_id = aws_cognito_identity_pool.main.id

  roles = {
    "authenticated" = aws_iam_role.authenticated.arn
  }
}

# -----------------------------------------------------------------------------
# Custom test VPC
# -----------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "test-vpc"
  }
}

# -----------------------------------------------------------------------------
# Subnet - does NOT auto-assign public IPs
# -----------------------------------------------------------------------------
resource "aws_subnet" "main" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "test-subnet"
  }
}

# -----------------------------------------------------------------------------
# Internet gateway
# -----------------------------------------------------------------------------
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "test-internet-gateway"
  }
}

# -----------------------------------------------------------------------------
# Elastic IP
# -----------------------------------------------------------------------------
resource "aws_eip" "main" {
  domain = "vpc"

  tags = {
    Name = "test-eip"
  }
}

# -----------------------------------------------------------------------------
# Custom DHCP options set using standard public DNS servers
# -----------------------------------------------------------------------------
resource "aws_vpc_dhcp_options" "main" {
  domain_name_servers = ["8.8.8.8", "8.8.4.4"]
  domain_name         = "test.local"

  tags = {
    Name = "test-dhcp-options"
  }
}

resource "aws_vpc_dhcp_options_association" "main" {
  vpc_id          = aws_vpc.main.id
  dhcp_options_id = aws_vpc_dhcp_options.main.id
}

# -----------------------------------------------------------------------------
# Default security group for the VPC
#   Ingress: HTTP, HTTPS, SSH - only from the VPC CIDR
#   Egress:  restricted to the VPC CIDR
# -----------------------------------------------------------------------------
resource "aws_default_security_group" "main" {
  vpc_id = aws_vpc.main.id

  ingress {
    description = "HTTP from VPC CIDR"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "HTTPS from VPC CIDR"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "SSH from VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "All traffic to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "test-default-security-group"
  }
}

terraform {
  required_version = ">= 1.5"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

data "aws_region" "current" {}
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

# ---------------------------------------------------------------------------
# KMS Key for encrypting the SNS topic
# ---------------------------------------------------------------------------
resource "aws_kms_key" "sns" {
  description             = "Customer-managed KMS key for SNS topic event-topic"
  enable_key_rotation     = true
  deletion_window_in_days = 10

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable admin access"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow SNS service to use the key"
        Effect = "Allow"
        Principal = {
          Service = "sns.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
      },
    ]
  })
}

resource "aws_kms_alias" "sns" {
  name          = "alias/event-topic-key"
  target_key_id = aws_kms_key.sns.key_id
}

# ---------------------------------------------------------------------------
# SNS Topic
# ---------------------------------------------------------------------------
resource "aws_sns_topic" "event" {
  name              = "event-topic"
  kms_master_key_id = aws_kms_key.sns.key_id
}

# ---------------------------------------------------------------------------
# IAM Role that grants API Gateway permission to publish to SNS
# ---------------------------------------------------------------------------
resource "aws_iam_role" "api_gateway_sns" {
  name               = "api-gateway-sns-publish-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "api_gateway_sns" {
  name = "api-gateway-sns-publish-policy"
  role = aws_iam_role.api_gateway_sns.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "sns:Publish"
        Resource = aws_sns_topic.event.arn
      },
      {
        Effect = "Allow"
        Action = [
          "kms:GenerateDataKey",
          "kms:Decrypt"
        ]
        Resource = aws_kms_key.sns.arn
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# API Gateway REST API
# ---------------------------------------------------------------------------
resource "aws_api_gateway_rest_api" "main" {
  name        = "event-ingest-api"
  description = "REST API that publishes POST requests to SNS topic event-topic"
}

# POST method on the root resource (/)
resource "aws_api_gateway_method" "root_post" {
  rest_api_id   = aws_api_gateway_rest_api.main.id
  resource_id   = aws_api_gateway_rest_api.main.root_resource_id
  http_method   = "POST"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "sns" {
  rest_api_id             = aws_api_gateway_rest_api.main.id
  resource_id             = aws_api_gateway_rest_api.main.root_resource_id
  http_method             = aws_api_gateway_method.root_post.http_method
  integration_http_method = "POST"
  type                    = "AWS"
  uri                     = "arn:${data.aws_partition.current.partition}:apigateway:${data.aws_region.current.region}:sns:path//"
  credentials             = aws_iam_role.api_gateway_sns.arn

  request_parameters = {
    "integration.request.header.Content-Type" = "'application/x-www-form-urlencoded'"
  }

  request_templates = {
    "application/json" = <<EOF
Action=Publish&TargetArn=${aws_sns_topic.event.arn}&Message=$util.urlEncode($input.body)
EOF
    "application/x-www-form-urlencoded" = <<EOF
Action=Publish&TargetArn=${aws_sns_topic.event.arn}&Message=$util.urlEncode($input.body)
EOF
  }
}

resource "aws_api_gateway_method_response" "root_post_200" {
  rest_api_id = aws_api_gateway_rest_api.main.id
  resource_id = aws_api_gateway_rest_api.main.root_resource_id
  http_method = aws_api_gateway_method.root_post.http_method
  status_code = "200"

  response_models = {
    "application/json" = "Empty"
  }
}

resource "aws_api_gateway_integration_response" "sns" {
  rest_api_id = aws_api_gateway_rest_api.main.id
  resource_id = aws_api_gateway_rest_api.main.root_resource_id
  http_method = aws_api_gateway_method.root_post.http_method
  status_code = aws_api_gateway_method_response.root_post_200.status_code

  depends_on = [aws_api_gateway_integration.sns]
}

resource "aws_api_gateway_deployment" "main" {
  rest_api_id = aws_api_gateway_rest_api.main.id

  triggers = {
    redeployment = sha1(jsonencode([
      aws_api_gateway_rest_api.main.body,
      aws_api_gateway_method.root_post.id,
      aws_api_gateway_integration.sns.id,
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_api_gateway_stage" "main" {
  deployment_id = aws_api_gateway_deployment.main.id
  rest_api_id   = aws_api_gateway_rest_api.main.id
  stage_name    = "prod"
}

variable "region" {
