  tags = {
    Name = "ntier-private"
  }
}

# Route table associations - public subnets
resource "aws_route_table_association" "web" {
  subnet_id      = aws_subnet.web.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "management" {
  subnet_id      = aws_subnet.management.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "web2" {
  subnet_id      = aws_subnet.web2.id
  route_table_id = aws_route_table.public.id
}

# Route table associations - private subnets
resource "aws_route_table_association" "app" {
  subnet_id      = aws_subnet.app.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "database" {
  subnet_id      = aws_subnet.database.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "app2" {
  subnet_id      = aws_subnet.app2.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "database2" {
  subnet_id      = aws_subnet.database2.id
  route_table_id = aws_route_table.private.id
}

# =============================================================================
# AWS KMS Key Management Module
# =============================================================================
# This Terraform template provisions and manages AWS KMS keys with support for:
#   - Standard customer-managed KMS keys (AWS-provided key material)
#   - External KMS keys (base64-encoded key material)
#   - Multi-region replica keys (standard or external)
#   - Dynamic key policy generation based on role inputs
#   - KMS aliases (exact names or name prefixes)
#   - KMS grants with encryption context constraints
# =============================================================================

terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.72.0"
    }
  }
}

# ---------------------------------------------------------------------------
# DATA SOURCES
# ---------------------------------------------------------------------------
data "aws_caller_identity" "current" {}

# ---------------------------------------------------------------------------
# VARIABLES - Mutually Exclusive Creation Flags
# ---------------------------------------------------------------------------
variable "create_standard_key" {
  description = "Flag to create a standard customer-managed KMS key with AWS-provided key material"
  type        = bool
  default     = false
}

variable "create_external_key" {
  description = "Flag to create an external KMS key with base64-encoded key material"
  type        = bool
  default     = false
}

variable "create_replica_standard_key" {
  description = "Flag to create a standard multi-region replica key referencing a primary key ARN"
  type        = bool
  default     = false
}

variable "create_replica_external_key" {
  description = "Flag to create a replica external key with custom key material and primary external key ARN"
  type        = bool
  default     = false
}

# ---------------------------------------------------------------------------
# VARIABLES - Key Configuration
# ---------------------------------------------------------------------------
variable "key_description" {
  description = "Description of the KMS key"
  type        = string
  default     = "KMS key managed by Terraform"
}

variable "key_deletion_window_in_days" {
  description = "Waiting period before key deletion (valid range 7-30)"
  type        = number
  default     = 7
}

variable "key_is_enabled" {
  description = "Whether the key is enabled for use"
  type        = bool
  default     = true
}

variable "key_usage" {
  description = "Intended cryptographic usage of the key (ENCRYPT_DECRYPT, GENERATE_VERIFY_MAC, etc.)"
  type        = string
  default     = "ENCRYPT_DECRYPT"
}

variable "key_spec" {
  description = "Key specification (SYMMETRIC_DEFAULT, RSA_2048, ECC_NIST_P256, etc.)"
  type        = string
  default     = "SYMMETRIC_DEFAULT"
}

variable "key_tags" {
  description = "Tags to attach to the KMS key"
  type        = map(string)
  default     = {}
}

variable "key_multi_region" {
  description = "Whether to create the key as a multi-region key (standard/external keys only)"
  type        = bool
  default     = false
}

variable "key_material_base64" {
  description = "Base64-encoded key material (required for external keys and replica external keys)"
  type        = string
  default     = null
}

variable "primary_key_arn" {
  description = "ARN of the primary key (required for replica keys)"
  type        = string
  default     = null
}

# ---------------------------------------------------------------------------
# VARIABLES - Policy Roles
# ---------------------------------------------------------------------------
variable "root_policy_arns" {
  description = "ARNs for root key policy (full access to all key operations)"
  type        = list(string)
  default     = []
}

variable "administrator_arns" {
  description = "ARNs for key administrators (manage, describe, schedule deletion)"
  type        = list(string)
  default     = []
}

variable "key_user_arns" {
  description = "ARNs for standard key users (encrypt, decrypt, re-encrypt, describe)"
  type        = list(string)
  default     = []
}

variable "service_user_arns" {
  description = "ARNs for service users (encrypt, decrypt only)"
  type        = list(string)
  default     = []
}

variable "ec2_autoscaling_role_arns" {
  description = "ARNs for EC2 Auto Scaling roles"
  type        = list(string)
  default     = []
}

variable "symmetric_crypto_user_arns" {
  description = "ARNs for symmetric cryptographic operation users"
  type        = list(string)
  default     = []
}

variable "hmac_user_arns" {
  description = "ARNs for HMAC operation users"
  type        = list(string)
  default     = []
}

variable "asymmetric_public_encryption_user_arns" {
  description = "ARNs for asymmetric public encryption users"
  type        = list(string)
  default     = []
}

variable "asymmetric_sign_verify_user_arns" {
  description = "ARNs for asymmetric sign/verify users"
  type        = list(string)
  default     = []
}

variable "route53_dnssec_role_arns" {
  description = "ARNs for Route 53 DNSSEC signing service permissions"
  type        = list(string)
  default     = []
}

variable "custom_policy_statements" {
  description = "Custom policy statements to append to the generated policy"
  type = list(object({
    sid         = string
    effect      = string
    principal   = any
    action      = list(string)
    resource    = optional(string)
    conditions  = optional(list(any))
  }))
  default = []
}

variable "override_policy" {
  description = "Complete override policy JSON string. When set, all other policy inputs are ignored."
  type        = string
  default     = null
}

# ---------------------------------------------------------------------------
# VARIABLES - Aliases and Grants
# ---------------------------------------------------------------------------
variable "aliases" {
  description = "List of KMS aliases to create. Each entry must have either 'name' (exact alias name) or 'name_prefix'."
  type = list(object({
    name        = optional(string)
    name_prefix = optional(string)
  }))
  default = []
}

variable "grants" {
  description = "List of KMS grants to create"
  type = list(object({
    grantee_principal           = string
    operations                  = list(string)
    retiring_principal          = optional(string)
    encryption_context_equals   = optional(map(string))
    encryption_context_subset   = optional(map(string))
  }))
  default = []
}

# ---------------------------------------------------------------------------
# CROSS-VARIABLE VALIDATION (check blocks)
# ---------------------------------------------------------------------------

check "exactly_one_key_type" {
  assert {
    condition = (
      (var.create_standard_key ? 1 : 0) +
      (var.create_external_key ? 1 : 0) +
      (var.create_replica_standard_key ? 1 : 0) +
      (var.create_replica_external_key ? 1 : 0)
    ) == 1
    error_message = "Exactly one of 'create_standard_key', 'create_external_key', 'create_replica_standard_key', or 'create_replica_external_key' must be set to true."
  }
}

check "external_key_material" {
  assert {
    condition     = !var.create_external_key || (var.key_material_base64 != null && var.key_material_base64 != "")
    error_message = "'key_material_base64' is required when 'create_external_key' is true."
  }
}

check "replica_external_key_material" {
  assert {
    condition     = !var.create_replica_external_key || (var.key_material_base64 != null && var.key_material_base64 != "")
    error_message = "'key_material_base64' is required when 'create_replica_external_key' is true."
  }
}

check "replica_key_arn" {
  assert {
    condition     = !(var.create_replica_standard_key || var.create_replica_external_key) || (var.primary_key_arn != null && var.primary_key_arn != "")
    error_message = "'primary_key_arn' is required when 'create_replica_standard_key' or 'create_replica_external_key' is true."
  }
}

check "alias_name_or_prefix" {
  assert {
    condition = alltrue([
      for a in var.aliases : (a.name != null) != (a.name_prefix != null)
    ])
    error_message = "Each alias entry must have exactly one of 'name' or 'name_prefix' set."
  }
}

# ---------------------------------------------------------------------------
# LOCALS - Policy Generation
# ---------------------------------------------------------------------------
locals {
  # Resolve the current caller ARN for default root policy
  current_arn = data.aws_caller_identity.current.arn

  # Default root ARNs: if none specified, default to the caller
  resolved_root_arns = length(var.root_policy_arns) > 0 ? var.root_policy_arns : [local.current_arn]

  # =========================================================================
  # Policy Statement Generation
  # =========================================================================

  # 1. Root owner statements (full access)
  root_statements = [
    for arn in local.resolved_root_arns : {
      Sid       = "Root Access"
      Effect    = "Allow"
      Principal = { AWS = arn }
      Action    = ["kms:*"]
      Resource  = "*"
    }
  ]

  # 2. Administrator statements
  admin_statements = [
    for arn in var.administrator_arns : {
      Sid       = "Administrator Access"
      Effect    = "Allow"
      Principal = { AWS = arn }
      Action    = [
        "kms:CancelKeyDeletion",
        "kms:CreateAlias",
        "kms:CreateGrant",
        "kms:DeleteAlias",
        "kms:DescribeKey",
        "kms:DisableKey",
        "kms:EnableKey",
        "kms:GetKeyPolicy",
        "kms:GetKeyRotationStatus",
        "kms:ListGrants",
        "kms:PutKeyPolicy",
        "kms:RevokeGrant",
        "kms:ScheduleKeyDeletion",
        "kms:TagResource",
        "kms:UntagResource",
        "kms:UpdateKeyDescription",
      ]
      Resource  = "*"
    }
  ]

  # 3. Standard key user statements
  key_user_statements = [
    for arn in var.key_user_arns : {
      Sid       = "Standard Key User"
      Effect    = "Allow"
      Principal = { AWS = arn }
      Action    = [
        "kms:Decrypt",
        "kms:DescribeKey",
        "kms:Encrypt",
        "kms:ReEncryptFrom",
        "kms:ReEncryptTo",
      ]
      Resource  = "*"
    }
  ]

  # 4. Service user statements
  service_user_statements = [
    for arn in var.service_user_arns : {
      Sid       = "Service User"
      Effect    = "Allow"
      Principal = { AWS = arn }
      Action    = [
        "kms:Decrypt",
        "kms:Encrypt",
      ]
      Resource  = "*"
    }
  ]

  # 5. EC2 Auto Scaling statements
  ec2_autoscaling_statements = [
    for arn in var.ec2_autoscaling_role_arns : {
      Sid       = "EC2 Auto Scaling"
      Effect    = "Allow"
      Principal = { AWS = arn }
      Action    = [
        "kms:CreateGrant",
        "kms:Decrypt",
        "kms:Encrypt",
        "kms:GenerateDataKeyWithoutPlaintext",
        "kms:ReEncryptFrom",
        "kms:ReEncryptTo",
        "kms:RevokeGrant",
      ]
      Resource  = "*"
    }
  ]

  # 6. Symmetric crypto user statements
  symmetric_crypto_statements = [
    for arn in var.symmetric_crypto_user_arns : {
      Sid       = "Symmetric Crypto User"
      Effect    = "Allow"
      Principal = { AWS = arn }
      Action    = [
        "kms:Decrypt",
        "kms:Encrypt",
        "kms:GenerateDataKey",
        "kms:GenerateDataKeyPair",
        "kms:GenerateDataKeyPairWithoutPlaintext",
        "kms:GenerateDataKeyWithoutPlaintext",
        "kms:ReEncryptFrom",
        "kms:ReEncryptTo",
      ]
      Resource  = "*"
    }
  ]

  # 7. HMAC user statements
  hmac_statements = [
    for arn in var.hmac_user_arns : {
      Sid       = "HMAC User"
      Effect    = "Allow"
      Principal = { AWS = arn }
      Action    = [
        "kms:GenerateMac",
        "kms:VerifyMac",
      ]
      Resource  = "*"
    }
  ]

  # 8. Asymmetric public encryption user statements
  asymmetric_public_encryption_statements = [
    for arn in var.asymmetric_public_encryption_user_arns : {
      Sid       = "Asymmetric Public Encryption User"
      Effect    = "Allow"
      Principal = { AWS = arn }
      Action    = [
        "kms:Decrypt",
        "kms:Encrypt",
      ]
      Resource  = "*"
    }
  ]

  # 9. Asymmetric sign/verify user statements
  asymmetric_sign_verify_statements = [
    for arn in var.asymmetric_sign_verify_user_arns : {
      Sid       = "Asymmetric Sign/Verify User"
      Effect    = "Allow"
      Principal = { AWS = arn }
      Action    = [
        "kms:Sign",
        "kms:Verify",
      ]
      Resource  = "*"
    }
  ]

  # 10. Route 53 DNSSEC signing service statements
  route53_dnssec_statements = [
    for arn in var.route53_dnssec_role_arns : {
      Sid       = "Route53 DNSSEC Signing"
      Effect    = "Allow"
      Principal = { AWS = arn }
      Action    = [
        "kms:GetPublicKey",
        "kms:Sign",
      ]
      Resource  = "*"
      Condition = {
        StringEquals = {
          "kms:SignUsage" = "DNSSEC"
        }
      }
    }
  ]

  # 11. Custom policy statements
  custom_statements = flatten([
    for stmt in var.custom_policy_statements : [
      { Sid = stmt.sid, Effect = stmt.effect, Principal = stmt.principal,
        Action = stmt.action, Resource = try(stmt.resource, "*") } +
      (try(length(try(stmt.conditions, [])), 0) > 0 ? { Condition = try(stmt.conditions[0], {}) } : {})
    ]
  ])

  # =========================================================================
  # Combine all statements
  # =========================================================================
  all_statements = concat(
    local.root_statements,
    local.admin_statements,
    local.key_user_statements,
    local.service_user_statements,
    local.ec2_autoscaling_statements,
    local.symmetric_crypto_statements,
    local.hmac_statements,
    local.asymmetric_public_encryption_statements,
    local.asymmetric_sign_verify_statements,
    local.route53_dnssec_statements,
    local.custom_statements
  )

  # =========================================================================
  # Final policy JSON (use override if provided, otherwise build dynamically)
  # =========================================================================
  policy_json = var.override_policy != null ? var.override_policy : jsonencode({
    Version   = "2012-10-17"
    Statement = local.all_statements
  })

  # =========================================================================
  # Resolved key ID and ARN (from whichever key resource is created)
  # =========================================================================
  is_standard_key   = var.create_standard_key
  is_external_key   = var.create_external_key
  is_replica_std    = var.create_replica_standard_key
  is_replica_ext    = var.create_replica_external_key
}

# ---------------------------------------------------------------------------
# RESOURCES - KMS Keys
# ---------------------------------------------------------------------------

# Standard or external KMS key
resource "aws_kms_key" "this" {
  count = local.is_standard_key ? 1 : 0

  description             = var.key_description
  deletion_window_in_days = var.key_deletion_window_in_days
  is_enabled              = var.key_is_enabled
  key_usage               = var.key_usage
  multi_region            = var.key_multi_region
  policy                  = local.policy_json
  tags                    = var.key_tags

  bypass_policy_lockout_safety_check = false

  lifecycle {
    # Prevent accidental deletion of KMS keys with data
    prevent_destroy = true
  }
}

# External KMS key (imported key material)
resource "aws_kms_external_key" "this" {
  count = var.create_external_key ? 1 : 0

  description             = var.key_description
  deletion_window_in_days = var.key_deletion_window_in_days
  enabled                 = var.key_is_enabled
  key_usage               = var.key_usage
  key_spec                = var.key_spec
  key_material_base64     = var.key_material_base64
  multi_region            = var.key_multi_region
  policy                  = local.policy_json
  tags                    = var.key_tags

  bypass_policy_lockout_safety_check = false

  lifecycle {
    prevent_destroy = true
  }
}

# Multi-region replica KMS key (standard)
resource "aws_kms_replica_key" "standard" {
  count = var.create_replica_standard_key ? 1 : 0

  primary_key_arn         = var.primary_key_arn
  description             = var.key_description
  deletion_window_in_days = var.key_deletion_window_in_days
  policy                  = local.policy_json
  tags                    = var.key_tags

  bypass_policy_lockout_safety_check = false

  lifecycle {
    prevent_destroy = true
  }
}

# Multi-region replica KMS key (external)
resource "aws_kms_replica_external_key" "this" {
  count = var.create_replica_external_key ? 1 : 0

  primary_key_arn         = var.primary_key_arn
  description             = var.key_description
  deletion_window_in_days = var.key_deletion_window_in_days
  key_material_base64     = var.key_material_base64
  policy                  = local.policy_json
  tags                    = var.key_tags

  bypass_policy_lockout_safety_check = false

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# LOCALS - Resolved Key References
# ---------------------------------------------------------------------------
locals {
  # The key ID is used for aliases and grants
  key_id = local.is_replica_std ? aws_kms_replica_key.standard[0].key_id : (
    local.is_replica_ext ? aws_kms_replica_external_key.this[0].key_id : (
      local.is_external_key ? aws_kms_external_key.this[0].arn : (
        aws_kms_key.this[0].key_id
      )
    )
  )

  # The key ARN is used for any references that need the full ARN
  key_arn = local.is_replica_std ? aws_kms_replica_key.standard[0].arn : (
    local.is_replica_ext ? aws_kms_replica_external_key.this[0].arn : (
      local.is_external_key ? aws_kms_external_key.this[0].arn : (
        aws_kms_key.this[0].arn
      )
    )
  )
}

# ---------------------------------------------------------------------------
# LOCALS - Resolved Aliases
# ---------------------------------------------------------------------------
locals {
  exact_alias_names = [for a in var.aliases : a.name if a.name != null]
  prefix_alias_names = [for a in var.aliases : a.name_prefix if a.name_prefix != null]
}

# ---------------------------------------------------------------------------
# RESOURCES - KMS Aliases
# ---------------------------------------------------------------------------

# Aliases with exact names
resource "aws_kms_alias" "exact" {
  count = length(local.exact_alias_names)

  name          = "alias/${local.exact_alias_names[count.index]}"
  target_key_id = local.key_id
}

# Aliases with name prefixes
resource "aws_kms_alias" "prefix" {
  count = length(local.prefix_alias_names)

  name          = "alias/${local.prefix_alias_names[count.index]}"
  target_key_id = local.key_id
}

# ---------------------------------------------------------------------------
# RESOURCES - KMS Grants
# ---------------------------------------------------------------------------

resource "aws_kms_grant" "this" {
  count = length(var.grants)

  key_id             = local.key_id
  grantee_principal  = var.grants[count.index].grantee_principal
  operations         = var.grants[count.index].operations
  retiring_principal = try(var.grants[count.index].retiring_principal, null)

  constraints {
    encryption_context_equals  = try(var.grants[count.index].encryption_context_equals, null)
    encryption_context_subset  = try(var.grants[count.index].encryption_context_subset, null)
  }
}

# ---------------------------------------------------------------------------
# OUTPUTS
# ---------------------------------------------------------------------------
output "key_id" {
  description = "The unique identifier of the created KMS key"
  value       = local.key_id
}

output "key_arn" {
  description = "The ARN of the created KMS key"
  value       = local.key_arn
}

output "key_type" {
  description = "The type of key created"
  value = var.create_standard_key ? "standard" : (
    var.create_external_key ? "external" : (
      var.create_replica_standard_key ? "replica_standard" : "replica_external"
    )
  )
}

output "alias_names" {
  description = "The list of created alias names"
  value = concat(
    [for a in aws_kms_alias.exact : a.name],
    [for a in aws_kms_alias.prefix : a.name]
  )
}

output "grant_count" {
  description = "The number of grants created"
  value = length(aws_kms_grant.this)
}

# ------------------------------------------------------------------------------
# Provider / version requirements
# ------------------------------------------------------------------------------
terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Data sources for static provider metadata
# ------------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

# ------------------------------------------------------------------------------
# Local values
# ------------------------------------------------------------------------------
locals {
  # Append ".fifo" suffix for FIFO topics if not already present
  topic_name = var.fifo_topic ? (
    endswith(var.topic_name, ".fifo") ? var.topic_name : "${var.topic_name}.fifo"
  ) : var.topic_name

  # Dynamic KMS selection: created key > provided key > fallback alias
  kms_master_key_id = var.create_kms_key ? (
    aws_kms_key.sns[0].arn
  ) : (
    var.kms_master_key_id != null ? var.kms_master_key_id : "alias/aws/sns"
  )
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "topic_name" {
  description = "Name of the SNS topic. For FIFO topics '.fifo' is appended automatically."
  type        = string
}

variable "create_kms_key" {
  description = "When true, create a dedicated KMS key for SNS encryption. Defaults to true to ensure a customer-managed key is used."
  type        = bool
  default     = true
}

variable "kms_master_key_id" {
  description = "Explicit KMS key ID, ARN, or alias to use. Ignored when create_kms_key is true."
  type        = string
  default     = null
}

variable "topic_policy_json" {
  description = "Optional JSON policy document to attach to the SNS topic."
  type        = string
  default     = null
}

variable "fifo_topic" {
  description = "Set to true for a FIFO SNS topic."
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enable content-based deduplication for FIFO topics. Only used when fifo_topic is true."
  type        = bool
  default     = false
}

variable "subscriptions" {
  description = "Map of subscriptions keyed by name. Each entry supports endpoint, protocol, endpoint_auto_confirms, raw_message_delivery, filter_policy (JSON string), and redrive_policy (JSON string)."
  type = map(object({
    endpoint               = string
    protocol               = string
    endpoint_auto_confirms = optional(bool, false)
    raw_message_delivery   = optional(bool, false)
    filter_policy          = optional(string, null)
    redrive_policy         = optional(string, null)
  }))
  default = {}
}

# ------------------------------------------------------------------------------
# Feedback / delivery logging variables
# ------------------------------------------------------------------------------
variable "application_success_feedback_role_arn" {
  description = "IAM role ARN for application success feedback logging."
  type        = string
  default     = null
}
variable "application_failure_feedback_role_arn" {
  description = "IAM role ARN for application failure feedback logging."
  type        = string
  default     = null
}
variable "application_success_feedback_sample_rate" {
  description = "Sample rate (0-100) for application success feedback."
  type        = number
  default     = null
}

variable "http_success_feedback_role_arn" {
  description = "IAM role ARN for HTTP success feedback logging."
  type        = string
  default     = null
}
variable "http_failure_feedback_role_arn" {
  description = "IAM role ARN for HTTP failure feedback logging."
  type        = string
  default     = null
}
variable "http_success_feedback_sample_rate" {
  description = "Sample rate (0-100) for HTTP success feedback."
  type        = number
  default     = null
}

variable "lambda_success_feedback_role_arn" {
  description = "IAM role ARN for Lambda success feedback logging."
  type        = string
  default     = null
}
variable "lambda_failure_feedback_role_arn" {
  description = "IAM role ARN for Lambda failure feedback logging."
  type        = string
  default     = null
}
variable "lambda_success_feedback_sample_rate" {
  description = "Sample rate (0-100) for Lambda success feedback."
  type        = number
  default     = null
}

variable "sqs_success_feedback_role_arn" {
  description = "IAM role ARN for SQS success feedback logging."
  type        = string
  default     = null
}
variable "sqs_failure_feedback_role_arn" {
  description = "IAM role ARN for SQS failure feedback logging."
  type        = string
  default     = null
}
variable "sqs_success_feedback_sample_rate" {
  description = "Sample rate (0-100) for SQS success feedback."
  type        = number
  default     = null
}

variable "firehose_success_feedback_role_arn" {
  description = "IAM role ARN for Firehose success feedback logging."
  type        = string
  default     = null
}
variable "firehose_failure_feedback_role_arn" {
  description = "IAM role ARN for Firehose failure feedback logging."
  type        = string
  default     = null
}
variable "firehose_success_feedback_sample_rate" {
  description = "Sample rate (0-100) for Firehose success feedback."
  type        = number
  default     = null
}

# ------------------------------------------------------------------------------
# KMS Key (optional)
# ------------------------------------------------------------------------------
resource "aws_kms_key" "sns" {
  count                    = var.create_kms_key ? 1 : 0
  description             = "Dedicated KMS key for SNS topic ${local.topic_name}"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAdminPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowCloudWatchLogsEncryption"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.region}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "sns" {
  count         = var.create_kms_key ? 1 : 0
  name          = "alias/sns/${replace(local.topic_name, ".", "-")}"
  target_key_id = aws_kms_key.sns[0].key_id
}

# ------------------------------------------------------------------------------
# SNS Topic
# ------------------------------------------------------------------------------
resource "aws_sns_topic" "this" {
  name = local.topic_name

  # FIFO settings
  fifo_topic                  = var.fifo_topic
  content_based_deduplication = var.fifo_topic ? var.content_based_deduplication : null

  # Server-side encryption
  kms_master_key_id = local.kms_master_key_id

  # Application endpoint feedback logging
  application_success_feedback_role_arn    = var.application_success_feedback_role_arn
  application_failure_feedback_role_arn    = var.application_failure_feedback_role_arn
  application_success_feedback_sample_rate = var.application_success_feedback_sample_rate

  # HTTP endpoint feedback logging
  http_success_feedback_role_arn    = var.http_success_feedback_role_arn
  http_failure_feedback_role_arn    = var.http_failure_feedback_role_arn
  http_success_feedback_sample_rate = var.http_success_feedback_sample_rate

  # Lambda endpoint feedback logging
  lambda_success_feedback_role_arn    = var.lambda_success_feedback_role_arn
  lambda_failure_feedback_role_arn    = var.lambda_failure_feedback_role_arn
  lambda_success_feedback_sample_rate = var.lambda_success_feedback_sample_rate

  # SQS endpoint feedback logging
  sqs_success_feedback_role_arn    = var.sqs_success_feedback_role_arn
  sqs_failure_feedback_role_arn    = var.sqs_failure_feedback_role_arn
  sqs_success_feedback_sample_rate = var.sqs_success_feedback_sample_rate

  # Firehose endpoint feedback logging
  firehose_success_feedback_role_arn    = var.firehose_success_feedback_role_arn
  firehose_failure_feedback_role_arn    = var.firehose_failure_feedback_role_arn
  firehose_success_feedback_sample_rate = var.firehose_success_feedback_sample_rate

  tags = var.tags
}

# ------------------------------------------------------------------------------
# SNS Topic Policy (optional)
# ------------------------------------------------------------------------------
resource "aws_sns_topic_policy" "this" {
  count  = var.topic_policy_json != null ? 1 : 0
  arn    = aws_sns_topic.this.arn
  policy = var.topic_policy_json
}

# ------------------------------------------------------------------------------
# SNS Topic Subscriptions (dynamic)
# ------------------------------------------------------------------------------
resource "aws_sns_topic_subscription" "this" {
  for_each = var.subscriptions

  topic_arn               = aws_sns_topic.this.arn
  endpoint                = each.value.endpoint
  protocol                = each.value.protocol
  endpoint_auto_confirms  = each.value.endpoint_auto_confirms
  raw_message_delivery    = each.value.raw_message_delivery
  filter_policy           = each.value.filter_policy
  redrive_policy          = each.value.redrive_policy
}

# ------------------------------------------------------------------------------
# Tags
# ------------------------------------------------------------------------------
variable "tags" {
  description = "Map of tags to apply to resources."
  type        = map(string)
  default     = {}
}

# ------------------------------------------------------------------------------
# IAM Access Management Infrastructure
#
# Organizes development team permissions and EC2 instance access. Every component
# has an independent boolean creation toggle so it can be enabled or disabled
# individually.
# ------------------------------------------------------------------------------

terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
  }
}

data "aws_partition" "current" {}

locals {
  iam_read_only_access_policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/IAMReadOnlyAccess"
}

# ------------------------------------------------------------------------------
# Independent creation toggles
# ------------------------------------------------------------------------------

variable "create_developers_group" {
  description = "Whether to create the IAM developers group"
  type        = bool
  default     = true
}

variable "create_read_only_and_s3_full_access_policy" {
  description = "Whether to create the IAM read-only and S3 read/write access policy"
  type        = bool
  default     = true
}

variable "create_group_policy_attachment" {
  description = "Whether to attach the read-only and S3 policy to the developers group"
  type        = bool
  default     = true
}

variable "create_developers_users" {
  description = "Whether to create the IAM developer users"
  type        = bool
  default     = true
}

variable "create_ec2_console_screenshot_policy" {
  description = "Whether to create the EC2 console screenshot policy"
  type        = bool
  default     = true
}

variable "create_user_policy_attachment" {
  description = "Whether to attach the EC2 console screenshot policy to each developer user"
  type        = bool
  default     = true
}

variable "create_group_membership" {
  description = "Whether to associate the developer users with the developers group"
  type        = bool
  default     = true
}

variable "create_ec2_instance_role" {
  description = "Whether to create the EC2 instance role"
  type        = bool
  default     = true
}

# ------------------------------------------------------------------------------
# Resource naming and default settings
# ------------------------------------------------------------------------------

variable "developers_group_name" {
  description = "Name of the IAM group for the development team"
  type        = string
  default     = "developers"
}

variable "developer_user_names" {
  description = "List of IAM user names to create for the development team"
  type        = list(string)
  default     = ["jack", "jones"]
}

variable "developer_user_tags" {
  description = "Tags applied to every created developer user"
  type        = map(string)
  default = {
    user_created_by = "terraform"
  }
}

variable "read_only_and_s3_full_access_policy_name" {
  description = "Name of the IAM policy granting IAM read-only and S3 read/write object access"
  type        = string
  default     = "iam_read_only_and_s3_full_access"
}

variable "ec2_console_screenshot_policy_name" {
  description = "Name of the IAM policy granting EC2 console screenshot access"
  type        = string
  default     = "ec2_get_console_screenshot"
}

variable "ec2_instance_role_name" {
  description = "Name of the IAM role that EC2 instances can assume"
  type        = string
  default     = "instance_role"
}

# ------------------------------------------------------------------------------
# IAM developers group
# ------------------------------------------------------------------------------

resource "aws_iam_group" "developers" {
  count = var.create_developers_group ? 1 : 0
  name  = var.developers_group_name
  path  = "/"
}

# ------------------------------------------------------------------------------
# IAM read-only and S3 read/write access policy
# ------------------------------------------------------------------------------

resource "aws_iam_policy" "read_only_and_s3_full_access" {
  count       = var.create_read_only_and_s3_full_access_policy ? 1 : 0
  name        = var.read_only_and_s3_full_access_policy_name
  description = "Allows read-only access to IAM and read/write access to S3 objects"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ReadOnlyAccessToIAM"
        Action = [
          "iam:GenerateCredentialReport",
          "iam:GenerateServiceLastAccessedDetails",
          "iam:Get*",
          "iam:List*",
        ]
        Effect   = "Allow"
        Resource = "*"
      },
      {
        Sid    = "ReadWriteAccessToS3Objects"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
        ]
        Effect   = "Allow"
        Resource = "arn:${data.aws_partition.current.partition}:s3:::*/*"
      },
    ]
  })
  tags = {
    policy_created_by = "terraform"
  }
}

# ------------------------------------------------------------------------------
# Group policy attachment
# ------------------------------------------------------------------------------

resource "aws_iam_group_policy_attachment" "read_only_and_s3_full_access" {
  count      = var.create_group_policy_attachment && var.create_developers_group && var.create_read_only_and_s3_full_access_policy ? 1 : 0
  group      = aws_iam_group.developers[0].name
  policy_arn = aws_iam_policy.read_only_and_s3_full_access[0].arn
}

# ------------------------------------------------------------------------------
# IAM developer users
# ------------------------------------------------------------------------------

resource "aws_iam_user" "developers" {
  for_each = var.create_developers_users ? toset(var.developer_user_names) : toset([])
  name     = each.key
  tags     = var.developer_user_tags
}

# ------------------------------------------------------------------------------
# EC2 console screenshot policy
# ------------------------------------------------------------------------------

resource "aws_iam_policy" "ec2_console_screenshot" {
  count       = var.create_ec2_console_screenshot_policy ? 1 : 0
  name        = var.ec2_console_screenshot_policy_name
  description = "Allows retrieving EC2 instance console screenshots"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowGetConsoleScreenshot"
        Action   = "ec2:GetConsoleScreenshot"
        Effect   = "Allow"
        Resource = "*"
      },
    ]
  })
  tags = {
    policy_created_by = "terraform"
  }
}

# ------------------------------------------------------------------------------
# User policy attachments
# ------------------------------------------------------------------------------

resource "aws_iam_user_policy_attachment" "ec2_console_screenshot" {
  for_each   = var.create_user_policy_attachment && var.create_developers_users && var.create_ec2_console_screenshot_policy ? toset(var.developer_user_names) : toset([])
  user       = each.key
  policy_arn = aws_iam_policy.ec2_console_screenshot[0].arn
}

# ------------------------------------------------------------------------------
# Group membership associations
# ------------------------------------------------------------------------------

resource "aws_iam_group_membership" "developers" {
  count = var.create_group_membership && var.create_developers_group && var.create_developers_users ? 1 : 0
  name  = "${var.developers_group_name}-developers-membership"
  users = [for user in var.developer_user_names : user]
  group = aws_iam_group.developers[0].name
}

# ------------------------------------------------------------------------------
# EC2 instance role
# ------------------------------------------------------------------------------

resource "aws_iam_role" "instance_role" {
  count       = var.create_ec2_instance_role ? 1 : 0
  name        = var.ec2_instance_role_name
  description = "IAM role that EC2 instances can assume"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowEC2ToAssumeRole"
        Action    = "sts:AssumeRole"
        Effect    = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })
  tags = {
    role_created_by = "terraform"
  }
}

resource "aws_iam_role_policy_attachment" "instance_role_iam_read_only" {
  count      = var.create_ec2_instance_role ? 1 : 0
  role       = aws_iam_role.instance_role[0].name
  policy_arn = local.iam_read_only_access_policy_arn
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name = "multi-cluster-networking"
  azs  = slice(data.aws_availability_zones.available.names, 0, 3)

  private_subnets = [
    cidrsubnet("10.0.0.0/16", 4, 0),
    cidrsubnet("10.0.0.0/16", 4, 1),
    cidrsubnet("10.0.0.0/16", 4, 2),
  ]

  public_subnets = [
    cidrsubnet("10.0.0.0/16", 8, 48),
    cidrsubnet("10.0.0.0/16", 8, 49),
    cidrsubnet("10.0.0.0/16", 8, 50),
  ]
}

module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "~> 5.0"

  name = local.name
  cidr = "10.0.0.0/16"

  azs             = local.azs
  private_subnets = local.private_subnets
  public_subnets  = local.public_subnets

  enable_nat_gateway = true
  single_nat_gateway = true
  enable_vpn_gateway = false

  public_subnet_tags = {
    "kubernetes.io/role/elb" = 1
  }

  private_subnet_tags = {
    "kubernetes.io/role/internal-elb" = 1
  }

  tags = {
    Blueprint  = local.name
    GithubRepo = "github.com/aws-ia/terraform-aws-eks-blueprints"
  }
}

resource "aws_security_group" "cluster1_additional_sg" {
  name        = "cluster1_additional_sg"
  description = "Security group for cluster1 cross-cluster communication"
  vpc_id      = module.vpc.vpc_id

  tags = {
    Blueprint  = local.name
    GithubRepo = "github.com/aws-ia/terraform-aws-eks-blueprints"
  }
}

resource "aws_security_group" "cluster2_additional_sg" {
  name        = "cluster2_additional_sg"
  description = "Security group for cluster2 cross-cluster communication"
  vpc_id      = module.vpc.vpc_id

  tags = {
    Blueprint  = local.name
    GithubRepo = "github.com/aws-ia/terraform-aws-eks-blueprints"
  }
}

# Cluster1: Ingress from cluster2
resource "aws_security_group_rule" "cluster1_ingress_from_cluster2" {
  type                     = "ingress"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  source_security_group_id = aws_security_group.cluster2_additional_sg.id
  security_group_id        = aws_security_group.cluster1_additional_sg.id
  description              = "Allow all traffic from cluster2"
}

# Cluster1: Egress to cluster2
resource "aws_security_group_rule" "cluster1_egress_to_cluster2" {
  type                     = "egress"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  source_security_group_id = aws_security_group.cluster2_additional_sg.id
  security_group_id        = aws_security_group.cluster1_additional_sg.id
  description              = "Allow all traffic to cluster2"
}

# Cluster2: Ingress from cluster1
resource "aws_security_group_rule" "cluster2_ingress_from_cluster1" {
  type                     = "ingress"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  source_security_group_id = aws_security_group.cluster1_additional_sg.id
  security_group_id        = aws_security_group.cluster2_additional_sg.id
  description              = "Allow all traffic from cluster1"
}

# Cluster2: Egress to cluster1
resource "aws_security_group_rule" "cluster2_egress_to_cluster1" {
  type                     = "egress"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  source_security_group_id = aws_security_group.cluster1_additional_sg.id
  security_group_id        = aws_security_group.cluster2_additional_sg.id
  description              = "Allow all traffic to cluster1"
}

# --------------------------------------------------------------------------
# Cognito User Pool — variables
# --------------------------------------------------------------------------

variable "pool_name" {
  description = "Name of the Cognito User Pool"
  type        = string
  default     = "Pool name"
}

variable "alias_attributes" {
  description = "Attributes that can be used as an alias for the user"
  type        = list(string)
  default     = ["email", "phone_number"]
}

variable "auto_verified_attributes" {
  description = "Attributes that are automatically verified"
  type        = list(string)
  default     = []
}

variable "email_verification_message" {
  description = "Email verification message template (use {####} for the code)"
  type        = string
  default     = "Some message {####}"
}

variable "email_verification_subject" {
  description = "Subject line for the email verification message"
  type        = string
  default     = "Some subject"
}

variable "mfa_configuration" {
  description = "MFA configuration: ON, OFF, or OPTIONAL"
  type        = string
  default     = "OPTIONAL"
}

variable "sms_authentication_message" {
  description = "SMS message template for authentication (use {####} for the code)"
  type        = string
  default     = "SMS authentication message {####}"
}

variable "sms_verification_message" {
  description = "SMS message template for verification (use {####} for the code)"
  type        = string
  default     = "SMS verification message {####}"
}

# --------------------------------------------------------------------------
# Verification message template by link
# --------------------------------------------------------------------------
variable "verification_default_email_option" {
  description = "Default email option (CONFIRM_WITH_LINK or CONFIRM_WITH_CODE)"
  type        = string
  default     = null
}

variable "verification_email_message_by_link" {
  description = "Email message template for link‑based verification"
  type        = string
  default     = null
}

variable "verification_email_subject_by_link" {
  description = "Email subject for link‑based verification"
  type        = string
  default     = null
}

# --------------------------------------------------------------------------
# SMS configuration  (conditionally provisioned when both are non‑empty)
# --------------------------------------------------------------------------
variable "sms_external_id" {
  description = "External ID for SMS configuration"
  type        = string
  default     = ""
}

variable "sms_sns_caller_arn" {
  description = "SNS caller ARN for SMS configuration"
  type        = string
  default     = ""
}

# --------------------------------------------------------------------------
# Recovery mechanisms  (inside account_recovery_setting)
# --------------------------------------------------------------------------
variable "recovery_mechanisms" {
  description = "List of recovery mechanisms with name and priority"
  type        = any
  default = [
    { name = "verified_email", priority = 2 },
    { name = "verified_phone_number", priority = 1 }
  ]
}

# --------------------------------------------------------------------------
# Invite message templates  (inside admin_create_user_config)
# --------------------------------------------------------------------------
variable "invite_email_message" {
  description = "Email message template for user invitations"
  type        = string
  default     = null
}

variable "invite_email_subject" {
  description = "Email subject for user invitations"
  type        = string
  default     = null
}

variable "invite_sms_message" {
  description = "SMS message template for user invitations"
  type        = string
  default     = null
}

# --------------------------------------------------------------------------
# General user pool settings
# --------------------------------------------------------------------------
variable "allow_admin_create_user_only" {
  description = "Only allow administrators to create users"
  type        = bool
  default     = false
}

variable "software_token_mfa_enabled" {
  description = "Enable software‑based TOTP MFA"
  type        = bool
  default     = true
}

variable "username_case_sensitive" {
  description = "Case‑sensitive usernames (null = do not set)"
  type        = bool
  default     = null
}

variable "device_challenge_required_on_new_device" {
  description = "Require challenge on a new device (null = do not set)"
  type        = bool
  default     = null
}

variable "device_only_remembered_on_user_prompt" {
  description = "Only remember device when user prompts (null = do not set)"
  type        = bool
  default     = null
}

# --------------------------------------------------------------------------
# Lambda triggers  (map of trigger‑name → ARN for simple triggers)
# --------------------------------------------------------------------------
variable "lambda_triggers" {
  description = "Map of Lambda trigger names to function ARNs (simple triggers)"
  type        = map(string)
  default     = {}
}

variable "lambda_custom_email_sender_arn" {
  description = "ARN of the custom email sender Lambda (leave empty to skip)"
  type        = string
  default     = ""
}

variable "lambda_custom_email_sender_version" {
  description = "Version string of the custom email sender Lambda"
  type        = string
  default     = ""
}

variable "lambda_custom_sms_sender_arn" {
  description = "ARN of the custom SMS sender Lambda (leave empty to skip)"
  type        = string
  default     = ""
}

variable "lambda_custom_sms_sender_version" {
  description = "Version string of the custom SMS sender Lambda"
  type        = string
  default     = ""
}

variable "lambda_pre_token_generation_arn" {
  description = "ARN of the pre‑token‑generation Lambda (leave empty to skip)"
  type        = string
  default     = ""
}

variable "lambda_pre_token_generation_version" {
  description = "Version string of the pre‑token‑generation Lambda"
  type        = string
  default     = ""
}

# --------------------------------------------------------------------------
# Custom schema definitions (list of attribute maps)
# --------------------------------------------------------------------------
variable "custom_schema" {
  description = "List of schema attribute definitions"
  type        = any
  default = [
    {
      name                = "email"
      attribute_data_type = "String"
      mutable             = true
      required            = true
    }
  ]
}

# ==========================================================================
# CLIENT configuration
# ==========================================================================

variable "client_app_names" {
  description = "List of client application names (empty = no clients)"
  type        = list(string)
  default     = []
}

variable "client_generate_secret" {
  description = "Generate a client secret for each app client"
  type        = bool
  default     = false
}

variable "client_access_token_validity" {
  description = "Access token validity (number, combined with the unit below)"
  type        = number
  default     = 120
}

variable "client_id_token_validity" {
  description = "ID token validity (number, combined with the unit below)"
  type        = number
  default     = 120
}

variable "client_refresh_token_validity" {
  description = "Refresh token validity (number, combined with the unit below)"
  type        = number
  default     = 7
}

variable "client_access_token_validity_unit" {
  description = "Unit for access token validity (seconds, minutes, hours, days)"
  type        = string
  default     = "minutes"
}

variable "client_id_token_validity_unit" {
  description = "Unit for ID token validity"
  type        = string
  default     = "minutes"
}

variable "client_refresh_token_validity_unit" {
  description = "Unit for refresh token validity"
  type        = string
  default     = "days"
}

variable "client_allowed_oauth_flows_user_pool_client" {
  description = "Allow OAuth flows only for user pool clients"
  type        = bool
  default     = false
}

variable "client_enable_token_revocation" {
  description = "Enable token revocation for clients"
  type        = bool
  default     = true
}

variable "client_explicit_auth_flows" {
  description = "Explicit authentication flows"
  type        = list(string)
  default     = ["ALLOW_REFRESH_TOKEN_AUTH", "ALLOW_USER_PASSWORD_AUTH", "ALLOW_USER_SRP_AUTH"]
}

variable "client_prevent_user_existence_errors" {
  description = "Setting for prevent‑user‑existence errors"
  type        = string
  default     = "LEGACY"
}

variable "client_read_attributes" {
  description = "Read‑accessible attributes (null = defaults)"
  type        = list(string)
  default     = null
}

variable "client_write_attributes" {
  description = "Write‑accessible attributes (null = defaults)"
  type        = list(string)
  default     = null
}

variable "client_callback_urls" {
  description = "Callback URLs (null = defaults)"
  type        = list(string)
  default     = null
}

variable "client_logout_urls" {
  description = "Logout URLs (null = defaults)"
  type        = list(string)
  default     = null
}

variable "client_oauth_flows" {
  description = "Allowed OAuth flows (null = use explicit auth flows)"
  type        = list(string)
  default     = null
}

variable "client_oauth_scopes" {
  description = "Allowed OAuth scopes (null = defaults)"
  type        = list(string)
  default     = null
}

variable "client_supported_identity_providers" {
  description = "Supported identity providers (null = defaults)"
  type        = list(string)
  default     = null
}

# ==========================================================================
# Group configuration
# ==========================================================================

variable "group_name" {
  description = "Cognito user group name (leave empty to skip)"
  type        = string
  default     = ""
}

variable "group_precedence" {
  description = "Precedence of the group"
  type        = number
  default     = 0
}

variable "group_role_arn" {
  description = "ARN of the IAM role for the group (leave empty to skip)"
  type        = string
  default     = ""
}

# ==========================================================================
# Domain configuration
# ==========================================================================

variable "domain_name" {
  description = "Cognito user pool domain (leave empty to skip)"
  type        = string
  default     = ""
}

variable "domain_certificate_arn" {
  description = "ARN of the ACM certificate for the domain"
  type        = string
  default     = ""
}

# ==========================================================================
# Route53 record configuration
# ==========================================================================

variable "create_route53_record" {
  description = "Create a Route53 A‑record alias to the CloudFront distribution"
  type        = bool
  default     = false
}

variable "route53_zone_id" {
  description = "Route53 zone ID (required when create_route53_record is true)"
  type        = string
  default     = ""
}

# ==========================================================================
# Locals
# ==========================================================================

locals {
  sms_config_enabled  = length(trimspace(var.sms_external_id)) > 0 && length(trimspace(var.sms_sns_caller_arn)) > 0
  domain_enabled      = length(trimspace(var.domain_name)) > 0
  group_enabled       = length(trimspace(var.group_name)) > 0
  route53_enabled     = var.create_route53_record && length(trimspace(var.route53_zone_id)) > 0 && local.domain_enabled

  verification_template_vm = var.verification_default_email_option != null || var.verification_email_message_by_link != null || var.verification_email_subject_by_link != null
  invite_template_vm       = var.invite_email_message != null || var.invite_email_subject != null || var.invite_sms_message != null
  device_config_vm         = var.device_challenge_required_on_new_device != null || var.device_only_remembered_on_user_prompt != null
  username_config_vm       = var.username_case_sensitive != null

  custom_email_sender_vm   = length(trimspace(var.lambda_custom_email_sender_arn)) > 0
  custom_sms_sender_vm     = length(trimspace(var.lambda_custom_sms_sender_arn)) > 0
  pre_token_gen_vm         = length(trimspace(var.lambda_pre_token_generation_arn)) > 0

  # Convert lists to maps for dynamic iteration
  recovery_mechanisms_map  = { for idx, val in var.recovery_mechanisms : idx => val }
  custom_schema_map        = { for idx, val in var.custom_schema : idx => val }

  # Token validity unit strings
  access_token_validity_str  = "${var.client_access_token_validity} ${var.client_access_token_validity_unit}"
  id_token_validity_str      = "${var.client_id_token_validity} ${var.client_id_token_validity_unit}"
  refresh_token_validity_str = "${var.client_refresh_token_validity} ${var.client_refresh_token_validity_unit}"
}

# ==========================================================================
# Cognito User Pool
# ==========================================================================

resource "aws_cognito_user_pool" "this" {
  name = var.pool_name

  alias_attributes         = var.alias_attributes
  auto_verified_attributes = var.auto_verified_attributes
  mfa_configuration        = var.mfa_configuration

  email_verification_message = var.email_verification_message
  email_verification_subject = var.email_verification_subject
  sms_authentication_message = var.sms_authentication_message
  sms_verification_message   = var.sms_verification_message

  # ---- Verification message template (by link) ----
  dynamic "verification_message_template" {
    for_each = local.verification_template_vm ? { "1" = "1" } : {}
    content {
      default_email_option   = var.verification_default_email_option
      email_message_by_link  = var.verification_email_message_by_link
      email_subject_by_link  = var.verification_email_subject_by_link
    }
  }

  # ---- SMS configuration (conditional) ----
  dynamic "sms_configuration" {
    for_each = local.sms_config_enabled ? { "1" = "1" } : {}
    content {
      external_id    = var.sms_external_id
      sns_caller_arn = var.sms_sns_caller_arn
    }
  }

  # ---- Account recovery setting ----
  account_recovery_setting {
    dynamic "recovery_mechanism" {
      for_each = local.recovery_mechanisms_map
      content {
        name     = recovery_mechanism.value["name"]
        priority = recovery_mechanism.value["priority"]
      }
    }
  }

  # ---- Admin create user config (invite templates) ----
  dynamic "admin_create_user_config" {
    for_each = local.invite_template_vm || var.allow_admin_create_user_only != false ? { "1" = "1" } : {}
    content {
      allow_admin_create_user_only = var.allow_admin_create_user_only

      dynamic "invite_message_template" {
        for_each = local.invite_template_vm ? { "1" = "1" } : {}
        content {
          email_message = var.invite_email_message
          email_subject = var.invite_email_subject
          sms_message   = var.invite_sms_message
        }
      }
    }
  }

  # ---- Software token MFA configuration ----
  software_token_mfa_configuration {
    enabled = var.software_token_mfa_enabled
  }

  # ---- Username configuration (case sensitivity) ----
  dynamic "username_configuration" {
    for_each = local.username_config_vm ? { "1" = "1" } : {}
    content {
      case_sensitive = var.username_case_sensitive
    }
  }

  # ---- Device configuration (conditional) ----
  dynamic "device_configuration" {
    for_each = local.device_config_vm ? { "1" = "1" } : {}
    content {
      challenge_required_on_new_device     = var.device_challenge_required_on_new_device
      device_only_remembered_on_user_prompt = var.device_only_remembered_on_user_prompt
    }
  }

  # ---- Lambda configuration ----
  dynamic "lambda_config" {
    for_each = length(var.lambda_triggers) > 0 || local.custom_email_sender_vm || local.custom_sms_sender_vm || local.pre_token_gen_vm ? { "1" = "1" } : {}
    content {
      create_auth_challenge          = lookup(var.lambda_triggers, "create_auth_challenge", null)
      custom_message                 = lookup(var.lambda_triggers, "custom_message", null)
      define_auth_challenge          = lookup(var.lambda_triggers, "define_auth_challenge", null)
      kms_key_id                     = lookup(var.lambda_triggers, "kms_key_id", null)
      post_authentication            = lookup(var.lambda_triggers, "post_authentication", null)
      post_confirmation              = lookup(var.lambda_triggers, "post_confirmation", null)
      pre_authentication             = lookup(var.lambda_triggers, "pre_authentication", null)
      pre_sign_up                    = lookup(var.lambda_triggers, "pre_sign_up", null)
      pre_token_generation           = lookup(var.lambda_triggers, "pre_token_generation", null)
      user_migration                 = lookup(var.lambda_triggers, "user_migration", null)
      verify_auth_challenge_response = lookup(var.lambda_triggers, "verify_auth_challenge_response", null)

      # Custom email sender (nested block)
      dynamic "custom_email_sender" {
        for_each = local.custom_email_sender_vm ? { "1" = "1" } : {}
        content {
          lambda_arn     = var.lambda_custom_email_sender_arn
          lambda_version = length(trimspace(var.lambda_custom_email_sender_version)) > 0 ? var.lambda_custom_email_sender_version : null
        }
      }

      # Custom SMS sender (nested block)
      dynamic "custom_sms_sender" {
        for_each = local.custom_sms_sender_vm ? { "1" = "1" } : {}
        content {
          lambda_arn     = var.lambda_custom_sms_sender_arn
          lambda_version = length(trimspace(var.lambda_custom_sms_sender_version)) > 0 ? var.lambda_custom_sms_sender_version : null
        }
      }

      # Pre‑token‑generation config (nested block)
      dynamic "pre_token_generation_config" {
        for_each = local.pre_token_gen_vm ? { "1" = "1" } : {}
        content {
          lambda_arn     = var.lambda_pre_token_generation_arn
          lambda_version = length(trimspace(var.lambda_pre_token_generation_version)) > 0 ? var.lambda_pre_token_generation_version : null
        }
      }
    }
  }

  # ---- Schema definitions ----
  dynamic "schema" {
    for_each = local.custom_schema_map
    content {
      name                = schema.value["name"]
      attribute_data_type = try(schema.value["attribute_data_type"], null)
      developer_only_attribute = try(schema.value["developer_only_attribute"], null)
      mutable             = try(schema.value["mutable"], null)
      required            = try(schema.value["required"], null)

      string_attribute_constraints {
        min_length = try(schema.value["string_attribute_constraints"]["min_length"], null)
        max_length = try(schema.value["string_attribute_constraints"]["max_length"], null)
      }

      number_attribute_constraints {
        min_value = try(schema.value["number_attribute_constraints"]["min_value"], null)
        max_value = try(schema.value["number_attribute_constraints"]["max_value"], null)
      }
    }
  }

  # Ignore changes to estimated_number_of_users
  lifecycle {
    ignore_changes = [estimated_number_of_users]
  }
}

# ==========================================================================
# Cognito User Pool Clients
# ==========================================================================

resource "aws_cognito_user_pool_client" "this" {
  for_each = toset(var.client_app_names)

  name         = each.key
  user_pool_id = aws_cognito_user_pool.this.id

  generate_secret = var.client_generate_secret

  explicit_auth_flows                  = var.client_explicit_auth_flows
  allowed_oauth_flows_user_pool_client = var.client_allowed_oauth_flows_user_pool_client
  enable_token_revocation              = var.client_enable_token_revocation
  prevent_user_existence_errors        = var.client_prevent_user_existence_errors

  read_attributes              = var.client_read_attributes
  write_attributes             = var.client_write_attributes
  callback_urls                = var.client_callback_urls
  logout_urls                  = var.client_logout_urls
  allowed_oauth_flows          = var.client_oauth_flows
  allowed_oauth_scopes         = var.client_oauth_scopes
  supported_identity_providers = var.client_supported_identity_providers

  # Token validity units (combines value + unit)
  token_validity_units {
    access_token  = local.access_token_validity_str
    id_token      = local.id_token_validity_str
    refresh_token = local.refresh_token_validity_str
  }
}

# ==========================================================================
# Cognito User Group  (conditional)
# ==========================================================================

resource "aws_cognito_user_group" "this" {
  count = local.group_enabled ? 1 : 0

  user_pool_id = aws_cognito_user_pool.this.id
  name         = var.group_name
  precedence   = var.group_precedence

  role_arn = length(trimspace(var.group_role_arn)) > 0 ? var.group_role_arn : null
}

# ==========================================================================
# Cognito User Pool Domain  (conditional)
# ==========================================================================

resource "aws_cognito_user_pool_domain" "this" {
  count = local.domain_enabled ? 1 : 0

  domain       = var.domain_name
  user_pool_id = aws_cognito_user_pool.this.id

  certificate_arn = length(trimspace(var.domain_certificate_arn)) > 0 ? var.domain_certificate_arn : null
}

# ==========================================================================
# Route53 A‑record Alias  (conditional)
# ==========================================================================

resource "aws_route53_record" "cognito_domain" {
  count = local.route53_enabled ? 1 : 0

  zone_id = var.route53_zone_id
  name    = var.domain_name
  type    = "A"

  alias {
    zone_id                = "Z2FDTNDATAQYW2"
    name                   = aws_cognito_user_pool_domain.this[0].cloudfront_distribution
    evaluate_target_health = false
  }
}

variable "vpc_cidr" {
  description = "VPC CIDR block"
  default     = "10.0.0.0/16"
}

variable "vpc_name" {
  description = "VPC name"
  default     = "DevOps-Project-VPC"
}

variable "igw_name" {
  description = "Internet Gateway name"
  default     = "devops-project-igw"
}

variable "route_table_name" {
  description = "Route table name"
  default     = "DevOps-project-RT"
}

variable "subnet_a_name" {
  description = "Public subnet identifier name"
  default     = "subnet_a"
}

variable "nat_gw_name" {
  description = "NAT Gateway name"
  default     = "DevOps-NAT-GW"
}

variable "public_ipv4_pool" {
  description = "Public IPv4 pool name"
  default     = "amazon"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = var.vpc_name
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = var.igw_name
  }
}

resource "aws_subnet" "subnet_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false
  tags = {
    Name       = "Subnet-A-Public"
    Identifier = var.subnet_a_name
  }
}

resource "aws_subnet" "subnet_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false
  tags = {
    Name = "Subnet-B-Private"
  }
}

resource "aws_subnet" "subnet_c" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.3.0/24"
  availability_zone       = data.aws_availability_zones.available.names[2]
  map_public_ip_on_launch = false
  tags = {
    Name = "Subnet-C-Private"
  }
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = var.route_table_name
  }
}

resource "aws_route" "default_route" {
  route_table_id         = aws_route_table.main.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "subnet_a" {
  subnet_id      = aws_subnet.subnet_a.id
  route_table_id = aws_route_table.main.id
}

resource "aws_eip" "nat" {
  domain           = "vpc"
  public_ipv4_pool = var.public_ipv4_pool
  tags = {
    Name = var.nat_gw_name
  }
  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  subnet_id         = aws_subnet.subnet_b.id
  connectivity_type = "public"
  allocation_id     = aws_eip.nat.id
  tags = {
    Name = var.nat_gw_name
  }
  depends_on = [aws_internet_gateway.main]
}

resource "aws_security_group" "default" {
  name        = "DefaultSecurityGroup"
  description = "Default security group permitting outbound egress traffic within VPC CIDR"
  vpc_id      = aws_vpc.main.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "DefaultSecurityGroup"
  }
}

output "nat_gateway_public_ip" {
  value       = aws_nat_gateway.main.public_ip
  description = "Public IP address of the NAT Gateway"
}

variable "vault_name" {
  description = "Name of the backup vault"
  type        = string
  default     = "my-backup-vault"
}

variable "vault_tags" {
  description = "Optional tags to apply to the backup vault"
  type        = map(string)
  default     = {}
}

variable "backup_tag_key" {
  description = "Tag key used for backup selection matching"
  type        = string
  default     = "backup"
}

variable "daily_schedule" {
  description = "Cron schedule for the daily backup plan"
  type        = string
  default     = "cron(0 12 ? * * *)"
}

variable "weekly_schedule" {
  description = "Cron schedule for the weekly backup plan"
  type        = string
  default     = "cron(0 12 ? * 1 *)"
}

variable "monthly_schedule" {
  description = "Cron schedule for the monthly backup plan"
  type        = string
  default     = "cron(0 12 1 * ? *)"
}

variable "daily_deletion_days" {
  description = "Number of days after which daily backups are deleted"
  type        = number
  default     = 7
}

variable "weekly_deletion_days" {
  description = "Number of days after which weekly backups are deleted"
  type        = number
  default     = 31
}

variable "monthly_deletion_days" {
  description = "Number of days after which monthly backups are deleted"
  type        = number
  default     = 366
}

variable "daily_continuous_backup" {
  description = "Enable continuous backup for the daily rule"
  type        = bool
  default     = false
}

variable "enable_notifications" {
  description = "Whether to enable backup vault notifications"
  type        = bool
  default     = false
}

variable "sns_topic_arn" {
  description = "ARN of the SNS topic for backup notifications"
  type        = string
  default     = ""
}

variable "notification_events" {
  description = "List of backup events to send notifications for"
  type        = list(string)
  default = [
    "BACKUP_JOB_FAILED",
    "RESTORE_JOB_FAILED",
    "COPY_JOB_FAILED",
    "S3_BACKUP_OBJECT_FAILED",
    "S3_RESTORE_OBJECT_FAILED",
  ]
}

locals {
  plan_name_daily   = "${var.vault_name}-daily"
  plan_name_weekly  = "${var.vault_name}-weekly"
  plan_name_monthly = "${var.vault_name}-monthly"
}

# KMS key for backup vault encryption with automatic rotation
resource "aws_kms_key" "backup" {
  description             = "KMS key for AWS Backup vault ${var.vault_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_kms_alias" "backup" {
  name          = "alias/${var.vault_name}"
  target_key_id = aws_kms_key.backup.id
}

# Backup vault
resource "aws_backup_vault" "main" {
  name        = var.vault_name
  kms_key_arn = aws_kms_key.backup.arn
  tags        = var.vault_tags
}

# IAM role for AWS Backup
resource "aws_iam_role" "backup" {
  name               = "${var.vault_name}-backup-role"
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role.json
}

data "aws_iam_policy_document" "backup_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_iam_role_policy_attachment" "backup" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

# Daily backup plan
resource "aws_backup_plan" "daily" {
  name = local.plan_name_daily

  rule {
    rule_name                = "daily_backup_rule"
    target_vault_name        = aws_backup_vault.main.name
    schedule                 = var.daily_schedule
    enable_continuous_backup = var.daily_continuous_backup

    lifecycle {
      delete_after = var.daily_deletion_days
    }
  }

  advanced_backup_setting {
    backup_options = {
      WindowsVSS = "enabled"
    }
    resource_type = "EC2"
  }

  depends_on = [aws_iam_role_policy_attachment.backup]
}

# Weekly backup plan
resource "aws_backup_plan" "weekly" {
  name = local.plan_name_weekly

  rule {
    rule_name         = "weekly_backup_rule"
    target_vault_name = aws_backup_vault.main.name
    schedule          = var.weekly_schedule

    lifecycle {
      delete_after = var.weekly_deletion_days
    }
  }

  advanced_backup_setting {
    backup_options = {
      WindowsVSS = "enabled"
    }
    resource_type = "EC2"
  }

  depends_on = [aws_iam_role_policy_attachment.backup]
}

# Monthly backup plan
resource "aws_backup_plan" "monthly" {
  name = local.plan_name_monthly

  rule {
    rule_name         = "monthly_backup_rule"
    target_vault_name = aws_backup_vault.main.name
    schedule          = var.monthly_schedule

    lifecycle {
      delete_after = var.monthly_deletion_days
    }
  }

  advanced_backup_setting {
    backup_options = {
      WindowsVSS = "enabled"
    }
    resource_type = "EC2"
  }

  depends_on = [aws_iam_role_policy_attachment.backup]
}

# Daily backup selection
resource "aws_backup_selection" "daily" {
  name         = "daily_backup_selection"
  plan_id      = aws_backup_plan.daily.id
  iam_role_arn = aws_iam_role.backup.arn

  selection_tag {
    type  = "STRINGEQUALS"
    key   = var.backup_tag_key
    value = "daily"
  }

  resources = ["*"]
}

# Weekly backup selection
resource "aws_backup_selection" "weekly" {
  name         = "weekly_backup_selection"
  plan_id      = aws_backup_plan.weekly.id
  iam_role_arn = aws_iam_role.backup.arn

  selection_tag {
    type  = "STRINGEQUALS"
    key   = var.backup_tag_key
    value = "weekly"
  }

  resources = ["*"]
}

# Monthly backup selection
resource "aws_backup_selection" "monthly" {
  name         = "monthly_backup_selection"
  plan_id      = aws_backup_plan.monthly.id
  iam_role_arn = aws_iam_role.backup.arn

  selection_tag {
    type  = "STRINGEQUALS"
    key   = var.backup_tag_key
    value = "monthly"
  }

  resources = ["*"]
}

# Conditional backup vault notifications
resource "aws_backup_vault_notifications" "main" {
  count = var.enable_notifications ? 1 : 0

  backup_vault_name   = aws_backup_vault.main.name
  sns_topic_arn       = var.sns_topic_arn
  backup_vault_events = var.notification_events
}

variable "aws_region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "env" {
  description = "Environment tag value"
  type        = string
  default     = "test"
}

variable "vpc_cidr" {
  description = "VPC CIDR block"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "Public subnet CIDR blocks"
  type        = list(string)
  default     = ["10.0.10.0/24", "10.0.11.0/24"]
}

variable "private_subnet_cidrs" {
  description = "Private subnet CIDR blocks"
  type        = list(string)
  default     = ["10.0.20.0/24", "10.0.21.0/24"]
}

variable "common_tags" {
  description = "Common tags to apply to all resources"
  type        = map(string)
  default = {
    Owner   = "Valerii Vasianovych"
    Project = "Terraform AWS"
  }
}

locals {
  aws_region = data.aws_region.current.region
  azs        = data.aws_availability_zones.available.names
}

# Data sources
data "aws_region" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.common_tags, {
    Name   = "${var.env}-vpc"
    Region = local.aws_region
  })
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.common_tags, {
    Name = "${var.env}-igw"
  })
}

# Public Subnets
resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index % length(local.azs)]
  map_public_ip_on_launch = false

  tags = merge(var.common_tags, {
    Name = "${var.env}-public-subnet-${count.index}"
  })
}

# Private Subnets
resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index % length(local.azs)]
  map_public_ip_on_launch = false

  tags = merge(var.common_tags, {
    Name = "${var.env}-private-subnet-${count.index}"
  })
}

# Elastic IPs for NAT Gateways
resource "aws_eip" "nat" {
  count = length(var.private_subnet_cidrs)

  domain = "vpc"

  tags = merge(var.common_tags, {
    Name = "${var.env}-nat-eip-${count.index}"
  })
}

# NAT Gateways
resource "aws_nat_gateway" "main" {
  count = length(var.private_subnet_cidrs)

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(var.common_tags, {
    Name = "${var.env}-nat-gw-${count.index}"
  })
}

# Public Route Table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.common_tags, {
    Name = "${var.env}-route-public-subnets"
  })
}

# Public Route to IGW
resource "aws_route" "public" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

# Private Route Tables
resource "aws_route_table" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id = aws_vpc.main.id

  tags = merge(var.common_tags, {
    Name = "${var.env}-route-private-subnets-${count.index}"
  })
}

# Private Routes to NAT Gateways
resource "aws_route" "private" {
  count = length(var.private_subnet_cidrs)

  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main[count.index].id
}

# Public Route Table Associations
resource "aws_route_table_association" "public" {
  count = length(var.public_subnet_cidrs)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Private Route Table Associations
resource "aws_route_table_association" "private" {
  count = length(var.private_subnet_cidrs)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

variable "create_eks" {
  description = "Whether to create the EKS cluster"
  type        = bool
  default     = false
}

variable "cluster_name" {
  description = "Name of the EKS cluster"
  type        = string
  default     = ""
}

variable "cluster_version" {
  description = "Kubernetes version for the EKS cluster"
  type        = string
  default     = null
}

variable "authentication_mode" {
  description = "Authentication mode for the EKS cluster"
  type        = string
  default     = "API_AND_CONFIG_MAP"
}

variable "subnet_ids" {
  description = "List of subnet IDs for the EKS cluster"
  type        = list(string)
  default     = []
}

variable "control_plane_subnet_ids" {
  description = "List of control plane subnet IDs for the EKS cluster (preferred if populated)"
  type        = list(string)
  default     = []
}

# IAM role assumed by the EKS service principal
resource "aws_iam_role" "eks_cluster" {
  name = "eks-cluster"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Attach the AmazonEKSClusterPolicy managed policy
resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.eks_cluster.name
}

# Attach the AmazonEKSVPCResourceController managed policy
resource "aws_iam_role_policy_attachment" "eks_vpc_resource_controller" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSVPCResourceController"
  role       = aws_iam_role.eks_cluster.name
}

# Dynamically select subnets: prefer control_plane_subnet_ids, fall back to subnet_ids
locals {
  cluster_subnet_ids = length(var.control_plane_subnet_ids) > 0 ? var.control_plane_subnet_ids : var.subnet_ids
}

# Conditionally created EKS cluster
resource "aws_eks_cluster" "this" {
  count = var.create_eks ? 1 : 0

  name     = var.cluster_name
  version  = var.cluster_version
  role_arn = aws_iam_role.eks_cluster.arn

  vpc_config {
    subnet_ids = local.cluster_subnet_ids
  }

  access_config {
    authentication_mode                         = var.authentication_mode
    bootstrap_cluster_creator_admin_permissions = true
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_iam_role_policy_attachment.eks_vpc_resource_controller,
  ]
}

data "aws_caller_identity" "current" {}

locals {
  base_name = "rwwise.dev"
  users = {
    Dev  = "DevUser-${local.base_name}"
    Test = "TestUser-${local.base_name}"
    Prod = "ProdUser-${local.base_name}"
  }
}

resource "aws_iam_user" "this" {
  for_each = local.users

  name = each.value
  path = "/system/"

  tags = {
    Name       = "${local.base_name} Infrastructure Setup"
    Repository = "https://github.com/zangrum/setup.inf.rwwise.dev"
    AccountID  = data.aws_caller_identity.current.account_id
    UserID     = data.aws_caller_identity.current.user_id
  }
}

resource "aws_iam_access_key" "this" {
  for_each = local.users

  user = aws_iam_user.this[each.key].name
}

resource "aws_iam_user_policy" "this" {
  for_each = {
    Dev  = "dev_cicd_user_policy"
    Test = "test_cicd_user_policy"
    Prod = "prod_cicd_user_policy"
  }

  name   = each.value
  user   = aws_iam_user.this[each.key].name
  policy = data.aws_iam_policy_document.combined.json
}

data "aws_iam_policy_document" "combined" {
  statement {
    sid    = "ReadOnlyListAccess"
    effect = "Allow"
    actions = [
      "codebuild:BatchGet*",
      "codebuild:List*",
      "codecommit:Get*",
      "codecommit:List*",
      "codecommit:BatchGet*",
      "codecommit:GitPull",
      "cloudwatch:Get*",
      "cloudwatch:List*",
      "cloudwatch:Describe*",
      "events:Describe*",
      "events:List*",
      "events:Get*",
      "logs:Describe*",
      "logs:Get*",
      "logs:List*",
      "logs:FilterLogEvents",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CodeStarConnectionsUserAccess"
    effect = "Allow"
    actions = [
      "codestar-connections:GetConnection",
      "codestar-connections:ListConnections",
      "codestar-connections:PassConnection",
    ]
    resources = [
      "arn:aws:codestar-connections:*:*:connection/*"
    ]
  }

  statement {
    sid    = "CodeStarNotificationsPowerUserAccess"
    effect = "Allow"
    actions = [
      "codestar-notifications:CreateNotificationRule",
      "codestar-notifications:DescribeNotificationRule",
      "codestar-notifications:UpdateNotificationRule",
      "codestar-notifications:TagResource",
      "codestar-notifications:UntagResource",
    ]
    resources = ["*"]

    condition {
      test     = "StringLike"
      variable = "codestar-notifications:NotificationsForResource"
      values   = ["arn:aws:codebuild:*"]
    }
  }

  statement {
    sid    = "CodeStarNotificationsListAccess"
    effect = "Allow"
    actions = [
      "codestar-notifications:ListNotificationRules",
      "codestar-notifications:ListEventTypes",
      "codestar-notifications:ListTargets",
    ]
    resources = ["*"]
  }
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------

variable "name" {
  description = "Module name; falls back to \"default\" if null or empty"
  type        = string
  default     = null
}

variable "tags" {
  description = "Tags to apply to all resources"
  type        = map(string)
  default     = {}
}

variable "bus_configuration" {
  description = "Configuration map for the event bus. Supports optional key `event_source_name`."
  type        = any
  default     = {}

  validation {
    condition     = var.bus_configuration != null
    error_message = "bus_configuration must not be null."
  }
}

variable "rules" {
  description = "List of rule objects. Each object must have a `name` key, and may optionally include `description`, `event_pattern`, and `schedule_expression`."
  type        = any
  default     = []

  validation {
    condition     = var.rules != null
    error_message = "rules must not be null."
  }
}

variable "targets" {
  description = "List of target objects. Each object must have `rule` and `arn` keys."
  type        = any
  default     = []

  validation {
    condition     = var.targets != null
    error_message = "targets must not be null."
  }
}

# ---------------------------------------------------------------------------
# Data sources
# ---------------------------------------------------------------------------

data "aws_partition" "current" {}

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------

locals {
  module_name = var.name != null && var.name != "" ? var.name : "default"
  bus_created = local.module_name != "default"

  # Convert the rules list to a map keyed by rule name for for_each use.
  rules_map = { for r in var.rules : r.name => r }

  # Convert the targets list to a map keyed by "rule:arn" for for_each use.
  targets_map = { for t in var.targets : "${t.rule}:${t.arn}" => t }
}

# ---------------------------------------------------------------------------
# EventBridge Event Bus (conditionally created)
# ---------------------------------------------------------------------------

resource "aws_cloudwatch_event_bus" "this" {
  count = local.bus_created ? 1 : 0

  name               = local.module_name
  event_source_name  = try(var.bus_configuration["event_source_name"], null)
  tags               = var.tags
}

# ---------------------------------------------------------------------------
# IAM Role and Policy
# ---------------------------------------------------------------------------

resource "aws_iam_role" "invoke" {
  name               = "${local.module_name}-invoke"
  assume_role_policy = data.aws_iam_policy_document.invoke_assume.json
  tags               = var.tags
}

data "aws_iam_policy_document" "invoke_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["events.${data.aws_partition.current.dns_suffix}"]
    }
  }
}

resource "aws_iam_role_policy" "invoke_targets" {
  name   = "${local.module_name}-invoke-targets"
  role   = aws_iam_role.invoke.name
  policy = data.aws_iam_policy_document.invoke_targets.json
}

data "aws_iam_policy_document" "invoke_targets" {
  statement {
    effect    = "Allow"
    actions   = ["lambda:InvokeFunction", "states:StartExecution"]
    resources = ["*"]
  }
}

# ---------------------------------------------------------------------------
# EventBridge Rules
# ---------------------------------------------------------------------------

resource "aws_cloudwatch_event_rule" "this" {
  for_each = local.rules_map

  name                = each.value.name
  description         = try(each.value.description, null)
  event_pattern       = try(each.value.event_pattern, null)
  schedule_expression = try(each.value.schedule_expression, null)
  event_bus_name      = local.bus_created ? aws_cloudwatch_event_bus.this[0].name : null
  tags                = var.tags
}

# ---------------------------------------------------------------------------
# EventBridge Targets
# ---------------------------------------------------------------------------

resource "aws_cloudwatch_event_target" "this" {
  for_each = local.targets_map

  rule           = each.value.rule
  arn            = each.value.arn
  event_bus_name = local.bus_created ? aws_cloudwatch_event_bus.this[0].name : null
  role_arn       = can(regex("stateMachine", each.value.arn)) ? aws_iam_role.invoke.arn : null

  depends_on = [aws_cloudwatch_event_rule.this]
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "module_name" {
  description = "Resolved module name"
  value       = local.module_name
}

output "event_bus_name" {
  description = "Name of the event bus (either custom or default)"
  value       = local.bus_created ? aws_cloudwatch_event_bus.this[0].name : "default"
}

output "event_bus_arn" {
  description = "ARN of the event bus"
  value       = local.bus_created ? aws_cloudwatch_event_bus.this[0].arn : null
}

output "invoke_role_arn" {
  description = "ARN of the IAM invoke role"
  value       = aws_iam_role.invoke.arn
}

output "rule_names" {
  description = "Map of rule names to rule ARNs"
  value       = { for k, r in aws_cloudwatch_event_rule.this : k => r.arn }
}

variable "name" {
  description = "Base name used for resource naming"
  type        = string
  default     = "default"
}

variable "kms_key_arn" {
  description = "Optional KMS key ARN for backup vault encryption"
  type        = string
  default     = null
}

variable "vault_policy" {
  description = "Optional JSON policy document for the backup vault access policy"
  type        = string
  default     = ""
}

variable "schedule" {
  description = "Cron expression for the backup schedule"
  type        = string
  default     = "cron(0 5 * * ? *)"
}

variable "start_window" {
  description = "Start window in minutes for the backup rule"
  type        = number
  default     = 60
}

variable "completion_window" {
  description = "Completion window in minutes for the backup rule"
  type        = number
  default     = 120
}

variable "destination_vault_map" {
  description = "Map of region to destination vault ARN for copy actions (e.g. { us-east-1 = \"arn:aws:backup:...:vault:...\" })"
  type        = map(string)
  default     = {}
}

variable "sns_topic_arn" {
  description = "Optional SNS topic ARN for backup event notifications"
  type        = string
  default     = ""
}

variable "selection_tag_key" {
  description = "Tag key used to select resources for backup"
  type        = string
  default     = "Backup"
}

variable "selection_tag_value" {
  description = "Tag value used to select resources for backup"
  type        = string
  default     = "true"
}

variable "selection_tag_operation" {
  description = "Tag operation type for resource selection (STRINGEQUALS, STRINGNOTEQUALS, etc.)"
  type        = string
  default     = "STRINGEQUALS"
}

locals {
  job_tag       = "${var.name}-backup"
  vault_name    = "vault-${var.name}-backup"
  plan_name     = "plan-${var.name}-backup"
  rule_name     = "rule-${var.name}-backup"
  selection_name = "selection-${var.name}-backup"
  iam_role_name = "aws-backup-${var.name}"
}

# ---------------------------------------------------------------------------
# IAM Role for Backup
# ---------------------------------------------------------------------------
resource "aws_iam_role" "backup" {
  name = local.iam_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Job = local.job_tag
  }
}

resource "aws_iam_role_policy_attachment" "backup" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

# ---------------------------------------------------------------------------
# Backup Vault
# ---------------------------------------------------------------------------
resource "aws_backup_vault" "main" {
  name        = local.vault_name
  kms_key_arn = var.kms_key_arn

  tags = {
    Job = local.job_tag
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Conditionally attach an access policy when vault_policy is non-empty
resource "aws_backup_vault_policy" "main" {
  count = var.vault_policy != "" ? 1 : 0

  backup_vault_name = aws_backup_vault.main.name
  policy            = var.vault_policy
}

# ---------------------------------------------------------------------------
# Backup Plan
# ---------------------------------------------------------------------------
resource "aws_backup_plan" "main" {
  name = local.plan_name

  rule {
    rule_name         = local.rule_name
    target_vault_name = aws_backup_vault.main.name
    schedule          = var.schedule
    start_window      = var.start_window
    completion_window = var.completion_window

    recovery_point_tags = {
      Job = local.job_tag
    }

    lifecycle {
      cold_storage_after = 30
      delete_after       = 120
    }

    dynamic "copy_action" {
      for_each = var.destination_vault_map
      content {
        destination_vault_arn = copy_action.value
      }
    }
  }

  tags = {
    Job = local.job_tag
  }
}

# ---------------------------------------------------------------------------
# Backup Selection
# ---------------------------------------------------------------------------
resource "aws_backup_selection" "main" {
  name         = local.selection_name
  iam_role_arn = aws_iam_role.backup.arn
  plan_id      = aws_backup_plan.main.id

  resources = ["*"]

  condition {}

  selection_tag {
    type  = var.selection_tag_operation
    key   = var.selection_tag_key
    value = var.selection_tag_value
  }
}

# ---------------------------------------------------------------------------
# Event Notifications (conditional on SNS topic ARN)
# ---------------------------------------------------------------------------
resource "aws_backup_vault_notifications" "main" {
  count = var.sns_topic_arn != "" ? 1 : 0

  backup_vault_name = aws_backup_vault.main.name
  sns_topic_arn     = var.sns_topic_arn
  backup_vault_events = [
    "BACKUP_JOB_FAILED",
    "COPY_JOB_FAILED",
  ]
}

variable "create" {
  description = "Whether to create a new Transit Gateway (true) or look up an existing one (false)"
  type        = bool
  default     = true

  validation {
    condition     = var.create || var.id != null || var.name != null
    error_message = "When create is false, either id or name must be provided."
  }
}

variable "id" {
  description = "ID of an existing Transit Gateway to use. Only used when create is false."
  type        = string
  default     = null
}

variable "name" {
  description = "Name tag of an existing Transit Gateway to use. Only used when create is false and id is not set."
  type        = string
  default     = null
}

variable "bgp_asn" {
  description = "BGP ASN for the Transit Gateway"
  type        = number
  default     = 65200
}

variable "auto_accept_shared_attachments" {
  description = "Whether to auto-accept shared attachments (enable or disable)"
  type        = string
  default     = null
}

variable "dns_support" {
  description = "DNS support for the Transit Gateway (enable or disable)"
  type        = string
  default     = "enable"
}

variable "vpn_ecmp_support" {
  description = "VPN ECMP support for the Transit Gateway (enable or disable)"
  type        = string
  default     = "enable"
}

variable "transit_gateway_cidr_blocks" {
  description = "List of CIDR blocks to attach to the Transit Gateway"
  type        = list(string)
  default     = []

  validation {
    condition = alltrue([
      for cidr in var.transit_gateway_cidr_blocks : can(cidrhost(cidr, 0))
    ])
    error_message = "All entries in transit_gateway_cidr_blocks must be valid IPv4 or IPv6 CIDR blocks."
  }
}

variable "route_tables" {
  description = "Map of route tables for the Transit Gateway. Each item conditionally creates a new route table or looks up an existing one."
  type = map(object({
    create = bool
    name   = optional(string)
    tags   = optional(map(string), {})
  }))
  default = {}
}

variable "shared_principals" {
  description = "Map of principal identifiers (e.g. AWS account IDs or organization ARNs) to share the Transit Gateway with via AWS RAM"
  type        = map(string)
  default     = {}
}

variable "ram_resource_share_name" {
  description = "Explicit name for the RAM resource share. Defaults to a fallback name based on the Transit Gateway name or resource label."
  type        = string
  default     = null
}

variable "tags" {
  description = "Global tags to apply to all resources"
  type        = map(string)
  default     = {}
}

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------
locals {
  # Resolve the Transit Gateway ID: from the created resource or from data sources.
  tgw_id = var.create ? aws_ec2_transit_gateway.this[0].id : (
    var.id != null ? data.aws_ec2_transit_gateway.by_id[0].id : data.aws_ec2_transit_gateway.by_name[0].id
  )

  # Resolve the Transit Gateway ARN (needed for RAM sharing).
  tgw_arn = var.create ? aws_ec2_transit_gateway.this[0].arn : (
    var.id != null ? data.aws_ec2_transit_gateway.by_id[0].arn : data.aws_ec2_transit_gateway.by_name[0].arn
  )
}

# ---------------------------------------------------------------------------
# Transit Gateway – created when var.create is true
# ---------------------------------------------------------------------------
resource "aws_ec2_transit_gateway" "this" {
  count = var.create ? 1 : 0

  default_route_table_association = "disable"
  default_route_table_propagation = "disable"
  amazon_side_asn                 = var.bgp_asn
  auto_accept_shared_attachments  = var.auto_accept_shared_attachments
  dns_support                     = var.dns_support
  vpn_ecmp_support                = var.vpn_ecmp_support
  transit_gateway_cidr_blocks     = var.transit_gateway_cidr_blocks

  tags = merge(var.tags, {
    Name = coalesce(var.name, "tgw")
  })
}

# ---------------------------------------------------------------------------
# Data sources for existing Transit Gateway
# ---------------------------------------------------------------------------
data "aws_ec2_transit_gateway" "by_id" {
  count = var.create ? 0 : (var.id != null ? 1 : 0)
  id    = var.id
}

data "aws_ec2_transit_gateway" "by_name" {
  count = var.create ? 0 : (var.id == null && var.name != null ? 1 : 0)

  filter {
    name   = "tag:Name"
    values = [var.name]
  }
}

# ---------------------------------------------------------------------------
# Transit Gateway Route Tables
# ---------------------------------------------------------------------------
resource "aws_ec2_transit_gateway_route_table" "this" {
  for_each = { for k, v in var.route_tables : k => v if v.create }

  transit_gateway_id = local.tgw_id

  tags = merge(
    var.tags,
    each.value.tags,
    {
      Name = coalesce(each.value.name, each.key, var.name, "tgw")
    },
  )
}

data "aws_ec2_transit_gateway_route_table" "this" {
  for_each = { for k, v in var.route_tables : k => v if !v.create }

  filter {
    name   = "transit-gateway-id"
    values = [local.tgw_id]
  }

  filter {
    name   = "tag:Name"
    values = [coalesce(each.value.name, each.key)]
  }
}

# ---------------------------------------------------------------------------
# RAM Resource Share – only provisioned when shared_principals is non-empty
# ---------------------------------------------------------------------------
resource "aws_ram_resource_share" "this" {
  count = length(var.shared_principals) > 0 ? 1 : 0

  name                      = var.ram_resource_share_name != null ? var.ram_resource_share_name : coalesce(var.name, "tgw-share")
  allow_external_principals = true

  tags = var.tags
}

resource "aws_ram_resource_association" "this" {
  count = length(var.shared_principals) > 0 ? 1 : 0

  resource_share_arn = aws_ram_resource_share.this[0].arn
  resource_arn       = local.tgw_arn
}

resource "aws_ram_principal_association" "this" {
  for_each = var.shared_principals

  resource_share_arn = aws_ram_resource_share.this[0].arn
  principal          = each.value
}

# Shared KMS key for all backup vaults
resource "aws_kms_key" "backup" {
  description             = "Shared KMS key for AWS Backup vaults"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "backup" {
  name          = "alias/backup-kms-key"
  target_key_id = aws_kms_key.backup.id
}

# IAM Role for Backup (shared across all tiers)
resource "aws_iam_role" "bronze_backup" {
  name = "Bronze_Backup_Role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "bronze_backup_policy" {
  role       = aws_iam_role.bronze_backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_iam_role_policy_attachment" "bronze_backup_restore" {
  role       = aws_iam_role.bronze_backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForRestores"
}

# ============================================================
# Bronze Tier
# ============================================================
resource "aws_backup_vault" "bronze" {
  name        = "Bronze_Backup_Vault"
  kms_key_arn = aws_kms_key.backup.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_plan" "bronze" {
  name = "Bronze_Backup"

  rule {
    rule_name         = "Bronze_Backup_Weekly"
    target_vault_name = aws_backup_vault.bronze.name
    schedule          = "cron(0 0 ? * FRI *)"
    lifecycle {
      delete_after = 10
    }
  }
}

resource "aws_backup_selection" "bronze" {
  name         = "Bronze_Resource_Assignment"
  plan_id      = aws_backup_plan.bronze.id
  iam_role_arn = aws_iam_role.bronze_backup.arn
  resources    = ["*"]

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "bronze"
  }
}

# ============================================================
# Silver Tier
# ============================================================
resource "aws_backup_vault" "silver" {
  name        = "Silver_Backup_Vault"
  kms_key_arn = aws_kms_key.backup.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_plan" "silver" {
  name = "Silver_Backup_Plan"

  rule {
    rule_name         = "Silver_Backup_Daily"
    target_vault_name = aws_backup_vault.silver.name
    schedule          = "cron(0 5 ? * * *)"
    lifecycle {
      delete_after = 7
    }
  }
}

resource "aws_backup_selection" "silver" {
  name         = "Silver_Backup_resource"
  plan_id      = aws_backup_plan.silver.id
  iam_role_arn = aws_iam_role.bronze_backup.arn
  resources    = ["*"]

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "silver"
  }
}

# ============================================================
# Gold Tier
# ============================================================
resource "aws_backup_vault" "gold" {
  name        = "Gold_Backup_Vault"
  kms_key_arn = aws_kms_key.backup.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_plan" "gold" {
  name = "Gold_Backup"

  rule {
    rule_name         = "Gold_Daily_Backup_Rule"
    target_vault_name = aws_backup_vault.gold.name
    schedule          = "cron(0 0 * * ? *)"
    lifecycle {
      delete_after = 31
    }
  }

  rule {
    rule_name         = "Gold_Monthly_Backup_Rule"
    target_vault_name = aws_backup_vault.gold.name
    schedule          = "cron(0 0 1 1/1 ? *)"
    lifecycle {
      delete_after = 365
    }
  }

  rule {
    rule_name         = "Gold_Yearly_Backup_Rule"
    target_vault_name = aws_backup_vault.gold.name
    schedule          = "cron(0 0 31 12 ? *)"
    lifecycle {
      delete_after = 2555
    }
  }
}

resource "aws_backup_selection" "gold" {
  name         = "Gold_Backup_Select"
  plan_id      = aws_backup_plan.gold.id
  iam_role_arn = aws_iam_role.bronze_backup.arn
  resources    = ["*"]

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "gold"
  }
}

# ============================================================
# Premium Tier
# ============================================================
resource "aws_backup_vault" "premium" {
  name        = "Premium"
  kms_key_arn = aws_kms_key.backup.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_plan" "premium" {
  name = "Premium"

  rule {
    rule_name         = "Premium_Daily_4Hour_Backup"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0/4 ? * * *)"
    lifecycle {
      delete_after = 1
    }
  }

  rule {
    rule_name         = "Premium_Daily_Backup"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0 * * ? *)"
    lifecycle {
      delete_after = 31
    }
  }

  rule {
    rule_name         = "Premium_Monthly"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0 1 1/1 ? *)"
    lifecycle {
      cold_storage_after = 15
      delete_after       = 365
    }
  }

  rule {
    rule_name         = "Premium_Yearly"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0 31 12 ? *)"
    lifecycle {
      cold_storage_after = 15
      delete_after       = 2555
    }
  }
}

resource "aws_backup_selection" "premium" {
  name         = "Premium"
  plan_id      = aws_backup_plan.premium.id
  iam_role_arn = aws_iam_role.bronze_backup.arn
  resources    = ["*"]

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "premium"
  }
}

variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "role_name" {
  description = "Name of the IAM role for Prisma Cloud"
  type        = string
  default     = "PrismaCloudReadWriteRole"
}

variable "read_write" {
  description = "Whether to attach the remediation (write) inline policy"
  type        = bool
  default     = false
}

data "aws_caller_identity" "current" {}

resource "random_id" "external_id" {
  byte_length = 16
}

locals {
  external_id = random_id.external_id.hex
}

resource "aws_iam_role" "prisma_cloud" {
  name               = var.role_name
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::188619942792:root"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "sts:ExternalId" = local.external_id
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "security_audit" {
  role       = aws_iam_role.prisma_cloud.name
  policy_arn = "arn:aws:iam::aws:policy/SecurityAudit"
}

resource "aws_iam_role_policy" "inline_read_only" {
  name   = "PrismaCloud-IAM-ReadOnly-Policy"
  role   = aws_iam_role.prisma_cloud.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "apigateway:GET",
          "cognito-identity:ListTagsForResource",
          "cognito-idp:ListTagsForResource",
          "ecr:DescribeImages",
          "ecr:GetLifecyclePolicy",
          "elasticbeanstalk:ListTagsForResource",
          "elasticfilesystem:DescribeTags",
          "glacier:GetVaultLock",
          "glacier:ListTagsForVault",
          "glue:GetSecurityConfigurations",
          "logs:GetLogEvents",
          "mq:listBrokers",
          "mq:describeBroker",
          "ram:GetResourceShares",
          "secretsmanager:DescribeSecret",
          "ssm:GetParameters",
          "ssm:ListTagsForResource",
          "sqs:SendMessage",
          "elasticmapreduce:ListSecurityConfigurations",
          "sns:listSubscriptions",
          "wafv2:ListResourcesForWebACL",
          "wafv2:ListWebACLs"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy" "inline_remediation" {
  count  = var.read_write ? 1 : 0
  name   = "PrismaCloud-IAM-Remediation-Policy"
  role   = aws_iam_role.prisma_cloud.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "iam:UpdateAccountPasswordPolicy",
          "ec2:ModifyImageAttribute",
          "rds:ModifyDBSnapshotAttribute",
          "s3:PutBucketAcl",
          "ec2:RevokeSecurityGroupIngress"
        ]
        Resource = "*"
      }
    ]
  })
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet"
  type        = string
  default     = "10.0.1.0/24"
}

variable "private_subnet_cidr" {
  description = "CIDR block for the private subnet"
  type        = string
  default     = "10.0.2.0/24"
}

variable "vpc_name" {
  description = "Name tag for the VPC"
  type        = string
  default     = "development-be-vpc"
}

variable "public_subnet_name" {
  description = "Name tag for the public subnet"
  type        = string
  default     = "development-be-public-subnet"
}

variable "private_subnet_name" {
  description = "Name tag for the private subnet"
  type        = string
  default     = "development-be-private-subnet"
}

variable "igw_name" {
  description = "Name tag for the internet gateway"
  type        = string
  default     = "development-be-ig"
}

variable "public_rt_name" {
  description = "Name tag for the public route table"
  type        = string
  default     = "development-be-public-rt"
}

variable "sg_name" {
  description = "Name tag for the security group"
  type        = string
  default     = "development-be-sg"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = var.public_subnet_name
  }
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = var.private_subnet_name
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = var.igw_name
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = var.public_rt_name
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "http_access" {
  name        = "http_access"
  description = "Security group for HTTP access and restricted SSH"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = var.sg_name
  }
}

resource "aws_vpc_security_group_ingress_rule" "ssh_from_vpc" {
  security_group_id = aws_security_group.http_access.id
  description       = "SSH from within VPC CIDR"
  from_port         = 22
  to_port           = 22
  ip_protocol       = "tcp"
  cidr_ipv4         = aws_vpc.main.cidr_block
}

resource "aws_vpc_security_group_ingress_rule" "http_from_all" {
  security_group_id = aws_security_group.http_access.id
  description       = "HTTP from anywhere"
  from_port         = 80
  to_port           = 80
  ip_protocol       = "tcp"
  cidr_ipv4         = "0.0.0.0/0"
}

resource "aws_vpc_security_group_egress_rule" "to_vpc_cidr" {
  security_group_id = aws_security_group.http_access.id
  description       = "Outbound traffic restricted to VPC CIDR"
  from_port         = 0
  to_port           = 0
  ip_protocol       = "-1"
  cidr_ipv4         = aws_vpc.main.cidr_block
}

output "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_id" {
  description = "The ID of the public subnet"
  value       = aws_subnet.public.id
}

output "private_subnet_id" {
  description = "The ID of the private subnet"
  value       = aws_subnet.private.id
}

# ------------------------------------------------------------------------------
# SNS Topic module
#
# Creates an Amazon SNS topic (standard or FIFO) with customizable access
# policies, conditional subscriptions, per-protocol delivery feedback logging,
# and an optional data protection policy.
# ------------------------------------------------------------------------------

locals {
  # Master toggle for the entire stack
  create = var.create

  # Whether the topic policy resource is created
  create_topic_policy = var.create && var.create_topic_policy

  # Whether topic subscription resources are created
  create_subscription = var.create && var.create_subscription

  # Mutually exclusive name / name_prefix selection
  name        = var.use_name_prefix ? null : var.name
  name_prefix = var.use_name_prefix ? var.name : null
}

data "aws_caller_identity" "current" {}

# ------------------------------------------------------------------------------
# IAM policy document combining source/override documents, custom statement
# maps, and an optional default policy statement that grants standard SNS
# actions to all AWS principals conditioned on the account owner ID.
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "this" {
  count = local.create_topic_policy ? 1 : 0

  source_policy_documents   = var.source_policy_documents
  override_policy_documents = var.override_policy_documents

  dynamic "statement" {
    for_each = var.statements

    content {
      sid           = try(statement.value.sid, null)
      actions       = try(statement.value.actions, null)
      not_actions   = try(statement.value.not_actions, null)
      effect        = try(statement.value.effect, null)
      resources     = try(statement.value.resources, null)
      not_resources = try(statement.value.not_resources, null)

      dynamic "principals" {
        for_each = try(statement.value.principals, [])

        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "not_principals" {
        for_each = try(statement.value.not_principals, [])

        content {
          type        = not_principals.value.type
          identifiers = not_principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = try(statement.value.condition, [])

        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }

  dynamic "statement" {
    for_each = var.enable_default_topic_policy ? [1] : []

    content {
      sid       = "SNSDefaultPolicy"
      effect    = "Allow"
      actions   = local.sns_default_actions
      resources = [aws_sns_topic.this[0].arn]

      principals {
        type        = "AWS"
        identifiers = ["*"]
      }

      condition {
        test     = "StringEquals"
        variable = "AWS:SourceOwner"
        values   = [data.aws_caller_identity.current.account_id]
      }
    }
  }
}

locals {
  sns_default_actions = [
    "SNS:GetTopicAttributes",
    "SNS:SetTopicAttributes",
    "SNS:AddPermission",
    "SNS:RemovePermission",
    "SNS:DeleteTopic",
    "SNS:Subscribe",
    "SNS:ListSubscriptionsByTopic",
    "SNS:Publish",
    "SNS:Receive",
  ]
}

# ------------------------------------------------------------------------------
# Core SNS topic
# ------------------------------------------------------------------------------
resource "aws_sns_topic" "this" {
  count = local.create ? 1 : 0

  name        = local.name
  name_prefix = local.name_prefix

  content_based_deduplication = var.content_based_deduplication
  delivery_policy             = var.delivery_policy
  display_name                = var.display_name
  kms_master_key_id           = var.kms_master_key_id
  signature_version           = var.fifo_topic ? null : var.signature_version
  tracing_config              = var.tracing_config
  fifo_topic                  = var.fifo_topic

  # Application delivery feedback logging
  application_failure_feedback_role_arn    = var.application_failure_feedback_role_arn
  application_success_feedback_role_arn    = var.application_success_feedback_role_arn
  application_success_feedback_sample_rate = var.application_success_feedback_sample_rate

  # Firehose delivery feedback logging
  firehose_failure_feedback_role_arn    = var.firehose_failure_feedback_role_arn
  firehose_success_feedback_role_arn    = var.firehose_success_feedback_role_arn
  firehose_success_feedback_sample_rate = var.firehose_success_feedback_sample_rate

  # HTTP delivery feedback logging
  http_failure_feedback_role_arn    = var.http_failure_feedback_role_arn
  http_success_feedback_role_arn    = var.http_success_feedback_role_arn
  http_success_feedback_sample_rate = var.http_success_feedback_sample_rate

  # Lambda delivery feedback logging
  lambda_failure_feedback_role_arn    = var.lambda_failure_feedback_role_arn
  lambda_success_feedback_role_arn    = var.lambda_success_feedback_role_arn
  lambda_success_feedback_sample_rate = var.lambda_success_feedback_sample_rate

  # SQS delivery feedback logging
  sqs_failure_feedback_role_arn    = var.sqs_failure_feedback_role_arn
  sqs_success_feedback_role_arn    = var.sqs_success_feedback_role_arn
  sqs_success_feedback_sample_rate = var.sqs_success_feedback_sample_rate
}

# ------------------------------------------------------------------------------
# Topic access policy (created when create_topic_policy is true)
# ------------------------------------------------------------------------------
resource "aws_sns_topic_policy" "this" {
  count = local.create_topic_policy ? 1 : 0

  arn    = aws_sns_topic.this[0].arn
  policy = coalesce(var.topic_policy, data.aws_iam_policy_document.this[0].json)
}

# ------------------------------------------------------------------------------
# Topic subscriptions (created when create and create_subscription are true)
# ------------------------------------------------------------------------------
resource "aws_sns_topic_subscription" "this" {
  for_each = local.create_subscription ? var.subscriptions : {}

  topic_arn                       = aws_sns_topic.this[0].arn
  confirmation_timeout_in_minutes = try(each.value.confirmation_timeout_in_minutes, null)
  delivery_policy                 = try(each.value.delivery_policy, null)
  endpoint                        = each.value.endpoint
  endpoint_auto_confirms          = try(each.value.endpoint_auto_confirms, null)
  filter_policy                   = try(each.value.filter_policy, null)
  filter_policy_scope             = try(each.value.filter_policy_scope, null)
  protocol                        = each.value.protocol
  raw_message_delivery            = try(each.value.raw_message_delivery, null)
  redrive_policy                  = try(each.value.redrive_policy, null)
  subscription_role_arn           = try(each.value.subscription_role_arn, null)
}

# ------------------------------------------------------------------------------
# Data protection policy (only applied to standard topics)
# ------------------------------------------------------------------------------
resource "aws_sns_topic_data_protection_policy" "this" {
  count = local.create && var.data_protection_policy != null && !var.fifo_topic ? 1 : 0

  arn    = aws_sns_topic.this[0].arn
  policy = var.data_protection_policy
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "create" {
  description = "Whether to create all resources"
  type        = bool
  default     = true
}

variable "name" {
  description = "Name of the SNS topic. Mutually exclusive with use_name_prefix."
  type        = string
  default     = null
}

variable "use_name_prefix" {
  description = "Determines whether the name argument is used to set the name, or a name_prefix argument is used."
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enables content-based deduplication for FIFO topics."
  type        = bool
  default     = false
}

variable "delivery_policy" {
  description = "The SNS delivery policy (JSON) defining retry, backoff and throttling."
  type        = string
  default     = null
}

variable "display_name" {
  description = "The display name to use for an SNS topic (emails / SMS)."
  type        = string
  default     = null
}

variable "kms_master_key_id" {
  description = "The ID of an AWS-managed customer master key (CMK) for SNS or a custom CMK."
  type        = string
  default     = null
}

variable "signature_version" {
  description = "Signature version for the topic. Ignored (forced to null) for FIFO topics."
  type        = number
  default     = null
}

variable "tracing_config" {
  description = "Tracing mode of an Amazon SNS topic: PassThrough or Active."
  type        = string
  default     = null
}

variable "fifo_topic" {
  description = "Boolean indicating whether the topic is a FIFO topic."
  type        = bool
  default     = false
}

# Application protocol delivery feedback
variable "application_failure_feedback_role_arn" {
  description = "IAM role ARN to allow an application to receive failed delivery feedback."
  type        = string
  default     = null
}

variable "application_success_feedback_role_arn" {
  description = "IAM role ARN to allow an application to receive successful delivery feedback."
  type        = string
  default     = null
}

variable "application_success_feedback_sample_rate" {
  description = "Percentage of successful application deliveries to generate feedback (0-100)."
  type        = number
  default     = null
}

# Firehose protocol delivery feedback
variable "firehose_failure_feedback_role_arn" {
  description = "IAM role ARN to allow Firehose to receive failed delivery feedback."
  type        = string
  default     = null
}

variable "firehose_success_feedback_role_arn" {
  description = "IAM role ARN to allow Firehose to receive successful delivery feedback."
  type        = string
  default     = null
}

variable "firehose_success_feedback_sample_rate" {
  description = "Percentage of successful Firehose deliveries to generate feedback (0-100)."
  type        = number
  default     = null
}

# HTTP protocol delivery feedback
variable "http_failure_feedback_role_arn" {
  description = "IAM role ARN to allow HTTP to receive failed delivery feedback."
  type        = string
  default     = null
}

variable "http_success_feedback_role_arn" {
  description = "IAM role ARN to allow HTTP to receive successful delivery feedback."
  type        = string
  default     = null
}

variable "http_success_feedback_sample_rate" {
  description = "Percentage of successful HTTP deliveries to generate feedback (0-100)."
  type        = number
  default     = null
}

# Lambda protocol delivery feedback
variable "lambda_failure_feedback_role_arn" {
  description = "IAM role ARN to allow Lambda to receive failed delivery feedback."
  type        = string
  default     = null
}

variable "lambda_success_feedback_role_arn" {
  description = "IAM role ARN to allow Lambda to receive successful delivery feedback."
  type        = string
  default     = null
}

variable "lambda_success_feedback_sample_rate" {
  description = "Percentage of successful Lambda deliveries to generate feedback (0-100)."
  type        = number
  default     = null
}

# SQS protocol delivery feedback
variable "sqs_failure_feedback_role_arn" {
  description = "IAM role ARN to allow SQS to receive failed delivery feedback."
  type        = string
  default     = null
}

variable "sqs_success_feedback_role_arn" {
  description = "IAM role ARN to allow SQS to receive successful delivery feedback."
  type        = string
  default     = null
}

variable "sqs_success_feedback_sample_rate" {
  description = "Percentage of successful SQS deliveries to generate feedback (0-100)."
  type        = number
  default     = null
}

# Topic policy variables
variable "create_topic_policy" {
  description = "Whether to create the SNS topic policy."
  type        = bool
  default     = true
}

variable "topic_policy" {
  description = "An external IAM policy (JSON) to attach directly to the topic. Used in place of the generated policy when provided."
  type        = string
  default     = null
}

variable "source_policy_documents" {
  description = "List of IAM policy documents (JSON) that are merged as the source of the generated policy."
  type        = list(string)
  default     = []
}

variable "override_policy_documents" {
  description = "List of IAM policy documents (JSON) that override the merged source policy document."
  type        = list(string)
  default     = []
}

variable "statements" {
  description = "A map of IAM policy statements for custom permissions."
  type        = any
  default     = {}
}

variable "enable_default_topic_policy" {
  description = "Whether to append an SNS default policy statement allowing standard actions to the account owner."
  type        = bool
  default     = true
}

# Subscription variables
variable "create_subscription" {
  description = "Whether to create SNS topic subscriptions."
  type        = bool
  default     = true
}

variable "subscriptions" {
  description = "Map of subscription definitions. Each entry supports confirmation_timeout_in_minutes, delivery_policy, endpoint, endpoint_auto_confirms, filter_policy, filter_policy_scope, protocol, raw_message_delivery, redrive_policy and subscription_role_arn."
  type        = any
  default     = {}
}

variable "data_protection_policy" {
  description = "The JSON data protection policy to attach to a standard (non-FIFO) SNS topic."
  type        = string
  default     = null
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------
output "sns_topic_arn" {
  description = "ARN of the SNS topic."
  value       = try(aws_sns_topic.this[0].arn, null)
}

output "sns_topic_id" {
  description = "ID of the SNS topic."
  value       = try(aws_sns_topic.this[0].id, null)
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------

variable "bucket_name" {
  description = "Optional bucket name. Falls back to corebucket-<random> if null."
  type        = string
  default     = null
}

variable "prefix" {
  description = "When true, appends an extra random suffix to the bucket name."
  type        = bool
  default     = false
}

variable "request_payer" {
  description = "Specifies who should be charged for requests: BucketOwner or Requester."
  type        = string
  default     = "BucketOwner"
}

variable "encryption" {
  description = "Enable SSE. When true, always uses aws:kms."
  type        = bool
  default     = true
}

variable "kms_key" {
  description = "ARN of an existing KMS key. If empty and encryption is true, a key is created."
  type        = string
  default     = ""
}

variable "versioning" {
  description = "Enable S3 versioning."
  type        = bool
  default     = false
}

variable "mfa_delete" {
  description = "Enable MFA delete on versioned bucket."
  type        = bool
  default     = false
}

variable "force_destroy" {
  description = "Allow bucket deletion even when non-empty."
  type        = bool
  default     = false
}

variable "acl" {
  description = "Canned ACL to apply (e.g. private, public-read). Conflicts with grants."
  type        = string
  default     = null
}

variable "policy" {
  description = "JSON bucket policy document."
  type        = string
  default     = null
}

variable "grants" {
  description = <<-EOT
    List of grants. Each entry has:
    - type      (string, required: CanonicalUser, Group, URI)
    - permission(string, required)
    - uri       (string, optional – required when type=URI)
    - id        (string, optional – required when type=CanonicalUser)
  EOT
  type = list(object({
    type       = string
    permission = string
    uri        = optional(string)
    id         = optional(string)
  }))
  default = null
}

variable "tags" {
  description = "Tags to apply to all resources."
  type        = map(string)
  default     = {}
}

variable "acceleration_status" {
  description = "Transfer acceleration: Enabled or Suspended."
  type        = string
  default     = null
}

variable "logging_target_bucket" {
  description = "Target bucket for access logs."
  type        = string
  default     = null
}

variable "logging_target_prefix" {
  description = "Prefix for log objects in the target bucket."
  type        = string
  default     = null
}

variable "website_index_document" {
  description = "Index document suffix for static website hosting."
  type        = string
  default     = null
}

variable "website_error_document" {
  description = "Error document key for static website hosting."
  type        = string
  default     = null
}

variable "website_redirect_all" {
  description = "Hostname to redirect all requests (takes precedence over index/error)."
  type        = string
  default     = null
}

variable "cors_rules" {
  description = "List of CORS rule maps."
  type        = any
  default     = null
}

variable "lifecycle_rules" {
  description = "List of lifecycle rule maps."
  type        = any
  default     = null
}

variable "object_lock_config" {
  description = "Object lock configuration: { mode, days?, years? }"
  type = object({
    mode  = string
    days  = optional(number)
    years = optional(number)
  })
  default = null
}

variable "replication_rules" {
  description = "List of replication rule maps."
  type        = any
  default     = null
}

variable "replication_role" {
  description = "ARN of an existing IAM role for replication. If null, a role is created."
  type        = string
  default     = null
}

# ---------------------------------------------------------------------------
# Data sources
# ---------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

# ---------------------------------------------------------------------------
# Random IDs for bucket naming
# ---------------------------------------------------------------------------

resource "random_id" "main" {
  byte_length = 4
}

resource "random_id" "suffix" {
  count       = var.prefix ? 1 : 0
  byte_length = 4
}

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------

locals {
  # Resolve the final bucket name
  base_name   = var.bucket_name != null ? var.bucket_name : "corebucket-${random_id.main.hex}"
  bucket_name = var.prefix ? "${local.base_name}-${random_id.suffix[0].hex}" : local.base_name

  # Should we create the KMS key?
  create_kms = var.encryption && var.kms_key == ""

  # The KMS key ARN to use for encryption
  kms_key_arn = var.kms_key != "" ? var.kms_key : (local.create_kms ? aws_kms_key.this[0].arn : null)

  # Destination bucket ARNs extracted from replication rules for the IAM policy
  destination_bucket_arns = var.replication_rules != null ? [
    for r in var.replication_rules : r.destination_bucket
  ] : []
}

# ---------------------------------------------------------------------------
# KMS Key (optional)
# ---------------------------------------------------------------------------

resource "aws_kms_key" "this" {
  count                   = local.create_kms ? 1 : 0
  description             = "S3 encryption key for ${local.bucket_name}"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  tags                    = var.tags
}

resource "aws_kms_alias" "this" {
  count         = local.create_kms ? 1 : 0
  name          = "alias/s3-${local.bucket_name}"
  target_key_id = aws_kms_key.this[0].key_id
}

# ---------------------------------------------------------------------------
# S3 Bucket
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "this" {
  bucket        = local.bucket_name
  force_destroy = var.force_destroy
  tags          = var.tags
}

# ---------------------------------------------------------------------------
# Public Access Block (always blocks all public access)
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_public_access_block" "this" {
  bucket                = aws_s3_bucket.this.id
  block_public_acls     = true
  block_public_policy   = true
  ignore_public_acls    = true
  restrict_public_buckets = true
}

# ---------------------------------------------------------------------------
# Server-Side Encryption
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.encryption ? "aws:kms" : "AES256"
      kms_master_key_id = var.encryption ? local.kms_key_arn : null
    }
    bucket_key_enabled = var.encryption ? true : null
  }
}

# ---------------------------------------------------------------------------
# Request Payer
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_request_payment_configuration" "this" {
  bucket = aws_s3_bucket.this.id
  payer  = var.request_payer
}

# ---------------------------------------------------------------------------
# Versioning
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status     = var.versioning ? "Enabled" : "Suspended"
    mfa_delete = var.mfa_delete ? "Enabled" : "Disabled"
  }
}

# ---------------------------------------------------------------------------
# Ownership Controls (required for canned ACLs)
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_ownership_controls" "this" {
  count  = var.acl != null ? 1 : 0
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

# ---------------------------------------------------------------------------
# ACL
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_acl" "this" {
  count  = var.acl != null ? 1 : 0
  bucket = aws_s3_bucket.this.id
  acl    = var.acl

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

# ---------------------------------------------------------------------------
# Grants (alternative to canned ACL)
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_acl" "grants" {
  count  = var.grants != null ? 1 : 0
  bucket = aws_s3_bucket.this.id

  access_control_policy {
    dynamic "grant" {
      for_each = var.grants != null ? var.grants : []
      content {
        grantee {
          type       = grant.value.type
          uri        = try(grant.value.uri, null)
          id         = try(grant.value.id, null)
        }
        permission = grant.value.permission
      }
    }

    owner {
      id = data.aws_caller_identity.current.user_id
    }
  }
}

# ---------------------------------------------------------------------------
# Bucket Policy
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_policy" "this" {
  count  = var.policy != null ? 1 : 0
  bucket = aws_s3_bucket.this.id
  policy = var.policy
}

# ---------------------------------------------------------------------------
# Transfer Acceleration
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count  = var.acceleration_status != null ? 1 : 0
  bucket = aws_s3_bucket.this.id
  status = var.acceleration_status
}

# ---------------------------------------------------------------------------
# Logging
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_logging" "this" {
  count  = var.logging_target_bucket != null ? 1 : 0
  bucket = aws_s3_bucket.this.id

  target_bucket = var.logging_target_bucket
  target_prefix = coalesce(var.logging_target_prefix, "")
}

# ---------------------------------------------------------------------------
# Static Website Hosting
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_website_configuration" "this" {
  count  = var.website_index_document != null || var.website_error_document != null || var.website_redirect_all != null ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "index_document" {
    for_each = var.website_index_document != null ? [1] : []
    content {
      suffix = var.website_index_document
    }
  }

  dynamic "error_document" {
    for_each = var.website_error_document != null ? [1] : []
    content {
      key = var.website_error_document
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = var.website_redirect_all != null ? [1] : []
    content {
      host_name = var.website_redirect_all
    }
  }
}

# ---------------------------------------------------------------------------
# CORS
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_cors_configuration" "this" {
  count  = var.cors_rules != null ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules != null ? var.cors_rules : []
    content {
      allowed_headers = try(cors_rule.value.allowed_headers, null)
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

# ---------------------------------------------------------------------------
# Lifecycle Rules
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count  = var.lifecycle_rules != null ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = var.lifecycle_rules != null ? var.lifecycle_rules : []
    content {
      id     = rule.value.id
      status = rule.value.status

      dynamic "filter" {
        for_each = try([rule.value.filter], [])
        content {
          prefix = try(filter.value.prefix, null)

          dynamic "tag" {
            for_each = try([filter.value.tag], [])
            content {
              key   = tag.value.key
              value = tag.value.value
            }
          }
        }
      }

      dynamic "expiration" {
        for_each = try([rule.value.expiration], [])
        content {
          days                         = try(expiration.value.days, null)
          date                         = try(expiration.value.date, null)
          expired_object_delete_marker = try(expiration.value.expired_object_delete_marker, null)
        }
      }

      dynamic "transition" {
        for_each = try(rule.value.transitions, [])
        content {
          days          = try(transition.value.days, null)
          date          = try(transition.value.date, null)
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = try([rule.value.noncurrent_version_expiration], [])
        content {
          noncurrent_days = noncurrent_version_expiration.value.noncurrent_days
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = try(rule.value.noncurrent_version_transitions, [])
        content {
          noncurrent_days = noncurrent_version_transition.value.noncurrent_days
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }
    }
  }
}

# ---------------------------------------------------------------------------
# Object Lock
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count  = var.object_lock_config != null ? 1 : 0
  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode  = var.object_lock_config.mode
      days  = try(var.object_lock_config.days, null)
      years = try(var.object_lock_config.years, null)
    }
  }
}

# ---------------------------------------------------------------------------
# Replication – IAM Role & Policy
# ---------------------------------------------------------------------------

resource "aws_iam_role" "replication" {
  count = var.replication_rules != null && var.replication_role == null ? 1 : 0
  name  = "CoreS3ReplicationRole_${local.bucket_name}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "s3.amazonaws.com"
        }
      }
    ]
  })
  tags = var.tags
}

resource "aws_iam_policy" "replication" {
  count = var.replication_rules != null && var.replication_role == null ? 1 : 0
  name  = "CoreS3ReplicationPolicy_${local.bucket_name}"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = [aws_s3_bucket.this.arn]
      }
    ,
      {
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Resource = ["${aws_s3_bucket.this.arn}/*"]
      }
    ,
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Resource = [
          for arn in local.destination_bucket_arns : "${arn}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "replication" {
  count      = var.replication_rules != null && var.replication_role == null ? 1 : 0
  role       = aws_iam_role.replication[0].name
  policy_arn = aws_iam_policy.replication[0].arn
}

# ---------------------------------------------------------------------------
# Replication Configuration
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_replication_configuration" "this" {
  count  = var.replication_rules != null ? 1 : 0
  bucket = aws_s3_bucket.this.id
  role   = var.replication_role != null ? var.replication_role : aws_iam_role.replication[0].arn

  dynamic "rule" {
    for_each = var.replication_rules != null ? var.replication_rules : []
    content {
      id     = rule.value.id
      status = rule.value.status

      dynamic "filter" {
        for_each = try([rule.value.filter], [])
        content {
          prefix = try(filter.value.prefix, null)
        }
      }

      destination {
        bucket        = rule.value.destination_bucket
        storage_class = try(rule.value.storage_class, null)

        # Only include replica_kms_key_id when SSE-KMS replication is requested
        dynamic "encryption_configuration" {
          for_each = try(rule.value.replica_kms_key_id, null) != null ? [1] : []
          content {
            replica_kms_key_id = rule.value.replica_kms_key_id
          }
        }
      }

      # source_selection_criteria is needed only for SSE-KMS replication
      dynamic "source_selection_criteria" {
        for_each = try(rule.value.replica_kms_key_id, null) != null ? [1] : []
        content {
          sse_kms_encrypted_objects {
            status = "Enabled"
          }
        }
      }

      delete_marker_replication {
        status = try(rule.value.delete_marker_replication, null) != null ? rule.value.delete_marker_replication : "Disabled"
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

variable "random_suffix" {
  description = "Append a random lowercase alphanumeric suffix to resource names"
  type        = bool
  default     = true
}

variable "suffix_length" {
  description = "Length of the random suffix string"
  type        = number
  default     = 4
}

variable "bucket_name" {
  description = "Base name for the S3 bucket"
  type        = string
  default     = "zedcloud"
}

variable "iam_username" {
  description = "Base name for the IAM user"
  type        = string
  default     = "zedcloud-s3-user"
}

variable "iam_policy_name" {
  description = "Base name for the IAM policy"
  type        = string
  default     = "zedcloud-s3-policy"
}

variable "upload_image" {
  description = "Whether to upload a local image file to the S3 bucket"
  type        = bool
  default     = false
}

variable "image_filename" {
  description = "Local path to the image file to upload"
  type        = string
  default     = "my-file.qcow2"
}

variable "s3_folder" {
  description = "S3 key folder prefix for the uploaded image"
  type        = string
  default     = "my-folder"
}

variable "create_folder" {
  description = "Whether to prefix the S3 key with the folder path"
  type        = bool
  default     = true
}

variable "create_iam_user" {
  description = "Whether to create the IAM user, access key, policy, and attachment"
  type        = bool
  default     = true
}

# ---------------------------------------------------------------------------
# Random suffix generator
# ---------------------------------------------------------------------------
resource "random_string" "suffix" {
  count     = var.random_suffix ? 1 : 0
  length    = var.suffix_length
  lower     = true
  numeric   = true
  upper     = false
  special   = false
}

locals {
  # When random_suffix is false the splat yields an empty list and join
  # produces an empty string; when true it yields the random string.
  suffix               = join("", random_string.suffix[*].result)
  resolved_bucket_name = "${var.bucket_name}${local.suffix}"
  resolved_iam_username  = "${var.iam_username}${local.suffix}"
  resolved_policy_name = "${var.iam_policy_name}${local.suffix}"
}

# ---------------------------------------------------------------------------
# Customer-managed KMS key with rotation enabled
# ---------------------------------------------------------------------------
resource "aws_kms_key" "main" {
  description             = "Customer-managed KMS key for S3 SSE-KMS encryption"
  deletion_window_in_days = 7
  is_enabled              = true
  enable_key_rotation     = true
  tags = {
    Name = local.resolved_bucket_name
  }
}

# ---------------------------------------------------------------------------
# S3 bucket with force_destroy and tag
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "main" {
  bucket        = local.resolved_bucket_name
  force_destroy = true
  tags = {
    Name = local.resolved_bucket_name
  }
}

# ---------------------------------------------------------------------------
# S3 bucket public access block – block all public access
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_public_access_block" "main" {
  bucket                  = aws_s3_bucket.main.id
  block_public_acls       = true
  ignore_public_acls      = true
  block_public_policy     = true
  restrict_public_buckets = true
}

# ---------------------------------------------------------------------------
# S3 bucket server-side encryption configuration (SSE-KMS)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.main.id
    }
  }
}

# ---------------------------------------------------------------------------
# IAM user (conditional)
# ---------------------------------------------------------------------------
resource "aws_iam_user" "main" {
  count         = var.create_iam_user ? 1 : 0
  name          = local.resolved_iam_username
  path          = "/"
  force_destroy = true
}

# ---------------------------------------------------------------------------
# IAM access key (conditional)
# ---------------------------------------------------------------------------
resource "aws_iam_access_key" "main" {
  count = var.create_iam_user ? 1 : 0
  user  = var.create_iam_user ? aws_iam_user.main[0].name : ""
}

# ---------------------------------------------------------------------------
# IAM policy (conditional)  –  least‑privilege S3 read‑only
# ---------------------------------------------------------------------------
resource "aws_iam_policy" "main" {
  count = var.create_iam_user ? 1 : 0
  name  = local.resolved_policy_name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["s3:GetObject"]
        Resource = ["${aws_s3_bucket.main.arn}/*"]
      },
      {
        Effect   = "Allow"
        Action   = ["s3:ListBucket"]
        Resource = [aws_s3_bucket.main.arn]
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# IAM user policy attachment (conditional)
# ---------------------------------------------------------------------------
resource "aws_iam_user_policy_attachment" "main" {
  count      = var.create_iam_user ? 1 : 0
  user       = var.create_iam_user ? aws_iam_user.main[0].name : ""
  policy_arn = var.create_iam_user ? aws_iam_policy.main[0].arn : ""
}

# ---------------------------------------------------------------------------
# Image upload (conditional)
# ---------------------------------------------------------------------------
resource "aws_s3_object" "image" {
  count  = var.upload_image ? 1 : 0
  bucket = aws_s3_bucket.main.id
  key    = var.create_folder ? "${var.s3_folder}/${var.image_filename}" : var.image_filename
  source = var.image_filename
}

variable "default_tags" {
  type        = map(string)
  description = "Provider-level default tags applied to every resource."
  default = {
    Project     = "tf-eks-jofo"
    Owner       = "Jovan Zelincevic"
    Compliance  = "Nothing"
    Environment = "dev"
    Provider    = "Terraform"
  }
}

variable "vpc_cidr" {
  type        = string
  description = "CIDR block for the main VPC."
  default     = "10.14.0.0/16"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  project       = var.default_tags["Project"]
  environment   = var.default_tags["Environment"]
  name_prefix   = "${local.project}-${local.environment}"
  azs           = slice(data.aws_availability_zones.available.names, 0, 3)
  cluster_tag   = { "kubernetes.io/cluster/${local.name_prefix}" = "shared" }
  public_cidrs  = [for i in range(3) : cidrsubnet(var.vpc_cidr, 4, i)]
  private_cidrs = [for i in range(3) : cidrsubnet(var.vpc_cidr, 4, i + 3)]
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.default_tags, {
    Name = local.name_prefix
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.default_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_subnet" "public" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(var.default_tags, local.cluster_tag, {
    Name                     = "${local.name_prefix}-public-${count.index + 1}"
    "kubernetes.io/role/elb" = "1"
  })
}

resource "aws_subnet" "private" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(var.default_tags, local.cluster_tag, {
    Name                              = "${local.name_prefix}-private-${count.index + 1}"
    "kubernetes.io/role/internal-elb" = "1"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.default_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(var.default_tags, {
    Name = "${local.name_prefix}-nat-eip"
  })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(var.default_tags, {
    Name = "${local.name_prefix}-nat"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.default_tags, {
    Name = "${local.name_prefix}-private-rt"
  })
}

resource "aws_route" "private_nat" {
  route_table_id         = aws_route_table.private.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main.id
}

resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# ------------------------------------------------------------------------------
# Highly Configurable Amazon S3 Bucket Module
# ------------------------------------------------------------------------------

terraform {
  required_version = ">= 1.3"
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------

variable "create_bucket" {
  description = "Whether to create the S3 bucket"
  type        = bool
  default     = true
}

variable "bucket" {
  description = "Name of the S3 bucket. Conflicts with bucket_prefix"
  type        = string
  default     = null
}

variable "bucket_prefix" {
  description = "Prefix for the S3 bucket name. Conflicts with bucket"
  type        = string
  default     = null
}

variable "acl" {
  description = "Canned ACL to apply to the S3 bucket"
  type        = string
  default     = "private"
}

variable "force_destroy" {
  description = "Allow the bucket to be destroyed even if it contains objects"
  type        = bool
  default     = false
}

variable "tags" {
  description = "Tags to apply to the S3 bucket"
  type        = map(string)
  default     = {}
}

variable "acceleration_status" {
  description = "Acceleration status of the S3 bucket"
  type        = string
  default     = null
}

variable "request_payer" {
  description = "Request payer configuration for the S3 bucket"
  type        = string
  default     = null
}

variable "control_object_ownership" {
  description = "Whether to control object ownership"
  type        = bool
  default     = false
}

variable "object_ownership" {
  description = "Object ownership setting. Required when control_object_ownership is true"
  type        = string
  default     = "ObjectWriter"
}

variable "website" {
  description = "Map of website configuration parameters (index_document, error_document, redirect_all_requests_to, routing_rules)"
  type        = any
  default     = null
}

variable "cors_rule" {
  description = "List of CORS rule maps"
  type        = any
  default     = []
}

variable "versioning" {
  description = "Map of versioning configuration (enabled, mfa_delete)"
  type        = map(string)
  default     = {}
}

variable "logging" {
  description = "Map of logging configuration (target_bucket, target_prefix)"
  type        = map(string)
  default     = {}
}

variable "grant" {
  description = "List of ACL grant blocks (type, permission, uri, id)"
  type        = any
  default     = []
}

variable "lifecycle_rule" {
  description = "List of lifecycle rule maps"
  type        = any
  default     = []
}

variable "replication_configuration" {
  description = "Map of replication configuration (role, rules)"
  type        = any
  default     = {}
}

variable "server_side_encryption_configuration" {
  description = "Map of server-side encryption configuration (sse_algorithm, kms_master_key_arn). If null, a KMS key is created"
  type        = any
  default     = null
}

variable "object_lock_configuration" {
  description = "Map of object lock configuration (object_lock_enabled, rule)"
  type        = any
  default     = {}
}

variable "attach_elb_log_delivery_policy" {
  description = "Whether to attach ELB log delivery policy"
  type        = bool
  default     = false
}

variable "attach_lb_log_delivery_policy" {
  description = "Whether to attach ALB/NLB log delivery policy"
  type        = bool
  default     = false
}

variable "attach_deny_insecure_transport_policy" {
  description = "Whether to attach a policy denying insecure transport"
  type        = bool
  default     = false
}

variable "attach_policy" {
  description = "Whether to attach a custom policy"
  type        = bool
  default     = false
}

variable "policy" {
  description = "Custom IAM policy document string"
  type        = string
  default     = null
}

variable "attach_public_policy" {
  description = "Whether to create an S3 public access block"
  type        = bool
  default     = true
}

variable "block_public_acls" {
  description = "Block public ACLs"
  type        = bool
  default     = true
}

variable "block_public_policy" {
  description = "Block public bucket policies"
  type        = bool
  default     = true
}

variable "ignore_public_acls" {
  description = "Ignore public ACLs"
  type        = bool
  default     = true
}

variable "restrict_public_buckets" {
  description = "Restrict public buckets"
  type        = bool
  default     = true
}

# ------------------------------------------------------------------------------
# Data sources
# ------------------------------------------------------------------------------

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

# ------------------------------------------------------------------------------
# KMS Key (created when no server-side encryption config is provided)
# ------------------------------------------------------------------------------

resource "aws_kms_key" "s3" {
  count                   = var.create_bucket && var.server_side_encryption_configuration == null ? 1 : 0
  description             = "S3 bucket SSE-KMS key"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  tags                    = var.tags
}

resource "aws_kms_alias" "s3" {
  count         = var.create_bucket && var.server_side_encryption_configuration == null ? 1 : 0
  name          = "alias/s3-bucket-key-${data.aws_caller_identity.current.account_id}"
  target_key_id = aws_kms_key.s3[0].key_id
}

# ------------------------------------------------------------------------------
# S3 Bucket
# ------------------------------------------------------------------------------

resource "aws_s3_bucket" "this" {
  count  = var.create_bucket ? 1 : 0
  bucket = var.bucket
  bucket_prefix = var.bucket_prefix
  force_destroy = var.force_destroy
  acceleration_status = var.acceleration_status
  request_payer       = var.request_payer
  tags                = var.tags
}

# ------------------------------------------------------------------------------
# Object Ownership
# ------------------------------------------------------------------------------

resource "aws_s3_bucket_ownership_controls" "this" {
  count  = var.create_bucket ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  rule {
    object_ownership = var.control_object_ownership ? var.object_ownership : "BucketOwnerPreferred"
  }
}

# ------------------------------------------------------------------------------
# Public Access Block
# ------------------------------------------------------------------------------

resource "aws_s3_bucket_public_access_block" "this" {
  count                   = var.create_bucket && var.attach_public_policy ? 1 : 0
  bucket                  = aws_s3_bucket.this[0].id
  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

# ------------------------------------------------------------------------------
# ACL Grants
# ------------------------------------------------------------------------------

resource "aws_s3_bucket_acl" "canned" {
  count  = var.create_bucket && length(var.grant) == 0 ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  acl    = var.acl

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

resource "aws_s3_bucket_acl" "grants" {
  count  = var.create_bucket && length(var.grant) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  acl    = var.acl

  depends_on = [aws_s3_bucket_ownership_controls.this]

  dynamic "access_control_policy" {
    for_each = length(var.grant) > 0 ? [1] : []
    content {
      dynamic "grant" {
        for_each = var.grant
        content {
          grantee {
            type          = grant.value.type
            uri           = try(grant.value.uri, null)
            id            = try(grant.value.id, null)
            email_address = try(grant.value.email_address, null)
          }
          permission = grant.value.permission
        }
      }
      owner {
        id = data.aws_caller_identity.current.account_id
      }
    }
  }
}

# ------------------------------------------------------------------------------
# Website Configuration
# ------------------------------------------------------------------------------

resource "aws_s3_bucket_website_configuration" "this" {
  count  = var.create_bucket && var.website != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  dynamic "index_document" {
    for_each = try(var.website.index_document, null) != null ? [1] : []
    content {
      suffix = var.website.index_document
    }
  }

  dynamic "error_document" {
    for_each = try(var.website.error_document, null) != null ? [1] : []
    content {
      key = var.website.error_document
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = try(var.website.redirect_all_requests_to, null) != null ? [1] : []
    content {
      host_name = var.website.redirect_all_requests_to.host_name
      protocol  = try(var.website.redirect_all_requests_to.protocol, null)
    }
  }

  dynamic "routing_rule" {
    for_each = try(var.website.routing_rules, [])
    content {
      dynamic "condition" {
        for_each = try(routing_rule.value.condition, null) != null ? [1] : []
        content {
          http_error_code_returned_equals = try(routing_rule.value.condition.http_error_code_returned_equals, null)
          key_prefix_equals               = try(routing_rule.value.condition.key_prefix_equals, null)
        }
      }
      dynamic "redirect" {
        for_each = try(routing_rule.value.redirect, null) != null ? [1] : []
        content {
          host_name               = try(routing_rule.value.redirect.host_name, null)
          http_redirect_code      = try(routing_rule.value.redirect.http_redirect_code, null)
          protocol                = try(routing_rule.value.redirect.protocol, null)
          replace_key_prefix_with = try(routing_rule.value.redirect.replace_key_prefix_with, null)
          replace_key_with        = try(routing_rule.value.redirect.replace_key_with, null)
        }
      }
    }
  }
}

# ------------------------------------------------------------------------------
# CORS Configuration
# ------------------------------------------------------------------------------

resource "aws_s3_bucket_cors_configuration" "this" {
  count  = var.create_bucket && length(var.cors_rule) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  dynamic "cors_rule" {
    for_each = var.cors_rule
    content {
      allowed_headers = try(cors_rule.value.allowed_headers, [])
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = try(cors_rule.value.expose_headers, [])
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

# ------------------------------------------------------------------------------
# Versioning
# ------------------------------------------------------------------------------

resource "aws_s3_bucket_versioning" "this" {
  count  = var.create_bucket && length(var.versioning) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  versioning_configuration {
    status     = try(var.versioning.enabled, false) ? "Enabled" : try(var.versioning.status, "Suspended")
    mfa_delete = try(var.versioning.mfa_delete, false) ? "Enabled" : "Disabled"
  }
}

# ------------------------------------------------------------------------------
# Server-Side Encryption
# ------------------------------------------------------------------------------

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count  = var.create_bucket ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.server_side_encryption_configuration == null ? "aws:kms" : try(var.server_side_encryption_configuration.sse_algorithm, "AES256")
      kms_master_key_id = var.server_side_encryption_configuration == null ? aws_kms_key.s3[0].arn : try(var.server_side_encryption_configuration.kms_master_key_arn, null)
    }
    bucket_key_enabled = try(var.server_side_encryption_configuration.bucket_key_enabled, null)
  }
}

# ------------------------------------------------------------------------------
# Access Logging
# ------------------------------------------------------------------------------

resource "aws_s3_bucket_logging" "this" {
  count  = var.create_bucket && length(var.logging) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  target_bucket = var.logging["target_bucket"]
  target_prefix = try(var.logging["target_prefix"], "")
}

# ------------------------------------------------------------------------------
# Lifecycle Rules
# ------------------------------------------------------------------------------

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count  = var.create_bucket && length(var.lifecycle_rule) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  dynamic "rule" {
    for_each = var.lifecycle_rule
    content {
      id     = try(rule.value.id, "rule-${rule.key}")
      status = try(rule.value.enabled, true) ? "Enabled" : "Disabled"

      dynamic "abort_incomplete_multipart_upload" {
        for_each = try(rule.value.abort_incomplete_multipart_upload_days, null) != null ? [1] : []
        content {
          days_after_initiation = rule.value.abort_incomplete_multipart_upload_days
        }
      }

      dynamic "expiration" {
        for_each = try(rule.value.expiration, null) != null ? [1] : []
        content {
          date                         = try(rule.value.expiration.date, null)
          days                         = try(rule.value.expiration.days, null)
          expired_object_delete_marker = try(rule.value.expiration.expired_object_delete_marker, null)
        }
      }

      dynamic "transition" {
        for_each = try(rule.value.transition, [])
        content {
          date          = try(transition.value.date, null)
          days          = try(transition.value.days, null)
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = try(rule.value.noncurrent_version_expiration, null) != null ? [1] : []
        content {
          newer_noncurrent_versions = try(rule.value.noncurrent_version_expiration.newer_noncurrent_versions, null)
          noncurrent_days           = rule.value.noncurrent_version_expiration.days
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = try(rule.value.noncurrent_version_transition, [])
        content {
          newer_noncurrent_versions = try(noncurrent_version_transition.value.newer_noncurrent_versions, null)
          noncurrent_days           = noncurrent_version_transition.value.days
          storage_class             = noncurrent_version_transition.value.storage_class
        }
      }

      filter {
        prefix = try(rule.value.prefix, null)
        dynamic "and" {
          for_each = try(rule.value.filter_and, null) != null ? [1] : []
          content {
            prefix               = try(rule.value.filter_and.prefix, null)
            tags                 = try(rule.value.filter_and.tags, null)
            object_size_greater_than = try(rule.value.filter_and.object_size_greater_than, null)
            object_size_less_than    = try(rule.value.filter_and.object_size_less_than, null)
          }
        }
        dynamic "tag" {
          for_each = try(rule.value.filter_tag, null) != null ? [1] : []
          content {
            key   = rule.value.filter_tag.key
            value = rule.value.filter_tag.value
          }
        }
        object_size_greater_than = try(rule.value.object_size_greater_than, null)
        object_size_less_than    = try(rule.value.object_size_less_than, null)
      }
    }
  }
}

# ------------------------------------------------------------------------------
# Cross-Region Replication
# ------------------------------------------------------------------------------

resource "aws_s3_bucket_replication_configuration" "this" {
  count      = var.create_bucket && length(var.replication_configuration) > 0 ? 1 : 0
  bucket     = aws_s3_bucket.this[0].id
  role       = var.replication_configuration["role"]

  dynamic "rule" {
    for_each = var.replication_configuration["rules"]
    content {
      id       = try(rule.value.id, null)
      status   = try(rule.value.status, "Enabled")
      priority = try(rule.value.priority, null)

      dynamic "delete_marker_replication" {
        for_each = try(rule.value.delete_marker_replication, null) != null ? [1] : []
        content {
          status = rule.value.delete_marker_replication
        }
      }

      destination {
        bucket             = rule.value.destination.bucket
        storage_class      = try(rule.value.destination.storage_class, null)
        account            = try(rule.value.destination.account, null)
        dynamic "encryption_configuration" {
          for_each = try(rule.value.destination.replica_kms_key_id, null) != null ? [1] : []
          content {
            replica_kms_key_id = rule.value.destination.replica_kms_key_id
          }
        }

        dynamic "access_control_translation" {
          for_each = try(rule.value.destination.access_control_translation, null) != null ? [1] : []
          content {
            owner = rule.value.destination.access_control_translation.owner
          }
        }

        dynamic "metrics" {
          for_each = try(rule.value.destination.metrics, null) != null ? [1] : []
          content {
            status  = rule.value.destination.metrics.status
            event_threshold {
              minutes = try(rule.value.destination.metrics.minutes, 15)
            }
          }
        }

        dynamic "replication_time" {
          for_each = try(rule.value.destination.replication_time, null) != null ? [1] : []
          content {
            status  = rule.value.destination.replication_time.status
            time {
              minutes = try(rule.value.destination.replication_time.minutes, 15)
            }
          }
        }
      }

      dynamic "source_selection_criteria" {
        for_each = try(rule.value.source_selection_criteria, null) != null ? [1] : []
        content {
          dynamic "replica_modifications" {
            for_each = try(rule.value.source_selection_criteria.replica_modifications, null) != null ? [1] : []
            content {
              status = rule.value.source_selection_criteria.replica_modifications.status
            }
          }
          dynamic "sse_kms_encrypted_objects" {
            for_each = try(rule.value.source_selection_criteria.sse_kms_encrypted_objects, null) != null ? [1] : []
            content {
              status = rule.value.source_selection_criteria.sse_kms_encrypted_objects.status
            }
          }
        }
      }

      dynamic "filter" {
        for_each = try(rule.value.filter, null) != null ? [1] : []
        content {
          prefix = try(rule.value.filter.prefix, null)

          dynamic "tag" {
            for_each = try(rule.value.filter.tags, [])
            content {
              key   = tag.value.key
              value = tag.value.value
            }
          }

          dynamic "and" {
            for_each = try(rule.value.filter.and, null) != null ? [1] : []
            content {
              prefix = try(rule.value.filter.and.prefix, null)
              tags   = try(rule.value.filter.and.tags, [])
            }
          }
        }
      }
    }
  }
}

# ------------------------------------------------------------------------------
# Object Lock Configuration
# ------------------------------------------------------------------------------

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count  = var.create_bucket && length(var.object_lock_configuration) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  object_lock_enabled = try(var.object_lock_configuration.object_lock_enabled, "Enabled")

  dynamic "rule" {
    for_each = try(var.object_lock_configuration.rule, null) != null ? [1] : []
    content {
      default_retention {
        mode  = var.object_lock_configuration.rule.default_retention.mode
        days  = try(var.object_lock_configuration.rule.default_retention.days, null)
        years = try(var.object_lock_configuration.rule.default_retention.years, null)
      }
    }
  }
}

# ------------------------------------------------------------------------------
# IAM Policy Document for combined bucket policy
# ------------------------------------------------------------------------------

data "aws_iam_policy_document" "combined" {
  count = var.create_bucket ? 1 : 0

  # ELB log delivery policy (classic ELB)
  dynamic "statement" {
    for_each = var.attach_elb_log_delivery_policy ? [1] : []
    content {
      sid    = "ELBDelivery"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = ["arn:${data.aws_partition.current.partition}:iam::127311923021:root"]
      }
      actions   = ["s3:PutObject"]
      resources = ["${aws_s3_bucket.this[0].arn}/*"]
    }
  }

  # ALB/NLB log delivery write policy
  dynamic "statement" {
    for_each = var.attach_lb_log_delivery_policy ? [1] : []
    content {
      sid    = "LBDeliveryWrite"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = ["arn:${data.aws_partition.current.partition}:iam::127311923021:root"]
      }
      actions   = ["s3:PutObject"]
      resources = ["${aws_s3_bucket.this[0].arn}/*"]
    }
  }

  # ALB/NLB log delivery ACL check policy
  dynamic "statement" {
    for_each = var.attach_lb_log_delivery_policy ? [1] : []
    content {
      sid    = "LBDeliveryAclCheck"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = ["arn:${data.aws_partition.current.partition}:iam::127311923021:root"]
      }
      actions   = ["s3:GetBucketAcl"]
      resources = [aws_s3_bucket.this[0].arn]
    }
  }

  # Deny insecure transport policy
  dynamic "statement" {
    for_each = var.attach_deny_insecure_transport_policy ? [1] : []
    content {
      sid    = "DenyInsecureTransport"
      effect = "Deny"
      principals {
        type        = "*"
        identifiers = ["*"]
      }
      actions   = ["s3:*"]
      resources = [aws_s3_bucket.this[0].arn, "${aws_s3_bucket.this[0].arn}/*"]
      condition {
        test     = "Bool"
        variable = "aws:SecureTransport"
        values   = ["false"]
      }
    }
  }

  # Custom policy document
  dynamic "statement" {
    for_each = var.attach_policy && var.policy != null ? [1] : []
    content {
      sid       = "CustomPolicy"
      effect    = "Allow"
      actions   = ["s3:*"]
      resources = [aws_s3_bucket.this[0].arn, "${aws_s3_bucket.this[0].arn}/*"]
    }
  }
}

# ------------------------------------------------------------------------------
# Bucket Policy (attach combined policy)
# ------------------------------------------------------------------------------

resource "aws_s3_bucket_policy" "this" {
  count  = var.create_bucket && (
    var.attach_elb_log_delivery_policy ||
    var.attach_lb_log_delivery_policy ||
    var.attach_deny_insecure_transport_policy ||
    (var.attach_policy && var.policy != null)
  ) ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  policy = data.aws_iam_policy_document.combined[0].json
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------

output "s3_bucket_id" {
  description = "The ID of the S3 bucket"
  value       = try(aws_s3_bucket.this[0].id, null)
}

output "s3_bucket_arn" {
  description = "The ARN of the S3 bucket"
  value       = try(aws_s3_bucket.this[0].arn, null)
}

output "s3_bucket_domain_name" {
  description = "The bucket domain name"
  value       = try(aws_s3_bucket.this[0].bucket_domain_name, null)
}

output "s3_bucket_regional_domain_name" {
  description = "The bucket regional domain name"
  value       = try(aws_s3_bucket.this[0].bucket_regional_domain_name, null)
}

output "kms_key_arn" {
  description = "The ARN of the KMS key created for SSE-KMS"
  value       = try(aws_kms_key.s3[0].arn, null)
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------

variable "awsRegion" {
  description = "AWS region where the network stack is deployed"
  type        = string
  default     = "us-east-1"
}

variable "projectPrefix" {
  description = "Prefix used when tagging the deployed resources"
  type        = string
  default     = "f5-dcec"
}

variable "resourceOwner" {
  description = "Owner of the deployed resources, used for tagging"
  type        = string
  default     = "f5-user"
}

variable "buildSuffix" {
  description = "Suffix used to uniquely mark the deployed resources, used for tagging"
  type        = string
  default     = "YY"
}

variable "map_public_ip_on_launch" {
  description = "Whether instances launched in the public subnets should receive a public IP address"
  type        = bool
  default     = false
}

variable "awsAz1" {
  description = "Availability zone used by the 'A' subnets. Falls back to the first available availability zone in the region when not set."
  type        = string
  default     = null
}

variable "awsAz2" {
  description = "Availability zone used by the 'B' subnets. Falls back to the second available availability zone in the region when not set, or to awsAz1 when awsAz1 is specified."
  type        = string
  default     = null
}

variable "vpcMainCidr" {
  description = "CIDR block for the main VPC"
  type        = string
  default     = "10.1.0.0/16"
}

variable "vpcMainSubPubACidr" {
  description = "CIDR block for the public subnet in the first availability zone"
  type        = string
  default     = "10.1.10.0/24"
}

variable "vpcMainSubPubBCidr" {
  description = "CIDR block for the public subnet in the second availability zone"
  type        = string
  default     = "10.1.110.0/24"
}

variable "vpcMainSubMgmtACidr" {
  description = "CIDR block for the management subnet in the first availability zone"
  type        = string
  default     = "10.1.1.0/24"
}

variable "vpcMainSubMgmtBCidr" {
  description = "CIDR block for the management subnet in the second availability zone"
  type        = string
  default     = "10.1.101.0/24"
}

variable "vpcMainSubPrivACidr" {
  description = "CIDR block for the private subnet in the first availability zone"
  type        = string
  default     = "10.1.20.0/24"
}

variable "vpcMainSubPrivBCidr" {
  description = "CIDR block for the private subnet in the second availability zone"
  type        = string
  default     = "10.1.120.0/24"
}

# ------------------------------------------------------------------------------
# Data sources
# ------------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------

locals {
  common_tags = {
    project     = var.projectPrefix
    owner       = var.resourceOwner
    buildSuffix = var.buildSuffix
  }

  name_prefix = "${var.projectPrefix}-${var.buildSuffix}"

  # Resolve the availability zones. When awsAz1 is set but awsAz2 is not,
  # awsAz2 falls back to referencing awsAz1 so the deployment stays
  # deterministic and single-AZ.
  az1 = var.awsAz1 == null ? data.aws_availability_zones.available.names[0] : var.awsAz1
  az2 = var.awsAz2 == null ? (var.awsAz1 == null ? data.aws_availability_zones.available.names[1] : var.awsAz1) : var.awsAz2
}

# ------------------------------------------------------------------------------
# VPC
# ------------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpcMainCidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

# ------------------------------------------------------------------------------
# Subnets
# ------------------------------------------------------------------------------

resource "aws_subnet" "pub_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPubACidr
  availability_zone       = local.az1
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-pub-a"
  })
}

resource "aws_subnet" "pub_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPubBCidr
  availability_zone       = local.az2
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-pub-b"
  })
}

resource "aws_subnet" "mgmt_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubMgmtACidr
  availability_zone = local.az1

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-mgmt-a"
  })
}

resource "aws_subnet" "mgmt_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubMgmtBCidr
  availability_zone = local.az2

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-mgmt-b"
  })
}

resource "aws_subnet" "priv_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubPrivACidr
  availability_zone = local.az1

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-priv-a"
  })
}

resource "aws_subnet" "priv_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubPrivBCidr
  availability_zone = local.az2

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-priv-b"
  })
}

# ------------------------------------------------------------------------------
# Internet gateway
# ------------------------------------------------------------------------------

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

# ------------------------------------------------------------------------------
# Route table and main route table association
# ------------------------------------------------------------------------------

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-rt"
  })
}

resource "aws_main_route_table_association" "main" {
  vpc_id         = aws_vpc.main.id
  route_table_id = aws_route_table.main.id
}

variable "resource_name" {
  description = "Default name for all named resources"
  type        = string
  default     = "benchmark"
}

variable "rule_count" {
  description = "Number of listener rules with path patterns"
  type        = number
  default     = 1
}

locals {
  vpc_cidr = "10.0.0.0/16"
  # Self-signed certificate for demo/testing purposes
  tls_private_key_pem = tls_private_key.ca.private_key_pem
  tls_cert_pem        = tls_self_signed_cert.ca.cert_pem
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.resource_name
  }
}

resource "aws_subnet" "main" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(local.vpc_cidr, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${var.resource_name}-${count.index}"
  }
}

resource "aws_security_group" "alb" {
  name        = var.resource_name
  description = "Allow all traffic within VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = var.resource_name
  }
}

# TLS certificate for HTTPS listener
resource "tls_private_key" "ca" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "ca" {
  private_key_pem = tls_private_key.ca.private_key_pem

  subject {
    common_name = "alb.internal"
  }

  dns_names = ["alb.internal"]

  validity_period_hours = 8760

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "alb" {
  private_key      = local.tls_private_key_pem
  certificate_body = local.tls_cert_pem

  tags = {
    Name = var.resource_name
  }
}

resource "aws_lb" "internal" {
  name               = var.resource_name
  internal           = true
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb.id]
  subnets            = aws_subnet.main[*].id

  drop_invalid_header_fields = true

  tags = {
    Name = var.resource_name
  }
}

resource "aws_lb_target_group" "http" {
  name        = var.resource_name
  port        = 8080
  protocol    = "HTTP"
  vpc_id      = aws_vpc.main.id
  target_type = "ip"

  health_check {
    enabled             = true
    port                = 8081
    protocol            = "HTTP"
    path                = "/health"
    interval            = 60
    timeout             = 3
    healthy_threshold   = 3
    unhealthy_threshold = 3
    matcher             = "200-299"
  }

  tags = {
    Name = var.resource_name
  }
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.internal.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-3-2021-06"
  certificate_arn   = aws_acm_certificate.alb.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.http.arn
  }
}

resource "aws_lb_listener_rule" "static" {
  count        = var.rule_count
  listener_arn = aws_lb_listener.https.arn
  priority     = 100 + count.index

  action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.http.arn
  }

  condition {
    path_pattern {
      values = ["/static-${count.index}/*"]
    }
  }

  tags = {
    Name = "${var.resource_name}-rule-${count.index}"
  }
}

variable "trail_name" {
  description = "Name of the CloudTrail trail"
  type        = string
  default     = "management_trail"
}

variable "is_organization_trail" {
  description = "Whether the trail is an organization trail"
  type        = bool
  default     = false
}

variable "cloudwatch_log_group_name" {
  description = "Name of the CloudWatch Log Group for CloudTrail logs"
  type        = string
  default     = "cloudtrail_logs"
}

variable "enable_kms_encryption" {
  description = "Whether to enable KMS encryption for CloudTrail and the S3 bucket"
  type        = bool
  default     = true
}

variable "kms_key_alias" {
  description = "Alias for the KMS key used for CloudTrail encryption"
  type        = string
  default     = "alias/cloudtrail_key"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

locals {
  current_region = data.aws_region.current.region
}

data "aws_partition" "current" {}

# Random suffix for the S3 bucket name
resource "random_string" "bucket_suffix" {
  length  = 12
  upper   = false
  lower   = true
  numeric = true
  special = false
}

# KMS Key for CloudTrail and S3 encryption
resource "aws_kms_key" "cloudtrail" {
  count = var.enable_kms_encryption ? 1 : 0

  description             = "KMS key for CloudTrail audit logging"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "cloudtrail-kms-key-policy"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudTrail to encrypt logs"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceArn" = "arn:${data.aws_partition.current.partition}:cloudtrail:${local.current_region}:${data.aws_caller_identity.current.account_id}:trail/${var.trail_name}"
          }
        }
      },
      {
        Sid    = "Allow S3 to use the key for bucket encryption"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt",
          "kms:DescribeKey",
          "kms:Encrypt",
          "kms:ReEncrypt*"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceArn" = "arn:${data.aws_partition.current.partition}:s3:::cloudtrail-bucket-${random_string.bucket_suffix.result}"
          }
        }
      },
      {
        Sid    = "Allow CloudWatch Logs to use the key"
        Effect = "Allow"
        Principal = {
          Service = "logs.${local.current_region}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceArn" = "arn:${data.aws_partition.current.partition}:logs:${local.current_region}:${data.aws_caller_identity.current.account_id}:log-group:${var.cloudwatch_log_group_name}"
          }
        }
      },
      {
        Sid    = "Allow account users to decrypt logs"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = [
          "kms:Decrypt",
          "kms:ReEncryptFrom"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:ViaService" = [
              "s3.${local.current_region}.amazonaws.com",
              "logs.${local.current_region}.amazonaws.com"
            ]
          }
        }
      }
    ]
  })
}

resource "aws_kms_alias" "cloudtrail" {
  count = var.enable_kms_encryption ? 1 : 0

  name          = var.kms_key_alias
  target_key_id = aws_kms_key.cloudtrail[0].key_id
}

# S3 bucket for CloudTrail logs
resource "aws_s3_bucket" "cloudtrail" {
  bucket        = "cloudtrail-bucket-${random_string.bucket_suffix.result}"
  force_destroy = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = try(aws_kms_key.cloudtrail[0].arn, null)
      sse_algorithm     = var.enable_kms_encryption ? "aws:kms" : "AES256"
    }
  }
}

resource "aws_s3_bucket_policy" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCloudTrailAclCheck"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action   = "s3:GetBucketAcl"
        Resource = aws_s3_bucket.cloudtrail.arn
        Condition = {
          StringEquals = {
            "aws:SourceArn" = "arn:${data.aws_partition.current.partition}:cloudtrail:${local.current_region}:${data.aws_caller_identity.current.account_id}:trail/${var.trail_name}"
          }
        }
      },
      {
        Sid    = "AllowCloudTrailWrite"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.cloudtrail.arn}/AWSLogs/${data.aws_caller_identity.current.account_id}/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control",
            "aws:SourceArn" = "arn:${data.aws_partition.current.partition}:cloudtrail:${local.current_region}:${data.aws_caller_identity.current.account_id}:trail/${var.trail_name}"
          }
        }
      }
    ]
  })
}

# CloudWatch Log Group for CloudTrail logs
resource "aws_cloudwatch_log_group" "cloudtrail" {
  name              = var.cloudwatch_log_group_name
  retention_in_days = 0

  kms_key_id = try(aws_kms_key.cloudtrail[0].arn, null)
}

# IAM role for CloudTrail to write to CloudWatch Logs
resource "aws_iam_role" "cloudtrail_cloudwatch" {
  name = "CloudTrailRoleForCloudWatchLogs"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCloudTrailToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "cloudtrail_cloudwatch" {
  name   = "allow-access-to-cw-logs"
  role   = aws_iam_role.cloudtrail_cloudwatch.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCloudTrailToCreateLogStreamsAndPutEvents"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
      }
    ]
  })
}

# CloudTrail trail
resource "aws_cloudtrail" "management" {
  name                          = var.trail_name
  enable_log_file_validation    = true
  is_multi_region_trail         = true
  include_global_service_events = true
  is_organization_trail         = var.is_organization_trail

  s3_bucket_name = aws_s3_bucket.cloudtrail.id

  cloud_watch_logs_group_arn = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
  cloud_watch_logs_role_arn  = aws_iam_role.cloudtrail_cloudwatch.arn

  kms_key_id = try(aws_kms_key.cloudtrail[0].arn, null)

  event_selector {
    read_write_type           = "All"
    include_management_events = true
  }

  depends_on = [
    aws_s3_bucket_policy.cloudtrail,
    aws_iam_role_policy.cloudtrail_cloudwatch
  ]
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

# Variables
variable "namespace" {
  description = "Optional namespace prefix for the repository name"
  type        = string
  default     = ""
}

variable "repository_name" {
  description = "Repository name (frigga naming, petname generated when null/empty)"
  type        = string
  default     = "ecr"
}

variable "image_tag_mutability" {
  description = "Image tag mutability setting"
  type        = string
  default     = "IMMUTABLE"
}

variable "image_scan_on_push" {
  description = "Enable image scan on push"
  type        = bool
  default     = true
}

variable "lifecycle_policy" {
  description = "JSON lifecycle policy string. If null, no lifecycle policy is created."
  type        = string
  default     = null
}

variable "trusted_accounts" {
  description = "List of additional AWS account IDs to grant cross-account read access"
  type        = list(string)
  default     = []
}

# Random pet for generating repository name when needed
resource "random_pet" "repository_name" {
  count  = var.repository_name == null || var.repository_name == "" ? 1 : 0
  length = 2
}

locals {
  repo_name_raw = var.repository_name == null || var.repository_name == "" ? random_pet.repository_name[0].id : var.repository_name
  repo_name     = var.namespace != "" ? "${var.namespace}/${local.repo_name_raw}" : local.repo_name_raw
}

# ECR repository
resource "aws_ecr_repository" "main" {
  name                 = local.repo_name
  image_tag_mutability = var.image_tag_mutability
  image_scanning_configuration {
    scan_on_push = var.image_scan_on_push
  }
  tags = {
    "terraform.io" = "managed"
    "Name"         = local.repo_name
  }
}

# Lifecycle policy - only created when lifecycle_policy is supplied
resource "aws_ecr_lifecycle_policy" "main" {
  count      = var.lifecycle_policy != null ? 1 : 0
  repository = aws_ecr_repository.main.name
  policy     = var.lifecycle_policy
}

# IAM policy document for read access
data "aws_iam_policy_document" "ecr_read" {
  statement {
    sid    = "EcrReadAccess"
    effect = "Allow"
    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:BatchGetImage",
      "ecr:DescribeImages",
      "ecr:DescribeRepositories",
      "ecr:GetAuthorizationToken",
      "ecr:GetDownloadUrlForLayer",
      "ecr:ListImages",
    ]
    resources = [
      aws_ecr_repository.main.arn,
    ]
  }
  # GetAuthorizationToken operates at the registry level, not repository
  statement {
    sid    = "EcrGetAuthToken"
    effect = "Allow"
    actions = [
      "ecr:GetAuthorizationToken",
    ]
    resources = ["*"]
  }
}

# IAM policy document for write access
data "aws_iam_policy_document" "ecr_write" {
  statement {
    sid    = "EcrWriteAccess"
    effect = "Allow"
    actions = [
      "ecr:PutImage",
      "ecr:UploadLayerPart",
      "ecr:InitiateLayerUpload",
      "ecr:CompleteLayerUpload",
    ]
    resources = [
      aws_ecr_repository.main.arn,
    ]
  }
  # GetAuthorizationToken operates at the registry level
  statement {
    sid    = "EcrGetAuthToken"
    effect = "Allow"
    actions = [
      "ecr:GetAuthorizationToken",
    ]
    resources = ["*"]
  }
}

# IAM policy for read access
resource "aws_iam_policy" "ecr_read" {
  name        = "${local.repo_name}-ecr-read"
  description = "Read-only access to ECR repository ${local.repo_name}"
  policy      = data.aws_iam_policy_document.ecr_read.json
  tags = {
    "terraform.io" = "managed"
    "Name"         = "${local.repo_name}-ecr-read"
  }
}

# IAM policy for write access
resource "aws_iam_policy" "ecr_write" {
  name        = "${local.repo_name}-ecr-write"
  description = "Write access to ECR repository ${local.repo_name}"
  policy      = data.aws_iam_policy_document.ecr_write.json
  tags = {
    "terraform.io" = "managed"
    "Name"         = "${local.repo_name}-ecr-write"
  }
}

# Data source for current caller identity
data "aws_caller_identity" "current" {}

# ECR repository policy for cross-account access
resource "aws_ecr_repository_policy" "main" {
  repository = aws_ecr_repository.main.name
  policy     = data.aws_iam_policy_document.repository_policy.json
}

data "aws_iam_policy_document" "repository_policy" {
  statement {
    sid    = "AllowCrossAccountAccess"
    effect = "Allow"
    principals {
      type = "AWS"
      identifiers = concat(
        ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"],
        [for account_id in var.trusted_accounts : "arn:aws:iam::${account_id}:root"]
      )
    }
    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:BatchGetImage",
      "ecr:DescribeImages",
      "ecr:DescribeRepositories",
      "ecr:GetAuthorizationToken",
      "ecr:GetDownloadUrlForLayer",
      "ecr:ListImages",
    ]
    # Only constrain the resource condition for repository-specific actions
    condition {
      test     = "StringEquals"
      variable = "ecr:RepositoryName"
      values   = [aws_ecr_repository.main.name]
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

variable "vpc_cidr" {
  description = "Base CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "enable_public_subnets" {
  description = "Enable public subnet tier with Internet Gateway access"
  type        = bool
  default     = true
}

variable "enable_nat_subnets" {
  description = "Enable NAT subnet tier"
  type        = bool
  default     = true
}

variable "enable_private_subnets" {
  description = "Enable private subnet tier"
  type        = bool
  default     = true
}

variable "az_count" {
  description = "Number of availability zones to use for subnet deployment"
  type        = number
  default     = 2
  validation {
    condition     = var.az_count >= 1
    error_message = "az_count must be at least 1."
  }
}

locals {
  # Cap AZ count to the number of available zones in the region
  az_count_actual = min(var.az_count, length(data.aws_availability_zones.available.names))
  azs             = slice(data.aws_availability_zones.available.names, 0, local.az_count_actual)

  # Count how many subnet tiers are active and the total subnets required
  tiers_count   = (var.enable_public_subnets ? 1 : 0) + (var.enable_nat_subnets ? 1 : 0) + (var.enable_private_subnets ? 1 : 0)
  total_subnets = local.tiers_count * local.az_count_actual

  # Find the smallest power of two >= total_subnets (log-based bitwise splitting)
  pow2_ge = local.total_subnets <= 0 ? 0 : (
    local.total_subnets <= 1 ? 1 : (
      local.total_subnets <= 2 ? 2 : (
        local.total_subnets <= 4 ? 4 : (
          local.total_subnets <= 8 ? 8 : (
            local.total_subnets <= 16 ? 16 : (
              local.total_subnets <= 32 ? 32 : 64
            )
          )
        )
      )
    )
  )

  # Number of additional bits required for subnetting (log2(pow2_ge))
  add_bits = local.pow2_ge == 0 ? 0 : (
    local.pow2_ge == 1 ? 0 : (
      local.pow2_ge == 2 ? 1 : (
        local.pow2_ge == 4 ? 2 : (
          local.pow2_ge == 8 ? 3 : (
            local.pow2_ge == 16 ? 4 : (
              local.pow2_ge == 32 ? 5 : 6
            )
          )
        )
      )
    )
  )

  # Subnet netnum offsets for each tier using offset CIDR calculations
  public_offset  = 0
  nat_offset     = var.enable_public_subnets ? local.az_count_actual : 0
  private_offset = local.nat_offset + (var.enable_nat_subnets ? local.az_count_actual : 0)
}

# ---------------------------------------------------------------------------
# VPC
# ---------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr

  tags = {
    Name = "main-vpc"
  }
}

# ---------------------------------------------------------------------------
# Public Subnets – auto-assign public IP, linked to Internet Gateway
# ---------------------------------------------------------------------------
resource "aws_subnet" "public" {
  count = var.enable_public_subnets ? local.az_count_actual : 0

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, local.add_bits, local.public_offset + count.index)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = "public-${local.azs[count.index]}"
    Tier = "public"
  }
}

# ---------------------------------------------------------------------------
# NAT Subnets – offset CIDR, no public IP assignment
# ---------------------------------------------------------------------------
resource "aws_subnet" "nat" {
  count = var.enable_nat_subnets ? local.az_count_actual : 0

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, local.add_bits, local.nat_offset + count.index)
  availability_zone = local.azs[count.index]

  tags = {
    Name = "nat-${local.azs[count.index]}"
    Tier = "nat"
  }
}

# ---------------------------------------------------------------------------
# Private Subnets – offset CIDR, no public IP assignment
# ---------------------------------------------------------------------------
resource "aws_subnet" "private" {
  count = var.enable_private_subnets ? local.az_count_actual : 0

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, local.add_bits, local.private_offset + count.index)
  availability_zone = local.azs[count.index]

  tags = {
    Name = "private-${local.azs[count.index]}"
    Tier = "private"
  }
}

# ---------------------------------------------------------------------------
# Internet Gateway – only created when public subnets are enabled
# ---------------------------------------------------------------------------
resource "aws_internet_gateway" "public" {
  count  = var.enable_public_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "public-igw"
  }
}

# ---------------------------------------------------------------------------
# Security Group – egress rule allowing all traffic to 0.0.0.0/0
# ---------------------------------------------------------------------------
resource "aws_security_group" "public" {
  count       = var.enable_public_subnets ? 1 : 0
  name        = "public-egress"
  description = "Allow all egress traffic for public subnets"
  vpc_id      = aws_vpc.main.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "public-egress"
  }
}

# ---------------------------------------------------------------------------
# Public Route Table – internet route via IGW, local VPC route auto-created
# ---------------------------------------------------------------------------
resource "aws_route_table" "public" {
  count  = var.enable_public_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.public[0].id
  }

  tags = {
    Name = "public"
  }
}

# ---------------------------------------------------------------------------
# Route Table Associations – attach each public subnet to the route table
# ---------------------------------------------------------------------------
resource "aws_route_table_association" "public" {
  count         = var.enable_public_subnets ? local.az_count_actual : 0
  subnet_id     = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

terraform {
  required_providers {
    tls = {
      source = "hashicorp/tls"
    }
  }
}

# =============================================================================
# Variables
# =============================================================================

variable "project" {
  description = "Project name used for resource naming and tagging"
  type        = string
  default     = "demo"
}

variable "environment" {
  description = "Deployment environment identifier"
  type        = string
  default     = "poc"
}

variable "vpc_name" {
  description = "Name label for the VPC"
  type        = string
  default     = "demo-dataflow"
}

variable "region" {
  description = "Target AWS region"
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the primary VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "List of CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.0.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "List of CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.3.0/24"]
}

variable "key_pair_name" {
  description = "Name of the EC2 key pair used for bastion SSH access"
  type        = string
  default     = "kplinuxdemo"
}

variable "bastion_instance_type" {
  description = "EC2 instance type for the SSH bastion host"
  type        = string
  default     = "t3.nano"
}

variable "ebs_optimization" {
  description = "Toggle for EBS-optimized instance configuration"
  type        = bool
  default     = false
}

variable "resource_tags" {
  description = "Custom resource tagging map applied to all resources"
  type        = map(string)
  default = {
    project     = "demo"
    environment = "poc"
    managed-by  = "terraform"
  }
}

variable "bastion_allowed_cidrs" {
  description = "List of CIDR blocks allowed to SSH into the bastion host"
  type        = list(string)
  default     = ["10.0.0.0/16"]
}

# =============================================================================
# Data Sources – static / well-known lookups only
# =============================================================================

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-*-*-*-*"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }
}

# =============================================================================
# TLS Key – generate a local RSA key for the bastion
# =============================================================================

resource "tls_private_key" "bastion" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "aws_key_pair" "bastion" {
  key_name   = var.key_pair_name
  public_key = tls_private_key.bastion.public_key_openssh

  tags = merge(var.resource_tags, {
    Name = var.key_pair_name
  })
}

# =============================================================================
# VPC – primary networking container
# =============================================================================

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.resource_tags, {
    Name = var.vpc_name
  })
}

# =============================================================================
# Internet Gateway – provides outbound / inbound Internet for public subnets
# =============================================================================

resource "aws_internet_gateway" "demo" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.resource_tags, {
    Name = "demogwInternet"
  })
}

# =============================================================================
# Public Subnets – no automatic public IP assignment on launch
# =============================================================================

resource "aws_subnet" "public" {
  count                   = length(var.public_subnet_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(var.resource_tags, {
    Name = "${var.project}-public-subnet-${count.index + 1}"
  })
}

# =============================================================================
# Private Subnets
# =============================================================================

resource "aws_subnet" "private" {
  count             = length(var.private_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(var.resource_tags, {
    Name = "${var.project}-private-subnet-${count.index + 1}"
  })
}

# =============================================================================
# Public Route Table – sends 0.0.0.0/0 traffic through the Internet Gateway
# =============================================================================

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.demo.id
  }

  tags = merge(var.resource_tags, {
    Name = "demoPublicRouteTable"
  })
}

# =============================================================================
# Route Table Association – attaches public subnets to the public route table
# =============================================================================

resource "aws_route_table_association" "public" {
  count          = length(var.public_subnet_cidrs)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# =============================================================================
# Bastion Security Group – allows inbound SSH from any source
# =============================================================================

locals {
  vpc_dns_resolver = cidrhost(var.vpc_cidr, 2)
}

resource "aws_security_group" "bastion" {
  name        = "${var.project}-bastion-sg"
  description = "Security group for SSH bastion host access"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH access from allowed networks"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = var.bastion_allowed_cidrs
  }

  egress {
    description = "DNS resolution via VPC resolver"
    from_port   = 53
    to_port     = 53
    protocol    = "udp"
    cidr_blocks = ["${local.vpc_dns_resolver}/32"]
  }

  egress {
    description = "SSH outbound to VPC destination hosts"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(var.resource_tags, {
    Name = "${var.project}-bastion-sg"
  })
}

# =============================================================================
# Bastion EC2 Instance – SSH jump host in the first public subnet
# =============================================================================

resource "aws_kms_key" "ebs" {
  description             = "KMS key for EBS root volume encryption"
  deletion_window_in_days = 7

  tags = merge(var.resource_tags, {
    Name = "${var.project}-ebs-kms-key"
  })
}

resource "aws_instance" "bastion" {
  instance_type              = var.bastion_instance_type
  ami                         = data.aws_ami.amazon_linux.id
  key_name                    = aws_key_pair.bastion.key_name
  subnet_id                   = aws_subnet.public[0].id
  vpc_security_group_ids      = [aws_security_group.bastion.id]
  associate_public_ip_address = true

  metadata_options {
    http_tokens   = "required"
    http_endpoint = "enabled"
  }

  root_block_device {
    encrypted  = true
    kms_key_id = aws_kms_key.ebs.id
  }

  tags = merge(var.resource_tags, {
    Name = "${var.project}-bastion"
  })
}

# AWS Backup solution for all RDS databases
# Provides daily, weekly, monthly, and yearly backup schedules
# Each with cross-region copy and optional cross-account copy configuration

# ============================================================
# VARIABLES
# ============================================================

variable "secondary_region" {
  description = "Secondary AWS region for cross-region backup vault copies"
  type        = string
  default     = "us-west-2"
}

variable "cross_account_enabled" {
  description = "Enable optional cross-account backup copy"
  type        = bool
  default     = true
}

variable "destination_account_id" {
  description = "Destination AWS account ID for cross-account backup copy"
  type        = string
  default     = "433568766270"
}

variable "excluded_rds_arns" {
  description = "List of RDS instance ARNs to exclude from backups"
  type        = list(string)
  default     = []
}

variable "create_daily_backup" {
  description = "Enable creation of the daily backup plan"
  type        = bool
  default     = true
}

# ============================================================
# DATA SOURCES
# ============================================================

data "aws_region" "current" {}



# ============================================================
# LOCAL VALUES
# ============================================================

locals {
  # Define the four backup schedules with their parameters
  schedules = {
    daily = {
      # At 02:00 UTC every day
      schedule_expr  = "cron(0 2 * * ? *)"
      retention_days = 7
      enabled        = var.create_daily_backup
    }
    weekly = {
      # At 02:00 UTC every Saturday (use ? for day-of-month since day-of-week is specified)
      schedule_expr  = "cron(0 2 ? * 6 *)"
      retention_days = 30
      enabled        = true
    }
    monthly = {
      # At 03:00 UTC on the 1st of every month
      schedule_expr  = "cron(0 3 1 * ? *)"
      retention_days = 365
      enabled        = true
    }
    yearly = {
      # At 04:00 UTC on January 1st
      schedule_expr  = "cron(0 4 1 1 ? *)"
      retention_days = 2555
      enabled        = true
    }
  }

  # Filter to only enabled schedules
  enabled_schedules = {
    for k, v in local.schedules : k => v if v.enabled
  }

  # Helper to convert schedule name to human-readable label
  schedule_labels = {
    daily   = "Daily"
    weekly  = "Weekly"
    monthly = "Monthly"
    yearly  = "Yearly"
  }
}

# ============================================================
# IAM ROLE AND POLICY FOR AWS BACKUP SERVICE
# ============================================================

resource "aws_iam_role" "backup_service" {
  name               = "RDSBackupServiceRole"
  assume_role_policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  description = "IAM role for AWS Backup service to back up RDS databases"
}

# Custom policy for the backup service role granting necessary AWS Backup and RDS permissions
resource "aws_iam_policy" "backup_service" {
  name        = "RDSBackupServicePolicy"
  description = "Custom policy granting AWS Backup service access to manage RDS backups"
  policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["backup:*"]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = ["rds:Describe*", "rds:List*"]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = ["tag:GetResources"]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "backup_service" {
  role       = aws_iam_role.backup_service.name
  policy_arn = aws_iam_policy.backup_service.arn
}

# ============================================================
# BACKUP VAULTS
# ============================================================

# Primary region vaults (one per schedule) - KMS-encrypted by default
resource "aws_backup_vault" "primary" {
  for_each = local.enabled_schedules
  name     = "rds-${each.key}-vault-${data.aws_region.current.region}"
  tags = {
    Name     = "RDS-${local.schedule_labels[each.key]}-Backup-Vault-Primary"
    Schedule = local.schedule_labels[each.key]
    Type     = "primary"
  }
}

# Secondary region vaults for cross-region copies (one per schedule) - KMS-encrypted by default
resource "aws_backup_vault" "secondary" {
  for_each = local.enabled_schedules
  name     = "rds-${each.key}-vault-${var.secondary_region}"
  region   = var.secondary_region
  tags = {
    Name     = "RDS-${local.schedule_labels[each.key]}-Backup-Vault-${var.secondary_region}"
    Schedule = local.schedule_labels[each.key]
    Type     = "cross-region"
  }
}

# ============================================================
# BACKUP PLANS
# ============================================================

# Main backup plan per schedule - backs up to primary vault, copies to secondary region vault
resource "aws_backup_plan" "main" {
  for_each = local.enabled_schedules
  name     = "rds-${each.key}-backup-plan"

  rule {
    rule_name                  = "${local.schedule_labels[each.key]}-backup-rule"
    target_vault_name          = aws_backup_vault.primary[each.key].name
    schedule                   = each.value.schedule_expr
    schedule_expression_timezone = "UTC"

    lifecycle {
      delete_after = each.value.retention_days
    }

    copy_action {
      destination_vault_arn = aws_backup_vault.secondary[each.key].arn
    }
  }
}

# ============================================================
# BACKUP SELECTIONS
# ============================================================

# Selection for main backup plan (selects all RDS databases except excluded ones)
resource "aws_backup_selection" "main" {
  for_each      = local.enabled_schedules
  name          = "rds-${each.key}-selection"
  plan_id       = aws_backup_plan.main[each.key].id
  iam_role_arn  = aws_iam_role.backup_service.arn
  not_resources = length(var.excluded_rds_arns) > 0 ? toset(var.excluded_rds_arns) : null

  # Select all RDS databases by matching the RDS resource type
  selection_tag {
    key   = "AWS::ResourceType"
    value = "RDS"
    type  = "STRINGEQUALS"
  }
}

# NOTE: Cross-account backup copy is configured via the cross_account_enabled and
# destination_account_id variables. In a production deployment, an
# aws_backup_vault_policy resource should be added to grant the destination
# account access to the secondary region vaults for cross-account backup copies.
# This requires the deploying identity to have the PutBackupVaultAccessPolicy
# permission.

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------
variable "allow_users_to_change_password" {
  description = "Whether to allow users to change their own password"
  type        = bool
  default     = true
}

variable "hard_expiry" {
  description = "Whether users are prevented from setting a new password after their password has expired"
  type        = bool
  default     = false
}

variable "max_password_age" {
  description = "Number of days that an IAM user password is valid"
  type        = number
  default     = 90
}

variable "minimum_password_length" {
  description = "Minimum length of IAM user password"
  type        = number
  default     = 14
}

variable "password_reuse_prevention" {
  description = "Number of previous passwords that users are prevented from reusing"
  type        = number
  default     = 24
}

variable "require_lowercase_characters" {
  description = "Whether to require lowercase characters in IAM user password"
  type        = bool
  default     = true
}

variable "require_uppercase_characters" {
  description = "Whether to require uppercase characters in IAM user password"
  type        = bool
  default     = true
}

variable "require_numbers" {
  description = "Whether to require numbers in IAM user password"
  type        = bool
  default     = true
}

variable "require_symbols" {
  description = "Whether to require symbols in IAM user password"
  type        = bool
  default     = true
}

# ---------------------------------------------------------------------------------------------------------------------
# ACCOUNT PASSWORD POLICY
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_iam_account_password_policy" "this" {
  allow_users_to_change_password = var.allow_users_to_change_password
  hard_expiry                    = var.hard_expiry
  max_password_age               = var.max_password_age
  minimum_password_length        = var.minimum_password_length
  password_reuse_prevention      = var.password_reuse_prevention
  require_lowercase_characters   = var.require_lowercase_characters
  require_uppercase_characters   = var.require_uppercase_characters
  require_numbers                = var.require_numbers
  require_symbols                = var.require_symbols
}

# ---------------------------------------------------------------------------------------------------------------------
# IAM GROUPS
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_iam_group" "administrators" {
  name = "administrators"
}

resource "aws_iam_group" "developpers" {
  name = "developpers"
}

resource "aws_iam_group" "prod_users" {
  name = "prod_users"
}

# ---------------------------------------------------------------------------------------------------------------------
# IAM GROUP POLICIES
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_iam_group_policy" "administrators_policy" {
  name   = "administrators_policy"
  group  = aws_iam_group.administrators.name
  policy = data.aws_iam_policy_document.administrators_policy.json
}

resource "aws_iam_group_policy" "developpers_policy" {
  name   = "developpers_policy"
  group  = aws_iam_group.developpers.name
  policy = data.aws_iam_policy_document.developpers_policy.json
}

resource "aws_iam_group_policy" "prod_users_policy" {
  name   = "prod_users_policy"
  group  = aws_iam_group.prod_users.name
  policy = data.aws_iam_policy_document.prod_users_policy.json
}

# ---------------------------------------------------------------------------------------------------------------------
# IAM POLICY DOCUMENTS
# ---------------------------------------------------------------------------------------------------------------------
data "aws_iam_policy_document" "administrators_policy" {
  statement {
    sid = "AllowBroadAccessExceptSecurityTaggedHigh"

    effect = "Allow"

    not_actions = [
      "iam:*",
      "organizations:*",
      "account:*",
    ]

    condition {
      test     = "StringNotEquals"
      variable = "aws:ResourceTag/security"
      values   = ["high"]
    }

    resources = ["*"]
  }

  statement {
    sid = "AllowSpecificIamOrgAccountActions"

    effect = "Allow"

    actions = [
      "iam:CreateServiceLinkedRole",
      "iam:DeleteServiceLinkedRole",
      "iam:ListRoles",
      "organizations:DescribeOrganization",
      "account:ListRegions",
    ]

    resources = ["*"]
  }
}

data "aws_iam_policy_document" "developpers_policy" {
  statement {
    sid = "AllowEc2RdsOnDevTaggedResources"

    effect = "Allow"

    actions = [
      "ec2:*",
      "rds:*",
    ]

    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/env"
      values   = ["dev"]
    }

    resources = ["*"]
  }
}

data "aws_iam_policy_document" "prod_users_policy" {
  statement {
    sid = "AllowEc2RdsOnPreprodOrProdTaggedResources"

    effect = "Allow"

    actions = [
      "ec2:*",
      "rds:*",
    ]

    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/env"
      values   = ["preprod", "prod"]
    }

    resources = ["*"]
  }
}

variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "name_prefix" {
  description = "Resource name prefix"
  type        = string
  default     = "tfm-aws"
}

variable "instance_tenancy" {
  description = "VPC instance tenancy"
  type        = string
  default     = "default"
}

variable "vpc_cidr" {
  description = "Main VPC CIDR block"
  type        = string
  default     = "10.0.0.0/16"
}

variable "private_subnets" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.2.0/24", "10.0.3.0/24"]
}

variable "public_inbound_acl_rules" {
  description = "Inbound network ACL rules for private subnets"
  type = list(object({
    rule_number = number
    protocol    = string
    from_port   = number
    to_port     = number
    cidr_block  = string
    action      = string
  }))
  default = [
    {
      rule_number = 100
      protocol    = "tcp"
      from_port   = 1024
      to_port     = 65535
      cidr_block  = "0.0.0.0/0"
      action      = "allow"
    },
  ]
}

variable "public_outbound_acl_rules" {
  description = "Outbound network ACL rules for private subnets"
  type = list(object({
    rule_number = number
    protocol    = string
    from_port   = number
    to_port     = number
    cidr_block  = string
    action      = string
  }))
  default = [
    {
      rule_number = 100
      protocol    = "tcp"
      from_port   = 443
      to_port     = 443
      cidr_block  = "0.0.0.0/0"
      action      = "allow"
    },
  ]
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, 2)
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  instance_tenancy     = var.instance_tenancy
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "${var.name_prefix}-vpc"
  }
}

resource "aws_subnet" "private" {
  count             = length(var.private_subnets)
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnets[count.index]
  availability_zone = local.azs[count.index]

  tags = {
    Name = "${var.name_prefix}-private-subnet-${count.index + 1}"
  }
}

resource "aws_route_table" "private" {
  count  = length(var.private_subnets)
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.name_prefix}-private-rt-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private" {
  count          = length(var.private_subnets)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id          = aws_vpc.main.id
  service_name    = "com.amazonaws.${var.region}.s3"
  vpc_endpoint_type = "Gateway"

  tags = {
    Name = "${var.name_prefix}-s3-gateway-endpoint"
  }
}

resource "aws_vpc_endpoint_route_table_association" "s3_private" {
  count           = length(var.private_subnets)
  route_table_id  = aws_route_table.private[count.index].id
  vpc_endpoint_id = aws_vpc_endpoint.s3.id
}

resource "aws_network_acl" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.name_prefix}-private-acl"
  }
}

resource "aws_network_acl_rule" "private_inbound" {
  count          = length(var.public_inbound_acl_rules)
  network_acl_id = aws_network_acl.private.id
  rule_number    = var.public_inbound_acl_rules[count.index].rule_number
  egress         = false
  protocol       = var.public_inbound_acl_rules[count.index].protocol
  rule_action    = var.public_inbound_acl_rules[count.index].action
  cidr_block     = var.public_inbound_acl_rules[count.index].cidr_block
  from_port      = var.public_inbound_acl_rules[count.index].from_port
  to_port        = var.public_inbound_acl_rules[count.index].to_port
}

resource "aws_network_acl_rule" "private_outbound" {
  count          = length(var.public_outbound_acl_rules)
  network_acl_id = aws_network_acl.private.id
  rule_number    = var.public_outbound_acl_rules[count.index].rule_number
  egress         = true
  protocol       = var.public_outbound_acl_rules[count.index].protocol
  rule_action    = var.public_outbound_acl_rules[count.index].action
  cidr_block     = var.public_outbound_acl_rules[count.index].cidr_block
  from_port      = var.public_outbound_acl_rules[count.index].from_port
  to_port        = var.public_outbound_acl_rules[count.index].to_port
}

resource "aws_network_acl_association" "private" {
  count          = length(var.private_subnets)
  network_acl_id = aws_network_acl.private.id
  subnet_id      = aws_subnet.private[count.index].id
}

variable "username" {
  description = "IAM user name"
  type        = string
  default     = "my_vpn_infra_user"
}

variable "group_name" {
  description = "IAM group name"
  type        = string
  default     = "my-vpn-infra-group"
}

variable "membership_name" {
  description = "IAM group membership name"
  type        = string
  default     = "my-vpn-infra-manager-group"
}

variable "project_tag" {
  description = "Value for the ProjectTag tag on all IAM resources"
  type        = string
  default     = "my-vpn-tag"
}

variable "policy_path" {
  description = "Path for all IAM policies"
  type        = string
  default     = "/my_vpn_infra/"
}

locals {
  tags = {
    ProjectTag = var.project_tag
  }
}

resource "aws_iam_user" "this" {
  name          = var.username
  force_destroy = true
  tags          = local.tags
}

resource "aws_iam_access_key" "this" {
  user    = aws_iam_user.this.name
  status  = "Active"
}

resource "aws_iam_group" "this" {
  name = var.group_name
}

resource "aws_iam_group_membership" "this" {
  name  = var.membership_name
  group = aws_iam_group.this.name
  users = [aws_iam_user.this.name]
}

# ---------------------------------------------------------------------------
# Policy: basic_policy
# ---------------------------------------------------------------------------
resource "aws_iam_policy" "basic" {
  name   = "${var.username}-basic"
  path   = var.policy_path
  policy = data.aws_iam_policy_document.basic.json
  tags   = local.tags
}

data "aws_iam_policy_document" "basic" {
  statement {
    effect = "Allow"
    actions = [
      "sts:GetCallerIdentity",
    ]
    resources = ["*"]
  }
}

# ---------------------------------------------------------------------------
# Policy: create_policy
# ---------------------------------------------------------------------------
resource "aws_iam_policy" "create" {
  name   = "${var.username}-create"
  path   = var.policy_path
  policy = data.aws_iam_policy_document.create.json
  tags   = local.tags
}

data "aws_iam_policy_document" "create" {
  statement {
    effect = "Allow"
    actions = [
      "ec2:CreateKeyPair",
      "ec2:CreateVpc",
      "ec2:CreateSubnet",
      "ec2:CreateInternetGateway",
      "ec2:CreateRoute",
      "ec2:CreateRouteTable",
      "ec2:CreateLocalGatewayRouteTableVpcAssociation",
      "ec2:CreateSecurityGroup",
      "ec2:AuthorizeSecurityGroupEgress",
      "ec2:AuthorizeSecurityGroupIngress",
      "ec2:CreateReplaceRootVolumeTask",
      "ec2:CreateTags",
      "ec2:AllocateAddress",
    ]
    resources = ["*"]
  }
}

# ---------------------------------------------------------------------------
# Policy: read_policy
# ---------------------------------------------------------------------------
resource "aws_iam_policy" "read" {
  name   = "${var.username}-read"
  path   = var.policy_path
  policy = data.aws_iam_policy_document.read.json
  tags   = local.tags
}

data "aws_iam_policy_document" "read" {
  statement {
    effect = "Allow"
    actions = [
      "ec2:Describe*",
    ]
    resources = ["*"]
  }
}

# ---------------------------------------------------------------------------
# Policy: update_policy
# ---------------------------------------------------------------------------
resource "aws_iam_policy" "update" {
  name   = "${var.username}-update"
  path   = var.policy_path
  policy = data.aws_iam_policy_document.update.json
  tags   = local.tags
}

data "aws_iam_policy_document" "update" {
  statement {
    effect = "Allow"
    actions = [
      "ec2:Modify*",
      "ec2:Associate*",
      "ec2:AttachInternetGateway",
      "ec2:Replace*",
      "ec2:Update*",
    ]
    resources = ["*"]
  }
}

# ---------------------------------------------------------------------------
# Policy: delete_policy
# ---------------------------------------------------------------------------
resource "aws_iam_policy" "delete" {
  name   = "${var.username}-delete"
  path   = var.policy_path
  policy = data.aws_iam_policy_document.delete.json
  tags   = local.tags
}

data "aws_iam_policy_document" "delete" {
  statement {
    effect = "Allow"
    actions = [
      "ec2:Delete*",
      "ec2:Detach*",
      "ec2:Disassociate*",
      "ec2:Release*",
      "ec2:Revoke*",
    ]
    resources = ["*"]
  }
}

# ---------------------------------------------------------------------------
# Policy: instance_policy
# ---------------------------------------------------------------------------
resource "aws_iam_policy" "instance" {
  name   = "${var.username}-instance"
  path   = var.policy_path
  policy = data.aws_iam_policy_document.instance.json
  tags   = local.tags
}

data "aws_iam_policy_document" "instance" {
  statement {
    effect = "Allow"
    actions = [
      "ec2:RunInstances",
      "ec2:StartInstances",
      "ec2:ResetInstanceAttribute",
      "ec2:ModifyInstanceAttribute",
      "ec2:StopInstances",
      "ec2:TerminateInstances",
      "ec2:RebootInstances",
    ]
    resources = ["*"]
  }
}

# ---------------------------------------------------------------------------
# Policy: terraform_backend_access
# ---------------------------------------------------------------------------
resource "aws_iam_policy" "backend" {
  name   = "${var.username}-backend"
  path   = var.policy_path
  policy = data.aws_iam_policy_document.backend.json
  tags   = local.tags
}

data "aws_iam_policy_document" "backend" {
  statement {
    effect = "Allow"
    actions = [
      "dynamodb:DescribeTable",
      "dynamodb:GetItem",
      "dynamodb:PutItem",
      "dynamodb:DeleteItem",
    ]
    resources = ["*"]
  }

  statement {
    effect = "Allow"
    actions = [
      "s3:ListBucket",
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
    ]
    resources = ["*"]
  }
}

# ---------------------------------------------------------------------------
# Attach all policies to the IAM group
# ---------------------------------------------------------------------------
resource "aws_iam_group_policy_attachment" "basic" {
  group      = aws_iam_group.this.name
  policy_arn = aws_iam_policy.basic.arn
}

resource "aws_iam_group_policy_attachment" "create" {
  group      = aws_iam_group.this.name
  policy_arn = aws_iam_policy.create.arn
}

resource "aws_iam_group_policy_attachment" "read" {
  group      = aws_iam_group.this.name
  policy_arn = aws_iam_policy.read.arn
}

resource "aws_iam_group_policy_attachment" "update" {
  group      = aws_iam_group.this.name
  policy_arn = aws_iam_policy.update.arn
}

resource "aws_iam_group_policy_attachment" "delete" {
  group      = aws_iam_group.this.name
  policy_arn = aws_iam_policy.delete.arn
}

resource "aws_iam_group_policy_attachment" "instance" {
  group      = aws_iam_group.this.name
  policy_arn = aws_iam_policy.instance.arn
}

resource "aws_iam_group_policy_attachment" "backend" {
  group      = aws_iam_group.this.name
  policy_arn = aws_iam_policy.backend.arn
}

variable "existing_vpc_id" {
  type        = string
  default     = ""
  description = "ID of an existing VPC. If empty, a new VPC is created."
}

variable "environment" {
  type        = string
  default     = "DEV"
  description = "Environment prefix used for resource naming."
}

variable "main_cidr" {
  type        = string
  default     = "10.0.0.0/16"
  description = "CIDR block for the VPC."
}

variable "craete_private_subnet" {
  type        = bool
  default     = false
  description = "When true, creates private subnets with a NAT Gateway."
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_id      = var.existing_vpc_id != "" ? var.existing_vpc_id : aws_vpc.main[0].id
  azs         = slice(data.aws_availability_zones.available.names, 0, 2)
  name_prefix = var.environment
}

# ---------------------------------------------------------------------------
# VPC (conditional)
# ---------------------------------------------------------------------------
resource "aws_vpc" "main" {
  count                = var.existing_vpc_id == "" ? 1 : 0
  cidr_block           = var.main_cidr
  enable_dns_hostnames = true

  tags = {
    Name        = "${local.name_prefix}-VPC"
    Environment = var.environment
  }
}

# ---------------------------------------------------------------------------
# Public subnets (always created)
# ---------------------------------------------------------------------------
resource "aws_subnet" "public" {
  count             = 2
  vpc_id            = local.vpc_id
  cidr_block        = cidrsubnet(var.main_cidr, 8, count.index + 1)
  availability_zone = local.azs[count.index]

  tags = {
    Name        = "${local.name_prefix}-Public-Subnet-${count.index + 1}"
    Tier        = "Public"
    Environment = var.environment
  }
}

# ---------------------------------------------------------------------------
# Internet Gateway
# ---------------------------------------------------------------------------
resource "aws_internet_gateway" "main" {
  vpc_id = local.vpc_id

  tags = {
    Name        = "${local.name_prefix}-IGW"
    Environment = var.environment
  }
}

# ---------------------------------------------------------------------------
# Public route table
# ---------------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = local.vpc_id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name        = "${local.name_prefix}-Public-RT"
    Tier        = "Public"
    Environment = var.environment
  }
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# Private subnets and NAT Gateway (conditional)
# ---------------------------------------------------------------------------
resource "aws_subnet" "private" {
  count             = var.craete_private_subnet ? 2 : 0
  vpc_id            = local.vpc_id
  cidr_block        = cidrsubnet(var.main_cidr, 8, count.index + 10)
  availability_zone = local.azs[count.index]

  tags = {
    Name        = "${local.name_prefix}-Private-Subnet-${count.index + 1}"
    Tier        = "Private"
    Environment = var.environment
  }
}

resource "aws_eip" "nat" {
  count  = var.craete_private_subnet ? 1 : 0
  domain = "vpc"

  tags = {
    Name        = "${local.name_prefix}-NAT-EIP"
    Environment = var.environment
  }
}

resource "aws_nat_gateway" "main" {
  count             = var.craete_private_subnet ? 1 : 0
  allocation_id     = aws_eip.nat[0].id
  subnet_id         = aws_subnet.public[0].id
  connectivity_type = "public"

  tags = {
    Name        = "${local.name_prefix}-NAT-GW"
    Environment = var.environment
  }
}

resource "aws_route_table" "private" {
  count  = var.craete_private_subnet ? 1 : 0
  vpc_id = local.vpc_id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[0].id
  }

  tags = {
    Name        = "${local.name_prefix}-Private-RT"
    Tier        = "Private"
    Environment = var.environment
  }
}

resource "aws_route_table_association" "private" {
  count          = var.craete_private_subnet ? 2 : 0
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[0].id
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws    = { source = "hashicorp/aws", version = ">= 5.0" }
    random = { source = "hashicorp/random", version = ">= 3.0" }
  }
}

################################################################################
# VARIABLES
################################################################################

variable "create" {
  description = "Whether to create the primary SQS queue and its associated resources."
  type        = bool
  default     = true
}

variable "name" {
  description = "Name of the primary queue. Queue names must contain only alphanumeric characters, hyphens, and underscores. For FIFO queues the `.fifo` suffix is appended automatically when not already supplied, and it is stripped automatically for standard queues."
  type        = string
  default     = null
}

variable "name_prefix" {
  description = "Name prefix for the primary queue. For standard queues a unique suffix is appended by AWS. For FIFO queues (where the generated name must end in `.fifo`), a deterministic unique name is built from this prefix instead."
  type        = string
  default     = null
}

variable "fifo_queue" {
  description = "Whether the queues (primary and dead-letter) are FIFO queues. FIFO queues cannot be changed to standard queues later."
  type        = bool
  default     = false
}

variable "sqs_managed_sse_enabled" {
  description = "Whether to use SQS-managed server-side encryption (SSE-SQS). Applied automatically whenever `kms_master_key_id` is not provided."
  type        = bool
  default     = true
}

variable "kms_master_key_id" {
  description = "The ID of a customer-managed AWS KMS key for SSE, an alias name or ARN. When provided, `sqs_managed_sse_enabled` is ignored and SSE-KMS is used."
  type        = string
  default     = null
}

variable "kms_data_key_reuse_period_seconds" {
  description = "Length of time, in seconds, for which SQS can reuse a data key before calling AWS KMS again. Only applies when a customer-managed KMS key is set."
  type        = number
  default     = null
}

variable "delay_seconds" {
  description = "The time in seconds that the delivery of all messages in the queue will be delayed."
  type        = number
  default     = 0
}

variable "max_message_size" {
  description = "The limit of how many bytes a message can contain before SQS rejects it."
  type        = number
  default     = 262144
}

variable "message_retention_seconds" {
  description = "The number of seconds SQS retains a message."
  type        = number
  default     = 345600
}

variable "receive_wait_time_seconds" {
  description = "The time for which a ReceiveMessage call waits for a message to arrive (long polling)."
  type        = number
  default     = 0
}

variable "visibility_timeout_seconds" {
  description = "The visibility timeout for the queue."
  type        = number
  default     = 30
}

variable "content_based_deduplication" {
  description = "Whether SQS uses content-based deduplication for FIFO queues."
  type        = bool
  default     = false
}

variable "deduplication_scope" {
  description = "Specifies whether message deduplication occurs at the message group or queue level. Valid values are `messageGroup` and `queue`."
  type        = string
  default     = null
}

variable "fifo_throughput_limit" {
  description = "Specifies whether the FIFO queue throughput quota applies to the entire queue or per message group. Valid values are `perQueue` and `perMessageGroupId`."
  type        = string
  default     = null
}

variable "tags" {
  description = "A map of tags to add to all resources."
  type        = map(string)
  default     = {}
}

variable "create_queue_policy" {
  description = "Whether to create and attach a queue policy to the primary queue. When enabled, the policy is assembled from `source_queue_policy_documents`, `override_queue_policy_documents`, and any `queue_policy_statements`."
  type        = bool
  default     = false
}

variable "source_queue_policy_documents" {
  description = "List of IAM policy JSON documents to merge as the source (base) of the primary queue policy."
  type        = list(string)
  default     = []
}

variable "override_queue_policy_documents" {
  description = "List of IAM policy JSON documents to merge and override statements in the primary queue policy."
  type        = list(string)
  default     = []
}

variable "queue_policy_statements" {
  description = "Map of IAM policy statements to render into the primary queue policy. When a statement omits `resources`, it defaults to the primary queue ARN."
  type        = any
  default     = {}
}

variable "create_dlq" {
  description = "Whether to create a dead-letter queue for the primary queue and attach a redrive policy to it."
  type        = bool
  default     = false
}

variable "dlq_name" {
  description = "Name of the dead-letter queue. Defaults to the primary queue name suffixed with `-dlq` (with the `.fifo` suffix managed automatically for FIFO queues)."
  type        = string
  default     = null
}

variable "dlq_name_prefix" {
  description = "Name prefix of the dead-letter queue. For standard queues a unique suffix is appended by AWS. For FIFO queues a deterministic unique name is built from this prefix instead."
  type        = string
  default     = null
}

variable "dlq_kms_master_key_id" {
  description = "The ID of a customer-managed AWS KMS key for dead-letter queue SSE. Falls back to `kms_master_key_id` (and then SQS-managed SSE) when not provided."
  type        = string
  default     = null
}

variable "dlq_sqs_managed_sse_enabled" {
  description = "Whether the dead-letter queue uses SQS-managed SSE. Falls back to `sqs_managed_sse_enabled` when not provided."
  type        = bool
  default     = null
}

variable "max_receive_count" {
  description = "The maximum number of times a message can be received by the primary queue before it is moved to the dead-letter queue."
  type        = number
  default     = 5
}

variable "create_dlq_redrive_allow_policy" {
  description = "Whether to attach a redrive allow policy to the dead-letter queue that restricts redrive permissions to the primary queue (`redrivePermission = \"byQueue\"`)."
  type        = bool
  default     = true
}

variable "dlq_tags" {
  description = "Additional tags for the dead-letter queue (merged with `tags`)."
  type        = map(string)
  default     = {}
}

################################################################################
# RANDOM SUFFIXES
################################################################################

# FIFO queue names must end in ".fifo". The AWS provider appends a random
# suffix after `name_prefix`, which would break that requirement, so a full
# unique name is generated here instead when a FIFO queue is unnamed.
resource "random_id" "this" {
  count = var.create && var.fifo_queue && var.name == null ? 1 : 0

  byte_length = 4
}

resource "random_id" "dlq" {
  count = var.create && var.create_dlq && var.fifo_queue && var.dlq_name == null && var.dlq_name_prefix != null ? 1 : 0

  byte_length = 4
}

################################################################################
# LOCALS
################################################################################

locals {
  # Effective name of the primary queue with automatic ".fifo" suffix handling
  queue_name = var.create ? (
    var.name != null ? (
      var.fifo_queue ? (
        endswith(var.name, ".fifo") ? var.name : format("%s.fifo", var.name)
      ) : trimsuffix(var.name, ".fifo")
    ) : null
  ) : null

  # Deterministic full name for FIFO queues using a name_prefix (or auto-generated)
  fifo_queue_name = var.create ? (
    var.fifo_queue && var.name == null ? (
      var.name_prefix != null ? format("%s%s.fifo", trimsuffix(var.name_prefix, ".fifo"), random_id.this[0].hex) : format("sqs-%s.fifo", random_id.this[0].hex)
    ) : null
  ) : null

  queue_name_effective = try(coalesce(local.queue_name, local.fifo_queue_name), null)

  queue_name_prefix_effective = local.queue_name_effective == null && var.name_prefix != null ? var.name_prefix : null

  # Effective name of the dead-letter queue (inherits FIFO configuration and
  # defaults to the primary queue name suffixed with "-dlq")
  dlq_name = var.create && var.create_dlq ? (
    var.dlq_name != null ? (
      var.fifo_queue ? (
        endswith(var.dlq_name, ".fifo") ? var.dlq_name : format("%s.fifo", var.dlq_name)
      ) : trimsuffix(var.dlq_name, ".fifo")
      ) : (
      var.fifo_queue ? (
        var.dlq_name_prefix != null ? format("%s%s.fifo", trimsuffix(var.dlq_name_prefix, ".fifo"), random_id.dlq[0].hex) : (
          local.queue_name_effective != null ? format("%s-dlq.fifo", trimsuffix(local.queue_name_effective, ".fifo")) : null
        )
        ) : (
        var.dlq_name_prefix != null ? null : (
          local.queue_name_effective != null ? format("%s-dlq", local.queue_name_effective) : null
        )
      )
    )
  ) : null

  dlq_name_prefix = var.create && var.create_dlq ? (
    var.dlq_name == null && !var.fifo_queue && var.dlq_name_prefix != null ? var.dlq_name_prefix : (
      var.dlq_name == null && !var.fifo_queue && var.dlq_name_prefix == null && local.queue_name_effective == null && var.name_prefix != null ? format("%s-dlq", trimsuffix(var.name_prefix, "-")) : null
    )
  ) : null

  # Encryption for the primary queue: SQS-managed SSE unless a custom KMS key is supplied
  sqs_managed_sse_enabled = var.kms_master_key_id == null ? var.sqs_managed_sse_enabled : null

  # Encryption for the dead-letter queue falls back to the primary queue settings
  dlq_kms_master_key_id       = try(coalesce(var.dlq_kms_master_key_id, var.kms_master_key_id), null)
  dlq_sqs_managed_sse_enabled = coalesce(var.dlq_sqs_managed_sse_enabled, var.sqs_managed_sse_enabled)
}

################################################################################
# PRIMARY QUEUE
################################################################################

resource "aws_sqs_queue" "this" {
  count = var.create ? 1 : 0

  content_based_deduplication       = var.content_based_deduplication
  deduplication_scope               = var.deduplication_scope
  delay_seconds                     = var.delay_seconds
  fifo_queue                        = var.fifo_queue
  fifo_throughput_limit             = var.fifo_throughput_limit
  kms_data_key_reuse_period_seconds = var.kms_master_key_id != null ? var.kms_data_key_reuse_period_seconds : null
  kms_master_key_id                 = var.kms_master_key_id
  max_message_size                  = var.max_message_size
  message_retention_seconds         = var.message_retention_seconds
  name                              = local.queue_name_effective
  name_prefix                       = local.queue_name_prefix_effective
  receive_wait_time_seconds         = var.receive_wait_time_seconds
  sqs_managed_sse_enabled           = local.sqs_managed_sse_enabled
  visibility_timeout_seconds        = var.visibility_timeout_seconds

  tags = var.tags
}

################################################################################
# DEAD-LETTER QUEUE
################################################################################

resource "aws_sqs_queue" "dlq" {
  count = var.create && var.create_dlq ? 1 : 0

  content_based_deduplication       = var.content_based_deduplication
  deduplication_scope               = var.deduplication_scope
  delay_seconds                     = var.delay_seconds
  fifo_queue                        = var.fifo_queue
  fifo_throughput_limit             = var.fifo_throughput_limit
  kms_data_key_reuse_period_seconds = local.dlq_kms_master_key_id != null ? var.kms_data_key_reuse_period_seconds : null
  kms_master_key_id                 = local.dlq_kms_master_key_id
  max_message_size                  = var.max_message_size
  message_retention_seconds         = var.message_retention_seconds
  name                              = local.dlq_name
  name_prefix                       = local.dlq_name_prefix
  receive_wait_time_seconds         = var.receive_wait_time_seconds
  sqs_managed_sse_enabled           = local.dlq_kms_master_key_id != null ? null : local.dlq_sqs_managed_sse_enabled
  visibility_timeout_seconds        = var.visibility_timeout_seconds

  tags = merge(var.tags, var.dlq_tags)
}

################################################################################
# QUEUE POLICY
################################################################################

data "aws_iam_policy_document" "this" {
  count = var.create && var.create_queue_policy ? 1 : 0

  source_policy_documents   = var.source_queue_policy_documents
  override_policy_documents = var.override_queue_policy_documents

  dynamic "statement" {
    for_each = var.queue_policy_statements

    content {
      sid           = lookup(statement.value, "sid", statement.key)
      effect        = statement.value.effect
      actions       = statement.value.actions
      resources     = try(statement.value.resources, null) != null ? statement.value.resources : [aws_sqs_queue.this[0].arn]
      not_actions   = try(statement.value.not_actions, [])
      not_resources = try(statement.value.not_resources, [])

      dynamic "principals" {
        for_each = try(statement.value.principals, [])

        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = try(statement.value.conditions, [])

        content {
          test     = condition.value.test
          values   = condition.value.values
          variable = condition.value.variable
        }
      }
    }
  }
}

# Attached via a dedicated resource (rather than the queue's `policy` argument)
# to avoid a self-referential dependency when statements default to the queue ARN.
resource "aws_sqs_queue_policy" "this" {
  count = var.create && var.create_queue_policy ? 1 : 0

  queue_url = aws_sqs_queue.this[0].url
  policy    = data.aws_iam_policy_document.this[0].json
}

################################################################################
# REDRIVE POLICY
################################################################################

resource "aws_sqs_queue_redrive_policy" "this" {
  count = var.create && var.create_dlq ? 1 : 0

  queue_url = aws_sqs_queue.this[0].url
  redrive_policy = jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq[0].arn
    maxReceiveCount     = var.max_receive_count
  })
}

resource "aws_sqs_queue_redrive_allow_policy" "dlq" {
  count = var.create && var.create_dlq && var.create_dlq_redrive_allow_policy ? 1 : 0

  queue_url = aws_sqs_queue.dlq[0].url
  redrive_allow_policy = jsonencode({
    redrivePermission = "byQueue"
    sourceQueueArns   = [aws_sqs_queue.this[0].arn]
  })
}

################################################################################
# OUTPUTS
################################################################################

output "queue_id" {
  description = "URL of the primary SQS queue"
  value       = try(aws_sqs_queue.this[0].id, null)
}

output "queue_name" {
  description = "Name of the primary SQS queue"
  value       = local.queue_name_effective
}

output "queue_arn" {
  description = "ARN of the primary SQS queue"
  value       = try(aws_sqs_queue.this[0].arn, null)
}

output "queue_url" {
  description = "URL of the primary SQS queue"
  value       = try(aws_sqs_queue.this[0].url, null)
}

output "dlq_id" {
  description = "URL of the dead-letter SQS queue"
  value       = try(aws_sqs_queue.dlq[0].id, null)
}

output "dlq_name" {
  description = "Name of the dead-letter SQS queue"
  value       = local.dlq_name
}

output "dlq_arn" {
  description = "ARN of the dead-letter SQS queue"
  value       = try(aws_sqs_queue.dlq[0].arn, null)
}

output "dlq_url" {
  description = "URL of the dead-letter SQS queue"
  value       = try(aws_sqs_queue.dlq[0].url, null)
}

# IAM infrastructure for load balancer monitoring automation

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

# IAM users under /system/ path
resource "aws_iam_user" "loadbalancer" {
  name = "loadbalancer"
  path = "/system/"
}

resource "aws_iam_user" "loadbalancer2" {
  name = "loadbalancer2"
  path = "/system/"
}

resource "aws_iam_user" "loadbalancer3" {
  name = "loadbalancer3"
  path = "/system/"
}

# Access keys for each user
resource "aws_iam_access_key" "loadbalancer" {
  user = aws_iam_user.loadbalancer.name
