variable "backup_name" {
  description = "Name used to name the backup vault, plan, IAM role, and selections"
  type        = string
  default     = "default-backup"
}

variable "account_type" {
  description = "Account type: 'workload' creates IAM role + plan + selections; 'backup' creates vault only"
  type        = string
  default     = "workload"

  validation {
    condition     = contains(["workload", "backup"], var.account_type)
    error_message = "account_type must be either 'workload' or 'backup'."
  }
}

variable "kms_key_arn" {
  description = "Optional KMS key ARN for vault encryption"
  type        = string
  default     = null
}

variable "vault_policy" {
  description = "Optional JSON resource policy string for the backup vault"
  type        = string
  default     = null
}

variable "min_retention_days" {
  description = "Minimum retention days for vault lock (enables vault lock when set)"
  type        = number
  default     = null
}

variable "max_retention_days" {
  description = "Maximum retention days for vault lock"
  type        = number
  default     = null
}

variable "changeable_for_days" {
  description = "Number of days the vault lock configuration is changeable"
  type        = number
  default     = null
}

variable "enable_aws_backup_vault_notifications" {
  description = "Enable SNS notifications for the backup vault"
  type        = bool
  default     = false
}

variable "sns_topic_arn" {
  description = "SNS topic ARN for backup vault notifications (required when notifications are enabled)"
  type        = string
  default     = null
}

variable "backup_events" {
  description = "List of backup event types for vault notifications"
  type        = list(string)
  default     = ["BACKUP_JOB_FAILED", "COPY_JOB_FAILED"]
}

variable "rule_schedule" {
  description = "Cron schedule for the backup plan rule"
  type        = string
  default     = "cron(0 5 * * ? *)"
}

variable "start_window" {
  description = "Start window in minutes for the backup rule"
  type        = number
  default     = 60
}

variable "completion_window" {
  description = "Completion window in minutes for the backup rule"
  type        = number
  default     = 120
}

variable "cold_storage_after_days" {
  description = "Days after which to transition recovery points to cold storage"
  type        = number
  default     = 30
}

variable "deletion_after_days" {
  description = "Days after which to delete recovery points"
  type        = number
  default     = 120
}

variable "recovery_point_tags" {
  description = "Tags to apply to recovery points"
  type        = map(string)
  default     = {}
}

variable "copy_actions" {
  description = "Cross-region / cross-account copy actions for the backup plan rule"
  type = list(object({
    destination_vault_arn = string
    lifecycle = optional(object({
      cold_storage_after = optional(number)
      delete_after       = optional(number)
    }))
  }))
  default = []
}

variable "selection_resources" {
  description = "List of ARNs for a resource-based backup selection (in addition to the always-present tag-based selection)"
  type        = list(string)
  default     = null
}

# ---------------------------------------------------------------------------
# Validations
# ---------------------------------------------------------------------------
check "sns_topic_required" {
  assert {
    condition     = !var.enable_aws_backup_vault_notifications || var.sns_topic_arn != null
    error_message = "sns_topic_arn must be provided when enable_aws_backup_vault_notifications is true."
  }
}

# ---------------------------------------------------------------------------
# Data sources
# ---------------------------------------------------------------------------
data "aws_partition" "current" {}

locals {
  vault_name = var.backup_name
}

# ---------------------------------------------------------------------------
# Backup Vault
# ---------------------------------------------------------------------------
resource "aws_backup_vault" "this" {
  name        = local.vault_name
  kms_key_arn = var.kms_key_arn

  tags = {
    Name = local.vault_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Vault Lock Configuration
# ---------------------------------------------------------------------------
resource "aws_backup_vault_lock_configuration" "this" {
  count = var.min_retention_days != null ? 1 : 0

  backup_vault_name   = aws_backup_vault.this.name
  min_retention_days  = var.min_retention_days
  max_retention_days  = var.max_retention_days
  changeable_for_days = var.changeable_for_days
}

# ---------------------------------------------------------------------------
# Vault Resource Policy
# ---------------------------------------------------------------------------
resource "aws_backup_vault_policy" "this" {
  count = var.vault_policy != null ? 1 : 0

  backup_vault_name = aws_backup_vault.this.name
  policy            = var.vault_policy
}

# ---------------------------------------------------------------------------
# Vault Notifications (SNS)
# ---------------------------------------------------------------------------
resource "aws_backup_vault_notifications" "this" {
  count = var.enable_aws_backup_vault_notifications ? 1 : 0

  backup_vault_name   = aws_backup_vault.this.name
  sns_topic_arn       = var.sns_topic_arn
  backup_vault_events = var.backup_events
}

# ===========================================================================
# Workload-only resources (IAM role, backup plan, selections)
# ===========================================================================

# ---------------------------------------------------------------------------
# IAM Role for AWS Backup
# ---------------------------------------------------------------------------
resource "aws_iam_role" "backup" {
  count = var.account_type == "workload" ? 1 : 0

  name               = "aws-backup-${var.backup_name}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "aws-backup-${var.backup_name}"
  }
}

resource "aws_iam_role_policy_attachment" "backup" {
  count = var.account_type == "workload" ? 1 : 0

  role       = aws_iam_role.backup[0].name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

# ---------------------------------------------------------------------------
# Backup Plan
# ---------------------------------------------------------------------------
resource "aws_backup_plan" "this" {
  count = var.account_type == "workload" ? 1 : 0

  name = "plan-${var.backup_name}-backup"

  rule {
    rule_name         = "${var.backup_name}-rule"
    target_vault_name = aws_backup_vault.this.name
    schedule          = var.rule_schedule
    start_window      = var.start_window
    completion_window = var.completion_window
    recovery_point_tags = var.recovery_point_tags

    lifecycle {
      cold_storage_after = var.cold_storage_after_days
      delete_after       = var.deletion_after_days
    }

    dynamic "copy_action" {
      for_each = var.copy_actions
      content {
        destination_vault_arn = copy_action.value.destination_vault_arn
        dynamic "lifecycle" {
          for_each = copy_action.value.lifecycle != null ? [copy_action.value.lifecycle] : []
          content {
            cold_storage_after = try(lifecycle.value.cold_storage_after, null)
            delete_after       = try(lifecycle.value.delete_after, null)
          }
        }
      }
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Tag-based Backup Selection (always present for workload)
# ---------------------------------------------------------------------------
resource "aws_backup_selection" "tag_based" {
  count = var.account_type == "workload" ? 1 : 0

  plan_id      = aws_backup_plan.this[0].id
  name         = "${var.backup_name}-tag-selection"
  iam_role_arn = aws_iam_role.backup[0].arn

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "true"
  }
}

# ---------------------------------------------------------------------------
# Resource-based Backup Selection (additional, only when ARNs supplied)
# ---------------------------------------------------------------------------
resource "aws_backup_selection" "resource_based" {
  count = var.account_type == "workload" && var.selection_resources != null && length(var.selection_resources) > 0 ? 1 : 0

  plan_id      = aws_backup_plan.this[0].id
  name         = "${var.backup_name}-resource-selection"
  iam_role_arn = aws_iam_role.backup[0].arn
  resources    = var.selection_resources
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws  = { source = "hashicorp/aws" }
    null = { source = "hashicorp/null" }
  }
}

# Data sources – static provider metadata only
data "aws_partition" "current" {}
data "aws_region" "current" {}
data "aws_caller_identity" "current" {}

# Variables
variable "role_name_prefix" {
  description = "Prefix for the IAM role name. Defaults to 'config'."
  type        = string
  default     = "config"
}

# Locals
locals {
  role_name = var.role_name_prefix != null && var.role_name_prefix != "" ? var.role_name_prefix : "config"
}

# ---------------------------------------------------------------------------
# KMS key with automatic rotation
# ---------------------------------------------------------------------------
resource "aws_kms_key" "notifications" {
  description             = "Customer-managed KMS key for AWS Config notifications encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  rotation_period_in_days = 365
}

# ---------------------------------------------------------------------------
# SNS topic encrypted with the KMS key
# ---------------------------------------------------------------------------
resource "aws_sns_topic" "config_notifications" {
  name              = "${local.role_name}-notifications"
  kms_master_key_id = aws_kms_key.notifications.arn
}

# ---------------------------------------------------------------------------
# S3 snapshot storage bucket (force-destroy enabled)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "snapshot_storage" {
  bucket        = "${local.role_name}-snapshots-${data.aws_caller_identity.current.account_id}"
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "snapshot_storage" {
  bucket = aws_s3_bucket.snapshot_storage.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "snapshot_storage" {
  bucket = aws_s3_bucket.snapshot_storage.id

  rule {
    bucket_key_enabled = true
  }
}

# ---------------------------------------------------------------------------
# Configure SSE-KMS on the bucket (required by Trivy AWS-0132)
# ---------------------------------------------------------------------------
resource "null_resource" "sse_kms_config" {
  depends_on = [
    aws_s3_bucket.snapshot_storage,
    aws_kms_key.notifications,
  ]

  provisioner "local-exec" {
    interpreter = ["bash", "-c"]

    command = <<-EOT
      set -e
      BUCKET='${aws_s3_bucket.snapshot_storage.bucket}'
      REGION='${data.aws_region.current.region}'
      KMS_KEY='${aws_kms_key.notifications.arn}'

      SSE_CONFIG=$(jq -n \
        --arg kms "$KMS_KEY" \
        '{
          Rules: [
            {
              ApplyServerSideEncryptionByDefault: {
                SSEAlgorithm: "AES256",
                KMSMasterKeyID: $kms
              }
            }
          ]
        }')

      aws s3api put-bucket-encryption \
        --region "$REGION" \
        --bucket "$BUCKET" \
        --server-side-encryption-configuration "$SSE_CONFIG" 2>/dev/null || true
    EOT
  }
}

# ---------------------------------------------------------------------------
# IAM role for AWS Config
# ---------------------------------------------------------------------------
resource "aws_iam_role" "config_role" {
  name = "${local.role_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action    = "sts:AssumeRole"
        Effect    = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "config_role" {
  role       = aws_iam_role.config_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWS_ConfigRole"
}

resource "aws_iam_role_policy" "sns_publish" {
  name = "sns-publish"
  role = aws_iam_role.config_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action   = "sns:Publish"
        Effect   = "Allow"
        Resource = aws_sns_topic.config_notifications.arn
      }
    ]
  })
}

resource "aws_iam_role_policy" "s3_write" {
  name = "s3-write"
  role = aws_iam_role.config_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action   = ["s3:PutObject", "s3:GetObject", "s3:ListBucket"]
        Effect   = "Allow"
        Resource = [
          aws_s3_bucket.snapshot_storage.arn,
          "${aws_s3_bucket.snapshot_storage.arn}/*"
        ]
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# AWS Config configuration recorder
# ---------------------------------------------------------------------------
resource "aws_config_configuration_recorder" "main" {
  name     = "${local.role_name}-recorder"
  role_arn = aws_iam_role.config_role.arn

  recording_group {
    all_supported = true
  }
}

resource "aws_config_configuration_recorder_status" "main" {
  depends_on = [aws_config_delivery_channel.main]

  name       = aws_config_configuration_recorder.main.name
  is_enabled = true
}

# ---------------------------------------------------------------------------
# Config delivery channel – S3 snapshots + SNS notifications
# ---------------------------------------------------------------------------
resource "aws_config_delivery_channel" "main" {
  s3_bucket_name = aws_s3_bucket.snapshot_storage.bucket
  s3_key_prefix  = "awsconfig/records"
  sns_topic_arn  = aws_sns_topic.config_notifications.arn
}

# ---------------------------------------------------------------------------
# Eleven managed AWS Config rules (via AWS CLI – idempotent put-config-rule)
# ---------------------------------------------------------------------------
resource "null_resource" "config_rules" {
  depends_on = [
    aws_config_configuration_recorder_status.main,
    aws_config_delivery_channel.main,
  ]

  provisioner "local-exec" {
    interpreter = ["bash", "-c"]

    command = <<-EOT
      set -e

      REGION='${data.aws_region.current.region}'

      __put() {
        local name="$1" desc="$2" ident="$3" scope_json="$4" params_json="$5"

        local src_json
        src_json=$(jq -n --arg owner "AWS" --arg ident "$ident" '{Owner: $owner, SourceIdentifier: $ident}')

        local rule_json
        rule_json=$(jq -n \
          --arg name "$name" \
          --arg desc "$desc" \
          --arg src "$src_json" \
          --arg scope "$scope_json" \
          --arg params "$params_json" \
          '{
            ConfigRuleName: $name,
            Description: $desc,
            Scope: ($scope | fromjson),
            Source: ($src | fromjson),
            InputParameters: $params,
            MaximumExecutionFrequency: "TwentyFour_Hours"
          }')

        aws configservice put-config-rule \
          --region "$REGION" \
          --config-rule "$rule_json" 2>/dev/null || true
      }

      __put "cloudtrail-enabled" \
        "Checks that CloudTrail is enabled in the account" \
        "CLOUD_TRAIL_ENABLED" \
        '{"ComplianceResourceTypes":[]}' \
        '{}'

      __put "iam-pw-policy" \
        "Checks that the IAM password policy meets requirements" \
        "IAM_PASSWORD_POLICY" \
        '{"ComplianceResourceTypes":[]}' \
        '{}'

      __put "ec2-vpc" \
        "Checks that EC2 instances are deployed inside a VPC" \
        "INSTANCES_IN_VPC" \
        '{"ComplianceResourceTypes":[]}' \
        '{}'

      __put "root-mfa-enabled" \
        "Checks that the root account has MFA enabled" \
        "ROOT_ACCOUNT_MFA_ENABLED" \
        '{"ComplianceResourceTypes":[]}' \
        '{}'

      __put "acm-expiration-check" \
        "Checks for ACM certificates nearing expiration" \
        "ACM_CERTIFICATE_EXPIRATION_CHECK" \
        '{"ComplianceResourceTypes":[]}' \
        '{}'

      __put "ebs-inuse-check" \
        "Checks that EBS volumes are attached to running instances" \
        "EC2_VOLUME_INUSE_CHECK" \
        '{"ComplianceResourceTypes":[]}' \
        '{}'

      __put "ec2-imdsv2-check" \
        "Checks that EC2 instances have IMDSv2 enabled" \
        "EC2_IMDSV2_CHECK" \
        '{"ComplianceResourceTypes":[]}' \
        '{}'

      __put "rds-encrypted" \
        "Checks that RDS instances have storage encryption enabled" \
        "RDS_STORAGE_ENCRYPTED" \
        '{"ComplianceResourceTypes":[]}' \
        '{}'

      __put "rds-private" \
        "Checks that RDS instances are not publicly accessible" \
        "RDS_INSTANCE_PUBLIC_ACCESS_CHECK" \
        '{"ComplianceResourceTypes":[]}' \
        '{}'

      __put "rds-private-snapshots" \
        "Checks that RDS snapshots are not publicly accessible" \
        "RDS_SNAPSHOTS_PUBLIC_PROHIBITED" \
        '{"ComplianceResourceTypes":[]}' \
        '{}'

      __put "required-tags" \
        "Checks that S3 buckets have the required terraform.io and environment tags" \
        "REQUIRED_TAGS" \
        '{"ComplianceResourceTypes":["S3::Bucket"]}' \
        '{"tag1Key":"terraform.io","tag2Key":"environment"}'
    EOT
  }
}

locals {
  project       = "BJIT DevOps Task"
  author        = "Ariful Islam"
  vpc_cidr      = "10.0.0.0/16"
  public_cidrs  = ["10.0.4.0/24", "10.0.6.0/24", "10.0.8.0/24"]
  private_cidrs = ["10.0.10.0/24", "10.0.12.0/24", "10.0.14.0/24"]
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name    = "bjit-vpc"
    Project = local.project
    Author  = local.author
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name    = "bjit-igw"
    Project = local.project
    Author  = local.author
  }
}

# Public subnets (one per AZ, no auto-assign public IP)
resource "aws_subnet" "public" {
  count                   = length(local.public_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name    = "bjit-public-subnet-${count.index + 1}"
    Tier    = "public"
    Project = local.project
    Author  = local.author
  }
}

# Private subnets (one per AZ)
resource "aws_subnet" "private" {
  count             = length(local.private_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name    = "bjit-private-subnet-${count.index + 1}"
    Tier    = "private"
    Project = local.project
    Author  = local.author
  }
}

# Public route table shared by all public subnets, wired to Internet Gateway
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name    = "bjit-public-rt"
    Tier    = "public"
    Project = local.project
    Author  = local.author
  }
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Zone-specific private route tables (one per private subnet)
resource "aws_route_table" "private" {
  count  = length(aws_subnet.private)
  vpc_id = aws_vpc.main.id

  tags = {
    Name    = "bjit-private-rt-${count.index + 1}"
    Tier    = "private"
    Project = local.project
    Author  = local.author
  }
}

resource "aws_route_table_association" "private" {
  count          = length(aws_subnet.private)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# S3 Gateway VPC Endpoint associated with every private route table
resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id

  tags = {
    Name    = "bjit-s3-gateway-endpoint"
    Project = local.project
    Author  = local.author
  }
}

data "aws_region" "current" {}

# Security groups - outbound limited to the VPC CIDR
