variable "base_name" {
  description = "Prefix name for all resources"
  type        = string
  default     = "benchmark"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_public_cidrs" {
  description = "List of CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "subnet_private_cidrs" {
  description = "List of CIDR blocks for private subnets (set to null to skip)"
  type        = list(string)
  default     = null
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

locals {
  azs                  = data.aws_availability_zones.available.names
  public_subnet_count  = length(var.subnet_public_cidrs)
  private_enabled      = var.subnet_private_cidrs != null
  private_subnet_count = local.private_enabled ? length(var.subnet_private_cidrs) : 0

  # Public subnets use AZs starting from index 1 (second zone)
  public_azs = [
    for i in range(local.public_subnet_count) :
    local.azs[(i + 1) % length(local.azs)]
  ]

  # Private subnets use matching AZ indices
  private_azs = local.private_enabled ? [
    for i in range(local.private_subnet_count) :
    local.azs[(i + 1) % length(local.azs)]
  ] : []
}

# ---------------------------------------------------------------------------
# VPC
# ---------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true

  tags = {
    Name = "${var.base_name}-vpc"
  }
}

# ---------------------------------------------------------------------------
# Internet Gateway
# ---------------------------------------------------------------------------
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.base_name}-igw"
  }
}

# ---------------------------------------------------------------------------
# Public subnets
# ---------------------------------------------------------------------------
resource "aws_subnet" "public" {
  count             = local.public_subnet_count
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_public_cidrs[count.index]
  availability_zone = local.public_azs[count.index]

  tags = {
    Name = "${var.base_name}-public-${count.index + 1}"
  }
}

# ---------------------------------------------------------------------------
# Public route table with default route to IGW
# ---------------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.base_name}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = local.public_subnet_count
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# S3 Gateway Endpoint for public subnets
# ---------------------------------------------------------------------------
resource "aws_vpc_endpoint" "s3_public" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.public.id]

  tags = {
    Name = "${var.base_name}-s3-public-endpoint"
  }
}

# ---------------------------------------------------------------------------
# Private subnet infrastructure (conditional)
# ---------------------------------------------------------------------------

# Elastic IPs for NAT Gateways (one per public subnet)
resource "aws_eip" "nat" {
  count  = local.private_enabled ? local.public_subnet_count : 0
  domain = "vpc"

  tags = {
    Name = "${var.base_name}-nat-eip-${count.index + 1}"
  }
}

# NAT Gateways (one per public subnet)
resource "aws_nat_gateway" "main" {
  count         = local.private_enabled ? local.public_subnet_count : 0
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  depends_on = [aws_internet_gateway.main]

  tags = {
    Name = "${var.base_name}-nat-${count.index + 1}"
  }
}

# Private subnets
resource "aws_subnet" "private" {
  count             = local.private_enabled ? local.private_subnet_count : 0
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_private_cidrs[count.index]
  availability_zone = local.private_azs[count.index]

  tags = {
    Name = "${var.base_name}-private-${count.index + 1}"
  }
}

# Private route tables (one per NAT Gateway)
resource "aws_route_table" "private" {
  count  = local.private_enabled ? local.public_subnet_count : 0
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }

  tags = {
    Name = "${var.base_name}-private-rt-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private" {
  count          = local.private_enabled ? local.private_subnet_count : 0
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# S3 Gateway Endpoint for private subnets (dedicated)
resource "aws_vpc_endpoint" "s3_private" {
  count             = local.private_enabled ? 1 : 0
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id

  tags = {
    Name = "${var.base_name}-s3-private-endpoint"
  }
}

# ---------------------------------------------------------------------------
# ECR VPC Endpoints and Security Group
# ---------------------------------------------------------------------------

# Security group for ECR endpoints
resource "aws_security_group" "ecr" {
  name        = "${var.base_name}-ecr-endpoint"
  description = "Security group for ECR VPC endpoints"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "${var.base_name}-ecr-endpoint"
  }
}

# Egress: allow all traffic within VPC CIDR only
resource "aws_vpc_security_group_egress_rule" "ecr" {
  security_group_id = aws_security_group.ecr.id
  description       = "Egress to VPC CIDR"
  cidr_ipv4         = var.vpc_cidr
  ip_protocol       = "-1"
}

# Ingress: HTTPS (443) from each public subnet CIDR
resource "aws_vpc_security_group_ingress_rule" "ecr_public" {
  count             = local.public_subnet_count
  security_group_id = aws_security_group.ecr.id
  description       = "HTTPS from public subnet ${count.index + 1}"
  cidr_ipv4         = var.subnet_public_cidrs[count.index]
  from_port         = 443
  to_port           = 443
  ip_protocol       = "tcp"
}

# Ingress: HTTPS (443) from each private subnet CIDR (conditional)
resource "aws_vpc_security_group_ingress_rule" "ecr_private" {
  count             = local.private_enabled ? local.private_subnet_count : 0
  security_group_id = aws_security_group.ecr.id
  description       = "HTTPS from private subnet ${count.index + 1}"
  cidr_ipv4         = var.subnet_private_cidrs[count.index]
  from_port         = 443
  to_port           = 443
  ip_protocol       = "tcp"
}

# ECR API Interface Endpoint
resource "aws_vpc_endpoint" "ecr_api" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.region}.ecr.api"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  subnet_ids          = local.private_enabled ? aws_subnet.private[*].id : aws_subnet.public[*].id
  security_group_ids  = [aws_security_group.ecr.id]

  tags = {
    Name = "${var.base_name}-ecr-api-endpoint"
  }
}

# ECR Docker Interface Endpoint
resource "aws_vpc_endpoint" "ecr_dkr" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.region}.ecr.dkr"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  subnet_ids          = local.private_enabled ? aws_subnet.private[*].id : aws_subnet.public[*].id
  security_group_ids  = [aws_security_group.ecr.id]

  tags = {
    Name = "${var.base_name}-ecr-dkr-endpoint"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  az_names = slice(data.aws_availability_zones.available.names, 0, 2)
}

