}

# ------------------------------------------------
# Public Route Table 1 (RT_PUBRT-1)
# ------------------------------------------------
resource "aws_route_table" "RT_PUBRT_1" {
  vpc_id = aws_vpc.project.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.T_igw.id
  }

  tags = {
    Name = "RT_PUBRT-1"
  }
}

resource "aws_route_table_association" "pub_sub_1" {
  subnet_id      = aws_subnet.pub_sub_1.id
  route_table_id = aws_route_table.RT_PUBRT_1.id
}

# ------------------------------------------------
# Public Route Table 2 (RT_PUBRT-2)
# ------------------------------------------------
resource "aws_route_table" "RT_PUBRT_2" {
  vpc_id = aws_vpc.project.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.T_igw.id
  }

  tags = {
    Name = "RT_PUBRT-2"
  }
}

resource "aws_route_table_association" "pub_sub_2" {
  subnet_id      = aws_subnet.pub_sub_2.id
  route_table_id = aws_route_table.RT_PUBRT_2.id
}

# ------------------------------------------------
# Elastic IPs for NAT Gateways
# ------------------------------------------------
resource "aws_eip" "nat_1" {
  domain = "vpc"

  tags = {
    Name = "T-NAT1-eip-1"
  }
}

resource "aws_eip" "nat_2" {
  domain = "vpc"

  tags = {
    Name = "T-NAT1-eip-2"
  }
}

# ------------------------------------------------
# NAT Gateways
# ------------------------------------------------
resource "aws_nat_gateway" "T_NAT_1" {
  allocation_id = aws_eip.nat_1.id
  subnet_id     = aws_subnet.pub_sub_1.id

  tags = {
    Name = "T-NAT1"
  }
}

resource "aws_nat_gateway" "T_NAT_2" {
  allocation_id = aws_eip.nat_2.id
  subnet_id     = aws_subnet.pub_sub_2.id

  tags = {
    Name = "T-NAT1"
  }
}

# ------------------------------------------------
# Private Route Table 1 (RT_PVTRT-1) — routes via NAT-1
# ------------------------------------------------
resource "aws_route_table" "RT_PVTRT_1" {
  vpc_id = aws_vpc.project.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.T_NAT_1.id
  }

  tags = {
    Name = "RT_PVTRT-1"
  }
}

resource "aws_route_table_association" "pvt_sub_1" {
  subnet_id      = aws_subnet.pvt_sub_1.id
  route_table_id = aws_route_table.RT_PVTRT_1.id
}

# ------------------------------------------------
# Private Route Table 2 (RT_PVTRT-2) — routes via NAT-1
# ------------------------------------------------
resource "aws_route_table" "RT_PVTRT_2" {
  vpc_id = aws_vpc.project.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.T_NAT_1.id
  }

  tags = {
    Name = "RT_PVTRT-2"
  }
}

resource "aws_route_table_association" "pvt_sub_2" {
  subnet_id      = aws_subnet.pvt_sub_2.id
  route_table_id = aws_route_table.RT_PVTRT_2.id
}

# ------------------------------------------------
# Public Security Group — allow_tls
# ------------------------------------------------
resource "aws_security_group" "allow_tls" {
  name        = "allow_tls"
  description = "Public security group permitting HTTP (80), HTTPS (443) and SSH (22)"
  vpc_id      = aws_vpc.project.id
}

# HTTP inbound from anywhere
resource "aws_security_group_rule" "allow_tls_http_in" {
  type              = "ingress"
  security_group_id = aws_security_group.allow_tls.id
  from_port         = 80
  to_port           = 80
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
}

# HTTPS inbound from anywhere
resource "aws_security_group_rule" "allow_tls_https_in" {
  type              = "ingress"
  security_group_id = aws_security_group.allow_tls.id
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
}

# SSH inbound from admin range only
resource "aws_security_group_rule" "allow_tls_ssh_in" {
  type              = "ingress"
  security_group_id = aws_security_group.allow_tls.id
  from_port         = 22
  to_port           = 22
  protocol          = "tcp"
  cidr_blocks       = ["203.0.113.0/24"]
}

# Egress limited to VPC CIDR
resource "aws_security_group_rule" "allow_tls_egress" {
  type              = "egress"
  security_group_id = aws_security_group.allow_tls.id
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [aws_vpc.project.cidr_block]
}

# ------------------------------------------------
# Private Security Group — pvt-seg
# ------------------------------------------------
resource "aws_security_group" "pvt_seg" {
  name        = "pvt-seg"
  description = "Private security group allowing traffic only from the public security group"
  vpc_id      = aws_vpc.project.id
}

# HTTP inbound from public SG
resource "aws_security_group_rule" "pvt_seg_http_in" {
  type                     = "ingress"
  security_group_id        = aws_security_group.pvt_seg.id
  from_port                = 80
  to_port                  = 80
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.allow_tls.id
}

# HTTPS inbound from public SG
resource "aws_security_group_rule" "pvt_seg_https_in" {
  type                     = "ingress"
  security_group_id        = aws_security_group.pvt_seg.id
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.allow_tls.id
}

# SSH inbound from public SG
resource "aws_security_group_rule" "pvt_seg_ssh_in" {
  type                     = "ingress"
  security_group_id        = aws_security_group.pvt_seg.id
  from_port                = 22
  to_port                  = 22
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.allow_tls.id
}

# PostgreSQL inbound from public SG
resource "aws_security_group_rule" "pvt_seg_postgres_in" {
  type                     = "ingress"
  security_group_id        = aws_security_group.pvt_seg.id
  from_port                = 5432
  to_port                  = 5432
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.allow_tls.id
}

# Egress restricted exclusively to the public security group
resource "aws_security_group_rule" "pvt_seg_egress" {
  type                     = "egress"
  security_group_id        = aws_security_group.pvt_seg.id
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  source_security_group_id = aws_security_group.allow_tls.id
}

data "aws_region" "current" {}

# DynamoDB Table
resource "aws_dynamodb_table" "pets" {
  name         = "Pets"
  read_capacity  = 5
  write_capacity = 5

  attribute {
    name = "id"
    type = "S"
  }
  attribute {
    name = "PetType"
    type = "S"
  }

  hash_key     = "id"

  global_secondary_index {
    name               = "PetType-index"
    hash_key           = "PetType"
    projection_type    = "INCLUDE"
    non_key_attributes = ["PetName", "PetPrice"]
    read_capacity      = 5
    write_capacity     = 5
  }

  lifecycle {
    prevent_destroy = true
  }
}

# IAM Role for API Gateway to DynamoDB integration
resource "aws_iam_role" "apigw_dynamodb" {
  name = "apigw-dynamodb-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "apigw_dynamodb" {
  name   = "apigw-dynamodb-policy"
  role   = aws_iam_role.apigw_dynamodb.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "dynamodb:PutItem",
          "dynamodb:Query"
        ]
        Resource = [
          aws_dynamodb_table.pets.arn,
          "${aws_dynamodb_table.pets.arn}/index/*"
        ]
      }
    ]
  })
}

# IAM Role for API Gateway CloudWatch logging
resource "aws_iam_role" "apigw_cloudwatch" {
  name = "apigw-cloudwatch-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "apigw_cloudwatch" {
  name   = "apigw-cloudwatch-policy"
  role   = aws_iam_role.apigw_cloudwatch.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents",
          "logs:GetLogEvents"
        ]
        Resource = "*"
      }
    ]
  })
}

# CloudWatch Log Group
resource "aws_cloudwatch_log_group" "apigw" {
  name = "/aws/APIGW/terraform"
  retention_in_days = 7
}

# API Gateway Account (sets CloudWatch role for logging)
resource "aws_api_gateway_account" "main" {
  cloudwatch_role_arn = aws_iam_role.apigw_cloudwatch.arn
}

# REST API
resource "aws_api_gateway_rest_api" "main" {
  name = "APIGW DynamoDB Serverless Pattern Demo"
}

# Resources paths
resource "aws_api_gateway_resource" "pets" {
  rest_api_id = aws_api_gateway_rest_api.main.id
  parent_id   = aws_api_gateway_rest_api.main.root_resource_id
  path_part   = "pets"
}

resource "aws_api_gateway_resource" "pets_pettype" {
  rest_api_id = aws_api_gateway_rest_api.main.id
  parent_id   = aws_api_gateway_resource.pets.id
  path_part   = "{PetType}"
}

# POST /pets method
resource "aws_api_gateway_method" "post_pets" {
  rest_api_id      = aws_api_gateway_rest_api.main.id
  resource_id      = aws_api_gateway_resource.pets.id
  http_method      = "POST"
  authorization    = "NONE"
  api_key_required = true
}

resource "aws_api_gateway_integration" "post_pets" {
  rest_api_id             = aws_api_gateway_rest_api.main.id
  resource_id             = aws_api_gateway_resource.pets.id
  http_method             = aws_api_gateway_method.post_pets.http_method
  type                    = "HTTP"
  integration_http_method = "POST"
  uri                     = "https://dynamodb.${data.aws_region.current.region}.amazonaws.com/"
  credentials             = aws_iam_role.apigw_dynamodb.arn

  request_templates = {
    "application/json" = <<EOF
{
    "TableName": "Pets",
    "Item": {
        "id": {"S": "$context.requestId"},
        "PetType": {"S": "$input.path('$.PetType')"},
        "PetName": {"S": "$input.path('$.PetName')"},
        "PetPrice": {"N": "$input.path('$.PetPrice')"},
        "PetBoolean": {"BOOL": true}
    }
}
EOF
  }

  request_parameters = {
    "integration.request.header.X-Amz-Target" = "'DynamoDB_20120810.PutItem'"
    "integration.request.header.Content-Type" = "'application/json'"
  }
}

# GET /pets/{PetType} method
resource "aws_api_gateway_method" "get_pets_pettype" {
  rest_api_id      = aws_api_gateway_rest_api.main.id
  resource_id      = aws_api_gateway_resource.pets_pettype.id
  http_method      = "GET"
  authorization    = "NONE"
  api_key_required = true
}

# Method response for GET 200 status
resource "aws_api_gateway_method_response" "get_pets_pettype_200" {
  rest_api_id = aws_api_gateway_rest_api.main.id
  resource_id = aws_api_gateway_resource.pets_pettype.id
  http_method = aws_api_gateway_method.get_pets_pettype.http_method
  status_code = "200"
}

resource "aws_api_gateway_integration" "get_pets_pettype" {
  rest_api_id             = aws_api_gateway_rest_api.main.id
  resource_id             = aws_api_gateway_resource.pets_pettype.id
  http_method             = aws_api_gateway_method.get_pets_pettype.http_method
  type                    = "HTTP"
  integration_http_method = "POST"
  uri                     = "https://dynamodb.${data.aws_region.current.region}.amazonaws.com/"
  credentials             = aws_iam_role.apigw_dynamodb.arn

  request_templates = {
    "application/json" = <<EOF
{
    "TableName": "Pets",
    "IndexName": "PetType-index",
    "KeyConditionExpression": "PetType = :PetType",
    "ExpressionAttributeValues": {
        ":PetType": {"S": "$input.params('PetType')"}
    }
}
EOF
  }

  request_parameters = {
    "integration.request.header.X-Amz-Target" = "'DynamoDB_20120810.Query'"
    "integration.request.header.Content-Type" = "'application/json'"
  }
}

# Integration response for GET with VTL response mapping
resource "aws_api_gateway_integration_response" "get_pets_pettype_200" {
  depends_on       = [aws_api_gateway_integration.get_pets_pettype, aws_api_gateway_method_response.get_pets_pettype_200]
  rest_api_id      = aws_api_gateway_rest_api.main.id
  resource_id      = aws_api_gateway_resource.pets_pettype.id
  http_method      = aws_api_gateway_method.get_pets_pettype.http_method
  status_code      = "200"
  selection_pattern = ""

  response_templates = {
    "application/json" = <<EOF
#set($items = $input.path('$.Items'))
#set($count = $input.path('$.Count'))
{
  "count": $count,
  "items": [
#foreach($item in $items)
    {
      "id": "$item.id.S",
      "PetType": "$item.PetType.S",
      "PetName": "$item.PetName.S",
      "PetPrice": $item.PetPrice.N
    }#if($foreach.hasNext),#end
#end
  ]
}
EOF
  }
}

# Deployment
resource "aws_api_gateway_deployment" "main" {
  depends_on = [
    aws_api_gateway_integration.post_pets,
    aws_api_gateway_integration.get_pets_pettype,
    aws_api_gateway_integration_response.get_pets_pettype_200
  ]
  rest_api_id = aws_api_gateway_rest_api.main.id
  triggers = {
    redeployment = timestamp()
  }
  lifecycle {
    create_before_destroy = true
  }
}

# Stage v1
resource "aws_api_gateway_stage" "v1" {
  stage_name    = "v1"
  rest_api_id   = aws_api_gateway_rest_api.main.id
  deployment_id = aws_api_gateway_deployment.main.id
}

# API Key
resource "aws_api_gateway_api_key" "main" {
  name    = "apigw-dynamodb-terraform-api-key"
  enabled = true
}

# Usage Plan
resource "aws_api_gateway_usage_plan" "main" {
  name = "apigw-dynamodb-terraform-usage-plan"

  quota_settings {
    limit  = 1000
    period = "MONTH"
  }

  throttle_settings {
    burst_limit = 20
    rate_limit  = 100
  }
}

# Usage Plan Key (associates API key with usage plan)
resource "aws_api_gateway_usage_plan_key" "main" {
  usage_plan_id = aws_api_gateway_usage_plan.main.id
  key_id        = aws_api_gateway_api_key.main.id
  key_type      = "API_KEY"
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

variable "name" {
  description = "Base name used to derive all S3 bucket names."
  type        = string
  default     = "sadcloud"
}

variable "no_versioning" {
  description = "When true, disables versioning on the primary bucket."
  type        = bool
  default     = false
}

variable "no_default_encryption" {
  description = "When true, disables default server-side encryption on the primary bucket."
  type        = bool
  default     = false
}

variable "no_logging" {
  description = "When true, omits the logging bucket and access logging configuration."
  type        = bool
  default     = false
}

variable "website_enabled" {
  description = "When true, enables static website hosting on the primary bucket."
  type        = bool
  default     = false
}

variable "allow_cleartext" {
  description = "When true, attaches a bucket policy denying all s3:* actions over non-SSL transport."
  type        = bool
  default     = false
}

variable "s3_getobject_only" {
  description = "When true, creates an additional bucket (name-getonly) granting public s3:GetObject access."
  type        = bool
  default     = false
}

variable "s3_public" {
  description = "When true, creates an additional bucket (name-public) granting full public s3:* access."
  type        = bool
  default     = false
}

variable "bucket_acl" {
  description = "Canned ACL applied to the logging bucket."
  type        = string
  default     = "log-delivery-write"
}

locals {
  primary_bucket_prefix = "${var.name}-"
  logging_bucket_name   = "${var.name}-logging"
  getonly_bucket_name   = "${var.name}-getonly"
  public_bucket_name    = "${var.name}-public"
  common_tags = {
    Environment = "security-testing"
  }
}

# ---------------------------------------------------------------------------
# Primary bucket
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "main" {
  bucket_prefix = local.primary_bucket_prefix
  force_destroy = true

  tags = merge(local.common_tags, {
    Name = var.name
  })
}

resource "aws_s3_bucket_ownership_controls" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "main" {
  depends_on = [aws_s3_bucket_ownership_controls.main]

  bucket = aws_s3_bucket.main.id
  acl    = "private"
}

resource "aws_s3_bucket_versioning" "main" {
  count  = var.no_versioning ? 0 : 1
  bucket = aws_s3_bucket.main.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "main" {
  bucket                  = aws_s3_bucket.main.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_kms_key" "main" {
  count                   = var.no_default_encryption ? 0 : 1
  description             = "Customer-managed KMS key for default encryption of the ${var.name} S3 bucket"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "${var.name}-kms"
  })
}

resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  count  = var.no_default_encryption ? 0 : 1
  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.main[0].arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_website_configuration" "main" {
  count  = var.website_enabled ? 1 : 0
  bucket = aws_s3_bucket.main.id

  index_document {
    suffix = "index.html"
  }
}

# ---------------------------------------------------------------------------
# Access logging bucket
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "logging" {
  count         = var.no_logging ? 0 : 1
  bucket        = local.logging_bucket_name
  force_destroy = true

  tags = merge(local.common_tags, {
    Name = local.logging_bucket_name
  })
}

resource "aws_s3_bucket_ownership_controls" "logging" {
  count  = var.no_logging ? 0 : 1
  bucket = aws_s3_bucket.logging[0].id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "logging" {
  count      = var.no_logging ? 0 : 1
  depends_on = [aws_s3_bucket_ownership_controls.logging]

  bucket = aws_s3_bucket.logging[0].id
  acl    = var.bucket_acl
}

resource "aws_s3_bucket_public_access_block" "logging" {
  count                   = var.no_logging ? 0 : 1
  bucket                  = aws_s3_bucket.logging[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_kms_key" "logging" {
  count                   = var.no_logging ? 0 : 1
  description             = "Customer-managed KMS key for default encryption of the ${local.logging_bucket_name} S3 bucket"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "${local.logging_bucket_name}-kms"
  })
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logging" {
  count  = var.no_logging ? 0 : 1
  bucket = aws_s3_bucket.logging[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.logging[0].arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_logging" "main" {
  count         = var.no_logging ? 0 : 1
  bucket        = aws_s3_bucket.main.id
  target_bucket = aws_s3_bucket.logging[0].id
  target_prefix = "log/"
}

# ---------------------------------------------------------------------------
# Optional bucket policy denying cleartext (non-SSL) transport
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_policy" "deny_cleartext" {
  count  = var.allow_cleartext ? 1 : 0
  bucket = aws_s3_bucket.main.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyNonSSLTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.main.arn,
          "${aws_s3_bucket.main.arn}/*",
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      },
    ]
  })
}

# ---------------------------------------------------------------------------
# Optional secondary bucket: public read-only (s3:GetObject)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "getonly" {
  count         = var.s3_getobject_only ? 1 : 0
  bucket        = local.getonly_bucket_name
  force_destroy = true

  tags = merge(local.common_tags, {
    Name = local.getonly_bucket_name
  })
}

resource "aws_s3_bucket_public_access_block" "getonly" {
  count                   = var.s3_getobject_only ? 1 : 0
  bucket                  = aws_s3_bucket.getonly[0].id
  block_public_acls       = false
  block_public_policy     = false
  ignore_public_acls      = false
  restrict_public_buckets = false
}

resource "aws_s3_bucket_policy" "getonly" {
  count  = var.s3_getobject_only ? 1 : 0
  bucket = aws_s3_bucket.getonly[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "PublicReadGetObject"
        Effect    = "Allow"
        Principal = "*"
        Action = [
          "s3:GetObject",
        ]
        Resource = [
          "${aws_s3_bucket.getonly[0].arn}/*",
        ]
      },
    ]
  })
}

# ---------------------------------------------------------------------------
# Optional secondary bucket: full public read-write (s3:*)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "public" {
  count         = var.s3_public ? 1 : 0
  bucket        = local.public_bucket_name
  force_destroy = true

  tags = merge(local.common_tags, {
    Name = local.public_bucket_name
  })
}

resource "aws_s3_bucket_public_access_block" "public" {
  count                   = var.s3_public ? 1 : 0
  bucket                  = aws_s3_bucket.public[0].id
  block_public_acls       = false
  block_public_policy     = false
  ignore_public_acls      = false
  restrict_public_buckets = false
}

resource "aws_s3_bucket_policy" "public" {
  count  = var.s3_public ? 1 : 0
  bucket = aws_s3_bucket.public[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "PublicReadWrite"
        Effect    = "Allow"
        Principal = "*"
        Action = [
          "s3:*",
        ]
        Resource = [
          aws_s3_bucket.public[0].arn,
          "${aws_s3_bucket.public[0].arn}/*",
        ]
      },
    ]
  })
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

locals {
  account_id         = data.aws_caller_identity.current.account_id
  partition          = data.aws_partition.current.partition
  policy_prefix      = "arn:${data.aws_partition.current.partition}:iam::aws:policy/"
  sr_policy_prefix   = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/"
  role_path          = "/service-role/"
}

# ---------------------------------------------------------------------------
# Service Roles (path = "/service-role/")
# ---------------------------------------------------------------------------

resource "aws_iam_role" "agent" {
  name = "AWSElasticDisasterRecoveryAgentRole"
  path = local.role_path
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "drs.amazonaws.com"
        }
        Action = [
          "sts:AssumeRole",
          "sts:SetSourceIdentity"
        ]
        Condition = {
          StringEquals = {
            "sts:CallerAccountId" = local.account_id
          }
          StringLike = {
            "sts:SourceIdentityPrefix" = "s-*"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role" "failback" {
  name = "AWSElasticDisasterRecoveryFailbackRole"
  path = local.role_path
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "drs.amazonaws.com"
        }
        Action = [
          "sts:AssumeRole",
          "sts:SetSourceIdentity"
        ]
        Condition = {
          StringEquals = {
            "sts:CallerAccountId" = local.account_id
          }
          StringLike = {
            "sts:SourceIdentityPrefix" = "i-*"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role" "conversion_server" {
  name = "AWSElasticDisasterRecoveryConversionServerRole"
  path = local.role_path
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = ["sts:AssumeRole"]
      }
    ]
  })
}

resource "aws_iam_role" "recovery_instance" {
  name = "AWSElasticDisasterRecoveryRecoveryInstanceRole"
  path = local.role_path
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = ["sts:AssumeRole"]
      }
    ]
  })
}

resource "aws_iam_role" "replication_server" {
  name = "AWSElasticDisasterRecoveryReplicationServerRole"
  path = local.role_path
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = ["sts:AssumeRole"]
      }
    ]
  })
}

resource "aws_iam_role" "recovery_instance_with_launch" {
  name = "AWSElasticDisasterRecoveryRecoveryInstanceWithLaunchActionsRole"
  path = local.role_path
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = ["sts:AssumeRole"]
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# Initializer Role (path = "/")
# ---------------------------------------------------------------------------

resource "aws_iam_role" "initializer" {
  name = "AWSElasticDisasterRecoveryInitializerRole"
  path = "/"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = data.aws_caller_identity.current.arn
        }
        Action = ["sts:AssumeRole"]
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# Custom Initialize Policy
# ---------------------------------------------------------------------------

resource "aws_iam_policy" "initialize_policy" {
  name        = "InitializePolicy"
  path        = "/"
  description = "Custom policy for DRS initialization permitting service initialization, instance profile creation, PassRole, service-linked role creation, full EC2, and role policy attachments restricted to DRS managed policies"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "FullEC2Access"
        Effect = "Allow"
        Action = [
          "ec2:*"
        ]
        Resource = ["*"]
      },
      {
        Sid    = "InstanceProfileCreation"
        Effect = "Allow"
        Action = [
          "iam:CreateInstanceProfile",
          "iam:GetInstanceProfile",
          "iam:ListInstanceProfiles"
        ]
        Resource = ["*"]
      },
      {
        Sid    = "PassRoleToEC2AndDRS"
        Effect = "Allow"
        Action = [
          "iam:PassRole"
        ]
        Resource = [
          "arn:${local.partition}:iam::*:role/service-role/AWSElasticDisasterRecovery*"
        ]
        Condition = {
          StringEquals = {
            "iam:ResourceService" = ["ec2.amazonaws.com", "drs.amazonaws.com"]
          }
        }
      },
      {
        Sid    = "ServiceLinkedRoleCreation"
        Effect = "Allow"
        Action = [
          "iam:CreateServiceLinkedRole"
        ]
        Resource = [
          "arn:${local.partition}:iam::*:role/aws-service-role/AWSServiceRoleForElasticDisasterRecovery"
        ]
      },
      {
        Sid    = "AttachDRSManagedPolicies"
        Effect = "Allow"
        Action = [
          "iam:AttachRolePolicy",
          "iam:DetachRolePolicy"
        ]
        Resource = [
          "arn:${local.partition}:iam::*:role/service-role/AWSElasticDisasterRecovery*"
        ]
        Condition = {
          StringEquals = {
            "iam:PolicyARN" = [
              "${local.sr_policy_prefix}AWSElasticDisasterRecoveryAgentPolicy",
              "${local.sr_policy_prefix}AWSElasticDisasterRecoveryFailbackPolicy",
              "${local.sr_policy_prefix}AWSElasticDisasterRecoveryConversionServerPolicy",
              "${local.sr_policy_prefix}AWSElasticDisasterRecoveryRecoveryInstancePolicy",
              "${local.sr_policy_prefix}AWSElasticDisasterRecoveryReplicationServerPolicy",
              "${local.policy_prefix}AmazonSSMManagedInstanceCore"
            ]
          }
        }
      },
      {
        Sid    = "ServiceRoleCRUD"
        Effect = "Allow"
        Action = [
          "iam:CreateRole",
          "iam:DeleteRole",
          "iam:UpdateRole",
          "iam:GetRole",
          "iam:ListRoles",
          "iam:TagRole",
          "iam:UntagRole"
        ]
        Resource = ["*"]
      },
      {
        Sid    = "ServiceInitialization"
        Effect = "Allow"
        Action = [
          "drs:*"
        ]
        Resource = ["*"]
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# Policy Attachments – AWS-managed policies to service roles
# ---------------------------------------------------------------------------

resource "aws_iam_role_policy_attachment" "agent" {
  role       = aws_iam_role.agent.name
  policy_arn = "${local.sr_policy_prefix}AWSElasticDisasterRecoveryAgentPolicy"
}

resource "aws_iam_role_policy_attachment" "failback" {
  role       = aws_iam_role.failback.name
  policy_arn = "${local.sr_policy_prefix}AWSElasticDisasterRecoveryFailbackPolicy"
}

resource "aws_iam_role_policy_attachment" "conversion_server" {
  role       = aws_iam_role.conversion_server.name
  policy_arn = "${local.sr_policy_prefix}AWSElasticDisasterRecoveryConversionServerPolicy"
}

resource "aws_iam_role_policy_attachment" "recovery_instance" {
  role       = aws_iam_role.recovery_instance.name
  policy_arn = "${local.sr_policy_prefix}AWSElasticDisasterRecoveryRecoveryInstancePolicy"
}

resource "aws_iam_role_policy_attachment" "replication_server" {
  role       = aws_iam_role.replication_server.name
  policy_arn = "${local.sr_policy_prefix}AWSElasticDisasterRecoveryReplicationServerPolicy"
}

# RecoveryInstanceWithLaunchActionsRole gets both RecoveryInstancePolicy and SSM
resource "aws_iam_role_policy_attachment" "recovery_instance_with_launch_recovery" {
  role       = aws_iam_role.recovery_instance_with_launch.name
  policy_arn = "${local.sr_policy_prefix}AWSElasticDisasterRecoveryRecoveryInstancePolicy"
}

resource "aws_iam_role_policy_attachment" "recovery_instance_with_launch_ssm" {
  role       = aws_iam_role.recovery_instance_with_launch.name
  policy_arn = "${local.policy_prefix}AmazonSSMManagedInstanceCore"
}

# Attach custom InitializePolicy to the initializer role
resource "aws_iam_role_policy_attachment" "initializer" {
  role       = aws_iam_role.initializer.name
  policy_arn = aws_iam_policy.initialize_policy.arn
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
}

variable "instance_count" {
  description = "Number of EC2 instances to create"
  type        = number
  default     = 3
}

variable "instance_type" {
  description = "EC2 instance type"
  type        = string
  default     = "t2.micro"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name      = "VPC_from_Terraform"
    Terraform = "true"
  }
}

resource "aws_subnet" "private" {
  count                   = length(var.subnet_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "private_subnet_${count.index + 1}"
  }
}

resource "aws_security_group" "allow_ssh_http_https" {
  name        = "allow_ssh_http_https"
  description = "Allow SSH from VPC CIDR, HTTP and HTTPS from everywhere"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "Terraform_SG_HTTP_HTTPS_SSH"
  }
}

resource "aws_vpc_security_group_ingress_rule" "ssh" {
  security_group_id = aws_security_group.allow_ssh_http_https.id
  cidr_ipv4         = aws_vpc.main.cidr_block
  from_port         = 22
  to_port           = 22
  ip_protocol       = "tcp"
  description       = "SSH from VPC CIDR"
}

resource "aws_vpc_security_group_ingress_rule" "http" {
  security_group_id = aws_security_group.allow_ssh_http_https.id
  cidr_ipv4         = "0.0.0.0/0"
  from_port         = 80
  to_port           = 80
  ip_protocol       = "tcp"
  description       = "HTTP from everywhere"
}

resource "aws_vpc_security_group_ingress_rule" "https" {
  security_group_id = aws_security_group.allow_ssh_http_https.id
  cidr_ipv4         = "0.0.0.0/0"
  from_port         = 443
  to_port           = 443
  ip_protocol       = "tcp"
  description       = "HTTPS from everywhere"
}

resource "aws_vpc_security_group_egress_rule" "vpc_cidr" {
  security_group_id = aws_security_group.allow_ssh_http_https.id
  cidr_ipv4         = aws_vpc.main.cidr_block
  ip_protocol       = "-1"
  description       = "Egress to VPC CIDR"
}

resource "aws_kms_key" "ebs" {
  description             = "KMS key for EBS encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowEBSAccess"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:CreateGrant",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
    ]
  })
}

resource "aws_kms_alias" "ebs" {
  name          = "alias/terraform-ebs-key"
  target_key_id = aws_kms_key.ebs.id
}

resource "aws_instance" "terraform_instance" {
  count                  = var.instance_count
  ami                    = data.aws_ami.amazon_linux_2.id
  instance_type          = var.instance_type
  subnet_id              = aws_subnet.private[count.index].id
  vpc_security_group_ids = [aws_security_group.allow_ssh_http_https.id]

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  root_block_device {
    volume_size = 20
    volume_type = "gp3"
    encrypted   = true
    kms_key_id  = aws_kms_key.ebs.arn
    tags = {
      Name = "Terraform_EBS_Volume1"
    }
  }

  tags = {
    Name = "Terraform_Instance"
  }
}

# Data sources for constructing ARNs
data "aws_partition" "current" {}
data "aws_region" "current" {}
data "aws_caller_identity" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
}

# ---------------------------------------------------------------------------
# Role 1: ecsServiceRole
# Trusted by: ecs.amazonaws.com and s3.amazonaws.com
# ---------------------------------------------------------------------------
resource "aws_iam_role" "ecs_service_role" {
  name = "ecsServiceRole"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = ["ecs.amazonaws.com", "s3.amazonaws.com"]
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "ecs_task_role_policy" {
  name = "ecsTaskRolePolicy"
  role = aws_iam_role.ecs_service_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      # ELB
      {
        Effect = "Allow"
        Action = [
          "elasticloadbalancing:DescribeLoadBalancers",
          "elasticloadbalancing:DescribeTargetGroups",
          "elasticloadbalancing:DescribeTargetHealth",
          "elasticloadbalancing:RegisterTargets",
          "elasticloadbalancing:DeregisterTargets",
          "elasticloadbalancing:AddTags",
          "elasticloadbalancing:DescribeTags",
        ]
        Resource = "*"
      },
      # EC2
      {
        Effect = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSubnets",
          "ec2:DescribeVpcs",
          "ec2:DescribeRouteTables",
        ]
        Resource = "*"
      },
      # SSM
      {
        Effect = "Allow"
        Action = [
          "ssm:GetParameter",
          "ssm:GetParameters",
          "ssm:GetParametersByPath",
          "ssm:DescribeParameters",
        ]
        Resource = "*"
      },
      # Secrets Manager
      {
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret",
          "secretsmanager:ListSecrets",
        ]
        Resource = "*"
      },
      # KMS
      {
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey",
          "kms:ListKeys",
          "kms:ListAliases",
          "kms:Encrypt",
          "kms:GenerateDataKey",
        ]
        Resource = "*"
      },
      # CodeDeploy
      {
        Effect = "Allow"
        Action = [
          "codedeploy:CreateDeployment",
          "codedeploy:GetDeployment",
          "codedeploy:ListDeployments",
          "codedeploy:RegisterApplicationRevision",
          "codedeploy:GetApplicationRevision",
          "codedeploy:GetDeploymentGroup",
          "codedeploy:ListDeploymentGroups",
          "codedeploy:CreateDeploymentGroup",
          "codedeploy:UpdateDeploymentGroup",
          "codedeploy:DeleteDeploymentGroup",
        ]
        Resource = "*"
      },
      # SNS
      {
        Effect = "Allow"
        Action = [
          "sns:Publish",
          "sns:ListTopics",
          "sns:CreateTopic",
        ]
        Resource = "*"
      },
      # CloudWatch (logs + metrics)
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams",
          "logs:GetLogEvents",
          "cloudwatch:PutMetricData",
          "cloudwatch:GetMetricData",
          "cloudwatch:DescribeAlarms",
          "cloudwatch:SetAlarmState",
        ]
        Resource = "*"
      },
      # Lambda
      {
        Effect = "Allow"
        Action = [
          "lambda:InvokeFunction",
          "lambda:InvokeFunctionAsync",
        ]
        Resource = "*"
      },
    ]
  })
}

# ---------------------------------------------------------------------------
# Role 2: ecsExecTaskRole
# Trusted by: ecs-tasks.amazonaws.com and s3.amazonaws.com
# ---------------------------------------------------------------------------
resource "aws_iam_role" "ecs_exec_task_role" {
  name = "ecsExecTaskRole"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = ["ecs-tasks.amazonaws.com", "s3.amazonaws.com"]
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "ecs_exec_role_policy" {
  name = "ecsExecRolePolicy"
  role = aws_iam_role.ecs_exec_task_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      # ECR
      {
        Effect = "Allow"
        Action = [
          "ecr:GetAuthorizationToken",
          "ecr:BatchCheckLayerAvailability",
          "ecr:BatchGetImage",
          "ecr:GetDownloadUrlForLayer",
          "ecr:DescribeRepositories",
          "ecr:DescribeImages",
        ]
        Resource = "*"
      },
      # ECS service description
      {
        Effect = "Allow"
        Action = [
          "ecs:DescribeServices",
          "ecs:ListServices",
        ]
        Resource = "*"
      },
      # CloudWatch logging
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams",
        ]
        Resource = "*"
      },
      # Secrets Manager
      {
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret",
        ]
        Resource = "*"
      },
      # KMS
      {
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey",
        ]
        Resource = "*"
      },
      # SSM
      {
        Effect = "Allow"
        Action = [
          "ssm:GetParameter",
          "ssm:GetParameters",
          "ssm:GetParametersByPath",
        ]
        Resource = "*"
      },
    ]
  })
}

resource "aws_iam_role_policy" "ecs_execution_additional" {
  name = "ecsExecution_additional"
  role = aws_iam_role.ecs_exec_task_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      # ECS service listing and description
      {
        Effect = "Allow"
        Action = [
          "ecs:ListServices",
          "ecs:DescribeServices",
        ]
        Resource = "*"
      },
      # S3 object read/write
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket",
          "s3:DeleteObject",
        ]
        Resource = "*"
      },
    ]
  })
}

# ---------------------------------------------------------------------------
# Role 3: ecsTaskRole
# Trusted by: ecs-tasks.amazonaws.com and s3.amazonaws.com
# ---------------------------------------------------------------------------
resource "aws_iam_role" "ecs_task_role" {
  name = "ecsTaskRole"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = ["ecs-tasks.amazonaws.com", "s3.amazonaws.com"]
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "ecs_task_role_additional" {
  name = "ecsTaskRole_additional"
  role = aws_iam_role.ecs_task_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      # ECS service listing and description
      {
