        ]
        Resource = "*"
      },
      # S3 object read/write
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket",
          "s3:DeleteObject",
        ]
        Resource = "*"
      },
    ]
  })
}

# ---------------------------------------------------------------------------
# Role 4: ecs_autoscale_role
# Trusted by: application-autoscaling.amazonaws.com
# ---------------------------------------------------------------------------
resource "aws_iam_role" "ecs_autoscale_role" {
  name = "ecs_autoscale_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "application-autoscaling.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "ecs_autoscale_role_policy" {
  name = "ecs_autoscale_role_policy"
  role = aws_iam_role.ecs_autoscale_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      # ECS service description and update
      {
        Effect = "Allow"
        Action = [
          "ecs:DescribeServices",
          "ecs:UpdateService",
        ]
        Resource = "*"
      },
      # CloudWatch alarm permissions
      {
        Effect = "Allow"
        Action = [
          "cloudwatch:DescribeAlarms",
          "cloudwatch:SetAlarmState",
          "cloudwatch:DescribeAlarmHistory",
          "cloudwatch:PutMetricData",
          "cloudwatch:GetMetricData",
        ]
        Resource = "*"
      },
    ]
  })
}

# ---------------------------------------------------------------------------
# Role 5: ecs_codedeploy_role
# Trusted by: codedeploy.amazonaws.com
# ---------------------------------------------------------------------------
resource "aws_iam_role" "ecs_codedeploy_role" {
  name = "ecs_codedeploy_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codedeploy.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Attach the managed AWSCodeDeployRole policy
resource "aws_iam_role_policy_attachment" "ecs_codedeploy_role_managed" {
  role       = aws_iam_role.ecs_codedeploy_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSCodeDeployRole"
}

resource "aws_iam_role_policy" "ecs_codedeploy_role_policy" {
  name = "ecs_codedeploy_role_policy"
  role = aws_iam_role.ecs_codedeploy_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      # ECS task set
      {
        Effect = "Allow"
        Action = [
          "ecs:CreateTaskSet",
          "ecs:UpdateTaskSet",
          "ecs:DescribeTaskSets",
          "ecs:DeleteTaskSet",
          "ecs:DescribeServices",
          "ecs:UpdateService",
        ]
        Resource = "*"
      },
      # ELB
      {
        Effect = "Allow"
        Action = [
          "elasticloadbalancing:DescribeLoadBalancers",
          "elasticloadbalancing:DescribeTargetGroups",
          "elasticloadbalancing:DescribeTargetHealth",
          "elasticloadbalancing:RegisterTargets",
          "elasticloadbalancing:DeregisterTargets",
          "elasticloadbalancing:AddTags",
          "elasticloadbalancing:RemoveTags",
        ]
        Resource = "*"
      },
      # Lambda
      {
        Effect = "Allow"
        Action = [
          "lambda:InvokeFunction",
          "lambda:InvokeFunctionAsync",
        ]
        Resource = "*"
      },
      # CloudWatch
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams",
          "logs:GetLogEvents",
          "cloudwatch:DescribeAlarms",
          "cloudwatch:SetAlarmState",
          "cloudwatch:PutMetricData",
          "cloudwatch:GetMetricData",
        ]
        Resource = "*"
      },
      # SNS
      {
        Effect = "Allow"
        Action = [
          "sns:Publish",
          "sns:ListTopics",
        ]
        Resource = "*"
      },
      # S3
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket",
          "s3:DeleteObject",
        ]
        Resource = "*"
      },
    ]
  })
}

# PassRole policy targeting the task role ARN
resource "aws_iam_role_policy" "ecs_codedeploy_role_policy_task" {
  name = "ecs_codedeploy_role_policy_task"
  role = aws_iam_role.ecs_codedeploy_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "iam:PassRole"
        Resource = aws_iam_role.ecs_task_role.arn
      }
    ]
  })
}

# PassRole policy targeting the execution role ARN
resource "aws_iam_role_policy" "ecs_codedeploy_role_policy_task_exec" {
  name = "ecs_codedeploy_role_policy_task_exec"
  role = aws_iam_role.ecs_codedeploy_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "iam:PassRole"
        Resource = aws_iam_role.ecs_exec_task_role.arn
      }
    ]
  })
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  subnet_suffixes = ["a", "b", "c", "d"]
}

# ===================== EXTERNAL VPC =====================

