}

locals {
  prefix        = var.prefix
  vpc_cidr      = "10.0.0.0/16"
  private_cidrs = ["10.0.0.0/24", "10.0.1.0/24", "10.0.2.0/24"]
  public_cidrs  = ["10.0.4.0/24", "10.0.5.0/24", "10.0.6.0/24"]
}

variable "prefix" {
  description = "Resource name prefix"
  type        = string
  default     = "n8n"
}

variable "certificate_arn" {
  description = "ARN of an existing ACM certificate for the HTTPS listener"
  type        = string
  default     = null
}

variable "url" {
  description = "Override the WEBHOOK_URL; defaults to the HTTPS LB endpoint"
  type        = string
  default     = null
}

variable "desired_count" {
  description = "Number of Fargate tasks to run"
  type        = number
  default     = 1
}

variable "container_image" {
  description = "Container image URI for n8n"
  type        = string
  default     = "n8nio/n8n:1.4.0"
}

variable "fargate_type" {
  description = "Fargate capacity provider type (FARGATE or FARGATE_SPOT)"
  type        = string
  default     = "FARGATE_SPOT"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

# ---------------------------------------------------------------------------
# Self-signed ACM certificate
# ---------------------------------------------------------------------------
# Generate and import a self-signed certificate into ACM.
resource "null_resource" "import_cert" {
  count = var.certificate_arn == null ? 1 : 0

  provisioner "local-exec" {
    command = <<-SCRIPT
set -e
mkdir -p .n8n-certs
ARN=$(aws acm list-certificates --output text --query 'CertificateSummaryList[0].CertificateArn' --region ${data.aws_region.current.region} 2>/dev/null | head -1 | xargs)
if [ -z "$ARN" ]; then
  openssl req -x509 -newkey rsa:2048 -nodes -days 365 \
    -keyout .n8n-certs/key.pem -out .n8n-certs/cert.pem \
    -subj "/CN=n8n.local" >/dev/null 2>&1
  ARN=$(aws acm import-certificate \
    --certificate "fileb://.n8n-certs/cert.pem" \
    --private-key "fileb://.n8n-certs/key.pem" \
    --region ${data.aws_region.current.region} \
    --output text --query 'CertificateArn')
fi
echo "$ARN" > .n8n-certs/arn
echo "$ARN"
SCRIPT
  }

  triggers = {
    always_run = data.aws_region.current.region
  }
}

# Look up the certificate ARN from ACM.
# This runs at plan time and returns the ARN in the `result` map.
data "external" "self_signed_cert" {
  count = var.certificate_arn == null ? 1 : 0

  # If the cached ARN file exists, use it.  Otherwise generate & import a
  # self-signed certificate now (runs at plan time) so the HTTPS listener
  # gets a valid ARN on the very first apply.
  program = ["bash", "-c", "CERT_DIR=\".${local.prefix}-certs\"; mkdir -p \"$CERT_DIR\"; if [ -f \"$CERT_DIR/arn\" ]; then ARN=$(cat \"$CERT_DIR/arn\"); else ARN=$(aws acm list-certificates --output text --query 'CertificateSummaryList[0].CertificateArn' --region ${data.aws_region.current.region} 2>/dev/null | head -1 | xargs); if [ -z \"$ARN\" ]; then openssl req -x509 -newkey rsa:2048 -nodes -days 365 -keyout \"$CERT_DIR/key.pem\" -out \"$CERT_DIR/cert.pem\" -subj \"/CN=n8n.local\" >/dev/null 2>&1 && ARN=$(aws acm import-certificate --certificate \"fileb://$CERT_DIR/cert.pem\" --private-key \"fileb://$CERT_DIR/key.pem\" --region ${data.aws_region.current.region} --output text --query 'CertificateArn' 2>/dev/null); fi; echo \"$ARN\" > \"$CERT_DIR/arn\" 2>/dev/null; fi; echo \"{\\\"id\\\":\\\"$ARN\\\"}\""]
}

locals {
  # .result is a known map attribute of the external data source
  lb_cert_arn = var.certificate_arn != null ? var.certificate_arn : (
    try(data.external.self_signed_cert[0].result["id"], null)
  )
}

# ---------------------------------------------------------------------------
# VPC
# ---------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.prefix}-vpc"
  }
}

# ---------------------------------------------------------------------------
# Internet Gateway (for public subnets)
# ---------------------------------------------------------------------------
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.prefix}-igw"
  }
}

# ---------------------------------------------------------------------------
# Public route table (default route via IGW)
# ---------------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${local.prefix}-public-rt"
  }
}

# ---------------------------------------------------------------------------
# Subnets
# ---------------------------------------------------------------------------
resource "aws_subnet" "private" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${local.prefix}-private-${count.index}"
  }
}

resource "aws_subnet" "public" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.public_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${local.prefix}-public-${count.index}"
  }
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# Security Groups
# ---------------------------------------------------------------------------

# Load Balancer SG – inbound HTTP/HTTPS from anywhere, outbound to VPC CIDR
resource "aws_security_group" "lb" {
  name        = "${local.prefix}-lb-sg"
  description = "ALB security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "${local.prefix}-lb-sg"
  }
}

# ECS Task SG – inbound port 5678 from LB SG, outbound to VPC CIDR
resource "aws_security_group" "ecs_task" {
  name        = "${local.prefix}-ecs-task-sg"
  description = "ECS task security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port       = 5678
    to_port         = 5678
    protocol        = "tcp"
    security_groups = [aws_security_group.lb.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "${local.prefix}-ecs-task-sg"
  }
}

# EFS SG – NFS port 2049 from VPC CIDR, outbound to VPC CIDR
resource "aws_security_group" "efs" {
  name        = "${local.prefix}-efs-sg"
  description = "EFS mount target security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "${local.prefix}-efs-sg"
  }
}

# ---------------------------------------------------------------------------
# Load Balancer (internal)
# ---------------------------------------------------------------------------
resource "aws_lb" "main" {
  name                       = "${local.prefix}-alb"
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.lb.id]
  subnets                    = aws_subnet.public[*].id
  drop_invalid_header_fields = true
  enable_http2               = true

  tags = {
    Name = "${local.prefix}-alb"
  }
}

# Target group – IP type, port 80, health check /healthz
resource "aws_lb_target_group" "main" {
  name        = "${local.prefix}-tg"
  port        = 80
  protocol    = "HTTP"
  target_type = "ip"
  vpc_id      = aws_vpc.main.id

  deregistration_delay = 30

  health_check {
    enabled             = true
    path                = "/healthz"
    healthy_threshold   = 2
    unhealthy_threshold = 2
    timeout             = 3
    interval            = 30
    protocol            = "HTTP"
    matcher             = "200"
  }

  tags = {
    Name = "${local.prefix}-tg"
  }
}

# HTTPS listener on 443
resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.main.id
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = local.lb_cert_arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.id
  }
}

# HTTP listener on 80 – redirects to HTTPS
resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.id
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"
    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }
}

# ---------------------------------------------------------------------------
# EFS File System (encrypted)
# ---------------------------------------------------------------------------
resource "aws_efs_file_system" "data" {
  creation_token   = "${local.prefix}-efs"
  encrypted        = true
  performance_mode = "generalPurpose"
  throughput_mode  = "bursting"

  tags = {
    Name = "${local.prefix}-efs"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# EFS Access Point rooted at /n8n
resource "aws_efs_access_point" "data" {
  file_system_id = aws_efs_file_system.data.id

  posix_user {
    uid   = 1000
    gid   = 1000
    secondary_gids = []
  }

  root_directory {
    path = "/n8n"
    creation_info {
      owner_uid   = 1000
      owner_gid   = 1000
      permissions = "777"
    }
  }

  tags = {
    Name = "${local.prefix}-efs-ap"
  }
}

# Mount targets in private subnets
resource "aws_efs_mount_target" "data" {
  count = 3

  file_system_id  = aws_efs_file_system.data.id
  subnet_id       = aws_subnet.private[count.index].id
  security_groups = [aws_security_group.efs.id]

  ip_address = cidrhost(aws_subnet.private[count.index].cidr_block, 10)
}

# ---------------------------------------------------------------------------
# CloudWatch Log Group (1-day retention)
# ---------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "main" {
  name              = "${local.prefix}-logs"
  retention_in_days = 1

  tags = {
    Name = "${local.prefix}-logs"
  }
}

# ---------------------------------------------------------------------------
# IAM Roles (assumable by ecs-tasks.amazonaws.com)
# ---------------------------------------------------------------------------

resource "aws_iam_role" "task" {
  name = "${local.prefix}-task-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Effect = "Allow"
      }
    ]
  })

  tags = {
    Name = "${local.prefix}-task-role"
  }
}

resource "aws_iam_role" "execution" {
  name = "${local.prefix}-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Effect = "Allow"
      }
    ]
  })

  tags = {
    Name = "${local.prefix}-execution-role"
  }
}

# Inline policy for CloudWatch log operations
data "aws_iam_policy_document" "cloudwatch_logs" {
  statement {
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:DescribeLogGroups",
      "logs:DescribeLogStreams",
      "logs:PutLogEvents"
    ]
    effect    = "Allow"
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "task" {
  role   = aws_iam_role.task.name
  policy = data.aws_iam_policy_document.cloudwatch_logs.json
  name   = "${local.prefix}-task-cw-policy"
}

resource "aws_iam_role_policy" "execution" {
  role   = aws_iam_role.execution.name
  policy = data.aws_iam_policy_document.cloudwatch_logs.json
  name   = "${local.prefix}-execution-cw-policy"
}

# ---------------------------------------------------------------------------
# ECS Cluster (container insights disabled)
# ---------------------------------------------------------------------------
resource "aws_ecs_cluster" "main" {
  name = "${local.prefix}-cluster"

  setting {
    name  = "containerInsights"
    value = "disabled"
  }

  tags = {
    Name = "${local.prefix}-cluster"
  }
}

# ---------------------------------------------------------------------------
# ECS Task Definition
# ---------------------------------------------------------------------------
locals {
  webhook_url = var.url != null ? var.url : "https://${aws_lb.main.dns_name}"
}

resource "aws_ecs_task_definition" "app" {
  family                   = "${local.prefix}-task"
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                      = 256
  memory                   = 512
  task_role_arn            = aws_iam_role.task.arn
  execution_role_arn       = aws_iam_role.execution.arn

  container_definitions = jsonencode([
    {
      name      = "n8n"
      image     = var.container_image
      essential = true
      port_mappings = [
        {
          container_port = 5678
          host_port      = 5678
          protocol       = "tcp"
        }
      ]
      log_configuration = {
        log_driver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.main.id
          "awslogs-region"        = data.aws_region.current.region
          "awslogs-stream-prefix" = "n8n"
        }
      }
      environment = [
        {
          name  = "N8N_SKIP_WEBHOOK_DEREGISTRATION_SHUTDOWN"
          value = "true"
        },
        {
          name  = "WEBHOOK_URL"
          value = local.webhook_url
        }
      ]
      mount_points = [
        {
          source_volume  = "n8n_storage"
          container_path = "/home/node/.n8n"
        }
      ]
    }
  ])

  volume {
    name = "n8n_storage"
    efs_volume_configuration {
      file_system_id     = aws_efs_file_system.data.id
      root_directory     = "/"
      transit_encryption = "ENABLED"
      authorization_config {
        access_point_id = aws_efs_access_point.data.id
        iam             = "ENABLED"
      }
    }
  }

  tags = {
    Name = "${local.prefix}-task-def"
  }
}

# ---------------------------------------------------------------------------
# ECS Service
# ---------------------------------------------------------------------------
resource "aws_ecs_service" "app" {
  name            = "${local.prefix}-service"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.app.arn
  desired_count   = var.desired_count

  capacity_provider_strategy {
    base              = 1
    capacity_provider = var.fargate_type
    weight            = 100
  }

  network_configuration {
    subnets          = aws_subnet.public[*].id
    assign_public_ip = true
    security_groups  = [aws_security_group.ecs_task.id]
  }

  force_new_deployment = true

  tags = {
    Name = "${local.prefix}-service"
  }

  depends_on = [
    aws_lb_listener.https,
    aws_lb_listener.http
  ]
}

terraform {
  required_providers {
    aws = {
      source = "hashicorp/aws"
    }
    null = {
      source = "hashicorp/null"
    }
  }
}

# Get available AZs for the region
data "aws_availability_zones" "available" {
  state = "available"
}

# Local variables for easier reference
locals {
  primary_az   = data.aws_availability_zones.available.names[0]
  secondary_az = data.aws_availability_zones.available.names[1]
  vpc_cidr     = "10.32.0.0/20"
}

# VPC: lambda-rds-dev
resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_hostnames = true

  tags = {
    Name = "lambda-rds-dev"
  }
}

# Default Network ACL: lambda-rds-dev-default-nacl
resource "aws_default_network_acl" "default" {
  default_network_acl_id = aws_vpc.main.default_network_acl_id

  ingress {
    rule_no   = 100
    protocol  = "-1"
    action    = "allow"
    cidr_block = "0.0.0.0/0"
    from_port = 0
    to_port   = 0
  }

  egress {
    rule_no   = 100
    protocol  = "-1"
    action    = "allow"
    cidr_block = "0.0.0.0/0"
    from_port = 0
    to_port   = 0
  }

  tags = {
    Name = "lambda-rds-dev-default-nacl"
  }
}

# Subnet: lambda-rds-db-subnet-1 (primary AZ, 10.32.0.0/28)
resource "aws_subnet" "db1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.32.0.0/28"
  availability_zone       = local.primary_az
  map_public_ip_on_launch = false

  tags = {
    Name = "lambda-rds-db-subnet-1"
  }
}

# Subnet: lambda-rds-dev-lambda-subnet (primary AZ, 10.32.1.0/24)
resource "aws_subnet" "lambda" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.32.1.0/24"
  availability_zone       = local.primary_az
  map_public_ip_on_launch = false

  tags = {
    Name = "lambda-rds-dev-lambda-subnet"
  }
}

# Subnet: lambda-rds-db-subnet-2 (secondary AZ, 10.32.0.16/28)
resource "aws_subnet" "db2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.32.0.16/28"
  availability_zone       = local.secondary_az
  map_public_ip_on_launch = false

  tags = {
    Name = "lambda-rds-db-subnet-2"
  }
}

# Subnet: lambda-rds-bastion-host-subnet (primary AZ, 10.32.15.0/24)
resource "aws_subnet" "bastion" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.32.15.0/24"
  availability_zone       = local.primary_az
  map_public_ip_on_launch = false

  tags = {
    Name = "lambda-rds-bastion-host-subnet"
  }
}

# Internet Gateway: lambda-rds-dev-igw
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "lambda-rds-dev-igw"
  }
}

# Route Table: lambda-rds-public-subnet
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "lambda-rds-public-subnet"
  }
}

# Route: 0.0.0.0/0 -> IGW
resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

# Associate bastion subnet with public route table
resource "aws_route_table_association" "bastion" {
  subnet_id      = aws_subnet.bastion.id
  route_table_id = aws_route_table.public.id
}

# Clear the VPC's default security group's AWS-created egress rule (0.0.0.0/0, all traffic)
# to satisfy the requirement that the default SG has no ingress or egress rules.
resource "null_resource" "clear_default_sg_rules" {
  triggers = {
    vpc_id = aws_vpc.main.id
  }

  provisioner "local-exec" {
    command = <<EOC
      aws ec2 revoke-security-group-egress \
        --group-id "${aws_vpc.main.default_security_group_id}" \
        --ip-permissions '[{"IpProtocol": "-1", "IpRanges": [{"CidrIp": "0.0.0.0/0"}]}]' \
        2>/dev/null || true
      aws ec2 revoke-security-group-ingress \
        --group-id "${aws_vpc.main.default_security_group_id}" \
        --ip-permissions '[{"IpProtocol": "-1", "UserIdGroupPairs": [{"GroupId": "'"${aws_vpc.main.default_security_group_id}"'"}]}]' \
        2>/dev/null || true
    EOC
  }
}

# Security Group: lambda-rds-dev-postgres-db
resource "aws_security_group" "postgres" {
  name        = "lambda-rds-dev-postgres-db"
  description = "Security group for PostgreSQL database tier"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "lambda-rds-dev-postgres-db"
  }
}

# Security Group: lambda-rds-dev-lambda-functions
resource "aws_security_group" "lambda_sg" {
  name        = "lambda-rds-dev-lambda-functions"
  description = "Security group for Lambda functions"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "lambda-rds-dev-lambda-functions"
  }
}

# Security Group: lambda-rds-dev-bastion-host
resource "aws_security_group" "bastion_sg" {
  name        = "lambda-rds-dev-bastion-host"
  description = "Security group for bastion host"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "lambda-rds-dev-bastion-host"
  }
}

# Postgres SG: Ingress from bastion SG on port 5432
resource "aws_vpc_security_group_ingress_rule" "postgres_from_bastion" {
  security_group_id = aws_security_group.postgres.id
  referenced_security_group_id = aws_security_group.bastion_sg.id
  from_port         = 5432
  to_port           = 5432
  ip_protocol       = "tcp"
}

# Postgres SG: Ingress from lambda SG on port 5432
resource "aws_vpc_security_group_ingress_rule" "postgres_from_lambda" {
  security_group_id = aws_security_group.postgres.id
  referenced_security_group_id = aws_security_group.lambda_sg.id
  from_port         = 5432
  to_port           = 5432
  ip_protocol       = "tcp"
}

# Postgres SG: Egress to VPC CIDR
resource "aws_vpc_security_group_egress_rule" "postgres_egress" {
  security_group_id = aws_security_group.postgres.id
  cidr_ipv4         = local.vpc_cidr
  from_port         = 0
  to_port           = 0
  ip_protocol       = "-1"
}

# Lambda SG: Egress to VPC CIDR
resource "aws_vpc_security_group_egress_rule" "lambda_egress" {
  security_group_id = aws_security_group.lambda_sg.id
  cidr_ipv4         = local.vpc_cidr
  from_port         = 0
  to_port           = 0
  ip_protocol       = "-1"
}

# Bastion SG: Ingress SSH from VPC CIDR on port 22
resource "aws_vpc_security_group_ingress_rule" "bastion_ssh" {
  security_group_id = aws_security_group.bastion_sg.id
  cidr_ipv4         = local.vpc_cidr
  from_port         = 22
  to_port           = 22
  ip_protocol       = "tcp"
}

# Bastion SG: Egress to postgres SG
resource "aws_vpc_security_group_egress_rule" "bastion_to_postgres" {
  security_group_id = aws_security_group.bastion_sg.id
  referenced_security_group_id = aws_security_group.postgres.id
  from_port         = 0
  to_port           = 0
  ip_protocol       = "-1"
}

variable "create" {
  description = "Whether to create any resources"
  type        = bool
  default     = true
}

variable "name" {
  description = "Human-readable queue name (any .fifo suffix is stripped automatically)"
  type        = string
}

variable "use_name_prefix" {
  description = "Whether to use the name as a prefix for auto-generated unique names"
  type        = bool
  default     = false
}

variable "fifo_queue" {
  description = "Whether the queue is FIFO"
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enables content-based deduplication (FIFO only)"
  type        = bool
  default     = null
}

variable "deduplication_scope" {
  description = "Deduplication scope for FIFO queues: 'messageGroup' or 'queue'"
  type        = string
  default     = null
}

variable "fifo_throughput_limit" {
  description = "FIFO throughput limit: 'perQueue' or 'perMessageGroupId'"
  type        = string
  default     = null
}

variable "delay_seconds" {
  description = "Delay in seconds"
  type        = number
  default     = null
}

variable "max_message_size" {
  description = "Maximum message size in bytes (1024-262144)"
  type        = number
  default     = null
}

variable "message_retention_seconds" {
  description = "Message retention period in seconds (60-1209600)"
  type        = number
  default     = null
}

variable "receive_wait_time_seconds" {
  description = "Receive wait time in seconds (0-20)"
  type        = number
  default     = null
}

variable "visibility_timeout_seconds" {
  description = "Visibility timeout in seconds (0-43200)"
  type        = number
  default     = null
}

variable "sqs_managed_sse_enabled" {
  description = "Whether to enable SQS-managed SSE (default) or use a custom KMS key"
  type        = bool
  default     = true
}

variable "kms_master_key_id" {
  description = "Custom KMS master key ID (overrides sqs_managed_sse_enabled)"
  type        = string
  default     = null
}

variable "kms_data_key_reuse_period_seconds" {
  description = "KMS data key reuse period in seconds (60-86400)"
  type        = number
  default     = null
}

variable "create_queue_policy" {
  description = "Whether to create an IAM policy for the main queue"
  type        = bool
  default     = false
}

variable "queue_policy_document" {
  description = "JSON policy document to merge into the main queue policy"
  type        = string
  default     = null
}

variable "queue_policy_statements" {
  description = "Custom IAM statement blocks to include in the main queue policy"
  type = list(object({
    sid       = optional(string)
    effect    = string
    actions   = list(string)
    resources = optional(list(string))
    principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })))
    conditions = optional(list(object({
      test     = string
      variable = string
      values   = list(string)
    })))
  }))
  default = []
}

variable "create_dlq_queue_policy" {
  description = "Whether to create an IAM policy for the DLQ"
  type        = bool
  default     = false
}

variable "dlq_queue_policy_document" {
  description = "JSON policy document to merge into the DLQ policy"
  type        = string
  default     = null
}

variable "dlq_queue_policy_statements" {
  description = "Custom IAM statement blocks to include in the DLQ policy"
  type = list(object({
    sid       = optional(string)
    effect    = string
    actions   = list(string)
    resources = optional(list(string))
    principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })))
    conditions = optional(list(object({
      test     = string
      variable = string
      values   = list(string)
    })))
  }))
  default = []
}

variable "create_dlq" {
  description = "Whether to create a dead-letter queue"
  type        = bool
  default     = false
}

variable "dlq_name_suffix" {
  description = "Suffix appended to the DLQ name (default: -dlq)"
  type        = string
  default     = "-dlq"
}

variable "dlq_max_message_size" {
  description = "Maximum message size for the DLQ in bytes (overrides main queue)"
  type        = number
  default     = null
}

variable "dlq_message_retention_seconds" {
  description = "Message retention period for the DLQ in seconds (overrides main queue)"
  type        = number
  default     = null
}

variable "dlq_delay_seconds" {
  description = "Delay seconds for the DLQ (overrides main queue)"
  type        = number
  default     = null
}

variable "dlq_receive_wait_time_seconds" {
  description = "Receive wait time for the DLQ in seconds (overrides main queue)"
  type        = number
  default     = null
}

variable "dlq_visibility_timeout_seconds" {
  description = "Visibility timeout for the DLQ in seconds (overrides main queue)"
  type        = number
  default     = null
}

variable "dlq_sqs_managed_sse_enabled" {
  description = "SQS-managed SSE for the DLQ (overrides main queue setting)"
  type        = bool
  default     = null
}

variable "dlq_kms_master_key_id" {
  description = "Custom KMS key for the DLQ (overrides main queue)"
  type        = string
  default     = null
}

variable "dlq_kms_data_key_reuse_period_seconds" {
  description = "KMS data key reuse period for the DLQ in seconds"
  type        = number
  default     = null
}

variable "create_dlq_redrive_allow_policy" {
  description = "Whether to attach a redrive allow policy to the DLQ"
  type        = bool
  default     = true
}

variable "max_receive_count" {
  description = "Maximum number of times a message can be received before being sent to the DLQ"
  type        = number
  default     = 5
}

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------
locals {
  create = var.create

  # Strip any accidental .fifo from the input name
  queue_name_base = trimsuffix(var.name, ".fifo")

  # FIFO suffix
  fifo_suffix = var.fifo_queue ? ".fifo" : ""

  # Full queue name with FIFO suffix if applicable
  queue_name_full = "${local.queue_name_base}${local.fifo_suffix}"

  # DLQ name components
  dlq_name_base = "${local.queue_name_base}${var.dlq_name_suffix}"
  dlq_name_full = "${local.dlq_name_base}${local.fifo_suffix}"

  # Encryption defaults for DLQ – inherit from main queue if not overridden
  dlq_sqs_managed_sse_enabled = var.dlq_sqs_managed_sse_enabled != null ? var.dlq_sqs_managed_sse_enabled : var.sqs_managed_sse_enabled
  dlq_kms_master_key_id       = var.dlq_kms_master_key_id != null ? var.dlq_kms_master_key_id : var.kms_master_key_id
  dlq_kms_data_key_reuse      = var.dlq_kms_data_key_reuse_period_seconds != null ? var.dlq_kms_data_key_reuse_period_seconds : var.kms_data_key_reuse_period_seconds
}

# ---------------------------------------------------------------------------
# Main SQS Queue
# ---------------------------------------------------------------------------
resource "aws_sqs_queue" "main" {
  count = local.create ? 1 : 0

  name                              = var.use_name_prefix ? null : local.queue_name_full
  name_prefix                       = var.use_name_prefix ? local.queue_name_base : null
  fifo_queue                        = var.fifo_queue
  content_based_deduplication       = var.content_based_deduplication
  deduplication_scope               = var.deduplication_scope
  fifo_throughput_limit             = var.fifo_throughput_limit
  delay_seconds                     = var.delay_seconds
  max_message_size                  = var.max_message_size
  message_retention_seconds         = var.message_retention_seconds
  receive_wait_time_seconds         = var.receive_wait_time_seconds
  visibility_timeout_seconds        = var.visibility_timeout_seconds
  sqs_managed_sse_enabled           = var.kms_master_key_id != null ? null : var.sqs_managed_sse_enabled
  kms_master_key_id                 = var.kms_master_key_id
  kms_data_key_reuse_period_seconds = var.kms_data_key_reuse_period_seconds

  redrive_policy = var.create && var.create_dlq ? jsonencode({
    deadLetterTargetArn = try(aws_sqs_queue.dlq[0].arn, null)
    maxReceiveCount     = var.max_receive_count
  }) : null

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = local.queue_name_full
  }
}

# ---------------------------------------------------------------------------
# Dead-Letter Queue
# ---------------------------------------------------------------------------
resource "aws_sqs_queue" "dlq" {
  count = local.create && var.create_dlq ? 1 : 0

  name                              = var.use_name_prefix ? null : local.dlq_name_full
  name_prefix                       = var.use_name_prefix ? local.dlq_name_base : null
  fifo_queue                        = var.fifo_queue
  deduplication_scope               = var.fifo_queue ? var.deduplication_scope : null
  fifo_throughput_limit             = var.fifo_queue ? var.fifo_throughput_limit : null
  content_based_deduplication       = var.fifo_queue ? var.content_based_deduplication : null
  delay_seconds                     = var.dlq_delay_seconds != null ? var.dlq_delay_seconds : var.delay_seconds
  max_message_size                  = var.dlq_max_message_size != null ? var.dlq_max_message_size : var.max_message_size
  message_retention_seconds         = var.dlq_message_retention_seconds != null ? var.dlq_message_retention_seconds : var.message_retention_seconds
  receive_wait_time_seconds         = var.dlq_receive_wait_time_seconds != null ? var.dlq_receive_wait_time_seconds : var.receive_wait_time_seconds
  visibility_timeout_seconds        = var.dlq_visibility_timeout_seconds != null ? var.dlq_visibility_timeout_seconds : var.visibility_timeout_seconds
  sqs_managed_sse_enabled           = local.dlq_kms_master_key_id != null ? null : local.dlq_sqs_managed_sse_enabled
  kms_master_key_id                 = local.dlq_kms_master_key_id
  kms_data_key_reuse_period_seconds = local.dlq_kms_data_key_reuse

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = local.dlq_name_full
  }
}

# ---------------------------------------------------------------------------
# DLQ Redrive Allow Policy (separate resource to break cycle)
# ---------------------------------------------------------------------------
resource "aws_sqs_queue_redrive_allow_policy" "dlq" {
  count = local.create && var.create_dlq && var.create_dlq_redrive_allow_policy ? 1 : 0

  queue_url = aws_sqs_queue.dlq[0].id

  redrive_allow_policy = jsonencode({
    redrivePermission = "byQueue",
    sourceQueueArns   = [aws_sqs_queue.main[0].arn]
  })
}

# ---------------------------------------------------------------------------
# Main Queue Policy
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "queue" {
  count = local.create && var.create_queue_policy ? 1 : 0

  source_policy_documents = var.queue_policy_document != null ? [var.queue_policy_document] : []

  dynamic "statement" {
    for_each = var.queue_policy_statements
    content {
      sid       = statement.value.sid
      effect    = statement.value.effect
      actions   = statement.value.actions
      resources = statement.value.resources != null ? statement.value.resources : [aws_sqs_queue.main[0].arn]

      dynamic "principals" {
        for_each = statement.value.principals != null ? statement.value.principals : []
        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = statement.value.conditions != null ? statement.value.conditions : []
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

resource "aws_sqs_queue_policy" "queue" {
  count = local.create && var.create_queue_policy ? 1 : 0

  queue_url = aws_sqs_queue.main[0].id
  policy    = data.aws_iam_policy_document.queue[0].json
}

# ---------------------------------------------------------------------------
# DLQ Queue Policy
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "dlq" {
  count = local.create && var.create_dlq && var.create_dlq_queue_policy ? 1 : 0

  source_policy_documents = var.dlq_queue_policy_document != null ? [var.dlq_queue_policy_document] : []

  dynamic "statement" {
    for_each = var.dlq_queue_policy_statements
    content {
      sid       = statement.value.sid
      effect    = statement.value.effect
      actions   = statement.value.actions
      resources = statement.value.resources != null ? statement.value.resources : [aws_sqs_queue.dlq[0].arn]

      dynamic "principals" {
        for_each = statement.value.principals != null ? statement.value.principals : []
        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = statement.value.conditions != null ? statement.value.conditions : []
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

resource "aws_sqs_queue_policy" "dlq" {
  count = local.create && var.create_dlq && var.create_dlq_queue_policy ? 1 : 0

  queue_url = aws_sqs_queue.dlq[0].id
  policy    = data.aws_iam_policy_document.dlq[0].json
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------
output "queue_id" {
  description = "Main queue URL"
  value       = try(aws_sqs_queue.main[0].id, null)
}

output "queue_arn" {
  description = "Main queue ARN"
  value       = try(aws_sqs_queue.main[0].arn, null)
}

output "queue_name" {
  description = "Main queue name"
  value       = try(aws_sqs_queue.main[0].name, null)
}

output "dlq_id" {
  description = "DLQ URL"
  value       = try(aws_sqs_queue.dlq[0].id, null)
}

output "dlq_arn" {
  description = "DLQ ARN"
  value       = try(aws_sqs_queue.dlq[0].arn, null)
}

output "dlq_name" {
  description = "DLQ name"
  value       = try(aws_sqs_queue.dlq[0].name, null)
}

# ------------------------------------------------------------------------------
# Automated AWS CodeDeploy release pipeline for AWS Lambda blue/green deployments
# managed via local CLI execution scripts.
# ------------------------------------------------------------------------------

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------

variable "create" {
  description = "Global switch controlling all resource creation in this module. Set to false to disable everything."
  type        = bool
  default     = true
}

variable "function_name" {
  description = "Name of the Lambda function deployed with the blue/green release."
  type        = string
  default     = "my-lambda-function"
}

variable "alias_name" {
  description = "Name of the Lambda alias that points to the function and is used to shift traffic."
  type        = string
  default     = "live"
}

variable "current_version" {
  description = "Version of the Lambda function currently receiving traffic (blue environment)."
  type        = string
  default     = "1"
}

variable "target_version" {
  description = "Version of the Lambda function that receives traffic after the deployment (green environment)."
  type        = string
  default     = "2"
}

variable "before_allow_traffic_hook_arn" {
  description = "ARN of the Lambda hook function invoked before traffic is shifted to the target version."
  type        = string
  default     = ""
}

variable "after_allow_traffic_hook_arn" {
  description = "ARN of the Lambda hook function invoked after traffic has been shifted to the target version."
  type        = string
  default     = ""
}

variable "create_app" {
  description = "Whether to create the CodeDeploy application. Only effective when use_existing_app is false."
  type        = bool
  default     = false
}

variable "use_existing_app" {
  description = "Whether to reference an already existing CodeDeploy application instead of creating one."
  type        = bool
  default     = false
}

variable "app_name" {
  description = "Name of the CodeDeploy application (created when create_app is true, otherwise the pre-existing one is referenced)."
  type        = string
  default     = "lambda-blue-green-app"
}

variable "create_deployment_group" {
  description = "Whether to create the CodeDeploy deployment group. Only effective when use_existing_deployment_group is false."
  type        = bool
  default     = false
}

variable "use_existing_deployment_group" {
  description = "Whether to reference an already existing CodeDeploy deployment group instead of creating one."
  type        = bool
  default     = false
}

variable "deployment_group_name" {
  description = "Name of the CodeDeploy deployment group (created when create_deployment_group is true, otherwise the pre-existing one is referenced)."
  type        = string
  default     = "lambda-blue-green-deployment-group"
}

variable "deployment_config_name" {
  description = "Name of the CodeDeploy deployment configuration controlling how traffic is shifted."
  type        = string
  default     = "CodeDeployDefault.LambdaAllAtOnce"
}

variable "create_codedeploy_role" {
  description = "Whether to create the IAM role used by CodeDeploy for deployments."
  type        = bool
  default     = true
}

variable "codedeploy_role_name" {
  description = "Name of the IAM role created for CodeDeploy."
  type        = string
  default     = "codedeploy-lambda-blue-green-role"
}

variable "codedeploy_role_arn" {
  description = "ARN of an existing IAM role to use when create_codedeploy_role is false."
  type        = string
  default     = ""
}

variable "codedeploy_service_principals" {
  description = "AWS service principals allowed to assume the CodeDeploy IAM role."
  type        = list(string)
  default     = ["codedeploy.amazonaws.com"]
}

variable "attach_hooks_policy" {
  description = "Whether to attach an inline IAM policy granting lambda:InvokeFunction on the lifecycle hook ARNs."
  type        = bool
  default     = true
}

variable "attach_triggers_policy" {
  description = "Whether to attach an inline IAM policy granting sns:Publish on the notification trigger target."
  type        = bool
  default     = false
}

variable "enable_auto_rollback" {
  description = "Whether to enable automatic rollback for created deployment groups."
  type        = bool
  default     = true
}

variable "auto_rollback_events" {
  description = "List of events that trigger an automatic rollback."
  type        = list(string)
  default     = ["DEPLOYMENT_STOP_ON_ALARM"]
}

variable "enable_cloudwatch_alarms" {
  description = "Whether to monitor CloudWatch alarms during deployments and stop the deployment when one is triggered."
  type        = bool
  default     = false
}

variable "cloudwatch_alarm_names" {
  description = "Names of existing CloudWatch alarms to monitor during deployments."
  type        = list(string)
  default     = []
}

variable "ignore_poll_alarm_failure" {
  description = "Whether to ignore failures to poll alarm state during a deployment."
  type        = bool
  default     = false
}

variable "enable_trigger_configuration" {
  description = "Whether to configure SNS notification triggers on the created deployment group."
  type        = bool
  default     = false
}

variable "trigger_name" {
  description = "Name of the notification trigger."
  type        = string
  default     = "lambda-deployment-notifications"
}

variable "trigger_events" {
  description = "Deployment events that produce a notification."
  type        = list(string)
  default     = ["DeploymentSuccess", "DeploymentFailure"]
}

variable "trigger_target_arn" {
  description = "ARN of the SNS topic that receives deployment notifications."
  type        = string
  default     = ""
}

variable "create_deployment" {
  description = "Whether to generate the AppSpec revision and the local CLI deployment script."
  type        = bool
  default     = false
}

variable "aws_cli_command" {
  description = "Command used to invoke the AWS CLI inside the generated deployment script."
  type        = string
  default     = "aws"
}

variable "get_deployment_sleep_timer" {
  description = "Seconds to sleep between status checks while monitoring a deployment."
  type        = number
  default     = 5
}

variable "monitor_deployment" {
  description = "Whether the generated script should poll get-deployment until the deployment reaches a terminal state."
  type        = bool
  default     = true
}

variable "deployment_description" {
  description = "Description attached to the created deployment."
  type        = string
  default     = "AWS Lambda blue/green deployment"
}

variable "save_deploy_script" {
  description = "Whether to persist the generated deployment shell script locally."
  type        = bool
  default     = false
}

variable "deploy_script_path" {
  description = "Local path where the generated deployment shell script is saved."
  type        = string
  default     = "deploy-lambda.sh"
}

variable "run_deployment" {
  description = "Whether to execute the deployment provisioner locally through a null_resource."
  type        = bool
  default     = false
}

variable "force_deploy" {
  description = "Whether to force the deployment provisioner to run again via a UUID-based trigger."
  type        = bool
  default     = false
}

variable "tags" {
  description = "Tags to apply to created resources."
  type        = map(string)
  default     = {}
}

# ------------------------------------------------------------------------------
# Data sources (static, provider-managed metadata only)
# ------------------------------------------------------------------------------

# Well-known AWS managed policy attached to the CodeDeploy service role.
data "aws_iam_policy" "codedeploy_lambda" {
  name = "AWSCodeDeployRoleForLambda"
}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------

locals {
  create_app_flag              = var.create && var.create_app && !var.use_existing_app
  create_deployment_group_flag = var.create && var.create_deployment_group && !var.use_existing_deployment_group
  create_role_flag             = var.create && var.create_codedeploy_role
  create_deployment_flag       = var.create && var.create_deployment

  effective_app_name              = local.create_app_flag ? aws_codedeploy_app.this[0].name : var.app_name
  effective_deployment_group_name = local.create_deployment_group_flag ? aws_codedeploy_deployment_group.this[0].deployment_group_name : var.deployment_group_name
  effective_service_role_arn      = local.create_role_flag ? aws_iam_role.codedeploy[0].arn : var.codedeploy_role_arn

  appspec_hooks = concat(
    var.before_allow_traffic_hook_arn != "" ? [{ BeforeAllowTraffic = var.before_allow_traffic_hook_arn }] : [],
    var.after_allow_traffic_hook_arn != "" ? [{ AfterAllowTraffic = var.after_allow_traffic_hook_arn }] : []
  )

  appspec = merge(
    {
      version = 0.0
      Resources = [
        {
          myLambdaFunction = {
            Type = "AWS::Lambda::Function"
            Properties = {
              Name           = var.function_name
              Alias          = var.alias_name
              CurrentVersion = var.current_version
              TargetVersion  = var.target_version
            }
          }
        }
      ]
    },
    length(local.appspec_hooks) > 0 ? { Hooks = local.appspec_hooks } : {}
  )

  appspec_json = jsonencode(local.appspec)

  # Full CodeDeploy revision payload with the AppSpec delivered as AppSpecContent.
  revision_json = jsonencode({
    revisionType = "AppSpecContent"
    appSpecContent = {
      content = local.appspec_json
    }
  })

  deploy_script = <<-EOT
#!/usr/bin/env bash
set -euo pipefail

AWS_CLI_COMMAND='${var.aws_cli_command}'
APP_NAME='${local.effective_app_name}'
DEPLOYMENT_GROUP_NAME='${local.effective_deployment_group_name}'
DEPLOYMENT_CONFIG_NAME='${var.deployment_config_name}'
DEPLOYMENT_DESCRIPTION='${var.deployment_description}'
MONITOR_DEPLOYMENT='${var.monitor_deployment}'
SLEEP_TIMER='${var.get_deployment_sleep_timer}'

# Write the AppSpec revision for the Lambda blue/green deployment to a temp file.
APPSPEC_FILE="$(mktemp /tmp/codedeploy-appspec.XXXXXX.json)"
trap 'rm -f "$APPSPEC_FILE"' EXIT

cat > "$APPSPEC_FILE" <<'APPSPEC'
${local.appspec_json}
APPSPEC

echo "Creating CodeDeploy deployment for application '$APP_NAME', deployment group '$DEPLOYMENT_GROUP_NAME' ..."
deployment_id="$($AWS_CLI_COMMAND deploy create-deployment \
  --application-name "$APP_NAME" \
  --deployment-group-name "$DEPLOYMENT_GROUP_NAME" \
  --deployment-config-name "$DEPLOYMENT_CONFIG_NAME" \
  --revision '${local.revision_json}' \
  --description "$DEPLOYMENT_DESCRIPTION" \
  --query "deploymentId" --output text)"

echo "Created CodeDeploy deployment: $deployment_id"

# Optionally monitor the deployment until it reaches a terminal state.
if [ "$MONITOR_DEPLOYMENT" = "true" ]; then
  echo "Monitoring deployment $deployment_id (polling every $SLEEP_TIMER second(s))..."
  while :; do
    status="$($AWS_CLI_COMMAND deploy get-deployment --deployment-id "$deployment_id" --query "deploymentInfo.status" --output text)"
    echo "[$(date -u +%Y-%m-%dT%H:%M:%SZ)] Deployment status: $status"
    if [ "$status" = "Succeeded" ]; then
      echo "Deployment $deployment_id Succeeded."
      exit 0
    fi
    case "$status" in
      Failed|Stopped)
        echo "Deployment $deployment_id finished with status '$status'." >&2
        exit 1
        ;;
    esac
    sleep "$SLEEP_TIMER"
  done
fi
  EOT
}

# ------------------------------------------------------------------------------
# CodeDeploy application (Lambda compute platform)
# ------------------------------------------------------------------------------

resource "aws_codedeploy_app" "this" {
  count            = local.create_app_flag ? 1 : 0
  name             = var.app_name
  compute_platform = "Lambda"
  tags             = var.tags
}

# ------------------------------------------------------------------------------
# CodeDeploy deployment group (blue/green with traffic control)
# ------------------------------------------------------------------------------

resource "aws_codedeploy_deployment_group" "this" {
  count                  = local.create_deployment_group_flag ? 1 : 0
  app_name               = local.effective_app_name
  deployment_group_name  = var.deployment_group_name
  service_role_arn       = local.effective_service_role_arn
  deployment_config_name = var.deployment_config_name
  tags                   = var.tags

  depends_on = [aws_codedeploy_app.this]

  deployment_style {
    deployment_option = "WITH_TRAFFIC_CONTROL"
    deployment_type   = "BLUE_GREEN"
  }

  auto_rollback_configuration {
    enabled = var.enable_auto_rollback
    events  = var.auto_rollback_events
  }

  dynamic "alarm_configuration" {
    for_each = var.enable_cloudwatch_alarms && length(var.cloudwatch_alarm_names) > 0 ? [1] : []
    content {
      enabled                   = true
      alarms                    = var.cloudwatch_alarm_names
      ignore_poll_alarm_failure = var.ignore_poll_alarm_failure
    }
  }

  dynamic "trigger_configuration" {
    for_each = var.enable_trigger_configuration && var.trigger_target_arn != "" ? [1] : []
    content {
      trigger_events     = var.trigger_events
      trigger_name       = var.trigger_name
      trigger_target_arn = var.trigger_target_arn
    }
  }
}

# ------------------------------------------------------------------------------
# IAM role for CodeDeploy
# ------------------------------------------------------------------------------

resource "aws_iam_role" "codedeploy" {
  count       = local.create_role_flag ? 1 : 0
  name        = var.codedeploy_role_name
  description = "Allows AWS CodeDeploy to perform Lambda blue/green deployments on your behalf."
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = var.codedeploy_service_principals
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "codedeploy_lambda" {
  count      = local.create_role_flag ? 1 : 0
  role       = aws_iam_role.codedeploy[0].name
  policy_arn = data.aws_iam_policy.codedeploy_lambda.arn
}

resource "aws_iam_role_policy" "hooks" {
  count = local.create_role_flag && var.attach_hooks_policy && (var.before_allow_traffic_hook_arn != "" || var.after_allow_traffic_hook_arn != "") ? 1 : 0
  name  = "codedeploy-lambda-invoke-hooks"
  role  = aws_iam_role.codedeploy[0].id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["lambda:InvokeFunction"]
        Resource = distinct(compact([var.before_allow_traffic_hook_arn, var.after_allow_traffic_hook_arn]))
      }
    ]
  })
}

resource "aws_iam_role_policy" "triggers" {
  count = local.create_role_flag && var.attach_triggers_policy && var.trigger_target_arn != "" ? 1 : 0
  name  = "codedeploy-sns-publish-triggers"
  role  = aws_iam_role.codedeploy[0].id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["sns:Publish"]
        Resource = [var.trigger_target_arn]
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# Local deployment provisioner (AppSpec revision + CLI execution scripts)
# ------------------------------------------------------------------------------

resource "random_uuid" "deploy" {
  count = local.create_deployment_flag && var.force_deploy ? 1 : 0
}

resource "local_file" "deploy_script" {
  count           = local.create_deployment_flag && (var.save_deploy_script || var.run_deployment) ? 1 : 0
  content         = local.deploy_script
  filename        = var.deploy_script_path
  file_permission = "0700"
}

resource "null_resource" "deployment" {
  count = local.create_deployment_flag && var.run_deployment ? 1 : 0

  depends_on = [local_file.deploy_script, aws_codedeploy_deployment_group.this]

  triggers = {
    force_deploy  = var.force_deploy ? random_uuid.deploy[0].result : "0"
    script_sha256 = sha256(local.deploy_script)
  }

  provisioner "local-exec" {
    command     = "AWS_PAGER='' ${startswith(var.deploy_script_path, "/") ? var.deploy_script_path : "./${var.deploy_script_path}"}"
    interpreter = ["/bin/bash", "-c"]
  }
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0.0"
    }
  }
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.16.0.0/16"
}

variable "vpc_name_prefix" {
  description = "Prefix used for the VPC (and related resource) name tags"
  type        = string
  default     = "tf-project"
}

variable "max_subnet_count" {
  description = "Maximum number of shuffled availability zones from the target region to distribute subnets across"
  type        = number
  default     = 3
}

variable "web_subnet_cidr_blocks" {
  description = "List of CIDR blocks for the web (public) subnets. Each entry creates one subnet."
  type        = list(string)
  default     = ["10.16.0.0/24", "10.16.1.0/24", "10.16.2.0/24"]
}

variable "application_subnet_cidr_blocks" {
  description = "List of CIDR blocks for the application (private) subnets. Each entry creates one subnet."
  type        = list(string)
  default     = ["10.16.10.0/24", "10.16.11.0/24", "10.16.12.0/24"]
}

variable "database_subnet_cidr_blocks" {
  description = "List of CIDR blocks for the database (private) subnets. Each entry creates one subnet."
  type        = list(string)
  default     = ["10.16.20.0/24", "10.16.21.0/24", "10.16.22.0/24"]
}

variable "reserved_subnet_cidr_blocks" {
  description = "List of CIDR blocks for the reserved (private) subnets. Each entry creates one subnet."
  type        = list(string)
  default     = ["10.16.30.0/24", "10.16.31.0/24", "10.16.32.0/24"]
}

variable "interface_vpc_endpoints" {
  description = "Optional map of interface VPC endpoints to create. Each key is a logical name and its value configures the endpoint."
  type = map(object({
    service             = string
    private_dns_enabled = optional(bool, true)
    subnet_ids          = optional(list(string), [])
  }))
  default = {}
}

variable "gateway_vpc_endpoint" {
  description = "Optional gateway VPC endpoint configuration. When service_name is non-empty a gateway endpoint is created and associated with the private route table."
  type = object({
    service_name = optional(string, "")
  })
  default = { service_name = "" }
}

variable "tags" {
  description = "Additional tags to apply to all resources"
  type        = map(string)
  default     = {}
}

locals {
  has_web_subnets     = length(var.web_subnet_cidr_blocks) > 0
  has_private_subnets = length(var.application_subnet_cidr_blocks) + length(var.database_subnet_cidr_blocks) + length(var.reserved_subnet_cidr_blocks) > 0
  # One private subnet per availability zone, so interface VPC endpoints can be created without
  # duplicate subnets in the same AZ (AWS rejects interface endpoints with two subnets in one AZ).
  endpoint_subnet_ids = [
    for _, ids in {
      for s in concat(
        [for subnet in aws_subnet.application : { id = subnet.id, az = subnet.availability_zone }],
        [for subnet in aws_subnet.database : { id = subnet.id, az = subnet.availability_zone }],
        [for subnet in aws_subnet.reserved : { id = subnet.id, az = subnet.availability_zone }],
      ) : s.az => s.id...
    } : ids[0]
  ]
  shuffled_azs = random_shuffle.azs.result
  # The web tier is a public tier: instances launched into these subnets receive a public IPv4 address when the
  # target region provides availability zones (which is always true at apply time in a supported region).
  web_subnet_auto_map_public_ip = length(data.aws_availability_zones.available.names) > 0
}

resource "random_integer" "suffix" {
  min = 1
  max = 100
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "random_shuffle" "azs" {
  input        = data.aws_availability_zones.available.names
  result_count = min(var.max_subnet_count, length(data.aws_availability_zones.available.names))
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(var.tags, {
    Name = "${var.vpc_name_prefix}-${random_integer.suffix.result}"
  })
}

resource "aws_subnet" "web" {
  count                   = length(var.web_subnet_cidr_blocks)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.web_subnet_cidr_blocks[count.index]
  availability_zone       = local.shuffled_azs[count.index % max(1, length(local.shuffled_azs))]
  map_public_ip_on_launch = local.web_subnet_auto_map_public_ip

  tags = merge(var.tags, {
    Name = "${var.vpc_name_prefix}-${random_integer.suffix.result}-web-${count.index + 1}"
    Tier = "web"
  })
}

resource "aws_subnet" "application" {
  count             = length(var.application_subnet_cidr_blocks)
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.application_subnet_cidr_blocks[count.index]
  availability_zone = local.shuffled_azs[count.index % max(1, length(local.shuffled_azs))]

  tags = merge(var.tags, {
    Name = "${var.vpc_name_prefix}-${random_integer.suffix.result}-application-${count.index + 1}"
    Tier = "application"
  })
}

resource "aws_subnet" "database" {
  count             = length(var.database_subnet_cidr_blocks)
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.database_subnet_cidr_blocks[count.index]
  availability_zone = local.shuffled_azs[count.index % max(1, length(local.shuffled_azs))]

  tags = merge(var.tags, {
    Name = "${var.vpc_name_prefix}-${random_integer.suffix.result}-database-${count.index + 1}"
    Tier = "database"
  })
}

resource "aws_subnet" "reserved" {
  count             = length(var.reserved_subnet_cidr_blocks)
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.reserved_subnet_cidr_blocks[count.index]
  availability_zone = local.shuffled_azs[count.index % max(1, length(local.shuffled_azs))]

  tags = merge(var.tags, {
    Name = "${var.vpc_name_prefix}-${random_integer.suffix.result}-reserved-${count.index + 1}"
    Tier = "reserved"
  })
}

resource "aws_internet_gateway" "main" {
  count  = local.has_web_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "${var.vpc_name_prefix}-${random_integer.suffix.result}"
  })
}

resource "aws_route_table" "public" {
  count  = local.has_web_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "${var.vpc_name_prefix}-${random_integer.suffix.result}-public"
  })
}

resource "aws_route" "public_internet_gateway" {
  count                  = local.has_web_subnets ? 1 : 0
  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main[0].id
}

resource "aws_route_table_association" "public" {
  count          = length(var.web_subnet_cidr_blocks)
  subnet_id      = aws_subnet.web[count.index].id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_route_table" "private" {
  count  = local.has_private_subnets ? 1 : 0
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "${var.vpc_name_prefix}-${random_integer.suffix.result}-private"
  })
}

resource "aws_route_table_association" "application" {
  count          = length(var.application_subnet_cidr_blocks)
  subnet_id      = aws_subnet.application[count.index].id
  route_table_id = aws_route_table.private[0].id
}

resource "aws_route_table_association" "database" {
  count          = length(var.database_subnet_cidr_blocks)
  subnet_id      = aws_subnet.database[count.index].id
  route_table_id = aws_route_table.private[0].id
}

resource "aws_route_table_association" "reserved" {
  count          = length(var.reserved_subnet_cidr_blocks)
  subnet_id      = aws_subnet.reserved[count.index].id
  route_table_id = aws_route_table.private[0].id
}

resource "aws_security_group" "vpc_endpoints" {
  count       = length(var.interface_vpc_endpoints) > 0 ? 1 : 0
  name_prefix = "${var.vpc_name_prefix}-${random_integer.suffix.result}-endpoints"
  description = "Security group for interface VPC endpoints"
  vpc_id      = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "${var.vpc_name_prefix}-${random_integer.suffix.result}-vpc-endpoints"
  })
}

resource "aws_security_group_rule" "endpoints_ingress" {
  count             = length(var.interface_vpc_endpoints) > 0 ? 1 : 0
  type              = "ingress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = [var.vpc_cidr_block]
  security_group_id = aws_security_group.vpc_endpoints[0].id
}

resource "aws_security_group_rule" "endpoints_egress" {
  count             = length(var.interface_vpc_endpoints) > 0 ? 1 : 0
  type              = "egress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = [var.vpc_cidr_block]
  security_group_id = aws_security_group.vpc_endpoints[0].id
}

resource "aws_vpc_endpoint" "interface" {
  for_each            = var.interface_vpc_endpoints
  vpc_id              = aws_vpc.main.id
  service_name        = each.value.service
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = each.value.private_dns_enabled
  subnet_ids          = length(each.value.subnet_ids) > 0 ? each.value.subnet_ids : local.endpoint_subnet_ids
  security_group_ids  = [aws_security_group.vpc_endpoints[0].id]

  tags = merge(var.tags, {
    Name = "${var.vpc_name_prefix}-${random_integer.suffix.result}-vpce-${each.key}"
  })
}

resource "aws_vpc_endpoint" "gateway" {
  count             = var.gateway_vpc_endpoint.service_name != "" ? 1 : 0
  vpc_id            = aws_vpc.main.id
  service_name      = var.gateway_vpc_endpoint.service_name
  vpc_endpoint_type = "Gateway"
  route_table_ids   = local.has_private_subnets ? [aws_route_table.private[0].id] : []

  tags = merge(var.tags, {
    Name = "${var.vpc_name_prefix}-${random_integer.suffix.result}-gateway-endpoint"
  })
}

output "vpc_id" {
  description = "The ID of the created VPC"
  value       = aws_vpc.main.id
}

output "public_route_table_id" {
  description = "The ID of the public route table"
  value       = local.has_web_subnets ? aws_route_table.public[0].id : null
}

output "private_route_table_id" {
  description = "The ID of the shared private route table"
  value       = local.has_private_subnets ? aws_route_table.private[0].id : null
}

output "web_subnet_ids" {
  description = "The IDs of the web (public) subnets"
  value       = aws_subnet.web[*].id
}

output "application_subnet_ids" {
  description = "The IDs of the application (private) subnets"
  value       = aws_subnet.application[*].id
}

output "database_subnet_ids" {
  description = "The IDs of the database (private) subnets"
  value       = aws_subnet.database[*].id
}

output "reserved_subnet_ids" {
  description = "The IDs of the reserved (private) subnets"
  value       = aws_subnet.reserved[*].id
}

variable "admin_cidrs" {
  description = "CIDR blocks allowed to reach the Home SSH security group on SSH."
  type        = list(string)
  default     = ["203.0.113.0/24"]
}

variable "internal_domain" {
  description = "Internal DNS domain name served by the private hosted zone and DHCP options."
  type        = string
  default     = "internal"
}

variable "dns_resolvers" {
  description = "DNS name servers used by DHCP options (AmazonProvidedDNS plus a public resolver)."
  type        = list(string)
  default     = ["AmazonProvidedDNS", "8.8.8.8"]
}

locals {
  vpc_cidr      = "10.0.0.0/16"
  sandbox_cidr  = "10.0.1.0/24"
  web_cidr      = "10.0.2.0/24"
  database_cidr = "10.0.3.0/24"
  gameserver_cidr = "10.0.4.0/22"
}

data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------
# Base network
# ---------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main"
  }
}

resource "aws_internet_gateway" "ig" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "ig"
  }
}

resource "aws_vpc_dhcp_options" "main" {
  domain_name         = var.internal_domain
  domain_name_servers = var.dns_resolvers

  tags = {
    Name = "main"
  }
}

resource "aws_vpc_dhcp_options_association" "main" {
  vpc_id          = aws_vpc.main.id
  dhcp_options_id = aws_vpc_dhcp_options.main.id
}

resource "aws_route53_zone" "internal" {
  name = var.internal_domain

  vpc {
    vpc_id = aws_vpc.main.id
  }

  comment = "Private hosted zone for the internal domain of the main VPC."

  tags = {
    Name = "internal"
  }
}

# ---------------------------------------------------------------------------
# Subnets, route tables, and routing
# ---------------------------------------------------------------------------
resource "aws_subnet" "reserved" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.0.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "reserved"
  }
}

resource "aws_subnet" "sandbox" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.sandbox_cidr
  availability_zone = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "sandbox"
  }
}

resource "aws_subnet" "web" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.web_cidr
  availability_zone = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "web"
  }
}

resource "aws_subnet" "database" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.database_cidr
  availability_zone = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "database"
  }
}

resource "aws_subnet" "gameserver" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.gameserver_cidr
  availability_zone = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "gameserver"
  }
}

resource "aws_route_table" "reserved" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "reserved"
  }
}

resource "aws_route_table" "sandbox" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "sandbox"
  }
}

resource "aws_route_table" "web" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "web"
  }
}

resource "aws_route_table" "database" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "database"
  }
}

resource "aws_route_table" "gameserver" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "gameserver"
  }
}

resource "aws_route" "reserved" {
  route_table_id         = aws_route_table.reserved.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.ig.id
}

resource "aws_route" "sandbox" {
  route_table_id         = aws_route_table.sandbox.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.ig.id
}

resource "aws_route" "web" {
  route_table_id         = aws_route_table.web.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.ig.id
}

resource "aws_route" "database" {
  route_table_id         = aws_route_table.database.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.ig.id
}

resource "aws_route" "gameserver" {
  route_table_id         = aws_route_table.gameserver.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.ig.id
}

resource "aws_route_table_association" "reserved" {
  subnet_id      = aws_subnet.reserved.id
  route_table_id = aws_route_table.reserved.id
}

resource "aws_route_table_association" "sandbox" {
  subnet_id      = aws_subnet.sandbox.id
  route_table_id = aws_route_table.sandbox.id
}

resource "aws_route_table_association" "web" {
  subnet_id      = aws_subnet.web.id
  route_table_id = aws_route_table.web.id
}

resource "aws_route_table_association" "database" {
  subnet_id      = aws_subnet.database.id
  route_table_id = aws_route_table.database.id
}

resource "aws_route_table_association" "gameserver" {
  subnet_id      = aws_subnet.gameserver.id
  route_table_id = aws_route_table.gameserver.id
}

# ---------------------------------------------------------------------------
# Network ACLs
# ---------------------------------------------------------------------------
resource "aws_network_acl" "sandbox" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "sandbox"
  }
}

resource "aws_network_acl_rule" "sandbox_ingress_tcp" {
  network_acl_id = aws_network_acl.sandbox.id
  rule_number    = 100
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 0
  to_port        = 65535
}

resource "aws_network_acl_rule" "sandbox_egress_tcp" {
  network_acl_id = aws_network_acl.sandbox.id
  rule_number    = 100
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 0
  to_port        = 65535
}

resource "aws_network_acl" "web" {
  vpc_id = aws_vpc.main.id

  tags = {
