  to_port        = 443
}

resource "aws_network_acl_rule" "web_ingress_ephemeral" {
  network_acl_id = aws_network_acl.web.id
  rule_number    = 130
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
