resource "aws_network_acl_rule" "web_egress_tcp" {
  network_acl_id = aws_network_acl.web.id
  rule_number    = 100
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 0
  to_port        = 65535
}

resource "aws_network_acl" "database" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "database"
  }
}

resource "aws_network_acl_rule" "database_ingress_from_web" {
