# ---------------------------------------------------------------------------
# Security groups
# ---------------------------------------------------------------------------
resource "aws_security_group" "home_ssh" {
  name        = "Home SSH"
  description = "Allows SSH from admin CIDRs and from itself; outbound restricted to the VPC CIDR."
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "Home SSH"
  }
}

resource "aws_security_group_rule" "home_ssh_ingress_admin" {
  type              = "ingress"
  from_port         = 22
  to_port           = 22
  protocol          = "tcp"
  cidr_blocks       = var.admin_cidrs
  security_group_id = aws_security_group.home_ssh.id
}

resource "aws_security_group_rule" "home_ssh_ingress_self" {
  type                     = "ingress"
  from_port                = 22
  to_port                  = 22
  protocol                 = "tcp"
  self                     = true
  security_group_id        = aws_security_group.home_ssh.id
}

resource "aws_security_group_rule" "home_ssh_egress" {
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [local.vpc_cidr]
  security_group_id = aws_security_group.home_ssh.id
}

resource "aws_security_group" "packer_ssh" {
  name        = "Packer SSH"
  description = "Allows SSH from the VPC CIDR and from itself; outbound restricted to the VPC CIDR."
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "Packer SSH"
  }
}

resource "aws_security_group_rule" "packer_ssh_ingress_vpc" {
  type              = "ingress"
  from_port         = 22
  to_port           = 22
  protocol          = "tcp"
  cidr_blocks       = [local.vpc_cidr]
  security_group_id = aws_security_group.packer_ssh.id
}

resource "aws_security_group_rule" "packer_ssh_ingress_self" {
  type                     = "ingress"
  from_port                = 22
  to_port                  = 22
  protocol                 = "tcp"
  self                     = true
  security_group_id        = aws_security_group.packer_ssh.id
}

resource "aws_security_group_rule" "packer_ssh_egress" {
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [local.vpc_cidr]
  security_group_id = aws_security_group.packer_ssh.id
}

variable "env" {
  description = "Environment name to prefix resource Name tags"
  type        = string
  default     = ""
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs    = data.aws_availability_zones.available.names
  prefix = var.env != "" ? "${var.env}-" : ""
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true

  tags = {
    Name = "${local.prefix}main"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.prefix}main"
  }
}

resource "aws_eip" "nat" {
  count  = 3
  domain = "vpc"

  tags = {
    Name = "${local.prefix}nat-${count.index + 1}"
  }
}

resource "aws_nat_gateway" "main" {
  count     = 3
  allocation_id = aws_eip.nat[count.index].id
  subnet_id = aws_subnet.public[count.index].id

  tags = {
    Name = "${local.prefix}nat-${count.index + 1}"
  }
}

resource "aws_subnet" "public" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.${count.index + 1}.0/24"
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.prefix}public-${count.index + 1}"
  }
}

resource "aws_subnet" "private_app" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.${(count.index + 1) * 10}.0/24"
  availability_zone = local.azs[count.index]

  tags = {
    Name = "${local.prefix}private-app-${count.index + 1}"
  }
}

resource "aws_subnet" "private_db" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.${100 + count.index * 10}.0/24"
  availability_zone = local.azs[count.index]

  tags = {
    Name = "${local.prefix}private-db-${count.index + 1}"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${local.prefix}public"
  }
}

resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private_app" {
  count = 3

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }

  tags = {
    Name = "${local.prefix}private-app-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private_app" {
  count = 3

  subnet_id      = aws_subnet.private_app[count.index].id
  route_table_id = aws_route_table.private_app[count.index].id
}

resource "aws_route_table" "private_db" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.prefix}private-db"
  }
}

resource "aws_route_table_association" "private_db" {
  count = 3

  subnet_id      = aws_subnet.private_db[count.index].id
  route_table_id = aws_route_table.private_db.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

variable "bucket_name" {
  description = "Base name for the S3 bucket"
  type        = string
  default     = "benchmark-bucket-tf5x"
}

variable "use_account_alias_prefix" {
  description = "Prefix bucket name with the AWS account ID"
  type        = bool
  default     = false
}

variable "use_random_suffix" {
  description = "Use a random hex suffix prefix for the bucket name"
  type        = bool
  default     = false
}

variable "custom_bucket_policy" {
  description = "Custom JSON bucket policy to extend with required security statements"
  type        = string
  default     = ""
}

variable "enable_s3_public_access_block" {
  description = "Enable public access block on the bucket"
  type        = bool
  default     = true
}

variable "kms_master_key_id" {
  description = "KMS master key ID for server-side encryption (null uses AES256)"
  type        = string
  default     = null
}

variable "bucket_key_enabled" {
  description = "Enable bucket key for server-side encryption"
  type        = bool
  default     = false
}

variable "bucket_force_destroy" {
  description = "Force destroy the bucket even when non-empty"
  type        = bool
  default     = false
}

variable "transition_minimum_object_size" {
  description = "Minimum object size for lifecycle transitions (e.g., all_storage_classes_128K)"
  type        = string
  default     = "all_storage_classes_128K"
}

variable "enable_analytics" {
  description = "Enable storage class analytics"
  type        = bool
  default     = true
}

variable "enable_bucket_inventory" {
  description = "Enable bucket inventory reporting"
  type        = bool
  default     = false
}

variable "logging_bucket" {
  description = "External target bucket for access logging (null to disable)"
  type        = string
  default     = null
}

variable "transfer_acceleration" {
  description = "Transfer acceleration status (Enabled or Disabled, null to disable resource)"
  type        = string
  default     = null
}

variable "s3_bucket_acl" {
  description = "Bucket ACL to apply (e.g., private, public-read, authenticated-read)"
  type        = string
  default     = null
}

variable "cors_rules" {
  description = "List of CORS rule maps, each with optional keys: allowed_headers, allowed_methods, allowed_origins, expose_headers, max_age_seconds"
  type        = list(any)
  default     = []
}

locals {
  account_prefix  = var.use_account_alias_prefix ? "${data.aws_caller_identity.current.account_id}-" : ""
  random_prefix   = var.use_random_suffix ? "${substr(md5(data.aws_caller_identity.current.account_id), 0, 8)}-" : ""
  bucket_name     = substr(replace("${local.account_prefix}${local.random_prefix}${var.bucket_name}", "/[^a-z0-9._-]/", "-"), 0, 63)

  # Transition default minimum object size for lifecycle rules
  min_object_size = var.transition_minimum_object_size

  # Required policy statements for security compliance
  required_statements = [
    {
      Sid       = "DenyNonTLS"
      Effect    = "Deny"
      Principal = "*"
      Action    = "s3:*"
      Resource  = [
        "arn:${data.aws_partition.current.partition}:s3:::${local.bucket_name}",
        "arn:${data.aws_partition.current.partition}:s3:::${local.bucket_name}/*"
      ]
      Condition = {
        Bool = {
          "aws:SecureTransport" = false
        }
      }
    },
    {
      Sid       = "AllowS3ServiceInventoryAnalytics"
      Effect    = "Allow"
      Principal = {
        Service = "s3.amazonaws.com"
      }
      Action = [
        "s3:PutObject",
        "s3:GetObject"
      ]
      Resource = [
        "arn:${data.aws_partition.current.partition}:s3:::${local.bucket_name}",
        "arn:${data.aws_partition.current.partition}:s3:::${local.bucket_name}/*"
      ]
    }
  ]

  # Parse custom policy statements if a custom policy JSON was provided
  custom_statements = var.custom_bucket_policy != "" ? try(jsondecode(var.custom_bucket_policy).Statement, []) : []

  # Combine required statements first, then custom statements
  all_statements = concat(local.required_statements, local.custom_statements)

  # Build the final policy document
  bucket_policy = jsonencode({
    Version   = "2012-10-17"
    Statement = local.all_statements
  })

  # Determine encryption algorithm
  encryption_algorithm = var.kms_master_key_id != null ? "aws:kms" : "AES256"
}

# ---------------------------------------------------------------------------
# MAIN S3 BUCKET
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "main" {
  bucket        = local.bucket_name
  force_destroy = var.bucket_force_destroy
}

# ---------------------------------------------------------------------------
# VERSIONING CONFIGURATION
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_versioning" "main" {
  bucket = aws_s3_bucket.main.id
  versioning_configuration {
    status = "Enabled"
  }
}

# ---------------------------------------------------------------------------
# PUBLIC ACCESS BLOCK
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_public_access_block" "main" {
  count                   = var.enable_s3_public_access_block ? 1 : 0
  bucket                  = aws_s3_bucket.main.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ---------------------------------------------------------------------------
# SERVER-SIDE ENCRYPTION CONFIGURATION
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm    = local.encryption_algorithm
      kms_master_key_id = var.kms_master_key_id
    }
  }
}

# ---------------------------------------------------------------------------
# BUCKET POLICY
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_policy" "main" {
  bucket = aws_s3_bucket.main.id
  policy = local.bucket_policy
}

# ---------------------------------------------------------------------------
# ACL (applied conditionally)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_acl" "main" {
  count  = var.s3_bucket_acl != null ? 1 : 0
  bucket = aws_s3_bucket.main.id
  acl    = var.s3_bucket_acl
}

# ---------------------------------------------------------------------------
# LOGGING CONFIGURATION (applied conditionally)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_logging" "main" {
  count          = var.logging_bucket != null ? 1 : 0
  bucket         = aws_s3_bucket.main.id
  target_bucket  = var.logging_bucket
  target_prefix  = "s3/${local.bucket_name}/"
}

# ---------------------------------------------------------------------------
# CORS CONFIGURATION (applied dynamically)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_cors_configuration" "main" {
  count  = length(var.cors_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.main.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = try(cors_rule.value.allowed_headers, null)
      allowed_methods = try(cors_rule.value.allowed_methods, null)
      allowed_origins = try(cors_rule.value.allowed_origins, null)
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

# ---------------------------------------------------------------------------
# LIFECYCLE CONFIGURATION – core rules (abort multipart, transition, expire)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_lifecycle_configuration" "core" {
  bucket = aws_s3_bucket.main.id
  transition_default_minimum_object_size = local.min_object_size

  rule {
    id     = "abort-incomplete-multipart-uploads"
    status = "Enabled"

    filter {
      prefix = ""
    }

    abort_incomplete_multipart_upload {
      days_after_initiation = 14
    }
  }

  rule {
    id     = "transition-noncurrent-to-standard-ia"
    status = "Enabled"

    filter {
      prefix = ""
    }

    noncurrent_version_transition {
      noncurrent_days = 30
      storage_class   = "STANDARD_IA"
    }
  }

  rule {
    id     = "expire-noncurrent-versions"
    status = "Enabled"

    filter {
      prefix = ""
    }

    noncurrent_version_expiration {
      noncurrent_days = 365
    }
  }
}

# ---------------------------------------------------------------------------
# LIFECYCLE CONFIGURATION – expire analytics data (30 days)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_lifecycle_configuration" "expire_analytics" {
  count  = var.enable_analytics ? 1 : 0
  bucket = aws_s3_bucket.main.id

  rule {
    id     = "expire-analytics-data"
    status = "Enabled"

    filter {
      prefix = "_AWSBucketAnalytics/"
    }

    expiration {
      days = 30
    }
  }
}

# ---------------------------------------------------------------------------
# LIFECYCLE CONFIGURATION – expire inventory data (14 days)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_lifecycle_configuration" "expire_inventory" {
  count  = var.enable_bucket_inventory ? 1 : 0
  bucket = aws_s3_bucket.main.id

  rule {
    id     = "expire-inventory-data"
    status = "Enabled"

    filter {
      prefix = "_AWSBucketInventory/"
    }

    expiration {
      days = 14
    }
  }
}

# ---------------------------------------------------------------------------
# ANALYTICS CONFIGURATION (Storage Class Analytics)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_metric" "main" {
  count  = var.enable_analytics ? 1 : 0
  bucket = aws_s3_bucket.main.id
  name   = "StorageClassAnalytics"

  filter {
    prefix = ""
  }
}

# ---------------------------------------------------------------------------
# INVENTORY CONFIGURATION
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_inventory" "main" {
  count                    = var.enable_bucket_inventory ? 1 : 0
  bucket                   = aws_s3_bucket.main.id
  included_object_versions = "Current"
  name                     = "BucketInventory"

  destination {
    bucket {
      bucket_arn = aws_s3_bucket.main.arn
      format     = "ORC"
      prefix     = "_AWSBucketInventory/"
    }
  }

  schedule {
    frequency = "Weekly"
  }
}

# ---------------------------------------------------------------------------
# TRANSFER ACCELERATION (conditionally applied)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_accelerate_configuration" "main" {
  count  = var.transfer_acceleration != null ? 1 : 0
  bucket = aws_s3_bucket.main.id
  status = var.transfer_acceleration
}

variable "bucket_name" {
  description = "Name of the S3 bucket"
  type        = string
  default     = "benchmark-access-logs-bkt"
}

variable "environment" {
  description = "Environment tag value"
  type        = string
  default     = "Development"
}

variable "extra_tags" {
  description = "Additional tags to merge"
  type        = map(string)
  default     = {}
}

# --- Server-Side Encryption ---
variable "sse_algorithm" {
  description = "Server-side encryption algorithm (AES256, aws:kms, or none)"
  type        = string
  default     = "AES256"
}

variable "kms_key_id" {
  description = "KMS key ID or ARN for SSE-KMS"
  type        = string
  default     = null
}

variable "bucket_key_enabled" {
  description = "Whether to use S3 Bucket Key for SSE-KMS"
  type        = bool
  default     = true
}

# --- Public Access Block ---
variable "block_public_access" {
  description = "Whether to create public access block settings"
  type        = bool
  default     = true
}

variable "block_public_acls" {
  description = "Block public ACLs"
  type        = bool
  default     = true
}

variable "block_public_policy" {
  description = "Block public bucket policies"
  type        = bool
  default     = true
}

variable "ignore_public_acls" {
  description = "Ignore public ACLs"
  type        = bool
  default     = true
}

variable "restrict_public_buckets" {
  description = "Restrict public buckets"
  type        = bool
  default     = true
}

# --- ACL / Grants ---
variable "canned_acl" {
  description = "Canned ACL to apply (e.g. private, public-read, etc.)"
  type        = string
  default     = null
}

variable "grants_json" {
  description = <<-EOT
    JSON-encoded list of grant objects. Each object must contain:
      - permission: string (e.g. "FULL_CONTROL", "READ", "WRITE", "READ_ACP", "WRITE_ACP")
      - type: string (e.g. "CanonicalUser", "Group")
      - id: string (canonical user ID, required for CanonicalUser)
      - uri: string (URI for Group type, e.g. http://acs.amazonaws.com/groups/global/AllUsers)
  EOT
  type        = string
  default     = null
}

# --- Bucket Ownership ---
variable "control_object_ownership" {
  description = "Whether to manage bucket ownership controls"
  type        = bool
  default     = false
}

variable "object_ownership" {
  description = "Object ownership setting (BucketOwnerPreferred, ObjectWriter, or BucketOwnerEnforced)"
  type        = string
  default     = "ObjectWriter"
}

# --- Versioning ---
variable "versioning_enabled" {
  description = "Enable bucket versioning"
  type        = bool
  default     = false
}

variable "mfa_delete" {
  description = "Enable MFA delete"
  type        = bool
  default     = false
}

# --- Logging ---
variable "bucket_logging" {
  description = "Whether to enable bucket logging"
  type        = bool
  default     = false
}

variable "log_bucket" {
  description = "Target bucket name for log delivery"
  type        = string
  default     = null
}

variable "log_prefix" {
  description = "Prefix for log objects"
  type        = string
  default     = null
}

# --- Object Lock ---
variable "object_lock_enabled" {
  description = "Enable S3 Object Lock (cannot be changed after bucket creation)"
  type        = bool
  default     = false
}

variable "object_lock_mode" {
  description = "Object Lock retention mode (GOVERNANCE or COMPLIANCE)"
  type        = string
  default     = "GOVERNANCE"
}

variable "object_lock_days" {
  description = "Object Lock retention days"
  type        = number
  default     = null
}

# --- Static Website ---
variable "website_config_json" {
  description = <<-EOT
    JSON-encoded static website configuration. Supports:
    {
      "index_document": {"suffix": "index.html"},
      "error_document": {"key": "error.html"},
      "redirect_all_requests_to": {"host_name": "example.com", "protocol": "https"},
      "routing_rules": [...]
    }
  EOT
  type        = string
  default     = null
}

# --- Intelligent Tiering ---
variable "intelligent_tiering_json" {
  description = <<-EOT
    JSON-encoded intelligent tiering configuration:
    {
      "name": "my-tiering",
      "tierings": [
        {"access_tier": "DEEP_ARCHIVE_ACCESS", "days": 180}
      ],
      "filter": {"prefix": "logs/"}
    }
  EOT
  type        = string
  default     = null
}

# --- CloudWatch Metrics ---
variable "metrics_json" {
  description = <<-EOT
    JSON-encoded list of CloudWatch metrics configurations:
    [
      {
        "name": "my-metric",
        "filter": {"prefix": "logs/", "tags": {"key": "val"}}
      }
    ]
  EOT
  type        = string
  default     = null
}

# --- CORS ---
variable "cors_rules_json" {
  description = <<-EOT
    JSON-encoded list of CORS rules:
    [
      {
        "allowed_headers": ["*"],
        "allowed_methods": ["GET"],
        "allowed_origins": ["*"],
        "expose_headers": ["ETag"],
        "max_age_seconds": 3600
      }
    ]
  EOT
  type        = string
  default     = null
}

# --- Lifecycle ---
variable "lifecycle_rules_json" {
  description = <<-EOT
    JSON-encoded list of lifecycle rules:
    [
      {
        "id": "rule1",
        "status": "Enabled",
        "abort_incomplete_multipart_upload_days": 7,
        "expiration_days": 365,
        "expiration_date": null,
        "noncurrent_version_expiration_days": 90,
        "transitions": [
          {"days": 30, "storage_class": "STANDARD_IA"}
        ],
        "noncurrent_version_transitions": [
          {"noncurrent_days": 30, "storage_class": "STANDARD_IA"}
        ],
        "filter_prefix": "logs/"
      }
    ]
  EOT
  type        = string
  default     = null
}

# --- Locals ---
locals {
  default_tags = merge(
    {
      Environment     = var.environment
      ServiceProvider = "Rackspace"
    },
    var.extra_tags
  )

  # Parsed JSON inputs
  grants             = var.grants_json != null ? jsondecode(var.grants_json) : null
  website_config     = var.website_config_json != null ? jsondecode(var.website_config_json) : null
  intelligent_tier   = var.intelligent_tiering_json != null ? jsondecode(var.intelligent_tiering_json) : null
  metrics_configs    = var.metrics_json != null ? jsondecode(var.metrics_json) : null
  cors_rules         = var.cors_rules_json != null ? jsondecode(var.cors_rules_json) : null
  lifecycle_rules    = var.lifecycle_rules_json != null ? jsondecode(var.lifecycle_rules_json) : null

  # SSE condition
  enable_sse         = var.sse_algorithm != "none"
  use_kms            = var.sse_algorithm == "aws:kms"
}

# --- Data Sources ---
data "aws_canonical_user_id" "current" {}

# --- S3 Bucket ---
resource "aws_s3_bucket" "this" {
  bucket              = var.bucket_name
  tags                = local.default_tags
  object_lock_enabled = var.object_lock_enabled
}

# --- Server-Side Encryption ---
resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count  = local.enable_sse ? 1 : 0
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.sse_algorithm
      kms_master_key_id = local.use_kms ? var.kms_key_id : null
    }
    bucket_key_enabled = local.use_kms ? var.bucket_key_enabled : null
  }
}

# --- Public Access Block ---
resource "aws_s3_bucket_public_access_block" "this" {
  count  = var.block_public_access ? 1 : 0
  bucket = aws_s3_bucket.this.id

  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

# --- Bucket Ownership Controls ---
resource "aws_s3_bucket_ownership_controls" "this" {
  count  = (var.control_object_ownership || var.canned_acl != null || local.grants != null) ? 1 : 0
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = var.object_ownership
  }
}

# --- Bucket ACL ---
resource "aws_s3_bucket_acl" "this" {
  count  = (var.canned_acl != null || local.grants != null) ? 1 : 0
  bucket = aws_s3_bucket.this.id
  depends_on = [aws_s3_bucket_ownership_controls.this]

  dynamic "access_control_policy" {
    for_each = local.grants != null ? [1] : []
    content {
      owner {
        id = data.aws_canonical_user_id.current.id
      }

      dynamic "grant" {
        for_each = local.grants
        content {
          permission = grant.value["permission"]
          grantee {
            type = grant.value["type"]
            id   = try(grant.value["id"], null)
            uri  = try(grant.value["uri"], null)
          }
        }
      }
    }
  }

  acl = local.grants == null && var.canned_acl != null ? var.canned_acl : null
}

# --- Versioning ---
resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status     = var.versioning_enabled ? "Enabled" : "Suspended"
    mfa_delete = var.mfa_delete ? "Enabled" : "Disabled"
  }
}

# --- Bucket Logging ---
resource "aws_s3_bucket_logging" "this" {
  count  = var.bucket_logging ? 1 : 0
  bucket = aws_s3_bucket.this.id

  target_bucket = var.log_bucket
  target_prefix = var.log_prefix
}

# --- Object Lock Configuration ---
resource "aws_s3_bucket_object_lock_configuration" "this" {
  count  = var.object_lock_enabled ? 1 : 0
  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode  = var.object_lock_mode
      days  = var.object_lock_days
    }
  }
}

# --- Static Website Hosting ---
resource "aws_s3_bucket_website_configuration" "this" {
  count  = local.website_config != null ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "index_document" {
    for_each = try(local.website_config["index_document"], null) != null ? [local.website_config["index_document"]] : []
    content {
      suffix = index_document.value["suffix"]
    }
  }

  dynamic "error_document" {
    for_each = try(local.website_config["error_document"], null) != null ? [local.website_config["error_document"]] : []
    content {
      key = error_document.value["key"]
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = try(local.website_config["redirect_all_requests_to"], null) != null ? [local.website_config["redirect_all_requests_to"]] : []
    content {
      host_name = redirect_all_requests_to.value["host_name"]
      protocol  = try(redirect_all_requests_to.value["protocol"], null)
    }
  }

  dynamic "routing_rule" {
    for_each = try(local.website_config["routing_rules"], [])
    content {
      dynamic "condition" {
        for_each = try(routing_rule.value["condition"], null) != null ? [routing_rule.value["condition"]] : []
        content {
          http_error_code_returned_equals = try(condition.value["http_error_code_returned_equals"], null)
          key_prefix_equals               = try(condition.value["key_prefix_equals"], null)
        }
      }
      dynamic "redirect" {
        for_each = try(routing_rule.value["redirect"], null) != null ? [routing_rule.value["redirect"]] : []
        content {
          host_name               = try(redirect.value["host_name"], null)
          http_redirect_code      = try(redirect.value["http_redirect_code"], null)
          protocol                = try(redirect.value["protocol"], null)
          replace_key_prefix_with = try(redirect.value["replace_key_prefix_with"], null)
          replace_key_with        = try(redirect.value["replace_key_with"], null)
        }
      }
    }
  }
}

# --- Intelligent Tiering ---
resource "aws_s3_bucket_intelligent_tiering_configuration" "this" {
  count  = local.intelligent_tier != null ? 1 : 0
  bucket = aws_s3_bucket.this.id
  name   = local.intelligent_tier["name"]

  dynamic "tiering" {
    for_each = try(local.intelligent_tier["tierings"], [])
    content {
      access_tier = tiering.value["access_tier"]
      days        = tiering.value["days"]
    }
  }

  dynamic "filter" {
    for_each = try(local.intelligent_tier["filter"], null) != null ? [local.intelligent_tier["filter"]] : []
    content {
      prefix = try(filter.value["prefix"], null)
    }
  }
}

# --- CloudWatch Metrics ---
resource "aws_s3_bucket_metric" "this" {
  for_each = local.metrics_configs != null ? { for m in local.metrics_configs : m["name"] => m } : {}
  bucket   = aws_s3_bucket.this.id
  name     = each.value["name"]

  dynamic "filter" {
    for_each = try(each.value["filter"], null) != null ? [each.value["filter"]] : []
    content {
      prefix = try(filter.value["prefix"], null)
    }
  }
}

# --- CORS ---
resource "aws_s3_bucket_cors_configuration" "this" {
  count  = local.cors_rules != null ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = local.cors_rules
    content {
      allowed_headers = try(cors_rule.value["allowed_headers"], null)
      allowed_methods = cors_rule.value["allowed_methods"]
      allowed_origins = cors_rule.value["allowed_origins"]
      expose_headers  = try(cors_rule.value["expose_headers"], null)
      max_age_seconds = try(cors_rule.value["max_age_seconds"], null)
    }
  }
}

# --- Lifecycle Configuration ---
resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count  = local.lifecycle_rules != null ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = local.lifecycle_rules
    content {
      id     = try(rule.value["id"], "rule-${rule.key}")
      status = try(rule.value["status"], "Enabled")

      dynamic "abort_incomplete_multipart_upload" {
        for_each = try(rule.value["abort_incomplete_multipart_upload_days"], null) != null ? [1] : []
        content {
          days_after_initiation = rule.value["abort_incomplete_multipart_upload_days"]
        }
      }

      dynamic "expiration" {
        for_each = try(rule.value["expiration_days"], null) != null || try(rule.value["expiration_date"], null) != null ? [1] : []
        content {
          days                         = try(rule.value["expiration_days"], null)
          date                         = try(rule.value["expiration_date"], null)
          expired_object_delete_marker = try(rule.value["expired_object_delete_marker"], null)
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = try(rule.value["noncurrent_version_expiration_days"], null) != null ? [1] : []
        content {
          noncurrent_days = rule.value["noncurrent_version_expiration_days"]
        }
      }

      dynamic "transition" {
        for_each = try(rule.value["transitions"], [])
        content {
          days          = try(transition.value["days"], null)
          date          = try(transition.value["date"], null)
          storage_class = transition.value["storage_class"]
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = try(rule.value["noncurrent_version_transitions"], [])
        content {
          noncurrent_days = try(noncurrent_version_transition.value["noncurrent_days"], null)
          storage_class   = noncurrent_version_transition.value["storage_class"]
          newer_noncurrent_versions = try(noncurrent_version_transition.value["newer_noncurrent_versions"], null)
        }
      }

      dynamic "filter" {
        for_each = [1]
        content {
          prefix = try(rule.value["filter_prefix"], null)
        }
      }
    }
  }
}

# Enterprise S3 Bucket Configuration
# ====================================

# ---------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------

variable "bucket_name" {
  type        = string
  default     = null
  description = "Name of the S3 bucket. Must be globally unique and 1-63 characters."
  validation {
    condition = var.bucket_name == null || (
      length(var.bucket_name) >= 1 && length(var.bucket_name) <= 63
    )
    error_message = "Bucket name must be null or between 1 and 63 characters."
  }
}

variable "bucket_name_prefix" {
  type        = string
  default     = null
  description = "Prefix for an auto-generated bucket name. Must be 1-37 characters."
  validation {
    condition = var.bucket_name_prefix == null || (
      length(var.bucket_name_prefix) >= 1 && length(var.bucket_name_prefix) <= 37
    )
    error_message = "Bucket name prefix must be null or between 1 and 37 characters."
  }
}

variable "force_destroy" {
  type        = bool
  default     = false
  description = "Allow the bucket to be destroyed even if it contains objects."
}

variable "object_ownership" {
  type        = string
  default     = "BucketOwnerEnforced"
  description = "Object ownership setting. Use 'BucketOwnerEnforced' to disable ACLs, 'ObjectWriter' to enable them."
  validation {
    condition     = contains(["BucketOwnerEnforced", "ObjectWriter", "BucketOwnerPreferred"], var.object_ownership)
    error_message = "Object ownership must be one of: BucketOwnerEnforced, ObjectWriter, BucketOwnerPreferred."
  }
}

variable "block_public_acls" {
  type        = bool
  default     = true
  description = "Block public ACLs on the bucket."
}

variable "block_public_policy" {
  type        = bool
  default     = true
  description = "Block public bucket policies."
}

variable "ignore_public_acls" {
  type        = bool
  default     = true
  description = "Ignore public ACLs on the bucket."
}

variable "restrict_public_buckets" {
  type        = bool
  default     = true
  description = "Restrict public bucket access."
}

variable "sse_algorithm" {
  type        = string
  default     = "AES256"
  description = "Server-side encryption algorithm. Use 'AES256' for S3-managed keys or 'aws:kms' for KMS."
  validation {
    condition     = contains(["AES256", "aws:kms"], var.sse_algorithm)
    error_message = "SSE algorithm must be either 'AES256' or 'aws:kms'."
  }
}

variable "kms_key_arn" {
  type        = string
  default     = null
  description = "ARN of the KMS key for SSE-KMS encryption. If set, sse_algorithm is forced to 'aws:kms' and bucket key is enabled."
}

variable "versioning_enabled" {
  type        = bool
  default     = false
  description = "Enable bucket versioning. Automatically enabled when object lock is configured."
}

variable "tags" {
  type        = map(string)
  default     = {}
  description = "Tags to apply to the S3 bucket."
}

variable "custom_bucket_policy" {
  type        = string
  default     = null
  description = "Custom JSON bucket policy to merge with the enforced SSL-only and logging policies."
}

variable "logging_source_bucket_arns" {
  type        = list(string)
  default     = []
  description = "ARNs of source buckets that will deliver server access logs to this bucket."
}

variable "enable_eventbridge" {
  type        = bool
  default     = false
  description = "Enable Amazon EventBridge notifications for the bucket."
}

variable "logging" {
  type = object({
    target_bucket = string
    target_prefix = optional(string, "log/")
  })
  default     = null
  description = "Server access logging destination configuration."
}

variable "object_lock" {
  type = object({
    mode  = string
    days  = optional(number)
    years = optional(number)
  })
  default     = null
  description = "Object lock retention configuration. Specify either days or years, not both."
  validation {
    condition = var.object_lock == null || (
      (var.object_lock.mode == "GOVERNANCE" || var.object_lock.mode == "COMPLIANCE")
    )
    error_message = "Object lock mode must be 'GOVERNANCE' or 'COMPLIANCE'."
  }
}

variable "replication_rules" {
  type = list(object({
    id       = string
    priority = number
    status   = optional(string, "Enabled")
    filter = optional(object({
      prefix = optional(string)
      tags   = optional(map(string))
    }))
    destination = object({
      bucket_arn         = string
      storage_class      = optional(string)
      replica_kms_key_id = optional(string)
    })
    delete_marker_replication = optional(bool, false)
    sse_kms_encrypted_objects = optional(bool, false)
  }))
  default     = []
  description = "Cross-region replication rule configurations."
}

variable "inventory_configurations" {
  type = list(object({
    name     = string
    enabled  = optional(bool, true)
    schedule = string
    destination = object({
      bucket_arn = string
      prefix     = optional(string)
      format     = string
      encryption = optional(object({
        sse_s3         = optional(bool, false)
        sse_kms_key_id = optional(string)
      }))
    })
    optional_fields          = optional(list(string))
    included_object_versions = optional(string, "All")
  }))
  default     = []
  description = "Inventory configuration settings."
}

variable "cors_rules" {
  type = list(object({
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default     = []
  description = "CORS rules for the bucket."
}

variable "lifecycle_rules" {
  type = list(object({
    id     = string
    status = optional(string, "Enabled")
    filter = optional(object({
      prefix = optional(string)
      tags   = optional(map(string))
    }))
    expiration = optional(object({
      days                         = optional(number)
      date                         = optional(string)
      expired_object_delete_marker = optional(bool)
    }))
    transitions = optional(list(object({
      days          = optional(number)
      date          = optional(string)
      storage_class = string
    })))
    noncurrent_version_expiration = optional(object({
      noncurrent_days = number
    }))
    noncurrent_version_transitions = optional(list(object({
      noncurrent_days = number
      storage_class   = string
    })))
    abort_incomplete_multipart_upload = optional(object({
      days_after_initiation = number
    }))
  }))
  default     = []
  description = "Lifecycle management rules."
}

# ---------------------------------------------------------------------------
# LOCALS
# ---------------------------------------------------------------------------

locals {
  # Bucket naming: use explicit name or prefix, never both
  bucket_name        = var.bucket_name
  bucket_name_prefix = var.bucket_name != null ? null : var.bucket_name_prefix

  # Feature flags
  has_logging        = var.logging != null
  has_object_lock    = var.object_lock != null
  has_logging_source = length(var.logging_source_bucket_arns) > 0

  # Versioning must be enabled when object lock is configured
  versioning_enabled = var.versioning_enabled || local.has_object_lock

  # Effective SSE algorithm
  sse_algorithm = var.kms_key_arn != null ? "aws:kms" : var.sse_algorithm
}

# ---------------------------------------------------------------------------
# DATA SOURCES
# ---------------------------------------------------------------------------

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

# ---------------------------------------------------------------------------
# MAIN S3 BUCKET
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "this" {
  bucket              = local.bucket_name
  bucket_prefix       = local.bucket_name_prefix
  force_destroy       = var.force_destroy
  object_lock_enabled = local.has_object_lock
  tags                = var.tags

  lifecycle {
    precondition {
      condition     = !(var.bucket_name != null && var.bucket_name_prefix != null)
      error_message = "Cannot specify both bucket_name and bucket_name_prefix."
    }
    precondition {
      condition     = !(local.has_logging && local.has_object_lock)
      error_message = "Server access logging and object lock cannot be enabled simultaneously."
    }
    precondition {
      condition     = !(local.has_object_lock && local.has_logging_source)
      error_message = "Object lock cannot be enabled on a bucket configured as a logging source."
    }
  }
}

# ---------------------------------------------------------------------------
# OBJECT OWNERSHIP & ACLs
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = var.object_ownership
  }
}

# Canned ACLs only when ownership is set to ObjectWriter
resource "aws_s3_bucket_acl" "this" {
  count  = var.object_ownership == "ObjectWriter" ? 1 : 0
  bucket = aws_s3_bucket.this.id
  acl    = "private"

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

# ---------------------------------------------------------------------------
# PUBLIC ACCESS BLOCK
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

# ---------------------------------------------------------------------------
# SERVER-SIDE ENCRYPTION
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = local.sse_algorithm
      kms_master_key_id = var.kms_key_arn
    }
    bucket_key_enabled = var.kms_key_arn != null ? true : null
  }
}

# ---------------------------------------------------------------------------
# VERSIONING
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = local.versioning_enabled ? "Enabled" : "Suspended"
  }
}

# ---------------------------------------------------------------------------
# BUCKET POLICY (SSL enforce + custom + logging)
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "ssl_deny" {
  statement {
    sid     = "DenyInsecureConnections"
    effect  = "Deny"
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.this.arn,
      "${aws_s3_bucket.this.arn}/*",
    ]
    principals {
      type        = "*"
      identifiers = ["*"]
    }
    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

data "aws_iam_policy_document" "logging_permissions" {
  count = local.has_logging_source ? 1 : 0

  statement {
    sid       = "S3ServerAccessLogsPolicy"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.this.arn}/*"]
    principals {
      type        = "Service"
      identifiers = ["logging.s3.amazonaws.com"]
    }
    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = var.logging_source_bucket_arns
    }
  }
}

data "aws_iam_policy_document" "combined_policy" {
  source_policy_documents = concat(
    var.custom_bucket_policy != null ? [var.custom_bucket_policy] : [],
    [data.aws_iam_policy_document.ssl_deny.json],
    local.has_logging_source ? [data.aws_iam_policy_document.logging_permissions[0].json] : [],
  )
}

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = data.aws_iam_policy_document.combined_policy.json
}

# ---------------------------------------------------------------------------
# EVENTBRIDGE NOTIFICATIONS
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_notification" "this" {
  count  = var.enable_eventbridge ? 1 : 0
  bucket = aws_s3_bucket.this.id

  eventbridge = true
}

# ---------------------------------------------------------------------------
# SERVER ACCESS LOGGING
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_logging" "this" {
  count  = local.has_logging ? 1 : 0
  bucket = aws_s3_bucket.this.id

  target_bucket = var.logging.target_bucket
  target_prefix = var.logging.target_prefix
}

# ---------------------------------------------------------------------------
# OBJECT LOCK CONFIGURATION
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count  = local.has_object_lock ? 1 : 0
  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode  = var.object_lock.mode
      days  = var.object_lock.days
      years = var.object_lock.years
    }
  }
}

# ---------------------------------------------------------------------------
# REPLICATION
# ---------------------------------------------------------------------------

resource "aws_iam_role" "replication" {
  count = length(var.replication_rules) > 0 ? 1 : 0
  name  = "s3-replication-${aws_s3_bucket.this.id}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
      }
    ]
  })

  tags = var.tags
}

data "aws_iam_policy_document" "replication" {
  count = length(var.replication_rules) > 0 ? 1 : 0

  statement {
    sid    = "ListAndGetSource"
    effect = "Allow"
    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket",
    ]
    resources = [aws_s3_bucket.this.arn]
  }

  statement {
    sid    = "GetObjectVersionsForReplication"
    effect = "Allow"
    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
    ]
    resources = ["${aws_s3_bucket.this.arn}/*"]
  }

  dynamic "statement" {
    for_each = length(var.replication_rules) > 0 ? [1] : []
    content {
      sid    = "ReplicateToDestinations"
      effect = "Allow"
      actions = [
        "s3:ReplicateObject",
        "s3:ReplicateDelete",
        "s3:ReplicateTags",
      ]
      resources = [
        for rule in var.replication_rules : "${rule.destination.bucket_arn}/*"
      ]
    }
  }
}

resource "aws_iam_policy" "replication" {
  count  = length(var.replication_rules) > 0 ? 1 : 0
  name   = "s3-replication-policy-${aws_s3_bucket.this.id}"
  policy = data.aws_iam_policy_document.replication[0].json

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "replication" {
  count      = length(var.replication_rules) > 0 ? 1 : 0
  role       = aws_iam_role.replication[0].name
  policy_arn = aws_iam_policy.replication[0].arn
}

resource "aws_s3_bucket_replication_configuration" "this" {
  count  = length(var.replication_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id
  role   = aws_iam_role.replication[0].arn

  dynamic "rule" {
    for_each = var.replication_rules
    content {
      id       = rule.value.id
      priority = rule.value.priority
      status   = rule.value.status

      dynamic "filter" {
        for_each = rule.value.filter != null ? [rule.value.filter] : []
        content {
          prefix = filter.value.prefix
          dynamic "tag" {
            for_each = filter.value.tags != null ? {
              for k, v in filter.value.tags : k => v
            } : {}
            content {
              key   = tag.key
              value = tag.value
            }
          }
        }
      }

      destination {
        bucket        = rule.value.destination.bucket_arn
        storage_class = rule.value.destination.storage_class
        dynamic "encryption_configuration" {
          for_each = rule.value.destination.replica_kms_key_id != null ? [1] : []
          content {
            replica_kms_key_id = rule.value.destination.replica_kms_key_id
          }
        }
      }

      delete_marker_replication {
        status = rule.value.delete_marker_replication ? "Enabled" : "Disabled"
      }

      source_selection_criteria {
        sse_kms_encrypted_objects {
          status = rule.value.sse_kms_encrypted_objects ? "Enabled" : "Disabled"
        }
      }
    }
  }
}

# ---------------------------------------------------------------------------
# INVENTORY CONFIGURATIONS
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_inventory" "this" {
  for_each = {
    for idx, inv in var.inventory_configurations : inv.name => inv
  }

  bucket  = aws_s3_bucket.this.id
  name    = each.value.name
  enabled = each.value.enabled

  schedule {
    frequency = each.value.schedule
  }

  destination {
    bucket {
      format     = each.value.destination.format
      bucket_arn = each.value.destination.bucket_arn
      prefix     = each.value.destination.prefix

      dynamic "encryption" {
        for_each = each.value.destination.encryption != null ? [each.value.destination.encryption] : []
        content {
          dynamic "sse_s3" {
            for_each = encryption.value.sse_s3 ? [1] : []
            content {}
          }
          dynamic "sse_kms" {
            for_each = encryption.value.sse_kms_key_id != null ? [encryption.value.sse_kms_key_id] : []
            content {
              key_id = sse_kms.value
            }
          }
        }
      }
    }
  }

  included_object_versions = each.value.included_object_versions
  optional_fields          = each.value.optional_fields
}

# ---------------------------------------------------------------------------
# CORS CONFIGURATION
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_cors_configuration" "this" {
  count  = length(var.cors_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

# ---------------------------------------------------------------------------
# LIFECYCLE CONFIGURATION
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count  = length(var.lifecycle_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = rule.value.status

      dynamic "filter" {
        for_each = rule.value.filter != null ? [rule.value.filter] : []
        content {
          prefix = filter.value.prefix
          dynamic "tag" {
            for_each = filter.value.tags != null ? {
              for k, v in filter.value.tags : k => v
            } : {}
            content {
              key   = tag.key
              value = tag.value
            }
          }
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration != null ? [rule.value.expiration] : []
        content {
          days                         = expiration.value.days
          date                         = expiration.value.date
          expired_object_delete_marker = expiration.value.expired_object_delete_marker
        }
      }

      dynamic "transition" {
        for_each = rule.value.transitions != null ? rule.value.transitions : []
        content {
          days          = transition.value.days
          date          = transition.value.date
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration != null ? [rule.value.noncurrent_version_expiration] : []
        content {
          noncurrent_days = noncurrent_version_expiration.value.noncurrent_days
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transitions != null ? rule.value.noncurrent_version_transitions : []
        content {
          noncurrent_days = noncurrent_version_transition.value.noncurrent_days
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload != null ? [rule.value.abort_incomplete_multipart_upload] : []
        content {
          days_after_initiation = abort_incomplete_multipart_upload.value.days_after_initiation
        }
      }
    }
  }
}

# ---------------------------------------------------------------------------
# OUTPUTS
# ---------------------------------------------------------------------------

output "bucket_id" {
  description = "The name of the S3 bucket."
  value       = aws_s3_bucket.this.id
}

output "bucket_arn" {
  description = "The ARN of the S3 bucket."
  value       = aws_s3_bucket.this.arn
}

output "bucket_domain_name" {
  description = "The bucket domain name."
  value       = aws_s3_bucket.this.bucket_domain_name
}

output "bucket_regional_domain_name" {
  description = "The bucket regional domain name."
  value       = aws_s3_bucket.this.bucket_regional_domain_name
}

output "bucket_hosted_zone_id" {
  description = "The Route 53 hosted zone ID for this bucket's region."
  value       = aws_s3_bucket.this.hosted_zone_id
}

variable "group_name_prefix" {
  description = "Prefix for IAM group names"
  type        = string
  default     = "app"
}

variable "designated_s3_region" {
  description = "The only AWS region where s3:CreateBucket is allowed"
  type        = string
  default     = "us-east-1"
}

variable "remote_state_bucket_name" {
  description = "Name of the remote state S3 bucket to deny access to"
  type        = string
  default     = "my-remote-state-bucket"
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

# ---------------------------------------------------------------------------
# Account-wide IAM password policy
# ---------------------------------------------------------------------------
resource "aws_iam_account_password_policy" "this" {
  minimum_password_length        = 12
  require_uppercase_characters   = true
  require_lowercase_characters   = true
  require_numbers                = true
  require_symbols                = true
  allow_users_to_change_password = true
  max_password_age               = 90
  password_reuse_prevention      = 24
  hard_expiry                    = false
}

# ---------------------------------------------------------------------------
# Account-level S3 public access block
# ---------------------------------------------------------------------------
resource "aws_s3_account_public_access_block" "this" {
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ---------------------------------------------------------------------------
# IAM Groups
# ---------------------------------------------------------------------------
resource "aws_iam_group" "developer" {
  name = "${var.group_name_prefix}_developer"
  path = "/"
}

resource "aws_iam_group" "admin" {
  name = "${var.group_name_prefix}_admin"
  path = "/"
}

# ---------------------------------------------------------------------------
# Developer group – AWS-managed policy attachments
# ---------------------------------------------------------------------------
data "aws_iam_policy" "iam_read_only" {
  arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/IAMReadOnlyAccess"
}

data "aws_iam_policy" "iam_user_change_password" {
  arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/IAMUserChangePassword"
}

data "aws_iam_policy" "iam_user_ssh_keys" {
  arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/IAMUserSSHKeys"
}

resource "aws_iam_group_policy_attachment" "developer_iam_read_only" {
  group      = aws_iam_group.developer.name
  policy_arn = data.aws_iam_policy.iam_read_only.arn
}

resource "aws_iam_group_policy_attachment" "developer_iam_user_change_password" {
  group      = aws_iam_group.developer.name
  policy_arn = data.aws_iam_policy.iam_user_change_password.arn
}

resource "aws_iam_group_policy_attachment" "developer_iam_user_ssh_keys" {
  group      = aws_iam_group.developer.name
  policy_arn = data.aws_iam_policy.iam_user_ssh_keys.arn
}

# ---------------------------------------------------------------------------
# Developer group – Custom policy: manage personal access keys
# ---------------------------------------------------------------------------
resource "aws_iam_policy" "manage_access_keys" {
  name        = "${var.group_name_prefix}_manage_access_keys"
  path        = "/"
  description = "Allow users to manage their own IAM access keys"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ManageOwnAccessKeys"
        Effect = "Allow"
        Action = [
          "iam:CreateAccessKey",
          "iam:DeleteAccessKey",
          "iam:ListAccessKeys",
          "iam:UpdateAccessKey",
          "iam:GetAccessKeyLastUsed"
        ]
        Resource = "arn:${data.aws_partition.current.partition}:iam::*:user/$${aws:username}"
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "developer_manage_access_keys" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.manage_access_keys.arn
}

# ---------------------------------------------------------------------------
# Developer group – Custom policy: virtual MFA devices
# (Requires MFA to deactivate / delete MFA devices)
# ---------------------------------------------------------------------------
resource "aws_iam_policy" "manage_mfa_devices" {
  name        = "${var.group_name_prefix}_manage_mfa_devices"
  path        = "/"
  description = "Allow users to manage their own virtual MFA devices; MFA required to deactivate"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ManageMFADevicesNoMFA"
        Effect = "Allow"
        Action = [
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:ListVirtualMFADevices",
          "iam:ListMFADevices",
          "iam:ResyncMFADevice"
        ]
        Resource = "*"
      },
      {
        Sid    = "DeactivateMFADeviceRequiresMFA"
        Effect = "Allow"
        Action = [
          "iam:DeactivateMFADevice"
        ]
        Resource = "arn:${data.aws_partition.current.partition}:iam::*:user/$${aws:username}"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid    = "DeleteVirtualMFADeviceRequiresMFA"
        Effect = "Allow"
        Action = [
          "iam:DeleteVirtualMFADevice"
        ]
        Resource = "arn:${data.aws_partition.current.partition}:iam::*:mfa/$${aws:username}"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "developer_manage_mfa_devices" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.manage_mfa_devices.arn
}

# ---------------------------------------------------------------------------
# Developer group – Custom policy: MFA-gated S3 access
# Denies CreateBucket outside designated region, denies access to remote-state bucket
# ---------------------------------------------------------------------------
resource "aws_iam_policy" "mfa_gated_s3" {
  name        = "${var.group_name_prefix}_mfa_gated_s3"
  path        = "/"
  description = "MFA-gated S3 access with restrictions on CreateBucket region and remote-state bucket"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3WithMFA"
        Effect = "Allow"
        Action = "s3:*"
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid    = "DenyCreateBucketOutsideDesignatedRegion"
        Effect = "Deny"
        Action = "s3:CreateBucket"
        Resource = "*"
        Condition = {
          StringNotEquals = {
            "aws:RequestedRegion" = var.designated_s3_region
          }
        }
      },
      {
        Sid    = "DenyRemoteStateBucketAccess"
        Effect = "Deny"
        Action = "s3:*"
        Resource = [
          "arn:${data.aws_partition.current.partition}:s3:::${var.remote_state_bucket_name}",
          "arn:${data.aws_partition.current.partition}:s3:::${var.remote_state_bucket_name}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "developer_mfa_gated_s3" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.mfa_gated_s3.arn
}

# ---------------------------------------------------------------------------
# Developer group – Custom policy: MFA-gated EC2 / ELB / CloudWatch /
# AutoScaling, and service-linked role pass-role
# ---------------------------------------------------------------------------
resource "aws_iam_policy" "mfa_gated_ec2_elb" {
  name        = "${var.group_name_prefix}_mfa_gated_ec2_elb"
  path        = "/"
  description = "MFA-gated access for EC2, ELB, CloudWatch, AutoScaling and service-linked roles"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "MfaGatedEc2ElbCloudWatchAutoScaling"
        Effect = "Allow"
        Action = [
          "ec2:*",
          "elasticloadbalancing:*",
          "cloudwatch:*",
          "autoscaling:*"
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid    = "PassRoleEC2AutoScalingServiceLinked"
        Effect = "Allow"
        Action = "iam:PassRole"
        Resource = [
          "arn:${data.aws_partition.current.partition}:iam::*:role/aws-service-role/autoscaling.amazonaws.com/AWSServiceRoleForAutoScaling",
          "arn:${data.aws_partition.current.partition}:iam::*:role/aws-service-role/ec2.amazonaws.com/AWSServiceRoleForEC2*"
        ]
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "developer_mfa_gated_ec2_elb" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.mfa_gated_ec2_elb.arn
}

# ---------------------------------------------------------------------------
# Admin IAM role (assumable by account root principal)
# ---------------------------------------------------------------------------
resource "aws_iam_role" "admin" {
  name        = "admin"
  description = "Admin role with MFA-gated full administrative access, assumable by account root principal"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "RootPrincipalAssumeRole"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Policy attached to the role – full admin, conditioned on active MFA
resource "aws_iam_policy" "admin_role_policy" {
  name        = "${var.group_name_prefix}_admin_role"
  path        = "/"
  description = "Full administrative access conditioned on active MFA"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "FullAdminWithMFA"
        Effect = "Allow"
        Action = "*"
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "admin_role_policy_attach" {
  role       = aws_iam_role.admin.name
  policy_arn = aws_iam_policy.admin_role_policy.arn
}

# ---------------------------------------------------------------------------
# Admin group – policy to allow assuming the admin role (requires MFA)
# ---------------------------------------------------------------------------
resource "aws_iam_policy" "admin_group_assume_role" {
  name        = "${var.group_name_prefix}_assume_admin_role"
  path        = "/"
  description = "Allow admin group members to assume the admin role when MFA is present"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AssumeAdminRoleWithMFA"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Resource = aws_iam_role.admin.arn
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "admin_group_assume_role_attach" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.admin_group_assume_role.arn
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------

variable "vpc_cidr" {
  description = "CIDR block for the primary VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_definitions" {
  description = <<-EOT
    List of 16 subnet definitions spanning CIDR blocks from 10.0.0.0/24
    through 10.0.15.0/24 across three availability zones. Each entry contains
    a CIDR block, target availability zone, and a name tag (subnet-0 through
    subnet-15).
  EOT
  type = list(object({
    cidr_block        = string
    availability_zone = string
    name              = string
  }))
  default = [
    { cidr_block = "10.0.0.0/24",  availability_zone = "us-east-1a", name = "subnet-0" },
    { cidr_block = "10.0.1.0/24",  availability_zone = "us-east-1b", name = "subnet-1" },
    { cidr_block = "10.0.2.0/24",  availability_zone = "us-east-1c", name = "subnet-2" },
    { cidr_block = "10.0.3.0/24",  availability_zone = "us-east-1a", name = "subnet-3" },
    { cidr_block = "10.0.4.0/24",  availability_zone = "us-east-1b", name = "subnet-4" },
    { cidr_block = "10.0.5.0/24",  availability_zone = "us-east-1c", name = "subnet-5" },
    { cidr_block = "10.0.6.0/24",  availability_zone = "us-east-1a", name = "subnet-6" },
    { cidr_block = "10.0.7.0/24",  availability_zone = "us-east-1b", name = "subnet-7" },
    { cidr_block = "10.0.8.0/24",  availability_zone = "us-east-1c", name = "subnet-8" },
    { cidr_block = "10.0.9.0/24",  availability_zone = "us-east-1a", name = "subnet-9" },
    { cidr_block = "10.0.10.0/24", availability_zone = "us-east-1b", name = "subnet-10" },
    { cidr_block = "10.0.11.0/24", availability_zone = "us-east-1c", name = "subnet-11" },
    { cidr_block = "10.0.12.0/24", availability_zone = "us-east-1a", name = "subnet-12" },
    { cidr_block = "10.0.13.0/24", availability_zone = "us-east-1b", name = "subnet-13" },
    { cidr_block = "10.0.14.0/24", availability_zone = "us-east-1c", name = "subnet-14" },
    { cidr_block = "10.0.15.0/24", availability_zone = "us-east-1a", name = "subnet-15" },
  ]
}

# ------------------------------------------------------------------------------
# Locals – classify each subnet into a tier by its list position
# ------------------------------------------------------------------------------

locals {
  # Build a map keyed by subnet name with tier classification
  subnet_map = {
    for idx, s in var.subnet_definitions : s.name => {
      cidr_block        = s.cidr_block
      availability_zone = s.availability_zone
      tier = (
        idx < 4  ? "private1" :
        idx < 8  ? "private2" :
        idx < 12 ? "public" :
        "spare"
      )
    }
  }
}

# ------------------------------------------------------------------------------
# VPC
# ------------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr
  instance_tenancy                 = "default"
  assign_generated_ipv6_cidr_block = true
  tags = {
    Name = "my-deploy-me-vpc"
  }
}

# ------------------------------------------------------------------------------
# Subnets (16 total)
# ------------------------------------------------------------------------------

resource "aws_subnet" "this" {
  for_each = local.subnet_map

  vpc_id                  = aws_vpc.main.id
  cidr_block              = each.value.cidr_block
  availability_zone       = each.value.availability_zone
  map_public_ip_on_launch = false

  tags = {
    Name = each.key
  }
}

# ------------------------------------------------------------------------------
# Internet Gateway
# ------------------------------------------------------------------------------

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "igw-deploy-me"
  }
}

# ------------------------------------------------------------------------------
# Elastic IP (for NAT Gateway)
# ------------------------------------------------------------------------------

resource "aws_eip" "nat" {
  domain = "vpc"
  tags = {
    Name = "eip-deploy-me-nat"
  }
}

# ------------------------------------------------------------------------------
# NAT Gateway – deployed in the first private subnet (subnet-0)
# ------------------------------------------------------------------------------

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.this["subnet-0"].id
  depends_on    = [aws_internet_gateway.main]
  tags = {
    Name = "deployme-natgw"
  }
}

# ------------------------------------------------------------------------------
# Private Route Table (also the VPC main route table)
# ------------------------------------------------------------------------------

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "rt-private-deploy-me"
  }
}

resource "aws_route" "private_nat" {
  route_table_id         = aws_route_table.private.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main.id
}

# Set the private route table as the VPC's main route table
resource "aws_main_route_table_association" "private" {
  vpc_id         = aws_vpc.main.id
  route_table_id = aws_route_table.private.id
}

# Explicitly associate all 8 private subnets with the private route table
resource "aws_route_table_association" "private" {
  for_each = {
    for name, attrs in local.subnet_map : name => name
    if attrs.tier == "private1" || attrs.tier == "private2"
  }

  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.private.id
}

# ------------------------------------------------------------------------------
# Public Route Table
# ------------------------------------------------------------------------------

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "rt-public-deploy-me"
  }
}

resource "aws_route" "public_ipv4" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route" "public_ipv6" {
  route_table_id              = aws_route_table.public.id
  destination_ipv6_cidr_block = "::/0"
  gateway_id                  = aws_internet_gateway.main.id
}

# Associate all 4 public subnets with the public route table
resource "aws_route_table_association" "public" {
  for_each = {
    for name, attrs in local.subnet_map : name => name
    if attrs.tier == "public"
  }

  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.public.id
}

# ------------------------------------------------------------------------------
# Spare Route Table
# ------------------------------------------------------------------------------

resource "aws_route_table" "spare" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "rt-spare-deploy-me"
  }
}

resource "aws_route" "spare_ipv4" {
  route_table_id         = aws_route_table.spare.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route" "spare_ipv6" {
  route_table_id              = aws_route_table.spare.id
  destination_ipv6_cidr_block = "::/0"
  gateway_id                  = aws_internet_gateway.main.id
}

# Associate all 4 spare subnets with the spare route table
resource "aws_route_table_association" "spare" {
  for_each = {
    for name, attrs in local.subnet_map : name => name
    if attrs.tier == "spare"
  }

  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.spare.id
}

# ------------------------------------------------------------------------------
# Security Group – allow_web_traffic
# ------------------------------------------------------------------------------

resource "aws_security_group" "allow_web_traffic" {
  name        = "allow_web_traffic"
  description = "Permits inbound HTTP/HTTPS from anywhere and SSH from within the VPC"
  vpc_id      = aws_vpc.main.id
  tags = {
    Name = "allow_web_traffic"
  }
}

# Inbound: HTTP from anywhere
resource "aws_vpc_security_group_ingress_rule" "http" {
  security_group_id = aws_security_group.allow_web_traffic.id
  cidr_ipv4         = "0.0.0.0/0"
  from_port         = 80
  to_port           = 80
  ip_protocol       = "tcp"
}

# Inbound: HTTPS from anywhere
resource "aws_vpc_security_group_ingress_rule" "https" {
  security_group_id = aws_security_group.allow_web_traffic.id
  cidr_ipv4         = "0.0.0.0/0"
  from_port         = 443
  to_port           = 443
  ip_protocol       = "tcp"
}

# Inbound: SSH from VPC CIDR only
resource "aws_vpc_security_group_ingress_rule" "ssh" {
  security_group_id = aws_security_group.allow_web_traffic.id
  cidr_ipv4         = var.vpc_cidr
  from_port         = 22
  to_port           = 22
  ip_protocol       = "tcp"
}

# Outbound: all traffic to VPC CIDR only
resource "aws_vpc_security_group_egress_rule" "all" {
  security_group_id = aws_security_group.allow_web_traffic.id
  cidr_ipv4         = var.vpc_cidr
  ip_protocol       = "-1"
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------

output "server_public_ip" {
  description = "Public IP address of the NAT Gateway Elastic IP"
  value       = aws_eip.nat.public_ip
}

variable "name" {
  description = "Name component of the label"
  type        = string
  default     = "security-group"
}

variable "environment" {
  description = "Environment component of the label"
  type        = string
  default     = "dev"
}

variable "managedby" {
  description = "Managed by label"
  type        = string
  default     = "opsstation"
}

variable "label_order" {
  description = "Order of label components for the ID"
  type        = list(string)
  default     = ["name", "environment"]
}

variable "repository" {
  description = "Repository URL for the module"
  type        = string
  default     = "https://github.com/opsstation/terraform-aws-security_group"
}

variable "enabled" {
  description = "Set to false to prevent the module from creating any resources"
  type        = bool
  default     = true
}

variable "new_sg" {
  description = "Flag to control whether a new security group is created"
  type        = bool
  default     = true
}

variable "vpc_id" {
  description = "VPC ID where the security group will be created (required when new_sg is true)"
  type        = string
  default     = null
}

variable "prefix_list_enabled" {
  description = "Flag to enable creation of an EC2 managed prefix list"
  type        = bool
  default     = false
}

variable "prefix_list_address_family" {
  description = "Address family for the managed prefix list (IPv4 or IPv6)"
  type        = string
  default     = "IPv4"
}

variable "prefix_list_max_entries" {
  description = "Maximum number of entries for the managed prefix list"
  type        = number
  default     = 5
}

variable "prefix_list_entries" {
  description = "List of entries for the managed prefix list"
  type = list(object({
    cidr        = string
    description = optional(string)
  }))
  default = []
}

variable "existing_sg_id" {
  description = "ID of an existing security group to apply rules to (used when new_sg is false)"
  type        = string
  default     = null
}

variable "ingress_rules" {
  description = "List of ingress security group rules. The type field determines the target type: cidr_blocks, self, source_security_group_id, or prefix_list_id."
  type = list(object({
    description              = optional(string)
    from_port                = number
    to_port                  = number
    protocol                 = string
    type                     = string
    cidr_blocks              = optional(list(string))
    ipv6_cidr_blocks         = optional(list(string))
    source_security_group_id = optional(string)
    prefix_list_id           = optional(string)
  }))
  default = []
}

variable "egress_rules" {
  description = "List of egress security group rules. The type field determines the target type: cidr_blocks, self, source_security_group_id, or prefix_list_id."
  type = list(object({
    description              = optional(string)
    from_port                = number
    to_port                  = number
    protocol                 = string
    type                     = string
    cidr_blocks              = optional(list(string))
    ipv6_cidr_blocks         = optional(list(string))
    source_security_group_id = optional(string)
    prefix_list_id           = optional(string)
  }))
  default = []
}

# ------------------------------------------------------------------------------
# Labels module from remote git source
# ------------------------------------------------------------------------------
module "labels" {
  source      = "git::https://github.com/opsstation/terraform-aws-labels.git?ref=v1.0.0"
  name        = var.name
  environment = var.environment
  managedby   = var.managedby
  label_order = var.label_order
  repository  = var.repository
}

# ------------------------------------------------------------------------------
# Local values
# ------------------------------------------------------------------------------
locals {
  # Determine which security group ID to use
  security_group_id = var.enabled ? (
    var.new_sg ? aws_security_group.this[0].id : var.existing_sg_id
  ) : null

  # Prefix list ID when created by this module
  prefix_list_id = var.enabled && var.prefix_list_enabled && length(var.prefix_list_entries) > 0 ? (
    aws_ec2_managed_prefix_list.this[0].id
  ) : null
}

# ------------------------------------------------------------------------------
# Security Group (created only when new_sg is true)
# ------------------------------------------------------------------------------
resource "aws_security_group" "this" {
  count       = var.enabled && var.new_sg ? 1 : 0
  name        = "${module.labels.id}-sg"
  description = "Security group for ${module.labels.id}"
  vpc_id      = var.vpc_id

  tags = module.labels.tags

  lifecycle {
    create_before_destroy = true
  }
}

# ------------------------------------------------------------------------------
# EC2 Managed Prefix List (created only when prefix_list_enabled and entries exist)
# ------------------------------------------------------------------------------
resource "aws_ec2_managed_prefix_list" "this" {
  count = var.enabled && var.prefix_list_enabled && length(var.prefix_list_entries) > 0 ? 1 : 0

  name           = "${module.labels.id}-prefix-list"
  address_family = var.prefix_list_address_family
  max_entries    = var.prefix_list_max_entries

  dynamic "entry" {
    for_each = var.prefix_list_entries
    content {
      cidr        = entry.value.cidr
      description = try(entry.value.description, null)
    }
  }

  tags = module.labels.tags
}

# ------------------------------------------------------------------------------
# Dynamic Ingress Rules
# ------------------------------------------------------------------------------
resource "aws_security_group_rule" "ingress" {
  for_each = var.enabled ? { for idx, rule in var.ingress_rules : idx => rule } : {}

  security_group_id = local.security_group_id
  type              = "ingress"
  description       = try(each.value.description, null)
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol

  cidr_blocks              = each.value.type == "cidr_blocks" ? try(each.value.cidr_blocks, null) : null
  ipv6_cidr_blocks         = each.value.type == "cidr_blocks" ? try(each.value.ipv6_cidr_blocks, null) : null
  self                     = each.value.type == "self" ? true : null
  source_security_group_id = each.value.type == "source_security_group_id" ? try(each.value.source_security_group_id, null) : null
  prefix_list_ids          = each.value.type == "prefix_list_id" ? (
    try(each.value.prefix_list_id, null) != null ? [each.value.prefix_list_id] : (
      local.prefix_list_id != null ? [local.prefix_list_id] : null
    )
  ) : null
}

# ------------------------------------------------------------------------------
# Dynamic Egress Rules
# ------------------------------------------------------------------------------
resource "aws_security_group_rule" "egress" {
  for_each = var.enabled ? { for idx, rule in var.egress_rules : idx => rule } : {}

  security_group_id = local.security_group_id
  type              = "egress"
  description       = try(each.value.description, null)
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol

  cidr_blocks              = each.value.type == "cidr_blocks" ? try(each.value.cidr_blocks, null) : null
  ipv6_cidr_blocks         = each.value.type == "cidr_blocks" ? try(each.value.ipv6_cidr_blocks, null) : null
  self                     = each.value.type == "self" ? true : null
  source_security_group_id = each.value.type == "source_security_group_id" ? try(each.value.source_security_group_id, null) : null
  prefix_list_ids          = each.value.type == "prefix_list_id" ? (
    try(each.value.prefix_list_id, null) != null ? [each.value.prefix_list_id] : (
      local.prefix_list_id != null ? [local.prefix_list_id] : null
    )
  ) : null
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------
output "security_group_id" {
  description = "The ID of the security group"
  value       = local.security_group_id
}

output "security_group_name" {
  description = "The name of the security group"
  value       = var.new_sg && var.enabled ? aws_security_group.this[0].name : null
}

output "prefix_list_id" {
  description = "The ID of the managed prefix list"
  value       = local.prefix_list_id
}

output "prefix_list_arn" {
  description = "The ARN of the managed prefix list"
  value       = var.enabled && var.prefix_list_enabled && length(var.prefix_list_entries) > 0 ? aws_ec2_managed_prefix_list.this[0].arn : null
}

output "labels_id" {
  description = "The label ID from the labels module"
  value       = module.labels.id
}

output "labels_tags" {
  description = "The tags from the labels module"
  value       = module.labels.tags
}

variable "env_name" {
  description = "Environment name used to construct IAM role names"
  type        = string
  default     = "dev"
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_region" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.region
}

# ------------------------------------------------------------------------------
# IAM Account Password Policy
# ------------------------------------------------------------------------------
resource "aws_iam_account_password_policy" "strict" {
  minimum_password_length        = 14
  require_lowercase_characters   = true
  require_uppercase_characters   = true
  require_numbers                = true
  require_symbols                = false
  allow_users_to_change_password = true
  max_password_age               = 90
  password_reuse_prevention      = 3
}

# ------------------------------------------------------------------------------
# ECS Task Role
# ------------------------------------------------------------------------------
resource "aws_iam_role" "ecs_task_role" {
  name = "ecs-task-role-for-${var.env_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_task_secretsmanager" {
  role       = aws_iam_role.ecs_task_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/SecretsManagerReadWrite"
}

resource "aws_iam_role_policy_attachment" "ecs_task_s3_full" {
  role       = aws_iam_role.ecs_task_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/AmazonS3FullAccess"
}

resource "aws_iam_role_policy" "ecs_task_inline_ssm" {
  name = "ecs-task-ssm-messages"
  role = aws_iam_role.ecs_task_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ssmmessages:CreateControlChannel",
          "ssmmessages:CreateDataChannel",
          "ssmmessages:OpenControlChannel",
          "ssmmessages:OpenDataChannel"
        ]
        Resource = "*"
      }
    ]
  })
}

