resource "aws_iam_role_policy_attachment" "ecs_execution_task_role_policy" {
  role       = aws_iam_role.ecs_execution_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_iam_role_policy_attachment" "ecs_execution_container_role" {
  role       = aws_iam_role.ecs_execution_role.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AmazonEC2ContainerServiceRole"
}

resource "aws_iam_role_policy" "ecs_execution_inline" {
  name = "ecs-execution-secrets-kms"
  role = aws_iam_role.ecs_execution_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue"
        ]
        Resource = [
          "arn:${local.partition}:secretsmanager:${local.region}:${local.account_id}:secret:*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Decrypt"
        ]
        Resource = [
          "arn:${local.partition}:kms:${local.region}:${local.account_id}:key/*"
        ]
      }
    ]
  })
}

