          "secretsmanager:ListSecrets"
        ]
        Resource = [
          "arn:${local.partition}:secretsmanager:${local.region}:${local.account_id}:secret:*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "lambda:InvokeFunction"
        ]
        Resource = [
          "arn:${local.partition}:lambda:${local.region}:${local.account_id}:function:*"
        ]
      }
    ]
  })
}

