# ------------------------------------------------------------------------------
# Developers Policy (limited MFA)
# ------------------------------------------------------------------------------
resource "aws_iam_policy" "developers_policy_limited_mfa" {
  name        = "developers-policy-limited-mfa"
  description = "Developer access policy with MFA enforcement for sensitive services"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3ReadWriteDeleteList"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:ListBucket"
        ]
        Resource = [
          "arn:${local.partition}:s3:::*",
          "arn:${local.partition}:s3:::*/*"
        ]
      },
      {
        Sid    = "SecretsManagerReadOnlyMFA"
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:ListSecrets",
          "secretsmanager:DescribeSecret"
        ]
        Resource = [
          "arn:${local.partition}:secretsmanager:${local.region}:${local.account_id}:secret:*"
        ]
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid    = "CloudWatchReadOnlyMFA"
        Effect = "Allow"
        Action = [
          "cloudwatch:DescribeAlarms",
          "cloudwatch:GetMetricData",
          "cloudwatch:GetMetricStatistics",
          "cloudwatch:ListMetrics",
          "cloudwatch:DescribeAlarmHistory"
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid    = "ECSReadOnlyMFA"
        Effect = "Allow"
        Action = [
          "ecs:ListClusters",
          "ecs:ListServices",
          "ecs:DescribeClusters",
          "ecs:DescribeServices",
          "ecs:ListTasks",
          "ecs:DescribeTasks",
          "ecs:ListContainerInstances",
          "ecs:DescribeContainerInstances"
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid    = "SelfServiceIAM"
        Effect = "Allow"
        Action = [
          "iam:ChangePassword",
          "iam:GetUser",
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:ListVirtualMFADevices",
          "iam:ListMFADevices",
          "iam:ResyncMFADevice",
          "iam:DeactivateMFADevice",
          "iam:DeleteVirtualMFADevice",
          "iam:CreateAccessKey",
          "iam:UpdateAccessKey",
          "iam:DeleteAccessKey",
          "iam:ListAccessKeys",
          "iam:UploadSSHPublicKey",
          "iam:DeleteSSHPublicKey",
          "iam:ListSSHPublicKeys",
          "iam:UpdateSSHPublicKey"
        ]
        Resource = "arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}"
      },
      {
        Sid    = "ExplicitMFAEnforcement"
        Effect = "Deny"
        NotAction = [
          "iam:ChangePassword",
          "iam:GetUser",
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:ListVirtualMFADevices",
          "iam:ListMFADevices",
          "iam:ResyncMFADevice",
          "iam:DeactivateMFADevice",
          "iam:DeleteVirtualMFADevice",
          "iam:CreateAccessKey",
          "iam:UpdateAccessKey",
          "iam:DeleteAccessKey",
          "iam:ListAccessKeys",
          "iam:UploadSSHPublicKey",
          "iam:DeleteSSHPublicKey",
          "iam:ListSSHPublicKeys",
          "iam:UpdateSSHPublicKey",
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:ListBucket"
        ]
        Resource = "*"
        Condition = {
          BoolIfExists = {
            "aws:MultiFactorAuthPresent" = "false"
          }
        }
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# Billing Policy (limited MFA)
# ------------------------------------------------------------------------------
resource "aws_iam_policy" "billing_policy_limited_mfa" {
  name        = "billing-policy-limited-mfa"
  description = "Billing access policy with MFA enforcement"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "BillingAccessMFA"
        Effect = "Allow"
        Action = [
          "aws-portal:ViewBilling",
          "aws-portal:ViewUsage",
          "aws-portal:ViewPaymentMethods",
          "aws-portal:ModifyBilling",
          "aws-portal:ModifyPaymentMethods",
          "budgets:ViewBudget",
          "budgets:DescribeBudgets",
          "budgets:DescribeBudgetActionsForBudget",
          "budgets:DescribeBudgetAction",
          "ce:GetCostAndUsage",
          "ce:GetCostForecast",
          "ce:GetDimensionValues",
          "ce:GetReservationUtilization",
          "ce:GetTags",
          "payments:ListPaymentPreferences",
          "payments:GetPaymentStatus",
          "tax:GetTaxRegistration",
          "tax:ListTaxRegistrations"
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid    = "SelfServiceMFA"
        Effect = "Allow"
        Action = [
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:ListVirtualMFADevices",
          "iam:ListMFADevices",
          "iam:ResyncMFADevice",
          "iam:DeactivateMFADevice",
          "iam:DeleteVirtualMFADevice"
        ]
        Resource = "arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}"
      },
      {
        Sid    = "ExplicitMFAEnforcement"
        Effect = "Deny"
        NotAction = [
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:ListVirtualMFADevices",
          "iam:ListMFADevices",
          "iam:ResyncMFADevice",
          "iam:DeactivateMFADevice",
          "iam:DeleteVirtualMFADevice"
        ]
        Resource = "*"
        Condition = {
          BoolIfExists = {
            "aws:MultiFactorAuthPresent" = "false"
          }
        }
      }
    ]
  })
}

terraform {
  required_providers {
    archive = {
      source = "hashicorp/archive"
    }
    random = {
      source = "hashicorp/random"
    }
  }
}

variable "config" {
  description = "YAML configuration for the CI/CD pipeline orchestration framework"
  type        = string
  default     = <<-EOF
artifact_bucket_prefix: "tf-artifacts"
cache_bucket_prefix: "tf-cache"
default_pipeline_role: true
repositories:
  - name: "demo-repo"
    description: "Demo repository for pipeline source"
build_projects:
  demo-build:
    description: "Demo CodeBuild project"
    environment:
      type: LINUX_CONTAINER
      compute_type: BUILD_GENERAL1_SMALL
      image: aws/codebuild/standard:7.0
    buildspec: |
      version: 0.2
      phases:
        build:
          commands:
            - echo "Build completed for demo"
lambda_functions:
  demo-lambda:
    description: "Demo Lambda function for pipeline deploy"
    handler: index.handler
    runtime: python3.11
    source: |
      def handler(event, context):
          print("Lambda invoked by CodePipeline")
          return {'statusCode': 200}
pipelines:
  - name: "demo-pipeline"
    source:
      provider: CodeCommit
      configuration:
        RepositoryName: "demo-repo"
        BranchName: "main"
    stages:
      - name: Source
        actions:
          - name: Source
            provider: CodeCommit
            namespace: SourceVariables
            output_artifacts: ["SourceArtifact"]
      - name: Build
        actions:
          - name: Build
            provider: CodeBuild
            configuration:
              ProjectName: "demo-build"
              PrimarySource: "SourceArtifact"
            input_artifacts: ["SourceArtifact"]
            output_artifacts: ["BuildArtifact"]
            namespace: BuildVariables
      - name: Deploy
        actions:
          - name: Invoke
            provider: Lambda
            configuration:
              FunctionName: "demo-lambda"
            input_artifacts: ["BuildArtifact"]
    triggers:
      - event: codecommit-branch
        branches: ["main"]
      - event: schedule
        cron: "cron(0 12 * * ? *)"
codestar_connections: []
EOF
}

resource "random_pet" "suffix" {
  length = 2
}

# ---------------------------------------------------------------------------
# Locals: parse YAML, resolve names, derive flags
# ---------------------------------------------------------------------------
locals {
  raw    = yamldecode(var.config)
  suffix = random_pet.suffix.id

  artifact_bucket_name       = "${local.raw.artifact_bucket_prefix}-${local.suffix}"
  cache_bucket_name          = "${local.raw.cache_bucket_prefix}-${local.suffix}"

  # Map friendly names to unique names
  repo_actual_name = {
    for r in local.raw.repositories : r.name => "${r.name}-${local.suffix}"
  }
  build_project_actual_name = {
    for k, _ in local.raw.build_projects : k => "${k}-${local.suffix}"
  }
  lambda_function_actual_name = {
    for k, _ in local.raw.lambda_functions : k => "${k}-${local.suffix}"
  }

  # Repository list enriched with unique name
  repositories = [
    for r in local.raw.repositories : merge(r, {
      unique_name = "${r.name}-${local.suffix}"
    })
  ]

  # Helper: extract all stage action providers across pipelines (for IAM)
  all_pipeline_actions = flatten([
    for p in local.raw.pipelines : [
      for s in p.stages : [
        for a in s.actions : {
          pipeline  = p.name
          stage     = s.name
          provider  = a.provider
          proj_name = try(a.configuration.ProjectName, null)
          func_name = try(a.configuration.FunctionName, null)
        }
      ]
    ]
  ])

  any_codecommit_source = anytrue([
    for p in local.raw.pipelines : p.source.provider == "CodeCommit"
  ])
  any_codebuild = anytrue([
    for a in local.all_pipeline_actions : a.provider == "CodeBuild"
  ])
  any_lambda = anytrue([
    for a in local.all_pipeline_actions : a.provider == "Lambda"
  ])
  any_ecr_source = anytrue([
    for p in local.raw.pipelines : p.source.provider == "ECR"
  ])
  any_codestar_source = anytrue([
    for p in local.raw.pipelines : contains(["Bitbucket", "GitHub", "GitHubEnterpriseServer"], p.source.provider)
  ])
  # Map each lambda function to the pipeline ARN that references it
  lambda_pipeline_map = {
    for f in flatten([
      for p in local.raw.pipelines : [
        for a in flatten([for s in p.stages : [for act in s.actions : {
          func = try(act.configuration.FunctionName, null)
          pipeline_arn = "arn:${data.aws_partition.current.partition}:codepipeline:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:${p.name}"
        }]]) : {
          func = a.func
          pipeline_arn = a.pipeline_arn
        } if a.func != null
      ]
    ]) : f.func => f.pipeline_arn...
  }

  # Unique per lambda: pick first pipeline ARN for source_arn
  lambda_source_arn = {
    for k, v in local.lambda_pipeline_map : k => v[0]
  }
}

# ---------------------------------------------------------------------------
# Data Sources
# ---------------------------------------------------------------------------
data "aws_region" "current" {}
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------
# KMS Key for S3 bucket encryption
# ---------------------------------------------------------------------------
resource "aws_kms_key" "s3" {
  description             = "KMS key for Terraforest S3 bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

# ---------------------------------------------------------------------------
# S3 Artifact Bucket
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "artifact" {
  bucket = local.artifact_bucket_name
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "artifact" {
  bucket                  = aws_s3_bucket.artifact.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifact" {
  bucket = aws_s3_bucket.artifact.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "artifact" {
  bucket = aws_s3_bucket.artifact.id
  versioning_configuration {
    status = "Enabled"
  }
}

# ---------------------------------------------------------------------------
# S3 Build Cache Bucket
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "cache" {
  bucket = local.cache_bucket_name
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "cache" {
  bucket                  = aws_s3_bucket.cache.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cache" {
  bucket = aws_s3_bucket.cache.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3.arn
    }
  }
}

# ---------------------------------------------------------------------------
# IAM: Assume-role policy documents
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "pipeline_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["codepipeline.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "codebuild_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["codebuild.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "lambda_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "eventbridge_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }
  }
}

# ---------------------------------------------------------------------------
# IAM: Default CodePipeline Role (path /terraforest/)
# ---------------------------------------------------------------------------
resource "aws_iam_role" "pipeline_default" {
  count              = local.raw.default_pipeline_role ? 1 : 0
  name               = "terraforest-pipeline-${local.suffix}"
  path               = "/terraforest/"
  assume_role_policy = data.aws_iam_policy_document.pipeline_assume.json

  tags = {
    Name = "terraforest-pipeline-${local.suffix}"
  }
}

data "aws_iam_policy_document" "pipeline_default" {
  count = local.raw.default_pipeline_role ? 1 : 0

  # S3 artifact bucket access
  statement {
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:ListBucket",
      "s3:GetBucketLocation",
    ]
    resources = [
      aws_s3_bucket.artifact.arn,
      "${aws_s3_bucket.artifact.arn}/*",
      aws_s3_bucket.cache.arn,
      "${aws_s3_bucket.cache.arn}/*",
    ]
  }

  # CodeCommit source access
  dynamic "statement" {
    for_each = local.any_codecommit_source ? [1] : []
    content {
      effect = "Allow"
      actions = [
        "codecommit:GetBranch",
        "codecommit:GetCommit",
        "codecommit:UploadArchive",
        "codecommit:GetUploadArchiveStatus",
        "codecommit:CancelUploadArchive",
      ]
      resources = [for r in aws_codecommit_repository.this : r.arn]
    }
  }

  # CodeBuild access
  dynamic "statement" {
    for_each = local.any_codebuild ? [1] : []
    content {
      effect = "Allow"
      actions = [
        "codebuild:StartBuild",
        "codebuild:BatchGetBuilds",
        "codebuild:StopBuild",
      ]
      resources = [for p in aws_codebuild_project.this : p.arn]
    }
  }

  # Lambda invocation
  dynamic "statement" {
    for_each = local.any_lambda ? [1] : []
    content {
      effect = "Allow"
      actions = [
        "lambda:InvokeFunction",
      ]
      resources = [for f in aws_lambda_function.this : f.arn]
    }
  }

  # ECR source access
  dynamic "statement" {
    for_each = local.any_ecr_source ? [1] : []
    content {
      effect = "Allow"
      actions = [
        "ecr:DescribeImages",
        "ecr:DescribeRepositories",
        "ecr:ListImages",
      ]
      resources = ["*"]
    }
  }

  # CodeStar connection access
  dynamic "statement" {
    for_each = local.any_codestar_source ? [1] : []
    content {
      effect = "Allow"
      actions = [
        "codestar-connections:UseConnection",
      ]
      resources = [for c in aws_codestarconnections_connection.this : c.arn]
    }
  }
}

resource "aws_iam_policy" "pipeline_default" {
  count       = local.raw.default_pipeline_role ? 1 : 0
  name        = "terraforest-pipeline-policy-${local.suffix}"
  path        = "/terraforest/"
  description = "Policy for CodePipeline default role"
  policy      = data.aws_iam_policy_document.pipeline_default[0].json
}

resource "aws_iam_role_policy_attachment" "pipeline_default" {
  count      = local.raw.default_pipeline_role ? 1 : 0
  role       = aws_iam_role.pipeline_default[0].name
  policy_arn = aws_iam_policy.pipeline_default[0].arn
}

# ---------------------------------------------------------------------------
# IAM: CodeBuild Service Role
# ---------------------------------------------------------------------------
resource "aws_iam_role" "codebuild" {
  count              = local.any_codebuild ? 1 : 0
  name               = "terraforest-codebuild-${local.suffix}"
  path               = "/terraforest/"
  assume_role_policy = data.aws_iam_policy_document.codebuild_assume.json
}

data "aws_iam_policy_document" "codebuild" {
  count = local.any_codebuild ? 1 : 0

  statement {
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:ListBucket",
      "s3:GetBucketLocation",
    ]
    resources = [
      aws_s3_bucket.artifact.arn,
      "${aws_s3_bucket.artifact.arn}/*",
      aws_s3_bucket.cache.arn,
      "${aws_s3_bucket.cache.arn}/*",
    ]
  }

  statement {
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "codebuild" {
  count       = local.any_codebuild ? 1 : 0
  name        = "terraforest-codebuild-policy-${local.suffix}"
  path        = "/terraforest/"
  description = "Policy for CodeBuild service role"
  policy      = data.aws_iam_policy_document.codebuild[0].json
}

resource "aws_iam_role_policy_attachment" "codebuild" {
  count      = local.any_codebuild ? 1 : 0
  role       = aws_iam_role.codebuild[0].name
  policy_arn = aws_iam_policy.codebuild[0].arn
}

# ---------------------------------------------------------------------------
# IAM: Lambda Execution Role
# ---------------------------------------------------------------------------
resource "aws_iam_role" "lambda_exec" {
  count              = local.any_lambda ? 1 : 0
  name               = "terraforest-lambda-${local.suffix}"
  path               = "/terraforest/"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume.json
}

data "aws_iam_policy_document" "lambda_exec" {
  count = local.any_lambda ? 1 : 0

  statement {
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "lambda_exec" {
  count       = local.any_lambda ? 1 : 0
  name        = "terraforest-lambda-policy-${local.suffix}"
  path        = "/terraforest/"
  description = "Policy for Lambda execution role"
  policy      = data.aws_iam_policy_document.lambda_exec[0].json
}

resource "aws_iam_role_policy_attachment" "lambda_exec" {
  count      = local.any_lambda ? 1 : 0
  role       = aws_iam_role.lambda_exec[0].name
  policy_arn = aws_iam_policy.lambda_exec[0].arn
}

# ---------------------------------------------------------------------------
# CodeCommit Repositories
# ---------------------------------------------------------------------------
resource "aws_codecommit_repository" "this" {
  for_each = {
    for r in local.repositories : r.name => r
  }
  repository_name = each.value.unique_name
  description     = each.value.description
  default_branch  = try(each.value.default_branch, "main")
}

# ---------------------------------------------------------------------------
# CodeBuild Projects
# ---------------------------------------------------------------------------
resource "aws_codebuild_project" "this" {
  for_each = local.raw.build_projects

  name         = "terraform-${each.key}-${local.suffix}"
  description  = each.value.description
  service_role = local.any_codebuild ? aws_iam_role.codebuild[0].arn : null

  artifacts {
    type = "CODEPIPELINE"
  }

  environment {
    type         = lookup(each.value.environment, "type", "LINUX_CONTAINER")
    compute_type = lookup(each.value.environment, "compute_type", "BUILD_GENERAL1_SMALL")
    image        = lookup(each.value.environment, "image", "aws/codebuild/standard:7.0")
    image_pull_credentials_type = lookup(each.value.environment, "image_pull_credentials_type", "CODEBUILD")
  }

  source {
    type      = "CODEPIPELINE"
    buildspec = each.value.buildspec
  }

  cache {
    type  = "S3"
    location = aws_s3_bucket.cache.id
  }

  logs_config {
    cloudwatch_logs {
      group_name  = "/aws/codebuild/${each.key}"
      stream_name = "build"
    }
  }
}

# ---------------------------------------------------------------------------
# Lambda Functions
# ---------------------------------------------------------------------------
data "archive_file" "lambda" {
  for_each = local.raw.lambda_functions

  type        = "zip"
  source_content      = each.value.source
  source_content_filename = "${each.key}.py"
  output_path         = "/tmp/terraforest-lambda-${each.key}-${local.suffix}.zip"
}

resource "aws_lambda_function" "this" {
  for_each = local.raw.lambda_functions

  function_name    = "terraforest-${each.key}-${local.suffix}"
  description      = each.value.description
  handler          = each.value.handler
  runtime          = each.value.runtime
  role             = local.any_lambda ? aws_iam_role.lambda_exec[0].arn : null
  filename         = data.archive_file.lambda[each.key].output_path
  source_code_hash = data.archive_file.lambda[each.key].output_base64sha256
  publish          = true

  environment {
    variables = try(each.value.environment_variables, {})
  }
}

resource "aws_lambda_permission" "codepipeline" {
  for_each = local.raw.lambda_functions

  statement_id  = "AllowCodePipelineInvoke"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.this[each.key].function_name
  principal     = "codepipeline.amazonaws.com"
  source_arn    = lookup(local.lambda_source_arn, each.key, null)
}

# ---------------------------------------------------------------------------
# CodeStar Connections
# ---------------------------------------------------------------------------
resource "aws_codestarconnections_connection" "this" {
  for_each = {
    for c in local.raw.codestar_connections : c.name => c
  }
  name          = each.value.name
  provider_type = each.value.provider
  tags = {
    Name = each.value.name
  }
}

# ---------------------------------------------------------------------------
# CodePipeline - Pipeline (dynamic stages + actions)
# ---------------------------------------------------------------------------
resource "aws_codepipeline" "this" {
  for_each = {
    for p in local.raw.pipelines : p.name => p
  }

  name     = each.key
  role_arn = try(each.value.role_arn, "") != "" ? each.value.role_arn : (
    local.raw.default_pipeline_role ? aws_iam_role.pipeline_default[0].arn : null
  )

  artifact_store {
    location = aws_s3_bucket.artifact.bucket
    type     = "S3"
  }

# Dynamic stages (including source stage from YAML config)
  dynamic "stage" {
    for_each = [
      for idx, s in each.value.stages : merge(s, { _order = idx })
    ]

    content {
      name = stage.value.name

      # Non-approval actions (with region)
      dynamic "action" {
        for_each = [
          for a in stage.value.actions : merge(a, {
            _idx = index(stage.value.actions, a)
          })
          if a.provider != "ManualApproval"
        ]
        content {
          name             = action.value.name
          category         = lookup(action.value, "category", (
            action.value.provider == "CodeCommit" || action.value.provider == "S3" || action.value.provider == "ECR" ? "Source" : (
              action.value.provider == "CodeBuild" ? "Build" : (
                action.value.provider == "Lambda" ? "Invoke" : "Build"
              )
            )
          ))
          owner            = lookup(action.value, "owner", "AWS")
          provider         = contains(["CodeCommit", "S3", "ECR"], action.value.provider) ? action.value.provider : (
            contains(["Bitbucket", "GitHub", "GitHubEnterpriseServer"], action.value.provider) ? "CodeStarSource" : action.value.provider
          )
          version          = lookup(action.value, "version", "1")
          run_order        = lookup(action.value, "run_order", try(stage.value._order * 10 + action.value._idx + 1, 1))
          region           = lookup(action.value, "region", data.aws_region.current.region)
          namespace        = lookup(action.value, "namespace", null)
          input_artifacts  = lookup(action.value, "input_artifacts", null)
          output_artifacts = lookup(action.value, "output_artifacts", null)

          configuration = merge(
            # Base configuration from YAML action
            lookup(action.value, "configuration", {}),
            # For source actions, inject pipeline-level source configuration
            contains(["CodeCommit", "S3", "ECR", "Bitbucket", "GitHub", "GitHubEnterpriseServer"], action.value.provider) ? lookup(lookup(each.value, "source", {}), "configuration", {}) : {},
            # For CodeCommit source, resolve RepositoryName to actual unique name
            action.value.provider == "CodeCommit" ? {
              RepositoryName = contains(keys(lookup(each.value, "source", {})), "configuration") ? lookup(
                local.repo_actual_name,
                try(each.value.source.configuration.RepositoryName, ""),
                try(each.value.source.configuration.RepositoryName, "")
              ) : null
            } : {},
            # Resolve ProjectName for CodeBuild
            contains(keys(lookup(action.value, "configuration", {})), "ProjectName") ? {
              ProjectName = lookup(
                local.build_project_actual_name,
                action.value.configuration.ProjectName,
                action.value.configuration.ProjectName
              )
            } : {},
            # Resolve FunctionName for Lambda
            contains(keys(lookup(action.value, "configuration", {})), "FunctionName") ? {
              FunctionName = lookup(
                local.lambda_function_actual_name,
                action.value.configuration.FunctionName,
                action.value.configuration.FunctionName
              )
            } : {},
            # Set PollForSourceChanges false for CodeCommit source (EventBridge driven)
            action.value.provider == "CodeCommit" ? {
              PollForSourceChanges = "false"
            } : {},
          )
        }
      }

      # Approval actions (without region)
      dynamic "action" {
        for_each = [
          for a in stage.value.actions : merge(a, {
            _idx = index(stage.value.actions, a)
          })
          if a.provider == "ManualApproval"
        ]
        content {
          name             = action.value.name
          category         = "Approval"
          owner            = "AWS"
          provider         = "ManualApproval"
          version          = "1"
          run_order        = lookup(action.value, "run_order", try(stage.value._order * 10 + action.value._idx + 1, 1))
          namespace        = lookup(action.value, "namespace", null)

          configuration   = lookup(action.value, "configuration", {})
        }
      }
    }
  }

  tags = {
    Name        = each.key
    Environment = "terraforest"
  }
}

# ---------------------------------------------------------------------------
# EventBridge: IAM Roles (terrabits-{pipeline_name})
# ---------------------------------------------------------------------------
resource "aws_iam_role" "eventbridge_pipeline" {
  for_each = {
    for p in local.raw.pipelines : p.name => p
    if length(try(p.triggers, [])) > 0
  }

  name               = "terrabits-${each.key}"
  path               = "/terraforest/"
  assume_role_policy = data.aws_iam_policy_document.eventbridge_assume.json

  tags = {
    Name = "terrabits-${each.key}"
  }
}

data "aws_iam_policy_document" "eventbridge_pipeline" {
  for_each = {
    for p in local.raw.pipelines : p.name => p
    if length(try(p.triggers, [])) > 0
  }

  statement {
    effect = "Allow"
    actions = [
      "codepipeline:StartPipelineExecution",
    ]
    resources = [
      aws_codepipeline.this[each.key].arn,
    ]
  }
}

resource "aws_iam_policy" "eventbridge_pipeline" {
  for_each = {
    for p in local.raw.pipelines : p.name => p
    if length(try(p.triggers, [])) > 0
  }

  name        = "terrabits-${each.key}-policy"
  path        = "/terraforest/"
  description = "Policy allowing EventBridge to start pipeline ${each.key}"
  policy      = data.aws_iam_policy_document.eventbridge_pipeline[each.key].json
}

resource "aws_iam_role_policy_attachment" "eventbridge_pipeline" {
  for_each = {
    for p in local.raw.pipelines : p.name => p
    if length(try(p.triggers, [])) > 0
  }

  role       = aws_iam_role.eventbridge_pipeline[each.key].name
  policy_arn = aws_iam_policy.eventbridge_pipeline[each.key].arn
}

# ---------------------------------------------------------------------------
# EventBridge: Rules and Targets per pipeline trigger
# ---------------------------------------------------------------------------
locals {
  # Flatten triggers to a list of objects, each with pipeline name + trigger config
  all_triggers = flatten([
    for p in local.raw.pipelines : [
      for t_idx, t in try(p.triggers, []) : {
        pipeline      = p.name
        trigger_index = t_idx
        trigger       = t
      }
    ]
  ])
}

resource "aws_cloudwatch_event_rule" "pipeline_trigger" {
  for_each = {
    for tr in local.all_triggers : "${tr.pipeline}-${tr.trigger_index}" => tr
  }

  name          = "terrabits-${each.value.pipeline}-${each.value.trigger_index}"
  description   = "Trigger for pipeline ${each.value.pipeline} (${each.value.trigger.event})"
  event_pattern = try(each.value.trigger.event, null) == "codecommit-branch" ? jsonencode({
    source      = ["aws.codecommit"]
    detail-type = ["CodeCommit Repository State Change"]
    resources   = [
      contains(keys(local.raw.pipelines[0].source.configuration), "RepositoryName") ? (
        "arn:${data.aws_partition.current.partition}:codecommit:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:${lookup(
          local.repo_actual_name,
          try(local.raw.pipelines[0].source.configuration.RepositoryName, ""),
          try(local.raw.pipelines[0].source.configuration.RepositoryName, "")
        )}"
      ) : ""
    ]
    detail = {
      event = ["referenceCreated", "referenceUpdated"]
      referenceType = ["branch"]
      referenceName = each.value.trigger.branches
    }
  }) : try(each.value.trigger.event, null) == "codecommit-tag" ? jsonencode({
    source      = ["aws.codecommit"]
    detail-type = ["CodeCommit Repository State Change"]
    resources   = [
      contains(keys(local.raw.pipelines[0].source.configuration), "RepositoryName") ? (
        "arn:${data.aws_partition.current.partition}:codecommit:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:${lookup(
          local.repo_actual_name,
          try(local.raw.pipelines[0].source.configuration.RepositoryName, ""),
          try(local.raw.pipelines[0].source.configuration.RepositoryName, "")
        )}"
      ) : ""
    ]
    detail = {
      event = ["referenceCreated", "referenceUpdated"]
      referenceType = ["tag"]
      referenceName = each.value.trigger.tags
    }
  }) : try(each.value.trigger.event, null) == "custom" ? jsonencode(each.value.trigger.pattern) : null

  schedule_expression = try(each.value.trigger.event, null) == "schedule" ? each.value.trigger.cron : null
}

resource "aws_cloudwatch_event_target" "pipeline_trigger" {
  for_each = {
    for tr in local.all_triggers : "${tr.pipeline}-${tr.trigger_index}" => tr
  }

  rule     = aws_cloudwatch_event_rule.pipeline_trigger[each.key].name
  target_id = "PipelineTarget"
  arn      = aws_codepipeline.this[each.value.pipeline].arn
  role_arn = aws_iam_role.eventbridge_pipeline[each.value.pipeline].arn
}

# -------------------------------------------------------------------------------------
# Variables
# -------------------------------------------------------------------------------------

variable "performance_mode" {
  description = "EFS performance mode (generalPurpose or maxIO)"
  type        = string
  default     = "generalPurpose"
}

variable "throughput_mode" {
  description = "EFS throughput mode (bursting or provisioned)"
  type        = string
  default     = "bursting"
}

variable "encrypted" {
  description = "Enable EFS encryption at rest"
  type        = bool
  default     = true
}

variable "kms_key_id" {
  description = "Optional KMS key ID for EFS encryption (defaults to AWS managed key)"
  type        = string
  default     = null
}

variable "vpc_id" {
  description = "VPC ID for deploying resources (empty for public endpoint)"
  type        = string
  default     = ""
}

variable "subnet_ids" {
  description = "List of subnet IDs for EFS mount targets and VPC endpoint"
  type        = list(string)
  default     = []
}

variable "sftp_server_name" {
  description = "Name tag for the SFTP server"
  type        = string
  default     = "managed-sftp-server"
}

variable "is_public" {
  description = "Allocate Elastic IPs when endpoint type is VPC (provides public internet access via EIPs)"
  type        = bool
  default     = false
}

variable "logging_enabled" {
  description = "Enable CloudWatch logging for the SFTP server"
  type        = bool
  default     = false
}

variable "sftp_role_arn" {
  description = "Optional IAM role ARN for SFTP users (auto-generated if empty)"
  type        = string
  default     = ""
}

variable "allowed_ip_range" {
  description = "CIDR block allowed to connect to the SFTP server (ingress)"
  type        = string
  default     = "0.0.0.0/0"
}

variable "efs_security_group_ids" {
  description = "Optional list of security group IDs to attach to EFS mount targets"
  type        = list(string)
  default     = []
}

variable "sftp_users" {
  description = <<EOT
Map of SFTP users with POSIX profiles and SSH keys.
Key = username, value = object with uid, gid, home_directory, restricted, ssh_public_key, role_arn (optional)
EOT
  type = map(object({
    uid              = number
    gid              = number
    home_directory   = string
    restricted       = bool
    ssh_public_key   = string
    role_arn         = optional(string)
  }))
  default = {}
}

variable "additional_access_points" {
  description = "Map of additional EFS access points for general storage paths"
  type = map(object({
    path        = string
    uid         = number
    gid         = number
    permissions = string
  }))
  default = {}
}

# -------------------------------------------------------------------------------------
# Terraform & Provider version constraints
# -------------------------------------------------------------------------------------

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

# -------------------------------------------------------------------------------------
# Locals
# -------------------------------------------------------------------------------------

locals {
  create_mount_targets  = var.vpc_id != "" && length(var.subnet_ids) > 0
  endpoint_type         = var.vpc_id != "" ? "VPC" : "PUBLIC"
  auto_role_name        = "${var.sftp_server_name}-role"
  logging_role_name     = "${var.sftp_server_name}-logging-role"
  policy_prefix         = "${var.sftp_server_name}-policy"
  vpc_mode              = var.vpc_id != ""

  # Extract role name from provided ARN for policy attachment
  provided_role_name = var.sftp_role_arn != "" ? regex("role/([^/]+)$", var.sftp_role_arn)[0] : ""

  # Security groups for EFS mount targets
  efs_mount_target_sgs = length(var.efs_security_group_ids) > 0 ? var.efs_security_group_ids : (
    var.vpc_id != "" ? [aws_security_group.efs[0].id] : []
  )

  # IAM role ARN for SFTP users (auto-generated or provided)
  sftp_role_arn_final = var.sftp_role_arn != "" ? var.sftp_role_arn : aws_iam_role.transfer[0].arn
}

# -------------------------------------------------------------------------------------
# Elastic IPs (conditional - only in VPC mode with is_public=true)
# -------------------------------------------------------------------------------------

resource "aws_eip" "sftp" {
  count  = local.vpc_mode && var.is_public ? length(var.subnet_ids) : 0
  domain = "vpc"

  tags = {
    Name = "${var.sftp_server_name}-eip-${count.index + 1}"
  }
}

# -------------------------------------------------------------------------------------
# Security Group for SFTP (VPC mode)
# -------------------------------------------------------------------------------------

resource "aws_security_group" "sftp" {
  count       = local.vpc_mode ? 1 : 0
  name        = "${var.sftp_server_name}-sftp"
  description = "Security group for AWS Transfer Family SFTP server"
  vpc_id      = var.vpc_id

  tags = {
    Name = "${var.sftp_server_name}-sftp"
  }
}

resource "aws_security_group_rule" "sftp_ingress_ssh" {
  count             = local.vpc_mode ? 1 : 0
  type              = "ingress"
  from_port         = 22
  to_port           = 22
  protocol          = "tcp"
  cidr_blocks       = [var.allowed_ip_range]
  security_group_id = aws_security_group.sftp[0].id
}

resource "aws_security_group_rule" "sftp_egress_all" {
  count             = local.vpc_mode ? 1 : 0
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.sftp[0].id
}

# -------------------------------------------------------------------------------------
# Security Group for EFS (NFS access from SFTP server)
# -------------------------------------------------------------------------------------

resource "aws_security_group" "efs" {
  count       = local.vpc_mode ? 1 : 0
  name        = "${var.sftp_server_name}-efs"
  description = "Security group for EFS file system"
  vpc_id      = var.vpc_id

  tags = {
    Name = "${var.sftp_server_name}-efs"
  }
}

resource "aws_security_group_rule" "efs_ingress_nfs" {
  count                    = local.vpc_mode ? 1 : 0
  type                     = "ingress"
  from_port                = 2049
  to_port                  = 2049
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.sftp[0].id
  security_group_id        = aws_security_group.efs[0].id
}

resource "aws_security_group_rule" "efs_egress_all" {
  count             = local.vpc_mode ? 1 : 0
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.efs[0].id
}

# -------------------------------------------------------------------------------------
# IAM Trust Policy for Transfer Service
# -------------------------------------------------------------------------------------

data "aws_iam_policy_document" "transfer_assume_role" {
  statement {
    sid    = "TransferAssumeRole"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["transfer.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

# -------------------------------------------------------------------------------------
# IAM Role for Transfer Server (auto-generated)
# -------------------------------------------------------------------------------------

resource "aws_iam_role" "transfer" {
  count              = var.sftp_role_arn == "" ? 1 : 0
  name               = local.auto_role_name
  assume_role_policy = data.aws_iam_policy_document.transfer_assume_role.json

  tags = {
    Name = local.auto_role_name
  }
}

# -------------------------------------------------------------------------------------
# IAM Policy: EFS Client Access
# -------------------------------------------------------------------------------------

data "aws_iam_policy_document" "efs_access" {
  statement {
    sid    = "EFSClientAccess"
    effect = "Allow"
    actions = [
      "elasticfilesystem:ClientMount",
      "elasticfilesystem:ClientRead",
      "elasticfilesystem:ClientWrite"
    ]
    resources = [aws_efs_file_system.this.arn]
  }
}

resource "aws_iam_policy" "efs_access" {
  name   = "${local.policy_prefix}-efs-access"
  policy = data.aws_iam_policy_document.efs_access.json
}

resource "aws_iam_role_policy_attachment" "efs_access" {
  role       = var.sftp_role_arn == "" ? aws_iam_role.transfer[0].name : local.provided_role_name
  policy_arn = aws_iam_policy.efs_access.arn
}

# -------------------------------------------------------------------------------------
# EFS File System
# -------------------------------------------------------------------------------------

resource "aws_efs_file_system" "this" {
  creation_token   = var.sftp_server_name
  performance_mode = var.performance_mode
  throughput_mode  = var.throughput_mode
  encrypted        = var.encrypted
  kms_key_id       = var.encrypted ? var.kms_key_id : null

  tags = {
    Name = var.sftp_server_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -------------------------------------------------------------------------------------
# EFS Mount Targets (conditional on vpc_id and subnet_ids)
# -------------------------------------------------------------------------------------

resource "aws_efs_mount_target" "this" {
  count           = local.create_mount_targets ? length(var.subnet_ids) : 0
  file_system_id  = aws_efs_file_system.this.id
  subnet_id       = var.subnet_ids[count.index]
  security_groups = local.efs_mount_target_sgs
}

# -------------------------------------------------------------------------------------
# EFS Access Points for sftp_users
# -------------------------------------------------------------------------------------

resource "aws_efs_access_point" "sftp_user" {
  for_each       = var.sftp_users
  file_system_id = aws_efs_file_system.this.id

  posix_user {
    uid = each.value.uid
    gid = each.value.gid
  }

  root_directory {
    path = each.value.home_directory
    creation_info {
      owner_uid   = each.value.uid
      owner_gid   = each.value.gid
      permissions = "0755"
    }
  }

  tags = {
    Name = "${var.sftp_server_name}-${each.key}"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -------------------------------------------------------------------------------------
# EFS Access Points for additional_access_points
# -------------------------------------------------------------------------------------

resource "aws_efs_access_point" "additional" {
  for_each       = var.additional_access_points
  file_system_id = aws_efs_file_system.this.id

  posix_user {
    uid = each.value.uid
    gid = each.value.gid
  }

  root_directory {
    path = each.value.path
    creation_info {
      owner_uid   = each.value.uid
      owner_gid   = each.value.gid
      permissions = each.value.permissions
    }
  }

  tags = {
    Name = "${var.sftp_server_name}-additional-${each.key}"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -------------------------------------------------------------------------------------
# AWS Transfer Family SFTP Server
# -------------------------------------------------------------------------------------

resource "aws_transfer_server" "this" {
  domain                 = "EFS"
  identity_provider_type = "SERVICE_MANAGED"
  security_policy_name   = "TransferSecurityPolicy-2023-05"
  endpoint_type          = local.endpoint_type
  protocols              = ["SFTP"]
  logging_role           = var.logging_enabled ? aws_iam_role.logging[0].arn : null

  dynamic "endpoint_details" {
    for_each = local.vpc_mode ? [1] : []
    content {
      address_allocation_ids = var.is_public ? aws_eip.sftp[*].id : null
      subnet_ids             = var.subnet_ids
      vpc_id                 = var.vpc_id
      security_group_ids     = [aws_security_group.sftp[0].id]
    }
  }

  tags = {
    Name = var.sftp_server_name
  }
}

# -------------------------------------------------------------------------------------
# SFTP Users
# -------------------------------------------------------------------------------------

resource "aws_transfer_user" "this" {
  for_each           = var.sftp_users
  server_id          = aws_transfer_server.this.id
  user_name          = each.key
  role               = each.value.role_arn != null ? each.value.role_arn : local.sftp_role_arn_final
  home_directory     = each.value.home_directory
  home_directory_type = each.value.restricted ? "PATH" : "LOGICAL"

  posix_profile {
    uid = each.value.uid
    gid = each.value.gid
  }

  tags = {
    Name = "${var.sftp_server_name}-user-${each.key}"
  }
}

resource "aws_transfer_ssh_key" "this" {
  for_each  = var.sftp_users
  server_id = aws_transfer_server.this.id
  user_name = aws_transfer_user.this[each.key].user_name
  body      = each.value.ssh_public_key
}

# -------------------------------------------------------------------------------------
# CloudWatch Logging (conditional)
# -------------------------------------------------------------------------------------

data "aws_iam_policy_document" "logging_assume_role" {
  statement {
    sid    = "LoggingAssumeRole"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["transfer.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

data "aws_iam_policy_document" "logging" {
  statement {
    sid    = "TransferLogDelivery"
    effect = "Allow"
    actions = [
      "logs:CreateLogDelivery",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogStreams",
      "logs:DescribeLogGroups"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role" "logging" {
  count              = var.logging_enabled ? 1 : 0
  name               = local.logging_role_name
  assume_role_policy = data.aws_iam_policy_document.logging_assume_role.json

  tags = {
    Name = local.logging_role_name
  }
}

resource "aws_iam_policy" "logging" {
  count  = var.logging_enabled ? 1 : 0
  name   = "${local.policy_prefix}-logging"
  policy = data.aws_iam_policy_document.logging.json
}

resource "aws_iam_role_policy_attachment" "logging" {
  count      = var.logging_enabled ? 1 : 0
  role       = aws_iam_role.logging[0].name
  policy_arn = aws_iam_policy.logging[0].arn
}

locals {
  create_bucket  = var.create_bucket && var.create_bucket_defaults
  use_kms        = local.create_bucket && var.sse_algorithm == null
  sse_algorithm  = var.sse_algorithm != null ? var.sse_algorithm : "aws:kms"
  sse_kms_key_id = local.use_kms ? aws_kms_key.s3[0].arn : (var.sse_algorithm != null && length(keys(var.sse_kms_key_override)) > 0 ? var.sse_kms_key_override[var.sse_algorithm == "aws:kms" ? "kms_master_key_id" : ""] : null)

  # Object ownership
  object_ownership_rules = var.object_ownership_enabled ? (var.object_ownership != null ? var.object_ownership : "ObjectWriter") : null

  # Bucket naming
  generated_name        = local.create_bucket && var.bucket_name == null && var.bucket_name_prefix == null ? "s3-${random_id.bucket[0].hex}" : null
  effective_bucket_name = var.bucket_name != null ? var.bucket_name : local.generated_name
  bucket_prefix_val     = local.create_bucket && var.bucket_name == null && var.bucket_name_prefix != null ? var.bucket_name_prefix : null

  # Compute the combined bucket policy
  # We always create the data resource for caller_identity and iam_policy_document
  bucket_policy_statements = concat(
    var.allow_elb_logging ? [
      {
        sid    = "ELBAccessLogDelivery"
        effect = "Allow"
        principals = {
          type        = "Service"
          identifiers = ["logdelivery.elasticloadbalancing.amazonaws.com"]
        }
        actions   = ["s3:PutObject"]
        resources = ["${aws_s3_bucket.this[0].arn}/*"]
        condition = null
      },
      {
        sid    = "ELBAccessLogDeliveryACL"
        effect = "Allow"
        principals = {
          type        = "AWS"
          identifiers = [data.aws_caller_identity.current.arn]
        }
        actions   = ["s3:GetBucketAcl"]
        resources = [aws_s3_bucket.this[0].arn]
        condition = null
      }
    ] : [],
    var.require_secure_transport ? [
      {
        sid    = "DenyInsecureTransport"
        effect = "Deny"
        principals = {
          type        = "*"
          identifiers = ["*"]
        }
        actions   = ["s3:*"]
        resources = [aws_s3_bucket.this[0].arn, "${aws_s3_bucket.this[0].arn}/*"]
        condition = {
          test     = "Bool"
          variable = "aws:SecureTransport"
          values   = ["false"]
        }
      }
    ] : [],
    var.minimum_tls_version != null ? [
      {
        sid    = "DenyTLSVersionOld"
        effect = "Deny"
        principals = {
          type        = "*"
          identifiers = ["*"]
        }
        actions   = ["s3:*"]
        resources = [aws_s3_bucket.this[0].arn, "${aws_s3_bucket.this[0].arn}/*"]
        condition = {
          test     = "NumericLessThan"
          variable = "s3:TlsVersion"
          values   = [var.minimum_tls_version]
        }
      }
    ] : []
  )

  attach_bucket_policy = local.create_bucket && (
    var.allow_elb_logging || var.require_secure_transport || var.minimum_tls_version != null || var.user_supplied_policy != null
  )
}

data "aws_caller_identity" "current" {}

resource "random_id" "bucket" {
  count       = local.create_bucket && var.bucket_name == null && var.bucket_name_prefix == null ? 1 : 0
  byte_length = 8
}

# KMS key for default encryption
resource "aws_kms_key" "s3" {
  count                    = local.use_kms ? 1 : 0
  description              = "KMS key for S3 bucket ${coalesce(local.effective_bucket_name, local.bucket_prefix_val)}"
  deletion_window_in_days  = var.kms_deletion_window
  enable_key_rotation      = true
  tags                     = var.tags
}

resource "aws_kms_alias" "s3" {
  count         = local.use_kms ? 1 : 0
  name_prefix   = "alias/s3-"
  target_key_id = aws_kms_key.s3[0].key_id
}

# The S3 bucket itself
resource "aws_s3_bucket" "this" {
  count         = local.create_bucket ? 1 : 0
  bucket        = local.effective_bucket_name
  bucket_prefix = local.bucket_prefix_val
  force_destroy = var.force_destroy
  tags          = var.tags
}

# Bucket policy (attached before public access block and ownership controls when policy exists)
resource "aws_s3_bucket_policy" "this" {
  count  = local.attach_bucket_policy ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  policy = data.aws_iam_policy_document.combined[0].json
  depends_on = [
    aws_s3_bucket.this
  ]
}

data "aws_iam_policy_document" "combined" {
  count = local.attach_bucket_policy ? 1 : 0

  dynamic "statement" {
    for_each = local.bucket_policy_statements
    content {
      sid       = statement.value.sid
      effect    = statement.value.effect
      actions   = statement.value.actions
      resources = statement.value.resources
      principals {
        type        = statement.value.principals.type
        identifiers = statement.value.principals.identifiers
      }
      dynamic "condition" {
        for_each = statement.value.condition != null ? [statement.value.condition] : []
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }

  # Merge user-supplied policy statements
  source_policy_documents = var.user_supplied_policy != null ? [var.user_supplied_policy] : []
}

# Public access block - apply after bucket policy to avoid conflicts
resource "aws_s3_bucket_public_access_block" "this" {
  count                   = local.create_bucket ? 1 : 0
  bucket                  = aws_s3_bucket.this[0].id
  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets

  depends_on = [aws_s3_bucket.this[0], aws_s3_bucket_policy.this]
}

# Object ownership controls - apply after bucket policy
resource "aws_s3_bucket_ownership_controls" "this" {
  count  = local.create_bucket && local.object_ownership_rules != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  rule {
    object_ownership = local.object_ownership_rules
  }

  depends_on = [aws_s3_bucket.this[0], aws_s3_bucket_policy.this]
}

# Server-side encryption configuration
resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count  = local.create_bucket ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = local.sse_algorithm
      kms_master_key_id = local.sse_kms_key_id
    }
  }
}

# Versioning
resource "aws_s3_bucket_versioning" "this" {
  count  = local.create_bucket && var.versioning_enabled != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  versioning_configuration {
    status = var.versioning_enabled ? "Enabled" : "Suspended"
  }
}

# Object lock configuration
resource "aws_s3_bucket_object_lock_configuration" "this" {
  count  = local.create_bucket && var.object_lock_enabled ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  rule {
    default_retention {
      mode  = var.object_lock_default_retention.mode
      days  = var.object_lock_default_retention.days
      years = var.object_lock_default_retention.years
    }
  }
}

# Canned ACL
resource "aws_s3_bucket_acl" "this" {
  count  = local.create_bucket && var.canned_acl != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  acl    = var.canned_acl

  depends_on = [
    aws_s3_bucket_ownership_controls.this,
    aws_s3_bucket_public_access_block.this
  ]
}

# Explicit ACL grants
resource "aws_s3_bucket_acl" "grants" {
  count  = local.create_bucket && var.canned_acl == null && length(var.access_control_grants) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  dynamic "access_control_policy" {
    for_each = length(var.access_control_grants) > 0 ? [1] : []
    iterator = _ignored
    content {
      dynamic "grant" {
        for_each = var.access_control_grants
        content {
          permission = grant.value.permission
          grantee {
            type          = grant.value.type
            email_address = grant.value.email_address
            id            = grant.value.id
            uri           = grant.value.uri
          }
        }
      }
      owner {
        id = data.aws_caller_identity.current.account_id
      }
    }
  }

  depends_on = [
    aws_s3_bucket_ownership_controls.this,
    aws_s3_bucket_public_access_block.this
  ]
}

# Static website hosting
resource "aws_s3_bucket_website_configuration" "this" {
  count  = local.create_bucket && var.website_configuration != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  index_document {
    suffix = try(var.website_configuration.index_document, null)
  }

  error_document {
    key = try(var.website_configuration.error_document, null)
  }

  dynamic "redirect_all_requests_to" {
    for_each = try(var.website_configuration.redirect_all_requests_to, null) != null ? [var.website_configuration.redirect_all_requests_to] : []
    content {
      host_name = redirect_all_requests_to.value.host_name
      protocol  = try(redirect_all_requests_to.value.protocol, null)
    }
  }

  dynamic "routing_rule" {
    for_each = try(var.website_configuration.routing_rules, [])
    content {
      dynamic "condition" {
        for_each = try(routing_rule.value.condition, null) != null ? [routing_rule.value.condition] : []
        content {
          http_error_code_returned_equals = try(condition.value.http_error_code_returned_equals, null)
          key_prefix_equals               = try(condition.value.key_prefix_equals, null)
        }
      }
      dynamic "redirect" {
        for_each = try(routing_rule.value.redirect, null) != null ? [routing_rule.value.redirect] : []
        content {
          host_name             = try(redirect.value.host_name, null)
          http_redirect_code    = try(redirect.value.http_redirect_code, null)
          protocol              = try(redirect.value.protocol, null)
          replace_key_prefix_with = try(redirect.value.replace_key_prefix_with, null)
          replace_key_with      = try(redirect.value.replace_key_with, null)
        }
      }
    }
  }
}

# CORS configuration
resource "aws_s3_bucket_cors_configuration" "this" {
  count  = local.create_bucket && length(var.cors_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = try(cors_rule.value.allowed_headers, null)
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

# Access logging
resource "aws_s3_bucket_logging" "this" {
  count  = local.create_bucket && var.logging_target_bucket != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  target_bucket = var.logging_target_bucket
  target_prefix = var.logging_target_prefix
}

# Transfer acceleration
resource "aws_s3_bucket_accelerate_configuration" "this" {
  count  = local.create_bucket && var.transfer_acceleration_enabled ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  status = "Enabled"
}

# Requester pays
resource "aws_s3_bucket_request_payment_configuration" "this" {
  count  = local.create_bucket && var.requester_pays_enabled ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  payer  = "Requester"
}

# Lifecycle rules
resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count  = local.create_bucket && length(var.lifecycle_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = try(rule.value.id, "rule-${rule.key}")
      status = rule.value.status

      dynamic "abort_incomplete_multipart_upload" {
        for_each = try(rule.value.abort_incomplete_multipart_upload, null) != null ? [rule.value.abort_incomplete_multipart_upload] : []
        content {
          days_after_initiation = abort_incomplete_multipart_upload.value.days_after_initiation
        }
      }

      dynamic "expiration" {
        for_each = try(rule.value.expiration, null) != null ? [rule.value.expiration] : []
        content {
          date                         = try(expiration.value.date, null)
          days                         = try(expiration.value.days, null)
          expired_object_delete_marker = try(expiration.value.expired_object_delete_marker, null)
        }
      }

      dynamic "filter" {
        for_each = try(rule.value.filter, null) != null ? [rule.value.filter] : []
        content {
          object_size_greater_than = try(filter.value.object_size_greater_than, null)
          object_size_less_than    = try(filter.value.object_size_less_than, null)
          prefix                   = try(filter.value.prefix, null)
          dynamic "and" {
            for_each = try(filter.value.and, null) != null ? [filter.value.and] : []
            content {
              object_size_greater_than = try(and.value.object_size_greater_than, null)
              object_size_less_than    = try(and.value.object_size_less_than, null)
              prefix                   = try(and.value.prefix, null)
              tags                     = try(and.value.tags, null)
            }
          }
          dynamic "tag" {
            for_each = try(filter.value.tag, null) != null ? [filter.value.tag] : []
            content {
              key   = tag.value.key
              value = tag.value.value
            }
          }
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = try(rule.value.noncurrent_version_expiration, null) != null ? [rule.value.noncurrent_version_expiration] : []
        content {
          newer_noncurrent_versions = try(noncurrent_version_expiration.value.newer_noncurrent_versions, null)
          noncurrent_days           = noncurrent_version_expiration.value.noncurrent_days
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = try(rule.value.noncurrent_version_transitions, [])
        content {
          newer_noncurrent_versions = try(noncurrent_version_transition.value.newer_noncurrent_versions, null)
          noncurrent_days           = noncurrent_version_transition.value.noncurrent_days
          storage_class             = noncurrent_version_transition.value.storage_class
        }
      }

      dynamic "transition" {
        for_each = try(rule.value.transitions, [])
        content {
          date          = try(transition.value.date, null)
          days          = try(transition.value.days, null)
          storage_class = transition.value.storage_class
        }
      }
    }
  }
}

# Cross-region replication
resource "aws_s3_bucket_replication_configuration" "this" {
  count   = local.create_bucket && var.replication_configuration != null ? 1 : 0
  bucket  = aws_s3_bucket.this[0].id
  role    = var.replication_configuration.iam_role_arn
  token   = try(var.replication_configuration.replication_token, null)

  dynamic "rule" {
    for_each = var.replication_configuration.rules
    content {
      id       = rule.value.id
      status   = rule.value.status
      priority = try(rule.value.priority, null)

      dynamic "delete_marker_replication" {
        for_each = try(rule.value.delete_marker_replication, null) != null ? [rule.value.delete_marker_replication] : []
        content {
          status = delete_marker_replication.value.status
        }
      }

      dynamic "destination" {
        for_each = [rule.value.destination]
        content {
          bucket        = destination.value.bucket
          storage_class = try(destination.value.storage_class, null)

          dynamic "access_control_translation" {
            for_each = try(destination.value.access_control_translation, null) != null ? [destination.value.access_control_translation] : []
            content {
              owner = access_control_translation.value.owner
            }
          }

          dynamic "encryption_configuration" {
            for_each = try(destination.value.encryption_configuration, null) != null ? [destination.value.encryption_configuration] : []
            content {
              replica_kms_key_id = encryption_configuration.value.replica_kms_key_id
            }
          }

          dynamic "metrics" {
            for_each = try(destination.value.metrics, null) != null ? [destination.value.metrics] : []
            content {
              status  = metrics.value.status
              event_threshold {
                minutes = try(metrics.value.event_threshold.minutes, 15)
              }
            }
          }

          dynamic "replication_time" {
            for_each = try(destination.value.replication_time, null) != null ? [destination.value.replication_time] : []
            content {
              status  = replication_time.value.status
              time {
                minutes = try(replication_time.value.time.minutes, 15)
              }
            }
          }
        }
      }

      dynamic "filter" {
        for_each = try(rule.value.filter, null) != null ? [rule.value.filter] : []
        content {
          prefix = try(filter.value.prefix, null)
          dynamic "and" {
            for_each = try(filter.value.and, null) != null ? [filter.value.and] : []
            content {
              prefix = try(and.value.prefix, null)
              tags   = try(and.value.tags, null)
            }
          }
          dynamic "tag" {
            for_each = try(filter.value.tag, null) != null ? [filter.value.tag] : []
            content {
              key   = tag.value.key
              value = tag.value.value
            }
          }
        }
      }

      dynamic "source_selection_criteria" {
        for_each = try(rule.value.source_selection_criteria, null) != null ? [rule.value.source_selection_criteria] : []
        content {
          dynamic "sse_kms_encrypted_objects" {
            for_each = try(source_selection_criteria.value.sse_kms_encrypted_objects, null) != null ? [source_selection_criteria.value.sse_kms_encrypted_objects] : []
            content {
              status = sse_kms_encrypted_objects.value.status
            }
          }
        }
      }
    }
  }
}

# Intelligent Tiering
resource "aws_s3_bucket_intelligent_tiering_configuration" "this" {
  count  = local.create_bucket && length(var.intelligent_tiering_configurations) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  name   = try(var.intelligent_tiering_configurations[0].name, "default")
  status = try(var.intelligent_tiering_configurations[0].status, "Enabled")

  dynamic "filter" {
    for_each = try(var.intelligent_tiering_configurations[0].filter, null) != null ? [var.intelligent_tiering_configurations[0].filter] : []
    content {
      prefix = try(filter.value.prefix, null)
      tags   = try(filter.value.tags, null)
    }
  }

  dynamic "tiering" {
    for_each = try(var.intelligent_tiering_configurations[0].tierings, [])
    content {
      access_tier = tiering.value.access_tier
      days        = tiering.value.days
    }
  }
}

# Variables
