variable "target_stack" {
  description = "Target stack name"
  type        = string
  default     = "benchmark"
}

variable "stack_githash" {
  description = "Stack git hash (short form)"
  type        = string
  default     = "benchmark0000"
}

variable "stack_githash_long" {
  description = "Stack git hash (long zero-padded placeholder)"
  type        = string
  default     = "benchmark000000000000000000000000000000000000000000000000"
}

variable "stack_s3_bucket" {
  description = "S3 bucket for deployment artifacts"
  type        = string
  default     = "benchmark-stack-bucket"
}

variable "dataset_s3_object_key" {
  description = "S3 object key for the standard dataset"
  type        = string
  default     = "dataset.csv"
}

variable "destigmatized_dataset_s3_object_key" {
  description = "S3 object key for the destigmatized dataset"
  type        = string
  default     = "destigmatized_dataset.csv"
}

variable "genomic_dataset_s3_object_key" {
  description = "S3 object key for the genomic dataset"
  type        = string
  default     = "genomic_dataset.csv"
}

locals {
  target_stack  = var.target_stack
  stack_githash = var.stack_githash
  s3_bucket     = var.stack_s3_bucket

  dataset_objects = [
    var.dataset_s3_object_key,
    var.destigmatized_dataset_s3_object_key,
    var.genomic_dataset_s3_object_key,
  ]

  # Map each role to its IAM name prefix and tier-specific S3 path prefixes
  role_defs = {
    wildfly = {
      name_prefix = "wildfly-deployment-s3"
      s3_prefixes = ["artifacts/wildfly/", "config/wildfly/", "ssl/wildfly/"]
    }
    httpd = {
      name_prefix = "httpd-deployment-s3"
      s3_prefixes = ["artifacts/httpd/", "config/httpd/", "ssl/httpd/"]
    }
    auth_hpds = {
      name_prefix = "auth-hpds-deployment-s3"
      s3_prefixes = ["artifacts/auth-hpds/", "config/auth-hpds/", "ssl/auth-hpds/"]
    }
    open_hpds = {
      name_prefix = "open-hpds-deployment-s3"
      s3_prefixes = ["artifacts/open-hpds/", "config/open-hpds/", "ssl/open-hpds/"]
    }
    dictionary = {
      name_prefix = "dictionary-deployment-s3"
      s3_prefixes = ["artifacts/dictionary/", "config/dictionary/", "ssl/dictionary/"]
    }
  }

  # Compute the fully-qualified IAM role/instance-profile name for each role
  role_full_names = {
    for k, v in local.role_defs : k => "${v.name_prefix}-${local.target_stack}-${local.stack_githash}"
  }
}

# ---------------------------------------------------------------------------
# EC2 assume-role trust policy (shared by all roles)
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

# ---------------------------------------------------------------------------
# IAM roles
# ---------------------------------------------------------------------------
resource "aws_iam_role" "this" {
  for_each           = local.role_defs
  name               = local.role_full_names[each.key]
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
  description        = "EC2 instance role for ${each.value.name_prefix} tier"

  tags = {
    Name        = local.role_full_names[each.key]
    Stack       = local.target_stack
    GitHash     = local.stack_githash
    Role        = each.value.name_prefix
    Environment = local.target_stack
  }
}

# ---------------------------------------------------------------------------
# Instance profiles (matching names)
# ---------------------------------------------------------------------------
resource "aws_iam_instance_profile" "this" {
  for_each = local.role_defs
  name     = local.role_full_names[each.key]
  role     = aws_iam_role.this[each.key].name

  tags = {
    Name        = local.role_full_names[each.key]
    Stack       = local.target_stack
    GitHash     = local.stack_githash
    Role        = each.value.name_prefix
    Environment = local.target_stack
  }
}

# ---------------------------------------------------------------------------
# Attach AWS managed policies
# ---------------------------------------------------------------------------
resource "aws_iam_role_policy_attachment" "cloudwatch" {
  for_each   = local.role_defs
  role       = aws_iam_role.this[each.key].name
  policy_arn = "arn:aws:iam::aws:policy/CloudWatchAgentServerPolicy"
}

resource "aws_iam_role_policy_attachment" "ssm" {
  for_each   = local.role_defs
  role       = aws_iam_role.this[each.key].name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

# ---------------------------------------------------------------------------
# Inline policy for each role (EC2 tagging, CloudWatch metrics, S3 retrieval)
# ---------------------------------------------------------------------------
resource "aws_iam_role_policy" "inline" {
  for_each = local.role_defs
  name     = "${local.role_full_names[each.key]}-inline"
  role     = aws_iam_role.this[each.key].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EC2CreateTags"
        Effect = "Allow"
        Action = ["ec2:CreateTags"]
        Resource = [
          "arn:aws:ec2:*:*:instance/*"
        ]
      },
      {
        Sid    = "CloudWatchPutMetricData"
        Effect = "Allow"
        Action = ["cloudwatch:PutMetricData"]
        Resource = ["*"]
      },
      {
        Sid    = "S3ListBucket"
        Effect = "Allow"
        Action = ["s3:ListBucket"]
        Resource = [
          "arn:aws:s3:::${local.s3_bucket}"
        ]
        Condition = {
          StringLike = {
            "s3:prefix" = concat(
              each.value.s3_prefixes,
              ["datasets/"],
              ["management/"]
            )
          }
        }
      },
      {
        Sid    = "S3GetObject"
        Effect = "Allow"
        Action = ["s3:GetObject"]
        Resource = concat(
          # Tier-specific artifacts, configs, SSL certs
          [for p in each.value.s3_prefixes : "arn:aws:s3:::${local.s3_bucket}/${p}*"],
          # Datasets
          [for k in local.dataset_objects : "arn:aws:s3:::${local.s3_bucket}/datasets/${k}"],
          # Common management / security tools
          ["arn:aws:s3:::${local.s3_bucket}/management/*"]
        )
      },
    ]
  })
}

variable "create" {
  description = "Whether to create this module's resources"
  type        = bool
  default     = true
}

variable "create_sg" {
  description = "Whether to create a new security group (true) or use an existing one (false)"
  type        = bool
  default     = true
}

variable "sg_id" {
  description = "ID of an existing security group to add rules to (used when create_sg = false)"
  type        = string
  default     = null
}

variable "vpc_id" {
  description = "ID of the VPC where the security group will be created (required when create_sg = true)"
  type        = string
  default     = null
}

variable "name" {
  description = "Name of the security group"
  type        = string
  default     = "default-sg"
}

variable "description" {
  description = "Description of the security group"
  type        = string
  default     = "Managed by Terraform"
}

variable "create_before_destroy" {
  description = "Whether to enable create-before-destroy lifecycle on the security group"
  type        = bool
  default     = true
}

variable "revoke_rules_on_delete" {
  description = "Whether to revoke rules on security group deletion"
  type        = bool
  default     = true
}

variable "tags" {
  description = "Tags to apply to created resources"
  type        = map(string)
  default     = {}
}

variable "ingress_rules" {
  description = <<-EOT
    List of ingress rule objects for the newly created security group.
    Each rule must specify exactly one of: cidr_ipv4, cidr_ipv6, referenced_sg_id, or prefix_list_id.
  EOT
  type = list(object({
    description      = optional(string, "")
    protocol         = string
    from_port        = number
    to_port          = number
    cidr_ipv4        = optional(string)
    cidr_ipv6        = optional(string)
    referenced_sg_id = optional(string)
    prefix_list_id   = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for rule in var.ingress_rules :
      sum([
        rule.cidr_ipv4 != null ? 1 : 0,
        rule.cidr_ipv6 != null ? 1 : 0,
        rule.referenced_sg_id != null ? 1 : 0,
        rule.prefix_list_id != null ? 1 : 0,
      ]) == 1
    ])
    error_message = "Each ingress rule must specify exactly one of: cidr_ipv4, cidr_ipv6, referenced_sg_id, or prefix_list_id."
  }
}

variable "egress_rules" {
  description = <<-EOT
    List of egress rule objects for the newly created security group.
    Each rule must specify exactly one of: cidr_ipv4, cidr_ipv6, referenced_sg_id, or prefix_list_id.
    Defaults to allowing all outbound IPv4 traffic if no rules are specified.
  EOT
  type = list(object({
    description      = optional(string, "")
    protocol         = string
    from_port        = number
    to_port          = number
    cidr_ipv4        = optional(string)
    cidr_ipv6        = optional(string)
    referenced_sg_id = optional(string)
    prefix_list_id   = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for rule in var.egress_rules :
      sum([
        rule.cidr_ipv4 != null ? 1 : 0,
        rule.cidr_ipv6 != null ? 1 : 0,
        rule.referenced_sg_id != null ? 1 : 0,
        rule.prefix_list_id != null ? 1 : 0,
      ]) == 1
    ])
    error_message = "Each egress rule must specify exactly one of: cidr_ipv4, cidr_ipv6, referenced_sg_id, or prefix_list_id."
  }
}

variable "existing_ingress_rules" {
  description = <<-EOT
    List of ingress rule objects to add to an existing security group (used when create_sg = false).
    Each rule must specify exactly one of: cidr_ipv4, cidr_ipv6, referenced_sg_id, or prefix_list_id.
  EOT
  type = list(object({
    description      = optional(string, "")
    protocol         = string
    from_port        = number
    to_port          = number
    cidr_ipv4        = optional(string)
    cidr_ipv6        = optional(string)
    referenced_sg_id = optional(string)
    prefix_list_id   = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for rule in var.existing_ingress_rules :
      sum([
        rule.cidr_ipv4 != null ? 1 : 0,
        rule.cidr_ipv6 != null ? 1 : 0,
        rule.referenced_sg_id != null ? 1 : 0,
        rule.prefix_list_id != null ? 1 : 0,
      ]) == 1
    ])
    error_message = "Each existing ingress rule must specify exactly one of: cidr_ipv4, cidr_ipv6, referenced_sg_id, or prefix_list_id."
  }
}

variable "existing_egress_rules" {
  description = <<-EOT
    List of egress rule objects to add to an existing security group (used when create_sg = false).
    Each rule must specify exactly one of: cidr_ipv4, cidr_ipv6, referenced_sg_id, or prefix_list_id.
    Defaults to allowing all outbound IPv4 traffic if no rules are specified.
  EOT
  type = list(object({
    description      = optional(string, "")
    protocol         = string
    from_port        = number
    to_port          = number
    cidr_ipv4        = optional(string)
    cidr_ipv6        = optional(string)
    referenced_sg_id = optional(string)
    prefix_list_id   = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for rule in var.existing_egress_rules :
      sum([
        rule.cidr_ipv4 != null ? 1 : 0,
        rule.cidr_ipv6 != null ? 1 : 0,
        rule.referenced_sg_id != null ? 1 : 0,
        rule.prefix_list_id != null ? 1 : 0,
      ]) == 1
    ])
    error_message = "Each existing egress rule must specify exactly one of: cidr_ipv4, cidr_ipv6, referenced_sg_id, or prefix_list_id."
  }
}

variable "create_prefix_list" {
  description = "Whether to create a customer-managed EC2 prefix list"
  type        = bool
  default     = false
}

variable "prefix_list_name" {
  description = "Name of the EC2 prefix list"
  type        = string
  default     = null
}

variable "prefix_list_address_family" {
  description = "Address family for the prefix list (IPv4 or IPv6)"
  type        = string
  default     = "IPv4"
}

variable "prefix_list_max_entries" {
  description = "Maximum number of entries for the prefix list"
  type        = number
  default     = null
}

variable "prefix_list_entries" {
  description = "List of CIDR entries for the prefix list"
  type = list(object({
    cidr        = string
    description = optional(string)
  }))
  default = []
}

locals {
  # If no egress rules are specified, AWS security groups default to allowing
  # all outbound traffic. We rely on that AWS default behavior rather than
  # adding an explicit 0.0.0.0/0 rule.
  new_sg_egress_rules   = var.egress_rules
  existing_egress_rules = var.existing_egress_rules

  # Merge module tags with resource-specific tags
  sg_tags = merge(var.tags, { Name = var.name })
}

# Security Group with create_before_destroy lifecycle (uses name_prefix for uniqueness)
resource "aws_security_group" "cbd" {
  count = var.create && var.create_sg && var.create_before_destroy ? 1 : 0

  name_prefix = "${var.name}-"
  description = var.description
  vpc_id      = var.vpc_id

  revoke_rules_on_delete = var.revoke_rules_on_delete

  dynamic "ingress" {
    for_each = var.ingress_rules
    content {
      description      = try(ingress.value.description, "")
      protocol         = ingress.value.protocol
      from_port        = ingress.value.from_port
      to_port          = ingress.value.to_port
      cidr_blocks      = ingress.value.cidr_ipv4 != null ? [ingress.value.cidr_ipv4] : null
      ipv6_cidr_blocks = ingress.value.cidr_ipv6 != null ? [ingress.value.cidr_ipv6] : null
      security_groups  = ingress.value.referenced_sg_id != null ? [ingress.value.referenced_sg_id] : null
      prefix_list_ids  = ingress.value.prefix_list_id != null ? [ingress.value.prefix_list_id] : null
    }
  }

  dynamic "egress" {
    for_each = local.new_sg_egress_rules
    content {
      description      = try(egress.value.description, "")
      protocol         = egress.value.protocol
      from_port        = egress.value.from_port
      to_port          = egress.value.to_port
      cidr_blocks      = egress.value.cidr_ipv4 != null ? [egress.value.cidr_ipv4] : null
      ipv6_cidr_blocks = egress.value.cidr_ipv6 != null ? [egress.value.cidr_ipv6] : null
      security_groups  = egress.value.referenced_sg_id != null ? [egress.value.referenced_sg_id] : null
      prefix_list_ids  = egress.value.prefix_list_id != null ? [egress.value.prefix_list_id] : null
    }
  }

  lifecycle {
    create_before_destroy = true
  }

  tags = local.sg_tags
}

# Security Group without create_before_destroy (uses fixed name)
resource "aws_security_group" "no_cbd" {
  count = var.create && var.create_sg && !var.create_before_destroy ? 1 : 0

  name        = var.name
  description = var.description
  vpc_id      = var.vpc_id

  revoke_rules_on_delete = var.revoke_rules_on_delete

  dynamic "ingress" {
    for_each = var.ingress_rules
    content {
      description      = try(ingress.value.description, "")
      protocol         = ingress.value.protocol
      from_port        = ingress.value.from_port
      to_port          = ingress.value.to_port
      cidr_blocks      = ingress.value.cidr_ipv4 != null ? [ingress.value.cidr_ipv4] : null
      ipv6_cidr_blocks = ingress.value.cidr_ipv6 != null ? [ingress.value.cidr_ipv6] : null
      security_groups  = ingress.value.referenced_sg_id != null ? [ingress.value.referenced_sg_id] : null
      prefix_list_ids  = ingress.value.prefix_list_id != null ? [ingress.value.prefix_list_id] : null
    }
  }

  dynamic "egress" {
    for_each = local.new_sg_egress_rules
    content {
      description      = try(egress.value.description, "")
      protocol         = egress.value.protocol
      from_port        = egress.value.from_port
      to_port          = egress.value.to_port
      cidr_blocks      = egress.value.cidr_ipv4 != null ? [egress.value.cidr_ipv4] : null
      ipv6_cidr_blocks = egress.value.cidr_ipv6 != null ? [egress.value.cidr_ipv6] : null
      security_groups  = egress.value.referenced_sg_id != null ? [egress.value.referenced_sg_id] : null
      prefix_list_ids  = egress.value.prefix_list_id != null ? [egress.value.prefix_list_id] : null
    }
  }

  lifecycle {
    create_before_destroy = false
  }

  tags = local.sg_tags
}

# Ingress rules for existing security group - used when create_sg == false
resource "aws_security_group_rule" "existing_ingress" {
  for_each = var.create && !var.create_sg ? {
    for idx, rule in var.existing_ingress_rules : idx => rule
  } : {}

  type                     = "ingress"
  security_group_id        = var.sg_id
  protocol                 = each.value.protocol
  from_port                = each.value.from_port
  to_port                  = each.value.to_port
  cidr_blocks              = each.value.cidr_ipv4 != null ? [each.value.cidr_ipv4] : null
  ipv6_cidr_blocks         = each.value.cidr_ipv6 != null ? [each.value.cidr_ipv6] : null
  source_security_group_id = each.value.referenced_sg_id != null ? each.value.referenced_sg_id : null
  prefix_list_ids          = each.value.prefix_list_id != null ? [each.value.prefix_list_id] : null
  description              = try(each.value.description, "")
}

# Egress rules for existing security group - used when create_sg == false
resource "aws_security_group_rule" "existing_egress" {
  for_each = var.create && !var.create_sg ? {
    for idx, rule in local.existing_egress_rules : idx => rule
  } : {}

  type                     = "egress"
  security_group_id        = var.sg_id
  protocol                 = each.value.protocol
  from_port                = each.value.from_port
  to_port                  = each.value.to_port
  cidr_blocks              = each.value.cidr_ipv4 != null ? [each.value.cidr_ipv4] : null
  ipv6_cidr_blocks         = each.value.cidr_ipv6 != null ? [each.value.cidr_ipv6] : null
  source_security_group_id = each.value.referenced_sg_id != null ? each.value.referenced_sg_id : null
  prefix_list_ids          = each.value.prefix_list_id != null ? [each.value.prefix_list_id] : null
  description              = try(each.value.description, "")
}

# Customer-managed EC2 prefix list
resource "aws_ec2_managed_prefix_list" "this" {
  count = var.create && var.create_prefix_list ? 1 : 0

  name           = var.prefix_list_name
  address_family = var.prefix_list_address_family
  max_entries    = var.prefix_list_max_entries

  dynamic "entry" {
    for_each = var.prefix_list_entries
    content {
      cidr        = entry.value.cidr
      description = try(entry.value.description, null)
    }
  }

  tags = merge(var.tags, { Name = var.prefix_list_name })
}

output "security_group_id" {
  description = "The ID of the security group (newly created or existing)"
  value = var.create && var.create_sg ? (
    var.create_before_destroy ? try(aws_security_group.cbd[0].id, null) : try(aws_security_group.no_cbd[0].id, null)
  ) : try(var.sg_id, null)
}

output "security_group_arn" {
  description = "The ARN of the security group"
  value = var.create && var.create_sg ? (
    var.create_before_destroy ? try(aws_security_group.cbd[0].arn, null) : try(aws_security_group.no_cbd[0].arn, null)
  ) : null
}

output "prefix_list_id" {
  description = "The ID of the created prefix list"
  value       = var.create && var.create_prefix_list ? try(aws_ec2_managed_prefix_list.this[0].id, null) : null
}

variable "project" {
  description = "Project name prefix for all IAM roles and resources"
  type        = string
  default     = "Cv-React-App"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  project = var.project
}

# ---------------------------------------------------------------------------
# Managed policy data sources
# ---------------------------------------------------------------------------

data "aws_iam_policy" "ec2_codedeploy" {
  arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonEC2RoleforAWSCodeDeploy"
}

data "aws_iam_policy" "ec2_full_access" {
  arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEC2FullAccess"
}

data "aws_iam_policy" "s3_full_access" {
  arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonS3FullAccess"
}

data "aws_iam_policy" "codedeploy_service_role" {
  arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSCodeDeployRole"
}

data "aws_iam_policy" "cloudwatch_agent" {
  arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/CloudWatchAgentServerPolicy"
}

# ---------------------------------------------------------------------------
# 1. EC2 CodeDeploy Role + Instance Profile
# ---------------------------------------------------------------------------

resource "aws_iam_role" "ec2_codedeploy" {
  name               = "${local.project}_ec2_codedeploy_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ec2_codedeploy_codedeploy" {
  role       = aws_iam_role.ec2_codedeploy.name
  policy_arn = data.aws_iam_policy.ec2_codedeploy.arn
}

resource "aws_iam_role_policy_attachment" "ec2_codedeploy_ec2_full" {
  role       = aws_iam_role.ec2_codedeploy.name
  policy_arn = data.aws_iam_policy.ec2_full_access.arn
}

resource "aws_iam_role_policy_attachment" "ec2_codedeploy_s3_full" {
  role       = aws_iam_role.ec2_codedeploy.name
  policy_arn = data.aws_iam_policy.s3_full_access.arn
}

resource "aws_iam_instance_profile" "ec2_codedeploy" {
  name = "${local.project}_ec2_codedeploy_profile"
  role = aws_iam_role.ec2_codedeploy.name
}

# ---------------------------------------------------------------------------
# 2. CodeDeploy Service Role (assumed by the CodeDeploy service itself)
# ---------------------------------------------------------------------------

resource "aws_iam_role" "codedeploy_service" {
  name               = "${local.project}_codedeploy_service_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "codedeploy.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "codedeploy_service_managed" {
  role       = aws_iam_role.codedeploy_service.name
  policy_arn = data.aws_iam_policy.codedeploy_service_role.arn
}

resource "aws_iam_role_policy_attachment" "codedeploy_service_s3_full" {
  role       = aws_iam_role.codedeploy_service.name
  policy_arn = data.aws_iam_policy.s3_full_access.arn
}

# ---------------------------------------------------------------------------
# 3. EC2 CloudWatch Agent Role + Instance Profile
# ---------------------------------------------------------------------------

resource "aws_iam_role" "ec2_cloudwatch_agent" {
  name               = "${local.project}_ec2_cloudwatch_agent_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ec2_cloudwatch_agent_managed" {
  role       = aws_iam_role.ec2_cloudwatch_agent.name
  policy_arn = data.aws_iam_policy.cloudwatch_agent.arn
}

resource "aws_iam_role_policy_attachment" "ec2_cloudwatch_agent_s3_full" {
  role       = aws_iam_role.ec2_cloudwatch_agent.name
  policy_arn = data.aws_iam_policy.s3_full_access.arn
}

resource "aws_iam_instance_profile" "ec2_cloudwatch_agent" {
  name = "${local.project}_ec2_cloudwatch_agent_profile"
  role = aws_iam_role.ec2_cloudwatch_agent.name
}

# ---------------------------------------------------------------------------
# 4. CodeBuild Role (named exactly "CodeBuildRole")
# ---------------------------------------------------------------------------

resource "aws_iam_role" "codebuild" {
  name               = "CodeBuildRole"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "codebuild_s3_full" {
  role       = aws_iam_role.codebuild.name
  policy_arn = data.aws_iam_policy.s3_full_access.arn
}

resource "aws_iam_role_policy" "codebuild_inline" {
  name   = "${local.project}_codebuild_inline_policy"
  role   = aws_iam_role.codebuild.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      # Logging permissions
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      },
      # CodePipeline S3 artifact bucket access in us-east-1
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:GetObjectVersion"
        ]
        Resource = "arn:${data.aws_partition.current.partition}:s3:::codepipeline-us-east-1-${data.aws_caller_identity.current.account_id}/*"
      },
      # CodeBuild report creation capabilities
      {
        Effect = "Allow"
        Action = [
          "codebuild:CreateReportGroup",
          "codebuild:CreateReport",
          "codebuild:UpdateReport",
          "codebuild:BatchPutTestCases",
          "codebuild:DescribeTestCases"
        ]
        Resource = "*"
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# 5. CodePipeline Role (named exactly "CodePipelineRole")
# ---------------------------------------------------------------------------

resource "aws_iam_role" "codepipeline" {
  name               = "CodePipelineRole"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS     = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
          Service = [
            "codepipeline.amazonaws.com",
            "codebuild.amazonaws.com",
            "codedeploy.amazonaws.com",
            "lambda.amazonaws.com",
            "cloudformation.amazonaws.com"
          ]
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "codepipeline_inline" {
  name   = "${local.project}_codepipeline_inline_policy"
  role   = aws_iam_role.codepipeline.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      # CodeStar Connections
      {
        Effect = "Allow"
        Action = [
          "codestar-connections:UseConnection",
          "codestar-connections:PassConnection"
        ]
        Resource = "*"
      },
      # S3
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:PutObject",
          "s3:ListBucket",
          "s3:GetBucketPolicy",
          "s3:PutBucketPolicy"
        ]
        Resource = "*"
      },
      # CodeCommit
      {
        Effect = "Allow"
        Action = [
          "codecommit:GetBranch",
          "codecommit:GetCommit",
          "codecommit:GetRepository",
          "codecommit:ListBranches",
          "codecommit:ListRepositories",
          "codecommit:UploadArchive",
          "codecommit:GetUploadArchiveStatus",
          "codecommit:CancelUploadArchive"
        ]
        Resource = "*"
      },
      # CodeDeploy
      {
        Effect = "Allow"
        Action = [
          "codedeploy:CreateDeployment",
          "codedeploy:GetDeployment",
          "codedeploy:GetDeploymentConfig",
          "codedeploy:GetApplication",
          "codedeploy:GetApplicationRevision",
          "codedeploy:RegisterApplicationRevision",
          "codedeploy:ListDeployments",
          "codedeploy:ListApplications",
          "codedeploy:StopDeployment"
        ]
        Resource = "*"
      },
      # Lambda
      {
        Effect = "Allow"
        Action = [
          "lambda:InvokeFunction",
          "lambda:ListFunctions"
        ]
        Resource = "*"
      },
      # CodeBuild
      {
        Effect = "Allow"
        Action = [
          "codebuild:StartBuild",
          "codebuild:BatchGetBuilds",
          "codebuild:StopBuild",
          "codebuild:ListProjects",
          "codebuild:ListBuildsForProject"
        ]
        Resource = "*"
      },
      # CloudFormation
      {
        Effect = "Allow"
        Action = [
          "cloudformation:CreateStack",
          "cloudformation:DeleteStack",
          "cloudformation:DescribeStacks",
          "cloudformation:DescribeStackEvents",
          "cloudformation:DescribeChangeSet",
          "cloudformation:ExecuteChangeSet",
          "cloudformation:GetTemplate",
          "cloudformation:ValidateTemplate",
          "cloudformation:UpdateStack",
          "cloudformation:ListStackResources"
        ]
        Resource = "*"
      },
      # Supporting infrastructure services (IAM PassRole + EC2)
      {
        Effect = "Allow"
        Action = [
          "iam:PassRole"
        ]
        Resource = "*"
        Condition = {
          StringEqualsIfExists = {
            "iam:PassedToService" = [
              "ec2.amazonaws.com",
              "ecs-tasks.amazonaws.com",
              "lambda.amazonaws.com",
              "codebuild.amazonaws.com",
              "codedeploy.amazonaws.com",
              "cloudformation.amazonaws.com"
            ]
          }
        }
      },
      {
        Effect = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSubnets",
          "ec2:DescribeVpcs"
        ]
        Resource = "*"
      }
    ]
  })
}

terraform {
  required_version = ">= 1.0"
