# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------
variable "admin_cidr_block" {
  description = "CIDR block allowed for SSH access to EC2 instances"
  type        = string
  default     = "10.0.0.0/8"
}

variable "ecs_cluster_name" {
  description = "Name for the ECS cluster"
  type        = string
  default     = "chaos-engineering-cluster"
}

variable "instance_type" {
  description = "EC2 instance type for the Auto Scaling group"
  type        = string
  default     = "t3.micro"
}

# ---------------------------------------------------------------------------
# Data sources
# ---------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "ecs_optimized" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-ecs-hvm-*-x86_64-ebs"]
  }
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

# ---------------------------------------------------------------------------
# SSH Key
# ---------------------------------------------------------------------------
resource "tls_private_key" "ssh" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_key_pair" "chaos" {
  key_name   = "chaos-engineering-key"
  public_key = tls_private_key.ssh.public_key_openssh
}

# ---------------------------------------------------------------------------
# VPC
# ---------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "chaos-engineering-vpc"
  }
}

# ---------------------------------------------------------------------------
# Subnet (single public subnet, no auto-assign public IP)
# ---------------------------------------------------------------------------
resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = false
  availability_zone       = data.aws_availability_zones.available.names[0]

  tags = {
    Name        = "chaos-engineering-subnet"
    ChaosTarget = "enabled"
  }
}

# ---------------------------------------------------------------------------
# Internet Gateway
# ---------------------------------------------------------------------------
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "chaos-engineering-igw"
  }
}

# ---------------------------------------------------------------------------
# Route Table & Association
# ---------------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "chaos-engineering-rt"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# Security Group (SSH from admin CIDR)
# ---------------------------------------------------------------------------
resource "aws_security_group" "instance" {
  name        = "chaos-engineering-sg"
  description = "Security group for chaos engineering instances"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from admin CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.admin_cidr_block]
  }

  egress {
    description = "All traffic to VPC CIDR (for VPC endpoints and DNS)"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "chaos-engineering-sg"
  }
}

# ---------------------------------------------------------------------------
# VPC Endpoints for ECS, SSM, ECR, and CloudWatch Logs
# ---------------------------------------------------------------------------
resource "aws_security_group" "vpc_endpoints" {
  name        = "chaos-engineering-vpc-endpoints-sg"
  description = "Security group for VPC interface endpoints"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from VPC CIDR"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "chaos-engineering-vpc-endpoints-sg"
  }
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id          = aws_vpc.main.id
  service_name    = "com.amazonaws.${data.aws_region.current.region}.s3"
  route_table_ids = [aws_route_table.public.id]

  tags = {
    Name = "chaos-engineering-s3-endpoint"
  }
}

resource "aws_vpc_endpoint" "ecr_api" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.region}.ecr.api"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.public.id]
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "chaos-engineering-ecr-api-endpoint"
  }
}

resource "aws_vpc_endpoint" "ecr_dkr" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.region}.ecr.dkr"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.public.id]
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "chaos-engineering-ecr-dkr-endpoint"
  }
}

resource "aws_vpc_endpoint" "ecs" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.region}.ecs"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.public.id]
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "chaos-engineering-ecs-endpoint"
  }
}

resource "aws_vpc_endpoint" "ecs_agent" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.region}.ecs-agent"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.public.id]
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "chaos-engineering-ecs-agent-endpoint"
  }
}

resource "aws_vpc_endpoint" "ssm" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.region}.ssm"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.public.id]
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "chaos-engineering-ssm-endpoint"
  }
}

resource "aws_vpc_endpoint" "ssm_messages" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.region}.ssmmessages"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.public.id]
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "chaos-engineering-ssmmessages-endpoint"
  }
}

resource "aws_vpc_endpoint" "ec2_messages" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.region}.ec2messages"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.public.id]
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "chaos-engineering-ec2messages-endpoint"
  }
}

resource "aws_vpc_endpoint" "logs" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.region}.logs"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.public.id]
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "chaos-engineering-logs-endpoint"
  }
}

# ---------------------------------------------------------------------------
# ECS Cluster
# ---------------------------------------------------------------------------
resource "aws_ecs_cluster" "main" {
  name = var.ecs_cluster_name

  tags = {
    Name        = var.ecs_cluster_name
    ChaosTarget = "enabled"
  }
}

# ---------------------------------------------------------------------------
# IAM Instance Role & Profile (for EC2 instances to run ECS + SSM)
# ---------------------------------------------------------------------------
resource "aws_iam_role" "ecs_instance" {
  name = "chaos-engineering-ecs-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "chaos-engineering-ecs-instance-role"
  }
}

resource "aws_iam_role_policy_attachment" "ecs_instance_ecs" {
  role       = aws_iam_role.ecs_instance.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonEC2ContainerServiceforEC2Role"
}

resource "aws_iam_role_policy_attachment" "ecs_instance_ssm" {
  role       = aws_iam_role.ecs_instance.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ecs_instance" {
  name = "chaos-engineering-ecs-instance-profile"
  role = aws_iam_role.ecs_instance.name
}

# ---------------------------------------------------------------------------
# Launch Template (IMDSv2, public IP, ECS-optimized AMI, SSH key)
# ---------------------------------------------------------------------------
resource "aws_launch_template" "chaos" {
  name_prefix   = "chaos-engineering-"
  image_id      = data.aws_ami.ecs_optimized.id
  instance_type = var.instance_type
  key_name      = aws_key_pair.chaos.key_name
  user_data = base64encode(<<-EOF
    #!/bin/bash
    echo ECS_CLUSTER=${var.ecs_cluster_name} >> /etc/ecs/ecs.config
  EOF
  )

  network_interfaces {
    associate_public_ip_address = true
    security_groups             = [aws_security_group.instance.id]
    delete_on_termination       = true
  }

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  iam_instance_profile {
    arn = aws_iam_instance_profile.ecs_instance.arn
  }

  block_device_mappings {
    device_name = "/dev/xvda"

    ebs {
      volume_size           = 30
      volume_type           = "gp3"
      delete_on_termination = true
    }
  }

  tag_specifications {
    resource_type = "instance"
    tags = {
      ChaosTarget = "enabled"
    }
  }

  tag_specifications {
    resource_type = "volume"
    tags = {
      ChaosTarget = "enabled"
    }
  }

  tags = {
    Name = "chaos-engineering-launch-template"
  }
}

# ---------------------------------------------------------------------------
# Auto Scaling Group
# ---------------------------------------------------------------------------
resource "aws_autoscaling_group" "chaos" {
  name_prefix         = "chaos-engineering-"
  vpc_zone_identifier = [aws_subnet.public.id]
  min_size            = 1
  max_size            = 1
  desired_capacity    = 1

  launch_template {
    id      = aws_launch_template.chaos.id
    version = "$Latest"
  }

  health_check_type         = "EC2"
  health_check_grace_period = 120
  force_delete              = true

  tag {
    key                 = "ChaosTarget"
    value               = "enabled"
    propagate_at_launch = true
  }

  tag {
    key                 = "Name"
    value               = "chaos-engineering-instance"
    propagate_at_launch = true
  }
}

# ---------------------------------------------------------------------------
# KMS Key for S3 bucket SSE-KMS
# ---------------------------------------------------------------------------
resource "aws_kms_key" "fis_logs" {
  description             = "Customer-managed key for FIS experiment log encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable root account permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow FIS execution role to use the key"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:role/chaos-engineering-fis-role"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "chaos-engineering-fis-log-key"
  }
}

resource "aws_kms_alias" "fis_logs" {
  name          = "alias/chaos-engineering-fis-logs"
  target_key_id = aws_kms_key.fis_logs.key_id
}

# ---------------------------------------------------------------------------
# S3 Bucket for FIS experiment logs
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "fis_logs" {
  bucket_prefix = "chaos-engineering-fis-logs-"

  tags = {
    Name = "chaos-engineering-fis-logs"
  }
}

resource "aws_s3_bucket_public_access_block" "fis_logs" {
  bucket = aws_s3_bucket.fis_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "fis_logs" {
  bucket = aws_s3_bucket.fis_logs.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.fis_logs.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_policy" "fis_logs" {
  bucket = aws_s3_bucket.fis_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowFISLogDelivery"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:role/chaos-engineering-fis-role"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.fis_logs.arn}/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-server-side-encryption" = "aws:kms"
          }
        }
      },
      {
        Sid    = "AllowAWSLogDelivery"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:role/chaos-engineering-fis-role"
        }
        Action = [
          "s3:PutObject",
          "s3:GetBucketAcl"
        ]
        Resource = [
          aws_s3_bucket.fis_logs.arn,
          "${aws_s3_bucket.fis_logs.arn}/*"
        ]
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# CloudWatch Log Group for FIS experiments
# ---------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "fis" {
  name              = "/aws/fis/chaos-engineering"
  retention_in_days = 7

  tags = {
    Name = "chaos-engineering-fis-logs"
  }
}

# ---------------------------------------------------------------------------
# CloudWatch Alarm as required no-op stop condition for FIS
# ---------------------------------------------------------------------------
resource "aws_cloudwatch_metric_alarm" "fis_noop_stop" {
  alarm_name          = "chaos-engineering-fis-noop-stop"
  comparison_operator = "GreaterThanThreshold"
  evaluation_periods  = "1"
  metric_name         = "NoopMetric"
  namespace           = "ChaosEngineering/Noop"
  period              = "86400"
  statistic           = "Maximum"
  threshold           = "0"
  treat_missing_data  = "notBreaching"
  alarm_description   = "No-op alarm that never fires, used as required FIS stop condition"

  tags = {
    Name = "chaos-engineering-fis-noop-stop"
  }
}

# ---------------------------------------------------------------------------
# IAM Role for FIS experiments
# ---------------------------------------------------------------------------
resource "aws_iam_role" "fis" {
  name = "chaos-engineering-fis-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "fis.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "chaos-engineering-fis-role"
  }
}

resource "aws_iam_role_policy" "fis" {
  name = "chaos-engineering-fis-policy"
  role = aws_iam_role.fis.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "FISEC2Describe"
        Effect = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeVolumes",
          "ec2:DescribeImages",
          "ec2:DescribeSubnets",
          "ec2:DescribeNetworkAcls",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeVpcs"
        ]
        Resource = "*"
      },
      {
        Sid    = "FISEC2Modify"
        Effect = "Allow"
        Action = [
          "ec2:TerminateInstances",
          "ec2:StopInstances",
          "ec2:ModifyVolume"
        ]
        Resource = "*"
      },
      {
        Sid    = "FISNetwork"
        Effect = "Allow"
        Action = [
          "ec2:CreateNetworkAclEntry",
          "ec2:ReplaceNetworkAclEntry",
          "ec2:DeleteNetworkAclEntry"
        ]
        Resource = "*"
      },
      {
        Sid    = "FISSSM"
        Effect = "Allow"
        Action = [
          "ssm:SendCommand",
          "ssm:StartAutomationExecution",
          "ssm:CancelCommand"
        ]
        Resource = "*"
      },
      {
        Sid    = "FISApiFault"
        Effect = "Allow"
        Action = [
          "fis:InjectApiInternalError",
          "ec2:DescribeImages"
        ]
        Resource = "*"
      },
      {
        Sid    = "FISIamPassRole"
        Effect = "Allow"
        Action = [
          "iam:PassRole"
        ]
        Resource = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:role/chaos-engineering-fis-role"
      },
      {
        Sid    = "FISS3Logging"
        Effect = "Allow"
        Action = [
          "s3:PutObject"
        ]
        Resource = "${aws_s3_bucket.fis_logs.arn}/*"
      },
      {
        Sid    = "FISKMS"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyPair",
          "kms:DescribeKey"
        ]
        Resource = aws_kms_key.fis_logs.arn
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# FIS Experiment Template: API-level internal error against DescribeImages
# Targets the FIS execution role so that calls made by that role to
# EC2 DescribeImages return an internal error.
# ---------------------------------------------------------------------------
resource "aws_fis_experiment_template" "api_internal_error" {
  description = "Inject InternalError fault into EC2 DescribeImages API via FIS role"
  role_arn    = aws_iam_role.fis.arn

  stop_condition {
    source = "aws:cloudwatch:alarm"
    value  = aws_cloudwatch_metric_alarm.fis_noop_stop.arn
  }

  target {
    name           = "FisRole"
    resource_type  = "aws:iam:role"
    selection_mode = "ALL"
    resource_arns  = [aws_iam_role.fis.arn]
  }

  action {
    name      = "InternalErrorDescribeImages"
    action_id = "aws:fis:inject-api-internal-error"

    parameter {
      key   = "duration"
      value = "PT1M"
    }

    parameter {
      key   = "service"
      value = "ec2"
    }

    parameter {
      key   = "operations"
      value = "DescribeImages"
    }

    parameter {
      key   = "percentage"
      value = "100"
    }

    target {
      key   = "Roles"
      value = "FisRole"
    }
  }

  log_configuration {
    log_schema_version = 2
    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.id
      prefix      = "fis-logs/api-internal-error"
    }
    cloudwatch_logs_configuration {
      log_group_arn = "${aws_cloudwatch_log_group.fis.arn}:*"
    }
  }

  tags = {
    Name = "chaos-engineering-api-internal-error"
  }
}

# ---------------------------------------------------------------------------
# FIS Experiment Template: EBS Volume I/O Pause
# ---------------------------------------------------------------------------
resource "aws_fis_experiment_template" "ebs_pause_io" {
  description = "Pause I/O on EBS volumes tagged ChaosTarget=enabled"
  role_arn    = aws_iam_role.fis.arn

  stop_condition {
    source = "aws:cloudwatch:alarm"
    value  = aws_cloudwatch_metric_alarm.fis_noop_stop.arn
  }

  target {
    name           = "Volumes"
    resource_type  = "aws:ec2:ebs-volume"
    selection_mode = "ALL"
    resource_tag {
      key   = "ChaosTarget"
      value = "enabled"
    }
  }

  action {
    name      = "PauseVolumeIO"
    action_id = "aws:ebs:pause-volume-io"

    parameter {
      key   = "duration"
      value = "PT1M"
    }

    target {
      key   = "Volumes"
      value = "Volumes"
    }
  }

  log_configuration {
    log_schema_version = 2
    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.id
      prefix      = "fis-logs/ebs-pause-io"
    }
    cloudwatch_logs_configuration {
      log_group_arn = "${aws_cloudwatch_log_group.fis.arn}:*"
    }
  }

  tags = {
    Name = "chaos-engineering-ebs-pause-io"
  }
}

# ---------------------------------------------------------------------------
# FIS Experiment Template: EC2 CPU Stress via SSM
# ---------------------------------------------------------------------------
resource "aws_fis_experiment_template" "ec2_cpu_stress" {
  description = "Inject CPU stress on EC2 instances tagged ChaosTarget=enabled"
  role_arn    = aws_iam_role.fis.arn

  stop_condition {
    source = "aws:cloudwatch:alarm"
    value  = aws_cloudwatch_metric_alarm.fis_noop_stop.arn
  }

  target {
    name           = "Instances"
    resource_type  = "aws:ec2:instance"
    selection_mode = "ALL"
    resource_tag {
      key   = "ChaosTarget"
      value = "enabled"
    }
  }

  action {
    name      = "CPUStress"
    action_id = "aws:ssm:send-command"

    parameter {
      key   = "documentArn"
      value = "arn:${data.aws_partition.current.partition}:ssm:${data.aws_region.current.region}::document/AWSFIS-Run-CPU-Stress"
    }

    parameter {
      key   = "duration"
      value = "PT1M"
    }

    target {
      key   = "Instances"
      value = "Instances"
    }
  }

  log_configuration {
    log_schema_version = 2
    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.id
      prefix      = "fis-logs/cpu-stress"
    }
    cloudwatch_logs_configuration {
      log_group_arn = "${aws_cloudwatch_log_group.fis.arn}:*"
    }
  }

  tags = {
    Name = "chaos-engineering-cpu-stress"
  }
}

# ---------------------------------------------------------------------------
# FIS Experiment Template: EC2 Instance Termination
# ---------------------------------------------------------------------------
resource "aws_fis_experiment_template" "ec2_terminate" {
  description = "Terminate EC2 instances tagged ChaosTarget=enabled"
  role_arn    = aws_iam_role.fis.arn

  stop_condition {
    source = "aws:cloudwatch:alarm"
    value  = aws_cloudwatch_metric_alarm.fis_noop_stop.arn
  }

  target {
    name           = "Instances"
    resource_type  = "aws:ec2:instance"
    selection_mode = "ALL"
    resource_tag {
      key   = "ChaosTarget"
      value = "enabled"
    }
  }

  action {
    name      = "TerminateInstances"
    action_id = "aws:ec2:terminate-instances"

    target {
      key   = "Instances"
      value = "Instances"
    }
  }

  log_configuration {
    log_schema_version = 2
    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.id
      prefix      = "fis-logs/instance-termination"
    }
    cloudwatch_logs_configuration {
      log_group_arn = "${aws_cloudwatch_log_group.fis.arn}:*"
    }
  }

  tags = {
    Name = "chaos-engineering-instance-termination"
  }
}

# ---------------------------------------------------------------------------
# FIS Experiment Template: Network Connectivity Disruption on Subnet
# ---------------------------------------------------------------------------
resource "aws_fis_experiment_template" "network_disruption" {
  description = "Disrupt network connectivity on subnets tagged ChaosTarget=enabled"
  role_arn    = aws_iam_role.fis.arn

  stop_condition {
    source = "aws:cloudwatch:alarm"
    value  = aws_cloudwatch_metric_alarm.fis_noop_stop.arn
  }

  target {
    name           = "Subnets"
    resource_type  = "aws:ec2:subnet"
    selection_mode = "ALL"
    resource_tag {
      key   = "ChaosTarget"
      value = "enabled"
    }
  }

  action {
    name      = "NetworkDisruption"
    action_id = "aws:network:disrupt-connectivity"

    parameter {
      key   = "duration"
      value = "PT1M"
    }

    parameter {
      key   = "scope"
      value = "all"
    }

    target {
      key   = "Subnets"
      value = "Subnets"
    }
  }

  log_configuration {
    log_schema_version = 2
    s3_configuration {
      bucket_name = aws_s3_bucket.fis_logs.id
      prefix      = "fis-logs/network-disruption"
    }
    cloudwatch_logs_configuration {
      log_group_arn = "${aws_cloudwatch_log_group.fis.arn}:*"
    }
  }

  tags = {
    Name = "chaos-engineering-network-disruption"
  }
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------
output "ssh_private_key" {
  description = "SSH private key for accessing EC2 instances"
  value       = tls_private_key.ssh.private_key_pem
  sensitive   = true
}

output "fis_experiment_templates" {
  description = "Map of FIS experiment template IDs"
  value = {
    api_internal_error = aws_fis_experiment_template.api_internal_error.id
    ebs_pause_io       = aws_fis_experiment_template.ebs_pause_io.id
    cpu_stress         = aws_fis_experiment_template.ec2_cpu_stress.id
    ec2_terminate      = aws_fis_experiment_template.ec2_terminate.id
    network_disruption = aws_fis_experiment_template.network_disruption.id
  }
}

output "fis_log_bucket" {
  description = "S3 bucket name for FIS experiment logs"
  value       = aws_s3_bucket.fis_logs.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------

variable "server_name" {
  description = "Explicit server identifier. Falls back to a random two-word pet name if empty."
  type        = string
  default     = ""
}

variable "endpoint_type" {
  description = "Server endpoint type: PUBLIC, VPC, or VPC_ENDPOINT."
  type        = string
  default     = "PUBLIC"
  validation {
    condition     = contains(["PUBLIC", "VPC", "VPC_ENDPOINT"], var.endpoint_type)
    error_message = "endpoint_type must be PUBLIC, VPC, or VPC_ENDPOINT."
  }
}

variable "logging_role_arn" {
  description = "ARN of an existing IAM logging role. If empty a role is provisioned dynamically."
  type        = string
  default     = ""
}

variable "vpc_id" {
  description = "VPC ID for VPC or VPC_ENDPOINT endpoint types."
  type        = string
  default     = ""
}

variable "subnet_ids" {
  description = "Subnet IDs for VPC-hosted endpoints."
  type        = list(string)
  default     = []
}

variable "security_policy_name" {
  description = "Security policy applied to the Transfer server."
  type        = string
  default     = "TransferSecurityPolicy-2023-05"
}

variable "host_key" {
  description = "SSH host private key content."
  type        = string
  default     = null
  sensitive   = true
}

variable "login_banner" {
  description = "Pre-authentication login banner text."
  type        = string
  default     = null
  sensitive   = true
}

variable "cloudwatch_log_group_arn" {
  description = "ARN of a CloudWatch log group for structured logging."
  type        = string
  default     = ""
}

variable "ftps_certificate_arn" {
  description = "ARN of an ACM certificate for FTPS."
  type        = string
  default     = ""
}

variable "route53_zone_id" {
  description = "Route53 zone ID for DNS CNAME mapping. Leave empty to skip."
  type        = string
  default     = ""
}

variable "route53_subdomain" {
  description = "Subdomain for the Route53 CNAME record."
  type        = string
  default     = "sftp"
}

variable "enable_api_gateway_auth" {
  description = "When true, provision an API Gateway authorization IAM role with CloudWatch logging permissions."
  type        = bool
  default     = false
}

variable "api_gateway_url" {
  description = "URL of the API Gateway endpoint for Transfer identity provider. Required when enable_api_gateway_auth is true."
  type        = string
  default     = ""
}

variable "users" {
  description = "Map of SFTP users. Key = username, Value = S3 home directory path (e.g. /bucket-name/path)."
  type        = map(string)
  default     = {}
}

variable "user_ssh_keys" {
  description = "Map of SSH public keys keyed by username. Only users present in the users map are processed."
  type        = map(string)
  default     = {}
}

variable "as2_transport_enabled" {
  description = "Enable AS2 transport protocol."
  type        = bool
  default     = false
}

variable "passive_ip" {
  description = "Passive IP address for FTPS/AS2 protocol details."
  type        = string
  default     = ""
}

variable "set_stat_option" {
  description = "Set-stat option for SFTP protocol details."
  type        = string
  default     = ""
}

variable "tls_session_resumption_mode" {
  description = "TLS session resumption mode."
  type        = string
  default     = ""
}

# ---------------------------------------------------------------------------
# Data sources (static provider metadata, no pre-existing infra dependency)
# ---------------------------------------------------------------------------

data "aws_partition" "current" {}

data "aws_region" "current" {}

# ---------------------------------------------------------------------------
# Random pet-name generation
# ---------------------------------------------------------------------------

resource "random_integer" "adjective_index" {
  min = 0
  max = length(local.adjectives) - 1
}

resource "random_integer" "animal_index" {
  min = 0
  max = length(local.animals) - 1
}

locals {
  adjectives = [
    "happy", "swift", "brave", "calm", "eager", "fancy", "gentle",
    "jolly", "keen", "lively", "merry", "noble", "proud", "quiet",
    "witty", "zesty", "amber", "bright", "cosmic", "dandy",
  ]
  animals = [
    "badger", "beaver", "beetle", "coyote", "dragon", "eagle",
    "falcon", "ferret", "gerbil", "giraffe", "heron", "ibex",
    "jaguar", "koala", "lemur", "macaw", "newt", "ocelot",
    "panda", "quokka", "raccoon", "sable", "tiger", "urchin",
    "vixen", "whale", "xerus", "yak", "zebra",
  ]

  generated_name = "${local.adjectives[random_integer.adjective_index.result]}-${local.animals[random_integer.animal_index.result]}"
  resolved_name  = var.server_name != "" ? var.server_name : local.generated_name

  is_vpc              = contains(["VPC", "VPC_ENDPOINT"], var.endpoint_type)
  needs_vpc_resources = local.is_vpc && var.vpc_id != "" && length(var.subnet_ids) > 0
  has_protocol_details = var.as2_transport_enabled || var.passive_ip != "" || var.set_stat_option != "" || var.tls_session_resumption_mode != ""
  has_structured_logging = var.cloudwatch_log_group_arn != ""

  # Build the protocol set – SFTP is always present
  protocols = toset(concat(["SFTP"], var.as2_transport_enabled ? ["AS2"] : [], var.ftps_certificate_arn != "" ? ["FTPS"] : []))

  # Only use SSH key users that are also defined in the users map
  ssh_key_users = { for k, v in var.user_ssh_keys : k => v if contains(keys(var.users), k) }
}

# ---------------------------------------------------------------------------
# IAM role for Transfer logging (provisioned only when no explicit ARN given)
# ---------------------------------------------------------------------------

resource "aws_iam_role" "transfer_logging" {
  count = var.logging_role_arn == "" ? 1 : 0
  name  = "${local.resolved_name}-logging"
  path  = "/transfer/"
  assume_role_policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "transfer.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "transfer_logging" {
  count = var.logging_role_arn == "" ? 1 : 0
  name  = "${local.resolved_name}-logging-policy"
  role  = aws_iam_role.transfer_logging[0].name
  policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:CreateLogGroup",
        ]
        Resource = "arn:${data.aws_partition.current.partition}:logs:*:*:*"
      }
    ]
  })
}

locals {
  logging_role_arn = var.logging_role_arn != "" ? var.logging_role_arn : aws_iam_role.transfer_logging[0].arn
}

# ---------------------------------------------------------------------------
# API Gateway authorization IAM role (when API Gateway auth is enabled)
# ---------------------------------------------------------------------------

resource "aws_iam_role" "api_gateway_auth" {
  count = var.enable_api_gateway_auth ? 1 : 0
  name  = "${local.resolved_name}-api-gateway-auth"
  path  = "/transfer/"
  assume_role_policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "transfer.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "api_gateway_logging" {
  count = var.enable_api_gateway_auth ? 1 : 0
  name  = "${local.resolved_name}-api-gateway-logging"
  role  = aws_iam_role.api_gateway_auth[0].name
  policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
        ]
        Resource = "arn:${data.aws_partition.current.partition}:logs:*:*:*"
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# VPC network resources (created only when needed and not supplied externally)
# ---------------------------------------------------------------------------

# Security group – port 22 open to 0.0.0.0/0
resource "aws_security_group" "transfer" {
  count       = local.needs_vpc_resources ? 1 : 0
  name        = "${local.resolved_name}-sftp"
  description = "Security group for Transfer Family SFTP server ${local.resolved_name}"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${local.resolved_name}-sftp"
  }
}

# One EC2 Elastic IP per specified subnet
resource "aws_eip" "transfer" {
  count  = local.needs_vpc_resources ? length(var.subnet_ids) : 0
  domain = "vpc"

  tags = {
    Name = "${local.resolved_name}-eip-${count.index}"
  }
}

# ---------------------------------------------------------------------------
# Transfer Family server
# ---------------------------------------------------------------------------

resource "aws_transfer_server" "this" {
  endpoint_type                   = var.endpoint_type
  protocols                       = local.protocols
  security_policy_name            = var.security_policy_name
  logging_role                    = local.logging_role_arn
  pre_authentication_login_banner = var.login_banner
  structured_log_destinations     = local.has_structured_logging ? toset([var.cloudwatch_log_group_arn]) : null
  host_key                        = var.host_key
  certificate                     = var.ftps_certificate_arn != "" ? var.ftps_certificate_arn : null
  identity_provider_type          = var.enable_api_gateway_auth ? "API_GATEWAY" : null
  invocation_role                 = var.enable_api_gateway_auth ? aws_iam_role.api_gateway_auth[0].arn : null
  url                             = var.enable_api_gateway_auth && var.api_gateway_url != "" ? var.api_gateway_url : null

  tags = {
    Name          = local.resolved_name
    EndpointType  = var.endpoint_type
  }

  dynamic "endpoint_details" {
    for_each = local.is_vpc && var.vpc_id != "" ? [true] : []
    content {
      vpc_id             = var.vpc_id
      subnet_ids         = var.subnet_ids
      security_group_ids = local.needs_vpc_resources ? toset([aws_security_group.transfer[0].id]) : null
    }
  }

  dynamic "protocol_details" {
    for_each = local.has_protocol_details ? [true] : []
    content {
      as2_transports              = var.as2_transport_enabled ? toset(["HTTP"]) : null
      passive_ip                  = var.passive_ip != "" ? var.passive_ip : null
      set_stat_option             = var.set_stat_option != "" ? var.set_stat_option : null
      tls_session_resumption_mode = var.tls_session_resumption_mode != "" ? var.tls_session_resumption_mode : null
    }
  }

  s3_storage_options {
    directory_listing_optimization = "ENABLED"
  }
}

# ---------------------------------------------------------------------------
# Route53 CNAME record
# ---------------------------------------------------------------------------

resource "aws_route53_record" "transfer" {
  count   = var.route53_zone_id != "" ? 1 : 0
  zone_id = var.route53_zone_id
  name    = "${var.route53_subdomain}.${data.aws_region.current.name}.${data.aws_partition.current.partition}"
  type    = "CNAME"
  ttl     = 300
  records = [aws_transfer_server.this.endpoint]
}

# ---------------------------------------------------------------------------
# Per-user IAM roles, Transfer users, and SSH keys
# ---------------------------------------------------------------------------

# IAM role for each SFTP user
resource "aws_iam_role" "sftp_user" {
  for_each = var.users
  name     = "${local.resolved_name}-${each.key}"
  path     = "/transfer/users/"
  assume_role_policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "transfer.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

# IAM policy granting the user S3 list and object access to their home directory
resource "aws_iam_role_policy" "sftp_user" {
  for_each = var.users
  name     = "${local.resolved_name}-${each.key}-policy"
  role     = aws_iam_role.sftp_user[each.key].name
  policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:ListBucketVersions",
          "s3:ListBucketMultipartUploads",
        ]
        Resource = "arn:${data.aws_partition.current.partition}:s3:::${trimprefix(each.value, "/")}"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:AbortMultipartUpload",
          "s3:ListMultipartUploadParts",
        ]
        Resource = "arn:${data.aws_partition.current.partition}:s3:::${trimprefix(each.value, "/")}/*"
      }
    ]
  })
}

# Transfer user for each entry in the users map
resource "aws_transfer_user" "this" {
  for_each           = var.users
  server_id          = aws_transfer_server.this.id
  user_name          = each.key
  role               = aws_iam_role.sftp_user[each.key].arn
  home_directory     = each.value
  home_directory_type = "PATH"
}

# SSH key for each user that has one in the user_ssh_keys map
resource "aws_transfer_ssh_key" "this" {
  for_each  = local.ssh_key_users
  server_id = aws_transfer_server.this.id
  user_name = each.key
  body      = each.value
}

variable "cluster_version" {
  description = "Kubernetes version for the EKS cluster"
  type        = string
  default     = "1.31"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs                  = slice(data.aws_availability_zones.available.names, 0, 3)
  cluster_name         = "md-k8s"
  public_subnet_cidrs  = ["192.168.0.0/19", "192.168.32.0/19", "192.168.64.0/19"]
  private_subnet_cidrs = ["192.168.96.0/19", "192.168.128.0/19", "192.168.160.0/19"]
}

# ---------------------------------------------------------------------------
# VPC
# ---------------------------------------------------------------------------
resource "aws_vpc" "this" {
  cidr_block           = "192.168.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "md-k8s-vpc"
  }
}

# ---------------------------------------------------------------------------
# Subnets
# ---------------------------------------------------------------------------
resource "aws_subnet" "public" {
  count             = 3
  vpc_id            = aws_vpc.this.id
  cidr_block        = local.public_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  map_public_ip_on_launch = false

  tags = {
    Name                                 = "md-k8s-public-${local.azs[count.index]}"
    "kubernetes.io/cluster/md-k8s"       = "shared"
    "kubernetes.io/role/elb"             = "1"
  }
}

resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.this.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  map_public_ip_on_launch = false

  tags = {
    Name                                 = "md-k8s-private-${local.azs[count.index]}"
    "kubernetes.io/cluster/md-k8s"       = "shared"
    "kubernetes.io/role/internal-elb"    = "1"
  }
}

# ---------------------------------------------------------------------------
# Internet Gateway & Public Route Table
# ---------------------------------------------------------------------------
resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id

  tags = {
    Name = "md-k8s-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.this.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.this.id
  }

  tags = {
    Name = "md-k8s-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# NAT Gateway (single, in first public subnet)
# ---------------------------------------------------------------------------
resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "md-k8s-nat-eip"
  }
}

resource "aws_nat_gateway" "this" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "md-k8s-nat-gw"
  }

  depends_on = [aws_internet_gateway.this]
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.this.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.this.id
  }

  tags = {
    Name = "md-k8s-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# ---------------------------------------------------------------------------
# DB Subnet Group
# ---------------------------------------------------------------------------
resource "aws_db_subnet_group" "this" {
  name        = "md-k8s-private-subnet-group"
  description = "DB subnet group for md-k8s private subnets"
  subnet_ids  = aws_subnet.private[*].id

  tags = {
    Name = "md-k8s-private-subnet-group"
  }
}

# ---------------------------------------------------------------------------
# KMS Key for envelope encryption of Kubernetes secrets
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "kms_key" {
  statement {
    sid    = "EnableRootPermissions"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowEKSClusterRole"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.cluster.arn]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
      "kms:CreateGrant",
    ]
    resources = ["*"]
  }
}

data "aws_caller_identity" "current" {}

resource "aws_kms_key" "eks" {
  description             = "EKS secrets encryption key for cluster md-k8s"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  policy                  = data.aws_iam_policy_document.kms_key.json
}

resource "aws_kms_alias" "eks" {
  name          = "alias/md-k8s-secrets"
  target_key_id = aws_kms_key.eks.key_id
}

# ---------------------------------------------------------------------------
# IAM Role and Policies for EKS Cluster
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "cluster_assume" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "cluster" {
  name               = "md-k8s-cluster-role"
  assume_role_policy = data.aws_iam_policy_document.cluster_assume.json

  tags = {
    Name = "md-k8s-cluster-role"
  }
}

# AWS-managed policies
resource "aws_iam_role_policy_attachment" "cluster_eks" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.cluster.name
}

resource "aws_iam_role_policy_attachment" "cluster_vpc_rc" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSVPCResourceController"
  role       = aws_iam_role.cluster.name
}

# Custom policy: describe EC2 networking
data "aws_iam_policy_document" "ec2_describe" {
  statement {
    effect = "Allow"
    actions = [
      "ec2:DescribeNetworkInterfaces",
      "ec2:DescribeSubnets",
      "ec2:DescribeSecurityGroups",
      "ec2:DescribeVpcs",
      "ec2:DescribeRouteTables",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "ec2_describe" {
  name        = "md-k8s-ec2-describe-policy"
  description = "Allows EKS to describe EC2 networking"
  policy      = data.aws_iam_policy_document.ec2_describe.json
}

resource "aws_iam_role_policy_attachment" "cluster_ec2_describe" {
  policy_arn = aws_iam_policy.ec2_describe.arn
  role       = aws_iam_role.cluster.name
}

# Custom policy: publish CloudWatch metrics
data "aws_iam_policy_document" "cloudwatch_metrics" {
  statement {
    effect = "Allow"
    actions = [
      "cloudwatch:PutMetricData"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "cloudwatch_metrics" {
  name        = "md-k8s-cloudwatch-metrics-policy"
  description = "Allows EKS to publish CloudWatch metrics"
  policy      = data.aws_iam_policy_document.cloudwatch_metrics.json
}

resource "aws_iam_role_policy_attachment" "cluster_cloudwatch_metrics" {
  policy_arn = aws_iam_policy.cloudwatch_metrics.arn
  role       = aws_iam_role.cluster.name
}

# ---------------------------------------------------------------------------
# Security Groups
# ---------------------------------------------------------------------------
resource "aws_security_group" "control_plane" {
  name        = "md-k8s-control-plane-sg"
  description = "Security group for md-k8s EKS control plane"
  vpc_id      = aws_vpc.this.id

  tags = {
    Name = "md-k8s-control-plane-sg"
  }
}

resource "aws_security_group" "node" {
  name        = "md-k8s-node-sg"
  description = "Shared security group for md-k8s worker nodes"
  vpc_id      = aws_vpc.this.id

  tags = {
    Name = "md-k8s-node-sg"
  }
}

# Node SG: allow all traffic from itself (node-to-node)
resource "aws_vpc_security_group_ingress_rule" "node_self" {
  security_group_id = aws_security_group.node.id
  referenced_security_group_id = aws_security_group.node.id
  from_port   = 0
  to_port     = 0
  ip_protocol = "-1"
}

# Node SG: allow all traffic from control plane SG
resource "aws_vpc_security_group_ingress_rule" "node_from_control_plane" {
  security_group_id = aws_security_group.node.id
  referenced_security_group_id = aws_security_group.control_plane.id
  from_port   = 0
  to_port     = 0
  ip_protocol = "-1"
}

# Control plane SG: allow HTTPS from node SG
resource "aws_vpc_security_group_ingress_rule" "cp_from_node" {
  security_group_id = aws_security_group.control_plane.id
  referenced_security_group_id = aws_security_group.node.id
  from_port   = 443
  to_port     = 443
  ip_protocol = "tcp"
}

# Node SG outbound: limited to VPC CIDR
resource "aws_vpc_security_group_egress_rule" "node_to_vpc" {
  security_group_id = aws_security_group.node.id
  cidr_ipv4         = aws_vpc.this.cidr_block
  from_port   = 0
  to_port     = 0
  ip_protocol = "-1"
}

# Control plane SG outbound: limited to VPC CIDR
resource "aws_vpc_security_group_egress_rule" "cp_to_vpc" {
  security_group_id = aws_security_group.control_plane.id
  cidr_ipv4         = aws_vpc.this.cidr_block
  from_port   = 0
  to_port     = 0
  ip_protocol = "-1"
}

# ---------------------------------------------------------------------------
# EKS Cluster
# ---------------------------------------------------------------------------
resource "aws_eks_cluster" "this" {
  name     = local.cluster_name
  role_arn = aws_iam_role.cluster.arn
  version  = var.cluster_version

  vpc_config {
    subnet_ids              = concat(aws_subnet.public[*].id, aws_subnet.private[*].id)
    security_group_ids      = [aws_security_group.control_plane.id]
    endpoint_private_access = true
    endpoint_public_access  = false
  }

  encryption_config {
    resources = ["secrets"]
    provider {
      key_arn = aws_kms_key.eks.arn
    }
  }

  depends_on = [
    aws_iam_role_policy_attachment.cluster_eks,
    aws_iam_role_policy_attachment.cluster_vpc_rc,
    aws_iam_role_policy_attachment.cluster_ec2_describe,
    aws_iam_role_policy_attachment.cluster_cloudwatch_metrics,
  ]

  tags = {
    Name = "md-k8s"
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# TERRAFORM & PROVIDER CONFIGURATION
# ---------------------------------------------------------------------------------------------------------------------

terraform {
  required_version = ">= 1.3"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

resource "random_id" "this" {
  byte_length = 4
}

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------

variable "namespace" {
  description = "Namespace (e.g., org or project name)"
  type        = string
  default     = ""
}

variable "environment" {
  description = "Environment (e.g., dev, prod, staging)"
  type        = string
  default     = ""
}

variable "name" {
  description = "Solution/application name"
  type        = string
  default     = "s3-bucket"
}

variable "attributes" {
  description = "Additional attributes for naming (e.g., [\"app\", \"data\"])"
  type        = list(string)
  default     = []
}

variable "delimiter" {
  description = "Delimiter between naming components"
  type        = string
  default     = "-"
}

variable "tags" {
  description = "Additional tags (merged with auto-generated tags)"
  type        = map(string)
  default     = {}
}

variable "force_destroy" {
  description = "Allow bucket deletion even when it contains objects"
  type        = bool
  default     = false
}

# -- ACL

variable "acl" {
  description = "Canned ACL to apply (e.g., private, public-read, public-read-write, aws-exec-read, authenticated-read, log-delivery-write)"
  type        = string
  default     = null
}

variable "grants" {
  description = "ACL grant entries"
  type = list(object({
    id          = optional(string)
    type        = string
    permissions = list(string)
    uri         = optional(string)
  }))
  default = []
}

# -- Versioning

variable "versioning_enabled" {
  description = "Enable S3 bucket versioning"
  type        = bool
  default     = true
}

# -- Encryption

variable "enable_kms" {
  description = "Enable KMS-SSE (aws:kms). When false, AES256 is used."
  type        = bool
  default     = true
}

variable "kms_key_id" {
  description = "ARN of an existing KMS key to use. If null a new customer-managed key is created."
  type        = string
  default     = null
}

variable "kms_key_deletion_window_in_days" {
  description = "Waiting period before the KMS key is destroyed (7-30)"
  type        = number
  default     = 30
}

# -- Lifecycle

variable "lifecycle_rules" {
  description = <<-EOT
    List of lifecycle rules. Each rule can specify:
    - id (required): unique identifier
    - enabled (required): true/false
    - prefix: object key prefix filter
    - tags: map of tag key-value pairs for filtering
    - abort_incomplete_multipart_upload_days: days after initiation to abort
    - transitions: list of { days, storage_class } for current versions
    - expiration: { days, expired_object_delete_marker }
    - noncurrent_version_transitions: list of { days, storage_class }
    - noncurrent_version_expiration: { days }
  EOT
  type = list(object({
    id                                     = string
    enabled                                = bool
    prefix                                 = optional(string)
    tags                                   = optional(map(string))
    abort_incomplete_multipart_upload_days = optional(number)
    transitions = optional(list(object({
      days          = number
      storage_class = string
    })), [])
    expiration = optional(object({
      days                         = optional(number)
      expired_object_delete_marker = optional(bool)
    }))
    noncurrent_version_transitions = optional(list(object({
      days          = number
      storage_class = string
    })), [])
    noncurrent_version_expiration = optional(object({
      days = number
    }))
  }))
  default  = []
  nullable = false
}

# -- Logging

variable "enable_logging" {
  description = "Enable S3 access logging to a separate target bucket"
  type        = bool
  default     = false
}

variable "logging_target_bucket" {
  description = "Name of an existing target bucket for logs. If null, a logging bucket is created."
  type        = string
  default     = null
}

variable "logging_prefix" {
  description = "Prefix for log objects in the target bucket"
  type        = string
  default     = "logs/"
}

# -- Static Website

variable "enable_website" {
  description = "Enable static website hosting"
  type        = bool
  default     = false
}

variable "website_index_document" {
  description = "Index document (e.g., index.html)"
  type        = string
  default     = "index.html"
}

variable "website_error_document" {
  description = "Error document (e.g., error.html)"
  type        = string
  default     = "error.html"
}

variable "website_routing_rules" {
  description = "Routing rules for the website"
  type = list(object({
    condition = object({
      key_prefix_equals               = optional(string)
      http_error_code_returned_equals = optional(string)
    })
    redirect = object({
      protocol                = optional(string)
      host_name               = optional(string)
      http_redirect_code      = optional(string)
      replace_key_prefix_with = optional(string)
      replace_key_with        = optional(string)
    })
  }))
  default = []
}

# -- CORS

variable "cors_rules" {
  description = "CORS rules for the bucket"
  type = list(object({
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default  = []
  nullable = false
}

# -- Object Lock

variable "enable_object_lock" {
  description = "Enable S3 Object Lock (requires versioning)"
  type        = bool
  default     = false
}

variable "object_lock_mode" {
  description = "Default retention mode: GOVERNANCE or COMPLIANCE"
  type        = string
  default     = "GOVERNANCE"
}

variable "object_lock_retention_days" {
  description = "Default retention period in days for object lock"
  type        = number
  default     = 30
}

# -- Bucket Policy

variable "bucket_policy" {
  description = <<-EOT
    JSON-formatted bucket policy. If null, no policy is attached.
    The placeholders {bucket_arn} and {bucket_name} are replaced with the
    actual bucket ARN and name before the policy is attached.
  EOT
  type        = string
  default     = null
}

# -- Acceleration

variable "enable_acceleration" {
  description = "Enable S3 Transfer Acceleration"
  type        = bool
  default     = false
}

# -- Requester Pays

variable "requester_pays" {
  description = "Enable requester pays"
  type        = bool
  default     = false
}

# ---------------------------------------------------------------------------------------------------------------------
# LOCALS (Label Module Replacement)
# ---------------------------------------------------------------------------------------------------------------------

locals {
  # Construct the bucket name from namespace, environment, name, attributes, and a random suffix
  name = join(var.delimiter, compact([
    var.namespace,
    var.environment,
    var.name,
    join(var.delimiter, var.attributes),
    random_id.this.hex,
  ]))

  # Merge user-provided tags with auto-generated ones
  tags = merge(var.tags, {
    Name = local.name
  }, var.namespace != "" ? { Namespace = var.namespace } : {}, var.environment != "" ? { Environment = var.environment } : {})

  # -- KMS helpers
  create_kms_key = var.enable_kms && var.kms_key_id == null
  kms_key_arn    = var.enable_kms ? (var.kms_key_id != null ? var.kms_key_id : try(aws_kms_key.this[0].arn, null)) : null

  # -- Logging helpers
  create_logging_bucket = var.enable_logging && var.logging_target_bucket == null
  logging_target        = local.create_logging_bucket ? try(aws_s3_bucket.logging[0].id, null) : var.logging_target_bucket

  # -- Object Lock requires versioning
  enable_object_lock = var.enable_object_lock && var.versioning_enabled

  # -- Flatten ACL grants into one entry per permission
  acl_grants = flatten([
    for grant in var.grants : [
      for permission in grant.permissions : {
        id         = try(grant.id, null)
        type       = grant.type
        uri        = try(grant.uri, null)
        permission = permission
      }
    ]
  ])
}

# ---------------------------------------------------------------------------------------------------------------------
# KMS KEY (created only when enable_kms = true and kms_key_id = null)
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_kms_key" "this" {
  count                   = local.create_kms_key ? 1 : 0
  description             = "${local.name} S3 encryption key"
  deletion_window_in_days = var.kms_key_deletion_window_in_days
  enable_key_rotation     = true
  tags                    = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "this" {
  count         = local.create_kms_key ? 1 : 0
  name          = "alias/${local.name}"
  target_key_id = try(aws_kms_key.this[0].key_id, null)
}

# ---------------------------------------------------------------------------------------------------------------------
# LOGGING BUCKET (created only when logging is enabled and no external target is provided)
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_s3_bucket" "logging" {
  count         = local.create_logging_bucket ? 1 : 0
  bucket        = "${local.name}-logs"
  force_destroy = var.force_destroy
  tags          = merge(local.tags, { Name = "${local.name}-logs" })

  lifecycle {
    prevent_destroy = true
  }
}

# The logging bucket must accept writes from the S3 log delivery service.
# ACLs are required for this, so disable BucketOwnerEnforced and grant log-delivery-write.
resource "aws_s3_bucket_ownership_controls" "logging" {
  count  = local.create_logging_bucket ? 1 : 0
  bucket = aws_s3_bucket.logging[0].id

  rule {
    object_ownership = "ObjectWriter"
  }
}

resource "aws_s3_bucket_acl" "logging" {
  count      = local.create_logging_bucket ? 1 : 0
  bucket     = aws_s3_bucket.logging[0].id
  acl        = "log-delivery-write"
  depends_on = [aws_s3_bucket_ownership_controls.logging]
}

resource "aws_s3_bucket_public_access_block" "logging" {
  count                   = local.create_logging_bucket ? 1 : 0
  bucket                  = aws_s3_bucket.logging[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "logging" {
  count  = local.create_logging_bucket ? 1 : 0
  bucket = aws_s3_bucket.logging[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logging" {
  count  = local.create_logging_bucket ? 1 : 0
  bucket = aws_s3_bucket.logging[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# MAIN S3 BUCKET
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_s3_bucket" "this" {
  bucket              = local.name
  force_destroy       = var.force_destroy
  object_lock_enabled = local.enable_object_lock
  tags                = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

# Object ownership controls: ACLs require an ownership mode other than BucketOwnerEnforced.
# - When canned ACL or grants are requested -> ObjectWriter enables ACLs on the bucket.
# - Otherwise the bucket keeps the secure default (BucketOwnerEnforced) which disables ACLs.
resource "aws_s3_bucket_ownership_controls" "this" {
  count  = (var.acl != null || length(var.grants) > 0) ? 1 : 0
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = "ObjectWriter"
  }
}

# -------------------------------
# Public Access Block (always)
# -------------------------------

resource "aws_s3_bucket_public_access_block" "this" {
  bucket                  = aws_s3_bucket.this.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# -------------------------------
# Versioning
# -------------------------------

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = var.versioning_enabled ? "Enabled" : "Suspended"
  }
}

# -------------------------------
# Server-Side Encryption
# -------------------------------

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.enable_kms ? "aws:kms" : "AES256"
      kms_master_key_id = var.enable_kms ? local.kms_key_arn : null
    }
  }
}

# -------------------------------
# Lifecycle Configuration
# -------------------------------

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count  = length(var.lifecycle_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = rule.value.enabled ? "Enabled" : "Disabled"

      filter {
        # When both prefix and tags are set, use an "and" block (tags attribute is a map)
        dynamic "and" {
          for_each = (rule.value.prefix != null && length(coalesce(rule.value.tags, {})) > 0) ? [1] : []
          content {
            prefix = rule.value.prefix
            tags   = rule.value.tags
          }
        }

        # Pure prefix filter (no tags)
        prefix = (rule.value.prefix != null && length(coalesce(rule.value.tags, {})) == 0) ? rule.value.prefix : null

        # Pure tag filter (no prefix) - tag blocks for each tag entry
        dynamic "tag" {
          for_each = (rule.value.prefix == null ? coalesce(rule.value.tags, {}) : {})
          content {
            key   = tag.key
            value = tag.value
          }
        }
      }

      dynamic "transition" {
        for_each = try(rule.value.transitions, [])
        content {
          days          = transition.value.days
          storage_class = transition.value.storage_class
        }
      }

      dynamic "expiration" {
        for_each = try(rule.value.expiration, null) != null ? [rule.value.expiration] : []
        content {
          days                         = try(expiration.value.days, null)
          expired_object_delete_marker = try(expiration.value.expired_object_delete_marker, null)
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = try(rule.value.noncurrent_version_transitions, [])
        content {
          noncurrent_days = noncurrent_version_transition.value.days
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = try(rule.value.noncurrent_version_expiration, null) != null ? [rule.value.noncurrent_version_expiration] : []
        content {
          noncurrent_days = noncurrent_version_expiration.value.days
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = try(rule.value.abort_incomplete_multipart_upload_days, null) != null ? [rule.value.abort_incomplete_multipart_upload_days] : []
        content {
          days_after_initiation = abort_incomplete_multipart_upload.value
        }
      }
    }
  }
}

# -------------------------------
# Bucket Logging
# -------------------------------

resource "aws_s3_bucket_logging" "this" {
  count  = var.enable_logging ? 1 : 0
  bucket = aws_s3_bucket.this.id

  target_bucket = local.logging_target
  target_prefix = var.logging_prefix
}

# -------------------------------
# Static Website Hosting
# -------------------------------

resource "aws_s3_bucket_website_configuration" "this" {
  count  = var.enable_website ? 1 : 0
  bucket = aws_s3_bucket.this.id

  index_document {
    suffix = var.website_index_document
  }

  error_document {
    key = var.website_error_document
  }

  dynamic "routing_rule" {
    for_each = var.website_routing_rules
    content {
      condition {
        key_prefix_equals               = try(routing_rule.value.condition.key_prefix_equals, null)
        http_error_code_returned_equals = try(routing_rule.value.condition.http_error_code_returned_equals, null)
      }
      redirect {
        protocol                = try(routing_rule.value.redirect.protocol, null)
        host_name               = try(routing_rule.value.redirect.host_name, null)
        http_redirect_code      = try(routing_rule.value.redirect.http_redirect_code, null)
        replace_key_prefix_with = try(routing_rule.value.redirect.replace_key_prefix_with, null)
        replace_key_with        = try(routing_rule.value.redirect.replace_key_with, null)
      }
    }
  }
}

# -------------------------------
# CORS Configuration
# -------------------------------

resource "aws_s3_bucket_cors_configuration" "this" {
  count  = length(var.cors_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = try(cors_rule.value.allowed_headers, null)
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

# -------------------------------
# Object Lock Configuration
# -------------------------------

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count  = local.enable_object_lock ? 1 : 0
  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode = var.object_lock_mode
      days = var.object_lock_retention_days
    }
  }
}

# -------------------------------
# Bucket Policy
# -------------------------------

resource "aws_s3_bucket_policy" "this" {
  count  = var.bucket_policy != null ? 1 : 0
  bucket = aws_s3_bucket.this.id
  policy = replace(
    replace(var.bucket_policy, "{bucket_arn}", aws_s3_bucket.this.arn),
    "{bucket_name}",
    aws_s3_bucket.this.id,
  )
}

# -------------------------------
# Transfer Acceleration
# -------------------------------

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count  = var.enable_acceleration ? 1 : 0
  bucket = aws_s3_bucket.this.id
  status = "Enabled"
}

# -------------------------------
# Requester Pays
# -------------------------------

resource "aws_s3_bucket_request_payment_configuration" "this" {
  count  = var.requester_pays ? 1 : 0
  bucket = aws_s3_bucket.this.id
  payer  = "Requester"
}

# -------------------------------
# ACL
# -------------------------------

resource "aws_s3_bucket_acl" "this" {
  count  = (var.acl != null) || length(var.grants) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id
  acl    = var.acl

  depends_on = [aws_s3_bucket_ownership_controls.this]

  dynamic "access_control_policy" {
    for_each = length(var.grants) > 0 ? [1] : []
    content {
      dynamic "grant" {
        for_each = local.acl_grants
        content {
          grantee {
            id   = try(grant.value.id, null)
            type = grant.value.type
            uri  = try(grant.value.uri, null)
          }
          permission = grant.value.permission
        }
      }
      owner {
        id = data.aws_canonical_user_id.this.id
      }
    }
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# DATA SOURCES (static metadata only)
# ---------------------------------------------------------------------------------------------------------------------

data "aws_canonical_user_id" "this" {}

# ---------------------------------------------------------------------------------------------------------------------
# OUTPUTS
# ---------------------------------------------------------------------------------------------------------------------

output "bucket_id" {
  description = "Bucket ID (name)"
  value       = aws_s3_bucket.this.id
}

output "bucket_arn" {
  description = "Bucket ARN"
  value       = aws_s3_bucket.this.arn
}

output "bucket_domain_name" {
  description = "Bucket domain name"
  value       = aws_s3_bucket.this.bucket_domain_name
}

output "bucket_regional_domain_name" {
  description = "Bucket regional domain name"
  value       = aws_s3_bucket.this.bucket_regional_domain_name
}

output "tags" {
  description = "Resource tags"
  value       = aws_s3_bucket.this.tags_all
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
  }
}

variable "vpc_name" {
  description = "Name tag for the VPC"
  type        = string
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/18"
}

variable "availability_zones" {
  description = "List of availability zones to use. Defaults to all AZs in the region."
  type        = list(string)
  default     = null
}

variable "create_public_subnets" {
  description = "Whether to create public subnets"
  type        = bool
  default     = true
}

variable "create_private_subnets" {
  description = "Whether to create private subnets"
  type        = bool
  default     = true
}

variable "create_nat_gateway" {
  description = "Whether to create a NAT gateway for private subnets"
  type        = bool
  default     = true
}

variable "private_subnet_tags" {
  description = "Additional tags for private subnets"
  type        = map(string)
  default     = {}
}

variable "public_subnet_tags" {
  description = "Additional tags for public subnets"
  type        = map(string)
  default     = {}
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs = var.availability_zones != null ? var.availability_zones : data.aws_availability_zones.available.names

  # Compute the subnet CIDR blocks
  # VPC is 10.0.0.0/18 (16384 addresses)
  # We split into public and private halves:
  #   Public:  10.0.0.0/19 (8192 addresses) -> /20 subnets per AZ
  #   Private: 10.0.32.0/19 (8192 addresses) -> /20 subnets per AZ
  public_subnet_cidrs = [
    for idx in range(length(local.azs)) :
    cidrsubnet("10.0.0.0/19", 4, idx)
  ]
  private_subnet_cidrs = [
    for idx in range(length(local.azs)) :
    cidrsubnet("10.0.32.0/19", 4, idx)
  ]
}

resource "aws_vpc" "this" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.vpc_name
  }
}

# Internet Gateway
resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id

  tags = {
    Name = "${var.vpc_name}-igw"
  }
}

# Public Subnets
resource "aws_subnet" "public" {
  count = var.create_public_subnets ? length(local.azs) : 0

  vpc_id                  = aws_vpc.this.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(
    {
      Name                                    = "${var.vpc_name}-public-${local.azs[count.index]}"
      "kubernetes.io/role/elb"                = "1"
      "kubernetes.io/cluster/${var.vpc_name}" = "shared"
    },
    var.public_subnet_tags
  )
}

# Private Subnets
resource "aws_subnet" "private" {
  count = var.create_private_subnets ? length(local.azs) : 0

  vpc_id                  = aws_vpc.this.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(
    {
      Name                                    = "${var.vpc_name}-private-${local.azs[count.index]}"
      "kubernetes.io/role/internal-elb"       = "1"
      "kubernetes.io/cluster/${var.vpc_name}" = "shared"
    },
    var.private_subnet_tags
  )
}

# Public Route Table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.this.id

  tags = {
    Name = "${var.vpc_name}-public"
  }
}

resource "aws_route" "public_internet_access" {
  count = var.create_public_subnets ? 1 : 0

  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this.id
}

resource "aws_route_table_association" "public" {
  count = var.create_public_subnets ? length(local.azs) : 0

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# NAT Gateway (Elastic IP + NAT Gateway in the first public subnet)
resource "aws_eip" "nat" {
  count = var.create_nat_gateway && var.create_public_subnets ? 1 : 0

  domain = "vpc"

  tags = {
    Name = "${var.vpc_name}-nat"
  }
}

resource "aws_nat_gateway" "this" {
  count = var.create_nat_gateway && var.create_public_subnets ? 1 : 0

  allocation_id = aws_eip.nat[0].id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "${var.vpc_name}-nat"
  }

  depends_on = [aws_internet_gateway.this]
}

# Private Route Table
resource "aws_route_table" "private" {
  count = var.create_private_subnets ? 1 : 0

  vpc_id = aws_vpc.this.id

  tags = {
    Name = "${var.vpc_name}-private"
  }
}

resource "aws_route" "private_nat_access" {
  count = var.create_nat_gateway && var.create_private_subnets ? 1 : 0

  route_table_id         = aws_route_table.private[0].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.this[0].id
}

resource "aws_route_table_association" "private" {
  count = var.create_private_subnets ? length(local.azs) : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[0].id
}

# Network ACLs
resource "aws_network_acl" "public" {
  count = var.create_public_subnets ? 1 : 0

  vpc_id = aws_vpc.this.id
  subnet_ids = [for s in aws_subnet.public : s.id]

  tags = {
    Name = "${var.vpc_name}-public-nacl"
  }
}

resource "aws_network_acl_rule" "public_inbound_http" {
  count = var.create_public_subnets ? 1 : 0

  network_acl_id = aws_network_acl.public[0].id
  rule_number    = 100
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 80
  to_port        = 80
}

resource "aws_network_acl_rule" "public_inbound_https" {
  count = var.create_public_subnets ? 1 : 0

  network_acl_id = aws_network_acl.public[0].id
  rule_number    = 110
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 443
  to_port        = 443
}

resource "aws_network_acl_rule" "public_inbound_ephemeral" {
  count = var.create_public_subnets ? 1 : 0

  network_acl_id = aws_network_acl.public[0].id
  rule_number    = 120
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 1024
  to_port        = 65535
}

resource "aws_network_acl_rule" "public_outbound_all" {
  count = var.create_public_subnets ? 1 : 0

  network_acl_id = aws_network_acl.public[0].id
  rule_number    = 100
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 0
  to_port        = 65535
}

resource "aws_network_acl_rule" "public_outbound_udp" {
  count = var.create_public_subnets ? 1 : 0

  network_acl_id = aws_network_acl.public[0].id
  rule_number    = 110
  egress         = true
  protocol       = "udp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 0
  to_port        = 65535
}

resource "aws_network_acl" "private" {
  count = var.create_private_subnets ? 1 : 0

  vpc_id = aws_vpc.this.id
  subnet_ids = [for s in aws_subnet.private : s.id]

  tags = {
    Name = "${var.vpc_name}-private-nacl"
  }
}

resource "aws_network_acl_rule" "private_inbound_vpc_tcp" {
  count = var.create_private_subnets ? 1 : 0

  network_acl_id = aws_network_acl.private[0].id
  rule_number    = 100
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = var.vpc_cidr
  from_port      = 0
  to_port        = 65535
}

resource "aws_network_acl_rule" "private_inbound_vpc_udp" {
  count = var.create_private_subnets ? 1 : 0

  network_acl_id = aws_network_acl.private[0].id
  rule_number    = 110
  egress         = false
  protocol       = "udp"
  rule_action    = "allow"
  cidr_block     = var.vpc_cidr
  from_port      = 0
  to_port        = 65535
}

resource "aws_network_acl_rule" "private_inbound_vpc_icmp" {
  count = var.create_private_subnets ? 1 : 0

  network_acl_id = aws_network_acl.private[0].id
  rule_number    = 120
  egress         = false
  protocol       = "icmp"
  rule_action    = "allow"
  cidr_block     = var.vpc_cidr
  from_port      = 0
  to_port        = 0
}

resource "aws_network_acl_rule" "private_inbound_ephemeral" {
  count = var.create_private_subnets ? 1 : 0

  network_acl_id = aws_network_acl.private[0].id
  rule_number    = 200
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 1024
  to_port        = 65535
}

resource "aws_network_acl_rule" "private_outbound_tcp" {
  count = var.create_private_subnets ? 1 : 0

  network_acl_id = aws_network_acl.private[0].id
  rule_number    = 100
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 0
  to_port        = 65535
}

resource "aws_network_acl_rule" "private_outbound_udp" {
  count = var.create_private_subnets ? 1 : 0

  network_acl_id = aws_network_acl.private[0].id
  rule_number    = 110
  egress         = true
  protocol       = "udp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 0
  to_port        = 65535
}

variable "is_ipv6_enabled" {
  type    = bool
  default = true
}

variable "vpc_cidr" {
  type    = string
  default = "10.16.0.0/16"
}

locals {
  azs = tolist(data.aws_availability_zones.available.names)

  # Subnet topology: 12 subnets across 3 AZs, 4 tiers
  sn_details = [
    # Web (public) subnets
    { name = "web-a",     az = local.azs[0], type = "public" },
    { name = "web-b",     az = local.azs[1], type = "public" },
    { name = "web-c",     az = local.azs[2], type = "public" },
    # App (private) subnets
    { name = "app-a",     az = local.azs[0], type = "private" },
    { name = "app-b",     az = local.azs[1], type = "private" },
    { name = "app-c",     az = local.azs[2], type = "private" },
    # Database (private) subnets
    { name = "database-a", az = local.azs[0], type = "private" },
    { name = "database-b", az = local.azs[1], type = "private" },
    { name = "database-c", az = local.azs[2], type = "private" },
    # Reserved (private) subnets
    { name = "reserved-a", az = local.azs[0], type = "private" },
    { name = "reserved-b", az = local.azs[1], type = "private" },
    { name = "reserved-c", az = local.azs[2], type = "private" },
  ]

  # Build the networks list for the subnets/cidr module (IPv4: /20 subnets = 4 additional bits)
  ipv4_network_defs = [
    for sn in local.sn_details : {
      name     = sn.name
      new_bits = 4
    }
  ]
}

data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------
# VPC
# ---------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr
  assign_generated_ipv6_cidr_block = var.is_ipv6_enabled
  instance_tenancy                 = "default"
  enable_dns_hostnames             = true
  enable_dns_support               = true

  tags = {
    Name = "main-vpc"
  }
}

# ---------------------------------------------------------------------------
# Subnet IPv4 CIDR calculation via hashicorp/subnets/cidr module
# ---------------------------------------------------------------------------
module "ipv4_subnets" {
  source  = "hashicorp/subnets/cidr"
  version = "1.0.0"

  base_cidr_block = aws_vpc.main.cidr_block
  networks        = local.ipv4_network_defs
}

# ---------------------------------------------------------------------------
# Subnets
# ---------------------------------------------------------------------------
resource "aws_subnet" "this" {
  for_each = { for sn in local.sn_details : sn.name => sn }

  vpc_id                          = aws_vpc.main.id
  availability_zone               = each.value.az
  cidr_block                      = module.ipv4_subnets.network_cidr_blocks[each.key]
  ipv6_cidr_block                 = var.is_ipv6_enabled ? cidrsubnets(aws_vpc.main.ipv6_cidr_block, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8)[index(local.sn_details[*].name, each.key)] : null
  map_public_ip_on_launch         = false
  assign_ipv6_address_on_creation = each.value.type == "public" ? true : false

  tags = {
    Name = each.key
    Tier = each.value.type == "public" ? "web" : (
      can(regex("^app", each.key)) ? "app" : (
        can(regex("^database", each.key)) ? "database" : "reserved"
      )
    )
    Type = each.value.type
  }
}

# ---------------------------------------------------------------------------
# Internet Gateway
# ---------------------------------------------------------------------------
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw-vpc-${aws_vpc.main.id}"
  }
}

# ---------------------------------------------------------------------------
# Public route table
# ---------------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  dynamic "route" {
    for_each = var.is_ipv6_enabled ? [1] : []
    content {
      ipv6_cidr_block = "::/0"
      gateway_id      = aws_internet_gateway.main.id
    }
  }

  tags = {
    Name = "public-rt-web"
  }
}

# ---------------------------------------------------------------------------
# Route table associations for public subnets
# ---------------------------------------------------------------------------
resource "aws_route_table_association" "public" {
  for_each = {
    for sn in local.sn_details : sn.name => sn
    if sn.type == "public"
  }

  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# Security Groups (created first without cross-references to break cycles)
# ---------------------------------------------------------------------------
resource "aws_security_group" "web_sg" {
  name        = "web-sg"
  description = "Security group for web tier"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "TLS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "SSH from VPC"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "web-sg"
  }
}

resource "aws_security_group" "app_sg" {
  name        = "app-sg"
  description = "Security group for app tier"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "app-sg"
  }
}

resource "aws_security_group" "db_sg" {
  name        = "db-sg"
  description = "Security group for database tier"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "db-sg"
  }
}

# ---------------------------------------------------------------------------
# Cross-referencing security group rules (separate resources to avoid cycles)
# ---------------------------------------------------------------------------
# web_sg egress: TLS to app_sg
resource "aws_security_group_rule" "web_egress_app" {
  type                     = "egress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.app_sg.id
  security_group_id        = aws_security_group.web_sg.id
  description              = "TLS to app tier"
}

# app_sg ingress: TLS from web_sg
resource "aws_security_group_rule" "app_ingress_web" {
  type                     = "ingress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.web_sg.id
  security_group_id        = aws_security_group.app_sg.id
  description              = "TLS from web tier"
}

# app_sg egress: TLS to db_sg
resource "aws_security_group_rule" "app_egress_db" {
  type                     = "egress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.db_sg.id
  security_group_id        = aws_security_group.app_sg.id
  description              = "TLS to database tier"
}

# db_sg ingress: TLS from app_sg
resource "aws_security_group_rule" "db_ingress_app" {
  type                     = "ingress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.app_sg.id
  security_group_id        = aws_security_group.db_sg.id
  description              = "TLS from app tier"
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws     = { source = "hashicorp/aws" }
    archive = { source = "hashicorp/archive" }
    random  = { source = "hashicorp/random" }
    time    = { source = "hashicorp/time" }
  }
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------

variable "canary_bucket_name" {
  description = "Name of the S3 bucket used to store CloudWatch Synthetics canary artifacts."
  type        = string
  default     = "benchmark-canary-bucket-tf5x"
}

variable "bucket_force_destroy" {
  description = "Allow destructive deletion of the artifacts bucket and its contents."
  type        = bool
  default     = true
}

variable "bucket_versioning_enabled" {
  description = "Enable versioning on the canary artifacts bucket."
  type        = bool
  default     = false
}

variable "enable_custom_kms_key" {
  description = "Toggle provisioning of a customer-managed KMS key. When false, SSE-S3 is used for the bucket."
  type        = bool
  default     = true
}

variable "kms_key_alias" {
  description = "Alias name of the customer-managed KMS key."
  type        = string
  default     = "alias/benchmark-canary-key"
}

variable "kms_deletion_window_in_days" {
  description = "Waiting period before AWS permanently deletes a KMS key."
  type        = number
  default     = 10

  validation {
    condition     = var.kms_deletion_window_in_days >= 7 && var.kms_deletion_window_in_days <= 30
    error_message = "The KMS deletion window must be between 7 and 30 days."
  }
}

variable "sns_topic_name" {
  description = "Name of the SNS topic used for canary failure notifications."
  type        = string
  default     = "benchmark-canary-topic"
}

variable "subscription_email" {
  description = "Email address subscribed to canary failure notifications."
  type        = string
  default     = "nobody@example.com"
}

variable "default_canary_runtime_version" {
  description = "Synthetics runtime version used for canaries that do not override it."
  type        = string
  default     = "syn-nodejs-puppeteer-18.0"
}

variable "default_canary_schedule_expression" {
  description = "CloudWatch Events schedule expression used when a canary does not specify one."
  type        = string
  default     = "rate(30 minutes)"
}

variable "default_canary_memory_in_mb" {
  description = "Lambda memory assigned to canary executions that do not override it."
  type        = number
  default     = 960
}

variable "canary_timeout_in_seconds" {
  description = "Maximum execution time (seconds) for a single canary run."
  type        = number
  default     = 120
}

variable "start_canaries" {
  description = "Start canaries immediately after provisioning so scheduled health checks execute."
  type        = bool
  default     = true
}

variable "canary_success_retention_period" {
  description = "Number of days to retain successful canary runs."
  type        = number
  default     = 31
}

variable "canary_failure_retention_period" {
  description = "Number of days to retain failed canary runs."
  type        = number
  default     = 31
}

variable "failure_alarm_evaluation_periods" {
  description = "Number of consecutive periods the failure metric must breach before the alarm triggers."
  type        = number
  default     = 1
}

variable "failure_alarm_period" {
  description = "Evaluation period (seconds) of the canary failure alarm."
  type        = number
  default     = 60
}

variable "failure_alarm_threshold" {
  description = "Number of failed canary runs in the evaluation window that triggers the failure alarm."
  type        = number
  default     = 1
}

variable "success_percent_alarm_enabled" {
  description = "Master toggle enabling the SuccessPercent alarm for canaries."
  type        = bool
  default     = false
}

variable "success_percent_threshold" {
  description = "Success percent below which the optional success alarm notifies the SNS topic."
  type        = number
  default     = 90
}

variable "success_percent_alarm_period" {
  description = "Evaluation period (seconds) of the canary success percent alarm."
  type        = number
  default     = 60
}

variable "success_percent_alarm_evaluation_periods" {
  description = "Number of consecutive periods the success percent metric must breach before the alarm triggers."
  type        = number
  default     = 1
}

variable "canaries" {
  description = <<-EOT
    Map of VPC-enabled CloudWatch Synthetics canary configurations. Each map key
    becomes the canary name and must be 1-21 characters long, containing only
    lowercase letters, numbers, and hyphens.

    Every entry must place the canary inside the given list of subnet IDs and
    security group IDs. The code source for a canary may be supplied in one of
    three ways:

      - zip_file : local path to an inline ZIP archive containing the canary code
      - s3_bucket / s3_key : location of the code package in an S3 bucket
      - code : inline JavaScript source used to build the canary package

    When no source or schedule is given, a default health-check canary and the
    default schedule expression are used.
  EOT
  type = map(object({
    subnet_ids            = list(string)
    security_group_ids    = list(string)
    runtime_version       = optional(string)
    handler               = optional(string)
    schedule_expression   = optional(string)
    timeout_in_seconds    = optional(number)
    memory_in_mb          = optional(number)
    active_tracing        = optional(bool)
    environment_variables = optional(map(string))
    zip_file              = optional(string)
    s3_bucket             = optional(string)
    s3_key                = optional(string)
    s3_version            = optional(string)
    code                  = optional(string)
    start_canary          = optional(bool)
    success_alarm_enabled = optional(bool)
  }))
  default = {}

  validation {
    condition = alltrue([
      for name, cfg in var.canaries :
      length(name) >= 1 && length(name) <= 21 && can(regex("^[a-z0-9-]+$", name))
    ])
    error_message = "Each canary name must be 1-21 characters and contain only lowercase letters, numbers, and hyphens."
  }

  validation {
    condition = alltrue([
      for name, cfg in var.canaries :
      (cfg.zip_file != null) || (cfg.s3_bucket != null && cfg.s3_key != null) || (cfg.code != null)
    ])
    error_message = "Each canary must provide a code source: zip_file, s3_bucket/s3_key, or inline code."
  }

  validation {
    condition = alltrue([
      for name, cfg in var.canaries :
      (cfg.s3_bucket == null && cfg.s3_key == null) || (cfg.s3_bucket != null && cfg.s3_key != null)
    ])
    error_message = "s3_bucket and s3_key must be supplied together."
  }
}

# ---------------------------------------------------------------------------
# Data sources
# ---------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------

locals {
  common_tags = {
    TerraformTemplate = "benchmark-canary-monitoring"
    ManagedBy         = "terraform"
  }

  default_canary_code = <<-EOT
exports.handler = async () => {
    console.log('benchmark canary heartbeat ' + new Date().toISOString());
    return 'health check ok';
};
EOT

  default_canary_entry = {
    "benchmark-canary" = {
      subnet_ids            = aws_subnet.private[*].id
      security_group_ids    = [aws_security_group.canary.id]
      runtime_version       = null
      handler               = null
      schedule_expression   = null
      timeout_in_seconds    = null
      memory_in_mb          = null
      active_tracing        = null
      environment_variables = null
      zip_file              = null
      s3_bucket             = null
      s3_key                = null
      s3_version            = null
      code                  = null
      start_canary          = null
      success_alarm_enabled = null
    }
  }

  canary_entries = merge(length(var.canaries) > 0 ? {} : local.default_canary_entry, var.canaries)

  canary_definitions = {
    for name, cfg in local.canary_entries : name => {
      subnet_ids            = cfg.subnet_ids
      security_group_ids    = cfg.security_group_ids
      runtime_version       = coalesce(cfg.runtime_version, var.default_canary_runtime_version)
      handler               = coalesce(cfg.handler, "${name}.handler")
      schedule_expression   = coalesce(cfg.schedule_expression, var.default_canary_schedule_expression)
      timeout_in_seconds    = coalesce(cfg.timeout_in_seconds, var.canary_timeout_in_seconds)
      memory_in_mb          = coalesce(cfg.memory_in_mb, var.default_canary_memory_in_mb)
      active_tracing        = coalesce(cfg.active_tracing, false)
      environment_variables = cfg.environment_variables
      zip_file              = cfg.zip_file
      s3_bucket             = cfg.s3_bucket
      s3_key                = cfg.s3_key
      s3_version            = cfg.s3_version
      code                  = coalesce(cfg.code, local.default_canary_code)
      start_canary          = coalesce(cfg.start_canary, var.start_canaries)
      success_alarm_enabled = coalesce(cfg.success_alarm_enabled, var.success_percent_alarm_enabled)
    }
  }
}

# ---------------------------------------------------------------------------
# VPC networking for VPC-based canaries
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "benchmark-canary-vpc" })
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 10)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, { Name = "benchmark-canary-private-${count.index}" })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "benchmark-canary-private-rt" })
}

resource "aws_route_table_association" "private" {
  count          = length(aws_subnet.private)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "canary" {
  name        = "benchmark-canary-sg"
  description = "Security group used by VPC-enabled CloudWatch Synthetics canaries"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "benchmark-canary-sg" })
}

resource "aws_vpc_security_group_egress_rule" "canary_https_vpc" {
  security_group_id = aws_security_group.canary.id
  ip_protocol       = "tcp"
  from_port         = 443
  to_port           = 443
  cidr_ipv4         = aws_vpc.main.cidr_block
}

resource "aws_vpc_security_group_egress_rule" "canary_http_vpc" {
  security_group_id = aws_security_group.canary.id
  ip_protocol       = "tcp"
  from_port         = 80
  to_port           = 80
  cidr_ipv4         = aws_vpc.main.cidr_block
}

resource "aws_vpc_security_group_egress_rule" "canary_dns" {
  security_group_id = aws_security_group.canary.id
  ip_protocol       = "udp"
  from_port         = 53
  to_port           = 53
  cidr_ipv4         = aws_vpc.main.cidr_block
}

# Security group applied to the interface VPC endpoints so canary traffic is
# accepted only from the canary security group over HTTPS.
resource "aws_security_group" "vpc_endpoints" {
  name        = "benchmark-canary-endpoint-sg"
  description = "Security group for CloudWatch and Synthetics VPC interface endpoints"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "benchmark-canary-endpoint-sg" })
}

resource "aws_vpc_security_group_ingress_rule" "endpoints_from_canaries" {
  security_group_id            = aws_security_group.vpc_endpoints.id
  ip_protocol                  = "tcp"
  from_port                    = 443
  to_port                      = 443
  referenced_security_group_id = aws_security_group.canary.id
}

# Gateway endpoint so canaries can upload artifacts to S3 from private subnets.
resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.region}.s3"
  vpc_endpoint_type = "Gateway"
  tags              = merge(local.common_tags, { Name = "benchmark-canary-s3-vpce" })
}

resource "aws_vpc_endpoint_route_table_association" "s3_private" {
  vpc_endpoint_id = aws_vpc_endpoint.s3.id
  route_table_id  = aws_route_table.private.id
}

# Interface endpoints used by the Synthetics canary runtime for log delivery,
# metric publishing, and canary orchestration.
resource "aws_vpc_endpoint" "logs" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.region}.logs"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = merge(local.common_tags, { Name = "benchmark-canary-logs-vpce" })
}

resource "aws_vpc_endpoint" "monitoring" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.region}.monitoring"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = merge(local.common_tags, { Name = "benchmark-canary-monitoring-vpce" })
}

resource "aws_vpc_endpoint" "synthetics" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.region}.synthetics"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = merge(local.common_tags, { Name = "benchmark-canary-synthetics-vpce" })
}

# ---------------------------------------------------------------------------
# IAM role and policies for canary execution
# ---------------------------------------------------------------------------

resource "random_pet" "unique_prefix" {
  length    = 2
  separator = "-"
}

resource "aws_iam_role" "canary_execution" {
  name               = "${random_pet.unique_prefix.id}-canary-execution-role"
  description        = "Execution role for CloudWatch Synthetics canaries showing randomized pet name prefix"
  assume_role_policy = data.aws_iam_policy_document.canary_assume_role.json

  tags = local.common_tags
}

data "aws_iam_policy_document" "canary_assume_role" {
  statement {
    sid     = "AllowLambdaAndSyntheticsToAssume"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com", "synthetics.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "canary_execution" {
  statement {
    sid       = "CanaryS3Artifacts"
    effect    = "Allow"
    actions   = ["s3:GetBucketLocation", "s3:ListBucket", "s3:GetObject", "s3:PutObject", "s3:DeleteObject"]
    resources = [aws_s3_bucket.canary_artifacts.arn, "${aws_s3_bucket.canary_artifacts.arn}/*"]
  }

  statement {
    sid       = "CanaryCloudWatchMetrics"
    effect    = "Allow"
    actions   = ["cloudwatch:PutMetricData"]
    resources = ["*"]
  }

  statement {
    sid       = "CanaryCloudWatchLogs"
    effect    = "Allow"
    actions   = ["logs:CreateLogGroup", "logs:CreateLogStream", "logs:PutLogEvents"]
    resources = ["*"]
  }

  statement {
    sid       = "CanaryEniManagement"
    effect    = "Allow"
    actions   = ["ec2:CreateNetworkInterface", "ec2:DescribeNetworkInterfaces", "ec2:DeleteNetworkInterface", "ec2:DetachNetworkInterface"]
    resources = ["*"]
  }

  statement {
    sid       = "CanaryKmsKeyUse"
    effect    = "Allow"
    actions   = ["kms:DescribeKey", "kms:Encrypt", "kms:Decrypt", "kms:GenerateDataKey*", "kms:ReEncrypt*"]
    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["s3.${data.aws_region.current.region}.amazonaws.com"]
    }
  }
}

resource "aws_iam_role_policy" "canary_execution" {
  name   = "canary-execution-policy"
  role   = aws_iam_role.canary_execution.id
  policy = data.aws_iam_policy_document.canary_execution.json
}

# Waits for the IAM role to be assumable by Lambda/Synthetics before the
# canaries are provisioned. Newly-created roles can take several seconds to
# propagate through IAM.
resource "time_sleep" "iam_propagation" {
  create_duration = "30s"

  depends_on = [
    aws_iam_role.canary_execution,
    aws_iam_role_policy.canary_execution,
  ]
}

# ---------------------------------------------------------------------------
# Customer-managed KMS key
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "canary_kms_key_policy" {
  statement {
    sid    = "EnableIAMRootPermissions"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudWatchSynthetics"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudwatch.amazonaws.com"]
    }

    actions = [
      "kms:DescribeKey",
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AllowSnsMessageEncryption"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }

    actions = [
      "kms:DescribeKey",
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
    ]
    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["sns.${data.aws_region.current.region}.amazonaws.com"]
    }
  }
}

resource "aws_kms_key" "canary" {
  count                   = var.enable_custom_kms_key ? 1 : 0
  description             = "KMS key used to encrypt CloudWatch Synthetics canary artifacts and notifications"
  deletion_window_in_days = var.kms_deletion_window_in_days
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.canary_kms_key_policy.json

  tags = local.common_tags
}

resource "aws_kms_alias" "canary" {
  count         = var.enable_custom_kms_key ? 1 : 0
  name          = var.kms_key_alias
  target_key_id = aws_kms_key.canary[0].key_id
}

# ---------------------------------------------------------------------------
# S3 bucket for canary artifacts
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "canary_artifacts" {
  bucket        = var.canary_bucket_name
  force_destroy = var.bucket_force_destroy

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "canary_artifacts" {
  bucket                  = aws_s3_bucket.canary_artifacts.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "canary_artifacts" {
  bucket = aws_s3_bucket.canary_artifacts.id

  versioning_configuration {
    status = var.bucket_versioning_enabled ? "Enabled" : "Suspended"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "canary_artifacts" {
  bucket = aws_s3_bucket.canary_artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.enable_custom_kms_key ? "aws:kms" : "AES256"
      kms_master_key_id = var.enable_custom_kms_key ? aws_kms_key.canary[0].arn : null
    }
  }
}

resource "aws_s3_bucket_cors_configuration" "canary_artifacts" {
  bucket = aws_s3_bucket.canary_artifacts.id

  cors_rule {
    allowed_headers = ["*"]
    allowed_methods = ["GET", "HEAD", "PUT"]
    allowed_origins = ["*"]
    expose_headers  = ["ETag"]
    max_age_seconds = 3000
  }
}

# ---------------------------------------------------------------------------
# SNS topic, subscriptions, and topic policy
# ---------------------------------------------------------------------------

resource "aws_sns_topic" "alerts" {
  name              = var.sns_topic_name
  display_name      = "Canary Monitoring Alerts"
  kms_master_key_id = var.enable_custom_kms_key ? aws_kms_key.canary[0].arn : null

  tags = local.common_tags
}

resource "aws_sns_topic_subscription" "alerts_email" {
  topic_arn = aws_sns_topic.alerts.arn
  protocol  = "email"
  endpoint  = var.subscription_email
}

data "aws_iam_policy_document" "alerts_topic_policy" {
  statement {
    sid    = "AllowCloudWatchAlarmsToPublish"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudwatch.amazonaws.com"]
    }

    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.alerts.arn]
  }
}

resource "aws_sns_topic_policy" "alerts" {
  arn    = aws_sns_topic.alerts.arn
  policy = data.aws_iam_policy_document.alerts_topic_policy.json
}

# ---------------------------------------------------------------------------
# Canary code packages (inline zip built for each canary that needs one)
# ---------------------------------------------------------------------------

data "archive_file" "canary_code" {
  for_each = local.canary_definitions

  type                    = "zip"
  source_content          = each.value.code
  source_content_filename = "${each.key}.js"
  output_path             = "${path.module}/canary_sources/${each.key}.zip"
  output_file_mode        = "0666"
}

# ---------------------------------------------------------------------------
# CloudWatch Synthetics canaries
# ---------------------------------------------------------------------------

resource "aws_synthetics_canary" "this" {
  for_each = local.canary_definitions

  name                     = each.key
  execution_role_arn       = aws_iam_role.canary_execution.arn
  runtime_version          = each.value.runtime_version
  handler                  = each.value.handler
  artifact_s3_location     = "s3://${aws_s3_bucket.canary_artifacts.id}/${each.key}/"
  start_canary             = each.value.start_canary
  success_retention_period = var.canary_success_retention_period
  failure_retention_period = var.canary_failure_retention_period
  zip_file                 = each.value.s3_bucket != null ? null : coalesce(each.value.zip_file, data.archive_file.canary_code[each.key].output_path)
  s3_bucket                = each.value.s3_bucket
  s3_key                   = each.value.s3_key
  s3_version               = each.value.s3_version

  depends_on = [time_sleep.iam_propagation]

  tags = merge(local.common_tags, { CanaryName = each.key })

  run_config {
    timeout_in_seconds    = each.value.timeout_in_seconds
    memory_in_mb          = each.value.memory_in_mb
    active_tracing        = each.value.active_tracing
    environment_variables = each.value.environment_variables
  }

  schedule {
    expression          = each.value.schedule_expression
    duration_in_seconds = 0
  }

  vpc_config {
    subnet_ids         = each.value.subnet_ids
    security_group_ids = each.value.security_group_ids
  }
}

# ---------------------------------------------------------------------------
# CloudWatch alarms
# ---------------------------------------------------------------------------

resource "aws_cloudwatch_metric_alarm" "canary_failure" {
  for_each = local.canary_definitions

  alarm_name          = "${each.key}-failed-runs-alarm"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = var.failure_alarm_evaluation_periods
  metric_name         = "Failed"
  namespace           = "CloudWatchSynthetics"
  period              = var.failure_alarm_period
  statistic           = "Sum"
  threshold           = var.failure_alarm_threshold
  treat_missing_data  = "notBreaching"
  alarm_description   = "CloudWatch Synthetics canary ${each.key} reported ${var.failure_alarm_threshold} or more failed runs within ${var.failure_alarm_period} seconds."
  alarm_actions       = [aws_sns_topic.alerts.arn]

  dimensions = {
    CanaryName = aws_synthetics_canary.this[each.key].name
  }

  tags = local.common_tags
}

resource "aws_cloudwatch_metric_alarm" "canary_success_percent" {
  for_each = {
    for name, cfg in local.canary_definitions : name => cfg if cfg.success_alarm_enabled
  }

  alarm_name          = "${each.key}-success-percent-alarm"
  comparison_operator = "LessThanThreshold"
  evaluation_periods  = var.success_percent_alarm_evaluation_periods
  metric_name         = "SuccessPercent"
  namespace           = "CloudWatchSynthetics"
  period              = var.success_percent_alarm_period
  statistic           = "Average"
  threshold           = var.success_percent_threshold
  treat_missing_data  = "notBreaching"
  alarm_description   = "CloudWatch Synthetics canary ${each.key} success percent fell below ${var.success_percent_threshold} percent within the evaluation window."
  alarm_actions       = [aws_sns_topic.alerts.arn]
  ok_actions          = [aws_sns_topic.alerts.arn]

  dimensions = {
    CanaryName = aws_synthetics_canary.this[each.key].name
  }

  tags = local.common_tags
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "canary_execution_role_arn" {
  description = "ARN of the canary execution IAM role."
  value       = aws_iam_role.canary_execution.arn
}

output "canary_artifacts_bucket" {
  description = "Name of the S3 bucket storing canary artifacts."
  value       = aws_s3_bucket.canary_artifacts.id
}

output "canary_kms_key_id" {
  description = "ID of the customer-managed KMS key when enabled."
  value       = var.enable_custom_kms_key ? aws_kms_key.canary[0].key_id : null
}

output "alerts_sns_topic_arn" {
  description = "ARN of the SNS topic receiving canary failure notifications."
  value       = aws_sns_topic.alerts.arn
}

output "canary_names" {
  description = "Names of the deployed CloudWatch Synthetics canaries."
  value       = keys(aws_synthetics_canary.this)
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Highly customizable VPC module supporting multi-tier subnet architecture and
# configurable NAT gateway routing.
#
# Features:
#   * Global creation toggle (create_vpc) that controls every resource.
#   * Configurable VPC CIDR block and DNS hostname/support flags.
#   * Public, private and isolated (intra) subnet tiers mapped across a
#     provided list of availability zone names or IDs.
#   * Automatic subnet Name tag generation using configurable tier suffixes
#     and availability zone identifiers, unless explicit name lists are given.
#   * Conditional Internet Gateway + dedicated public route table with a
#     default 0.0.0.0/0 route when public subnets exist.
#   * Optional NAT Gateways (with Elastic IPs) limited to the minimum count of
#     public/private subnets, one dedicated private route table per private
#     subnet with a default NAT route.
#   * Intra subnets keep isolated route tables with no external internet route.
# ------------------------------------------------------------------------------

variable "create_vpc" {
  description = "Controls if the VPC and all related resources should be created."
  type        = bool
  default     = true
}

variable "name" {
  description = "Name prefix used for generated resource and tag names."
  type        = string
  default     = "my-vpc"
}

variable "tags" {
  description = "A map of additional tags to apply to all resources."
  type        = map(string)
  default     = {}
}

variable "vpc_cidr_block" {
  description = "The CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "enable_dns_hostnames" {
  description = "A boolean flag to enable/disable DNS hostnames in the VPC."
  type        = bool
  default     = true
}

variable "enable_dns_support" {
  description = "A boolean flag to enable/disable DNS support in the VPC."
  type        = bool
  default     = true
}

variable "availability_zones" {
  description = "List of availability zone names or IDs across which the subnet tiers are mapped."
  type        = list(string)
  default     = []
}

variable "public_subnets" {
  description = "List of CIDR blocks for public subnets."
  type        = list(string)
  default     = []
}

variable "private_subnets" {
  description = "List of CIDR blocks for private subnets."
  type        = list(string)
  default     = []
}

variable "intra_subnets" {
  description = "List of CIDR blocks for isolated (intra) subnets."
  type        = list(string)
  default     = []
}

variable "public_subnet_suffix" {
  description = "Suffix used for auto-generated public subnet Name tags."
  type        = string
  default     = "public"
}

variable "private_subnet_suffix" {
  description = "Suffix used for auto-generated private subnet Name tags."
  type        = string
  default     = "private"
}

variable "intra_subnet_suffix" {
  description = "Suffix used for auto-generated intra subnet Name tags."
  type        = string
  default     = "intra"
}

variable "public_subnet_names" {
  description = "Explicit names for public subnets. When supplied, these take precedence over auto-generated names."
  type        = list(string)
  default     = []
}

variable "private_subnet_names" {
  description = "Explicit names for private subnets. When supplied, these take precedence over auto-generated names."
  type        = list(string)
  default     = []
}

variable "intra_subnet_names" {
  description = "Explicit names for intra subnets. When supplied, these take precedence over auto-generated names."
  type        = list(string)
  default     = []
}

variable "map_public_ip_on_launch" {
  description = "Whether instances launched into public subnets are assigned a public IP address."
  type        = bool
  default     = false
}

variable "create_igw" {
  description = "Controls if an Internet Gateway is created and attached to the public route table."
  type        = bool
  default     = true
}

variable "enable_nat_gateway" {
  description = "Controls if NAT Gateways (with Elastic IPs) are provisioned for the private subnets."
  type        = bool
  default     = false
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  # Availability zones to distribute subnets across. Falls back to all
  # available zones in the region when none are provided.
  azs = length(var.availability_zones) > 0 ? var.availability_zones : data.aws_availability_zones.available.names

  # Translate AZ IDs (e.g. "use1-az1") to names (e.g. "us-east-1a") when the
  # caller supplies IDs instead of names so aws_subnet gets a valid name.
  az_ids_to_names = zipmap(data.aws_availability_zones.available.zone_ids, data.aws_availability_zones.available.names)
  az_names        = [for az in local.azs : try(local.az_ids_to_names[az], az)]

  # Number of NAT gateways: one per AZ up to the minimum of public/private
  # subnet counts, matching one public (carrier) subnet per gateway.
  nat_gateway_count = min(length(var.private_subnets), length(var.public_subnets))
}

# ------------------------------------------------------------------------------
# VPC
# ------------------------------------------------------------------------------
resource "aws_vpc" "this" {
  count = var.create_vpc ? 1 : 0

  cidr_block           = var.vpc_cidr_block
  enable_dns_hostnames = var.enable_dns_hostnames
  enable_dns_support   = var.enable_dns_support

  tags = merge(
    var.tags,
    { Name = var.name }
  )
}

# ------------------------------------------------------------------------------
# Public subnets
# ------------------------------------------------------------------------------
resource "aws_subnet" "public" {
  count = var.create_vpc ? length(var.public_subnets) : 0

  vpc_id                  = aws_vpc.this[0].id
  cidr_block              = var.public_subnets[count.index]
  availability_zone       = element(local.az_names, count.index)
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(
    var.tags,
    {
      Name = length(var.public_subnet_names) > 0 ? element(var.public_subnet_names, count.index) : format(
        "%s-%s-%s",
        var.name,
        var.public_subnet_suffix,
        element(local.azs, count.index),
      )
    }
  )
}

# ------------------------------------------------------------------------------
# Private subnets
# ------------------------------------------------------------------------------
resource "aws_subnet" "private" {
  count = var.create_vpc ? length(var.private_subnets) : 0

  vpc_id            = aws_vpc.this[0].id
  cidr_block        = var.private_subnets[count.index]
  availability_zone = element(local.az_names, count.index)

  tags = merge(
    var.tags,
    {
      Name = length(var.private_subnet_names) > 0 ? element(var.private_subnet_names, count.index) : format(
        "%s-%s-%s",
        var.name,
        var.private_subnet_suffix,
        element(local.azs, count.index),
      )
    }
  )
}

# ------------------------------------------------------------------------------
# Intra (isolated) subnets
# ------------------------------------------------------------------------------
resource "aws_subnet" "intra" {
  count = var.create_vpc ? length(var.intra_subnets) : 0

  vpc_id            = aws_vpc.this[0].id
  cidr_block        = var.intra_subnets[count.index]
  availability_zone = element(local.az_names, count.index)

  tags = merge(
    var.tags,
    {
      Name = length(var.intra_subnet_names) > 0 ? element(var.intra_subnet_names, count.index) : format(
        "%s-%s-%s",
        var.name,
        var.intra_subnet_suffix,
        element(local.azs, count.index),
      )
    }
  )
}

# ------------------------------------------------------------------------------
# Internet Gateway, public route table and default route
# ------------------------------------------------------------------------------
resource "aws_internet_gateway" "this" {
  count = var.create_vpc && var.create_igw && length(var.public_subnets) > 0 ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(
    var.tags,
    { Name = format("%s-igw", var.name) }
  )
}

resource "aws_route_table" "public" {
  count = var.create_vpc && length(var.public_subnets) > 0 ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(
    var.tags,
    { Name = format("%s-%s", var.name, var.public_subnet_suffix) }
  )
}

resource "aws_route" "public_internet_gateway" {
  count = var.create_vpc && var.create_igw && length(var.public_subnets) > 0 ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[0].id
}

resource "aws_route_table_association" "public" {
  count = var.create_vpc ? length(var.public_subnets) : 0

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

# ------------------------------------------------------------------------------
# Elastic IPs and NAT Gateways (one per public subnet, limited to the minimum
# count of public/private subnets)
# ------------------------------------------------------------------------------
resource "aws_eip" "nat" {
  count = var.create_vpc && var.enable_nat_gateway ? local.nat_gateway_count : 0

  domain = "vpc"

  tags = merge(
    var.tags,
    { Name = format("%s-nat-%s", var.name, element(local.azs, count.index)) }
  )
}

resource "aws_nat_gateway" "this" {
  count = var.create_vpc && var.enable_nat_gateway ? local.nat_gateway_count : 0

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(
    var.tags,
    { Name = format("%s-nat-%s", var.name, element(local.azs, count.index)) }
  )

  depends_on = [aws_internet_gateway.this]
}

# ------------------------------------------------------------------------------
# Private route tables, NAT routes and associations
# ------------------------------------------------------------------------------
resource "aws_route_table" "private" {
  count = var.create_vpc ? length(var.private_subnets) : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(
    var.tags,
    { Name = format("%s-%s-%s", var.name, var.private_subnet_suffix, element(local.azs, count.index)) }
  )
}

resource "aws_route" "private_nat_gateway" {
  count = var.create_vpc && var.enable_nat_gateway ? local.nat_gateway_count : 0

  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.this[count.index].id
}

resource "aws_route_table_association" "private" {
  count = var.create_vpc ? length(var.private_subnets) : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# ------------------------------------------------------------------------------
# Intra (isolated) route tables and associations - no external routes
# ------------------------------------------------------------------------------
resource "aws_route_table" "intra" {
  count = var.create_vpc ? length(var.intra_subnets) : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(
    var.tags,
    { Name = format("%s-%s-%s", var.name, var.intra_subnet_suffix, element(local.azs, count.index)) }
  )
}

resource "aws_route_table_association" "intra" {
  count = var.create_vpc ? length(var.intra_subnets) : 0

  subnet_id      = aws_subnet.intra[count.index].id
  route_table_id = aws_route_table.intra[count.index].id
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------
output "vpc_id" {
  description = "The ID of the VPC"
  value       = try(aws_vpc.this[0].id, null)
}

output "public_subnet_ids" {
  description = "IDs of the created public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the created private subnets"
  value       = aws_subnet.private[*].id
}

output "intra_subnet_ids" {
  description = "IDs of the created intra subnets"
  value       = aws_subnet.intra[*].id
}

output "nat_gateway_ids" {
  description = "IDs of the created NAT gateways"
  value       = aws_nat_gateway.this[*].id
}

variable "api_type" {
  description = "API type: 'http' for HTTP API (v2) or 'rest' for REST API (v1)"
  type        = string
  default     = "http"

  validation {
    condition     = contains(["http", "rest"], var.api_type)
    error_message = "api_type must be 'http' or 'rest'"
  }
}

variable "api_name" {
  description = "Name of the API"
  type        = string
  default     = "benchmark-api"
}

variable "environment" {
  description = "Environment name"
  type        = string
  default     = "dev"
}

variable "custom_domain" {
  description = "Custom domain name for the API (optional)"
  type        = string
  default     = ""
}

variable "enable_vpc_link" {
  description = "Enable VPC link for the API"
  type        = bool
  default     = false
}

variable "enable_custom_domain" {
  description = "Enable custom domain configuration"
  type        = bool
  default     = false
}

variable "enable_route53_alias" {
  description = "Enable Route 53 alias A record for the custom domain"
  type        = bool
  default     = false
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "private_subnet_cidr_bits" {
  description = "Additional bits for private subnet CIDR calculation"
  type        = number
  default     = 8
}

variable "rest_route_path" {
  description = "Resource path for REST API root resource"
  type        = string
  default     = "benchmark"
}

variable "rest_method_verb" {
  description = "HTTP method for the REST API method"
  type        = string
  default     = "GET"
}

variable "usage_plan_price" {
  description = "Price per request for the usage plan (in USD)"
  type        = number
  default     = 0.01
}

variable "nlb_tcp_port" {
  description = "TCP port for the NLB listener and target group"
  type        = number
  default     = 443
}

variable "alb_id" {
  description = "ALB ID to use as target for the NLB target group"
  type        = string
  default     = ""
}

variable "lambda_zip_path" {
  description = "Path to the Lambda function zip file"
  type        = string
  default     = "lambda-authorizer.zip"
}

variable "http_routes" {
  description = "List of HTTP API route definitions"
  type = list(object({
    route_key = string
    target    = string
  }))
  default = [
    { route_key = "GET /benchmark", target = "integrations" },
    { route_key = "POST /benchmark", target = "integrations" },
    { route_key = "ANY /{proxy+}", target = "integrations" }
  ]
}

locals {
  stage_name                      = "${var.environment}-stage"
  api_type_lower                  = lower(var.api_type)
  should_create_http              = local.api_type_lower == "http"
  should_create_rest              = local.api_type_lower == "rest"
  should_create_vpc               = var.enable_vpc_link || var.enable_custom_domain || var.enable_route53_alias
  should_create_custom_domain     = var.enable_custom_domain && var.custom_domain != ""
  should_create_vpc_link_http     = var.enable_vpc_link && local.should_create_http
  should_create_vpc_link_rest     = var.enable_vpc_link && local.should_create_rest
  should_create_route53           = var.enable_route53_alias && var.custom_domain != ""
  should_create_lambda_authorizer = local.should_create_rest
  should_create_usage_plan        = local.should_create_rest
  nlb_target_port                 = tostring(var.nlb_tcp_port)
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

# ---------------------------------------------------------------------------
# VPC and networking infrastructure
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  count      = local.should_create_vpc ? 1 : 0
  cidr_block = var.vpc_cidr

  tags = {
    Name        = var.api_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_subnet" "private" {
  count             = local.should_create_vpc ? length(data.aws_availability_zones.available.names) : 0
  vpc_id            = aws_vpc.main[0].id
  cidr_block        = cidrsubnet(var.vpc_cidr, var.private_subnet_cidr_bits, count.index + 1)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name        = "${var.api_name}-private-${count.index + 1}"
    Environment = var.environment
    Type        = "private"
  }
}

resource "aws_security_group" "api" {
  count       = local.should_create_vpc ? 1 : 0
  name        = "${var.api_name}-sg"
  vpc_id      = aws_vpc.main[0].id
  description = "Security group for ${var.api_name}"

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name        = "${var.api_name}-sg"
    Environment = var.environment
  }
}

# ---------------------------------------------------------------------------
# HTTP API (v2) resources
# ---------------------------------------------------------------------------

resource "aws_apigatewayv2_api" "http" {
  count         = local.should_create_http ? 1 : 0
  name          = var.api_name
  protocol_type = "HTTP"
  cors_configuration {
    allow_origins     = ["*"]
    allow_methods     = ["GET", "POST", "PUT", "DELETE", "PATCH"]
    allow_headers     = ["*"]
    expose_headers    = ["*"]
  }

  tags = {
    Name        = var.api_name
    Environment = var.environment
    Type        = "HTTP"
  }
}

resource "aws_apigatewayv2_integration" "http" {
  count              = local.should_create_http ? 1 : 0
  api_id             = aws_apigatewayv2_api.http[0].id
  integration_type   = "HTTP_PROXY"
  integration_method = "ANY"
  integration_uri    = "https://example.com/api"
  payload_format_version = "1.0"
  connection_type    = "INTERNET"
}

resource "aws_apigatewayv2_route" "http" {
  count     = local.should_create_http ? length(var.http_routes) : 0
  api_id    = aws_apigatewayv2_api.http[0].id
  route_key = var.http_routes[count.index].route_key
  target    = "integrations/${aws_apigatewayv2_integration.http[0].id}"
}

resource "aws_apigatewayv2_stage" "http" {
  count       = local.should_create_http ? 1 : 0
  api_id      = aws_apigatewayv2_api.http[0].id
  name        = local.stage_name
  auto_deploy = true

  tags = {
    Name        = local.stage_name
    Environment = var.environment
  }
}

# Certificate for custom domain – self-signed via the TLS provider
resource "tls_private_key" "custom_domain" {
  count     = local.should_create_custom_domain && local.should_create_http ? 1 : 0
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "custom_domain" {
  count                  = local.should_create_custom_domain && local.should_create_http ? 1 : 0
  private_key_pem        = tls_private_key.custom_domain[0].private_key_pem
  validity_period_hours  = 8760

  subject {
    common_name = var.custom_domain
  }

  dns_names = [var.custom_domain]

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

# Import the certificate into ACM (AWS Certificate Manager)
resource "aws_acm_certificate" "custom_domain" {
  count            = local.should_create_custom_domain && local.should_create_http ? 1 : 0
  certificate_body = tls_self_signed_cert.custom_domain[0].cert_pem
  private_key      = tls_private_key.custom_domain[0].private_key_pem
  domain_name      = var.custom_domain

  tags = {
    Name        = var.custom_domain
    Environment = var.environment
  }
}

resource "aws_apigatewayv2_domain_name" "http" {
  count       = local.should_create_custom_domain && local.should_create_http ? 1 : 0
  domain_name = var.custom_domain
  domain_name_configuration {
    certificate_arn = aws_acm_certificate.custom_domain[0].arn
    endpoint_type   = "REGIONAL"
    security_policy = "TLS_1_2"
  }

  tags = {
    Name        = var.custom_domain
    Environment = var.environment
  }
}

resource "aws_apigatewayv2_api_mapping" "http" {
  count       = local.should_create_custom_domain && local.should_create_http ? 1 : 0
  api_id      = aws_apigatewayv2_api.http[0].id
  domain_name = aws_apigatewayv2_domain_name.http[0].domain_name
  stage       = local.stage_name
}

resource "aws_route53_zone" "custom" {
  count = local.should_create_route53 && local.should_create_http ? 1 : 0
  name  = "${var.custom_domain}."

  tags = {
    Name        = var.custom_domain
    Environment = var.environment
  }
}

resource "aws_route53_record" "alias_a" {
  count   = local.should_create_route53 && local.should_create_http ? 1 : 0
  zone_id = aws_route53_zone.custom[0].zone_id
  name    = "${var.custom_domain}."
  type    = "A"

  alias {
    name                   = replace(replace(aws_apigatewayv2_api.http[0].api_endpoint, "/^https?://", ""), "/[:/].*", "")
    zone_id                = "Z3BJ6ZW7M0HQ0"
    evaluate_target_health = true
  }
}

resource "aws_apigatewayv2_vpc_link" "http" {
  count              = local.should_create_vpc_link_http ? 1 : 0
  name               = "${var.api_name}-vpc-link"
  security_group_ids = [aws_security_group.api[0].id]
  subnet_ids         = aws_subnet.private[*].id

  tags = {
    Name        = "${var.api_name}-vpc-link"
    Environment = var.environment
  }
}

# ---------------------------------------------------------------------------
# REST API (v1) resources
# ---------------------------------------------------------------------------
resource "aws_api_gateway_rest_api" "rest" {
  count = local.should_create_rest ? 1 : 0
  name  = var.api_name

  endpoint_configuration {
    types = ["REGIONAL"]
  }

  tags = {
    Name        = var.api_name
    Environment = var.environment
    Type        = "REST"
  }
}

# Dynamic resource path mapping
resource "aws_api_gateway_resource" "rest_root" {
  count       = local.should_create_rest ? 1 : 0
  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  parent_id   = aws_api_gateway_rest_api.rest[0].root_resource_id
  path_part   = var.rest_route_path
}

resource "aws_api_gateway_resource" "rest_proxy" {
  count       = local.should_create_rest ? 1 : 0
  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  parent_id   = aws_api_gateway_resource.rest_root[0].id
  path_part   = "{proxy+}"
}

# Route methods with path parameter overrides
resource "aws_api_gateway_method" "rest_get" {
  count         = local.should_create_rest ? 1 : 0
  rest_api_id   = aws_api_gateway_rest_api.rest[0].id
  resource_id   = aws_api_gateway_resource.rest_root[0].id
  http_method   = var.rest_method_verb
  authorization = "NONE"
  request_parameters = {
    "method.request.path.${var.rest_route_path}" = false
  }
}

resource "aws_api_gateway_method" "rest_proxy_get" {
  count         = local.should_create_rest ? 1 : 0
  rest_api_id   = aws_api_gateway_rest_api.rest[0].id
  resource_id   = aws_api_gateway_resource.rest_proxy[0].id
  http_method   = "ANY"
  authorization = "NONE"
  request_parameters = {
    "method.request.path.proxy" = false
  }
}

# Mock integrations for REST API methods
resource "aws_api_gateway_integration" "rest_get" {
  count       = local.should_create_rest ? 1 : 0
  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  resource_id = aws_api_gateway_resource.rest_root[0].id
  http_method = aws_api_gateway_method.rest_get[0].http_method
  type        = "MOCK"
  request_templates = {
    "application/json" = "{\"statusCode\": 200}"
  }
}

resource "aws_api_gateway_integration" "rest_proxy_get" {
  count       = local.should_create_rest ? 1 : 0
  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  resource_id = aws_api_gateway_resource.rest_proxy[0].id
  http_method = aws_api_gateway_method.rest_proxy_get[0].http_method
  type        = "MOCK"
  request_templates = {
    "application/json" = "{\"statusCode\": 200}"
  }
}

# Automatic redeployment trigger
resource "aws_api_gateway_deployment" "rest" {
  count        = local.should_create_rest ? 1 : 0
  rest_api_id  = aws_api_gateway_rest_api.rest[0].id
  description  = "Deployment triggered by Terraform - ${timestamp()}"

  depends_on = [
    aws_api_gateway_integration.rest_get[0],
    aws_api_gateway_integration.rest_proxy_get[0],
  ]

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_api_gateway_stage" "rest" {
  count         = local.should_create_rest ? 1 : 0
  rest_api_id   = aws_api_gateway_rest_api.rest[0].id
  stage_name    = local.stage_name
  deployment_id = aws_api_gateway_deployment.rest[0].id

  tags = {
    Name        = local.stage_name
    Environment = var.environment
  }
}

# Usage plan with API keys
resource "aws_api_gateway_usage_plan" "rest" {
  count        = local.should_create_usage_plan ? 1 : 0
  name         = "${var.api_name}-usage-plan"
  description  = "Usage plan for ${var.api_name}"
  product_code = "BENCHMARK"
  depends_on   = [aws_api_gateway_stage.rest[0]]

  api_stages {
    api_id = aws_api_gateway_rest_api.rest[0].id
    stage  = local.stage_name
  }

  quota_settings {
    limit  = 10000
    offset = 0
    period = "DAY"
  }

  throttle_settings {
    burst_limit = 100
    rate_limit  = 50
  }

  tags = {
    Name        = "${var.api_name}-usage-plan"
    Environment = var.environment
  }
}

resource "random_password" "api_key" {
  count  = local.should_create_usage_plan ? 1 : 0
  length = 32
}

resource "aws_api_gateway_api_key" "rest" {
  count   = local.should_create_usage_plan ? 1 : 0
  name    = "${var.api_name}-key"
  value   = random_password.api_key[0].result
  enabled = true

  tags = {
    Name        = "${var.api_name}-key"
    Environment = var.environment
  }
}

resource "aws_api_gateway_usage_plan_key" "rest" {
  count         = local.should_create_usage_plan ? 1 : 0
  usage_plan_id = aws_api_gateway_usage_plan.rest[0].id
  key_id        = aws_api_gateway_api_key.rest[0].id
  key_type      = "API_KEY"
}

# Store API key in SSM Parameter Store as SecureString
resource "aws_ssm_parameter" "api_key" {
  count = local.should_create_usage_plan ? 1 : 0
  name  = "/${var.api_name}/api-key"
  type  = "SecureString"
  value = aws_api_gateway_api_key.rest[0].value

  lifecycle {
    create_before_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Custom Lambda Authorizer (Node.js 16.x)
# ---------------------------------------------------------------------------

resource "aws_iam_role" "lambda_authorizer" {
  count = local.should_create_lambda_authorizer ? 1 : 0
  name  = "${var.api_name}-lambda-authorizer-role"

  assume_role_policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Effect = "Allow"
      }
    ]
  })

  tags = {
    Name        = "${var.api_name}-lambda-authorizer-role"
    Environment = var.environment
  }
}

resource "aws_iam_role_policy" "lambda_authorizer_execution" {
  count = local.should_create_lambda_authorizer ? 1 : 0
  name  = "${var.api_name}-lambda-authorizer-execution-policy"
  role  = aws_iam_role.lambda_authorizer[0].name

  policy = data.aws_iam_policy_document.lambda_authorizer_execution[0].json
}

data "aws_iam_policy_document" "lambda_authorizer_execution" {
  count = local.should_create_lambda_authorizer ? 1 : 0

  statement {
    actions   = ["logs:CreateLogGroup", "logs:CreateLogStream", "logs:PutLogEvents"]
    resources = ["*"]
    effect    = "Allow"
  }

  statement {
    actions   = ["lambda:InvokeFunction"]
    resources = ["arn:aws:lambda:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:function:${var.api_name}-authorizer"]
    effect    = "Allow"
  }
}

resource "aws_lambda_function" "authorizer" {
  count            = local.should_create_lambda_authorizer ? 1 : 0
  function_name    = "${var.api_name}-authorizer"
  role             = aws_iam_role.lambda_authorizer[0].arn
  handler          = "index.handler"
  runtime          = "nodejs16.x"
  filename         = var.lambda_zip_path
  source_code_hash = filebase64sha256(var.lambda_zip_path)

  lifecycle {
    create_before_destroy = true
  }

  tags = {
    Name        = "${var.api_name}-authorizer"
    Environment = var.environment
  }
}

resource "aws_lambda_permission" "authorizer_invoke" {
  count         = local.should_create_lambda_authorizer ? 1 : 0
  function_name = aws_lambda_function.authorizer[0].function_name
  action        = "lambda:InvokeFunction"
  principal     = "apigateway.amazonaws.com"
}

resource "aws_api_gateway_authorizer" "rest" {
  count           = local.should_create_lambda_authorizer ? 1 : 0
  rest_api_id     = aws_api_gateway_rest_api.rest[0].id
  name            = "${var.api_name}-authorizer"
  type            = "TOKEN"
  authorizer_uri  = aws_lambda_function.authorizer[0].invoke_arn
  identity_source = "method.request.header.Authorization"

  lifecycle {
    create_before_destroy = true
  }
}

# ---------------------------------------------------------------------------
# REST API VPC Link – NLB, target group, listener, VPC link
# ---------------------------------------------------------------------------

resource "aws_lb" "nlb" {
  count              = local.should_create_vpc_link_rest ? 1 : 0
  name               = "${var.api_name}-nlb"
  internal           = true
  load_balancer_type = "network"
  security_groups    = [aws_security_group.api[0].id]
  subnet_mapping {
    subnet_id = aws_subnet.private[0].id
  }

  tags = {
    Name        = "${var.api_name}-nlb"
    Environment = var.environment
  }
}

resource "aws_lb_target_group" "nlb" {
  count    = local.should_create_vpc_link_rest ? 1 : 0
  name     = "${var.api_name}-tg"
  port     = var.nlb_tcp_port
  protocol = "TCP"
  vpc_id   = aws_vpc.main[0].id

  health_check {
    enabled             = true
    protocol            = "HTTPS"
    port                = local.nlb_target_port
    path                = "/health"
    interval            = 30
    timeout             = 10
    healthy_threshold   = 3
    unhealthy_threshold = 3
  }

  tags = {
    Name        = "${var.api_name}-tg"
    Environment = var.environment
  }
}

resource "aws_lb_target_group_attachment" "nlb" {
  count            = local.should_create_vpc_link_rest && var.alb_id != "" ? 1 : 0
  target_group_arn = aws_lb_target_group.nlb[0].arn
  target_id        = var.alb_id
  port             = var.nlb_tcp_port
}

resource "aws_lb_listener" "nlb_tcp" {
  count             = local.should_create_vpc_link_rest ? 1 : 0
  load_balancer_arn = aws_lb.nlb[0].arn
  port              = var.nlb_tcp_port
  protocol          = "TCP"
  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.nlb[0].arn
  }
}

resource "aws_api_gateway_vpc_link" "rest" {
  count = local.should_create_vpc_link_rest ? 1 : 0
  name  = "${var.api_name}-vpc-link"

  target_arns = [
    aws_lb.nlb[0].arn
  ]

  tags = {
    Name        = "${var.api_name}-vpc-link"
    Environment = var.environment
  }
}

# ------------------------------------------------------------------------------
# AWS CloudTrail Logging Architecture
#
# Provisions a comprehensive, secure CloudTrail logging setup for auditing and
# compliance: a dedicated trail, an encrypted S3 log bucket, a CloudWatch Log
# Group with a dedicated ingestion role, a dedicated KMS key, and an optional
# SNS notification topic.
# ------------------------------------------------------------------------------

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_region" "current" {}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------

variable "trail_name" {
  description = "Name of the CloudTrail trail."
  type        = string
  default     = "cloudtrail-global"
}

variable "bucket_name" {
  description = "Name of the S3 bucket for CloudTrail logs. When empty, a name is generated incorporating the account ID, region and a random 8-character lowercase suffix."
  type        = string
  default     = ""
}

variable "random_suffix" {
  description = "Optional 8-character lowercase suffix for the generated S3 bucket name. When null/empty and bucket_name is empty, a random suffix is generated."
  type        = string
  default     = null
}

variable "bucket_force_destroy" {
  description = "Whether to force destroy the S3 bucket, allowing deletion even when it contains objects."
  type        = bool
  default     = true
}

variable "bucket_versioning_enabled" {
  description = "Whether to enable versioning on the CloudTrail S3 bucket."
  type        = bool
  default     = false
}

variable "s3_key_prefix" {
  description = "Prefix for the S3 keys under which CloudTrail objects are stored."
  type        = string
  default     = ""
}

variable "kms_key_deletion_window_in_days" {
  description = "Deletion window (in days) for the dedicated CloudTrail KMS key."
  type        = number
  default     = 30
}

variable "kms_key_alias_prefix" {
  description = "Prefix for the KMS key alias. Must begin with 'alias/'."
  type        = string
  default     = "alias/cloudtrail-"
}

variable "cloudtrail_log_decryption_role_arn" {
  description = "Optional IAM role ARN allowed to decrypt CloudTrail logs using the dedicated KMS key."
  type        = string
  default     = ""
}

variable "log_group_name" {
  description = "Name of the CloudWatch Log Group that receives CloudTrail events."
  type        = string
  default     = "cloudtrail-cloudwatch-logs"
}

variable "cloudwatch_logs_retention_in_days" {
  description = "Retention period (in days) for the CloudWatch Log Group."
  type        = number
  default     = 90
}

variable "cloudwatch_logs_role_name" {
  description = "Name of the IAM role CloudTrail assumes to deliver logs to CloudWatch Logs."
  type        = string
  default     = "cloudtrail-cloudwatch-logs-role"
}

variable "include_global_service_events" {
  description = "Whether the trail includes global service events such as IAM, STS and CloudFront."
  type        = bool
  default     = true
}

variable "is_multi_region_trail" {
  description = "Whether the trail applies to all AWS Regions."
  type        = bool
  default     = true
}

variable "enable_logging" {
  description = "Whether CloudTrail logging is enabled when the trail is created."
  type        = bool
  default     = true
}

variable "is_organization_trail" {
  description = "Whether this trail captures activity for all accounts in an AWS Organization."
  type        = bool
  default     = false
}

variable "enable_log_file_validation" {
  description = "Whether CloudTrail log file validation (SHA-256 hashing) is enabled."
  type        = bool
  default     = true
}

variable "event_selector_read_write_type" {
  description = "Read/write type captured by the event selector: All, ReadOnly or WriteOnly."
  type        = string
  default     = "All"
}

variable "event_selector_include_management_events" {
  description = "Whether management events are included in the event selector."
  type        = bool
  default     = true
}

variable "event_selector_data_resources" {
  description = "List of data resources captured by the event selector (e.g. S3 objects, Lambda functions, DynamoDB tables)."
  type = list(object({
    type   = string
    values = list(string)
  }))
  default = []
}

variable "insight_selector_types" {
  description = "List of CloudTrail Insights types to enable (ApiCallRateInsight, ApiErrorRateInsight)."
  type        = list(string)
  default     = []
}

variable "create_sns_topic" {
  description = "Whether to create an SNS topic for CloudTrail notifications."
  type        = bool
  default     = false
}

variable "sns_topic_name" {
  description = "Name of the SNS topic created when create_sns_topic is true."
  type        = string
  default     = "cloudtrail-alerts"
}

variable "cloudtrail_sns_topic_arn" {
  description = "ARN of an existing SNS topic used for CloudTrail notifications when create_sns_topic is false."
  type        = string
  default     = ""
}

variable "tags" {
  description = "Additional tags applied to all created resources."
  type        = map(string)
  default     = { ManagedBy = "terraform" }
}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------

locals {
  partition  = data.aws_partition.current.partition
  dns_suffix = data.aws_partition.current.dns_suffix
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.region

  trail_name = var.trail_name
  trail_arn  = "arn:${local.partition}:cloudtrail:${local.region}:${local.account_id}:trail/${local.trail_name}"

  log_group_name = var.log_group_name
  log_group_arn  = "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:${local.log_group_name}:*"
  log_stream_arn = "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:${local.log_group_name}:log-stream:*"

  kms_alias_prefix = startswith(var.kms_key_alias_prefix, "alias/") ? var.kms_key_alias_prefix : "alias/${var.kms_key_alias_prefix}"

  bucket_name = var.bucket_name != "" ? var.bucket_name : (
    (var.random_suffix != null && var.random_suffix != "")
    ? "cloudtrail-${local.account_id}-${local.region}-${lower(var.random_suffix)}"
    : "cloudtrail-${local.account_id}-${local.region}-${random_string.bucket_suffix[0].result}"
  )

  s3_object_prefix = var.s3_key_prefix != "" ? "${trim(var.s3_key_prefix, "/")}/AWSLogs/${local.account_id}/*" : "AWSLogs/${local.account_id}/*"

  common_tags = merge(var.tags, { ManagedBy = "terraform" })

  bucket_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AWSCloudTrailAclCheck"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.${local.dns_suffix}"
        }
        Action   = "s3:GetBucketAcl"
        Resource = "arn:${local.partition}:s3:::${local.bucket_name}"
        Condition = {
          StringEquals = {
            "aws:SourceArn" = local.trail_arn
          }
        }
      },
      {
        Sid    = "AWSCloudTrailWrite"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.${local.dns_suffix}"
        }
        Action   = "s3:PutObject"
        Resource = "arn:${local.partition}:s3:::${local.bucket_name}/${local.s3_object_prefix}"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl"  = "bucket-owner-full-control"
            "aws:SourceArn" = local.trail_arn
          }
        }
      }
    ]
  })

  kms_key_policy = jsonencode({
    Version = "2012-10-17"
    Id      = "cloudtrail-kms-key-policy"
    Statement = concat([
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudTrail to encrypt logs"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.${local.dns_suffix}"
        }
        Action   = "kms:GenerateDataKey*"
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceArn" = local.trail_arn
          }
          StringLike = {
            "kms:EncryptionContext:aws:cloudtrail:arn" = "${local.trail_arn}*"
          }
        }
      },
      {
        Sid    = "Allow CloudWatch Logs to use the key"
        Effect = "Allow"
        Principal = {
          Service = "logs.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey",
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow S3 to use the key"
        Effect = "Allow"
        Principal = {
          Service = "s3.${local.dns_suffix}"
        }
        Action = [
          "kms:GenerateDataKey",
          "kms:Decrypt",
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      }
    ], var.cloudtrail_log_decryption_role_arn != "" ? [{
      Sid    = "Allow role to decrypt CloudTrail logs"
      Effect = "Allow"
      Principal = {
        AWS = var.cloudtrail_log_decryption_role_arn
      }
      Action = [
        "kms:Decrypt",
        "kms:DescribeKey",
      ]
      Resource = "*"
    }] : [])
  })
}

# ------------------------------------------------------------------------------
# Random bucket suffix
# ------------------------------------------------------------------------------

resource "random_string" "bucket_suffix" {
  count   = var.bucket_name == "" && (var.random_suffix == null || var.random_suffix == "") ? 1 : 0
  length  = 8
  lower   = true
  upper   = false
  numeric = true
  special = false
}

# ------------------------------------------------------------------------------
# KMS key for CloudTrail log encryption
# ------------------------------------------------------------------------------

resource "aws_kms_key" "cloudtrail" {
  description             = "KMS key used to encrypt CloudTrail log files and the CloudTrail S3 bucket."
  deletion_window_in_days = var.kms_key_deletion_window_in_days
  enable_key_rotation     = true
  policy                  = local.kms_key_policy
  tags                    = merge(local.common_tags, { Name = "${var.trail_name}-kms-key" })
}

resource "aws_kms_alias" "cloudtrail" {
  name_prefix   = local.kms_alias_prefix
  target_key_id = aws_kms_key.cloudtrail.key_id
}

# ------------------------------------------------------------------------------
# S3 bucket for CloudTrail log storage
# ------------------------------------------------------------------------------

resource "aws_s3_bucket" "cloudtrail" {
  bucket        = local.bucket_name
  force_destroy = var.bucket_force_destroy
  tags          = merge(local.common_tags, { Name = local.bucket_name })
}

resource "aws_s3_bucket_public_access_block" "cloudtrail" {
  bucket                  = aws_s3_bucket.cloudtrail.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.cloudtrail.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  versioning_configuration {
    status = var.bucket_versioning_enabled ? "Enabled" : "Suspended"
  }
}

resource "aws_s3_bucket_policy" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id
  policy = local.bucket_policy
}

# ------------------------------------------------------------------------------
# CloudWatch Log Group and dedicated ingestion role
# ------------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "cloudtrail" {
  name              = var.log_group_name
  retention_in_days = var.cloudwatch_logs_retention_in_days
  kms_key_id        = aws_kms_key.cloudtrail.arn
  tags              = merge(local.common_tags, { Name = var.log_group_name })
}

resource "aws_iam_role" "cloudtrail_cloudwatch_logs" {
  name = var.cloudwatch_logs_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CloudTrailAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.${local.dns_suffix}"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, { Name = var.cloudwatch_logs_role_name })
}

resource "aws_iam_role_policy" "cloudtrail_cloudwatch_logs" {
  name = "cloudtrail-cloudwatch-logs-delivery"
  role = aws_iam_role.cloudtrail_cloudwatch_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "CloudTrailCreateLogStream"
        Effect   = "Allow"
        Action   = "logs:CreateLogStream"
        Resource = local.log_stream_arn
      },
      {
        Sid      = "CloudTrailPutLogEvents"
        Effect   = "Allow"
        Action   = "logs:PutLogEvents"
        Resource = local.log_stream_arn
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# Optional SNS notification topic
# ------------------------------------------------------------------------------

resource "aws_sns_topic" "cloudtrail" {
  count = var.create_sns_topic ? 1 : 0
  name  = var.sns_topic_name
  tags  = merge(local.common_tags, { Name = var.sns_topic_name })
}

resource "aws_sns_topic_policy" "cloudtrail" {
  count = var.create_sns_topic ? 1 : 0
  arn   = aws_sns_topic.cloudtrail[0].arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Allow CloudTrail to publish notifications"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.${local.dns_suffix}"
        }
        Action   = "sns:Publish"
        Resource = aws_sns_topic.cloudtrail[0].arn
        Condition = {
          StringEquals = {
            "aws:SourceArn" = local.trail_arn
          }
        }
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# CloudTrail trail
# ------------------------------------------------------------------------------

resource "aws_cloudtrail" "this" {
  name                          = var.trail_name
  s3_bucket_name                = aws_s3_bucket.cloudtrail.id
  s3_key_prefix                 = var.s3_key_prefix != "" ? var.s3_key_prefix : null
  cloud_watch_logs_group_arn    = local.log_group_arn
  cloud_watch_logs_role_arn     = aws_iam_role.cloudtrail_cloudwatch_logs.arn
  kms_key_id                    = aws_kms_key.cloudtrail.arn
  sns_topic_name                = var.create_sns_topic ? aws_sns_topic.cloudtrail[0].name : (var.cloudtrail_sns_topic_arn != "" ? var.cloudtrail_sns_topic_arn : null)
  is_multi_region_trail         = var.is_multi_region_trail
  enable_logging                = var.enable_logging
  include_global_service_events = var.include_global_service_events
  is_organization_trail         = var.is_organization_trail
  enable_log_file_validation    = var.enable_log_file_validation
  tags                          = merge(local.common_tags, { Name = var.trail_name })

  event_selector {
    read_write_type           = var.event_selector_read_write_type
    include_management_events = var.event_selector_include_management_events

    dynamic "data_resource" {
      for_each = var.event_selector_data_resources
      content {
        type   = data_resource.value.type
        values = data_resource.value.values
      }
    }
  }

  dynamic "insight_selector" {
    for_each = var.insight_selector_types
    content {
      insight_type = insight_selector.value
    }
  }

  depends_on = [
    aws_s3_bucket_policy.cloudtrail,
    aws_cloudwatch_log_group.cloudtrail,
    aws_iam_role_policy.cloudtrail_cloudwatch_logs,
  ]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
  required_version = ">= 1.3"
}

variable "enabled" {
  description = "Global enable/disable flag for all EBS security settings"
  type        = bool
  default     = true
}

variable "enable_ebs_encryption" {
  description = "Enable default EBS encryption for the target region"
  type        = bool
  default     = true
}

variable "block_public_access_state" {
  description = "State for EBS snapshot block public access. Valid values: block-all-sharing, block-new-sharing"
  type        = string
  default     = "block-all-sharing"

  validation {
    condition     = contains(["block-all-sharing", "block-new-sharing"], var.block_public_access_state)
    error_message = "The block_public_access_state must be either 'block-all-sharing' or 'block-new-sharing'."
  }
}

variable "target_region" {
  description = "Optional region to target. Defaults to the current provider region when not specified."
  type        = string
  default     = null
}

data "aws_region" "current" {}

locals {
  region = var.target_region != null ? var.target_region : data.aws_region.current.region
}

# ---------------------------------------------------------------------------
# Provider alias targeting the resolved region
# ---------------------------------------------------------------------------
provider "aws" {
  alias  = "target"
  region = local.region
}

# ---------------------------------------------------------------------------
# Enable default EBS encryption in the target region
# ---------------------------------------------------------------------------
resource "aws_ebs_encryption_by_default" "this" {
  count = var.enabled && var.enable_ebs_encryption ? 1 : 0

  provider = aws.target
  enabled  = true
}

# ---------------------------------------------------------------------------
# Block public access to EBS snapshots in the target region
# ---------------------------------------------------------------------------
resource "aws_ebs_snapshot_block_public_access" "this" {
  count = var.enabled ? 1 : 0

  provider = aws.target
  state    = var.block_public_access_state
}

variable "iam_user_name" {
  description = "Name of the IAM deployment user"
  type        = string
  default     = "DeploymentUser"
}

variable "tags" {
  description = "Optional resource tags"
  type        = map(string)
  default     = {}
}

variable "s3_bucket_arns" {
  description = "List of S3 bucket ARNs to grant object and bucket permissions for"
  type        = list(string)
  default     = []
}

variable "s3_bucket_subpaths" {
  description = "Map of S3 bucket ARN to sub-path (prefix). Defaults to '*' (all objects) for buckets not listed."
  type        = map(string)
  default     = {}
}

variable "lambda_function_arns" {
  description = "List of Lambda function ARNs to grant UpdateFunctionCode permission for"
  type        = list(string)
  default     = []
}

resource "aws_iam_user" "this" {
  name = var.iam_user_name
  tags = var.tags
}

locals {
  s3_bucket_paths = {
    for arn in var.s3_bucket_arns :
    arn => try(var.s3_bucket_subpaths[arn], "*")
  }
}

resource "aws_iam_user_policy" "s3" {
  count = length(var.s3_bucket_arns) > 0 ? 1 : 0
  name  = "${var.iam_user_name}-s3"
  user  = aws_iam_user.this.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = concat(
      [
        for arn, subpath in local.s3_bucket_paths : {
          Effect = "Allow"
          Action = [
            "s3:GetObject",
            "s3:PutObject",
            "s3:PutObjectAcl",
            "s3:DeleteObject"
          ]
          Resource = "${arn}/${subpath}"
        }
      ],
      [
        {
          Effect = "Allow"
          Action = [
            "s3:ListBucket"
          ]
          Resource = var.s3_bucket_arns
        }
      ]
    )
  })
}

resource "aws_iam_user_policy" "lambda" {
  count = length(var.lambda_function_arns) > 0 ? 1 : 0
  name  = "${var.iam_user_name}-lambda"
  user  = aws_iam_user.this.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "lambda:UpdateFunctionCode"
        Resource = var.lambda_function_arns
      }
    ]
  })
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

variable "bucket_name" {
  type        = string
  default     = ""
  description = "Custom name for the S3 bucket"
}

variable "domain_name" {
  type        = string
  default     = ""
  description = "Domain name for the static website (requires hosted_zone_id)"
}

variable "hosted_zone_id" {
  type        = string
  default     = ""
  description = "Route 53 hosted zone ID (required if domain_name is set)"
}

variable "create_www_subdomain" {
  type        = bool
  default     = false
  description = "Whether to create www. subdomain aliases and wildcard SAN in the certificate"
}

variable "enable_versioning" {
  type        = bool
  default     = false
  description = "Enable S3 bucket versioning"
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
resource "random_id" "this" {
  byte_length = 8
}

locals {
  domain_provided = var.domain_name != ""
  bucket_name_final = var.bucket_name != "" ? var.bucket_name : (
    var.domain_name != "" ? var.domain_name : "webapp-template-${random_id.this.hex}"
  )
}

provider "aws" {
  alias  = "us_east_1"
  region = "us-east-1"
}

# ---------------------------------------------------------------------------
# KMS Key (initial default policy, updated after CloudFront exists)
# ---------------------------------------------------------------------------
resource "aws_kms_key" "this" {
  description             = "Customer-managed KMS key for S3 bucket SSE-KMS"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
    ]
  })
}

resource "aws_kms_alias" "this" {
  name          = "alias/s3-sse-kms-${local.bucket_name_final}"
  target_key_id = aws_kms_key.this.key_id
}

# ---------------------------------------------------------------------------
# S3 Bucket
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "this" {
  bucket        = local.bucket_name_final
  force_destroy = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id
  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = var.enable_versioning ? "Enabled" : "Suspended"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.this.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

# ---------------------------------------------------------------------------
# CloudFront Origin Access Control
# ---------------------------------------------------------------------------
resource "aws_cloudfront_origin_access_control" "this" {
  name                              = "oac-${local.bucket_name_final}"
  description                       = "OAC for static website S3 bucket"
  origin_access_control_origin_type = "s3"
  signing_behavior                  = "always"
  signing_protocol                  = "sigv4"
}

# ---------------------------------------------------------------------------
# WAFv2 Web ACL (CloudFront-scoped, must be in us-east-1)
# ---------------------------------------------------------------------------
resource "aws_wafv2_web_acl" "this" {
  name        = "waf-cf-${replace(local.bucket_name_final, ".", "-")}"
  description = "CloudFront-scoped WAFv2 web ACL with default allow"
  scope       = "CLOUDFRONT"

  default_action {
    allow {}
  }

  visibility_config {
    cloudwatch_metrics_enabled = true
    metric_name               = "waf-cf-${replace(local.bucket_name_final, ".", "-")}"
    sampled_requests_enabled  = true
  }

  provider = aws.us_east_1
}

# ---------------------------------------------------------------------------
# CloudFront Distribution
# ---------------------------------------------------------------------------
resource "aws_cloudfront_distribution" "this" {
  enabled             = true
  is_ipv6_enabled     = true
  price_class         = "PriceClass_100"
  default_root_object = "index.html"
  retain_on_delete    = false
  wait_for_deployment = true

  aliases = local.domain_provided ? concat(
    [var.domain_name],
    var.create_www_subdomain ? ["www.${var.domain_name}"] : []
  ) : []

  origin {
    domain_name              = aws_s3_bucket.this.bucket_regional_domain_name
    origin_access_control_id = aws_cloudfront_origin_access_control.this.id
    origin_id                = "S3-${aws_s3_bucket.this.id}"

  }

  default_cache_behavior {
    target_origin_id       = "S3-${aws_s3_bucket.this.id}"
    viewer_protocol_policy = "redirect-to-https"
    cache_policy_id        = data.aws_cloudfront_cache_policy.caching_optimized.id
    allowed_methods        = ["GET", "HEAD", "OPTIONS"]
    cached_methods         = ["GET", "HEAD"]
    compress               = true
  }

  ordered_cache_behavior {
    path_pattern           = "/index.html"
    target_origin_id       = "S3-${aws_s3_bucket.this.id}"
    viewer_protocol_policy = "redirect-to-https"
    cache_policy_id        = data.aws_cloudfront_cache_policy.caching_disabled.id
    allowed_methods        = ["GET", "HEAD", "OPTIONS"]
    cached_methods         = ["GET", "HEAD"]
    compress               = true
  }

  custom_error_response {
    error_code            = 403
    response_code         = 404
    response_page_path    = "/index.html"
    error_caching_min_ttl = 10
  }

  custom_error_response {
    error_code            = 404
    response_code         = 404
    response_page_path    = "/index.html"
    error_caching_min_ttl = 10
  }

  viewer_certificate {
    cloudfront_default_certificate = !local.domain_provided
    acm_certificate_arn            = local.domain_provided ? aws_acm_certificate_validation.this[0].certificate_arn : null
    ssl_support_method             = local.domain_provided ? "sni-only" : null
    minimum_protocol_version       = local.domain_provided ? "TLSv1.2_2021" : null
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  web_acl_id = aws_wafv2_web_acl.this.arn

  tags = {
    Name = "static-site-${local.bucket_name_final}"
  }
}

# ---------------------------------------------------------------------------
# Managed Cache Policy Data Sources
# ---------------------------------------------------------------------------
data "aws_cloudfront_cache_policy" "caching_optimized" {
  name = "Managed-CachingOptimized"
}

data "aws_cloudfront_cache_policy" "caching_disabled" {
  name = "Managed-CachingDisabled"
}

# ---------------------------------------------------------------------------
# S3 Bucket Policy (allows CloudFront OAC with source ARN condition)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCloudFrontOAC"
        Effect = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
        Action   = "s3:GetObject"
        Resource = "${aws_s3_bucket.this.arn}/*"
        Condition = {
          StringEquals = {
            "aws:SourceArn" = aws_cloudfront_distribution.this.arn
          }
        }
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# KMS Key Policy Update (add CloudFront decrypt permission)
# ---------------------------------------------------------------------------
resource "aws_kms_key_policy" "this" {
  key_id = aws_kms_key.this.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudFront Decrypt"
        Effect = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey*"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceArn" = aws_cloudfront_distribution.this.arn
          }
        }
      },
    ]
  })
  depends_on = [aws_cloudfront_distribution.this]
}

# ---------------------------------------------------------------------------
# ACM Certificate (us-east-1) + DNS Validation – only when domain is given
# ---------------------------------------------------------------------------
resource "aws_acm_certificate" "this" {
  count = local.domain_provided ? 1 : 0

  domain_name       = var.domain_name
  validation_method = "DNS"
  subject_alternative_names = var.create_www_subdomain ? ["*.${var.domain_name}"] : []

  provider = aws.us_east_1

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_route53_record" "validation" {
  count = local.domain_provided ? length(aws_acm_certificate.this[0].domain_validation_options) : 0

  zone_id = var.hosted_zone_id
  name    = aws_acm_certificate.this[0].domain_validation_options[count.index].resource_record_name
  type    = aws_acm_certificate.this[0].domain_validation_options[count.index].resource_record_type
  records = [aws_acm_certificate.this[0].domain_validation_options[count.index].resource_record_value]
  ttl     = 60
  allow_overwrite = true
}

resource "aws_acm_certificate_validation" "this" {
  count = local.domain_provided ? 1 : 0

  certificate_arn         = aws_acm_certificate.this[0].arn
  validation_record_fqdns = aws_route53_record.validation[*].fqdn

  provider = aws.us_east_1
}

# ---------------------------------------------------------------------------
# Route 53 Alias Records – only when domain is given
# ---------------------------------------------------------------------------
resource "aws_route53_record" "main" {
  count = local.domain_provided ? 1 : 0

  zone_id = var.hosted_zone_id
  name    = var.domain_name
  type    = "A"

  alias {
    name                   = aws_cloudfront_distribution.this.domain_name
    zone_id                = aws_cloudfront_distribution.this.hosted_zone_id
    evaluate_target_health = false
  }
}

resource "aws_route53_record" "www" {
  count = local.domain_provided && var.create_www_subdomain ? 1 : 0

  zone_id = var.hosted_zone_id
  name    = "www.${var.domain_name}"
  type    = "A"

  alias {
    name                   = aws_cloudfront_distribution.this.domain_name
    zone_id                = aws_cloudfront_distribution.this.hosted_zone_id
    evaluate_target_health = false
  }
}

variable "availability_zones" {
  description = "Comma-separated list of availability zone names"
  type        = string
  default     = "us-east-1a,us-east-1b,us-east-1c"
}

variable "enable_s3_vpc_endpoint" {
  description = "Enable S3 VPC Gateway Endpoint"
  type        = bool
  default     = true
}

variable "multi_az_nat_gateway" {
  description = "Deploy one NAT gateway per availability zone"
  type        = number
  default     = 1
}

variable "single_nat_gateway" {
  description = "Deploy a single shared NAT gateway"
  type        = number
  default     = 0
}

locals {
  azs      = split(",", var.availability_zones)
  vpc_cidr = "10.20.0.0/16"

  default_tags = {
    Author     = "Fairwinds"
    "Managed By" = "Terraform"
  }

  tier_configs = {
    admin              = { suffix = "admin",              netnum_start = 0  }
    public             = { suffix = "public",             netnum_start = 4  }
    private_production = { suffix = "private-production", netnum_start = 8  }
    private_working    = { suffix = "private-working",    netnum_start = 12 }
  }

  # Flat map of all subnets: key = "tier_azN"
  subnets = merge([
    for tier_key, tier_cfg in local.tier_configs : {
      for i, az in local.azs :
      "${tier_key}_az${i + 1}" => {
        az_index    = i
        tier_key    = tier_key
        tier_suffix = tier_cfg.suffix
        az          = az
        cidr        = cidrsubnet(local.vpc_cidr, 5, tier_cfg.netnum_start + i)
      }
    }
  ]...)

  subnet_keys_public  = [for k, v in local.subnets : k if v.tier_key == "public"]
  subnet_keys_private = [for k, v in local.subnets : k if v.tier_key != "public"]

  nat_gateway_count = var.single_nat_gateway == 1 ? 1 : (var.multi_az_nat_gateway == 1 ? length(local.azs) : 0)
}

# ---------------------------------------------------------------------------
# VPC
# ---------------------------------------------------------------------------
resource "aws_vpc" "this" {
  cidr_block           = local.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(local.default_tags, {
    Name = "main"
  })
}

# ---------------------------------------------------------------------------
# Internet Gateway
# ---------------------------------------------------------------------------
resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id

  tags = merge(local.default_tags, {
    Name = "vpc"
  })
}

# ---------------------------------------------------------------------------
# Subnets
# ---------------------------------------------------------------------------
resource "aws_subnet" "this" {
  for_each = local.subnets

  vpc_id            = aws_vpc.this.id
  cidr_block        = each.value.cidr
  availability_zone = each.value.az

  map_public_ip_on_launch = false

  tags = merge(local.default_tags, {
    Name = "${each.value.tier_suffix}-az${each.value.az_index + 1}"
    Tier = each.value.tier_key
    Az   = "az${each.value.az_index + 1}"
  })
}

# ---------------------------------------------------------------------------
# Elastic IPs
# ---------------------------------------------------------------------------
resource "aws_eip" "nat" {
  count  = local.nat_gateway_count
  domain = "vpc"

  tags = merge(local.default_tags, {
    Name = "nat-${count.index + 1}"
  })
}

# ---------------------------------------------------------------------------
# NAT Gateways (per-AZ or single, controlled by variables)
# ---------------------------------------------------------------------------
resource "aws_nat_gateway" "this" {
  count = local.nat_gateway_count

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = local.nat_gateway_count == 1 ? aws_subnet.this["public_az1"].id : aws_subnet.this["public_az${count.index + 1}"].id

  depends_on = [aws_internet_gateway.this]

  tags = merge(local.default_tags, {
    Name = "nat-${count.index + 1}"
  })
}

# ---------------------------------------------------------------------------
# Public Route Table (shared across all public subnets)
# ---------------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.this.id

  tags = merge(local.default_tags, {
    Name = "public"
  })
}

resource "aws_route" "public_igw" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this.id
}

# ---------------------------------------------------------------------------
# Private Route Tables (one per AZ)
# ---------------------------------------------------------------------------
resource "aws_route_table" "private" {
  count = length(local.azs)

  vpc_id = aws_vpc.this.id

  tags = merge(local.default_tags, {
    Name = "private_az${count.index + 1}"
  })
}

resource "aws_route" "private_nat" {
  count = length(local.azs)

  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = local.nat_gateway_count == 1 ? aws_nat_gateway.this[0].id : aws_nat_gateway.this[count.index].id
}

# ---------------------------------------------------------------------------
# Route Table Associations – Public
# ---------------------------------------------------------------------------
resource "aws_route_table_association" "public" {
  for_each = toset(local.subnet_keys_public)

  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# Route Table Associations – Private (per AZ, covers admin, production, working)
# ---------------------------------------------------------------------------
resource "aws_route_table_association" "private" {
  for_each = toset(local.subnet_keys_private)

  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.private[local.subnets[each.key].az_index].id
}

# ---------------------------------------------------------------------------
# Data: current region (used for S3 endpoint service name)
# ---------------------------------------------------------------------------
data "aws_region" "current" {}

# ---------------------------------------------------------------------------
# S3 Gateway VPC Endpoint (conditional)
# ---------------------------------------------------------------------------
resource "aws_vpc_endpoint" "s3" {
  count = var.enable_s3_vpc_endpoint ? 1 : 0

  vpc_id            = aws_vpc.this.id
  service_name      = "com.amazonaws.${data.aws_region.current.region}.s3"
  vpc_endpoint_type = "Gateway"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = "*"
        Action    = "s3:*"
        Resource  = "*"
      }
    ]
  })

  route_table_ids = aws_route_table.private[*].id

  tags = merge(local.default_tags, {
    Name = "s3-gateway-endpoint"
  })
}

variable "github_organization" {
  description = "GitHub organization or account name for OIDC CI/CD role trust"
  type        = string
}

variable "health_check_path" {
  description = "Path for ALB health checks"
  type        = string
  default     = "/health"
}

variable "app_port" {
  description = "Port the application container listens on"
  type        = number
  default     = 80
}

locals {
  name_prefix = "fargate-backend"
  azs         = slice(data.aws_availability_zones.available.names, 0, 2)
  app_port    = var.app_port
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

data "aws_partition" "current" {}

# ─── VPC ─────────────────────────────────────────────────────────────────────

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.name_prefix}-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-igw"
  }
}

# ─── Public Subnets ─────────────────────────────────────────────────────────

resource "aws_subnet" "public" {
  count                   = length(local.azs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}-public-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count             = length(local.azs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + length(local.azs))
  availability_zone = local.azs[count.index]

  tags = {
    Name = "${local.name_prefix}-private-${count.index}"
  }
}

# ─── Route Tables ────────────────────────────────────────────────────────────

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${local.name_prefix}-public"
  }
}

resource "aws_route_table_association" "public" {
  count          = length(local.azs)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-private"
  }
}

resource "aws_route_table_association" "private" {
  count          = length(local.azs)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# ─── ECR Repository ──────────────────────────────────────────────────────────

resource "aws_ecr_repository" "app" {
  name                 = "${local.name_prefix}-app"
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }
}

resource "aws_ecr_lifecycle_policy" "untagged_expiry" {
  repository = aws_ecr_repository.app.name

  policy = jsonencode({
    rules = [
      {
        rulePriority = 1
        description  = "Expire untagged images after 14 days"
        selection = {
          tagStatus   = "untagged"
          countType   = "sinceImagePushed"
          countUnit   = "days"
          countNumber = 14
        }
        action = {
          type = "expire"
        }
      }
    ]
  })
}

# ─── Security Groups ─────────────────────────────────────────────────────────

resource "aws_security_group" "alb" {
  name        = "${local.name_prefix}-alb"
  description = "ALB security group"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-alb"
  }
}

resource "aws_security_group" "app" {
  name        = "${local.name_prefix}-app"
  description = "Application container security group"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-app"
  }
}

resource "aws_security_group" "database" {
  name        = "${local.name_prefix}-database"
  description = "RDS security group"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-database"
  }
}

# ── ALB rules ──────────────────────────────────────────────────────────────

resource "aws_security_group_rule" "alb_ingress_https" {
  type              = "ingress"
  security_group_id = aws_security_group.alb.id
  description       = "HTTPS from internet"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
}

resource "aws_security_group_rule" "alb_ingress_http" {
  type              = "ingress"
  security_group_id = aws_security_group.alb.id
  description       = "HTTP from internet (redirects to HTTPS)"
  from_port         = 80
  to_port           = 80
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
}

resource "aws_security_group_rule" "alb_egress_vpc" {
  type              = "egress"
  security_group_id = aws_security_group.alb.id
  description       = "Outbound within VPC only"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [aws_vpc.main.cidr_block]
}

# ── App rules ───────────────────────────────────────────────────────────────

resource "aws_security_group_rule" "app_ingress_alb" {
  type                     = "ingress"
  security_group_id        = aws_security_group.app.id
  description              = "Traffic from ALB"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  source_security_group_id = aws_security_group.alb.id
}

resource "aws_security_group_rule" "app_egress_db" {
  type                     = "egress"
  security_group_id        = aws_security_group.app.id
  description              = "Outbound to database"
  from_port                = 5432
  to_port                  = 5432
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.database.id
}

resource "aws_security_group_rule" "app_egress_vpc" {
  type              = "egress"
  security_group_id = aws_security_group.app.id
  description       = "Outbound within VPC (non-DB)"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [aws_vpc.main.cidr_block]
}

# ── Database rules ──────────────────────────────────────────────────────────

resource "aws_security_group_rule" "db_ingress_app" {
  type                     = "ingress"
  security_group_id        = aws_security_group.database.id
  description              = "PostgreSQL from app containers"
  from_port                = 5432
  to_port                  = 5432
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.app.id
}

resource "aws_security_group_rule" "db_egress_vpc" {
  type              = "egress"
  security_group_id = aws_security_group.database.id
  description       = "Outbound within VPC only"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [aws_vpc.main.cidr_block]
}

# ─── RDS PostgreSQL ──────────────────────────────────────────────────────────

resource "aws_db_subnet_group" "main" {
  name       = "${local.name_prefix}-db-subnets"
  subnet_ids = aws_subnet.private[*].id
}

resource "aws_db_instance" "postgres" {
  identifier             = "${local.name_prefix}-postgres"
  engine                 = "postgres"
  engine_version         = "16.3"
  instance_class         = "db.t4g.micro"
  allocated_storage      = 20
  storage_encrypted      = true
  db_name                = "mydb"
  username               = "postgres"
  password               = "postgres"
  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.database.id]
  publicly_accessible    = false
  multi_az               = false
  skip_final_snapshot    = true

  lifecycle {
    prevent_destroy = true
  }
}

# ─── ACM Certificate (self-signed) ───────────────────────────────────────────

resource "tls_private_key" "self_signed" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "self_signed" {
  private_key_pem = tls_private_key.self_signed.private_key_pem

  subject {
    common_name  = "fargate-backend.local"
    organization = "Fargate Backend"
  }

  validity_period_hours = 87600

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "self_signed" {
  private_key       = tls_private_key.self_signed.private_key_pem
  certificate_body  = tls_self_signed_cert.self_signed.cert_pem
}

# ─── Application Load Balancer ───────────────────────────────────────────────

resource "aws_lb" "internal" {
  name                       = "${local.name_prefix}-alb"
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = aws_subnet.public[*].id
  drop_invalid_header_fields = true

  enable_deletion_protection = false
}

resource "aws_lb_target_group" "app" {
  name        = "${local.name_prefix}-tg"
  port        = local.app_port
  protocol    = "HTTP"
  vpc_id      = aws_vpc.main.id
  target_type = "ip"

  health_check {
    enabled             = true
    path                = var.health_check_path
    protocol            = "HTTP"
    healthy_threshold   = 2
    unhealthy_threshold = 3
    timeout             = 5
    interval            = 30
  }
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.internal.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.self_signed.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.app.arn
  }
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.internal.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }
}

# ─── ECS Cluster ─────────────────────────────────────────────────────────────

resource "aws_ecs_cluster" "main" {
  name = "${local.name_prefix}-cluster"
}

# We need a CloudWatch log group so the execution role can write logs
resource "aws_cloudwatch_log_group" "app" {
  name              = "/ecs/${local.name_prefix}-app"
  retention_in_days = 14
}

# ─── IAM Roles for ECS ───────────────────────────────────────────────────────

resource "aws_iam_role" "ecs_execution" {
  name = "${local.name_prefix}-ecs-execution"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_execution_managed" {
  role       = aws_iam_role.ecs_execution.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_iam_role" "ecs_task" {
  name = "${local.name_prefix}-ecs-task"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# ─── ECS Task Definition ─────────────────────────────────────────────────────

resource "aws_ecs_task_definition" "app" {
  family                   = "${local.name_prefix}-app"
  requires_compatibilities = ["FARGATE"]
  network_mode             = "awsvpc"
  cpu                      = "256"
  memory                   = "512"
  execution_role_arn       = aws_iam_role.ecs_execution.arn
  task_role_arn            = aws_iam_role.ecs_task.arn

  container_definitions = jsonencode([
    {
      name      = "app"
      image     = "public.ecr.aws/nginx/nginx:latest"
      essential = true
      portMappings = [
        {
          containerPort = local.app_port
          hostPort      = local.app_port
          protocol      = "tcp"
        }
      ]
      environment = [
        {
          name  = "DATABASE_URL"
          value = "postgres://postgres:postgres@${aws_db_instance.postgres.address}:5432/mydb"
        },
        {
          name  = "PGUSER"
          value = "postgres"
        },
        {
          name  = "PGPASSWORD"
          value = "postgres"
        },
        {
          name  = "PGHOST"
          value = aws_db_instance.postgres.address
        },
        {
          name  = "PGPORT"
          value = "5432"
        },
        {
          name  = "PGDATABASE"
          value = "mydb"
        }
      ]
      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.app.name
          "awslogs-region"        = data.aws_region.current.region
          "awslogs-stream-prefix" = "ecs"
        }
      }
    }
  ])
}

# ─── ECS Service ─────────────────────────────────────────────────────────────

resource "aws_ecs_service" "app" {
  name            = "${local.name_prefix}-service"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.app.arn
  desired_count   = 2
  network_configuration {
    subnets         = aws_subnet.private[*].id
    security_groups = [aws_security_group.app.id]
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.app.arn
    container_name   = "app"
    container_port   = local.app_port
  }

  deployment_circuit_breaker {
    enable   = true
    rollback = true
  }

  capacity_provider_strategy {
    capacity_provider = "FARGATE"
    weight            = 20
    base             = 1
  }

  capacity_provider_strategy {
    capacity_provider = "FARGATE_SPOT"
    weight            = 80
  }

  lifecycle {
    ignore_changes = [task_definition, desired_count]
  }
}

# ─── Auto Scaling ────────────────────────────────────────────────────────────

resource "aws_appautoscaling_target" "ecs" {
  max_capacity       = 4
  min_capacity       = 2
  resource_id        = "service/${aws_ecs_cluster.main.name}/${aws_ecs_service.app.name}"
  scalable_dimension = "ecs:service:DesiredCount"
  service_namespace  = "ecs"
}

resource "aws_appautoscaling_policy" "cpu" {
  name               = "${local.name_prefix}-cpu-tracking"
  policy_type        = "TargetTrackingScaling"
  resource_id        = aws_appautoscaling_target.ecs.resource_id
  scalable_dimension = aws_appautoscaling_target.ecs.scalable_dimension
  service_namespace  = aws_appautoscaling_target.ecs.service_namespace

  target_tracking_scaling_policy_configuration {
    predefined_metric_specification {
      predefined_metric_type = "ECSServiceAverageCPUUtilization"
    }
    target_value = 70.0
  }
}

resource "aws_appautoscaling_policy" "memory" {
  name               = "${local.name_prefix}-memory-tracking"
  policy_type        = "TargetTrackingScaling"
  resource_id        = aws_appautoscaling_target.ecs.resource_id
  scalable_dimension = aws_appautoscaling_target.ecs.scalable_dimension
  service_namespace  = aws_appautoscaling_target.ecs.service_namespace

  target_tracking_scaling_policy_configuration {
    predefined_metric_specification {
      predefined_metric_type = "ECSServiceAverageMemoryUtilization"
    }
    target_value = 70.0
  }
}

# ─── IAM OIDC for GitHub Actions ────────────────────────────────────────────

resource "aws_iam_openid_connect_provider" "github" {
  url = "https://token.actions.githubusercontent.com"

  client_id_list = ["sts.amazonaws.com"]

  thumbprint_list = [
    "6938fd4d98bab03faadb97b34396831e3780aea1",
  ]
}

resource "aws_iam_role" "github_actions" {
  name = "${local.name_prefix}-github-actions"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = aws_iam_openid_connect_provider.github.arn
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringLike = {
            "token.actions.githubusercontent.com:sub" = "repo:${var.github_organization}/*"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "github_actions" {
  name = "${local.name_prefix}-github-actions"
  role = aws_iam_role.github_actions.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ecr:GetAuthorizationToken",
          "ecr:BatchCheckLayerAvailability",
          "ecr:BatchGetImage",
          "ecr:CompleteLayerUpload",
          "ecr:InitiateLayerUpload",
          "ecr:PutImage",
          "ecr:UploadLayerPart",
          "ecr:GetDownloadUrlForLayer",
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "ecr:BatchDeleteImage",
          "ecr:DescribeImages",
          "ecr:ListImages",
        ]
        Resource = aws_ecr_repository.app.arn
      },
      {
        Effect = "Allow"
        Action = [
          "ecs:RegisterTaskDefinition",
          "ecs:DescribeTaskDefinition",
          "ecs:DeregisterTaskDefinition",
          "ecs:ListTaskDefinitions",
          "ecs:UpdateService",
          "ecs:DescribeServices",
          "ecs:DescribeTasks",
          "ecs:ListTasks",
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "iam:PassRole"
        ]
        Resource = [
          aws_iam_role.ecs_execution.arn,
          aws_iam_role.ecs_task.arn
        ]
      }
    ]
  })
}

variable "cluster_tag" {
  description = "Tag used to namespace all HashiStack resources"
  type        = string
  default     = "default"
}

variable "enable_key_rotation" {
  description = "Enable annual KMS key rotation"
  type        = bool
  default     = false
}

variable "machine_roles" {
  description = "Map of role names to lists of policy identifier strings"
  type        = map(list(string))
  default     = {}
}

locals {
  secret_names = [
    "consul-agent-token",
    "consul-gossip-key",
    "nomad-client-consul-token",
    "nomad-gossip-key",
    "nomad-server-consul-token",
    "nomad-vault-token",
    "vault-consul-token",
  ]
}

# ---------------------------------------------------------------------------
# KMS key for Vault unsealing
# ---------------------------------------------------------------------------
resource "aws_kms_key" "vault_unseal" {
  description         = "resinstack:vault:seal:${var.cluster_tag}"
  enable_key_rotation = var.enable_key_rotation
  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Random passwords for Secrets Manager secrets
# ---------------------------------------------------------------------------
resource "random_password" "hashistack" {
  for_each = toset(local.secret_names)
  length   = 32
  special  = false
}

# ---------------------------------------------------------------------------
# Secrets Manager secrets and versions
# ---------------------------------------------------------------------------
resource "aws_secretsmanager_secret" "hashistack" {
  for_each = toset(local.secret_names)
  name     = "resinstack-${each.key}-${var.cluster_tag}"
  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "hashistack" {
  for_each      = toset(local.secret_names)
  secret_id     = aws_secretsmanager_secret.hashistack[each.key].id
  secret_string = random_password.hashistack[each.key].result
}

# ---------------------------------------------------------------------------
# IAM policy documents
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "vault_kms" {
  statement {
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:DescribeKey",
    ]
    resources = [
      aws_kms_key.vault_unseal.arn,
    ]
  }
}

data "aws_iam_policy_document" "read_tags" {
  statement {
    actions = [
      "ec2:DescribeInstances",
    ]
    resources = ["*"]
  }
}

data "aws_iam_policy_document" "client_keys" {
  statement {
    actions = [
      "secretsmanager:GetSecretValue",
    ]
    resources = [
      aws_secretsmanager_secret.hashistack["consul-agent-token"].arn,
      aws_secretsmanager_secret.hashistack["consul-gossip-key"].arn,
      aws_secretsmanager_secret.hashistack["nomad-client-consul-token"].arn,
    ]
  }
}

data "aws_iam_policy_document" "nomad_keys" {
  statement {
    actions = [
      "secretsmanager:GetSecretValue",
    ]
    resources = [
      aws_secretsmanager_secret.hashistack["consul-agent-token"].arn,
      aws_secretsmanager_secret.hashistack["consul-gossip-key"].arn,
      aws_secretsmanager_secret.hashistack["nomad-gossip-key"].arn,
      aws_secretsmanager_secret.hashistack["nomad-server-consul-token"].arn,
      aws_secretsmanager_secret.hashistack["nomad-vault-token"].arn,
    ]
  }
}

data "aws_iam_policy_document" "consul_keys" {
  statement {
    actions = [
      "secretsmanager:GetSecretValue",
    ]
    resources = [
      aws_secretsmanager_secret.hashistack["consul-gossip-key"].arn,
    ]
  }
}

data "aws_iam_policy_document" "vault_keys" {
  statement {
    actions = [
      "secretsmanager:GetSecretValue",
    ]
    resources = [
      aws_secretsmanager_secret.hashistack["consul-gossip-key"].arn,
      aws_secretsmanager_secret.hashistack["vault-consul-token"].arn,
    ]
  }
}

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

# ---------------------------------------------------------------------------
# IAM policies
# ---------------------------------------------------------------------------
resource "aws_iam_policy" "vault_kms" {
  name   = "resinstack-vault-kms-${var.cluster_tag}"
  policy = data.aws_iam_policy_document.vault_kms.json
}

resource "aws_iam_policy" "read_tags" {
  name   = "resinstack-read-tags-${var.cluster_tag}"
  policy = data.aws_iam_policy_document.read_tags.json
}

resource "aws_iam_policy" "client_keys" {
  name   = "resinstack-client-keys-${var.cluster_tag}"
  policy = data.aws_iam_policy_document.client_keys.json
}

resource "aws_iam_policy" "nomad_keys" {
  name   = "resinstack-nomad-keys-${var.cluster_tag}"
  policy = data.aws_iam_policy_document.nomad_keys.json
}

resource "aws_iam_policy" "consul_keys" {
  name   = "resinstack-consul-keys-${var.cluster_tag}"
  policy = data.aws_iam_policy_document.consul_keys.json
}

resource "aws_iam_policy" "vault_keys" {
  name   = "resinstack-vault-keys-${var.cluster_tag}"
  policy = data.aws_iam_policy_document.vault_keys.json
}

# ---------------------------------------------------------------------------
# Machine roles – dynamically created from machine_roles variable
# ---------------------------------------------------------------------------
resource "aws_iam_role" "machine" {
  for_each              = var.machine_roles
  name                  = "resinstack-${each.key}-${var.cluster_tag}"
  assume_role_policy    = data.aws_iam_policy_document.ec2_assume_role.json
  max_session_duration  = 43200
  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
}

# ---------------------------------------------------------------------------
# Instance profiles – one per machine role
# ---------------------------------------------------------------------------
resource "aws_iam_instance_profile" "machine" {
  for_each = var.machine_roles
  name     = "resinstack-${each.key}-${var.cluster_tag}"
  role     = aws_iam_role.machine[each.key].name
}

# ---------------------------------------------------------------------------
# Policy-to-role attachments – conditionally attached based on identifiers
# ---------------------------------------------------------------------------
resource "aws_iam_role_policy_attachment" "read_tags" {
  for_each   = { for r, ids in var.machine_roles : r => r if contains(ids, "read-tags") }
  role       = aws_iam_role.machine[each.key].name
  policy_arn = aws_iam_policy.read_tags.arn
}

resource "aws_iam_role_policy_attachment" "vault_kms" {
  for_each   = { for r, ids in var.machine_roles : r => r if contains(ids, "vault-kms") }
  role       = aws_iam_role.machine[each.key].name
  policy_arn = aws_iam_policy.vault_kms.arn
}

resource "aws_iam_role_policy_attachment" "client_keys" {
  for_each   = { for r, ids in var.machine_roles : r => r if contains(ids, "client-keys") }
  role       = aws_iam_role.machine[each.key].name
  policy_arn = aws_iam_policy.client_keys.arn
}

resource "aws_iam_role_policy_attachment" "nomad_keys" {
  for_each   = { for r, ids in var.machine_roles : r => r if contains(ids, "nomad-keys") }
  role       = aws_iam_role.machine[each.key].name
  policy_arn = aws_iam_policy.nomad_keys.arn
}

resource "aws_iam_role_policy_attachment" "consul_keys" {
  for_each   = { for r, ids in var.machine_roles : r => r if contains(ids, "consul-keys") }
  role       = aws_iam_role.machine[each.key].name
  policy_arn = aws_iam_policy.consul_keys.arn
}

resource "aws_iam_role_policy_attachment" "vault_keys" {
  for_each   = { for r, ids in var.machine_roles : r => r if contains(ids, "vault-keys") }
  role       = aws_iam_role.machine[each.key].name
  policy_arn = aws_iam_policy.vault_keys.arn
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------
output "vault_kms_key_id" {
  description = "ARN of the KMS key used for Vault unsealing"
  value       = aws_kms_key.vault_unseal.arn
}

output "secret_names" {
  description = "Map of logical secret names to Secrets Manager secret names"
  value = {
    for k, v in aws_secretsmanager_secret.hashistack : k => v.name
  }
}

output "machine_role_names" {
  description = "Map of machine role names to IAM role names"
  value = {
    for k, v in aws_iam_role.machine : k => v.name
  }
}

output "instance_profile_names" {
  description = "Map of machine role names to instance profile names"
  value = {
    for k, v in aws_iam_instance_profile.machine : k => v.name
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

variable "environment_prefix" {
  description = "Prefix applied to resource tags and names."
  type        = string
  default     = "elluis_codes_limited_network"
}

variable "az_offset_map" {
  description = "Explicit map of availability zones to 8-bit CIDR offset values. Leave empty to auto-select the first three available zones in the region with offsets 11, 22, and 33."
  type        = map(number)
  default     = {}
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_cidr = "64.0.0.0/16"
  az_offset_map = length(var.az_offset_map) > 0 ? var.az_offset_map : {
    for idx, az in data.aws_availability_zones.available.names : az => 11 + (idx * 11) if idx < 3
  }
}

# ---------------------------------------------------------------------------
# VPC
# ---------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = true
  # ClassicLink is disabled by default and cannot be enabled on newly created VPCs.

  tags = {
    Name = "${var.environment_prefix}-vpc"
  }
}

# ---------------------------------------------------------------------------
# Subnets (one public + one private per availability zone, 8-bit CIDR offsets)
# ---------------------------------------------------------------------------
resource "aws_subnet" "public" {
  for_each                = local.az_offset_map
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, each.value)
  availability_zone       = each.key
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.environment_prefix}-public-${each.key}"
  }
}

resource "aws_subnet" "private" {
  for_each                = local.az_offset_map
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, each.value + 128)
  availability_zone       = each.key
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.environment_prefix}-private-${each.key}"
  }
}

# ---------------------------------------------------------------------------
# Internet Gateway + public route table
# ---------------------------------------------------------------------------
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.environment_prefix}-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.environment_prefix}-public-rt"
  }
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  for_each       = aws_subnet.public
  subnet_id      = each.value.id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# Elastic IP + NAT Gateway per availability zone
# ---------------------------------------------------------------------------
resource "aws_eip" "nat" {
  for_each = local.az_offset_map
  domain   = "vpc"

  tags = {
    Name = "${var.environment_prefix}-eip-${each.key}"
  }
}

resource "aws_nat_gateway" "az" {
  for_each      = local.az_offset_map
  allocation_id = aws_eip.nat[each.key].id
  subnet_id     = aws_subnet.public[each.key].id

  tags = {
    Name = "${var.environment_prefix}-nat-${each.key}"
  }

  lifecycle {
    ignore_changes = [allocation_id, subnet_id]
  }
}

# ---------------------------------------------------------------------------
# Dedicated private route table per availability zone
# ---------------------------------------------------------------------------
resource "aws_route_table" "private" {
  for_each = local.az_offset_map
  vpc_id   = aws_vpc.main.id

  tags = {
    Name = "${var.environment_prefix}-private-rt-${each.key}"
  }
}

resource "aws_route" "private_nat" {
  for_each               = local.az_offset_map
  route_table_id         = aws_route_table.private[each.key].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.az[each.key].id
}

resource "aws_route_table_association" "private" {
  for_each       = local.az_offset_map
  subnet_id      = aws_subnet.private[each.key].id
  route_table_id = aws_route_table.private[each.key].id

  lifecycle {
    ignore_changes = [subnet_id]
  }
}

variable "creation_token" {
  description = "Creation token for the EFS file system"
  type        = string
  default     = "test-efs"
}

variable "performance_mode" {
  description = "Performance mode for the EFS file system (generalPurpose or maxIO)"
  type        = string
  default     = "generalPurpose"
}

variable "throughput_mode" {
  description = "Throughput mode for the EFS file system (bursting or provisioned)"
  type        = string
  default     = "bursting"
}

variable "subnet_ids" {
  description = "List of subnet IDs for EFS mount targets. When null, defaults to subnets created inside the configuration."
  type        = list(string)
  default     = null
}

variable "security_group_ids" {
  description = "List of security group IDs for EFS mount targets. When null, defaults to the security group created inside the configuration."
  type        = list(string)
  default     = null
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  az_count                    = min(length(data.aws_availability_zones.available.names), 3)
  effective_subnet_ids        = var.subnet_ids != null ? var.subnet_ids : aws_subnet.main[*].id
  effective_security_group_ids = var.security_group_ids != null ? var.security_group_ids : [aws_security_group.efs.id]
}

resource "aws_kms_key" "efs" {
  description             = "KMS key for EFS file system encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = {
    Name = "efs-encryption-key"
  }
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "efs-vpc"
  }
}

resource "aws_subnet" "main" {
  count = local.az_count

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet("10.0.0.0/16", 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "efs-subnet-${count.index + 1}"
  }
}

resource "aws_security_group" "efs" {
  name        = "efs-mount-targets-sg"
  description = "Security group for EFS mount targets"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "NFS from VPC"
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "efs-mount-targets-sg"
  }
}

resource "aws_efs_file_system" "shared" {
  creation_token   = var.creation_token
  performance_mode = var.performance_mode
  throughput_mode  = var.throughput_mode
  encrypted        = true
  kms_key_id       = aws_kms_key.efs.arn

  lifecycle_policy {
    transition_to_ia = "AFTER_30_DAYS"
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "shared-encrypted-efs"
  }
}

resource "aws_efs_mount_target" "main" {
  for_each = { for idx, id in local.effective_subnet_ids : idx => id }

  file_system_id  = aws_efs_file_system.shared.id
  subnet_id       = each.value
  security_groups = local.effective_security_group_ids
}

terraform {
  required_version = ">= 1.3"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

variable "user_name" {
  description = "Name of the IAM user for cert-manager"
  type        = string
  default     = "cert-manager"
}

variable "hosted_zone_id" {
  description = "ID of the Route 53 hosted zone to grant DNS record permissions for"
  type        = string
  default     = "*"
}

data "aws_iam_policy_document" "cert_manager_route53" {
  statement {
    sid    = "GetChange"
    effect = "Allow"
    actions = [
      "route53:GetChange",
    ]
    resources = [
      "arn:aws:route53:::change/*",
    ]
  }

  statement {
    sid    = "ManageResourceRecordSets"
    effect = "Allow"
    actions = [
      "route53:ChangeResourceRecordSets",
      "route53:ListResourceRecordSets",
    ]
    resources = [
      "arn:aws:route53:::hostedzone/${var.hosted_zone_id}",
    ]
  }

  statement {
    sid    = "ListHostedZonesByName"
    effect = "Allow"
    actions = [
      "route53:ListHostedZonesByName",
    ]
    resources = [
      "*",
    ]
  }
}

resource "aws_iam_policy" "cert_manager_route53" {
  name        = "${var.user_name}-route53-policy"
  description = "Route 53 policy for cert-manager DNS challenges"
  policy      = data.aws_iam_policy_document.cert_manager_route53.json
}

resource "aws_iam_user" "cert_manager" {
  name = var.user_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_access_key" "cert_manager" {
  user = aws_iam_user.cert_manager.name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ssm_parameter" "access_key" {
  name  = "/cert-manager/access-key"
  type  = "SecureString"
  value = aws_iam_access_key.cert_manager.id

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ssm_parameter" "secret_key" {
  name  = "/cert-manager/secret-key"
  type  = "SecureString"
  value = aws_iam_access_key.cert_manager.secret

  lifecycle {
    prevent_destroy = true
  }
}

# =============================================================================
# Amazon GuardDuty Threat Detection & Findings Export Infrastructure
# =============================================================================

terraform {
  required_version = ">= 1.3, < 2.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 6.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
    null = {
      source  = "hashicorp/null"
      version = ">= 3.0"
    }
  }
}

# ---------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------

variable "enable_detector" {
  description = "Enable the primary GuardDuty detector"
  type        = bool
  default     = true
}

variable "enable_s3_logs" {
  description = "Enable S3 logs data source in GuardDuty"
  type        = bool
  default     = true
}

variable "enable_kubernetes_audit_logs" {
  description = "Enable Kubernetes audit logs data source in GuardDuty"
  type        = bool
  default     = false
}

variable "enable_ec2_malware_scanning" {
  description = "Enable EC2 malware scanning in GuardDuty"
  type        = bool
  default     = false
}

variable "finding_publishing_frequency" {
  description = "Frequency for publishing GuardDuty findings"
  type        = string
  default     = "FIFTEEN_MINUTES"

  validation {
    condition     = contains(["FIFTEEN_MINUTES", "ONE_HOUR", "SIX_HOURS"], var.finding_publishing_frequency)
    error_message = "Allowed values: FIFTEEN_MINUTES, ONE_HOUR, SIX_HOURS"
  }
}

variable "snapshot_retention_toggle" {
  description = "Enable EBS snapshot retention with findings"
  type        = bool
  default     = false
}

variable "enable_ip_sets" {
  description = "Enable IP sets (triggers supporting infrastructure)"
  type        = bool
  default     = false
}

variable "enable_threat_intel_sets" {
  description = "Enable threat intelligence sets (triggers supporting infrastructure)"
  type        = bool
  default     = false
}

variable "enable_s3_publishing" {
  description = "Enable S3 publishing destination (triggers supporting infrastructure)"
  type        = bool
  default     = false
}

variable "replica_region" {
  description = "AWS region for the replica S3 bucket"
  type        = string
  default     = "us-west-2"
}

variable "ip_sets" {
  description = "List of IP sets to create"
  type = list(object({
    name     = string
    format   = string
    location = string
    activate = optional(bool, true)
  }))
  default = []
}

variable "threat_intel_sets" {
  description = "List of threat intelligence sets to create"
  type = list(object({
    name     = string
    format   = string
    location = string
    activate = optional(bool, true)
  }))
  default = []
}

variable "finding_filters" {
  description = "List of finding filters to create"
  type = list(object({
    name     = string
    action   = string
    rank     = optional(number, 1)
    field    = string
    equals   = optional(list(string), [])
    matches  = optional(list(string), [])
  }))
  default = []
}

variable "publishing_destinations" {
  description = "List of custom S3 publishing destinations"
  type = list(object({
    destination_arn = string
    kms_key_arn     = string
  }))
  default = []
}

# ---------------------------------------------------------------------------
# DATA SOURCES  (static metadata lookups only)
# ---------------------------------------------------------------------------

data "aws_partition" "current" {}
data "aws_caller_identity" "current" {}

# ---------------------------------------------------------------------------
# RANDOM SUFFIX FOR UNIQUE GLOBAL NAMES
# ---------------------------------------------------------------------------

resource "random_string" "suffix" {
  length  = 8
  special = false
  upper   = false
}

# ---------------------------------------------------------------------------
# LOCALS
# ---------------------------------------------------------------------------

locals {
  has_ip_sets        = length(var.ip_sets) > 0 || var.enable_ip_sets
  has_threat_intel   = length(var.threat_intel_sets) > 0 || var.enable_threat_intel_sets
  has_s3_publishing  = length(var.publishing_destinations) > 0 || var.enable_s3_publishing
  enable_supporting_infra = local.has_ip_sets || local.has_threat_intel || local.has_s3_publishing
  partition = data.aws_partition.current.partition
}

# ---------------------------------------------------------------------------
# CROSS-REGION PROVIDER  (for replica S3 bucket)
# ---------------------------------------------------------------------------

provider "aws" {
  alias  = "replica"
  region = var.replica_region
}

# ============================================================================
#  GUARDDUTY DETECTOR
# ============================================================================

resource "aws_guardduty_detector" "primary" {
  enable                        = var.enable_detector
  finding_publishing_frequency  = var.finding_publishing_frequency

  datasources {
    s3_logs {
      enable = var.enable_s3_logs
    }
    kubernetes {
      audit_logs {
        enable = var.enable_kubernetes_audit_logs
      }
    }
    malware_protection {
      scan_ec2_instance_with_findings {
        ebs_volumes {
          enable = var.enable_ec2_malware_scanning
        }
      }
    }
  }
}

# ============================================================================
#  EBS SNAPSHOT PRESERVATION  (local-exec provisioner)
# ============================================================================

resource "null_resource" "ebs_snapshot_preservation" {
  triggers = {
    detector_id = aws_guardduty_detector.primary.id
    toggle      = tostring(var.snapshot_retention_toggle)
  }

  provisioner "local-exec" {
    command = "VALUE='${var.snapshot_retention_toggle ? "RETENTION_WITH_FINDING" : "NO_RETENTION"}' && aws guardduty update-organization-configuration --detector-id '${aws_guardduty_detector.primary.id}' 2>/dev/null; echo \"EBS snapshot preservation desired: $VALUE (set via AWS Console if CLI unavailable)\""
  }
}

# ============================================================================
#  GUARDDUTY FINDING FILTERS
# ============================================================================

resource "aws_guardduty_filter" "this" {
  count = length(var.finding_filters)

  detector_id = aws_guardduty_detector.primary.id
  name        = var.finding_filters[count.index].name
  action      = var.finding_filters[count.index].action
  rank        = var.finding_filters[count.index].rank

  finding_criteria {
    criterion {
      field   = var.finding_filters[count.index].field
      equals  = var.finding_filters[count.index].equals
      matches = var.finding_filters[count.index].matches
    }
  }
}

# ============================================================================
#  GUARDDUTY IP SETS
# ============================================================================

resource "aws_guardduty_ipset" "this" {
  count = length(var.ip_sets)

  detector_id = aws_guardduty_detector.primary.id
  name        = var.ip_sets[count.index].name
  format      = var.ip_sets[count.index].format
  location    = var.ip_sets[count.index].location
  activate    = var.ip_sets[count.index].activate
}

# ============================================================================
#  GUARDDUTY THREAT INTELLIGENCE SETS
# ============================================================================

resource "aws_guardduty_threatintelset" "this" {
  count = length(var.threat_intel_sets)

  detector_id = aws_guardduty_detector.primary.id
  name        = var.threat_intel_sets[count.index].name
  format      = var.threat_intel_sets[count.index].format
  location    = var.threat_intel_sets[count.index].location
  activate    = var.threat_intel_sets[count.index].activate
}

# ============================================================================
#  GUARDDUTY PUBLISHING DESTINATIONS  (user-provided destinations)
# ============================================================================

resource "aws_guardduty_publishing_destination" "this" {
  count = length(var.publishing_destinations)

  detector_id      = aws_guardduty_detector.primary.id
  destination_type = "S3"
  destination_arn  = var.publishing_destinations[count.index].destination_arn
  kms_key_arn      = var.publishing_destinations[count.index].kms_key_arn
}

# Auto-created publishing destination when S3 publishing is enabled
resource "null_resource" "publishing_destination" {
  count = var.enable_s3_publishing ? 1 : 0

  triggers = {
    detector_id      = aws_guardduty_detector.primary.id
    destination_arn  = "arn:${local.partition}:s3:::${aws_s3_bucket.guardduty_primary[0].id}"
    kms_key_arn      = aws_kms_key.guardduty[0].arn
  }

  provisioner "local-exec" {
    command = <<-EOF
      aws guardduty create-publishing-destination \
        --detector-id "${aws_guardduty_detector.primary.id}" \
        --destination-type "S3" \
        --destination-arn "arn:${local.partition}:s3:::${aws_s3_bucket.guardduty_primary[0].id}" \
        --kms-key-arn "${aws_kms_key.guardduty[0].arn}" \
        --publish-frequency "${var.finding_publishing_frequency}" 2>/dev/null || \
      echo "Publishing destination creation failed - create manually via AWS Console."
    EOF
  }
}

# ============================================================================
#  SUPPORTING INFRASTRUCTURE  (created when IP sets, threat intel, or S3
#  publishing is enabled)
# ============================================================================

# ---------------------------------------------------------------------------
#  KMS KEY  — multi-region, auto-rotation, 7-day deletion window
# ---------------------------------------------------------------------------

resource "aws_kms_key" "guardduty" {
  count = local.enable_supporting_infra ? 1 : 0

  description             = "GuardDuty multi-region encryption key"
  deletion_window_in_days = 7
  is_enabled              = true
  enable_key_rotation     = true
  rotation_period_in_days = 365

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = ["kms:*"]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Principal = {
          Service = "guardduty.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name        = "guardduty-encryption-key"
    Environment = "production"
  }
}

# ---------------------------------------------------------------------------
#  S3 LOG BUCKET  — dedicated bucket for server-side access logs
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "guardduty_logs" {
  count = local.enable_supporting_infra ? 1 : 0

  bucket        = "guardduty-logs-${random_string.suffix.result}"
  force_destroy = true

  tags = {
    Name        = "guardduty-access-logs"
    Environment = "production"
  }
}

resource "aws_s3_bucket_public_access_block" "guardduty_logs" {
  count = local.enable_supporting_infra ? 1 : 0

  bucket = aws_s3_bucket.guardduty_logs[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "guardduty_logs" {
  count = local.enable_supporting_infra ? 1 : 0

  bucket = aws_s3_bucket.guardduty_logs[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# ---------------------------------------------------------------------------
#  S3 PRIMARY BUCKET  — versioned, KMS-encrypted, logged
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "guardduty_primary" {
  count = local.enable_supporting_infra ? 1 : 0

  bucket        = "guardduty-primary-${random_string.suffix.result}"
  force_destroy = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = "s3:*"
        Resource = [
          "arn:${local.partition}:s3:::guardduty-primary-${random_string.suffix.result}",
          "arn:${local.partition}:s3:::guardduty-primary-${random_string.suffix.result}/*"
        ]
      },
      {
        Effect = "Allow"
        Principal = {
          Service = "guardduty.amazonaws.com"
        }
        Action = "s3:PutObject"
        Resource = [
          "arn:${local.partition}:s3:::guardduty-primary-${random_string.suffix.result}",
          "arn:${local.partition}:s3:::guardduty-primary-${random_string.suffix.result}/*"
        ]
      }
    ]
  })

  logging {
    target_bucket = aws_s3_bucket.guardduty_logs[0].id
    target_prefix = "access-logs/"
  }

  tags = {
    Name        = "guardduty-findings"
    Environment = "production"
  }
}

resource "aws_s3_bucket_versioning" "guardduty_primary" {
  count = local.enable_supporting_infra ? 1 : 0

  bucket = aws_s3_bucket.guardduty_primary[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "guardduty_primary" {
  count = local.enable_supporting_infra ? 1 : 0

  bucket = aws_s3_bucket.guardduty_primary[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "guardduty_primary" {
  count = local.enable_supporting_infra ? 1 : 0

  bucket = aws_s3_bucket.guardduty_primary[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# ---------------------------------------------------------------------------
#  IAM REPLICATION ROLE & POLICY
# ---------------------------------------------------------------------------

resource "aws_iam_role" "replication" {
  count = local.enable_supporting_infra ? 1 : 0

  name        = "guardduty-s3-replication-${random_string.suffix.result}"
  description = "IAM role for S3 Replication Time Control"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name        = "guardduty-replication-role"
    Environment = "production"
  }
}

resource "aws_iam_role_policy" "replication" {
  count = local.enable_supporting_infra ? 1 : 0

  name = "guardduty-s3-replication-policy-${random_string.suffix.result}"
  role = aws_iam_role.replication[0].name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateTags"
        ]
        Resource = [
          "arn:${local.partition}:s3:::${aws_s3_bucket.guardduty_replica[0].id}",
          "arn:${local.partition}:s3:::${aws_s3_bucket.guardduty_replica[0].id}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:GetObjectVersionForReplication"
        ]
        Resource = [
          "arn:${local.partition}:s3:::${aws_s3_bucket.guardduty_primary[0].id}",
          "arn:${local.partition}:s3:::${aws_s3_bucket.guardduty_primary[0].id}/*"
        ]
      }
    ]
  })
}

# ---------------------------------------------------------------------------
#  S3 REPLICA BUCKET  (in replica region)
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "guardduty_replica" {
  provider = aws.replica
  count    = local.enable_supporting_infra ? 1 : 0

  bucket        = "guardduty-replica-${random_string.suffix.result}"
  force_destroy = true

  tags = {
    Name        = "guardduty-replica"
    Environment = "production"
  }
}

resource "aws_s3_bucket_versioning" "guardduty_replica" {
  provider = aws.replica
  count    = local.enable_supporting_infra ? 1 : 0

  bucket = aws_s3_bucket.guardduty_replica[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "guardduty_replica" {
  provider = aws.replica
  count    = local.enable_supporting_infra ? 1 : 0

  bucket = aws_s3_bucket.guardduty_replica[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "guardduty_replica" {
  provider = aws.replica
  count    = local.enable_supporting_infra ? 1 : 0

  bucket = aws_s3_bucket.guardduty_replica[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# ---------------------------------------------------------------------------
#  S3 REPLICATION CONFIGURATION  — via local-exec for cross-region SRTC
#  Terraform provider has limitations with cross-region destination ARN
# ---------------------------------------------------------------------------

resource "null_resource" "s3_replication_config" {
  count = local.enable_supporting_infra ? 1 : 0

  triggers = {
    rule_id         = "guardduty-replication-rule"
    primary_bucket  = aws_s3_bucket.guardduty_primary[0].id
    replica_bucket  = aws_s3_bucket.guardduty_replica[0].id
    role_arn        = aws_iam_role.replication[0].arn
  }

  provisioner "local-exec" {
    command = <<-EOF
      aws s3api put-bucket-replication-configuration \
        --bucket "${aws_s3_bucket.guardduty_primary[0].id}" \
        --replication-configuration '{
          "Role": "${aws_iam_role.replication[0].arn}",
          "Rules": [
            {
              "Id": "guardduty-replication-rule",
              "Priority": 1,
              "Status": "Enabled",
              "Destination": {
                "Bucket": "${aws_s3_bucket.guardduty_replica[0].id}",
                "Region": "${var.replica_region}",
                "ReplicationTimeControl": {
                  "TimeThreshold": {
                    "15Minutes": true
                  }
                }
              }
            }
          ]
        }' 2>/dev/null || \
      echo "S3 Replication via CLI not available; configure manually via AWS Console."
    EOF
  }
}

variable "name_prefix" {
  description = "Name prefix applied to all IAM resources created by this configuration."
  type        = string
  default     = "imputation-example"
}

variable "tags" {
  description = "A map of tags to apply to all resources."
  type        = map(string)
  default     = {}
}

data "aws_partition" "current" {}

locals {
  common_tags = var.tags
}

# ---------------------------------------------------------------------------
# EMR service role
# ---------------------------------------------------------------------------
resource "aws_iam_role" "emr_service_role" {
  name = "${var.name_prefix}-emr-role"
  path = "/"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "elasticmapreduce.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-emr-role"
  })
}

resource "aws_iam_role_policy_attachment" "emr_service_role_policy" {
  role       = aws_iam_role.emr_service_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonEMRServicePolicy_v2"
}

# ---------------------------------------------------------------------------
# EC2 instance profile role (CloudWatch + SSM policies)
# ---------------------------------------------------------------------------
resource "aws_iam_role" "ec2_instance_role" {
  name = "${var.name_prefix}-ec2-role"
  path = "/"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-ec2-role"
  })
}

resource "aws_iam_role_policy_attachment" "ec2_cloudwatch_policy" {
  role       = aws_iam_role.ec2_instance_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/CloudWatchAgentServerPolicy"
}

resource "aws_iam_role_policy_attachment" "ec2_ssm_policy" {
  role       = aws_iam_role.ec2_instance_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

# ---------------------------------------------------------------------------
# EMR autoscaling role
# ---------------------------------------------------------------------------
resource "aws_iam_role" "autoscaling_role" {
  name = "${var.name_prefix}-autoscaling-role"
  path = "/"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = [
            "elasticmapreduce.amazonaws.com",
            "application-autoscaling.amazonaws.com",
          ]
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-autoscaling-role"
  })
}

resource "aws_iam_role_policy_attachment" "autoscaling_role_policy" {
  role       = aws_iam_role.autoscaling_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonElasticMapReduceforAutoScalingRole"
}

# ---------------------------------------------------------------------------
# EC2 instance profile for EMR cluster instances
# ---------------------------------------------------------------------------
resource "aws_iam_instance_profile" "emr_instance_profile" {
  name = "${var.name_prefix}-emr-instance-profile"
  role = aws_iam_role.ec2_instance_role.name
  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-emr-instance-profile"
  })
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------
output "emr_service_role_arn" {
  description = "ARN of the EMR service role."
  value       = aws_iam_role.emr_service_role.arn
}

output "emr_service_role_name" {
  description = "Name of the EMR service role."
  value       = aws_iam_role.emr_service_role.name
}

output "emr_service_role_unique_id" {
  description = "Unique ID of the EMR service role."
  value       = aws_iam_role.emr_service_role.unique_id
}

output "emr_ec2_instance_role_arn" {
  description = "ARN of the EC2 instance profile role used by EMR."
  value       = aws_iam_role.ec2_instance_role.arn
}

output "emr_ec2_instance_role_name" {
  description = "Name of the EC2 instance profile role used by EMR."
  value       = aws_iam_role.ec2_instance_role.name
}

output "emr_ec2_instance_role_unique_id" {
  description = "Unique ID of the EC2 instance profile role used by EMR."
  value       = aws_iam_role.ec2_instance_role.unique_id
}

output "emr_autoscaling_role_arn" {
  description = "ARN of the EMR autoscaling role."
  value       = aws_iam_role.autoscaling_role.arn
}

output "emr_autoscaling_role_name" {
  description = "Name of the EMR autoscaling role."
  value       = aws_iam_role.autoscaling_role.name
}

output "emr_autoscaling_role_unique_id" {
  description = "Unique ID of the EMR autoscaling role."
  value       = aws_iam_role.autoscaling_role.unique_id
}

output "emr_instance_profile_id" {
  description = "ID of the EC2 instance profile used by EMR."
  value       = aws_iam_instance_profile.emr_instance_profile.id
}

output "emr_instance_profile_arn" {
  description = "ARN of the EC2 instance profile used by EMR."
  value       = aws_iam_instance_profile.emr_instance_profile.arn
}

output "emr_instance_profile_name" {
  description = "Name of the EC2 instance profile used by EMR."
  value       = aws_iam_instance_profile.emr_instance_profile.name
}

variable "cognito_user_pool_arn" {
  description = "Optional ARN of a Cognito user pool. When non-empty, an IAM policy granting cognito-idp:AdminInitiateAuth scoped to this pool is created and attached."
  type        = string
  default     = ""
}

variable "user_name" {
  description = "Name of the IAM user to create"
  type        = string
  default     = "postman-user"
}

# ---------------------------------------------------------------------------
# IAM user
# ---------------------------------------------------------------------------
resource "aws_iam_user" "postman" {
  name = var.user_name
  path = "/"
}

# ---------------------------------------------------------------------------
# Access key pair for the user
# ---------------------------------------------------------------------------
resource "aws_iam_access_key" "postman" {
  user = aws_iam_user.postman.name
}

# ---------------------------------------------------------------------------
# Inline policy: read-only access to API Gateway (GET)
# ---------------------------------------------------------------------------
resource "aws_iam_user_policy" "api_gateway_read_only" {
  name   = "api-gateway-read-only"
  user   = aws_iam_user.postman.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["apigateway:GET"]
        Resource = "*"
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# Inline policy: read-only access to CloudWatch Metrics
# ---------------------------------------------------------------------------
resource "aws_iam_user_policy" "cloudwatch_metrics" {
  name   = "cloudwatch-metrics-read-only"
  user   = aws_iam_user.postman.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "cloudwatch:GetMetricData",
          "cloudwatch:ListMetrics"
        ]
        Resource = "*"
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# Optional inline policy: Cognito AdminInitiateAuth on the supplied pool ARN
# Created only when var.cognito_user_pool_arn is a non-empty string.
# ---------------------------------------------------------------------------
resource "aws_iam_user_policy" "cognito_admin_initiate_auth" {
  count = var.cognito_user_pool_arn != "" ? 1 : 0

  name   = "cognito-admin-initiate-auth"
  user   = aws_iam_user.postman.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["cognito-idp:AdminInitiateAuth"]
        Resource = var.cognito_user_pool_arn
      }
    ]
  })
}

variable "cluster_name" {
  description = "Name of the EKS cluster"
  type        = string
  default     = "legion"
}

data "aws_partition" "current" {}

locals {
  master_role_name      = "tf-${var.cluster_name}"
  worker_role_name      = "tf-${var.cluster_name}-node"
  autoscaling_policy_name = "eks-worker-autoscaling-${var.cluster_name}"
}

# ---------------------------------------------------------------------------
# Master IAM Role – EKS control plane
# ---------------------------------------------------------------------------
resource "aws_iam_role" "master" {
  name = local.master_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "master_eks_cluster" {
  role       = aws_iam_role.master.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "master_eks_service" {
  role       = aws_iam_role.master.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSServicePolicy"
}

# ---------------------------------------------------------------------------
# Worker Node IAM Role
# ---------------------------------------------------------------------------
resource "aws_iam_role" "worker" {
  name = local.worker_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "worker_eks_node" {
  role       = aws_iam_role.worker.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "worker_eks_cni" {
  role       = aws_iam_role.worker.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKS_CNI_Policy"
}

resource "aws_iam_role_policy_attachment" "worker_ec2_readonly" {
  role       = aws_iam_role.worker.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

# ---------------------------------------------------------------------------
# EC2 Instance Profile (associated with the worker role)
# ---------------------------------------------------------------------------
resource "aws_iam_instance_profile" "worker" {
  name = local.worker_role_name
  role = local.worker_role_name
}

# ---------------------------------------------------------------------------
# Custom Cluster Autoscaler Policy
# ---------------------------------------------------------------------------
resource "aws_iam_policy" "autoscaling" {
  name        = local.autoscaling_policy_name
  description = "EKS Cluster Autoscaler integration policy for worker nodes"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "autoscaling:DescribeAutoScalingGroups",
          "autoscaling:DescribeAutoScalingInstances",
          "autoscaling:DescribeLaunchConfigurations",
          "autoscaling:DescribeTags",
          "autoscaling:DescribeLaunchTemplateVersions"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "autoscaling:SetDesiredCapacity",
          "autoscaling:TerminateInstanceInAutoScalingGroup",
          "autoscaling:UpdateAutoScalingGroup"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:ResourceTag/kubernetes.io/cluster/${var.cluster_name}" = "owned"
            "aws:ResourceTag/k8s.io/cluster-autoscaler/enabled"        = "true"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "worker_autoscaling" {
  role       = aws_iam_role.worker.name
  policy_arn = aws_iam_policy.autoscaling.arn
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "172.69.0.0/16"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet"
  type        = string
  default     = "172.69.1.0/24"
}

variable "private_subnet_cidr" {
  description = "CIDR block for the private subnet"
  type        = string
  default     = "172.69.2.0/24"
}

variable "web_server_ingress_rules" {
  description = "Dynamic ingress rules for the web server security group"
  type = list(object({
    description = string
    from_port   = number
    to_port     = number
    protocol    = string
    cidr_blocks = list(string)
  }))
  default = [
    {
      description = "HTTP from anywhere"
      from_port   = 80
      to_port     = 80
      protocol    = "tcp"
      cidr_blocks = ["0.0.0.0/0"]
    },
    {
      description = "SSH from VPC CIDR"
      from_port   = 22
      to_port     = 22
      protocol    = "tcp"
      cidr_blocks = ["172.69.0.0/16"]
    },
  ]
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "vpc_name"
  }
}

resource "aws_subnet" "public" {
  vpc_id     = aws_vpc.main.id
  cidr_block = var.public_subnet_cidr

  tags = {
    Name = "public_subnet"
  }
}

resource "aws_subnet" "private" {
  vpc_id     = aws_vpc.main.id
  cidr_block = var.private_subnet_cidr

  tags = {
    Name = "private_subnet"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "igw_tag"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "rtb_tag"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "web_server" {
  name        = "webserver-sg_${aws_vpc.main.id}"
  description = "Security group for web servers"
  vpc_id      = aws_vpc.main.id

  dynamic "ingress" {
    for_each = var.web_server_ingress_rules
    content {
      description = ingress.value.description
      from_port   = ingress.value.from_port
      to_port     = ingress.value.to_port
      protocol    = ingress.value.protocol
      cidr_blocks = ingress.value.cidr_blocks
    }
  }

  egress {
    description = "Outbound traffic limited to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "web-server_security_group"
  }
}

resource "aws_security_group" "database" {
  name        = "database-sg_${aws_vpc.main.id}"
  description = "Security group for database servers"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "MySQL from web server security group"
    from_port       = 3306
    to_port         = 3306
    protocol        = "tcp"
    security_groups = [aws_security_group.web_server.id]
  }

  tags = {
    Name = "database-security_group"
  }
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

variable "tags" {
  description = "A map of tags to apply to all resources"
  type        = map(string)
  default     = {}
}

locals {
  controlplane_name = "aws_ccm_k8s_controlplane"
  worker_name       = "aws_ccm_k8s_worker"
}

# Trust policy document allowing EC2 to assume the role
data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

# ─────────────────────────────────────────────────────────────
# Control Plane IAM Role, Policy, and Instance Profile
# ─────────────────────────────���───────────────────────────────

resource "aws_iam_role" "controlplane" {
  name               = local.controlplane_name
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
  tags               = var.tags
}

resource "aws_iam_policy" "controlplane" {
  name        = local.controlplane_name
  description = "Permissions for the AWS Cloud Controller Manager control plane role"
  policy      = data.aws_iam_policy_document.controlplane.json
  tags        = var.tags
}

resource "aws_iam_role_policy_attachment" "controlplane" {
  role       = aws_iam_role.controlplane.name
  policy_arn = aws_iam_policy.controlplane.arn
}

resource "aws_iam_instance_profile" "controlplane" {
  name = local.controlplane_name
  role = aws_iam_role.controlplane.name
  tags = var.tags
}

data "aws_iam_policy_document" "controlplane" {
  # EC2 networking – describe and list operations
  statement {
    effect = "Allow"
    actions = [
      "ec2:DescribeVpcs",
      "ec2:DescribeSubnets",
      "ec2:DescribeSecurityGroups",
      "ec2:DescribeRouteTables",
      "ec2:DescribeNetworkInterfaces",
      "ec2:DescribeInternetGateways",
      "ec2:DescribeNatGateways",
      "ec2:DescribeInstanceTypes",
      "ec2:DescribeInstances",
      "ec2:DescribeAvailabilityZones",
    ]
    resources = ["*"]
  }

  # Auto Scaling group description
  statement {
    effect = "Allow"
    actions = [
      "autoscaling:DescribeAutoScalingGroups",
      "autoscaling:DescribeAutoScalingInstances",
      "autoscaling:DescribeLaunchConfigurations",
    ]
    resources = ["*"]
  }

  # Elastic Load Balancing management (v2)
  statement {
    effect = "Allow"
    actions = [
      "elasticloadbalancing:CreateLoadBalancer",
      "elasticloadbalancing:DescribeLoadBalancers",
      "elasticloadbalancing:DescribeLoadBalancerAttributes",
      "elasticloadbalancing:DescribeTargetGroups",
      "elasticloadbalancing:DescribeTargetHealth",
      "elasticloadbalancing:DescribeListeners",
      "elasticloadbalancing:DescribeRules",
      "elasticloadbalancing:CreateTargetGroup",
      "elasticloadbalancing:DeleteTargetGroup",
      "elasticloadbalancing:ModifyTargetGroup",
      "elasticloadbalancing:ModifyTargetGroupAttributes",
      "elasticloadbalancing:RegisterTargets",
      "elasticloadbalancing:DeregisterTargets",
      "elasticloadbalancing:SetSecurityGroups",
      "elasticloadbalancing:SetSubnets",
      "elasticloadbalancing:DeleteLoadBalancer",
      "elasticloadbalancing:ModifyLoadBalancerAttributes",
      "elasticloadbalancing:CreateListener",
      "elasticloadbalancing:DeleteListener",
      "elasticloadbalancing:ModifyListener",
      "elasticloadbalancing:CreateRule",
      "elasticloadbalancing:DeleteRule",
      "elasticloadbalancing:ModifyRule",
      "elasticloadbalancing:AddTags",
      "elasticloadbalancing:RemoveTags",
    ]
    resources = ["*"]
  }

  # KMS key description
  statement {
    effect = "Allow"
    actions = [
      "kms:DescribeKey",
    ]
    resources = ["*"]
  }

  # Service-linked role creation
  statement {
    effect = "Allow"
    actions = [
      "iam:CreateServiceLinkedRole",
    ]
    resources = ["arn:aws:iam::*:role/aws-service-role/*"]
    condition {
      test     = "StringLike"
      variable = "iam:AWSServiceName"
      values = [
        "elasticloadbalancing.amazonaws.com",
      ]
    }
  }
}

# ─────────────────────────────────────────────────────────────
# Worker IAM Role, Policy, and Instance Profile
# ─────────────────────────────────────────────────────────────

resource "aws_iam_role" "worker" {
  name               = local.worker_name
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json
  tags               = var.tags
}

resource "aws_iam_policy" "worker" {
  name        = local.worker_name
  description = "Permissions for the AWS Cloud Controller Manager worker node role"
  policy      = data.aws_iam_policy_document.worker.json
  tags        = var.tags
}

resource "aws_iam_role_policy_attachment" "worker" {
  role       = aws_iam_role.worker.name
  policy_arn = aws_iam_policy.worker.arn
}

resource "aws_iam_instance_profile" "worker" {
  name = local.worker_name
  role = aws_iam_role.worker.name
  tags = var.tags
}

data "aws_iam_policy_document" "worker" {
  # EC2 describe instances and regions
  statement {
    effect = "Allow"
    actions = [
      "ec2:DescribeInstances",
      "ec2:DescribeRegions",
      "ec2:DescribeInstanceTypes",
      "ec2:DescribeAvailabilityZones",
    ]
    resources = ["*"]
  }

  # ECR read-only – fetch container images
  statement {
    effect = "Allow"
    actions = [
      "ecr:GetAuthorizationToken",
      "ecr:BatchCheckLayerAvailability",
      "ecr:GetDownloadUrlForLayer",
      "ecr:BatchGetImage",
      "ecr:DescribeRepositories",
      "ecr:ListImages",
      "ecr:DescribeImages",
    ]
    resources = ["*"]
  }
}

# ------------------------------------------------------------------------------
# Foundational IAM Security Structure
#
# Creates three IAM user groups and an MFA-enforced administrative role for
# multi-user access management:
#   - demo-users      : attached to a custom self-management policy
#   - read-only-users : attached to the AWS managed ReadOnlyAccess policy
#   - mfa-superadmin  : can assume the administrative role when MFA is present
#   - <prefix>admin   : assumable by account root, requires MFA, 12h session
# ------------------------------------------------------------------------------

variable "name" {
  description = "Resource name prefix applied to all IAM resources"
  type        = string
  default     = "awscademo-"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  prefix = var.name

  # Default tags applied to every taggable IAM resource.
  default_tags = {
    contact           = "security-team@example.com"
    deployment_method = "Terraform"
    deployment_date   = formatdate("YYYY-MM-DD", timestamp())
    # -1 denotes an infinite / no-expiration TTL
    ttl = "-1"
  }

  # The administrative role name retains the resource prefix and is truncated
  # to a maximum of 31 characters.
  admin_role_name = substr("${local.prefix}admin", 0, 31)
}

# ------------------------------------------------------------------------------
# IAM User Groups
# ------------------------------------------------------------------------------

resource "aws_iam_group" "demo_users" {
  name = "${local.prefix}demo-users"
}

resource "aws_iam_group" "read_only_users" {
  name = "${local.prefix}read-only-users"
}

resource "aws_iam_group" "mfa_superadmin" {
  name = "${local.prefix}mfa-superadmin"
}

# ------------------------------------------------------------------------------
# Self-Management Policy (demo users group)
# Allows users to change their own password, manage their own access keys,
# upload their own SSH public keys, and manage their own virtual MFA devices.
# Deactivating their own MFA device is only allowed while MFA is present.
# ------------------------------------------------------------------------------

resource "aws_iam_policy" "self_management" {
  name        = "${local.prefix}self-management-policy"
  description = "Allows users to self-manage passwords, access keys, SSH public keys, and virtual MFA devices"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowUsersToManageTheirOwnPasswordsAccessKeysAndSSHKeys"
        Effect = "Allow"
        Action = [
          "iam:ChangePassword",
          "iam:GetUser",
          "iam:CreateLoginProfile",
          "iam:DeleteLoginProfile",
          "iam:GetLoginProfile",
          "iam:UpdateLoginProfile",
          "iam:CreateAccessKey",
          "iam:DeleteAccessKey",
          "iam:GetAccessKeyLastUsed",
          "iam:ListAccessKeys",
          "iam:UpdateAccessKey",
          "iam:UploadSSHPublicKey",
          "iam:GetSSHPublicKey",
          "iam:ListSSHPublicKeys",
          "iam:UpdateSSHPublicKey",
          "iam:DeleteSSHPublicKey"
        ]
        Resource = ["arn:${data.aws_partition.current.partition}:iam::*:user/$${aws:username}"]
      },
      {
        Sid    = "AllowUsersToManageTheirOwnVirtualMFADevices"
        Effect = "Allow"
        Action = [
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:ResyncMFADevice",
          "iam:DeleteVirtualMFADevice",
          "iam:DeactivateMFADevice"
        ]
        Resource = [
          "arn:${data.aws_partition.current.partition}:iam::*:user/$${aws:username}",
          "arn:${data.aws_partition.current.partition}:iam::*:mfa/$${aws:username}"
        ]
      },
      {
        Sid    = "AllowUsersToListTheirOwnMFADevices"
        Effect = "Allow"
        Action = [
          "iam:ListMFADevices",
          "iam:ListVirtualMFADevices"
        ]
        Resource = ["*"]
      },
      {
        Sid    = "RequireMFAForDeactivatingOwnMFADevice"
        Effect = "Deny"
        Action = "iam:DeactivateMFADevice"
        Resource = [
          "arn:${data.aws_partition.current.partition}:iam::*:user/$${aws:username}",
          "arn:${data.aws_partition.current.partition}:iam::*:mfa/$${aws:username}"
        ]
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "false"
          }
        }
      }
    ]
  })
  tags = local.default_tags
}

# ------------------------------------------------------------------------------
# Policy Attachments
# ------------------------------------------------------------------------------

resource "aws_iam_group_policy_attachment" "demo_users_self_management" {
  group      = aws_iam_group.demo_users.name
  policy_arn = aws_iam_policy.self_management.arn
}

resource "aws_iam_group_policy_attachment" "read_only_users_managed" {
  group      = aws_iam_group.read_only_users.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/ReadOnlyAccess"
}

# ------------------------------------------------------------------------------
# Administrative Role (MFA enforced)
# Assumable by the account root principal with a maximum session of 12 hours.
# ------------------------------------------------------------------------------

resource "aws_iam_role" "admin" {
  name        = local.admin_role_name
  description = "Administrative role assumable by account root when MFA is present (max 12h session)"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowAccountRootToAssumeAdminRole"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = "sts:AssumeRole"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
  max_session_duration = 43200 # 12 hours (maximum allowed value)
  tags                 = local.default_tags
}

resource "aws_iam_role_policy" "admin_policy" {
  name = "${local.prefix}admin-policy"
  role = aws_iam_role.admin.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowFullAdministratorAccessWhenMFAEnabled"
        Effect   = "Allow"
        Action   = "*"
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# MFA Superadmin Group Policy
# Allows group members to assume the administrative role when MFA is present.
# ------------------------------------------------------------------------------

resource "aws_iam_group_policy" "mfa_superadmin_assume_admin_role" {
  name  = "${local.prefix}assume-admin-role"
  group = aws_iam_group.mfa_superadmin.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowAssumeAdminRoleWhenMFAEnabled"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Resource = [
          aws_iam_role.admin.arn
        ]
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

output "demo_users_group" {
  description = "Demo users IAM group name"
  value       = aws_iam_group.demo_users.name
}

output "read_only_users_group" {
  description = "Read-only users IAM group name"
  value       = aws_iam_group.read_only_users.name
}

output "mfa_superadmin_group" {
  description = "MFA superadmin IAM group name"
  value       = aws_iam_group.mfa_superadmin.name
}

output "admin_role_arn" {
  description = "ARN of the MFA-enforced administrative IAM role"
  value       = aws_iam_role.admin.arn
}

terraform {
  required_version = ">= 1.5"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# IAM Access Management Framework
#
# - CloudPosse label modules provide consistent naming across the admin and
#   non-admin groups using namespace, environment, name, attributes and tags.
# - A self-management policy is attached to BOTH groups so members can manage
#   their own passwords, access keys and virtual MFA devices, list account MFA
#   devices and password policies, and only deactivate their own virtual MFA
#   device while an active MFA session is present.
# - The admin group additionally gets a policy that allows assuming a dedicated
#   admin role. MFA is strictly required both for assuming the role (caller
#   policy) and in the role trust policy (which targets the account root).
# - Group memberships are managed conditionally from the supplied admin and
#   non-admin user name lists.
# ------------------------------------------------------------------------------

variable "namespace" {
  description = "Namespace (e.g. company acronym) used in the CloudPosse label"
  type        = string
  default     = "example"
}

variable "environment" {
  description = "Environment (e.g. prod) used in the CloudPosse label"
  type        = string
  default     = "prod"
}

variable "name" {
  description = "Resource name used in the CloudPosse label"
  type        = string
  default     = "access"
}

variable "attributes" {
  description = "Additional attributes appended to the CloudPosse label id"
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Additional tags merged into the CloudPosse label tags"
  type        = map(string)
  default     = {}
}

variable "admin_user_names" {
  description = "List of IAM user names to add as members of the admin group"
  type        = list(string)
  default     = []
}

variable "non_admin_user_names" {
  description = "List of IAM user names to add as members of the non-admin group"
  type        = list(string)
  default     = []
}

# ------------------------------------------------------------------------------
# Static provider metadata (used for the account root principal and ARNs)
# ------------------------------------------------------------------------------
data "aws_partition" "this" {}

data "aws_caller_identity" "this" {}

# ------------------------------------------------------------------------------
# CloudPosse labels for consistent naming of every IAM resource
# ------------------------------------------------------------------------------
module "this" {
  source      = "cloudposse/label/null"
  version     = "0.25.0"
  namespace   = var.namespace
  environment = var.environment
  name        = var.name
  attributes  = var.attributes
  tags        = var.tags
}

module "admin_group_label" {
  source     = "cloudposse/label/null"
  version    = "0.25.0"
  context    = module.this.context
  attributes = ["admin"]
}

module "non_admin_group_label" {
  source     = "cloudposse/label/null"
  version    = "0.25.0"
  context    = module.this.context
  attributes = ["non-admin"]
}

module "admin_role_label" {
  source     = "cloudposse/label/null"
  version    = "0.25.0"
  context    = module.this.context
  attributes = ["admin", "role"]
}

module "self_management_policy_label" {
  source     = "cloudposse/label/null"
  version    = "0.25.0"
  context    = module.this.context
  attributes = ["iam", "self-management"]
}

module "admin_assume_policy_label" {
  source     = "cloudposse/label/null"
  version    = "0.25.0"
  context    = module.this.context
  attributes = ["iam", "admin-assume"]
}

# ------------------------------------------------------------------------------
# IAM policy documents
# ------------------------------------------------------------------------------

# Attached to both groups: manage own passwords / access keys / virtual MFA
# devices, list account MFA devices and password policy, and only deactivate
# your own virtual MFA device while MFA is active.
data "aws_iam_policy_document" "self_management" {
  statement {
    sid    = "AllowViewAccountInfo"
    effect = "Allow"
    actions = [
      "iam:GetAccountPasswordPolicy",
      "iam:ListMFADevices",
      "iam:ListVirtualMFADevices",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AllowManageOwnPasswords"
    effect = "Allow"
    actions = [
      "iam:ChangePassword",
      "iam:GetUser",
      "iam:CreateLoginProfile",
      "iam:DeleteLoginProfile",
      "iam:GetLoginProfile",
      "iam:UpdateLoginProfile",
    ]
    resources = ["arn:${data.aws_partition.this.partition}:iam::*:user/&{aws:username}"]
  }

  statement {
    sid    = "AllowManageOwnAccessKeys"
    effect = "Allow"
    actions = [
      "iam:CreateAccessKey",
      "iam:DeleteAccessKey",
      "iam:GetAccessKeyLastUsed",
      "iam:ListAccessKeys",
      "iam:UpdateAccessKey",
    ]
    resources = ["arn:${data.aws_partition.this.partition}:iam::*:user/&{aws:username}"]
  }

  statement {
    sid    = "AllowCreateOwnVirtualMFADevice"
    effect = "Allow"
    actions = [
      "iam:CreateVirtualMFADevice",
    ]
    resources = ["arn:${data.aws_partition.this.partition}:iam::*:mfa/*"]
  }

  statement {
    sid    = "AllowManageOwnMfaDevices"
    effect = "Allow"
    actions = [
      "iam:EnableMFADevice",
      "iam:ListMFADevices",
      "iam:ResyncMFADevice",
    ]
    resources = ["arn:${data.aws_partition.this.partition}:iam::*:user/&{aws:username}"]
  }

  # Deactivating a virtual MFA device requires an active MFA session.
  statement {
    sid    = "AllowDeactivateOwnMfaDeviceWithActiveMfa"
    effect = "Allow"
    actions = [
      "iam:DeactivateMFADevice",
    ]
    resources = ["arn:${data.aws_partition.this.partition}:iam::*:user/&{aws:username}"]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

# Admin group caller policy: assume the dedicated admin role only with MFA.
data "aws_iam_policy_document" "admin_assume_role" {
  statement {
    sid       = "AllowAssumeAdminRoleWithMfa"
    effect    = "Allow"
    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.admin.arn]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

# Admin role trust policy: only the account root principal may assume the role,
# and only when MFA is present.
data "aws_iam_policy_document" "admin_role_trust" {
  statement {
    sid     = "AllowAccountRootAssumeRoleWithMfa"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.this.partition}:iam::${data.aws_caller_identity.this.account_id}:root"]
    }
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

# ------------------------------------------------------------------------------
# IAM groups
# ------------------------------------------------------------------------------
resource "aws_iam_group" "admin" {
  name = module.admin_group_label.id
  path = "/"
}

resource "aws_iam_group" "non_admin" {
  name = module.non_admin_group_label.id
  path = "/"
}

# ------------------------------------------------------------------------------
# IAM policies
# ------------------------------------------------------------------------------
resource "aws_iam_policy" "self_management" {
  name        = module.self_management_policy_label.id
  description = "Allows members to manage their own passwords, access keys and virtual MFA devices and to list account MFA devices and password policies"
  path        = "/"
  policy      = data.aws_iam_policy_document.self_management.json
}

resource "aws_iam_policy" "admin_assume_role" {
  name        = module.admin_assume_policy_label.id
  description = "Allows members of the admin group to assume the dedicated admin role when MFA is present"
  path        = "/"
  policy      = data.aws_iam_policy_document.admin_assume_role.json
}

# ------------------------------------------------------------------------------
# Admin role (AWS-managed AdministratorAccess attached)
# ------------------------------------------------------------------------------
resource "aws_iam_role" "admin" {
  name               = module.admin_role_label.id
  description        = "Administrative role assumable only by the account root principal when MFA is present"
  path               = "/"
  assume_role_policy = data.aws_iam_policy_document.admin_role_trust.json
  tags               = module.admin_role_label.tags
}

resource "aws_iam_role_policy_attachment" "admin_administrator_access" {
  role       = aws_iam_role.admin.name
  policy_arn = "arn:${data.aws_partition.this.partition}:iam::aws:policy/AdministratorAccess"
}

# ------------------------------------------------------------------------------
# Policy attachments
# ------------------------------------------------------------------------------

# Self-management policy is attached to BOTH groups.
resource "aws_iam_group_policy_attachment" "admin_self_management" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.self_management.arn
}

resource "aws_iam_group_policy_attachment" "non_admin_self_management" {
  group      = aws_iam_group.non_admin.name
  policy_arn = aws_iam_policy.self_management.arn
}

# Admin-only permission to assume the dedicated admin role (MFA required).
resource "aws_iam_group_policy_attachment" "admin_assume_admin_role" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.admin_assume_role.arn
}

# ------------------------------------------------------------------------------
# Conditional user creation and group membership
# ------------------------------------------------------------------------------
resource "aws_iam_user" "admin" {
  for_each = toset(var.admin_user_names)
  name     = each.value
  path     = "/"
  tags     = module.admin_group_label.tags
}

resource "aws_iam_user" "non_admin" {
  for_each = toset(var.non_admin_user_names)
  name     = each.value
  path     = "/"
  tags     = module.non_admin_group_label.tags
}

resource "aws_iam_user_group_membership" "admin" {
  for_each   = toset(var.admin_user_names)
  user       = each.value
  groups     = [aws_iam_group.admin.name]
  depends_on = [aws_iam_user.admin]
}

resource "aws_iam_user_group_membership" "non_admin" {
  for_each   = toset(var.non_admin_user_names)
  user       = each.value
  groups     = [aws_iam_group.non_admin.name]
  depends_on = [aws_iam_user.non_admin]
}

locals {
  vpc_cidr = "10.0.0.0/16"

  # Subnet CIDRs
  public_subnet_cidrs = {
    az1 = "10.0.1.0/24"
    az2 = "10.0.2.0/24"
  }

  private_subnet_1_cidrs = {
    az1 = "10.0.3.0/24"
    az2 = "10.0.4.0/24"
  }

  private_subnet_2_cidrs = {
    az1 = "10.0.5.0/24"
    az2 = "10.0.6.0/24"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "dev-test-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "dev-test-igw"
  }
}

# --- Public Subnets (no auto-assign public IP on launch) ---

resource "aws_subnet" "public" {
  for_each = local.public_subnet_cidrs

  vpc_id                  = aws_vpc.main.id
  cidr_block              = each.value
  availability_zone       = data.aws_availability_zones.available.names[each.key == "az1" ? 0 : 1]
  map_public_ip_on_launch = false

  tags = {
    Name = "public-subnet-${each.key}"
  }
}

# --- Private Subnets (two per AZ) ---

resource "aws_subnet" "private_1" {
  for_each = local.private_subnet_1_cidrs

  vpc_id                  = aws_vpc.main.id
  cidr_block              = each.value
  availability_zone       = data.aws_availability_zones.available.names[each.key == "az1" ? 0 : 1]
  map_public_ip_on_launch = false

  tags = {
    Name = "private-subnet-1-${each.key}"
  }
}

resource "aws_subnet" "private_2" {
  for_each = local.private_subnet_2_cidrs

  vpc_id                  = aws_vpc.main.id
  cidr_block              = each.value
  availability_zone       = data.aws_availability_zones.available.names[each.key == "az1" ? 0 : 1]
  map_public_ip_on_launch = false

  tags = {
    Name = "private-subnet-2-${each.key}"
  }
}

# --- Public Route Table with default route to Internet Gateway ---

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "public-route-table"
  }
}

# --- Public Route Table Associations ---

resource "aws_route_table_association" "public" {
  for_each = aws_subnet.public

  subnet_id      = each.value.id
  route_table_id = aws_route_table.public.id
}

# --- Private Route Table (no explicit routes) ---

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "private-route-table"
  }
}

# --- Private Route Table Associations ---

resource "aws_route_table_association" "private_1" {
  for_each = aws_subnet.private_1

  subnet_id      = each.value.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_2" {
  for_each = aws_subnet.private_2

  subnet_id      = each.value.id
  route_table_id = aws_route_table.private.id
}

# --- Public Security Group ---

resource "aws_security_group" "public" {
  name        = "public-sg"
  description = "Public security group for dev/test"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "public-sg"
  }
}

resource "aws_security_group_rule" "public_in_all_from_vpc" {
  security_group_id = aws_security_group.public.id
  type              = "ingress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [local.vpc_cidr]
}

resource "aws_security_group_rule" "public_in_ssh_from_vpc" {
  security_group_id = aws_security_group.public.id
  type              = "ingress"
  from_port         = 22
  to_port           = 22
  protocol          = "tcp"
  cidr_blocks       = [local.vpc_cidr]
}

resource "aws_security_group_rule" "public_in_http_from_anywhere" {
  security_group_id = aws_security_group.public.id
  type              = "ingress"
  from_port         = 80
  to_port           = 80
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
}

resource "aws_security_group_rule" "public_out_to_vpc" {
  security_group_id = aws_security_group.public.id
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [local.vpc_cidr]
}

# --- Private Security Group ---

resource "aws_security_group" "private" {
  name        = "private-sg"
  description = "Private security group for dev/test"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "private-sg"
  }
}

resource "aws_security_group_rule" "private_in_all_from_vpc" {
  security_group_id = aws_security_group.private.id
  type              = "ingress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [local.vpc_cidr]
}

resource "aws_security_group_rule" "private_out_to_vpc" {
  security_group_id = aws_security_group.private.id
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [local.vpc_cidr]
}

variable "name_suffix" {
  description = "Suffix appended to all resource names (default: empty string)"
  type        = string
  default     = ""
}

locals {
  name_base = "prod-ci-${var.name_suffix}"
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

# IAM Role with wildcard Principal assume-role policy
resource "aws_iam_role" "this" {
  name = local.name_base
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "*"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# IAM Policy granting permission to assume the role
resource "aws_iam_policy" "assume_role" {
  name        = "${local.name_base}-assume-role-policy"
  description = "Allows assuming the prod-ci IAM role"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Resource = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:role/${local.name_base}"
      }
    ]
  })
}

# IAM Group
resource "aws_iam_group" "this" {
  name = local.name_base
}

# Attach the assume-role policy to the group
resource "aws_iam_group_policy_attachment" "this" {
  group      = aws_iam_group.this.name
  policy_arn = aws_iam_policy.assume_role.arn
}

# IAM User
resource "aws_iam_user" "this" {
  name = local.name_base
}

# Group membership binding the user to the group
resource "aws_iam_group_membership" "this" {
  name  = "${local.name_base}-membership"
  group = aws_iam_group.this.name
  users = [aws_iam_user.this.name]
}

data "aws_caller_identity" "current" {}

resource "aws_config_configuration_aggregator" "default" {
  name = "default"

  account_aggregation_source {
    account_ids     = [data.aws_caller_identity.current.account_id]
    all_regions = true
  }

  tags = {
    ManagedBy = "Terraform"
  }
}

# ------------------------------------------------------------------------------
# IAM role and instance profile for EC2 image building automation (Image Builder)
# ------------------------------------------------------------------------------

terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

data "aws_partition" "current" {}

# IAM role assumed by EC2 services for image building automation
resource "aws_iam_role" "imagebuilder" {
  name        = "imagebuilder_role"
  path        = "/"
  description = "IAM role for EC2 image building automation via Image Builder"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "imagebuilder_role"
  }
}

# Attach the AWS-managed full access policy for Image Builder
resource "aws_iam_role_policy_attachment" "imagebuilder_full_access" {
  role       = aws_iam_role.imagebuilder.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AWSImageBuilderFullAccess"
}

# Instance profile that grants the role to EC2 instances used for image building
resource "aws_iam_instance_profile" "imagebuilder" {
  name = "imagebuilder_instance_profile"
  path = "/"
  role = aws_iam_role.imagebuilder.name
}

