variable "permissions_boundary_arn" {
  description = "Optional ARN of the permissions boundary policy to attach to the IAM role"
  type        = string
  default     = null
}

variable "tags" {
  description = "A map of resource tags to apply to all created resources"
  type        = map(string)
  default     = {}
}

resource "aws_iam_role" "tamr_instance" {
  name                 = var.iam_role_name
  assume_role_policy   = jsonencode({
    Version = "2012-10-17"
