      {
        Action    = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Effect    = "Allow"
      }
    ]
  })
  permissions_boundary = var.permissions_boundary_arn
  tags                 = var.tags
}

resource "aws_iam_instance_profile" "tamr_instance" {
  name = var.instance_profile_name
  role = aws_iam_role.tamr_instance.name
  tags = var.tags
}

