variable "name_prefix" {
  description = "Environment-specific prefix for resource names (e.g. dev, staging, prod)"
  type        = string
  default     = "dev"
}

variable "target_account_id" {
  description = "AWS account ID of the target account containing the S3 bucket with software installation files"
  type        = string
  default     = "123456789012"
}

variable "target_role_name" {
  description = "Name of the IAM role in the target account to assume for reading S3 objects"
  type        = string
  default     = "SoftwareInstallBucketReader"
}

locals {
  role_name      = "${var.name_prefix}-packer-builder"
  profile_name   = "${var.name_prefix}-packer-builder"
  policy_name    = "${var.name_prefix}-assume-target-role"
  target_role_arn = "arn:aws:iam::${var.target_account_id}:role/${var.target_role_name}"
}

# IAM role for the EC2 Packer builder instance
resource "aws_iam_role" "packer_builder" {
  name               = local.role_name
  description        = "IAM role for Packer builder EC2 instance (environment: ${var.name_prefix})"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = {
    Name        = local.role_name
    Environment = var.name_prefix
  }
}

# Instance profile to attach the role to EC2 instances
resource "aws_iam_instance_profile" "packer_builder" {
  name = local.profile_name
  role = aws_iam_role.packer_builder.name

  tags = {
    Name        = local.profile_name
    Environment = var.name_prefix
  }
}

# Policy allowing the Packer builder role to assume the target role in another account
resource "aws_iam_policy" "assume_target_role" {
  name        = local.policy_name
  description = "Allows ${local.role_name} to assume ${var.target_role_name} in account ${var.target_account_id} for S3 read access"
  policy      = data.aws_iam_policy_document.assume_target_role.json

  tags = {
    Name        = local.policy_name
    Environment = var.name_prefix
  }
}

# Attach the assume-role policy to the Packer builder role
resource "aws_iam_role_policy_attachment" "assume_target_role" {
  role       = aws_iam_role.packer_builder.name
  policy_arn = aws_iam_policy.assume_target_role.arn
}

# ---------- IAM Policy Documents ----------

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "assume_target_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    resources = [local.target_role_arn]

    # Condition to scope the assume-role to the intended target
    condition {
      test     = "StringEquals"
      variable = "sts:ExternalId"
      values   = [var.name_prefix]
    }
  }
}

