# Secrets Manager secret to hold the user password (best practice)
resource "aws_secretsmanager_secret" "user_password" {
  name        = "service-catalog-test-user-password"
  description = "Password for the Service Catalog test IAM user"
}

# ---------------------------------------------------------------------------
# IAM role: service-catalog-assumable "test_role"
# ---------------------------------------------------------------------------
resource "aws_iam_role" "test_role" {
  name = "test_role"
  description = "IAM role assumable by AWS Service Catalog for launching products with scoped constraints"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "servicecatalog.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# Scoped launch-constraint policy for Service Catalog
# ---------------------------------------------------------------------------
resource "aws_iam_policy" "launch_constraint" {
  name        = "service-catalog-launch-constraint"
  description = "Scoped launch-constraint policy that restricts Service Catalog product launches"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "servicecatalog:LaunchProduct"
        Resource = "*"
        Condition = {
          StringEquals = {
            "servicecatalog:launchConstraint" = "scoped"
          }
        }
      }
    ]
  })
}

# Attach the launch-constraint policy to the role
resource "aws_iam_role_policy_attachment" "launch_constraint" {
  role       = aws_iam_role.test_role.name
  policy_arn = aws_iam_policy.launch_constraint.arn
}

# ---------------------------------------------------------------------------
# IAM group
# ---------------------------------------------------------------------------
resource "aws_iam_group" "main" {
  name = "service-catalog-test-group"
}

# ---------------------------------------------------------------------------
# Console-enabled IAM user
# ---------------------------------------------------------------------------
resource "aws_iam_user" "test_user" {
  name = "service-catalog-test-user"
}

resource "aws_iam_user_login_profile" "test_user" {
  user = aws_iam_user.test_user.name
}

# Store the generated password in Secrets Manager
resource "aws_secretsmanager_secret_version" "user_password" {
  secret_id     = aws_secretsmanager_secret.user_password.id
  secret_string = aws_iam_user_login_profile.test_user.password
}

# Add the user to the group
resource "aws_iam_group_membership" "test_user" {
  name  = "service-catalog-group-membership"
  group = aws_iam_group.main.name
  users = [aws_iam_user.test_user.name]
}

# -----------------------------------------------------------------------------
# Multi-tier AWS VPC network infrastructure for Datadog Agentless Scanner
# -----------------------------------------------------------------------------

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

locals {
  # Availability zones to use (up to var.az_count) available in the region.
  azs = slice(
    data.aws_availability_zones.available.names,
    0,
    min(var.az_count, length(data.aws_availability_zones.available.names))
  )

  # Public subnets are assigned sequentially from the VPC CIDR.
  # Private subnets are offset past the public subnets so that both tiers
  # never overlap regardless of the number of availability zones used.
  public_subnet_cidrs  = [for i in range(length(local.azs)) : cidrsubnet(var.vpc_cidr, 8, i)]
  private_subnet_cidrs = [for i in range(length(local.azs)) : cidrsubnet(var.vpc_cidr, 8, i + length(local.azs))]

  # Optional interface VPC endpoints for AWS Systems Manager.
  ssm_endpoint_services = toset(["ssm", "ec2messages", "ssmmessages"])
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

# -----------------------------------------------------------------------------
# VPC
# -----------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(
    var.default_tags,
    {
      Name = var.vpc_name
    }
  )
}

# -----------------------------------------------------------------------------
# Subnets
# -----------------------------------------------------------------------------
resource "aws_subnet" "public" {
  count             = length(local.azs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.public_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = merge(
    var.default_tags,
    {
      Name = "${var.vpc_name}-public-${local.azs[count.index]}"
    }
  )
}

resource "aws_subnet" "private" {
  count             = length(local.azs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = merge(
    var.default_tags,
    {
      Name = "${var.vpc_name}-private-${local.azs[count.index]}"
    }
  )
}

# -----------------------------------------------------------------------------
# Internet Gateway and public routing
# -----------------------------------------------------------------------------
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    var.default_tags,
    {
      Name = "${var.vpc_name}-igw"
    }
  )
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    var.default_tags,
    {
      Name = "${var.vpc_name}-public"
    }
  )
}

resource "aws_route" "public_internet_gateway" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count          = length(local.azs)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# NAT Gateway (single, placed in the first public subnet) and private routing
# -----------------------------------------------------------------------------
resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(
    var.default_tags,
    {
      Name = "${var.vpc_name}-nat"
    }
  )
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(
    var.default_tags,
    {
      Name = "${var.vpc_name}-nat"
    }
  )
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    var.default_tags,
    {
      Name = "${var.vpc_name}-private"
    }
  )
}

resource "aws_route" "private_nat_gateway" {
  route_table_id         = aws_route_table.private.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main.id
}

resource "aws_route_table_association" "private" {
  count          = length(local.azs)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# -----------------------------------------------------------------------------
# VPC Endpoints
# -----------------------------------------------------------------------------
# Gateway endpoint for S3, attached to both public and private route tables.
resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.public.id, aws_route_table.private.id]

  tags = merge(
    var.default_tags,
    {
      Name = "${var.vpc_name}-s3"
    }
  )
}

# Security group for interface VPC endpoints.
resource "aws_security_group" "vpc_endpoints" {
  name_prefix = "${var.vpc_name}-vpc-endpoints-"
  description = "Security group for interface VPC endpoints"
  vpc_id      = aws_vpc.main.id

  tags = merge(
    var.default_tags,
    {
      Name = "${var.vpc_name}-vpc-endpoints"
    }
  )
}

resource "aws_security_group_rule" "vpc_endpoints_https_ingress" {
  type              = "ingress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.vpc_endpoints.id
  description       = "Allow HTTPS traffic from the VPC CIDR"
}

# Interface endpoint for AWS Lambda, deployed across all private subnets.
resource "aws_vpc_endpoint" "lambda" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.region}.lambda"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  subnet_ids          = aws_subnet.private[*].id

  tags = merge(
    var.default_tags,
    {
      Name = "${var.vpc_name}-lambda"
    }
  )
}

# Interface endpoint for Amazon EBS, deployed across all private subnets.
resource "aws_vpc_endpoint" "ebs" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.region}.ebs"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  subnet_ids          = aws_subnet.private[*].id

  tags = merge(
    var.default_tags,
    {
      Name = "${var.vpc_name}-ebs"
    }
  )
}

# Optional interface endpoints for AWS Systems Manager (ssm, ec2messages, ssmmessages).
resource "aws_vpc_endpoint" "ssm" {
  for_each            = var.enable_ssm_endpoints ? local.ssm_endpoint_services : toset([])
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.region}.${each.value}"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  subnet_ids          = aws_subnet.private[*].id

  tags = merge(
    var.default_tags,
    {
      Name = "${var.vpc_name}-vpc-endpoint-${each.value}"
    }
  )
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------
variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "vpc_name" {
  description = "Name tag applied to the VPC and associated resources"
  type        = string
  default     = "DatatogAgentlessScanner"
}

variable "az_count" {
  description = "Number of availability zones to use for subnets, up to a maximum of 3"
  type        = number
  default     = 3
}

variable "enable_ssm_endpoints" {
  description = "Whether to create SSM interface VPC endpoints (ssm, ec2messages, ssmmessages)"
  type        = bool
  default     = false
}

variable "default_tags" {
  description = "Default tags applied to all resources"
  type        = map(string)
  default = {
    "Datadog"                 = "true"
    "DatadogAgentlessScanner" = "true"
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "vpc_id" {
  description = "ID of the VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets"
  value       = aws_subnet.private[*].id
}

output "nat_gateway_id" {
  description = "ID of the NAT gateway"
  value       = aws_nat_gateway.main.id
}

output "vpc_endpoint_ids" {
  description = "IDs of all VPC endpoints created"
  value = concat(
    [aws_vpc_endpoint.s3.id, aws_vpc_endpoint.lambda.id, aws_vpc_endpoint.ebs.id],
    [for ep in aws_vpc_endpoint.ssm : ep.id]
  )
}

variable "role_name" {
  description = "Name of the CloudForecast IAM role"
  type        = string
  default     = "CloudForecast-ZeroWaste"
}

variable "external_id" {
  description = "External ID for cross-account STS assume-role condition"
  type        = string
  default     = "benchmark-external-id"
}

resource "aws_iam_role" "cloudforecast" {
  name        = var.role_name
  description = "Dedicated third-party IAM integration role for CloudForecast read-only cost optimization and waste-monitoring analysis"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          AWS = "arn:aws:iam::656227328603:root"
        }
        Action    = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "sts:ExternalId" = var.external_id
          }
        }
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# Policy 1:  CloudWatch – read metric statistics
# ---------------------------------------------------------------------------
resource "aws_iam_role_policy" "cloudwatch_metrics" {
  name = "cloudwatch-metrics"
  role = aws_iam_role.cloudforecast.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "cloudwatch:GetMetricStatistics"
        Resource = "*"
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# Policy 2:  Resource Groups Tagging – query resources & tags
# ---------------------------------------------------------------------------
resource "aws_iam_role_policy" "tag_resources" {
  name = "tag-resources"
  role = aws_iam_role.cloudforecast.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "tag:GetResources"
        Resource = "*"
      }
    ]
  })
}

