variable "env_suffix" {
  description = "Environment suffix appended to IAM user names"
  type        = string
  default     = "dev"
}

variable "enable_db_disaster_recovery_user" {
  description = "Toggle creation of the database disaster recovery IAM user"
  type        = bool
  default     = false
}

variable "enable_data_exports_user" {
  description = "Toggle creation of the data exports IAM user"
  type        = bool
  default     = false
}

variable "enable_packer_image_builder_user" {
  description = "Toggle creation of the Packer image builder IAM user"
  type        = bool
  default     = false
}

variable "s3_export_bucket_arn" {
  description = "ARN of the S3 export bucket assigned to the data exports user"
  type        = string
  default     = ""
}

variable "s3_monitoring_state_bucket_arn" {
  description = "ARN of the S3 monitoring state bucket for the Packer builder user"
  type        = string
  default     = ""
}

variable "server_role_name" {
  description = "Name of the IAM server role to grant PassRole authority for the Packer builder"
  type        = string
  default     = ""
}

# ---------------------------------------------------------------------------
# Data sources – static provider metadata only
# ---------------------------------------------------------------------------
data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

# ---------------------------------------------------------------------------
# Local values used multiple times across resources
# ---------------------------------------------------------------------------
locals {
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.region
  account_id = data.aws_caller_identity.current.account_id

  server_role_arn = var.server_role_name != "" ? (
    "arn:${local.partition}:iam::${local.account_id}:role/${var.server_role_name}"
  ) : ""
}

# ---------------------------------------------------------------------------
# 1. MANDATORY – Cost Reporting user with full Cost Explorer access
# ---------------------------------------------------------------------------
resource "aws_iam_user" "cost_report" {
  name = "mattermost-cost-report-${var.env_suffix}"
}

resource "aws_iam_user_policy" "cost_report" {
  name   = "cost-explorer-policy"
  user   = aws_iam_user.cost_report.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["cost-explorer:*"]
        Resource = ["*"]
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# 2. OPTIONAL – Database Disaster Recovery user:
#    full RDS & KMS access + read on rds-cluster-multitenant-* secrets
# ---------------------------------------------------------------------------
resource "aws_iam_user" "db_disaster_recovery" {
  count = var.enable_db_disaster_recovery_user ? 1 : 0
  name  = "mattermost-db-dr-${var.env_suffix}"
}

resource "aws_iam_user_policy" "db_disaster_recovery" {
  count = var.enable_db_disaster_recovery_user ? 1 : 0
  name  = "db-disaster-recovery-policy"
  user  = aws_iam_user.db_disaster_recovery[0].name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["rds:*", "kms:*"]
        Resource = ["*"]
      },
      {
        Effect   = "Allow"
        Action   = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret",
          "secretsmanager:ListSecrets",
          "secretsmanager:ListSecretVersionIds"
        ]
        Resource = ["arn:${local.partition}:secretsmanager:${local.region}:${local.account_id}:secret:rds-cluster-multitenant-*"]
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# 3. OPTIONAL – Data Exports user:
#    bucket listing + object read/write on a configurable S3 bucket
# ---------------------------------------------------------------------------
resource "aws_iam_user" "data_exports" {
  count = var.enable_data_exports_user ? 1 : 0
  name  = "mattermost-data-exports-${var.env_suffix}"
}

resource "aws_iam_user_policy" "data_exports" {
  count = var.enable_data_exports_user ? 1 : 0
  name  = "data-exports-policy"
  user  = aws_iam_user.data_exports[0].name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["s3:ListBucket"]
        Resource = [var.s3_export_bucket_arn]
      },
      {
        Effect   = "Allow"
        Action   = ["s3:GetObject", "s3:PutObject"]
        Resource = ["${var.s3_export_bucket_arn}/*"]
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# 4. OPTIONAL – Packer Image Builder user:
#    EC2, Auto Scaling, CloudWatch Events, SSM, IAM inspection,
#    S3 monitoring bucket, Lambda configuration, and PassRole
# ---------------------------------------------------------------------------
locals {
  packer_base_statements = [
    # EC2 – build & manage images and instances
    {
      Effect = "Allow"
      Action = [
        "ec2:DescribeImages",
        "ec2:DescribeInstances",
        "ec2:DescribeVolumes",
        "ec2:DescribeSnapshots",
        "ec2:DescribeSecurityGroups",
        "ec2:DescribeSubnets",
        "ec2:DescribeVpcs",
        "ec2:DescribeTags",
        "ec2:CreateTags",
        "ec2:RunInstances",
        "ec2:TerminateInstances",
        "ec2:CreateVolumes",
        "ec2:DeleteVolumes",
        "ec2:CreateSnapshots",
        "ec2:DeleteSnapshots",
        "ec2:AttachVolume",
        "ec2:DetachVolume",
        "ec2:RegisterImage",
        "ec2:DeregisterImage"
      ]
      Resource = ["*"]
    },
    # Auto Scaling – discover & modify groups
    {
      Effect = "Allow"
      Action = [
        "autoscaling:DescribeAutoScalingGroups",
        "autoscaling:DescribeAutoScalingInstances",
        "autoscaling:UpdateAutoScalingGroup",
        "autoscaling:EnterStandby",
        "autoscaling:ExitStandby"
      ]
      Resource = ["*"]
    },
    # CloudWatch Events – emit build lifecycle events
    {
      Effect = "Allow"
      Action = [
        "events:PutEvents",
        "events:DescribeRule",
        "events:ListRules"
      ]
      Resource = ["*"]
    },
    # SSM – read parameter store values
    {
      Effect = "Allow"
      Action = [
        "ssm:GetParameter",
        "ssm:GetParameters",
        "ssm:DescribeParameters"
      ]
      Resource = ["*"]
    },
    # IAM – inspect roles & instance profiles
    {
      Effect = "Allow"
      Action = [
        "iam:GetRole",
        "iam:ListRoles",
        "iam:GetInstanceProfile",
        "iam:ListInstanceProfiles"
      ]
      Resource = ["*"]
    },
    # S3 – monitoring state bucket read/write
    {
      Effect = "Allow"
      Action = [
        "s3:ListBucket",
        "s3:GetObject",
        "s3:PutObject"
      ]
      Resource = [
        var.s3_monitoring_state_bucket_arn,
        "${var.s3_monitoring_state_bucket_arn}/*"
      ]
    },
    # Lambda – update configuration on bind-server-network-attachment
    {
      Effect = "Allow"
      Action = [
        "lambda:UpdateFunctionConfiguration",
        "lambda:GetFunctionConfiguration",
        "lambda:GetFunction"
      ]
      Resource = [
        "arn:${local.partition}:lambda:${local.region}:${local.account_id}:function:bind-server-network-attachment"
      ]
    }
  ]

  packer_pass_role_statement = var.server_role_name != "" ? [
    {
      Effect   = "Allow"
      Action   = ["iam:PassRole"]
      Resource = [local.server_role_arn]
    }
  ] : []

  packer_all_statements = concat(local.packer_base_statements, local.packer_pass_role_statement)
}

resource "aws_iam_user" "packer_image_builder" {
  count = var.enable_packer_image_builder_user ? 1 : 0
  name  = "mattermost-packer-builder-${var.env_suffix}"
}

resource "aws_iam_user_policy" "packer_image_builder" {
  count = var.enable_packer_image_builder_user ? 1 : 0
  name  = "packer-image-builder-policy"
  user  = aws_iam_user.packer_image_builder[0].name
  policy = jsonencode({
    Version   = "2012-10-17"
    Statement = local.packer_all_statements
  })
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------

variable "aws_region" {
  description = "AWS region where the HealthOmics test infrastructure is deployed."
  type        = string
  default     = "us-east-1"
}

variable "output_bucket_name" {
  description = "Name of the S3 bucket used to store HealthOmics workflow outputs."
  type        = string
  default     = "tf-benchmark-omics-output-bucket"
}

variable "service_account_user_name" {
  description = "Name of the IAM user with programmatic access used for HealthOmics workflows."
  type        = string
  default     = "workbench-health-omics"
}

variable "iam_role_name" {
  description = "Name of the IAM role assumed by the AWS HealthOmics service."
  type        = string
  default     = "HealthOmicsRole"
}

variable "service_policy_name" {
  description = "Name of the IAM policy attached to the HealthOmics service role."
  type        = string
  default     = "HealthOmicsServicePolicy"
}

variable "user_policy_name" {
  description = "Name of the IAM policy attached to the HealthOmics service account user."
  type        = string
  default     = "HealthOmicsUserPolicy"
}

variable "ecr_repository_names" {
  description = "Names of the ECR repositories used to store HealthOmics container images."
  type        = list(string)
  default     = ["healthomics/workflows"]
}

variable "additional_s3_bucket_names" {
  description = "Optional list of additional S3 buckets the service account user is granted read-only access to."
  type        = list(string)
  default     = []
}

variable "external_account_ids" {
  description = "Optional list of external AWS account IDs granted cross-account pull access to the ECR repositories."
  type        = list(string)
  default     = []
}

variable "kms_key_alias" {
  description = "Alias of the customer-managed KMS key used to encrypt the HealthOmics output bucket."
  type        = string
  default     = "alias/healthomics-output-bucket-key"
}

# ------------------------------------------------------------------------------
# Data sources (static provider metadata and purely local policy documents)
# ------------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_iam_policy_document" "omics_role_trust" {
  statement {
    sid    = "AllowOmicsServiceAssumeRole"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["omics.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

data "aws_iam_policy_document" "omics_service_policy" {
  statement {
    sid     = "AllowS3OutputBucketAccess"
    effect  = "Allow"
    actions = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject", "s3:ListBucket"]
    resources = [
      "arn:${data.aws_partition.current.partition}:s3:::${var.output_bucket_name}",
      "arn:${data.aws_partition.current.partition}:s3:::${var.output_bucket_name}/*",
    ]
  }

  statement {
    sid    = "AllowKMSOutputKeyUse"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
    ]
    resources = [aws_kms_key.output_bucket_key.arn]
  }

  statement {
    sid       = "AllowECRAuthorizationToken"
    effect    = "Allow"
    actions   = ["ecr:GetAuthorizationToken"]
    resources = ["*"]
  }

  statement {
    sid       = "AllowECRPullImages"
    effect    = "Allow"
    actions   = ["ecr:BatchCheckLayerAvailability", "ecr:BatchGetImage", "ecr:GetDownloadUrlForLayer"]
    resources = [for repo in aws_ecr_repository.repositories : repo.arn]
  }

  statement {
    sid     = "AllowCloudWatchLogs"
    effect  = "Allow"
    actions = ["logs:CreateLogGroup", "logs:CreateLogStream", "logs:PutLogEvents"]
    resources = [
      "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:log-group:/aws/omics/*",
      "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:log-group:/aws/omics/*:*",
    ]
  }
}

data "aws_iam_policy_document" "omics_user_policy" {
  statement {
    sid       = "AllowPassRole"
    effect    = "Allow"
    actions   = ["iam:PassRole"]
    resources = [aws_iam_role.health_omics.arn]
  }

  statement {
    sid       = "AllowFullOmicsActions"
    effect    = "Allow"
    actions   = ["omics:*"]
    resources = ["*"]
  }

  statement {
    sid       = "AllowKMSDecryptOutputKey"
    effect    = "Allow"
    actions   = ["kms:Decrypt", "kms:DescribeKey"]
    resources = [aws_kms_key.output_bucket_key.arn]
  }

  statement {
    sid     = "AllowReadOutputBucket"
    effect  = "Allow"
    actions = ["s3:GetBucketLocation", "s3:GetObject", "s3:GetObjectVersion", "s3:ListBucket"]
    resources = [
      "arn:${data.aws_partition.current.partition}:s3:::${var.output_bucket_name}",
      "arn:${data.aws_partition.current.partition}:s3:::${var.output_bucket_name}/*",
    ]
  }

  dynamic "statement" {
    for_each = length(var.additional_s3_bucket_names) > 0 ? [1] : []
    content {
      sid     = "AllowReadAdditionalBuckets"
      effect  = "Allow"
      actions = ["s3:GetBucketLocation", "s3:GetObject", "s3:GetObjectVersion", "s3:ListBucket"]
      resources = flatten([
        for bucket in var.additional_s3_bucket_names : [
          "arn:${data.aws_partition.current.partition}:s3:::${bucket}",
          "arn:${data.aws_partition.current.partition}:s3:::${bucket}/*",
        ]
      ])
    }
  }
}

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid    = "EnableIAMRootAdministration"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }
}

data "aws_iam_policy_document" "ecr_repository_policy" {
  statement {
    sid    = "AllowOmicsServicePull"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["omics.amazonaws.com"]
    }
    actions = ["ecr:BatchCheckLayerAvailability", "ecr:BatchGetImage", "ecr:GetDownloadUrlForLayer"]
  }

  dynamic "statement" {
    for_each = length(var.external_account_ids) > 0 ? [1] : []
    content {
      sid    = "AllowCrossAccountPull"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = [for account_id in var.external_account_ids : "arn:${data.aws_partition.current.partition}:iam::${account_id}:root"]
      }
      actions = ["ecr:BatchCheckLayerAvailability", "ecr:BatchGetImage", "ecr:GetDownloadUrlForLayer"]
    }
  }
}

# ------------------------------------------------------------------------------
# Customer-managed KMS key for output bucket encryption
# ------------------------------------------------------------------------------

resource "aws_kms_key" "output_bucket_key" {
  description             = "Customer-managed KMS key used to encrypt the HealthOmics output bucket in ${var.aws_region}."
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json
  tags = {
    Name        = var.kms_key_alias
    Environment = "testing"
  }
}

resource "aws_kms_alias" "output_bucket_key" {
  name          = var.kms_key_alias
  target_key_id = aws_kms_key.output_bucket_key.key_id
}

# ------------------------------------------------------------------------------
# IAM role assumed by the AWS HealthOmics service
# ------------------------------------------------------------------------------

resource "aws_iam_role" "health_omics" {
  name               = var.iam_role_name
  description        = "IAM role assumed by the AWS HealthOmics service to run workflows and access required resources."
  assume_role_policy = data.aws_iam_policy_document.omics_role_trust.json
  tags = {
    Name        = var.iam_role_name
    Environment = "testing"
  }
}

resource "aws_iam_policy" "health_omics_service_policy" {
  name        = var.service_policy_name
  description = "IAM policy granting the HealthOmics service role access to S3, KMS, ECR, and CloudWatch resources."
  policy      = data.aws_iam_policy_document.omics_service_policy.json
}

resource "aws_iam_role_policy_attachment" "health_omics_service_policy" {
  role       = aws_iam_role.health_omics.name
  policy_arn = aws_iam_policy.health_omics_service_policy.arn
}

# ------------------------------------------------------------------------------
# IAM user with programmatic access
# ------------------------------------------------------------------------------

resource "aws_iam_user" "health_omics_user" {
  name = var.service_account_user_name
  path = "/"
  tags = {
    Name        = var.service_account_user_name
    Environment = "testing"
  }
}

resource "aws_iam_policy" "health_omics_user_policy" {
  name        = var.user_policy_name
  description = "IAM policy granting the HealthOmics service account user pass-role, full omics actions, and read-only S3 access."
  policy      = data.aws_iam_policy_document.omics_user_policy.json
}

resource "aws_iam_user_policy_attachment" "health_omics_user_policy" {
  user       = aws_iam_user.health_omics_user.name
  policy_arn = aws_iam_policy.health_omics_user_policy.arn
}

resource "aws_iam_access_key" "health_omics_user" {
  user = aws_iam_user.health_omics_user.name
}

# ------------------------------------------------------------------------------
# S3 output bucket with public access blocked and SSE-KMS encryption
# ------------------------------------------------------------------------------

resource "aws_s3_bucket" "output_bucket" {
  bucket = var.output_bucket_name

  tags = {
    Name        = var.output_bucket_name
    Environment = "testing"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "output_bucket" {
  bucket                  = aws_s3_bucket.output_bucket.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "output_bucket" {
  bucket = aws_s3_bucket.output_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.output_bucket_key.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "output_bucket" {
  bucket = aws_s3_bucket.output_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

# ------------------------------------------------------------------------------
# ECR repositories with images that the HealthOmics service may pull
# ------------------------------------------------------------------------------

resource "aws_ecr_repository" "repositories" {
  for_each             = toset(var.ecr_repository_names)
  name                 = each.value
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  tags = {
    Environment = "testing"
  }
}

resource "aws_ecr_repository_policy" "repositories" {
  for_each   = aws_ecr_repository.repositories
  repository = each.value.name
  policy     = data.aws_iam_policy_document.ecr_repository_policy.json
}

# ------------------------------------------------------------------------------
# Outputs (no secrets)
# ------------------------------------------------------------------------------

output "health_omics_role_arn" {
  description = "ARN of the IAM role assumed by the AWS HealthOmics service."
  value       = aws_iam_role.health_omics.arn
}

output "health_omics_user_name" {
  description = "Name of the IAM user with programmatic access for HealthOmics workflows."
  value       = aws_iam_user.health_omics_user.name
}

output "health_omics_user_access_key_id" {
  description = "Access key ID of the HealthOmics service account user."
  value       = aws_iam_access_key.health_omics_user.id
}

output "output_bucket_name" {
  description = "Name of the S3 bucket used to store HealthOmics workflow outputs."
  value       = aws_s3_bucket.output_bucket.id
}

output "output_bucket_kms_key_arn" {
  description = "ARN of the customer-managed KMS key encrypting the HealthOmics output bucket."
  value       = aws_kms_key.output_bucket_key.arn
}

output "ecr_repositories" {
  description = "URLs of the ECR repositories used to store HealthOmics container images."
  value       = { for name, repo in aws_ecr_repository.repositories : name => repo.repository_url }
}

variable "cluster_name" {
  description = "Name of the ECS cluster"
  type        = string
  default     = "benchmark"
}

variable "vpc_cidr_network_octets" {
  description = "First two octets for VPC CIDR block (e.g. '10.0' yields 10.0.0.0/16)"
  type        = string
  default     = "10.0"
}

variable "default_tags" {
  description = "Default tags applied to all resources"
  type        = map(string)
  default     = {}
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  cluster_name_full = "dit-paas-${var.cluster_name}-cluster"
  vpc_cidr          = "${var.vpc_cidr_network_octets}.0.0/16"

  public_subnet_cidrs = [
    "${var.vpc_cidr_network_octets}.12.0/22",
    "${var.vpc_cidr_network_octets}.16.0/22",
    "${var.vpc_cidr_network_octets}.20.0/22",
  ]

  private_subnet_cidrs = [
    "${var.vpc_cidr_network_octets}.0.0/22",
    "${var.vpc_cidr_network_octets}.4.0/22",
    "${var.vpc_cidr_network_octets}.8.0/22",
  ]

  azs = slice(data.aws_availability_zones.available.names, 0, 3)
}

# ---------------------------------------------------------------------------
# VPC
# ---------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_hostnames = false

  tags = merge(var.default_tags, {
    Name = "${local.cluster_name_full}-vpc"
  })
}

# ---------------------------------------------------------------------------
# Public subnets (one per AZ)
# ---------------------------------------------------------------------------
resource "aws_subnet" "public" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  tags = merge(var.default_tags, {
    Name = "${local.cluster_name_full}-public-${count.index}"
  })
}

# ---------------------------------------------------------------------------
# Private subnets (one per AZ)
# ---------------------------------------------------------------------------
resource "aws_subnet" "private" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = merge(var.default_tags, {
    Name = "${local.cluster_name_full}-private-${count.index}"
  })
}

# ---------------------------------------------------------------------------
# Internet Gateway
# ---------------------------------------------------------------------------
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.default_tags, {
    Name = "${var.cluster_name}-ig"
  })
}

# ---------------------------------------------------------------------------
# Public route table (shared across all public subnets)
# ---------------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.default_tags, {
    Name = "${local.cluster_name_full}-public-rt"
  })
}

resource "aws_route" "public_default" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# Elastic IPs & NAT Gateways (one per public subnet)
# ---------------------------------------------------------------------------
resource "aws_eip" "nat" {
  count = 3

  domain = "vpc"

  tags = merge(var.default_tags, {
    Name = "${local.cluster_name_full}-eip-nat-${count.index}"
  })
}

resource "aws_nat_gateway" "main" {
  count = 3

  allocation_id = aws_eip.nat[count.index].allocation_id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(var.default_tags, {
    Name = "${local.cluster_name_full}-natgw-${count.index}"
  })
}

# ---------------------------------------------------------------------------
# Private route tables (dedicated per private subnet)
# ---------------------------------------------------------------------------
resource "aws_route_table" "private" {
  count = 3

  vpc_id = aws_vpc.main.id

  tags = merge(var.default_tags, {
    Name = "${local.cluster_name_full}-private-rt-${count.index}"
  })
}

resource "aws_route" "private_default" {
  count = 3

  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main[count.index].id
}

resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# ---------------------------------------------------------------------------
# ECS Cluster
# ---------------------------------------------------------------------------
resource "aws_ecs_cluster" "main" {
  name = local.cluster_name_full

  tags = merge(var.default_tags, {
    Name = local.cluster_name_full
  })
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.34"
    }
  }
}

variable "vpc_name" {
  description = "Name of the VPC"
  type        = string
  default     = "benchmark-vpc"
}

variable "cidr_block" {
  description = "Primary IPv4 CIDR block for the VPC"
  type        = string
  default     = "172.16.0.0/16"
}

variable "availability_zones" {
  description = "Availability zones to provision subnets across (first three zones of us-east-1)"
  type        = list(string)
  default     = ["us-east-1a", "us-east-1b", "us-east-1c"]
}

data "aws_region" "current" {}

locals {
  azs                  = var.availability_zones
  public_subnet_cidrs  = [for i in range(length(local.azs)) : cidrsubnet(var.cidr_block, 4, i)]
  private_subnet_cidrs = [for i in range(length(local.azs)) : cidrsubnet(var.cidr_block, 4, i + 8)]

  interface_endpoint_services = {
    ecr_docker = "ecr.dkr"
    ecr_api    = "ecr.api"
    logs       = "logs"
    ssm        = "ssm"
    kms        = "kms"
  }
}

# ------------------------------------------------------------------------------
# VPC (CloudPosse community module)
# ------------------------------------------------------------------------------
module "vpc" {
  source                           = "cloudposse/vpc/aws"
  version                          = "2.2.0"
  namespace                        = ""
  stage                            = ""
  name                             = var.vpc_name
  ipv4_primary_cidr_block          = var.cidr_block
  assign_generated_ipv6_cidr_block = false
  dns_hostnames_enabled            = true
  dns_support_enabled              = true
  default_security_group_deny_all  = true
}

# ------------------------------------------------------------------------------
# Public subnets + internet routing
# ------------------------------------------------------------------------------
resource "aws_subnet" "public" {
  count             = length(local.azs)
  vpc_id            = module.vpc.vpc_id
  cidr_block        = local.public_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]
  tags = {
    Name = "${var.vpc_name}-public-${local.azs[count.index]}"
  }
}

resource "aws_route_table" "public" {
  count  = length(local.azs)
  vpc_id = module.vpc.vpc_id
  tags = {
    Name = "${var.vpc_name}-public-rt-${local.azs[count.index]}"
  }
}

resource "aws_route_table_association" "public" {
  count          = length(local.azs)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[count.index].id
}

resource "aws_route" "public_igw" {
  count                  = length(local.azs)
  route_table_id         = aws_route_table.public[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = module.vpc.igw_id
}

# ------------------------------------------------------------------------------
# NAT gateway for outbound routing from private subnets
# ------------------------------------------------------------------------------
resource "aws_eip" "nat" {
  count  = 1
  domain = "vpc"
  tags = {
    Name = "${var.vpc_name}-nat-eip"
  }
}

resource "aws_nat_gateway" "main" {
  count         = 1
  allocation_id = aws_eip.nat[0].id
  subnet_id     = aws_subnet.public[0].id
  tags = {
    Name = "${var.vpc_name}-nat-gateway"
  }
}

# ------------------------------------------------------------------------------
# Private subnets + NAT routing
# ------------------------------------------------------------------------------
resource "aws_subnet" "private" {
  count             = length(local.azs)
  vpc_id            = module.vpc.vpc_id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]
  tags = {
    Name = "${var.vpc_name}-private-${local.azs[count.index]}"
  }
}

resource "aws_route_table" "private" {
  count  = length(local.azs)
  vpc_id = module.vpc.vpc_id
  tags = {
    Name = "${var.vpc_name}-private-rt-${local.azs[count.index]}"
  }
}

resource "aws_route_table_association" "private" {
  count          = length(local.azs)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_route" "private_nat" {
  count                  = length(local.azs)
  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main[0].id
}

# ------------------------------------------------------------------------------
# VPC endpoint security group (self-referencing TCP on port 443 only)
# ------------------------------------------------------------------------------
resource "aws_security_group" "vpc_endpoint_sg" {
  name        = "vpc_endpoint_sg"
  description = "Security group for VPC interface endpoints"
  vpc_id      = module.vpc.vpc_id
  tags = {
    Name = "vpc_endpoint_sg"
  }

  ingress {
    from_port = 443
    to_port   = 443
    protocol  = "tcp"
    self      = true
  }

  egress {
    from_port = 443
    to_port   = 443
    protocol  = "tcp"
    self      = true
  }
}

# ------------------------------------------------------------------------------
# S3 Gateway VPC endpoint (public, private and default route tables)
# ------------------------------------------------------------------------------
resource "aws_vpc_endpoint" "s3" {
  vpc_id            = module.vpc.vpc_id
  service_name      = "com.amazonaws.${data.aws_region.current.region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids = concat(
    [module.vpc.vpc_default_route_table_id],
    aws_route_table.public[*].id,
    aws_route_table.private[*].id,
  )
}

# ------------------------------------------------------------------------------
# Interface VPC endpoints (private DNS enabled, in private subnets)
# ECR Docker, ECR API, CloudWatch Logs, SSM, KMS
# ------------------------------------------------------------------------------
resource "aws_vpc_endpoint" "interface" {
  for_each            = local.interface_endpoint_services
  vpc_id              = module.vpc.vpc_id
  service_name        = "com.amazonaws.${data.aws_region.current.region}.${each.value}"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoint_sg.id]
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

locals {
  vpc_name = var.vpc_name

  # Determine the set of AWS interface endpoint services to create
  aws_endpoint_services = toset(var.aws_endpoint_services)

  # Determine if ssm is in the set
  ssm_enabled = contains(local.aws_endpoint_services, "ssm")

  # Standard AWS interface endpoint service names
  interface_service_map = {
    logs        = "com.amazonaws.${data.aws_region.current.region}.logs"
    ssm         = "com.amazonaws.${data.aws_region.current.region}.ssm"
    ec2         = "com.amazonaws.${data.aws_region.current.region}.ec2"
    ec2messages = "com.amazonaws.${data.aws_region.current.region}.ec2messages"
    ssmmessages = "com.amazonaws.${data.aws_region.current.region}.ssmmessages"
    kms         = "com.amazonaws.${data.aws_region.current.region}.kms"
    sts         = "com.amazonaws.${data.aws_region.current.region}.sts"
    monitoring  = "com.amazonaws.${data.aws_region.current.region}.monitoring"
    sqs         = "com.amazonaws.${data.aws_region.current.region}.sqs"
    sns         = "com.amazonaws.${data.aws_region.current.region}.sns"
    lambda      = "com.amazonaws.${data.aws_region.current.region}.lambda"
    ecr_api     = "com.amazonaws.${data.aws_region.current.region}.ecr.api"
    ecr_dkr     = "com.amazonaws.${data.aws_region.current.region}.ecr.dkr"
  }

  # Gateway endpoint service names
  gateway_service_map = {
    dynamodb = "com.amazonaws.${data.aws_region.current.region}.dynamodb"
    s3       = "com.amazonaws.${data.aws_region.current.region}.s3"
  }

  # List of AWS interface endpoint services from the aws_endpoint_services set
  # that are known in the interface_service_map
  interface_services = [for s in local.aws_endpoint_services : s if contains(keys(local.interface_service_map), s)]

  # Gateway services to create
  gateway_services_to_create = ["dynamodb", "s3"]

  # Route table IDs for gateway endpoints: use provided ones, or fall back to the VPC's main route table
  gateway_route_table_ids = length(var.gateway_endpoint_route_table_ids) > 0 ? var.gateway_endpoint_route_table_ids : [aws_vpc.this.main_route_table_id]

  # Whether interface endpoints should be created (need subnet IDs)
  create_interface_endpoints = length(var.interface_endpoint_subnet_ids) > 0 && length(local.interface_services) > 0

  # Whether custom endpoints should be created
  create_custom_endpoints = length(var.custom_endpoint_services) > 0 && length(var.interface_endpoint_subnet_ids) > 0
}

data "aws_region" "current" {}

# ---------------------------------------------------------------------------
# VPC
# ---------------------------------------------------------------------------
resource "aws_vpc" "this" {
  cidr_block           = var.vpc_cidr
  instance_tenancy     = var.instance_tenancy
  enable_dns_hostnames = var.enable_dns_hostnames
  enable_dns_support   = true

  tags = {
    Name = local.vpc_name
  }
}

# ---------------------------------------------------------------------------
# Default VPC Security Group Management
# ---------------------------------------------------------------------------
resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.this.id

  tags = {
    Name = "${local.vpc_name}-default-sg"
  }
}

# ---------------------------------------------------------------------------
# Custom Security Groups
# ---------------------------------------------------------------------------
resource "aws_security_group" "vpc_endpoints" {
  name_prefix = "vpc-endpoints-${local.vpc_name}-"
  description = "Security group for VPC interface endpoints"
  vpc_id      = aws_vpc.this.id

  tags = {
    Name = "vpc-endpoints-${local.vpc_name}"
  }
}

# Ingress for VPC endpoints SG: HTTPS from all allowed source SGs
resource "aws_security_group_rule" "vpc_endpoints_ingress" {
  for_each = toset(var.endpoint_source_security_group_ids)

  type                     = "ingress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  cidr_blocks              = []
  security_group_id        = aws_security_group.vpc_endpoints.id
  source_security_group_id = each.value
  description              = "HTTPS from source SG ${each.value}"
}

# Egress for VPC endpoints SG: HTTPS to all allowed source SGs
resource "aws_security_group_rule" "vpc_endpoints_egress" {
  for_each = toset(var.endpoint_source_security_group_ids)

  type                     = "egress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  cidr_blocks              = []
  security_group_id        = aws_security_group.vpc_endpoints.id
  source_security_group_id = each.value
  description              = "HTTPS to source SG ${each.value}"
}

# ---------------------------------------------------------------------------
# Custom Endpoint Services Security Groups
# ---------------------------------------------------------------------------
resource "aws_security_group" "custom_endpoint" {
  for_each = { for idx, svc in var.custom_endpoint_services : svc.key => svc }

  name_prefix = "custom-ep-${each.value.key}-${local.vpc_name}-"
  description = "Security group for custom endpoint service ${each.value.key}"
  vpc_id      = aws_vpc.this.id

  tags = {
    Name = "custom-ep-${each.value.key}-${local.vpc_name}"
  }
}

# Ingress rules for custom endpoint SGs: per service port from each source SG
resource "aws_security_group_rule" "custom_endpoint_ingress" {
  for_each = {
    for pair in flatten([
      for svc in var.custom_endpoint_services : [
        for sg_id in var.endpoint_source_security_group_ids : {
          key   = "${svc.key}-${sg_id}"
          key_s = svc.key
          port  = svc.port
          sg_id = sg_id
        }
      ]
    ]) : pair.key => pair
  }

  type                     = "ingress"
  from_port                = each.value.port
  to_port                  = each.value.port
  protocol                 = "tcp"
  cidr_blocks              = []
  security_group_id        = aws_security_group.custom_endpoint[each.value.key_s].id
  source_security_group_id = each.value.sg_id
  description              = "Port ${each.value.port} from SG ${each.value.sg_id}"
}

# Egress rules for custom endpoint SGs: per service port to each source SG
resource "aws_security_group_rule" "custom_endpoint_egress" {
  for_each = {
    for pair in flatten([
      for svc in var.custom_endpoint_services : [
        for sg_id in var.endpoint_source_security_group_ids : {
          key   = "${svc.key}-${sg_id}"
          key_s = svc.key
          port  = svc.port
          sg_id = sg_id
        }
      ]
    ]) : pair.key => pair
  }

  type                     = "egress"
  from_port                = each.value.port
  to_port                  = each.value.port
  protocol                 = "tcp"
  cidr_blocks              = []
  security_group_id        = aws_security_group.custom_endpoint[each.value.key_s].id
  source_security_group_id = each.value.sg_id
  description              = "Port ${each.value.port} to SG ${each.value.sg_id}"
}

# ---------------------------------------------------------------------------
# VPC Flow Logs
# ---------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "flow_logs" {
  name              = "/aws/vpc-flow-logs/${local.vpc_name}"
  retention_in_days = 180

  tags = {
    Name = "/aws/vpc-flow-logs/${local.vpc_name}"
  }
}

resource "aws_iam_role" "flow_logs" {
  name = "vpc_flow_logs_${local.vpc_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "vpc_flow_logs_${local.vpc_name}"
  }
}

resource "aws_iam_role_policy" "flow_logs" {
  name = "vpc_flow_logs_${local.vpc_name}_policy"
  role = aws_iam_role.flow_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = "${aws_cloudwatch_log_group.flow_logs.arn}:*"
      }
    ]
  })
}

resource "aws_flow_log" "this" {
  iam_role_arn    = aws_iam_role.flow_logs.arn
  log_destination = aws_cloudwatch_log_group.flow_logs.arn
  traffic_type    = "ALL"
  vpc_id          = aws_vpc.this.id

  tags = {
    Name = "${local.vpc_name}-flow-log"
  }
}

# ---------------------------------------------------------------------------
# Gateway VPC Endpoints (dynamodb, s3)
# Uses the VPC's main route table if no route table IDs are provided via var.
# ---------------------------------------------------------------------------
resource "aws_vpc_endpoint" "gateway" {
  for_each = toset(local.gateway_services_to_create)

  vpc_id            = aws_vpc.this.id
  service_name      = local.gateway_service_map[each.value]
  vpc_endpoint_type = "Gateway"
  route_table_ids   = local.gateway_route_table_ids

  tags = {
    Name = "${each.value}-${local.vpc_name}"
  }
}

# ---------------------------------------------------------------------------
# Interface VPC Endpoints for Standard AWS Services (private DNS enabled)
# Only created when subnet IDs are provided via var.interface_endpoint_subnet_ids.
# ---------------------------------------------------------------------------
resource "aws_vpc_endpoint" "interface" {
  for_each = local.create_interface_endpoints ? toset(local.interface_services) : toset([])

  vpc_id              = aws_vpc.this.id
  service_name        = local.interface_service_map[each.value]
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  subnet_ids          = var.interface_endpoint_subnet_ids
  security_group_ids  = [aws_security_group.vpc_endpoints.id]

  tags = {
    Name = "${each.value}-${local.vpc_name}"
  }
}

# ---------------------------------------------------------------------------
# Interface VPC Endpoints for Custom Endpoint Services (private DNS disabled)
# Only created when subnet IDs and custom endpoint services are provided.
# ---------------------------------------------------------------------------
resource "aws_vpc_endpoint" "custom" {
  for_each = local.create_custom_endpoints ? { for idx, svc in var.custom_endpoint_services : svc.key => svc } : {}

  vpc_id              = aws_vpc.this.id
  service_name        = each.value.service_name
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = false
  subnet_ids          = var.interface_endpoint_subnet_ids
  security_group_ids  = [aws_security_group.custom_endpoint[each.value.key].id]

  tags = {
    Name = "custom-${each.value.key}-${local.vpc_name}"
  }
}

# ---------------------------------------------------------------------------
# SSM Role and Instance Profile (if "ssm" is in aws_endpoint_services)
# ---------------------------------------------------------------------------
resource "aws_iam_role" "ssm" {
  count = local.ssm_enabled ? 1 : 0

  name = "ssm_${local.vpc_name}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "ssm_${local.vpc_name}"
  }
}

resource "aws_iam_role_policy_attachment" "ssm" {
  count = local.ssm_enabled ? 1 : 0

  role       = aws_iam_role.ssm[0].name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ssm" {
  count = local.ssm_enabled ? 1 : 0

  name = "ssm_${local.vpc_name}"
  role = aws_iam_role.ssm[0].name

  tags = {
    Name = "ssm_${local.vpc_name}"
  }
}

data "aws_partition" "current" {}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------
variable "vpc_name" {
  description = "Name tag for the VPC and derived resource names"
  type        = string
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  description = "Primary CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "instance_tenancy" {
  description = "Instance tenancy for the VPC"
  type        = string
  default     = "default"
}

variable "enable_dns_hostnames" {
  description = "Enable DNS hostnames in the VPC"
  type        = bool
  default     = true
}

variable "aws_endpoint_services" {
  description = "Set of AWS service names to create Interface VPC endpoints for (private DNS enabled)"
  type        = set(string)
  default     = ["logs"]
}

variable "endpoint_source_security_group_ids" {
  description = "List of source security group IDs for VPC endpoint and custom endpoint security group rules"
  type        = list(string)
  default     = []
}

variable "gateway_endpoint_route_table_ids" {
  description = "List of route table IDs to associate with Gateway endpoints (dynamodb, s3). Defaults to the VPC's main route table."
  type        = list(string)
  default     = []
}

variable "interface_endpoint_subnet_ids" {
  description = "List of subnet IDs to create Interface VPC endpoints in. Required for interface endpoints."
  type        = list(string)
  default     = []
}

variable "custom_endpoint_services" {
  description = "List of custom endpoint service definitions, each with key, service_name, and port"
  type = list(object({
    key          = string
    service_name = string
    port         = number
  }))
  default = []
}

variable "project_name" {
  description = "Project name used in KMS key aliases"
  type        = string
  default     = "myproject"
}

variable "external_ebs_kms_key_arn" {
  description = "Optional external KMS key ARN for default EBS encryption. If left empty, the internal compute KMS key is used."
  type        = string
  default     = ""
}

variable "key_rotation_period_in_days" {
  description = "Rotation period in days for KMS customer-managed keys"
  type        = number
  default     = 90
}

variable "imdsv2_hop_limit" {
  description = "Hop limit for EC2 instance metadata service (IMDSv2)"
  type        = number
  default     = 1
}

variable "enable_imdsv2" {
  description = "Toggle to enforce IMDSv2 as the default for EC2 instances"
  type        = bool
  default     = true
}

variable "disable_serial_console" {
  description = "Toggle to disable EC2 Serial Console access at the account level"
  type        = bool
  default     = true
}

variable "enable_emr_block_public_access" {
  description = "Toggle to enable EMR block public access configuration"
  type        = bool
  default     = true
}

# ---------------------------------------------------------------------------
# Data sources (static account metadata only)
# ---------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.region
  partition  = data.aws_partition.current.partition
  ebs_key_arn = var.external_ebs_kms_key_arn != "" ? var.external_ebs_kms_key_arn : aws_kms_key.compute.arn
}

# ---------------------------------------------------------------------------
# KMS key policy documents
# ---------------------------------------------------------------------------

# Compute KMS key policy – IAM root, EC2 service, Auto Scaling
data "aws_iam_policy_document" "compute_kms" {
  statement {
    sid    = "EnableRootAccess"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowEC2Service"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["ec2.${local.region}.amazonaws.com"]
    }
  }

  statement {
    sid    = "AllowAutoScalingService"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["autoscaling.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
      "kms:CreateGrant",
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["ec2.${local.region}.amazonaws.com"]
    }
  }
}

# Observability KMS key policy – IAM root, CloudWatch Logs, CloudTrail,
# CloudWatch Alarms, SNS, SQS, EventBridge
data "aws_iam_policy_document" "observability_kms" {
  statement {
    sid    = "EnableRootAccess"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudWatchLogs"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["logs.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]
    resources = ["*"]
    condition {
      test     = "ArnLike"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = ["arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:*"]
    }
  }

  statement {
    sid    = "AllowCloudTrail"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudWatchAlarms"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudwatch.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AllowSNS"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AllowSQS"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["sqs.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AllowEventBridge"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]
    resources = ["*"]
  }
}

# Storage KMS key policy – IAM root, S3, AWS Config, CloudTrail
data "aws_iam_policy_document" "storage_kms" {
  statement {
    sid    = "EnableRootAccess"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowS3Service"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["s3.${local.region}.amazonaws.com"]
    }
  }

  statement {
    sid    = "AllowConfig"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudTrail"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]
    resources = ["*"]
  }
}

# ---------------------------------------------------------------------------
# KMS keys and aliases
# ---------------------------------------------------------------------------

resource "aws_kms_key" "compute" {
  description             = "KMS key for compute layer – ${var.project_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  rotation_period_in_days = var.key_rotation_period_in_days
  policy                  = data.aws_iam_policy_document.compute_kms.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "compute" {
  name          = "alias/${var.project_name}-compute"
  target_key_id = aws_kms_key.compute.key_id
}

resource "aws_kms_key" "observability" {
  description             = "KMS key for observability layer – ${var.project_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  rotation_period_in_days = var.key_rotation_period_in_days
  policy                  = data.aws_iam_policy_document.observability_kms.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "observability" {
  name          = "alias/${var.project_name}-observability"
  target_key_id = aws_kms_key.observability.key_id
}

resource "aws_kms_key" "storage" {
  description             = "KMS key for storage layer – ${var.project_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  rotation_period_in_days = var.key_rotation_period_in_days
  policy                  = data.aws_iam_policy_document.storage_kms.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "storage" {
  name          = "alias/${var.project_name}-storage"
  target_key_id = aws_kms_key.storage.key_id
}

# ---------------------------------------------------------------------------
# Account-level default EBS encryption
# ---------------------------------------------------------------------------

resource "aws_ebs_encryption_by_default" "this" {
  enabled = true
}

resource "aws_ebs_default_kms_key" "this" {
  key_arn = local.ebs_key_arn
}

# ---------------------------------------------------------------------------
# EC2 Image Block Public Access
# ---------------------------------------------------------------------------

resource "aws_ec2_image_block_public_access" "this" {
  state = "block-new-sharing"
}

# ---------------------------------------------------------------------------
# EBS Snapshot Block Public Access
# ---------------------------------------------------------------------------

resource "aws_ebs_snapshot_block_public_access" "this" {
  state = "block-all-sharing"
}

# ---------------------------------------------------------------------------
# EC2 Instance Metadata Defaults (IMDSv2)
# ---------------------------------------------------------------------------

resource "aws_ec2_instance_metadata_defaults" "this" {
  count = var.enable_imdsv2 ? 1 : 0

  http_tokens                 = "required"
  http_put_response_hop_limit = var.imdsv2_hop_limit
}

# ---------------------------------------------------------------------------
# EC2 Serial Console Access (disabled)
# ---------------------------------------------------------------------------

resource "aws_ec2_serial_console_access" "this" {
  count = var.disable_serial_console ? 1 : 0

  enabled = false
}

# ---------------------------------------------------------------------------
# EMR Block Public Access
# ---------------------------------------------------------------------------

resource "aws_emr_block_public_access_configuration" "this" {
  count = var.enable_emr_block_public_access ? 1 : 0

  block_public_security_group_rules = true
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------
variable "cluster_prefix" {
  description = "Prefix for naming cluster resources (5-8 characters)"
  type        = string
  default     = "bench"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "172.16.0.0/16"
}

variable "availability_zones" {
  description = "List of availability zones to use (defaults to all available)"
  type        = list(string)
  default     = []
}

variable "key_name" {
  description = "Name for the SSH key pair"
  type        = string
  default     = "benchmark-keypair"
}

variable "public_key" {
  description = "Public key material for SSH access"
  type        = string
  default     = "ssh-rsa  benchmark-keypair"
}

variable "ingress_cidr_rules" {
  description = "List of custom ingress CIDR rules for the default security group"
  type = list(object({
    cidr        = string
    from_port   = number
    to_port     = number
    protocol    = string
    description = optional(string)
  }))
  default = []
}

variable "inventory_nodes" {
  description = "List of EC2 inventory node configurations"
  type = list(object({
    instance_type = string
    subnet_type   = optional(string, "public")
    subnet_index  = optional(number)
    assign_eip    = optional(bool, false)
    ebs_optimized = optional(bool, true)
    root_volume = object({
      volume_type           = optional(string, "gp3")
      volume_size           = optional(number, 20)
      encrypted             = optional(bool, true)
      delete_on_termination = optional(bool, true)
    })
    additional_volumes = optional(list(object({
      device_name           = string
      volume_type           = optional(string, "gp3")
      volume_size           = number
      encrypted             = optional(bool, true)
      delete_on_termination = optional(bool, true)
    })), [])
  }))
  default = [
    {
      instance_type = "t3.micro"
      subnet_type   = "public"
      assign_eip    = false
      root_volume = {
        volume_size = 20
      }
      additional_volumes = [
        {
          device_name = "/dev/xvdb"
          volume_size = 10
        }
      ]
    }
  ]
}

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------
locals {
  # Validate cluster_prefix length (5-8 chars)
  cluster_prefix = length(var.cluster_prefix) >= 5 && length(var.cluster_prefix) <= 8 ? var.cluster_prefix : "bench"

  # Tags
  tags = {
    Environment = "testing"
    ManagedBy   = "terraform"
    Cluster     = local.cluster_prefix
  }

  # Number of AZs to use: min of requested AZs and what's available
  az_names     = data.aws_availability_zones.available.names
  num_azs      = min(length(var.availability_zones) > 0 ? length(var.availability_zones) : length(local.az_names), length(local.az_names))
  selected_azs = slice(local.az_names, 0, local.num_azs)

  # Subnet bits for CIDR calculation
  subnet_bits = 8

  # Build subnet specifications
  public_subnets = [
    for idx in range(local.num_azs) : {
      az       = local.selected_azs[idx]
      cidr     = cidrsubnet(var.vpc_cidr, local.subnet_bits, idx)
      type     = "public"
      az_index = idx
    }
  ]

  private_subnets = [
    for idx in range(local.num_azs) : {
      az       = local.selected_azs[idx]
      cidr     = cidrsubnet(var.vpc_cidr, local.subnet_bits, idx + local.num_azs)
      type     = "private"
      az_index = idx
    }
  ]

  # Map each node to a subnet (by index position)
  node_subnet_map = [
    for idx, node in var.inventory_nodes : {
      node        = node
      subnet_type = node.subnet_type == "private" ? "private" : "public"
      subnet_idx  = node.subnet_index != null ? node.subnet_index : (idx % local.num_azs)
      idx         = idx
    }
  ]

  # Indices of nodes that need Elastic IP association
  eip_node_indices = [for idx, node in var.inventory_nodes : idx if lookup(node, "assign_eip", false) == true]
}

# ---------------------------------------------------------------------------
# Data sources: static provider metadata only
# ---------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }
}

# ---------------------------------------------------------------------------
# VPC
# ---------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, { Name = "${local.cluster_prefix}-vpc" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.tags, { Name = "${local.cluster_prefix}-igw" })
}

# ---------------------------------------------------------------------------
# SSH Key Pair
# ---------------------------------------------------------------------------
resource "aws_key_pair" "deploy" {
  key_name   = var.key_name
  public_key = var.public_key

  tags = merge(local.tags, { Name = var.key_name })
}

# ---------------------------------------------------------------------------
# Subnets
# ---------------------------------------------------------------------------
resource "aws_subnet" "public" {
  count = length(local.public_subnets)

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.public_subnets[count.index].cidr
  availability_zone = local.public_subnets[count.index].az

  map_public_ip_on_launch = false

  tags = merge(local.tags, {
    Name = "${local.cluster_prefix}-public-${count.index}"
    Type = "public"
  })
}

resource "aws_subnet" "private" {
  count = length(local.private_subnets)

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnets[count.index].cidr
  availability_zone = local.private_subnets[count.index].az

  tags = merge(local.tags, {
    Name = "${local.cluster_prefix}-private-${count.index}"
    Type = "private"
  })
}

# ---------------------------------------------------------------------------
# Public route table
# ---------------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.tags, { Name = "${local.cluster_prefix}-public-rt" })
}

resource "aws_route_table_association" "public" {
  count = length(local.public_subnets)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# Elastic IPs for NAT Gateways
# ---------------------------------------------------------------------------
resource "aws_eip" "nat" {
  count = length(local.public_subnets)

  domain = "vpc"

  tags = merge(local.tags, { Name = "${local.cluster_prefix}-nat-eip-${count.index}" })
}

# ---------------------------------------------------------------------------
# NAT Gateways (one per public subnet)
# ---------------------------------------------------------------------------
resource "aws_nat_gateway" "main" {
  count = length(local.public_subnets)

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(local.tags, { Name = "${local.cluster_prefix}-nat-${count.index}" })

  depends_on = [aws_internet_gateway.main]
}

# ---------------------------------------------------------------------------
# Private route tables (one per AZ, routing through its NAT Gateway)
# ---------------------------------------------------------------------------
resource "aws_route_table" "private" {
  count = length(local.private_subnets)

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }

  tags = merge(local.tags, { Name = "${local.cluster_prefix}-private-rt-${count.index}" })
}

resource "aws_route_table_association" "private" {
  count = length(local.private_subnets)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# ---------------------------------------------------------------------------
# Default Security Group
# ---------------------------------------------------------------------------
resource "aws_security_group" "default" {
  name        = "${local.cluster_prefix}-default-sg"
  description = "Default security group for ${local.cluster_prefix} cluster"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.tags, { Name = "${local.cluster_prefix}-default-sg" })
}

# Full self-referencing intra-group ingress
resource "aws_vpc_security_group_ingress_rule" "self" {
  security_group_id = aws_security_group.default.id

  referenced_security_group_id = aws_security_group.default.id
  from_port                    = 0
  to_port                      = 65535
  ip_protocol                  = "tcp"
  description                  = "Self-referencing intra-group ingress"
}

# Outbound traffic only within VPC CIDR
resource "aws_vpc_security_group_egress_rule" "vpc_cidr" {
  security_group_id = aws_security_group.default.id

  cidr_ipv4   = aws_vpc.main.cidr_block
  from_port   = 0
  to_port     = 65535
  ip_protocol = "tcp"
  description = "Outbound within VPC CIDR"
}

# Custom dynamic ingress CIDR rules
resource "aws_vpc_security_group_ingress_rule" "custom_cidr" {
  count = length(var.ingress_cidr_rules)

  security_group_id = aws_security_group.default.id

  cidr_ipv4   = var.ingress_cidr_rules[count.index].cidr
  from_port   = var.ingress_cidr_rules[count.index].from_port
  to_port     = var.ingress_cidr_rules[count.index].to_port
  ip_protocol = var.ingress_cidr_rules[count.index].protocol
  description = try(var.ingress_cidr_rules[count.index].description, "Custom ingress from ${var.ingress_cidr_rules[count.index].cidr}")
}

# ---------------------------------------------------------------------------
# KMS Key for EBS encryption
# ---------------------------------------------------------------------------
resource "aws_kms_key" "ebs" {
  description             = "${local.cluster_prefix} EBS encryption key"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.tags, { Name = "${local.cluster_prefix}-ebs-key" })
}

# ---------------------------------------------------------------------------
# EC2 Inventory Nodes
# ---------------------------------------------------------------------------
resource "aws_instance" "node" {
  count = length(var.inventory_nodes)

  ami                         = data.aws_ami.amazon_linux_2.id
  instance_type               = local.node_subnet_map[count.index].node.instance_type
  key_name                    = aws_key_pair.deploy.key_name
  subnet_id                   = local.node_subnet_map[count.index].subnet_type == "public" ? aws_subnet.public[local.node_subnet_map[count.index].subnet_idx].id : aws_subnet.private[local.node_subnet_map[count.index].subnet_idx].id
  ebs_optimized               = lookup(local.node_subnet_map[count.index].node, "ebs_optimized", true)
  vpc_security_group_ids      = [aws_security_group.default.id]
  associate_public_ip_address = local.node_subnet_map[count.index].subnet_type == "public" && lookup(local.node_subnet_map[count.index].node, "assign_eip", false) == false

  metadata_options {
    http_tokens = "required"
  }

  root_block_device {
    volume_type           = lookup(local.node_subnet_map[count.index].node.root_volume, "volume_type", "gp3")
    volume_size           = lookup(local.node_subnet_map[count.index].node.root_volume, "volume_size", 20)
    encrypted             = lookup(local.node_subnet_map[count.index].node.root_volume, "encrypted", true)
    kms_key_id            = aws_kms_key.ebs.arn
    delete_on_termination = lookup(local.node_subnet_map[count.index].node.root_volume, "delete_on_termination", true)

    tags = merge(local.tags, {
      Name = "${local.cluster_prefix}-node-${count.index}-root"
    })
  }

  dynamic "ebs_block_device" {
    for_each = lookup(local.node_subnet_map[count.index].node, "additional_volumes", [])

    content {
      device_name           = ebs_block_device.value.device_name
      volume_type           = lookup(ebs_block_device.value, "volume_type", "gp3")
      volume_size           = ebs_block_device.value.volume_size
      encrypted             = lookup(ebs_block_device.value, "encrypted", true)
      kms_key_id            = aws_kms_key.ebs.arn
      delete_on_termination = lookup(ebs_block_device.value, "delete_on_termination", true)
      tags = merge(local.tags, {
        Name = "${local.cluster_prefix}-node-${count.index}-${replace(ebs_block_device.value.device_name, "/dev/", "")}"
      })
    }
  }

  tags = merge(local.tags, {
    Name = "${local.cluster_prefix}-node-${count.index}"
    Type = "inventory-node"
  })
}

# Optional Elastic IPs for nodes
resource "aws_eip" "node" {
  count = length(var.inventory_nodes)

  domain = "vpc"

  tags = merge(local.tags, { Name = "${local.cluster_prefix}-node-eip-${count.index}" })
}

resource "aws_eip_association" "node" {
  count = length(local.eip_node_indices)

  instance_id   = aws_instance.node[local.eip_node_indices[count.index]].id
  allocation_id = aws_eip.node[local.eip_node_indices[count.index]].id
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------
output "vpc_id" {
  description = "ID of the created VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets"
  value       = aws_subnet.private[*].id
}

output "default_security_group_id" {
  description = "ID of the default security group"
  value       = aws_security_group.default.id
}

output "nat_gateway_ips" {
  description = "Elastic IPs associated with NAT Gateways"
  value       = aws_eip.nat[*].public_ip
}

output "instance_ids" {
  description = "IDs of the provisioned EC2 instances"
  value       = aws_instance.node[*].id
}

output "instance_public_ips" {
  description = "Public IPs of provisioned instances (if any)"
  value       = aws_instance.node[*].public_ip
}

# ---------------------------------------------------------------------------
# benchmark-vpc networking module
# ---------------------------------------------------------------------------

# ── Variables ────────────────────────────────────────────────────────────────

variable "vpc_name" {
  description = "Name tag for the VPC"
  type        = string
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

variable "enable_private_subnets" {
  description = "Toggle to create private subnets (2 public + 2 private) vs 4 public"
  type        = bool
  default     = true
}

variable "nat_gateway_enabled" {
  description = "Deploy NAT Gateways in each public subnet with private route tables"
  type        = bool
  default     = false
}

variable "nat_instance_enabled" {
  description = "Deploy NAT EC2 instances (m1.small) in each public subnet"
  type        = bool
  default     = false
}

variable "egress_only_igw_enabled" {
  description = "Create an Egress-Only Internet Gateway with IPv6 routes"
  type        = bool
  default     = false
}

# ── Validation ──────────────────────────────────────────────────────────────

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

locals {
  # Count how many egress strategies are enabled (should be 0 or 1)
  egress_count = sum([
    var.nat_gateway_enabled ? 1 : 0,
    var.nat_instance_enabled ? 1 : 0,
    var.egress_only_igw_enabled ? 1 : 0,
  ])
}

# Resource used only for plan-time precondition validation
resource "terraform_data" "validation" {
  lifecycle {
    precondition {
      condition     = local.egress_count <= 1
      error_message = "Egress strategies are mutually exclusive: enable at most one of nat_gateway_enabled, nat_instance_enabled, egress_only_igw_enabled."
    }
    precondition {
      condition     = !(local.egress_count > 0) || var.enable_private_subnets
      error_message = "Egress strategies (NAT Gateway, NAT Instance, Egress-Only IGW) require enable_private_subnets = true."
    }
  }
}

# ── Data Sources ────────────────────────────────────────────────────────────

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "nat" {
  count       = var.nat_instance_enabled ? 1 : 0
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn-nat-*"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }
}

# ── VPC ─────────────────────────────────────────────────────────────────────

resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr
  assign_generated_ipv6_cidr_block = var.egress_only_igw_enabled

  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = var.vpc_name
  }
}

# ── Internet Gateway ────────────────────────────────────────────────────────

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-igw"
  }
}

# ── Security Groups ─────────────────────────────────────────────────────────

# Default SG – self-referencing ingress and egress only
resource "aws_security_group" "default" {
  name        = "${var.vpc_name}-default-sg"
  description = "Default security group - self-referencing ingress and egress"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-default-sg"
  }
}

resource "aws_security_group_rule" "default_ingress_self" {
  type              = "ingress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  self              = true
  security_group_id = aws_security_group.default.id
}

resource "aws_security_group_rule" "default_egress_self" {
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  self              = true
  security_group_id = aws_security_group.default.id
}

# TLS SG – inbound TLS on 443
resource "aws_security_group" "tls" {
  name        = "${var.vpc_name}-tls-sg"
  description = "Allow inbound TLS traffic on port 443"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-tls-sg"
  }
}

resource "aws_security_group_rule" "tls_ingress" {
  type              = "ingress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.tls.id
}

# NAT Instance SG (only created when nat_instance_enabled)
resource "aws_security_group" "nat_instance" {
  count       = var.nat_instance_enabled ? 1 : 0
  name        = "${var.vpc_name}-nat-instance-sg"
  description = "Security group for NAT instances"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-nat-instance-sg"
  }
}

resource "aws_security_group_rule" "nat_instance_inbound" {
  count             = var.nat_instance_enabled ? 1 : 0
  type              = "ingress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = var.enable_private_subnets ? var.private_subnet_cidrs : []
  security_group_id = aws_security_group.nat_instance[0].id
}

resource "aws_security_group_rule" "nat_instance_outbound" {
  count             = var.nat_instance_enabled ? 1 : 0
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.nat_instance[0].id
}

# ── Local helpers for subnet counts / CIDR lists ───────────────────────────

locals {
  az_list         = data.aws_availability_zones.available.names
  all_cidrs       = concat(var.public_subnet_cidrs, var.private_subnet_cidrs)

  # When private subnets are enabled: 2 public (first 2 CIDRs) + 2 private (last 2 CIDRs);
  # otherwise: 4 public (all 4 CIDRs)
  public_cidr_list  = var.enable_private_subnets ? var.public_subnet_cidrs : local.all_cidrs
  private_cidr_list = var.enable_private_subnets ? var.private_subnet_cidrs : []

  public_count  = length(local.public_cidr_list)
  private_count = length(local.private_cidr_list)
}

# ── Subnets ─────────────────────────────────────────────────────────────────

resource "aws_subnet" "public" {
  count = local.public_count

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_cidr_list[count.index]
  availability_zone       = local.az_list[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.vpc_name}-public-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count = local.private_count

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_cidr_list[count.index]
  availability_zone       = local.az_list[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.vpc_name}-private-${count.index + 1}"
  }
}

# ── Route Table – Public (main) ────────────────────────────────────────────

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-public"
  }
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count         = local.public_count
  subnet_id     = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ── NAT Gateways ───────────────────────────────────────────────────────────

resource "aws_eip" "nat_gateway" {
  count = var.nat_gateway_enabled && var.enable_private_subnets ? local.public_count : 0
  domain = "vpc"

  tags = {
    Name = "${var.vpc_name}-nat-gw-eip-${count.index + 1}"
  }
}

resource "aws_nat_gateway" "this" {
  count = var.nat_gateway_enabled && var.enable_private_subnets ? local.public_count : 0

  subnet_id     = aws_subnet.public[count.index].id
  connectivity_type = "public"
  allocation_id = aws_eip.nat_gateway[count.index].id

  tags = {
    Name = "${var.vpc_name}-nat-gw-${count.index + 1}"
  }
}

# Private route tables for NAT Gateways
resource "aws_route_table" "private_nat_gw" {
  count = var.nat_gateway_enabled && var.enable_private_subnets ? local.private_count : 0

  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-private-natgw-${count.index + 1}"
  }
}

resource "aws_route" "private_nat_gw" {
  count = var.nat_gateway_enabled && var.enable_private_subnets ? local.private_count : 0

  route_table_id         = aws_route_table.private_nat_gw[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.this[count.index].id
}

resource "aws_route_table_association" "private_nat_gw" {
  count = var.nat_gateway_enabled && var.enable_private_subnets ? local.private_count : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private_nat_gw[count.index].id
}

# ── NAT Instances ──────────────────────────────────────────────────────────

resource "aws_instance" "nat" {
  count = var.nat_instance_enabled && var.enable_private_subnets ? local.public_count : 0

  subnet_id                   = aws_subnet.public[count.index].id
  instance_type               = "m1.small"
  ami                         = data.aws_ami.nat[0].id
  vpc_security_group_ids      = [aws_security_group.nat_instance[0].id]
  associate_public_ip_address = true
  source_dest_check           = false

  tags = {
    Name = "${var.vpc_name}-nat-instance-${count.index + 1}"
  }
}

# Private route tables for NAT Instances
resource "aws_route_table" "private_nat_instance" {
  count = var.nat_instance_enabled && var.enable_private_subnets ? local.private_count : 0

  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-private-natins-${count.index + 1}"
  }
}

resource "aws_route" "private_nat_instance" {
  count = var.nat_instance_enabled && var.enable_private_subnets ? local.private_count : 0

  route_table_id         = aws_route_table.private_nat_instance[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  network_interface_id   = aws_instance.nat[count.index].primary_network_interface_id
}

resource "aws_route_table_association" "private_nat_instance" {
  count = var.nat_instance_enabled && var.enable_private_subnets ? local.private_count : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private_nat_instance[count.index].id
}

# ── Egress-Only Internet Gateway ───────────────────────────────────────────

resource "aws_egress_only_internet_gateway" "this" {
  count = var.egress_only_igw_enabled && var.enable_private_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-eigw"
  }
}

# Private route tables for Egress-Only IGW
resource "aws_route_table" "private_eigw" {
  count = var.egress_only_igw_enabled && var.enable_private_subnets ? local.private_count : 0

  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-private-eigw-${count.index + 1}"
  }
}

resource "aws_route" "private_eigw" {
  count = var.egress_only_igw_enabled && var.enable_private_subnets ? local.private_count : 0

  route_table_id          = aws_route_table.private_eigw[count.index].id
  destination_ipv6_cidr_block = "::/0"
  egress_only_gateway_id  = aws_egress_only_internet_gateway.this[0].id
}

resource "aws_route_table_association" "private_eigw" {
  count = var.egress_only_igw_enabled && var.enable_private_subnets ? local.private_count : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private_eigw[count.index].id
}

data "aws_caller_identity" "current" {}

variable "environment_name" {
  description = "Environment name used as a prefix for all resource names"
  type        = string
  default     = "benchmark"
}

variable "primary_region" {
  description = "Primary AWS region for Terraform state and access logs buckets"
  type        = string
  default     = "us-east-1"
}

variable "secondary_region" {
  description = "Secondary AWS region for replica buckets (disaster recovery)"
  type        = string
  default     = "us-west-2"
}

variable "glacier_transition_days" {
  description = "Number of days before objects transition to Glacier storage class"
  type        = number
  default     = 7
}

variable "expiration_days" {
  description = "Number of additional days after Glacier transition before objects expire"
  type        = number
  default     = 30
}

locals {
  account_id = data.aws_caller_identity.current.account_id

  # Bucket name format: {env}-{purpose}-{region}-{account}
  # The account suffix guarantees globally-unique bucket names so the template
  # is fully self-contained and never collides with existing infrastructure.
  state_bucket_name          = "${var.environment_name}-terraform-state-${var.primary_region}-${local.account_id}"
  access_logs_bucket_name    = "${var.environment_name}-terraform-access-logs-${var.primary_region}-${local.account_id}"
  replica_state_bucket_name  = "${var.environment_name}-terraform-state-replica-${var.secondary_region}-${local.account_id}"
  replica_logs_bucket_name   = "${var.environment_name}-terraform-access-logs-replica-${var.secondary_region}-${local.account_id}"

  # Shared bucket policy restricting all S3 actions to requests from the same account
  # (bucket-owner-full-control is implicitly guaranteed because the bucket owner is the
  # same account that owns the KMS keys and IAM identities used here)
  state_bucket_policy = {
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource  = [
          "arn:aws:s3:::${local.state_bucket_name}",
          "arn:aws:s3:::${local.state_bucket_name}/*"
        ]
        Condition = {
          StringNotEquals = {
            "aws:PrincipalAccount" = local.account_id
          }
        }
      }
    ]
  }

  replica_state_bucket_policy = {
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource  = [
          "arn:aws:s3:::${local.replica_state_bucket_name}",
          "arn:aws:s3:::${local.replica_state_bucket_name}/*"
        ]
        Condition = {
          StringNotEquals = {
            "aws:PrincipalAccount" = local.account_id
          }
        }
      }
    ]
  }
}

# --------------------------------------------------------------------------
# KMS Keys
# --------------------------------------------------------------------------

resource "aws_kms_key" "state_bucket" {
  description             = "KMS key for server-side encryption of ${local.state_bucket_name}"
  deletion_window_in_days = 10
  tags = {
    environment = var.environment_name
  }
}

resource "aws_kms_key" "replica_state_bucket" {
  description             = "KMS key for server-side encryption of ${local.replica_state_bucket_name} with automatic rotation"
  deletion_window_in_days = 10
  enable_key_rotation     = true
  tags = {
    environment = var.environment_name
  }
}

# --------------------------------------------------------------------------
# IAM Role and Policy for S3 Replication
# --------------------------------------------------------------------------

resource "aws_iam_role" "s3_replication" {
  name = "${var.environment_name}-s3-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "s3_replication" {
  name = "${var.environment_name}-s3-replication-policy"
  role = aws_iam_role.s3_replication.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = [
          "arn:aws:s3:::${local.state_bucket_name}",
          "arn:aws:s3:::${local.access_logs_bucket_name}"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl"
        ]
        Resource = [
          "arn:aws:s3:::${local.state_bucket_name}/*",
          "arn:aws:s3:::${local.access_logs_bucket_name}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete"
        ]
        Resource = [
          "arn:aws:s3:::${local.replica_state_bucket_name}/*",
          "arn:aws:s3:::${local.replica_logs_bucket_name}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Decrypt"
        ]
        Resource = [
          aws_kms_key.state_bucket.arn
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:GenerateDataKey"
        ]
        Resource = [
          aws_kms_key.replica_state_bucket.arn
        ]
      }
    ]
  })
}

resource "aws_kms_grant" "state_key_replication" {
  name              = "${var.environment_name}-s3-replication-source-state-key"
  key_id            = aws_kms_key.state_bucket.key_id
  grantee_principal = aws_iam_role.s3_replication.arn
  operations        = ["Decrypt", "ReEncryptFrom"]
}

resource "aws_kms_grant" "replica_state_key_replication" {
  name              = "${var.environment_name}-s3-replication-dest-state-key"
  key_id            = aws_kms_key.replica_state_bucket.key_id
  grantee_principal = aws_iam_role.s3_replication.arn
  operations        = ["Encrypt", "GenerateDataKey", "ReEncryptTo"]
}

# --------------------------------------------------------------------------
# Primary Access Logs Bucket
# --------------------------------------------------------------------------

resource "aws_s3_bucket" "access_logs" {
  bucket = local.access_logs_bucket_name

  force_destroy = true
}

resource "aws_s3_bucket_ownership_controls" "access_logs" {
  bucket = aws_s3_bucket.access_logs.bucket

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "access_logs" {
  depends_on = [aws_s3_bucket_ownership_controls.access_logs]

  bucket = aws_s3_bucket.access_logs.bucket
  acl    = "log-delivery-write"
}

resource "aws_s3_bucket_versioning" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id

  rule {
    id     = "glacier-and-expire"
    status = "Enabled"

    transition {
      days          = var.glacier_transition_days
      storage_class = "GLACIER"
    }

    expiration {
      days = var.glacier_transition_days + var.expiration_days
    }
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "access_logs" {
  bucket = aws_s3_bucket.access_logs.bucket

  rule {
    bucket_key_enabled = true
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# --------------------------------------------------------------------------
# Primary Terraform State Bucket
# --------------------------------------------------------------------------

resource "aws_s3_bucket" "state" {
  bucket = local.state_bucket_name

  force_destroy = true
}

resource "aws_s3_bucket_logging" "state" {
  bucket        = aws_s3_bucket.state.id
  target_bucket = aws_s3_bucket.access_logs.id
  target_prefix = "state-bucket-logs/"
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.bucket

  rule {
    bucket_key_enabled = false
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.state_bucket.id
    }
  }
}

resource "aws_s3_bucket_policy" "state" {
  bucket = aws_s3_bucket.state.bucket
  policy = jsonencode(local.state_bucket_policy)
}

# --------------------------------------------------------------------------
# Replica Access Logs Bucket
# --------------------------------------------------------------------------

resource "aws_s3_bucket" "replica_access_logs" {
  bucket = local.replica_logs_bucket_name

  force_destroy = true
}

resource "aws_s3_bucket_ownership_controls" "replica_access_logs" {
  bucket = aws_s3_bucket.replica_access_logs.bucket

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "replica_access_logs" {
  depends_on = [aws_s3_bucket_ownership_controls.replica_access_logs]

  bucket = aws_s3_bucket.replica_access_logs.bucket
  acl    = "log-delivery-write"
}

resource "aws_s3_bucket_versioning" "replica_access_logs" {
  bucket = aws_s3_bucket.replica_access_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "replica_access_logs" {
  bucket = aws_s3_bucket.replica_access_logs.id

  rule {
    id     = "glacier-and-expire"
    status = "Enabled"

    transition {
      days          = var.glacier_transition_days
      storage_class = "GLACIER"
    }

    expiration {
      days = var.glacier_transition_days + var.expiration_days
    }
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica_access_logs" {
  bucket = aws_s3_bucket.replica_access_logs.bucket

  rule {
    bucket_key_enabled = true
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "replica_access_logs" {
  bucket = aws_s3_bucket.replica_access_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# --------------------------------------------------------------------------
# Replica State Bucket
# --------------------------------------------------------------------------

resource "aws_s3_bucket" "replica_state" {
  bucket = local.replica_state_bucket_name

  force_destroy = true
}

resource "aws_s3_bucket_versioning" "replica_state" {
  bucket = aws_s3_bucket.replica_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "replica_state" {
  bucket = aws_s3_bucket.replica_state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica_state" {
  bucket = aws_s3_bucket.replica_state.bucket

  rule {
    bucket_key_enabled = false
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.replica_state_bucket.id
    }
  }
}

resource "aws_s3_bucket_policy" "replica_state" {
  bucket = aws_s3_bucket.replica_state.bucket
  policy = jsonencode(local.replica_state_bucket_policy)
}

# --------------------------------------------------------------------------
# Replication Configurations
# --------------------------------------------------------------------------

resource "aws_s3_bucket_replication_configuration" "state" {
  bucket = aws_s3_bucket.state.id
  role   = aws_iam_role.s3_replication.arn

  depends_on = [
    aws_s3_bucket_versioning.state,
    aws_s3_bucket_versioning.replica_state
  ]

  rule {
    id     = "state-to-replica"
    status = "Enabled"
    priority = 1

    filter {
      prefix = ""
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica_state.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica_state_bucket.arn
      }
    }

    delete_marker_replication {
      status = "Enabled"
    }
  }
}

resource "aws_s3_bucket_replication_configuration" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id
  role   = aws_iam_role.s3_replication.arn

  depends_on = [
    aws_s3_bucket_versioning.access_logs,
    aws_s3_bucket_versioning.replica_access_logs
  ]

  rule {
    id     = "access-logs-to-replica"
    status = "Enabled"
    priority = 1

    filter {
      prefix = ""
    }

    destination {
      bucket        = aws_s3_bucket.replica_access_logs.arn
      storage_class = "STANDARD"
    }

    delete_marker_replication {
      status = "Enabled"
    }
  }
}

# ==============================================================================
# Versatile VPC Networking and Private Interface Endpoint Module
#
# Provisions either a brand-new VPC (with public/private/database subnets and
# routing) or integrates with existing infrastructure supplied via variables
# (vpc_id, subnet ID maps, NAT gateway ID, endpoint security group ID).
# ==============================================================================

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

# Static provider metadata.
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------

variable "name" {
  description = "Name of the VPC and base name used for derived resource names."
  type        = string
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  description = "Primary IPv4 CIDR block for the VPC. Must match the CIDR of an existing VPC when vpc_id is supplied."
  type        = string
  default     = "10.0.0.0/16"
}

variable "vpc_id" {
  description = "ID of an existing VPC to integrate with. Leave null to provision a new VPC."
  type        = string
  default     = null
}

variable "availability_zones" {
  description = "Availability zones for subnet provisioning. Defaults to the first two available zones in the region."
  type        = list(string)
  default     = []
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets, one per availability zone, in zone order."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets, one per availability zone, in zone order."
  type        = list(string)
  default     = ["10.0.10.0/24", "10.0.11.0/24"]
}

variable "database_subnet_cidrs" {
  description = "CIDR blocks for database subnets, one per availability zone, in zone order."
  type        = list(string)
  default     = ["10.0.20.0/24", "10.0.21.0/24"]
}

variable "public_subnet_ids" {
  description = "Map of availability zone -> existing public subnet ID. Overrides public subnet provisioning when non-empty."
  type        = map(string)
  default     = {}
}

variable "private_subnet_ids" {
  description = "Map of availability zone -> existing private subnet ID. Overrides private subnet provisioning when non-empty."
  type        = map(string)
  default     = {}
}

variable "database_subnet_ids" {
  description = "Map of availability zone -> existing database subnet ID. Overrides database subnet provisioning when non-empty."
  type        = map(string)
  default     = {}
}

variable "existing_nat_id" {
  description = "ID of an existing NAT gateway to reuse for private outbound routing. Leave null to provision a new EIP-backed NAT gateway."
  type        = string
  default     = null
}

variable "vpc_endpoints_security_group_id" {
  description = "ID of an existing security group to secure VPC interface endpoints. Leave null to create one."
  type        = string
  default     = null
}

variable "endpoint_services" {
  description = "AWS services to expose via private interface VPC endpoints."
  type        = list(string)
  default     = ["ec2", "ecr.api", "ecr.dkr", "s3", "logs", "sts", "elasticloadbalancing", "autoscaling"]
}

# ------------------------------------------------------------------------------
# Local values
# ------------------------------------------------------------------------------

locals {
  create_vpc = var.vpc_id == null

  vpc_id   = local.create_vpc ? aws_vpc.this[0].id : var.vpc_id
  vpc_cidr = var.vpc_cidr

  # Two availability zones across the region.
  azs = length(var.availability_zones) >= 2 ? slice(var.availability_zones, 0, 2) : slice(data.aws_availability_zones.available.names, 0, 2)

  # AZ -> CIDR maps used only when subnets are provisioned inside the new VPC.
  public_subnet_az_map   = local.create_vpc && length(var.public_subnet_ids) == 0 ? { for i, az in local.azs : az => var.public_subnet_cidrs[i] } : {}
  private_subnet_az_map  = local.create_vpc && length(var.private_subnet_ids) == 0 ? { for i, az in local.azs : az => var.private_subnet_cidrs[i] } : {}
  database_subnet_az_map = local.create_vpc && length(var.database_subnet_ids) == 0 ? { for i, az in local.azs : az => var.database_subnet_cidrs[i] } : {}

  # AZ -> subnet ID maps resolved from either existing infrastructure or created subnets.
  effective_public_subnet_az_map   = length(var.public_subnet_ids) > 0 ? var.public_subnet_ids : { for k, s in aws_subnet.public : k => s.id }
  effective_private_subnet_az_map  = length(var.private_subnet_ids) > 0 ? var.private_subnet_ids : { for k, s in aws_subnet.private : k => s.id }
  effective_database_subnet_az_map = length(var.database_subnet_ids) > 0 ? var.database_subnet_ids : { for k, s in aws_subnet.database : k => s.id }

  # First public subnet (in the first AZ) hosts the NAT gateway.
  first_public_subnet_id = local.create_vpc ? values(local.effective_public_subnet_az_map)[0] : ""

  nat_gateway_id = var.existing_nat_id != null ? var.existing_nat_id : (local.create_vpc ? aws_nat_gateway.this[0].id : "")

  vpc_endpoints_sg_id = var.vpc_endpoints_security_group_id != null ? var.vpc_endpoints_security_group_id : aws_security_group.vpc_endpoints[0].id
}

# ------------------------------------------------------------------------------
# VPC (created only when vpc_id is not supplied)
# ------------------------------------------------------------------------------

resource "aws_vpc" "this" {
  count = local.create_vpc ? 1 : 0

  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true
  instance_tenancy     = "default"

  tags = { Name = var.name }
}

# ------------------------------------------------------------------------------
# Subnets
# ------------------------------------------------------------------------------

resource "aws_subnet" "public" {
  for_each = local.public_subnet_az_map

  vpc_id                  = local.vpc_id
  availability_zone       = each.key
  cidr_block              = each.value
  map_public_ip_on_launch = false

  tags = { Name = "${var.name}-public-${each.key}" }
}

resource "aws_subnet" "private" {
  for_each = local.private_subnet_az_map

  vpc_id            = local.vpc_id
  availability_zone = each.key
  cidr_block        = each.value

  tags = { Name = "${var.name}-private-${each.key}" }
}

resource "aws_subnet" "database" {
  for_each = local.database_subnet_az_map

  vpc_id            = local.vpc_id
  availability_zone = each.key
  cidr_block        = each.value

  tags = { Name = "${var.name}-database-${each.key}" }
}

# ------------------------------------------------------------------------------
# Internet Gateway
# ------------------------------------------------------------------------------

resource "aws_internet_gateway" "this" {
  count = local.create_vpc ? 1 : 0

  vpc_id = local.vpc_id

  tags = { Name = "${var.name}-igw" }
}

# ------------------------------------------------------------------------------
# NAT Gateway (single, EIP-backed, in the first public subnet)
# ------------------------------------------------------------------------------

resource "aws_eip" "nat" {
  count = local.create_vpc && var.existing_nat_id == null ? 1 : 0

  domain = "vpc"

  tags = { Name = "${var.name}-nat-eip" }
}

resource "aws_nat_gateway" "this" {
  count = local.create_vpc && var.existing_nat_id == null ? 1 : 0

  allocation_id = aws_eip.nat[0].id
  subnet_id     = local.first_public_subnet_id

  tags = { Name = "${var.name}-nat" }

  depends_on = [aws_internet_gateway.this]
}

# ------------------------------------------------------------------------------
# Route tables and routes
# ------------------------------------------------------------------------------

resource "aws_route_table" "public" {
  count = local.create_vpc ? 1 : 0

  vpc_id = local.vpc_id

  tags = { Name = "${var.name}-public" }
}

resource "aws_route" "public_internet" {
  count = local.create_vpc ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[0].id
}

resource "aws_route_table_association" "public" {
  for_each = aws_subnet.public

  subnet_id      = each.value.id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_route_table" "private" {
  count = local.create_vpc ? 1 : 0

  vpc_id = local.vpc_id

  tags = { Name = "${var.name}-private" }
}

resource "aws_route" "private_nat" {
  count = local.create_vpc ? 1 : 0

  route_table_id         = aws_route_table.private[0].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = local.nat_gateway_id
}

resource "aws_route_table_association" "private" {
  for_each = aws_subnet.private

  subnet_id      = each.value.id
  route_table_id = aws_route_table.private[0].id
}

resource "aws_route_table" "database" {
  count = local.create_vpc ? 1 : 0

  vpc_id = local.vpc_id

  tags = { Name = "${var.name}-database" }
}

resource "aws_route_table_association" "database" {
  for_each = aws_subnet.database

  subnet_id      = each.value.id
  route_table_id = aws_route_table.database[0].id
}

# ------------------------------------------------------------------------------
# RDS database subnet group (named with lowercased VPC name)
# ------------------------------------------------------------------------------

resource "aws_db_subnet_group" "this" {
  count = length(local.effective_database_subnet_az_map) > 0 ? 1 : 0

  name        = lower(var.name)
  description = "Database subnets for ${var.name}"
  subnet_ids  = values(local.effective_database_subnet_az_map)

  tags = { Name = lower(var.name) }
}

# ------------------------------------------------------------------------------
# VPC interface endpoints
# ------------------------------------------------------------------------------

resource "aws_security_group" "vpc_endpoints" {
  count = var.vpc_endpoints_security_group_id == null ? 1 : 0

  name        = "${var.name}-vpc-endpoints"
  description = "Security group controlling access to VPC interface endpoints"
  vpc_id      = local.vpc_id

  ingress {
    description = "HTTPS from VPC CIDR"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    description = "HTTPS within VPC CIDR only"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = { Name = "${var.name}-vpc-endpoints" }
}

resource "aws_vpc_endpoint" "interface" {
  for_each = toset(var.endpoint_services)

  vpc_id             = local.vpc_id
  service_name       = "com.amazonaws.${data.aws_region.current.region}.${each.value}"
  vpc_endpoint_type  = "Interface"
  subnet_ids         = values(local.effective_private_subnet_az_map)
  security_group_ids = [local.vpc_endpoints_sg_id]

  # Services that support both Gateway and Interface endpoint types (S3,
  # DynamoDB) require a Gateway endpoint in the VPC before private DNS can be
  # enabled for their interface endpoint. Private DNS is therefore left
  # disabled for those dual-type services so the interface endpoints work
  # standalone; every other interface endpoint gets private DNS enabled.
  private_dns_enabled = !contains(["s3", "dynamodb"], each.value)

  tags = { Name = "${var.name}-${each.value}" }
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------

output "vpc_id" {
  description = "ID of the VPC used by the module."
  value       = local.vpc_id
}

output "public_subnet_ids" {
  description = "Map of availability zone -> public subnet ID."
  value       = local.effective_public_subnet_az_map
}

output "private_subnet_ids" {
  description = "Map of availability zone -> private subnet ID."
  value       = local.effective_private_subnet_az_map
}

output "database_subnet_ids" {
  description = "Map of availability zone -> database subnet ID."
  value       = local.effective_database_subnet_az_map
}

output "nat_gateway_id" {
  description = "ID of the NAT gateway used for private outbound routing."
  value       = local.nat_gateway_id
}

output "vpc_endpoints_security_group_id" {
  description = "ID of the security group securing the VPC interface endpoints."
  value       = local.vpc_endpoints_sg_id
}

output "database_subnet_group_name" {
  description = "Name of the RDS database subnet group."
  value       = length(local.effective_database_subnet_az_map) > 0 ? aws_db_subnet_group.this[0].name : ""
}

variable "app_shortcode" {
  description = "Application shortcode used as a prefix for IAM role, instance profile and resource naming"
  type        = string
  default     = "bmk"
}

locals {
  vpc_cidr    = "10.8.0.0/16"
  subnet_cidr = "10.8.1.0/24"
  name_prefix = var.app_shortcode
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-ebs"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "state"
    values = ["available"]
  }
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.name_prefix}-isolated-vpc"
  }
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.subnet_cidr
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "${local.name_prefix}-private-subnet"
  }
}

resource "aws_security_group" "endpoint" {
  name        = "${local.name_prefix}-endpoint-sg"
  description = "Security group for VPC interface endpoints allowing inbound HTTPS from the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  # Intentional: no egress rules for endpoint security group

  tags = {
    Name = "${local.name_prefix}-endpoint-sg"
  }
}

resource "aws_security_group" "instance" {
  name        = "${local.name_prefix}-instance-sg"
  description = "Security group for SSM test instance allowing outbound HTTPS to the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  egress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  # Intentional: no ingress rules for instance security group

  tags = {
    Name = "${local.name_prefix}-instance-sg"
  }
}

resource "aws_vpc_endpoint" "ssm" {
  service_name        = "com.amazonaws.${data.aws_region.current.region}.ssm"
  vpc_id              = aws_vpc.main.id
  vpc_endpoint_type   = "Interface"
  auto_accept         = true
  private_dns_enabled = true
  subnet_ids          = [aws_subnet.private.id]
  security_group_ids  = [aws_security_group.endpoint.id]

  tags = {
    Name = "${local.name_prefix}-ssm-endpoint"
  }
}

resource "aws_vpc_endpoint" "ec2messages" {
  service_name        = "com.amazonaws.${data.aws_region.current.region}.ec2messages"
  vpc_id              = aws_vpc.main.id
  vpc_endpoint_type   = "Interface"
  auto_accept         = true
  private_dns_enabled = true
  subnet_ids          = [aws_subnet.private.id]
  security_group_ids  = [aws_security_group.endpoint.id]

  tags = {
    Name = "${local.name_prefix}-ec2messages-endpoint"
  }
}

resource "aws_vpc_endpoint" "ssmmessages" {
  service_name        = "com.amazonaws.${data.aws_region.current.region}.ssmmessages"
  vpc_id              = aws_vpc.main.id
  vpc_endpoint_type   = "Interface"
  auto_accept         = true
  private_dns_enabled = true
  subnet_ids          = [aws_subnet.private.id]
  security_group_ids  = [aws_security_group.endpoint.id]

  tags = {
    Name = "${local.name_prefix}-ssmmessages-endpoint"
  }
}

resource "aws_vpc_endpoint" "logs" {
  service_name        = "com.amazonaws.${data.aws_region.current.region}.logs"
  vpc_id              = aws_vpc.main.id
  vpc_endpoint_type   = "Interface"
  auto_accept         = true
  private_dns_enabled = true
  subnet_ids          = [aws_subnet.private.id]
  security_group_ids  = [aws_security_group.endpoint.id]

  tags = {
    Name = "${local.name_prefix}-logs-endpoint"
  }
}

resource "aws_iam_role" "instance" {
  name = "${local.name_prefix}-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "instance_ssm" {
  name = "${local.name_prefix}-instance-ssm-policy"
  role = aws_iam_role.instance.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["ssm:*"]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy" "instance_ec2messages" {
  name = "${local.name_prefix}-instance-ec2messages-policy"
  role = aws_iam_role.instance.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["ec2messages:*"]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy" "instance_ssmmessages" {
  name = "${local.name_prefix}-instance-ssmmessages-policy"
  role = aws_iam_role.instance.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["ssmmessages:*"]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy" "instance_logs" {
  name = "${local.name_prefix}-instance-logs-policy"
  role = aws_iam_role.instance.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["logs:DescribeLogGroups", "logs:DescribeLogStreams", "logs:CreateLogGroup", "logs:CreateLogStream", "logs:PutLogEvents"]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy" "instance_kms" {
  name = "${local.name_prefix}-instance-kms-policy"
  role = aws_iam_role.instance.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["kms:GenerateDataKey", "kms:GenerateDataKeyWithoutPlaintext", "kms:Decrypt"]
        Resource = [aws_kms_key.ebs.arn]
      }
    ]
  })
}

resource "aws_iam_role_policy" "instance_s3" {
  name = "${local.name_prefix}-instance-s3-policy"
  role = aws_iam_role.instance.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject", "s3:ListBucket", "s3:GetBucketLocation"]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_instance_profile" "instance" {
  name = "${local.name_prefix}-instance-profile"
  role = aws_iam_role.instance.name
}

# Customer-managed KMS key used to encrypt the root volume. A dedicated key
# is used so access to the key material can be governed by the instance role.
resource "aws_kms_key" "ebs" {
  description             = "${local.name_prefix} EBS volume encryption key"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable principal access to manage the key"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "${local.name_prefix}-ebs-key"
  }
}

resource "aws_instance" "test" {
  ami                    = data.aws_ami.amazon_linux_2.id
  instance_type          = "t3.small"
  subnet_id              = aws_subnet.private.id
  vpc_security_group_ids = [aws_security_group.instance.id]
  iam_instance_profile   = aws_iam_instance_profile.instance.name
  source_dest_check      = false
  private_ip             = "10.8.1.10"

  root_block_device {
    encrypted  = true
    kms_key_id = aws_kms_key.ebs.arn
  }

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
  }

  tags = {
    Name = "${local.name_prefix}-test-instance"
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }
}

locals {
  vpc_cidr    = "10.0.0.0/16"
  azs         = slice(data.aws_availability_zones.available.names, 0, 3)
  name_prefix = "fargate-crowdnews"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}
data "aws_partition" "current" {}

# ---------------------------------------------------------------------------
# VPC
# ---------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "${local.name_prefix}-vpc"
  }
}

# ---------------------------------------------------------------------------
# Subnets
# ---------------------------------------------------------------------------
resource "aws_subnet" "public" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(local.vpc_cidr, 8, count.index)
  availability_zone = local.azs[count.index]
  map_public_ip_on_launch = false
  tags = {
    Name = "${local.name_prefix}-public-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(local.vpc_cidr, 8, count.index + 3)
  availability_zone = local.azs[count.index]
  tags = {
    Name = "${local.name_prefix}-private-${count.index}"
  }
}

# ---------------------------------------------------------------------------
# Internet Gateway
# ---------------------------------------------------------------------------
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "${local.name_prefix}-igw"
  }
}

# ---------------------------------------------------------------------------
# Elastic IPs for NAT Gateways
# ---------------------------------------------------------------------------
resource "aws_eip" "nat" {
  count  = 3
  domain = "vpc"
  tags = {
    Name = "${local.name_prefix}-nat-eip-${count.index}"
  }
}

# ---------------------------------------------------------------------------
# NAT Gateways (one per AZ)
# ---------------------------------------------------------------------------
resource "aws_nat_gateway" "main" {
  count         = 3
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id
  tags = {
    Name = "${local.name_prefix}-nat-${count.index}"
  }
}

# ---------------------------------------------------------------------------
# Route Tables
# ---------------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
  tags = {
    Name = "${local.name_prefix}-public-rt"
  }
}

resource "aws_route_table" "private" {
  count  = 3
  vpc_id = aws_vpc.main.id
  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }
  tags = {
    Name = "${local.name_prefix}-private-rt-${count.index}"
  }
}

# ---------------------------------------------------------------------------
# Route table associations
# ---------------------------------------------------------------------------
resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# ---------------------------------------------------------------------------
# VPC Gateway Endpoint for S3 (attached to private route tables)
# ---------------------------------------------------------------------------
resource "aws_vpc_endpoint" "s3" {
  vpc_id       = aws_vpc.main.id
  service_name = "com.amazonaws.${data.aws_region.current.region}.s3"
  route_table_ids = [for rt in aws_route_table.private : rt.id]
  tags = {
    Name = "${local.name_prefix}-s3-gateway-endpoint"
  }
}

# ---------------------------------------------------------------------------
# Security group for VPC endpoints (interface endpoints)
# ---------------------------------------------------------------------------
resource "aws_security_group" "vpc_endpoints" {
  name        = "${local.name_prefix}-vpc-endpoints-sg"
  description = "Allow HTTPS from VPC CIDR to interface VPC endpoints"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "${local.name_prefix}-vpc-endpoints-sg"
  }
}

# ---------------------------------------------------------------------------
# Interface VPC Endpoints
# ---------------------------------------------------------------------------
resource "aws_vpc_endpoint" "ecr_docker" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.region}.ecr.dkr"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true
  tags = {
    Name = "${local.name_prefix}-ecr-dkr-endpoint"
  }
}

resource "aws_vpc_endpoint" "ecr_api" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.region}.ecr.api"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true
  tags = {
    Name = "${local.name_prefix}-ecr-api-endpoint"
  }
}

resource "aws_vpc_endpoint" "logs" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.region}.logs"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true
  tags = {
    Name = "${local.name_prefix}-logs-endpoint"
  }
}

resource "aws_vpc_endpoint" "secretsmanager" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.region}.secretsmanager"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true
  tags = {
    Name = "${local.name_prefix}-secretsmanager-endpoint"
  }
}

resource "aws_vpc_endpoint" "ssm" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.region}.ssm"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true
  tags = {
    Name = "${local.name_prefix}-ssm-endpoint"
  }
}

resource "aws_vpc_endpoint" "ssmmessages" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.region}.ssmmessages"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true
  tags = {
    Name = "${local.name_prefix}-ssmmessages-endpoint"
  }
}

resource "aws_vpc_endpoint" "ec2messages" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.region}.ec2messages"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true
  tags = {
    Name = "${local.name_prefix}-ec2messages-endpoint"
  }
}

resource "aws_vpc_endpoint" "kms" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.region}.kms"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true
  tags = {
    Name = "${local.name_prefix}-kms-endpoint"
  }
}

# ---------------------------------------------------------------------------
# Cloud Map Private DNS Namespace
# ---------------------------------------------------------------------------
resource "aws_service_discovery_private_dns_namespace" "main" {
  name        = "private-fargate-crowdnews.hands-on.cloud.local"
  description = "Private DNS namespace for fargate crowdnews services"
  vpc         = aws_vpc.main.id
}

# ---------------------------------------------------------------------------
# ECR Repository
# ---------------------------------------------------------------------------
resource "aws_ecr_repository" "nginx" {
  name                 = "${local.name_prefix}/nginx"
  image_tag_mutability = "IMMUTABLE"
  image_scanning_configuration {
    scan_on_push = true
  }
  tags = {
    Name = "${local.name_prefix}-nginx"
  }
}

# ---------------------------------------------------------------------------
# CloudWatch Log Group
# ---------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "nginx" {
  name              = "/ecs/${local.name_prefix}/nginx"
  retention_in_days = 7
  tags = {
    Name = "${local.name_prefix}-nginx-logs"
  }
}

# ---------------------------------------------------------------------------
# ECS Cluster
# ---------------------------------------------------------------------------
resource "aws_ecs_cluster" "main" {
  name = "${local.name_prefix}-cluster"
  setting {
    name  = "containerInsights"
    value = "enabled"
  }
  tags = {
    Name = "${local.name_prefix}-cluster"
  }
}

# ---------------------------------------------------------------------------
# IAM Policies and Roles for ECS
# ---------------------------------------------------------------------------
resource "aws_iam_role" "ecs_task_execution" {
  name = "${local.name_prefix}-ecs-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "ecs_execution_inline" {
  name        = "${local.name_prefix}-ecs-execution-inline"
  description = "Inline policy for ECS task execution role"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ecr:BatchCheckLayerAvailability",
          "ecr:BatchGetImage",
          "ecr:GetAuthorizationToken",
          "ecr:GetDownloadUrlForLayer"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.nginx.arn}:*"
      },
      {
        Effect = "Allow"
        Action = [
          "ssm:GetParameters",
          "ssm:GetParameter"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Decrypt"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_execution_inline" {
  role       = aws_iam_role.ecs_task_execution.name
  policy_arn = aws_iam_policy.ecs_execution_inline.arn
}

resource "aws_iam_role" "ecs_task" {
  name = "${local.name_prefix}-ecs-task-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "ecs_task_inline" {
  name        = "${local.name_prefix}-ecs-task-inline"
  description = "Inline policy for ECS task role"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "servicediscovery:DiscoverInstances",
          "servicediscovery:GetInstance",
          "servicediscovery:GetInstancesHealthStatus"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_task_inline" {
  role       = aws_iam_role.ecs_task.name
  policy_arn = aws_iam_policy.ecs_task_inline.arn
}

# ---------------------------------------------------------------------------
# Security Group for ECS Tasks
# ---------------------------------------------------------------------------
resource "aws_security_group" "ecs_tasks" {
  name        = "${local.name_prefix}-ecs-tasks-sg"
  description = "Allow port 80 ingress from VPC CIDR for ECS tasks"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from VPC"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "${local.name_prefix}-ecs-tasks-sg"
  }
}

# ---------------------------------------------------------------------------
# Cloud Map Service (for service discovery)
# ---------------------------------------------------------------------------
resource "aws_service_discovery_service" "nginx" {
  name = "nginx"

  dns_config {
    namespace_id = aws_service_discovery_private_dns_namespace.main.id

    dns_records {
      ttl  = 10
      type = "A"
    }

    dns_records {
      ttl  = 10
      type = "SRV"
    }

    routing_policy = "MULTIVALUE"
  }

  health_check_custom_config {
    failure_threshold = 1
  }

  tags = {
    Name = "${local.name_prefix}-nginx-sd"
  }
}

# ---------------------------------------------------------------------------
# ECS Task Definition
# ---------------------------------------------------------------------------
resource "aws_ecs_task_definition" "nginx" {
  family                   = "${local.name_prefix}-nginx"
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                      = "512"
  memory                   = "1024"
  execution_role_arn       = aws_iam_role.ecs_task_execution.arn
  task_role_arn            = aws_iam_role.ecs_task.arn

  container_definitions = jsonencode([
    {
      name      = "nginx"
      image     = "${aws_ecr_repository.nginx.repository_url}:latest"
      essential = true
      portMappings = [
        {
          containerPort = 80
          hostPort      = 80
          protocol      = "tcp"
        }
      ]
      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.nginx.name
          "awslogs-region"        = data.aws_region.current.region
          "awslogs-stream-prefix" = "ecs"
        }
      }
      environment = [
        {
          name  = "SERVICE_DISCOVERY_NAMESPACE_ID"
          value = aws_service_discovery_private_dns_namespace.main.id
        },
        {
          name  = "SERVICE_DISCOVERY_NAMESPACE_NAME"
          value = aws_service_discovery_private_dns_namespace.main.name
        }
      ]
    }
  ])

  tags = {
    Name = "${local.name_prefix}-nginx-taskdef"
  }
}

# ---------------------------------------------------------------------------
# ECS Service (Fargate)
# ---------------------------------------------------------------------------
resource "aws_ecs_service" "nginx" {
  name            = "${local.name_prefix}-nginx-svc"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.nginx.arn
  desired_count   = 1
  launch_type     = "FARGATE"

  network_configuration {
    subnets         = aws_subnet.private[*].id
    security_groups = [aws_security_group.ecs_tasks.id]
    assign_public_ip = false
  }

  service_registries {
    registry_arn   = aws_service_discovery_service.nginx.arn
    container_name = "nginx"
    container_port = 80
  }

  depends_on = [
    aws_iam_role_policy_attachment.ecs_execution_inline,
    aws_iam_role_policy_attachment.ecs_task_inline
  ]

  tags = {
    Name = "${local.name_prefix}-nginx-svc"
  }
}

# ---------------------------------------------------------------------------
# IAM Role & Instance Profile for SSM Jumphost EC2
# ---------------------------------------------------------------------------
resource "aws_iam_role" "ssm_jumphost" {
  name = "${local.name_prefix}-ssm-jumphost-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ssm_jumphost_ssm" {
  role       = aws_iam_role.ssm_jumphost.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ssm_jumphost" {
  name = "${local.name_prefix}-ssm-jumphost-instance-profile"
  role = aws_iam_role.ssm_jumphost.name
}

# ---------------------------------------------------------------------------
# Security Group for SSM Jumphost EC2 Instance
# ---------------------------------------------------------------------------
resource "aws_security_group" "ssm_jumphost" {
  name        = "${local.name_prefix}-ssm-jumphost-sg"
  description = "Allow all inbound traffic from VPC CIDR for SSM jumphost"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "All traffic from VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "${local.name_prefix}-ssm-jumphost-sg"
  }
}

# ---------------------------------------------------------------------------
# AMI for Amazon Linux 2 (latest)
# ---------------------------------------------------------------------------
data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

# ---------------------------------------------------------------------------
# Custom Network Interface for EC2 (static private IP in first public subnet)
# ---------------------------------------------------------------------------
resource "aws_network_interface" "ssm_jumphost" {
  subnet_id       = aws_subnet.public[0].id
  private_ips     = ["10.0.0.50"]
  security_groups = [aws_security_group.ssm_jumphost.id]

  tags = {
    Name = "${local.name_prefix}-ssm-jumphost-eni"
  }
}

# ---------------------------------------------------------------------------
# KMS Key for EBS encryption
# ---------------------------------------------------------------------------
resource "aws_kms_key" "ebs" {
  description             = "KMS key for EBS volume encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  tags = {
    Name = "${local.name_prefix}-ebs-key"
  }
}

# ---------------------------------------------------------------------------
# t3.micro Amazon Linux 2 EC2 Instance (SSM jumphost)
# ---------------------------------------------------------------------------
resource "aws_instance" "ssm_jumphost" {
  ami           = data.aws_ami.amazon_linux_2.id
  instance_type = "t3.micro"
  iam_instance_profile = aws_iam_instance_profile.ssm_jumphost.name

  network_interface {
    network_interface_id = aws_network_interface.ssm_jumphost.id
    device_index         = 0
  }

  metadata_options {
    http_tokens   = "required"
    http_endpoint = "enabled"
  }

  root_block_device {
    encrypted = true
    kms_key_id = aws_kms_key.ebs.arn
  }

  credit_specification {
    cpu_credits = "standard"
  }

  tags = {
    Name = "${local.name_prefix}-ssm-jumphost"
  }
}

# ---------------------------------------------------------------------------
# Output: curl command to reach NGINX via service discovery DNS name
# ---------------------------------------------------------------------------
output "curl_nginx_command" {
  description = "Curl command to reach the NGINX service via its private service discovery DNS name"
  value       = "curl http://nginx.${aws_service_discovery_private_dns_namespace.main.name}"
}

# Data sources for static provider metadata
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

# Variables
variable "project" {
  description = "Project name for naming/tagging"
  type        = string
  default     = "benchmark"
}

variable "application" {
  description = "Application name for naming/tagging"
  type        = string
  default     = "iacbench"
}

variable "environment" {
  description = "Environment name for naming/tagging"
  type        = string
  default     = "dev"
}

variable "availability_zone" {
  description = "Availability zone for the subnet (defaults to first available AZ)"
  type        = string
  default     = null
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_cidr" {
  description = "CIDR block for the public subnet"
  type        = string
  default     = "10.0.1.0/24"
}

variable "instance_type" {
  description = "EC2 instance type"
  type        = string
  default     = "t3.micro"
}

variable "root_volume_size" {
  description = "Size of the encrypted root volume in GB"
  type        = number
  default     = 20
}

variable "create_eip" {
  description = "Whether to allocate and associate a static Elastic IP"
  type        = bool
  default     = false
}

variable "create_ssh_key" {
  description = "Whether to generate and attach an SSH key pair"
  type        = bool
  default     = false
}

variable "attach_amazon_ssm_managed_instance_core" {
  description = "Whether to attach the AmazonSSMManagedInstanceCore managed policy"
  type        = bool
  default     = true
}

variable "custom_routes" {
  description = "Custom route definitions to inject into the route table"
  type = list(object({
    destination_cidr_block     = string
    gateway_id                 = optional(string)
    nat_gateway_id             = optional(string)
    network_interface_id       = optional(string)
    transit_gateway_id         = optional(string)
    vpc_peering_connection_id  = optional(string)
    egress_only_gateway_id     = optional(string)
  }))
  default = []
}

# Locals
locals {
  az = var.availability_zone != null ? var.availability_zone : data.aws_availability_zones.available.names[0]

  name_prefix = "${var.project}-${var.application}-${var.environment}"

  common_tags = {
    Name        = local.name_prefix
    Project     = var.project
    Application = var.application
    Environment = var.environment
    ManagedBy   = "terraform"
  }

  ssm_session_manager_policy_name = "${local.name_prefix}-ssm-session-manager"
  iam_role_name                   = "${local.name_prefix}-instance-role"
  instance_profile_name           = "${local.name_prefix}-instance-profile"
}

# ─────────────────────────────────────────────────────────────
# Networking
# ─────────────────────────────────────────────────────────────

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_cidr
  availability_zone       = local.az
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-public"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-rt-public"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route" "custom" {
  for_each = { for idx, route in var.custom_routes : idx => route }

  route_table_id           = aws_route_table.public.id
  destination_cidr_block   = each.value.destination_cidr_block
  gateway_id               = try(each.value.gateway_id, null)
  nat_gateway_id           = try(each.value.nat_gateway_id, null)
  network_interface_id     = try(each.value.network_interface_id, null)
  transit_gateway_id       = try(each.value.transit_gateway_id, null)
  vpc_peering_connection_id = try(each.value.vpc_peering_connection_id, null)
  egress_only_gateway_id   = try(each.value.egress_only_gateway_id, null)
}

# ─────────────────────────────────────────────────────────────
# Security Groups
# ─────────────────────────────────────────────────────────────

resource "aws_security_group" "instance" {
  name        = "${local.name_prefix}-sg"
  description = "Security group for benchmark EC2 instance"
  vpc_id      = aws_vpc.main.id

  dynamic "ingress" {
    for_each = var.create_ssh_key ? [1] : []
    content {
      description = "SSH from anywhere (key pair present)"
      from_port   = 22
      to_port     = 22
      protocol    = "tcp"
      cidr_blocks = ["0.0.0.0/0"]
    }
  }

  # No egress rules needed — SSM traffic routes through VPC Interface Endpoints
  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-sg"
  })
}

resource "aws_security_group" "endpoints" {
  name        = "${local.name_prefix}-sg-endpoints"
  description = "Security group for VPC Interface Endpoints"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "HTTPS from instance security group"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    security_groups = [aws_security_group.instance.id]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-sg-endpoints"
  })
}

# ─────────────────────────────────────────────────────────────
# VPC Interface Endpoints for SSM (avoids internet egress)
# ─────────────────────────────────────────────────────────────

locals {
  ssm_endpoint_services = ["ssm", "ssmmessages", "ec2messages"]
}

resource "aws_vpc_endpoint" "ssm" {
  for_each = toset(local.ssm_endpoint_services)

  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.region}.${each.key}"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.public.id]
  security_group_ids  = [aws_security_group.endpoints.id]
  private_dns_enabled = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpce-${each.key}"
  })
}

# ─────────────────────────────────────────────────────────────
# Network Interface (dedicated ENI, no auto-public-IP)
# ─────────────────────────────────────────────────────────────

resource "aws_network_interface" "instance" {
  subnet_id         = aws_subnet.public.id
  security_groups   = [aws_security_group.instance.id]
  source_dest_check = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-eni"
  })
}

# ─────────────────────────────────────────────────────────────
# Optional Elastic IP
# ─────────────────────────────────────────────────────────────

resource "aws_eip" "main" {
  count  = var.create_eip ? 1 : 0
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-eip"
  })
}

resource "aws_eip_association" "main" {
  count                = var.create_eip ? 1 : 0
  network_interface_id = aws_network_interface.instance.id
  allocation_id        = aws_eip.main[0].id
}

# ─────────────────────────────────────────────────────────────
# Optional SSH Key Pair (generated)
# ─────────────────────────────────────────────────────────────

resource "tls_private_key" "main" {
  count     = var.create_ssh_key ? 1 : 0
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_key_pair" "main" {
  count      = var.create_ssh_key ? 1 : 0
  key_name   = "${local.name_prefix}-key"
  public_key = tls_private_key.main[0].public_key_openssh

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-key"
  })
}

# ─────────────────────────────────────────────────────────────
# IAM: Role, Policies, Instance Profile
# ─────────────────────────────────────────────────────────────

data "aws_iam_policy_document" "instance_trust" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com", "ssm.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "instance" {
  name               = local.iam_role_name
  assume_role_policy = data.aws_iam_policy_document.instance_trust.json

  tags = merge(local.common_tags, {
    Name = local.iam_role_name
  })
}

data "aws_iam_policy_document" "ssm_session_manager" {
  statement {
    sid    = "SSMControlChannel"
    effect = "Allow"
    actions = [
      "ssm:StartSession",
      "ssm:TerminateSession",
      "ssm:ResumeSession",
      "ssm:DescribeSessions",
      "ssm:GetConnectionStatus",
      "ssm:UpdateInstanceInformation"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "SSMDataChannel"
    effect = "Allow"
    actions = [
      "ec2messages:*",
      "ssmmessages:*"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "ssm_session_manager" {
  name        = local.ssm_session_manager_policy_name
  description = "Grants SSM Session Manager permissions for control and data channels"
  policy      = data.aws_iam_policy_document.ssm_session_manager.json

  tags = merge(local.common_tags, {
    Name = local.ssm_session_manager_policy_name
  })
}

resource "aws_iam_role_policy_attachment" "ssm_session_manager" {
  role       = aws_iam_role.instance.name
  policy_arn = aws_iam_policy.ssm_session_manager.arn
}

data "aws_iam_policy" "amazon_ssm_managed_instance_core" {
  count = var.attach_amazon_ssm_managed_instance_core ? 1 : 0
  arn   = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_role_policy_attachment" "amazon_ssm_managed_instance_core" {
  count      = var.attach_amazon_ssm_managed_instance_core ? 1 : 0
  role       = aws_iam_role.instance.name
  policy_arn = data.aws_iam_policy.amazon_ssm_managed_instance_core[0].arn
}

resource "aws_iam_instance_profile" "main" {
  name = local.instance_profile_name
  role = aws_iam_role.instance.name

  tags = merge(local.common_tags, {
    Name = local.instance_profile_name
  })
}

# ─────────────────────────────────────────────────────────────
# EC2 Instance
# ─────────────────────────────────────────────────────────────

resource "aws_instance" "main" {
  ami           = data.aws_ami.amazon_linux_2.id
  instance_type = var.instance_type

  primary_network_interface {
    network_interface_id = aws_network_interface.instance.id
  }

  iam_instance_profile = aws_iam_instance_profile.main.name

  metadata_options {
    http_tokens             = "required"
    http_endpoint           = "enabled"
    http_put_response_hop_limit = 1
    instance_metadata_tags  = "enabled"
  }

  root_block_device {
    volume_size           = var.root_volume_size
    volume_type           = "gp3"
    encrypted             = true
    kms_key_id            = "alias/aws/ebs"
    delete_on_termination = true

    tags = merge(local.common_tags, {
      Name = "${local.name_prefix}-root-volume"
    })
  }

  key_name = var.create_ssh_key ? aws_key_pair.main[0].key_name : null

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-instance"
  })


}

# ─────────────────────────────────────────────────────────────
# Outputs
# ─────────────────────────────────────────────────────────────

output "instance_id" {
  description = "EC2 instance ID"
  value       = aws_instance.main.id
}

output "instance_arn" {
  description = "EC2 instance ARN"
  value       = aws_instance.main.arn
}

output "iam_role_name" {
  description = "IAM role name"
  value       = aws_iam_role.instance.name
}

output "iam_role_arn" {
  description = "IAM role ARN"
  value       = aws_iam_role.instance.arn
}

output "instance_profile_name" {
  description = "Instance profile name"
  value       = aws_iam_instance_profile.main.name
}

output "instance_profile_arn" {
  description = "Instance profile ARN"
  value       = aws_iam_instance_profile.main.arn
}

output "route_table_id" {
  description = "Route table ID"
  value       = aws_route_table.public.id
}

output "route_table_arn" {
  description = "Route table ARN"
  value       = "arn:${data.aws_partition.current.partition}:ec2:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:route-table/${aws_route_table.public.id}"
}

output "subnet_id" {
  description = "Subnet ID"
  value       = aws_subnet.public.id
}

output "subnet_arn" {
  description = "Subnet ARN"
  value       = aws_subnet.public.arn
}

locals {
  cluster_name = "demo-eks"
  nodegroup    = "demo-eks-node-group"
  base_tags = {
    "kubernetes.io/cluster/demo-eks" = "owned"
  }
}

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "eks_node" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amazon-eks-node-1.32-*"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

# ---------------------------------------------------------------------------
# Networking: VPC, subnets, IGW, NAT, routing
# ---------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.base_tags, { Name = "demo-eks-vpc" })
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.0.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.base_tags, { Name = "demo-eks-public" })
}

resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.${count.index + 1}.0/24"
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.base_tags, { Name = "demo-eks-private-${data.aws_availability_zones.available.names[count.index]}" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.base_tags, { Name = "demo-eks-igw" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.base_tags, { Name = "demo-eks-public-rt" })
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.base_tags, { Name = "demo-eks-nat-eip" })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  tags = merge(local.base_tags, { Name = "demo-eks-nat" })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.base_tags, { Name = "demo-eks-private-rt" })
}

resource "aws_route" "private_nat" {
  route_table_id         = aws_route_table.private.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main.id
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# ---------------------------------------------------------------------------
# KMS key for EKS secret encryption
# ---------------------------------------------------------------------------
resource "aws_kms_key" "eks" {
  description             = "Customer managed KMS key used by the demo-eks cluster to encrypt secrets"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = local.base_tags
}

resource "aws_kms_alias" "eks" {
  name          = "alias/demo-eks"
  target_key_id = aws_kms_key.eks.key_id
}

# ---------------------------------------------------------------------------
# IAM: EKS cluster role and worker node role
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "cluster_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com", "eks-fargate-pods.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "node_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "cluster_kms" {
  statement {
    actions = [
      "kms:CreateGrant",
      "kms:DescribeKey",
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
    ]
    resources = [aws_kms_key.eks.arn]
  }
}

resource "aws_iam_role" "cluster" {
  name               = "eksClusterRole"
  assume_role_policy = data.aws_iam_policy_document.cluster_assume.json

  tags = local.base_tags
}

resource "aws_iam_role_policy" "cluster_kms" {
  name   = "eksClusterRoleKms"
  role   = aws_iam_role.cluster.id
  policy = data.aws_iam_policy_document.cluster_kms.json
}

resource "aws_iam_role_policy_attachment" "cluster_eks" {
  role       = aws_iam_role.cluster.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "cluster_vpc" {
  role       = aws_iam_role.cluster.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSVPCResourceController"
}

resource "aws_iam_role" "node" {
  name               = "eks-demo-node"
  assume_role_policy = data.aws_iam_policy_document.node_assume.json

  tags = local.base_tags
}

resource "aws_iam_role_policy_attachment" "node_worker" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "node_cni" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKS_CNI_Policy"
}

resource "aws_iam_role_policy_attachment" "node_ecr" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

resource "aws_iam_role_policy_attachment" "node_ssm" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "node" {
  name = "eks-demo-node"
  role = aws_iam_role.node.name
}

# ---------------------------------------------------------------------------
# EKS control plane
# ---------------------------------------------------------------------------
resource "aws_eks_cluster" "this" {
  name     = local.cluster_name
  role_arn = aws_iam_role.cluster.arn
  version  = "1.32"

  enabled_cluster_log_types = ["api", "audit", "authenticator", "controllerManager", "scheduler"]

  access_config {
    authentication_mode = "API_AND_CONFIG_MAP"
  }

  vpc_config {
    subnet_ids              = aws_subnet.private[*].id
    endpoint_private_access = true
    endpoint_public_access  = false
  }

  encryption_config {
    provider {
      key_arn = aws_kms_key.eks.arn
    }
    resources = ["secrets"]
  }

  depends_on = [
    aws_iam_role_policy.cluster_kms,
    aws_iam_role_policy_attachment.cluster_eks,
    aws_iam_role_policy_attachment.cluster_vpc,
  ]

  tags = local.base_tags
}

resource "aws_eks_access_entry" "node" {
  cluster_name  = aws_eks_cluster.this.name
  principal_arn = aws_iam_role.node.arn
  type          = "EC2_LINUX"
}

# ---------------------------------------------------------------------------
# Worker node security groups
# ---------------------------------------------------------------------------
resource "aws_security_group" "node" {
  name        = "demo-eks-node-sg"
  description = "Security group for the demo-eks worker nodes"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.base_tags, { Name = "demo-eks-node-sg" })
}

# Unrestricted internal communication between worker nodes
resource "aws_security_group_rule" "node_self_ingress" {
  description              = "Allow all traffic between worker nodes"
  type                     = "ingress"
  security_group_id        = aws_security_group.node.id
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  source_security_group_id = aws_security_group.node.id
}

resource "aws_security_group_rule" "node_self_egress" {
  description              = "Allow all traffic between worker nodes"
  type                     = "egress"
  security_group_id        = aws_security_group.node.id
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  source_security_group_id = aws_security_group.node.id
}

# Outbound traffic is restricted to the VPC CIDR only
resource "aws_security_group_rule" "node_vpc_egress" {
  description       = "Allow all outbound traffic within the VPC"
  type              = "egress"
  security_group_id = aws_security_group.node.id
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [aws_vpc.main.cidr_block]
}

# Two-way communication with the EKS control plane security group
resource "aws_security_group_rule" "node_ingress_443" {
  description              = "Allow control plane traffic to worker nodes on 443"
  type                     = "ingress"
  security_group_id        = aws_security_group.node.id
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_eks_cluster.this.vpc_config[0].cluster_security_group_id
}

resource "aws_security_group_rule" "node_ingress_ephemeral" {
  description              = "Allow control plane traffic to worker nodes on 1025-65535"
  type                     = "ingress"
  security_group_id        = aws_security_group.node.id
  from_port                = 1025
  to_port                  = 65535
  protocol                 = "tcp"
  source_security_group_id = aws_eks_cluster.this.vpc_config[0].cluster_security_group_id
}

resource "aws_security_group_rule" "node_egress_443" {
  description              = "Allow worker nodes to reach the control plane on 443"
  type                     = "egress"
  security_group_id        = aws_security_group.node.id
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_eks_cluster.this.vpc_config[0].cluster_security_group_id
}

resource "aws_security_group_rule" "node_egress_ephemeral" {
  description              = "Allow worker nodes to reach the control plane on 1025-65535"
  type                     = "egress"
  security_group_id        = aws_security_group.node.id
  from_port                = 1025
  to_port                  = 65535
  protocol                 = "tcp"
  source_security_group_id = aws_eks_cluster.this.vpc_config[0].cluster_security_group_id
}

resource "aws_security_group_rule" "cluster_ingress_443" {
  description              = "Allow the control plane to receive traffic from worker nodes on 443"
  type                     = "ingress"
  security_group_id        = aws_eks_cluster.this.vpc_config[0].cluster_security_group_id
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.node.id
}

resource "aws_security_group_rule" "cluster_ingress_ephemeral" {
  description              = "Allow the control plane to receive traffic from worker nodes on 1025-65535"
  type                     = "ingress"
  security_group_id        = aws_eks_cluster.this.vpc_config[0].cluster_security_group_id
  from_port                = 1025
  to_port                  = 65535
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.node.id
}

resource "aws_security_group_rule" "cluster_egress_443" {
  description              = "Allow the control plane to reach worker nodes on 443"
  type                     = "egress"
  security_group_id        = aws_eks_cluster.this.vpc_config[0].cluster_security_group_id
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.node.id
}

resource "aws_security_group_rule" "cluster_egress_ephemeral" {
  description              = "Allow the control plane to reach worker nodes on 1025-65535"
  type                     = "egress"
  security_group_id        = aws_eks_cluster.this.vpc_config[0].cluster_security_group_id
  from_port                = 1025
  to_port                  = 65535
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.node.id
}

# ---------------------------------------------------------------------------
# SSH key pair for worker nodes
# ---------------------------------------------------------------------------
resource "tls_private_key" "eks" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "null_resource" "ssh_dir" {
  provisioner "local-exec" {
    command = "mkdir -p ${pathexpand("~/.ssh")}"
  }
}

resource "local_file" "eks_private_key" {
  filename        = pathexpand("~/.ssh/eks-aws.pem")
  content         = tls_private_key.eks.private_key_pem
  file_permission = "0400"

  depends_on = [null_resource.ssh_dir]
}

resource "aws_key_pair" "eks" {
  key_name   = "eks_kp"
  public_key = tls_private_key.eks.public_key_openssh

  tags = local.base_tags
}

# ---------------------------------------------------------------------------
# Worker node launch template
# ---------------------------------------------------------------------------
resource "aws_launch_template" "node" {
  name          = "demo-eks-node-lt"
  image_id      = data.aws_ami.eks_node.id
  instance_type = "t3.medium"
  key_name      = aws_key_pair.eks.key_name

  vpc_security_group_ids = [aws_security_group.node.id]

  iam_instance_profile {
    name = aws_iam_instance_profile.node.name
  }

  user_data = base64encode(<<-EOT
#!/bin/bash
set -o xtrace
export AWS_DEFAULT_REGION=${data.aws_region.current.region}
/etc/eks/bootstrap.sh ${aws_eks_cluster.this.name} --apiserver-endpoint ${aws_eks_cluster.this.endpoint} --b64-cluster-ca ${aws_eks_cluster.this.certificate_authority[0].data} --kubelet-extra-args '--node-labels=eks.amazonaws.com/nodegroup=${local.nodegroup}'
/opt/aws/bin/cfn-signal --exit-code $? --stack eks-cluster-stack --resource NodeAutoScalingGroup --region ${data.aws_region.current.region}
EOT
  )

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
  }

  block_device_mappings {
    device_name = "/dev/xvda"

    ebs {
      volume_type           = "gp2"
      volume_size           = 30
      encrypted             = true
      delete_on_termination = true
    }
  }

  tag_specifications {
    resource_type = "instance"
    tags          = merge(local.base_tags, { Name = "demo-eks-worker" })
  }

  tag_specifications {
    resource_type = "volume"
    tags          = merge(local.base_tags, { Name = "demo-eks-worker-volume" })
  }

  tags = merge(local.base_tags, { Name = "demo-eks-node-lt" })
}

# ---------------------------------------------------------------------------
# 30 second settle delay for the launch template before the node group stack
# ---------------------------------------------------------------------------
resource "time_sleep" "launch_template_settle" {
  create_duration = "30s"
  depends_on      = [aws_launch_template.node]
}

# ---------------------------------------------------------------------------
# CloudFormation managed Auto Scaling Group for unmanaged worker nodes
# ---------------------------------------------------------------------------
resource "aws_cloudformation_stack" "nodegroup" {
  name = "eks-cluster-stack"

  template_body = <<-YAML
AWSTemplateFormatVersion: 2010-09-09
Description: EKS unmanaged worker nodes Auto Scaling Group for demo-eks
Parameters:
  ClusterName:
    Type: String
  NodeGroupName:
    Type: String
  NodeLaunchTemplateId:
    Type: String
  NodeLaunchTemplateVersion:
    Type: String
  SubnetIds:
    Type: List<AWS::EC2::Subnet::Id>
  MinSize:
    Type: Number
    Default: 1
  DesiredCapacity:
    Type: Number
    Default: 3
  MaxSize:
    Type: Number
    Default: 4
Resources:
  NodeAutoScalingGroup:
    Type: AWS::AutoScaling::AutoScalingGroup
    UpdatePolicy:
      AutoScalingRollingUpdate:
        MaxBatchSize: 1
        MinInstancesInService: 3
        PauseTime: PT5M
    Properties:
      AutoScalingGroupName: !Ref NodeGroupName
      DesiredCapacity: !Ref DesiredCapacity
      MinSize: !Ref MinSize
      MaxSize: !Ref MaxSize
      VPCZoneIdentifier: !Ref SubnetIds
      LaunchTemplate:
        LaunchTemplateId: !Ref NodeLaunchTemplateId
        Version: !Ref NodeLaunchTemplateVersion
      HealthCheckType: EC2
      HealthCheckGracePeriod: 300
      Tags:
        - Key: Name
          Value: !Sub "$${ClusterName}-worker"
          PropagateAtLaunch: true
        - Key: kubernetes.io/cluster/demo-eks
          Value: owned
          PropagateAtLaunch: true
Outputs:
  AutoScalingGroupName:
    Description: Auto Scaling Group ID created for the EKS worker nodes
    Value: !Ref NodeAutoScalingGroup
YAML

  parameters = {
    ClusterName               = aws_eks_cluster.this.name
    NodeGroupName             = local.nodegroup
    NodeLaunchTemplateId      = aws_launch_template.node.id
    NodeLaunchTemplateVersion = aws_launch_template.node.latest_version
    SubnetIds                 = join(",", aws_subnet.private[*].id)
    MinSize                   = "1"
    DesiredCapacity           = "3"
    MaxSize                   = "4"
  }

  timeout_in_minutes = 20

  depends_on = [
    time_sleep.launch_template_settle,
    aws_eks_access_entry.node,
    aws_iam_role_policy_attachment.node_worker,
    aws_iam_role_policy_attachment.node_cni,
    aws_iam_role_policy_attachment.node_ecr,
    aws_iam_role_policy_attachment.node_ssm,
    aws_security_group_rule.node_self_ingress,
    aws_security_group_rule.node_self_egress,
    aws_security_group_rule.node_vpc_egress,
    aws_security_group_rule.node_ingress_443,
    aws_security_group_rule.node_ingress_ephemeral,
    aws_security_group_rule.node_egress_443,
    aws_security_group_rule.node_egress_ephemeral,
    aws_security_group_rule.cluster_ingress_443,
    aws_security_group_rule.cluster_ingress_ephemeral,
    aws_security_group_rule.cluster_egress_443,
    aws_security_group_rule.cluster_egress_ephemeral,
  ]
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------
output "node_instance_role_arn" {
  description = "ARN of the IAM role attached to the EKS worker node instances"
  value       = aws_iam_role.node.arn
}

output "node_security_group_id" {
  description = "ID of the security group assigned to the EKS worker nodes"
  value       = aws_security_group.node.id
}

output "autoscaling_group_id" {
  description = "Auto Scaling Group ID created by the eks-cluster-stack CloudFormation stack"
  value       = aws_cloudformation_stack.nodegroup.outputs["AutoScalingGroupName"]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
    local = {
      source  = "hashicorp/local"
      version = ">= 2.0.0"
    }
  }
}

variable "second_region" {
  description = "AWS region for the replica (disaster recovery) S3 bucket"
  type        = string
  default     = "us-west-2"
}

variable "stacks" {
  description = "Map of EKS stack names to their deployment regions"
  type = map(object({
    region = string
  }))
  default = {
    production = {
      region = "us-east-1"
    }
    staging = {
      region = "us-west-2"
    }
    development = {
      region = "eu-west-1"
    }
  }
}

locals {
  state_tags = {
    ManagedBy           = "Terraform"
    Environment         = "state-management"
    Purpose             = "remote-state-backend"
    Service             = "eks-terraform-backend"
    Automation          = "iacgod-agent"
    SecurityLevel       = "high"
    DataClassification  = "infrastructure-state"
    ComplianceFramework = "terraform-state-management"
  }
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_region" "current" {}
provider "aws" {
  alias  = "replica"
  region = var.second_region
}

# ---------------------------------------------------------------------------
# PRIMARY KMS KEY (us-east-1)
# ---------------------------------------------------------------------------
resource "aws_kms_key" "primary" {
  description             = "Primary KMS key for S3 state bucket server-side encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  rotation_period_in_days = 365
  tags                    = local.state_tags
}

# ---------------------------------------------------------------------------
# PRIMARY S3 BUCKET (us-east-1)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "primary" {
  bucket = "terraform-state-${data.aws_caller_identity.current.account_id}"
  tags   = local.state_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "primary" {
  bucket = aws_s3_bucket.primary.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "primary" {
  bucket = aws_s3_bucket.primary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id
  rule {
    bucket_key_enabled = false
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.primary.key_id
    }
  }
}

resource "aws_s3_bucket_policy" "primary" {
  bucket = aws_s3_bucket.primary.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          "arn:${data.aws_partition.current.partition}:s3:::${aws_s3_bucket.primary.id}",
          "arn:${data.aws_partition.current.partition}:s3:::${aws_s3_bucket.primary.id}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# REPLICA KMS KEY (second region)
# ---------------------------------------------------------------------------
resource "aws_kms_key" "replica" {
  provider                = aws.replica
  description             = "Replica KMS key for disaster recovery S3 bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  rotation_period_in_days = 365
  tags                    = local.state_tags
}

# ---------------------------------------------------------------------------
# REPLICA S3 BUCKET (second region)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "replica" {
  provider = aws.replica
  bucket   = "terraform-state-replica-${data.aws_caller_identity.current.account_id}"
  tags     = local.state_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id
  rule {
    bucket_key_enabled = false
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.replica.key_id
    }
  }
}

resource "aws_s3_bucket_policy" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          "arn:${data.aws_partition.current.partition}:s3:::${aws_s3_bucket.replica.id}",
          "arn:${data.aws_partition.current.partition}:s3:::${aws_s3_bucket.replica.id}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# CROSS-REGION REPLICATION IAM ROLE
# ---------------------------------------------------------------------------
resource "aws_iam_role" "replication" {
  name = "s3-cross-region-replication-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = local.state_tags
}

resource "aws_iam_role_policy" "replication" {
  name = "s3-cross-region-replication-policy"
  role = aws_iam_role.replication.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Resource = [
          "arn:${data.aws_partition.current.partition}:s3:::${aws_s3_bucket.primary.id}",
          "arn:${data.aws_partition.current.partition}:s3:::${aws_s3_bucket.primary.id}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Decrypt"
        ]
        Resource = [
          aws_kms_key.primary.arn
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:ReEncrypt*"
        ]
        Resource = [
          aws_kms_key.replica.arn
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = [
          "arn:${data.aws_partition.current.partition}:s3:::${aws_s3_bucket.replica.id}",
          "arn:${data.aws_partition.current.partition}:s3:::${aws_s3_bucket.replica.id}/*"
        ]
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# S3 CROSS-REGION REPLICATION CONFIGURATION
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_replication_configuration" "main" {
  bucket = aws_s3_bucket.primary.id
  role   = aws_iam_role.replication.arn

  rule {
    id       = "cross-region-replication"
    status   = "Enabled"
    priority = 1

    destination {
      bucket = aws_s3_bucket.replica.arn
      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica.arn
      }
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }
  }
}

# ---------------------------------------------------------------------------
# DYNAMODB TABLES — one per stack (pay-per-request, keyed by LockID)
# ---------------------------------------------------------------------------
resource "aws_dynamodb_table" "stack_lock" {
  for_each = var.stacks

  name         = "terraform-stack-lock-${each.key}"
  billing_mode = "PAY_PER_REQUEST"

  attribute {
    name = "LockID"
    type = "S"
  }

  hash_key = "LockID"

  tags = local.state_tags

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# STACK-SPECIFIC IAM POLICIES
# ---------------------------------------------------------------------------
resource "aws_iam_policy" "stack" {
  for_each = var.stacks

  name = "terraform-stack-${each.key}-policy"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:ListBucket"
        ]
        Resource = [
          "arn:${data.aws_partition.current.partition}:s3:::${aws_s3_bucket.primary.id}",
          "arn:${data.aws_partition.current.partition}:s3:::${aws_s3_bucket.primary.id}/${each.key}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "dynamodb:GetItem",
          "dynamodb:PutItem",
          "dynamodb:DeleteItem",
          "dynamodb:UpdateItem",
          "dynamodb:Scan",
          "dynamodb:Query"
        ]
        Resource = [aws_dynamodb_table.stack_lock[each.key].arn]
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey"
        ]
        Resource = [aws_kms_key.primary.arn]
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# LOCAL BACKEND.TF FILES — one per stack in eks-stacks/<name>/backend.tf
# ---------------------------------------------------------------------------
resource "local_file" "backend" {
  for_each = var.stacks

  filename = "eks-stacks/${each.key}/backend.tf"
  content  = <<-EOF
terraform {
  backend "s3" {
    bucket         = "${aws_s3_bucket.primary.bucket}"
    key            = "${each.key}/terraform.tfstate"
    region         = "${data.aws_region.current.region}"
    encrypt        = true
    dynamodb_table = "${aws_dynamodb_table.stack_lock[each.key].name}"
    kms_key_id     = "${aws_kms_key.primary.key_id}"
  }
}
EOF
}

variable "users" {
  description = "Map of IAM usernames to their Owner tag value. Owner 'Devel' assigns the user to the developer group, anything else to the guest group."
  type        = map(string)
  default = {
    dev1  = "Devel"
    dev2  = "Devel"
    guest = "Guest"
  }
}

# --- IAM Groups ---

resource "aws_iam_group" "developers" {
  name = "Ersia_Devel_Group"
}

resource "aws_iam_group" "guests" {
  name = "Ersia_Guest_Group"
}

# --- AWS-managed policy attachments ---

resource "aws_iam_group_policy_attachment" "developers_readonly" {
  group      = aws_iam_group.developers.name
  policy_arn = "arn:aws:iam::aws:policy/ReadOnlyAccess"
}

resource "aws_iam_group_policy_attachment" "guests_iamreadonly" {
  group      = aws_iam_group.guests.name
  policy_arn = "arn:aws:iam::aws:policy/IAMReadOnlyAccess"
}

# --- IAM Users ---

resource "aws_iam_user" "this" {
  for_each = var.users

  name = each.key
  tags = {
    Owner = each.value
  }
}

# --- Group membership ---

resource "aws_iam_user_group_membership" "this" {
  for_each = var.users

  user = each.key

  groups = [
    each.value == "Devel"
    ? aws_iam_group.developers.name
    : aws_iam_group.guests.name
  ]

  depends_on = [
    aws_iam_user.this,
    aws_iam_group_policy_attachment.developers_readonly,
    aws_iam_group_policy_attachment.guests_iamreadonly,
  ]
}

data "aws_region" "current" {}
data "aws_partition" "current" {}
data "aws_caller_identity" "current" {}

variable "name_prefix" {
  description = "Prefix for pet name generation"
  type        = string
  default     = "ws"
}

resource "random_pet" "this" {
  length    = 2
  separator = "-"
  prefix    = var.name_prefix
}

# KMS key for SQS queue encryption with automatic rotation
resource "aws_kms_key" "sqs" {
  description             = "KMS key for ${random_pet.this.id} SQS queue"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_kms_alias" "sqs" {
  name          = "alias/${random_pet.this.id}-sqs"
  target_key_id = aws_kms_key.sqs.key_id
}

# SQS queue
resource "aws_sqs_queue" "this" {
  name                              = "${random_pet.this.id}-messages"
  kms_master_key_id                 = aws_kms_key.sqs.key_id
  kms_data_key_reuse_period_seconds = 300
}

# CloudWatch log group for API access logging
resource "aws_cloudwatch_log_group" "api_logs" {
  name              = "/aws/apigateway/${random_pet.this.id}"
  retention_in_days = 1
}

# IAM role for API Gateway to assume
resource "aws_iam_role" "api_gateway" {
  name               = "${random_pet.this.id}-api-gw-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action    = "sts:AssumeRole"
        Effect    = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
      }
    ]
  })
}

# IAM policy with SQS and CloudWatch Logs permissions
resource "aws_iam_policy" "api_gateway" {
  name   = "${random_pet.this.id}-api-gw-policy"
  policy = data.aws_iam_policy_document.api_gateway_policy.json
}

data "aws_iam_policy_document" "api_gateway_policy" {
  statement {
    actions   = ["sqs:SendMessage"]
    resources = [aws_sqs_queue.this.arn]
  }
  statement {
    actions   = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:DescribeLogGroups",
      "logs:DescribeLogStreams",
      "logs:PutLogEvents"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy_attachment" "api_gateway" {
  role       = aws_iam_role.api_gateway.name
  policy_arn = aws_iam_policy.api_gateway.arn
}

# WebSocket API
resource "aws_apigatewayv2_api" "this" {
  name                       = random_pet.this.id
  protocol_type              = "WEBSOCKET"
  route_selection_expression = "$request.body.action"
}

# Connect route - mock integration returning 200
resource "aws_apigatewayv2_route" "connect" {
  api_id    = aws_apigatewayv2_api.this.id
  route_key = "$connect"
  target    = "integrations/${aws_apigatewayv2_integration.connect.id}"
}

resource "aws_apigatewayv2_integration" "connect" {
  api_id           = aws_apigatewayv2_api.this.id
  integration_type = "MOCK"
  request_templates = {
    "application/json" = jsonencode({
      statusCode = 200
    })
  }
  template_selection_expression = "\\$default"
}

# Default route - send raw message body to SQS via AWS service integration
resource "aws_apigatewayv2_route" "default" {
  api_id    = aws_apigatewayv2_api.this.id
  route_key = "$default"
  target    = "integrations/${aws_apigatewayv2_integration.default.id}"
}

resource "aws_apigatewayv2_integration" "default" {
  api_id             = aws_apigatewayv2_api.this.id
  integration_type   = "AWS"
  integration_method = "POST"
  integration_uri    = "arn:${data.aws_partition.current.partition}:apigateway:${data.aws_region.current.region}:sqs:path/${data.aws_caller_identity.current.account_id}/${aws_sqs_queue.this.name}"
  credentials_arn    = aws_iam_role.api_gateway.arn
  passthrough_behavior = "WHEN_NO_MATCH"
  request_parameters = {
    "integration.request.header.Content-Type" = "'application/x-www-form-urlencoded'"
  }
  request_templates = {
    "application/json" = "Action=SendMessage&MessageBody=$input.body"
  }
  template_selection_expression = "\\$default"
}

# Disconnect route - send fixed "Client disconnected" message to SQS
resource "aws_apigatewayv2_route" "disconnect" {
  api_id    = aws_apigatewayv2_api.this.id
  route_key = "$disconnect"
  target    = "integrations/${aws_apigatewayv2_integration.disconnect.id}"
}

resource "aws_apigatewayv2_integration" "disconnect" {
  api_id             = aws_apigatewayv2_api.this.id
  integration_type   = "AWS"
  integration_method = "POST"
  integration_uri    = "arn:${data.aws_partition.current.partition}:apigateway:${data.aws_region.current.region}:sqs:path/${data.aws_caller_identity.current.account_id}/${aws_sqs_queue.this.name}"
  credentials_arn    = aws_iam_role.api_gateway.arn
  passthrough_behavior = "WHEN_NO_MATCH"
  request_parameters = {
    "integration.request.header.Content-Type" = "'application/x-www-form-urlencoded'"
  }
  request_templates = {
    "application/json" = "Action=SendMessage&MessageBody=Client disconnected"
  }
  template_selection_expression = "\\$default"
}

# Deployment with auto-deploy
resource "aws_apigatewayv2_deployment" "this" {
  api_id      = aws_apigatewayv2_api.this.id
  description = "Deployment for ${random_pet.this.id}"
  triggers = {
    redeployment = sha1(join(",", [
      aws_apigatewayv2_integration.connect.id,
      aws_apigatewayv2_integration.default.id,
      aws_apigatewayv2_integration.disconnect.id,
      aws_apigatewayv2_route.connect.id,
      aws_apigatewayv2_route.default.id,
      aws_apigatewayv2_route.disconnect.id,
    ]))
  }
  lifecycle {
    create_before_destroy = true
  }
}

# Stage "dev" with access logging
resource "aws_apigatewayv2_stage" "dev" {
  api_id      = aws_apigatewayv2_api.this.id
  name        = "dev"
  deployment_id = aws_apigatewayv2_deployment.this.id
  auto_deploy = true

  default_route_settings {
    logging_level = "INFO"
    data_trace_enabled = false
    throttling_burst_limit = 500
    throttling_rate_limit  = 1000
  }

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.api_logs.arn
    format = jsonencode({
      requestId               = "$context.requestId"
      ip                      = "$context.identity.sourceIp"
      caller                  = "$context.identity.caller"
      user                    = "$context.identity.user"
      requestTime             = "$context.requestTime"
      httpMethod              = "$context.httpMethod"
      resourcePath            = "$context.resourcePath"
      status                  = "$context.status"
      protocol                = "$context.protocol"
      responseLength          = "$context.responseLength"
      integrationErrorMessage = "$context.integrationErrorMessage"
      routeKey                = "$context.routeKey"
      connectionId            = "$context.connectionId"
      eventType               = "$context.eventType"
    })
  }
}

output "websocket_url" {
  description = "The WebSocket endpoint URL including the stage name"
  value       = "${aws_apigatewayv2_api.this.api_endpoint}/dev"
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

variable "vpc_test_name" {
  description = "Name tag for the first standalone VPC"
  type        = string
  default     = "XXXX-vpc-test"
}

variable "vpc_test_cidr_block" {
  description = "CIDR block for the first standalone VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "vpc_test_enable_dns_support" {
  description = "Enable DNS resolution support for the first standalone VPC"
  type        = bool
  default     = true
}

variable "vpc_test_enable_dns_hostnames" {
  description = "Enable DNS hostnames for the first standalone VPC"
  type        = bool
  default     = false
}

variable "vpc_default_name" {
  description = "Name tag for the second standalone VPC"
  type        = string
  default     = "Default"
}

variable "vpc_default_cidr_block" {
  description = "CIDR block for the second standalone VPC"
  type        = string
  default     = "172.31.0.0/16"
}

variable "vpc_default_enable_dns_support" {
  description = "Enable DNS resolution support for the second standalone VPC"
  type        = bool
  default     = true
}

variable "vpc_default_enable_dns_hostnames" {
  description = "Enable DNS hostnames for the second standalone VPC"
  type        = bool
  default     = true
}

variable "vpc_eksctl_name" {
  description = "Name tag for the eksctl-managed standalone VPC"
  type        = string
  default     = "eksctl-eks-cluster-px-cluster/VPC"
}

variable "vpc_eksctl_cidr_block" {
  description = "CIDR block for the eksctl-managed standalone VPC"
  type        = string
  default     = "192.168.0.0/16"
}

variable "vpc_eksctl_enable_dns_support" {
  description = "Enable DNS resolution support for the eksctl-managed standalone VPC"
  type        = bool
  default     = true
}

variable "vpc_eksctl_enable_dns_hostnames" {
  description = "Enable DNS hostnames for the eksctl-managed standalone VPC"
  type        = bool
  default     = true
}

variable "vpc_eksctl_cluster_name_tag_key" {
  description = "EKSCTL tag key recording the cluster name"
  type        = string
  default     = "alpha.eksctl.io/cluster-name"
}

variable "vpc_eksctl_cluster_name" {
  description = "EKS cluster name recorded in the eksctl cluster-name tag"
  type        = string
  default     = "eks-cluster-px"
}

variable "vpc_eksctl_version_tag_key" {
  description = "EKSCTL tag key recording the eksctl version"
  type        = string
  default     = "alpha.eksctl.io/eksctl-version"
}

variable "vpc_eksctl_version" {
  description = "EKSCTL version recorded in the eksctl version tag"
  type        = string
  default     = "0.94.0"
}

variable "vpc_untagged_cidr_block" {
  description = "CIDR block for the untagged standalone VPC"
  type        = string
  default     = "10.0.0.0/24"
}

variable "vpc_untagged_enable_dns_support" {
  description = "Enable DNS resolution support for the untagged standalone VPC"
  type        = bool
  default     = true
}

variable "vpc_untagged_enable_dns_hostnames" {
  description = "Enable DNS hostnames for the untagged standalone VPC"
  type        = bool
  default     = false
}

variable "vpc_empty_name_tag_cidr_block" {
  description = "CIDR block for the standalone VPC carrying an empty Name tag"
  type        = string
  default     = "10.0.0.0/16"
}

variable "vpc_empty_name_tag_enable_dns_support" {
  description = "Enable DNS resolution support for the standalone VPC carrying an empty Name tag"
  type        = bool
  default     = true
}

variable "vpc_empty_name_tag_enable_dns_hostnames" {
  description = "Enable DNS hostnames for the standalone VPC carrying an empty Name tag"
  type        = bool
  default     = false
}

variable "vpc_empty_name_tag" {
  description = "Value of the empty Name tag on the fifth standalone VPC"
  type        = string
  default     = ""
}

resource "aws_vpc" "test" {
  cidr_block           = var.vpc_test_cidr_block
  instance_tenancy     = "default"
  enable_dns_support   = var.vpc_test_enable_dns_support
  enable_dns_hostnames = var.vpc_test_enable_dns_hostnames

  tags = {
    Name = var.vpc_test_name
  }
}

resource "aws_vpc" "default" {
  cidr_block           = var.vpc_default_cidr_block
  instance_tenancy     = "default"
  enable_dns_support   = var.vpc_default_enable_dns_support
  enable_dns_hostnames = var.vpc_default_enable_dns_hostnames

  tags = {
    Name = var.vpc_default_name
  }
}

resource "aws_vpc" "eksctl" {
  cidr_block           = var.vpc_eksctl_cidr_block
  instance_tenancy     = "default"
  enable_dns_support   = var.vpc_eksctl_enable_dns_support
  enable_dns_hostnames = var.vpc_eksctl_enable_dns_hostnames

  tags = {
    Name                                  = var.vpc_eksctl_name
    (var.vpc_eksctl_cluster_name_tag_key) = var.vpc_eksctl_cluster_name
    (var.vpc_eksctl_version_tag_key)      = var.vpc_eksctl_version
  }
}

resource "aws_vpc" "untagged" {
  cidr_block           = var.vpc_untagged_cidr_block
  instance_tenancy     = "default"
  enable_dns_support   = var.vpc_untagged_enable_dns_support
  enable_dns_hostnames = var.vpc_untagged_enable_dns_hostnames
}

resource "aws_vpc" "empty_name_tag" {
  cidr_block           = var.vpc_empty_name_tag_cidr_block
  instance_tenancy     = "default"
  enable_dns_support   = var.vpc_empty_name_tag_enable_dns_support
  enable_dns_hostnames = var.vpc_empty_name_tag_enable_dns_hostnames

  tags = {
    Name = var.vpc_empty_name_tag
  }
}

variable "tags" {
  description = "Optional tags to apply to the IAM roles. Any tag that is already set identically in the provider default tags is merged and skipped automatically by the AWS provider."
  type        = map(string)
  default     = {}
}

data "aws_partition" "current" {}

# ---------------------------------------------------------------------------
# ECS service role (ecs-role)
# ---------------------------------------------------------------------------
resource "aws_iam_role" "ecs_role" {
  name                 = "ecs-role"
  path                 = "/"
  description          = "Allows the ECS service scheduler to manage the containers that belong to ECS services."
  assume_role_policy   = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowECS"
        Effect    = "Allow"
        Principal = {
          Service = "ecs.amazonaws.com"
        }
        Action    = "sts:AssumeRole"
      }
    ]
  })
  force_detach_policies = true
  tags                  = var.tags
}

resource "aws_iam_role_policy_attachment" "ecs_role_amazon_ec2_container_service" {
  role       = aws_iam_role.ecs_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonEC2ContainerServiceRole"
}

# ---------------------------------------------------------------------------
# ECS task execution role (ecs-tasks-role)
# ---------------------------------------------------------------------------
resource "aws_iam_role" "ecs_tasks_role" {
  name                 = "ecs-tasks-role"
  path                 = "/"
  description          = "Used by the ECS tasks to pull container images and publish container logs to CloudWatch."
  assume_role_policy   = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowECSTasks"
        Effect    = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action    = "sts:AssumeRole"
      }
    ]
  })
  force_detach_policies = true
  tags                  = var.tags
}

resource "aws_iam_role_policy_attachment" "ecs_tasks_role_amazon_ecs_task_execution" {
  role       = aws_iam_role.ecs_tasks_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

# ---------------------------------------------------------------------------
# EventBridge / CloudWatch Events scheduler role (events-role)
# ---------------------------------------------------------------------------
resource "aws_iam_role" "events_role" {
  name                 = "events-role"
  path                 = "/"
  description          = "Allows Amazon EventBridge to run scheduled ECS tasks."
  assume_role_policy   = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowEvents"
        Effect    = "Allow"
        Principal = {
          Service = "events.amazonaws.com"
        }
        Action    = "sts:AssumeRole"
      }
    ]
  })
  force_detach_policies = true
  tags                  = var.tags
}

resource "aws_iam_policy" "ecs_policy" {
  name        = "ecs-policy"
  description = "Allows EventBridge to run ECS tasks and pass only the ECS task execution role."
  path        = "/"
  policy      = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "RunECSTasks"
        Effect   = "Allow"
        Action   = "ecs:RunTask"
        Resource = "*"
      },
      {
        Sid      = "PassECSTaskExecutionRole"
        Effect   = "Allow"
        Action   = "iam:PassRole"
        Resource = aws_iam_role.ecs_tasks_role.arn
        Condition = {
          StringEquals = {
            "iam:PassedToService" = "ecs-tasks.amazonaws.com"
          }
        }
      }
    ]
  })
  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "events_role_cloudwatch_logs_full_access" {
  role       = aws_iam_role.events_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/CloudWatchLogsFullAccess"
}

resource "aws_iam_role_policy_attachment" "events_role_ecs_policy" {
  role       = aws_iam_role.events_role.name
  policy_arn = aws_iam_policy.ecs_policy.arn
}

terraform {
  required_version = ">= 1.6"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

variable "primary_bucket_name" {
  description = "Prefix used for the primary S3 bucket name (suffixed with the AWS account ID)"
  type        = string
  default     = "example1"
}

variable "secondary_bucket_name" {
  description = "Prefix used for the secondary S3 bucket name (suffixed with the AWS account ID)"
  type        = string
  default     = "example2"
}

variable "mrap_name" {
  description = "Name of the Multi-Region Access Point"
  type        = string
  default     = "example-mrap"
}

locals {
  primary_region   = "us-east-1"
  secondary_region = "us-west-2"
  account_id       = data.aws_caller_identity.current.account_id
  partition        = data.aws_partition.current.partition
  primary_bucket   = "${var.primary_bucket_name}-${local.account_id}"
  secondary_bucket = "${var.secondary_bucket_name}-${local.account_id}"
  owner_arn        = "arn:${local.partition}:iam::${local.account_id}:root"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

provider "aws" {
  alias  = "primary"
  region = local.primary_region
}

provider "aws" {
  alias  = "secondary"
  region = local.secondary_region
}

# ---------------------------------------------------------------------------
# Customer-managed KMS keys with automatic rotation, one per bucket region
# ---------------------------------------------------------------------------
resource "aws_kms_key" "primary" {
  provider                = aws.primary
  description             = "KMS key for default encryption of the primary S3 bucket ${local.primary_bucket}"
  enable_key_rotation     = true
  deletion_window_in_days = 7
}

resource "aws_kms_key" "secondary" {
  provider                = aws.secondary
  description             = "KMS key for default encryption of the secondary S3 bucket ${local.secondary_bucket}"
  enable_key_rotation     = true
  deletion_window_in_days = 7
}

# ---------------------------------------------------------------------------
# Primary S3 bucket (us-east-1)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "primary" {
  provider = aws.primary
  bucket   = local.primary_bucket

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "primary" {
  provider = aws.primary
  bucket   = aws_s3_bucket.primary.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "primary" {
  provider = aws.primary
  bucket   = aws_s3_bucket.primary.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "primary" {
  provider = aws.primary
  bucket   = aws_s3_bucket.primary.id
  acl      = "private"

  depends_on = [aws_s3_bucket_ownership_controls.primary]
}

resource "aws_s3_bucket_public_access_block" "primary" {
  provider = aws.primary
  bucket   = aws_s3_bucket.primary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  provider = aws.primary
  bucket   = aws_s3_bucket.primary.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.primary.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# ---------------------------------------------------------------------------
# Secondary S3 bucket (us-west-2)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "secondary" {
  provider = aws.secondary
  bucket   = local.secondary_bucket

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "secondary" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.secondary.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "secondary" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.secondary.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "secondary" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.secondary.id
  acl      = "private"

  depends_on = [aws_s3_bucket_ownership_controls.secondary]
}

resource "aws_s3_bucket_public_access_block" "secondary" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.secondary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "secondary" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.secondary.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.secondary.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# ---------------------------------------------------------------------------
# IAM role and policy for S3 replication (least privilege)
# ---------------------------------------------------------------------------
resource "aws_iam_role" "replication" {
  name = "s3-replication-${local.primary_bucket}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowS3ToAssumeRole"
        Effect    = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "replication" {
  name = "s3-replication-policy-${local.primary_bucket}"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SourceBucketReadConfiguration"
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket",
        ]
        Resource = [aws_s3_bucket.primary.arn]
      },
      {
        Sid    = "SourceBucketReadObjectVersions"
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging",
        ]
        Resource = ["${aws_s3_bucket.primary.arn}/*"]
      },
      {
        Sid    = "DestinationBucketReplicate"
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
        ]
        Resource = ["${aws_s3_bucket.secondary.arn}/*"]
      },
      {
        Sid    = "DecryptSourceObjects"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
        ]
        Resource = [aws_kms_key.primary.arn]
      },
      {
        Sid    = "EncryptDestinationObjects"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:GenerateDataKey",
        ]
        Resource = [aws_kms_key.secondary.arn]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "replication" {
  role       = aws_iam_role.replication.name
  policy_arn = aws_iam_policy.replication.arn
}

# ---------------------------------------------------------------------------
# S3 replication from the primary bucket to the secondary bucket
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_replication_configuration" "primary" {
  provider = aws.primary
  role     = aws_iam_role.replication.arn
  bucket   = aws_s3_bucket.primary.id

  rule {
    id     = "replicate-kms-encrypted-objects"
    status = "Enabled"

    filter {
      prefix = ""
    }

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.secondary.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.secondary.arn
      }
    }
  }

  depends_on = [aws_iam_role_policy_attachment.replication]
}

# ---------------------------------------------------------------------------
# Multi-Region Access Point (created and managed in the secondary region)
# ---------------------------------------------------------------------------
resource "aws_s3control_multi_region_access_point" "mrap" {
  provider   = aws.secondary
  account_id = local.account_id

  details {
    name = var.mrap_name

    public_access_block {
      block_public_acls       = true
      block_public_policy     = true
      ignore_public_acls      = true
      restrict_public_buckets = true
    }

    region {
      bucket = aws_s3_bucket.primary.id
    }

    region {
      bucket = aws_s3_bucket.secondary.id
    }
  }
}

resource "aws_s3control_multi_region_access_point_policy" "mrap" {
  provider   = aws.secondary
  account_id = local.account_id

  details {
    name = aws_s3control_multi_region_access_point.mrap.name

    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Sid       = "AllowOwningAccountObjectAccess"
          Effect    = "Allow"
          Principal = {
            AWS = local.owner_arn
          }
          Action = [
            "s3:GetObject",
            "s3:PutObject",
          ]
          Resource = [
            "${aws_s3control_multi_region_access_point.mrap.arn}/object/*",
          ]
        }
      ]
    })
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Data sources - static account/region metadata only
# ------------------------------------------------------------------------------
data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "namespace" {
  type        = string
  default     = "eg"
  description = "Namespace, which is often abbreviated organization name, for Cloud Posse null-label naming."
}

variable "environment" {
  type        = string
  default     = "ue2"
  description = "Environment, e.g. 'uw2', 'us-west-2', OR 'prod', 'staging', 'dev'."
}

variable "stage" {
  type        = string
  default     = "dev"
  description = "Stage, e.g. 'prod', 'staging', 'dev'."
}

variable "name" {
  type        = string
  default     = "patch-manager"
  description = "Solution name used as the base label."
}

variable "attributes" {
  type        = list(string)
  default     = []
  description = "Additional attributes appended to the identifier."
}

variable "delimiter" {
  type        = string
  default     = "-"
  description = "Delimiter used to join the null-label components."
}

variable "tags" {
  type        = map(string)
  default     = {}
  description = "Additional tags applied to all resources."
}

variable "scan_window_schedule" {
  type        = string
  default     = "cron(0 0 18 ? * WED *)"
  description = "Cron schedule for the patch scan maintenance window."
}

variable "install_window_schedule" {
  type        = string
  default     = "cron(0 0 21 ? * WED *)"
  description = "Cron schedule for the patch install maintenance window."
}

variable "scan_window_duration_hours" {
  type        = number
  default     = 3
  description = "Duration of the scan maintenance window in hours."
}

variable "install_window_duration_hours" {
  type        = number
  default     = 3
  description = "Duration of the install maintenance window in hours."
}

variable "scan_window_cutoff_hours" {
  type        = number
  default     = 1
  description = "Number of hours before the end of the scan window that new tasks stop being scheduled."
}

variable "install_window_cutoff_hours" {
  type        = number
  default     = 1
  description = "Number of hours before the end of the install window that new tasks stop being scheduled."
}

variable "allow_unassociated_targets" {
  type        = bool
  default     = true
  description = "Whether targets must be registered with the maintenance window before running tasks."
}

variable "scan_instance_tag_key" {
  type        = string
  default     = "Patch Group"
  description = "Tag key used to select instances for the scan maintenance window."
}

variable "scan_instance_tag_value" {
  type        = string
  default     = "TOSCAN"
  description = "Tag value used to select instances for the scan maintenance window."
}

variable "install_instance_tag_key" {
  type        = string
  default     = "Patch Group"
  description = "Tag key used to select instances for the install maintenance window."
}

variable "install_instance_tag_value" {
  type        = string
  default     = "TOPATCH"
  description = "Tag value used to select instances for the install maintenance window."
}

variable "max_concurrency" {
  type        = string
  default     = "20"
  description = "Maximum number of targets that can run the task simultaneously."
}

variable "max_errors" {
  type        = string
  default     = "50"
  description = "Maximum number of errors allowed before the task stops being scheduled on additional targets."
}

variable "scan_reboot_option" {
  type        = string
  default     = "NoReboot"
  description = "Reboot behavior for the scan operation."
}

variable "reboot_option" {
  type        = string
  default     = "RebootIfNeeded"
  description = "Reboot behavior for the install operation."
}

variable "task_timeout_seconds" {
  type        = number
  default     = 3600
  description = "Timeout for the AWS-RunPatchBaseline Run Command invocation, in seconds."
}

variable "s3_log_key_prefix" {
  type        = string
  default     = "scanning"
  description = "S3 key prefix under which command output is stored."
}

variable "create_s3_log_bucket" {
  type        = bool
  default     = true
  description = "Whether to create the versioned, private S3 log bucket for command output."
}

variable "s3_log_bucket_name" {
  type        = string
  default     = ""
  description = "Optional explicit S3 log bucket name. Defaults to a null-label derived name."
}

variable "enable_sns_notifications" {
  type        = bool
  default     = false
  description = "Whether to create an SNS topic and send Run Command notifications to it."
}

variable "enable_cloudwatch_logs" {
  type        = bool
  default     = false
  description = "Whether to send Run Command output to CloudWatch Logs."
}

variable "cloudwatch_log_retention_days" {
  type        = number
  default     = 14
  description = "Retention period in days for the optional CloudWatch log group."
}

variable "approve_after_days" {
  type        = number
  default     = 7
  description = "Number of days after a patch is released before it is automatically approved."
}

variable "patch_baseline_compliance_level" {
  type        = string
  default     = "HIGH"
  description = "Compliance level for patches approved by the approximation rule."
}

variable "enable_non_security" {
  type        = bool
  default     = true
  description = "Whether to include non-security updates in the default approval rule."
}

variable "approved_patches" {
  type        = list(string)
  default     = []
  description = "List of explicitly approved patches."
}

variable "approved_patches_compliance_level" {
  type        = string
  default     = "HIGH"
  description = "Compliance level for the explicitly approved patches."
}

variable "rejected_patches" {
  type        = list(string)
  default     = []
  description = "List of explicitly rejected patches."
}

# ------------------------------------------------------------------------------
# Locals - Cloud Posse null-label style naming and tags
# ------------------------------------------------------------------------------
locals {
  context_labels = compact([
    var.namespace,
    var.environment,
    var.stage,
    var.name,
  ])

  id = join(var.delimiter, concat(local.context_labels, var.attributes))

  label_tags = {
    for k, v in {
      "Name"        = local.id
      "Namespace"   = var.namespace
      "Environment" = var.environment
      "Stage"       = var.stage
      "Terraform"   = "true"
    } : k => v if length(v) > 0
  }

  tags = merge(local.label_tags, var.tags)

  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.name

  scan_window_name    = format("%s-scan", local.id)
  install_window_name = format("%s-install", local.id)
  patch_baseline_name = format("%s-al2-patch-baseline", local.id)
  sns_topic_name      = format("%s-patch-notifications", local.id)
  cloudwatch_log_name = format("/aws/ssm/%s", local.id)
  iam_role_name       = format("%s-maintenance-window-service-role", local.id)

  s3_log_bucket_name = var.s3_log_bucket_name != "" ? var.s3_log_bucket_name : format("%s-ssm-command-logs", local.id)

  s3_log_bucket_id  = var.create_s3_log_bucket ? aws_s3_bucket.logs[0].id : var.s3_log_bucket_name
  s3_log_bucket_arn = var.create_s3_log_bucket ? aws_s3_bucket.logs[0].arn : format("arn:%s:s3:::%s", local.partition, var.s3_log_bucket_name)
}

# ------------------------------------------------------------------------------
# Patch baseline for Amazon Linux 2
# ------------------------------------------------------------------------------
resource "aws_ssm_patch_baseline" "main" {
  name                              = local.patch_baseline_name
  description                       = "Amazon Linux 2 patch baseline with auto-approval of Critical, Important, and Medium severity Security, Bugfix, and Recommended patches after ${var.approve_after_days} days."
  operating_system                  = "AMAZON_LINUX_2"
  approved_patches                  = var.approved_patches
  approved_patches_compliance_level = var.approved_patches_compliance_level
  rejected_patches                  = var.rejected_patches
  tags                              = local.tags

  approval_rule {
    approve_after_days  = var.approve_after_days
    compliance_level    = var.patch_baseline_compliance_level
    enable_non_security = var.enable_non_security

    patch_filter {
      key    = "PRODUCT"
      values = ["AmazonLinux2"]
    }
    patch_filter {
      key    = "CLASSIFICATION"
      values = ["Security", "Bugfix", "Recommended"]
    }
    patch_filter {
      key    = "SEVERITY"
      values = ["Critical", "Important", "Medium"]
    }
  }
}

# ------------------------------------------------------------------------------
# Register both patch groups against the Amazon Linux 2 baseline
# ------------------------------------------------------------------------------
resource "aws_ssm_patch_group" "scan" {
  baseline_id = aws_ssm_patch_baseline.main.id
  patch_group = var.scan_instance_tag_value
}

resource "aws_ssm_patch_group" "install" {
  baseline_id = aws_ssm_patch_baseline.main.id
  patch_group = var.install_instance_tag_value
}

# ------------------------------------------------------------------------------
# Maintenance window service role
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "maintenance_window_assume_role" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["ssm.amazonaws.com", "ec2.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

data "aws_iam_policy_document" "maintenance_window_role" {
  statement {
    sid    = "SSMRunPatchBaselineCommands"
    effect = "Allow"
    actions = [
      "ssm:SendCommand",
      "ssm:GetDocument",
    ]
    resources = [
      format("arn:%s:ssm:%s:%s:document/AWS-RunPatchBaseline", local.partition, local.region, local.account_id),
      format("arn:%s:ssm:%s:%s:managed-instance/*", local.partition, local.region, local.account_id),
    ]
  }

  statement {
    sid    = "SSMListAndInspectCommands"
    effect = "Allow"
    actions = [
      "ssm:CancelCommand",
      "ssm:ListCommands",
      "ssm:ListCommandInvocations",
      "ssm:GetCommandInvocation",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "WriteCommandOutputToS3"
    effect = "Allow"
    actions = [
      "s3:GetBucketLocation",
      "s3:GetObject",
      "s3:PutObject",
    ]
    resources = [
      local.s3_log_bucket_arn,
      format("%s/*", local.s3_log_bucket_arn),
    ]
  }

  dynamic "statement" {
    for_each = var.create_s3_log_bucket ? toset([1]) : toset([])
    content {
      sid    = "DecryptAndEncryptCommandOutput"
      effect = "Allow"
      actions = [
        "kms:Decrypt",
        "kms:GenerateDataKey",
        "kms:ReEncryptFrom",
        "kms:ReEncryptTo",
      ]
      resources = [aws_kms_key.logs[0].arn]
    }
  }

  dynamic "statement" {
    for_each = var.enable_sns_notifications ? toset([1]) : toset([])
    content {
      sid    = "PublishCommandNotifications"
      effect = "Allow"
      actions = [
        "sns:Publish",
      ]
      resources = [aws_sns_topic.maintenance_window[0].arn]
    }
  }

  dynamic "statement" {
    for_each = var.enable_cloudwatch_logs ? toset([1]) : toset([])
    content {
      sid    = "WriteCommandOutputToCloudWatch"
      effect = "Allow"
      actions = [
        "logs:CreateLogStream",
        "logs:PutLogEvents",
        "logs:DescribeLogStreams",
      ]
      resources = [
        aws_cloudwatch_log_group.maintenance_window[0].arn,
        format("%s:log-stream:*", aws_cloudwatch_log_group.maintenance_window[0].arn),
      ]
    }
  }
}

resource "aws_iam_role" "maintenance_window" {
  name               = local.iam_role_name
  description        = "Service role used by AWS Systems Manager maintenance windows to run AWS-RunPatchBaseline tasks."
  assume_role_policy = data.aws_iam_policy_document.maintenance_window_assume_role.json
  tags               = local.tags
}

resource "aws_iam_role_policy" "maintenance_window" {
  name   = format("%s-policy", local.id)
  role   = aws_iam_role.maintenance_window.id
  policy = data.aws_iam_policy_document.maintenance_window_role.json
}

# ------------------------------------------------------------------------------
# SNS notifications (optional, disabled by default)
# ------------------------------------------------------------------------------
resource "aws_sns_topic" "maintenance_window" {
  count        = var.enable_sns_notifications ? 1 : 0
  name         = local.sns_topic_name
  display_name = format("%s Patch Notifications", local.id)
  tags         = local.tags
}

data "aws_iam_policy_document" "sns_topic" {
  count = var.enable_sns_notifications ? 1 : 0

  statement {
    sid    = "AllowAccountToPublish"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = [format("arn:%s:iam::%s:root", local.partition, local.account_id)]
    }
    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.maintenance_window[0].arn]
  }

  statement {
    sid    = "AllowSSMToPublish"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["ssm.amazonaws.com"]
    }
    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.maintenance_window[0].arn]
  }
}

resource "aws_sns_topic_policy" "maintenance_window" {
  count  = var.enable_sns_notifications ? 1 : 0
  arn    = aws_sns_topic.maintenance_window[0].arn
  policy = data.aws_iam_policy_document.sns_topic[0].json
}

# ------------------------------------------------------------------------------
# CloudWatch Logs (optional, disabled by default)
# ------------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "maintenance_window" {
  count             = var.enable_cloudwatch_logs ? 1 : 0
  name              = local.cloudwatch_log_name
  retention_in_days = var.cloudwatch_log_retention_days
  tags              = local.tags
}

# ------------------------------------------------------------------------------
# Versioned, private S3 log bucket for command output
# ------------------------------------------------------------------------------
resource "aws_kms_key" "logs" {
  count                   = var.create_s3_log_bucket ? 1 : 0
  description             = format("%s customer-managed key for encrypting SSM command output in S3", local.id)
  enable_key_rotation     = true
  deletion_window_in_days = 10
  tags                    = local.tags
}

resource "aws_kms_alias" "logs" {
  count         = var.create_s3_log_bucket ? 1 : 0
  name          = format("alias/%s", local.s3_log_bucket_name)
  target_key_id = aws_kms_key.logs[0].key_id
}

data "aws_iam_policy_document" "s3_log_bucket" {
  count = var.create_s3_log_bucket ? 1 : 0

  statement {
    sid    = "AllowAccountReadWriteAccess"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = [format("arn:%s:iam::%s:root", local.partition, local.account_id)]
    }
    actions = [
      "s3:GetBucketLocation",
      "s3:ListBucket",
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
    ]
    resources = [
      aws_s3_bucket.logs[0].arn,
      format("%s/*", aws_s3_bucket.logs[0].arn),
    ]
  }
}

resource "aws_s3_bucket" "logs" {
  count         = var.create_s3_log_bucket ? 1 : 0
  bucket        = local.s3_log_bucket_name
  force_destroy = false
  tags          = merge(local.tags, { "Name" = local.s3_log_bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "logs" {
  count  = var.create_s3_log_bucket ? 1 : 0
  bucket = aws_s3_bucket.logs[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logs" {
  count  = var.create_s3_log_bucket ? 1 : 0
  bucket = aws_s3_bucket.logs[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.logs[0].key_id
    }
  }
}

resource "aws_s3_bucket_public_access_block" "logs" {
  count                   = var.create_s3_log_bucket ? 1 : 0
  bucket                  = aws_s3_bucket.logs[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "logs" {
  count  = var.create_s3_log_bucket ? 1 : 0
  bucket = aws_s3_bucket.logs[0].id
  policy = data.aws_iam_policy_document.s3_log_bucket[0].json
}

# ------------------------------------------------------------------------------
# Scan maintenance window - target and AWS-RunPatchBaseline task
# ------------------------------------------------------------------------------
resource "aws_ssm_maintenance_window" "scan" {
  name                       = local.scan_window_name
  description                = "Weekly patch compliance scan of targets tagged with Patch Group=${var.scan_instance_tag_value}."
  schedule                   = var.scan_window_schedule
  duration                   = var.scan_window_duration_hours
  cutoff                     = var.scan_window_cutoff_hours
  allow_unassociated_targets = var.allow_unassociated_targets
  tags                       = local.tags
}

resource "aws_ssm_maintenance_window_target" "scan" {
  window_id     = aws_ssm_maintenance_window.scan.id
  resource_type = "INSTANCE"
  name          = format("%s-scan-target", local.id)

  targets {
    key    = format("tag:%s", var.scan_instance_tag_key)
    values = [var.scan_instance_tag_value]
  }
}

resource "aws_ssm_maintenance_window_task" "scan" {
  window_id        = aws_ssm_maintenance_window.scan.id
  task_type        = "RUN_COMMAND"
  task_arn         = "AWS-RunPatchBaseline"
  name             = format("%s-scan-task", local.id)
  priority         = 1
  service_role_arn = aws_iam_role.maintenance_window.arn
  max_concurrency  = var.max_concurrency
  max_errors       = var.max_errors

  targets {
    key    = "WindowTargetIds"
    values = [aws_ssm_maintenance_window_target.scan.id]
  }

  task_invocation_parameters {
    run_command_parameters {
      parameter {
        name   = "Operation"
        values = ["Scan"]
      }
      parameter {
        name   = "RebootOption"
        values = [var.scan_reboot_option]
      }

      timeout_seconds      = var.task_timeout_seconds
      service_role_arn     = aws_iam_role.maintenance_window.arn
      output_s3_bucket     = local.s3_log_bucket_id
      output_s3_key_prefix = var.s3_log_key_prefix

      dynamic "notification_config" {
        for_each = var.enable_sns_notifications ? toset([1]) : toset([])
        content {
          notification_arn    = aws_sns_topic.maintenance_window[0].arn
          notification_events = ["All"]
          notification_type   = "Command"
        }
      }

      dynamic "cloudwatch_config" {
        for_each = var.enable_cloudwatch_logs ? toset([1]) : toset([])
        content {
          cloudwatch_log_group_name = aws_cloudwatch_log_group.maintenance_window[0].name
          cloudwatch_output_enabled = true
        }
      }
    }
  }
}

# ------------------------------------------------------------------------------
# Install maintenance window - target and AWS-RunPatchBaseline task
# ------------------------------------------------------------------------------
resource "aws_ssm_maintenance_window" "install" {
  name                       = local.install_window_name
  description                = "Weekly patch installation on targets tagged with Patch Group=${var.install_instance_tag_value}."
  schedule                   = var.install_window_schedule
  duration                   = var.install_window_duration_hours
  cutoff                     = var.install_window_cutoff_hours
  allow_unassociated_targets = var.allow_unassociated_targets
  tags                       = local.tags
}

resource "aws_ssm_maintenance_window_target" "install" {
  window_id     = aws_ssm_maintenance_window.install.id
  resource_type = "INSTANCE"
  name          = format("%s-install-target", local.id)

  targets {
    key    = format("tag:%s", var.install_instance_tag_key)
    values = [var.install_instance_tag_value]
  }
}

resource "aws_ssm_maintenance_window_task" "install" {
  window_id        = aws_ssm_maintenance_window.install.id
  task_type        = "RUN_COMMAND"
  task_arn         = "AWS-RunPatchBaseline"
  name             = format("%s-install-task", local.id)
  priority         = 1
  service_role_arn = aws_iam_role.maintenance_window.arn
  max_concurrency  = var.max_concurrency
  max_errors       = var.max_errors

  targets {
    key    = "WindowTargetIds"
    values = [aws_ssm_maintenance_window_target.install.id]
  }

  task_invocation_parameters {
    run_command_parameters {
      parameter {
        name   = "Operation"
        values = ["Install"]
      }
      parameter {
        name   = "RebootOption"
        values = [var.reboot_option]
      }

      timeout_seconds      = var.task_timeout_seconds
      service_role_arn     = aws_iam_role.maintenance_window.arn
      output_s3_bucket     = local.s3_log_bucket_id
      output_s3_key_prefix = var.s3_log_key_prefix

      dynamic "notification_config" {
        for_each = var.enable_sns_notifications ? toset([1]) : toset([])
        content {
          notification_arn    = aws_sns_topic.maintenance_window[0].arn
          notification_events = ["All"]
          notification_type   = "Command"
        }
      }

      dynamic "cloudwatch_config" {
        for_each = var.enable_cloudwatch_logs ? toset([1]) : toset([])
        content {
          cloudwatch_log_group_name = aws_cloudwatch_log_group.maintenance_window[0].name
          cloudwatch_output_enabled = true
        }
      }
    }
  }
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

variable "notification_emails" {
  type        = list(string)
  default     = ["alerts@example.com"]
  description = "Email addresses to receive management activity alerts"
}

# ---------------------------------------------------------------------------
# KMS keys with automatic rotation
# ---------------------------------------------------------------------------
resource "aws_kms_key" "cloudtrail" {
  description             = "KMS key for CloudTrail log encryption"
  deletion_window_in_days = 30
  rotation_period_in_days = 365
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "kms-cloudtrail-policy"
    Statement = [
      {
        Sid    = "AllowCloudTrailEncryption"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey",
          "kms:Decrypt"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowAccountAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = "kms:*"
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_key" "sns" {
  description             = "KMS key for SNS topic encryption"
  deletion_window_in_days = 30
  rotation_period_in_days = 365
  enable_key_rotation     = true
}

# ---------------------------------------------------------------------------
# S3 bucket for CloudTrail logs
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "cloudtrail_logs" {
  bucket = "cloudtrail-monitor-management-event-logs-${data.aws_caller_identity.current.account_id}"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CloudTrailObjectAccess"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = "s3:PutObject"
        Resource = "arn:aws:s3:::cloudtrail-monitor-management-event-logs-${data.aws_caller_identity.current.account_id}/*"
      },
      {
        Sid    = "CloudTrailBucketAccess"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = [
          "s3:GetBucketLocation",
          "s3:ListBucket",
          "s3:GetBucketAcl"
        ]
        Resource = "arn:aws:s3:::cloudtrail-monitor-management-event-logs-${data.aws_caller_identity.current.account_id}"
      }
    ]
  })
}

resource "aws_s3_bucket_public_access_block" "cloudtrail_logs" {
  bucket                  = aws_s3_bucket.cloudtrail_logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.cloudtrail.id
    }
  }
}

# ---------------------------------------------------------------------------
# CloudWatch Logs group
# ---------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "cloudtrail" {
  name = "cloudtrail_to_cloudwatch_logs"
}

# ---------------------------------------------------------------------------
# IAM role for CloudTrail to assume when delivering to CloudWatch
# ---------------------------------------------------------------------------
resource "aws_iam_role" "cloudtrail_cloudwatch" {
  name = "cloudtrail-cloudwatch-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "cloudtrail_cloudwatch" {
  name = "cloudtrail-cloudwatch-policy"
  role = aws_iam_role.cloudtrail_cloudwatch.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups"
        ]
        Resource = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# Multi-region CloudTrail trail
# ---------------------------------------------------------------------------
resource "aws_cloudtrail" "monitor" {
  depends_on                    = [
    aws_s3_bucket.cloudtrail_logs,
    aws_kms_key.cloudtrail,
    aws_iam_role.cloudtrail_cloudwatch,
    aws_sns_topic.management_updates,
    aws_sns_topic_policy.management_updates,
    aws_cloudwatch_metric_alarm.security_group_changes,
    aws_cloudwatch_metric_alarm.iam_user_changes,
    aws_cloudwatch_metric_alarm.failed_console_logins,
    aws_cloudwatch_metric_alarm.iam_policy_attachment_changes,
    aws_cloudwatch_metric_alarm.iam_policy_changes,
    aws_cloudwatch_metric_alarm.iam_group_membership_changes,
    aws_cloudwatch_metric_alarm.iam_role_changes,
  ]
  name                          = "monitor_account_activities"
  s3_bucket_name                = aws_s3_bucket.cloudtrail_logs.id
  include_global_service_events = true
  is_multi_region_trail         = true
  enable_log_file_validation    = true
  kms_key_id                    = aws_kms_key.cloudtrail.arn
  cloud_watch_logs_group_arn   = "arn:aws:logs:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:log-group:cloudtrail_to_cloudwatch_logs:*"
  cloud_watch_logs_role_arn     = aws_iam_role.cloudtrail_cloudwatch.arn

  event_selector {
    include_management_events = true
    read_write_type          = "All"
  }
}

# ---------------------------------------------------------------------------
# SNS topic for management update alerts
# ---------------------------------------------------------------------------
resource "aws_sns_topic" "management_updates" {
  name              = "management-updates"
  kms_master_key_id = aws_kms_key.sns.id
}

resource "aws_sns_topic_policy" "management_updates" {
  arn = aws_sns_topic.management_updates.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "sns-policy-for-management-updates"
    Statement = [
      {
        Sid    = "allow-cloudwatch-publish"
        Effect = "Allow"
        Principal = {
          Service = "cloudwatch.amazonaws.com"
        }
        Action = [
          "sns:Publish"
        ]
        Resource = [
          aws_sns_topic.management_updates.arn
        ]
      },
      {
        Sid    = "allow-email-subscribe"
        Effect = "Allow"
        Principal = {
          AWS = "*"
        }
        Action = [
          "sns:Subscribe"
        ]
        Resource = [
          aws_sns_topic.management_updates.arn
        ]
        Condition = {
          StringEquals = {
            "sns:Protocol" = "email"
          }
        }
      }
    ]
  })
}

resource "aws_sns_topic_subscription" "management_updates" {
  count     = length(var.notification_emails)
  topic_arn = aws_sns_topic.management_updates.arn
  protocol  = "email"
  endpoint  = var.notification_emails[count.index]
}

# ---------------------------------------------------------------------------
# CloudWatch Logs metric filters and alarms
# Namespace: management_activities
# ---------------------------------------------------------------------------

locals {
  alarm_actions = [aws_sns_topic.management_updates.arn]
}

# 1. Security group changes
resource "aws_cloudwatch_log_metric_filter" "security_group_changes" {
  name           = "security-group-changes"
  pattern        = "{ ($.eventSource = \"ec2.amazonaws.com\") && (($.eventName = \"CreateSecurityGroup\") || ($.eventName = \"DeleteSecurityGroup\") || ($.eventName = \"ModifySecurityGroupAttributes\") || ($.eventName = \"AuthorizeSecurityGroupIngress\") || ($.eventName = \"RevokeSecurityGroupIngress\") || ($.eventName = \"AuthorizeSecurityGroupEgress\") || ($.eventName = \"RevokeSecurityGroupEgress\")) }"
  log_group_name = aws_cloudwatch_log_group.cloudtrail.name

  metric_transformation {
    name      = "SecurityGroupChanges"
    namespace = "management_activities"
    value     = "1"
  }
}

resource "aws_cloudwatch_metric_alarm" "security_group_changes" {
  alarm_name          = "security-group-changes-alarm"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = 1
  metric_name         = aws_cloudwatch_log_metric_filter.security_group_changes.metric_transformation[0].name
  namespace           = aws_cloudwatch_log_metric_filter.security_group_changes.metric_transformation[0].namespace
  period              = 60
  statistic           = "Sum"
  threshold           = 1
  alarm_actions       = local.alarm_actions
}

# 2. IAM user creation or deletion
resource "aws_cloudwatch_log_metric_filter" "iam_user_changes" {
  name           = "iam-user-changes"
  pattern        = "{ ($.eventSource = \"iam.amazonaws.com\") && (($.eventName = \"CreateUser\") || ($.eventName = \"DeleteUser\")) }"
  log_group_name = aws_cloudwatch_log_group.cloudtrail.name

  metric_transformation {
    name      = "IAMUserChanges"
    namespace = "management_activities"
    value     = "1"
  }
}

resource "aws_cloudwatch_metric_alarm" "iam_user_changes" {
  alarm_name          = "iam-user-changes-alarm"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = 1
  metric_name         = aws_cloudwatch_log_metric_filter.iam_user_changes.metric_transformation[0].name
  namespace           = aws_cloudwatch_log_metric_filter.iam_user_changes.metric_transformation[0].namespace
  period              = 60
  statistic           = "Sum"
  threshold           = 1
  alarm_actions       = local.alarm_actions
}

# 3. Failed console logins
resource "aws_cloudwatch_log_metric_filter" "failed_console_logins" {
  name           = "failed-console-logins"
  pattern        = "{ ($.eventName = \"ConsoleLogin\") && ($.responseElements.ConsoleLogin = \"Failure\") }"
  log_group_name = aws_cloudwatch_log_group.cloudtrail.name

  metric_transformation {
    name      = "FailedConsoleLogins"
    namespace = "management_activities"
    value     = "1"
  }
}

resource "aws_cloudwatch_metric_alarm" "failed_console_logins" {
  alarm_name          = "failed-console-logins-alarm"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = 1
  metric_name         = aws_cloudwatch_log_metric_filter.failed_console_logins.metric_transformation[0].name
  namespace           = aws_cloudwatch_log_metric_filter.failed_console_logins.metric_transformation[0].namespace
  period              = 60
  statistic           = "Sum"
  threshold           = 1
  alarm_actions       = local.alarm_actions
}

# 4. IAM group, role, and user policy changes
resource "aws_cloudwatch_log_metric_filter" "iam_policy_attachment_changes" {
  name           = "iam-policy-attachment-changes"
  pattern        = "{ ($.eventSource = \"iam.amazonaws.com\") && (($.eventName = \"AttachGroupPolicy\") || ($.eventName = \"DetachGroupPolicy\") || ($.eventName = \"AttachRolePolicy\") || ($.eventName = \"DetachRolePolicy\") || ($.eventName = \"AttachUserPolicy\") || ($.eventName = \"DetachUserPolicy\")) }"
  log_group_name = aws_cloudwatch_log_group.cloudtrail.name

  metric_transformation {
    name      = "IAMPolicyAttachmentChanges"
    namespace = "management_activities"
    value     = "1"
  }
}

resource "aws_cloudwatch_metric_alarm" "iam_policy_attachment_changes" {
  alarm_name          = "iam-policy-attachment-changes-alarm"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = 1
  metric_name         = aws_cloudwatch_log_metric_filter.iam_policy_attachment_changes.metric_transformation[0].name
  namespace           = aws_cloudwatch_log_metric_filter.iam_policy_attachment_changes.metric_transformation[0].namespace
  period              = 60
  statistic           = "Sum"
  threshold           = 1
  alarm_actions       = local.alarm_actions
}

# 5. IAM policy changes (create/delete)
resource "aws_cloudwatch_log_metric_filter" "iam_policy_changes" {
  name           = "iam-policy-changes"
  pattern        = "{ ($.eventSource = \"iam.amazonaws.com\") && (($.eventName = \"CreatePolicy\") || ($.eventName = \"DeletePolicy\")) }"
  log_group_name = aws_cloudwatch_log_group.cloudtrail.name

  metric_transformation {
    name      = "IAMPolicyChanges"
    namespace = "management_activities"
    value     = "1"
  }
}

resource "aws_cloudwatch_metric_alarm" "iam_policy_changes" {
  alarm_name          = "iam-policy-changes-alarm"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = 1
  metric_name         = aws_cloudwatch_log_metric_filter.iam_policy_changes.metric_transformation[0].name
  namespace           = aws_cloudwatch_log_metric_filter.iam_policy_changes.metric_transformation[0].namespace
  period              = 60
  statistic           = "Sum"
  threshold           = 1
  alarm_actions       = local.alarm_actions
}

# 6. Users being added to / removed from groups
resource "aws_cloudwatch_log_metric_filter" "iam_group_membership_changes" {
  name           = "iam-group-membership-changes"
  pattern        = "{ ($.eventSource = \"iam.amazonaws.com\") && (($.eventName = \"AddUserToGroup\") || ($.eventName = \"RemoveUserFromGroup\")) }"
  log_group_name = aws_cloudwatch_log_group.cloudtrail.name

  metric_transformation {
    name      = "IAMGroupMembershipChanges"
    namespace = "management_activities"
    value     = "1"
  }
}

resource "aws_cloudwatch_metric_alarm" "iam_group_membership_changes" {
  alarm_name          = "iam-group-membership-changes-alarm"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = 1
  metric_name         = aws_cloudwatch_log_metric_filter.iam_group_membership_changes.metric_transformation[0].name
  namespace           = aws_cloudwatch_log_metric_filter.iam_group_membership_changes.metric_transformation[0].namespace
  period              = 60
  statistic           = "Sum"
  threshold           = 1
  alarm_actions       = local.alarm_actions
}

# 7. IAM role creation or deletion
resource "aws_cloudwatch_log_metric_filter" "iam_role_changes" {
  name           = "iam-role-changes"
  pattern        = "{ ($.eventSource = \"iam.amazonaws.com\") && (($.eventName = \"CreateRole\") || ($.eventName = \"DeleteRole\")) }"
  log_group_name = aws_cloudwatch_log_group.cloudtrail.name

  metric_transformation {
    name      = "IAMRoleChanges"
    namespace = "management_activities"
    value     = "1"
  }
}

resource "aws_cloudwatch_metric_alarm" "iam_role_changes" {
  alarm_name          = "iam-role-changes-alarm"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = 1
  metric_name         = aws_cloudwatch_log_metric_filter.iam_role_changes.metric_transformation[0].name
  namespace           = aws_cloudwatch_log_metric_filter.iam_role_changes.metric_transformation[0].namespace
  period              = 60
  statistic           = "Sum"
  threshold           = 1
  alarm_actions       = local.alarm_actions
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------
variable "name_prefix" {
  description = "Optional prefix for the AWS Config managed rule name"
  type        = string
  default     = ""
}

variable "days_to_expiration" {
  description = "Number of days before an ACM certificate expiration triggers an evaluation"
  type        = number
  default     = 30
}

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------
locals {
  rule_name = var.name_prefix != "" ? "${var.name_prefix}acm-certificate-expiration-check" : "acm-certificate-expiration-check"
}

# ---------------------------------------------------------------------------
# AWS Config IAM Role for Configuration Recorder
# ---------------------------------------------------------------------------
resource "aws_iam_role" "config_recorder" {
  name               = "aws-config-recorder-role"
  assume_role_policy = data.aws_iam_policy_document.config_recorder_assume.json

  managed_policy_arns = ["arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWS_ConfigRole"]
}

data "aws_iam_policy_document" "config_recorder_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }
  }
}

# ---------------------------------------------------------------------------
# AWS Config IAM Role for Config Rules
# ---------------------------------------------------------------------------
resource "aws_iam_role" "config_rule" {
  name               = "aws-config-rule-role"
  assume_role_policy = data.aws_iam_policy_document.config_rule_assume.json

  managed_policy_arns = ["arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWS_ConfigRole"]
}

data "aws_iam_policy_document" "config_rule_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }
  }
}

# ---------------------------------------------------------------------------
# KMS Key for S3 Bucket Encryption
# ---------------------------------------------------------------------------
resource "aws_kms_key" "config" {
  description             = "KMS key for AWS Config S3 bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.config_kms_key.json
}

data "aws_iam_policy_document" "config_kms_key" {
  statement {
    sid    = "Enable IAM User Permissions"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "Allow Config Service to Use the Key"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }
    actions = [
      "kms:GenerateDataKey",
      "kms:Decrypt",
    ]
    resources = ["*"]
  }
}

# ---------------------------------------------------------------------------
# S3 Bucket for Config Delivery Channel
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "config" {
  bucket        = "aws-config-delivery-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.region}"
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "config" {
  bucket                  = aws_s3_bucket.config.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "config" {
  bucket = aws_s3_bucket.config.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.config.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_policy" "config" {
  bucket = aws_s3_bucket.config.id
  policy = data.aws_iam_policy_document.config_bucket.json
}

data "aws_iam_policy_document" "config_bucket" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }
    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.config.arn]
  }

  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.config.arn}/*"]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

# ---------------------------------------------------------------------------
# AWS Config Recorder
# ---------------------------------------------------------------------------
resource "aws_config_configuration_recorder" "main" {
  name     = "aws-config-recorder"
  role_arn = aws_iam_role.config_recorder.arn

  recording_group {
    all_supported                 = true
    include_global_resource_types = true
  }
}

# ---------------------------------------------------------------------------
# AWS Config Delivery Channel
# ---------------------------------------------------------------------------
resource "aws_config_delivery_channel" "main" {
  name           = "aws-config-delivery-channel"
  s3_bucket_name = aws_s3_bucket.config.id
  depends_on     = [aws_config_configuration_recorder.main]
}

# ---------------------------------------------------------------------------
# AWS Config Recorder Status (enabled by default)
# ---------------------------------------------------------------------------
resource "aws_config_configuration_recorder_status" "main" {
  name       = aws_config_configuration_recorder.main.name
  is_enabled = true
  depends_on = [aws_config_delivery_channel.main]
}

# ---------------------------------------------------------------------------
# AWS Config Managed Rule: acm-certificate-expiration-check
# ---------------------------------------------------------------------------
resource "aws_config_config_rule" "acm_expiration" {
  name        = local.rule_name
  description = "Checks whether ACM certificates in the account are close to expiring"

  source {
    owner             = "AWS"
    source_identifier = "ACM_CERTIFICATE_EXPIRATION_CHECK"
  }

  input_parameters = jsonencode({
    daysToExpiration = tostring(var.days_to_expiration)
  })

  depends_on = [aws_config_configuration_recorder_status.main]
}

# ---------------------------------------------------------------------------
# Data sources (static provider metadata)
# ---------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

resource "aws_cognito_user_pool" "this" {
  name = "fiap-hackathon-cognito-pool"

  username_attributes      = ["email"]
  auto_verified_attributes = ["email"]

  mfa_configuration = "OFF"

  schema {
    name                = "name"
    attribute_data_type = "String"
    required            = true
    mutable             = true
    string_attribute_constraints {
      min_length = 1
      max_length = 256
    }
  }

  password_policy {
    minimum_length    = 8
    require_lowercase = false
    require_numbers   = false
    require_symbols   = false
    require_uppercase = false
  }

  account_recovery_setting {
    recovery_mechanism {
      name     = "verified_email"
      priority = 1
    }
  }

  admin_create_user_config {
    allow_admin_create_user_only = false
  }

  email_configuration {
    email_sending_account = "COGNITO_DEFAULT"
  }

  verification_message_template {
    default_email_option = "CONFIRM_WITH_CODE"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_cognito_user_pool_client" "this" {
  name                                 = "cognito-pool-client"
  user_pool_id                         = aws_cognito_user_pool.this.id
  generate_secret                      = false
  explicit_auth_flows                  = ["ALLOW_USER_PASSWORD_AUTH", "ALLOW_ADMIN_USER_PASSWORD_AUTH", "ALLOW_REFRESH_TOKEN_AUTH"]
  prevent_user_existence_errors        = "ENABLED"
  enable_token_revocation              = true
  refresh_token_validity               = 30
  access_token_validity                = 60
  id_token_validity                    = 60
  token_validity_units {
    access_token    = "minutes"
    id_token        = "minutes"
    refresh_token   = "days"
  }
}

locals {
  tenant_id  = "221ca1d3-b3f2-4346-8abc-88f802495c7d"
  client_id  = "c8b9cf86-e2b4-4428-b356-14313412a4d1"
  issuer_url = "https://sts.windows.net/${local.tenant_id}/"
  # Thumbprint of the TLS certificate presented by sts.windows.net:443
  thumbprint = "F8AA7F1BF50F4F7F492FB70EBB6062D8B117ADCC"
}

# ---------------------------------------------------------------------------
# IAM OIDC identity provider for Azure AD
# ---------------------------------------------------------------------------
resource "aws_iam_openid_connect_provider" "azure_ad" {
  url             = local.issuer_url
  client_id_list  = [local.client_id]
  thumbprint_list = [local.thumbprint]
}

# ---------------------------------------------------------------------------
# IAM role for Sentinel function apps
# ---------------------------------------------------------------------------
resource "aws_iam_role" "sentinel_organizations_readonly" {
  name = "Sentinel-OIDC-Organizations-ReadOnly"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = aws_iam_openid_connect_provider.azure_ad.arn
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "sts.windows.net/${local.tenant_id}:aud" = local.client_id
          }
        }
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# Attach the AWS managed AWSOrganizationsReadOnlyAccess policy
# ---------------------------------------------------------------------------
resource "aws_iam_role_policy_attachment" "organizations_readonly" {
  role       = aws_iam_role.sentinel_organizations_readonly.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AWSOrganizationsReadOnlyAccess"
}

