resource "aws_iam_role_policy" "allow_all_clusters" {
  name   = "allow-all-clusters"
  role   = aws_iam_role.ec2_rds_role.id
  policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
