resource "aws_iam_role_policy" "deny_all_clusters" {
  name   = "deny-all-clusters"
  role   = aws_iam_role.ec2_rds_role.id
  policy = jsonencode({
    Version   = "2012-10-17"
    Statement = [
      {
        Effect   = "Deny"
        Action   = "rds:Add*"
        Resource = "arn:aws:rds:*:*:cluster:*"
      }
    ]
  })
}

variable "environment_name" {
  description = "Environment name used in the state bucket name"
  type        = string
  default     = "dev"
}

data "aws_caller_identity" "current" {}

# ---------------------------------------------------------------------------
# KMS key for the Terraform state bucket
# ---------------------------------------------------------------------------
resource "aws_kms_key" "state" {
  description             = "KMS key for Terraform state S3 bucket encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "key-state"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow S3 to use the key"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow DynamoDB to use the key"
        Effect = "Allow"
        Principal = {
          Service = "dynamodb.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
  tags = {
    Name = "near-frontend-terraform-state-kms"
  }
}

resource "aws_kms_alias" "state" {
  name          = "alias/near-frontend-terraform-state"
  target_key_id = aws_kms_key.state.key_id
}

# ---------------------------------------------------------------------------
# KMS key for the frontend S3 bucket
# ---------------------------------------------------------------------------
resource "aws_kms_key" "frontend" {
  description             = "KMS key for frontend S3 bucket encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "key-frontend"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow S3 to use the key"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
  tags = {
    Name = "s3-frontend-kms"
  }
}

resource "aws_kms_alias" "frontend" {
  name          = "alias/s3-frontend-nft-maker-v2"
  target_key_id = aws_kms_key.frontend.key_id
}

# ---------------------------------------------------------------------------
# Terraform state S3 bucket
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "state" {
  bucket = "near-frontend-${var.environment_name}-terraform-state-${data.aws_caller_identity.current.account_id}"

  force_destroy = false

  tags = {
    Name = "near-frontend-terraform-state"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.state.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

# ---------------------------------------------------------------------------
# DynamoDB table for state locking
# ---------------------------------------------------------------------------
resource "aws_dynamodb_table" "state_lock" {
  name           = "near-frontend-terraform-state"
  billing_mode   = "PROVISIONED"
  read_capacity  = 5
  write_capacity = 5
  hash_key       = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.state.arn
  }

  tags = {
    Name = "near-frontend-terraform-state"
  }
}

# ---------------------------------------------------------------------------
# Frontend S3 bucket
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "frontend" {
  bucket = "s3-frontend-nft-maker-v2-${data.aws_caller_identity.current.account_id}"

  force_destroy = false

  tags = {
    Name = "s3-frontend-nft-maker-v2"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.frontend.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_website_configuration" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  index_document {
    suffix = "index.html"
  }

  error_document {
    key = "index.html"
  }
}

resource "aws_s3_bucket_cors_configuration" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  cors_rule {
    allowed_headers = ["*"]
    allowed_methods = ["GET", "PUT", "POST", "DELETE"]
    allowed_origins = ["*"]
    expose_headers  = ["ETag"]
    max_age_seconds = 3600
  }
}

# ---------------------------------------------------------------------------
# CloudFront origin access identity
# ---------------------------------------------------------------------------
resource "aws_cloudfront_origin_access_identity" "main" {
  comment = "OAI for frontend S3 bucket"
}

# ---------------------------------------------------------------------------
# S3 bucket policy granting OAI read and list access
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_policy" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CloudFrontOAIReadList"
        Effect = "Allow"
        Principal = {
          AWS = aws_cloudfront_origin_access_identity.main.iam_arn
        }
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.frontend.arn,
          "${aws_s3_bucket.frontend.arn}/*"
        ]
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# WAFv2 web ACL (CloudFront-scoped)
# ---------------------------------------------------------------------------
resource "aws_wafv2_web_acl" "main" {
  name        = "near-frontend-waf"
  description = "WAF for CloudFront frontend"
  scope       = "CLOUDFRONT"

  default_action {
    allow {}
  }

  rule {
    name     = "AWS-AWSManagedRulesCommonRuleSet"
    priority = 0

    override_action {
      none {}
    }

    statement {
      managed_rule_group_statement {
        name        = "AWSManagedRulesCommonRuleSet"
        vendor_name = "AWS"
      }
    }

    visibility_config {
      sampled_requests_enabled   = true
      cloudwatch_metrics_enabled = true
      metric_name                = "AWSManagedRulesCommonRuleSet"
    }
  }

  visibility_config {
    sampled_requests_enabled   = true
    cloudwatch_metrics_enabled = true
    metric_name                = "near-frontend-waf"
  }

  tags = {
    Name = "near-frontend-waf"
  }
}

# ---------------------------------------------------------------------------
# CloudFront distribution
# ---------------------------------------------------------------------------
resource "aws_cloudfront_distribution" "main" {
  origin {
    domain_name = aws_s3_bucket.frontend.bucket_regional_domain_name
    origin_id   = "frontendS3Origin"

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.main.cloudfront_access_identity_path
    }
  }

  enabled             = true
  is_ipv6_enabled     = true
  comment             = "Frontend distribution for NFT Maker"
  default_root_object = "index.html"
  price_class         = "PriceClass_200"

  aliases = []

  default_cache_behavior {
    allowed_methods  = ["GET", "HEAD", "OPTIONS"]
    cached_methods   = ["GET", "HEAD", "OPTIONS"]
    target_origin_id = "frontendS3Origin"

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }

    viewer_protocol_policy = "redirect-to-https"
    min_ttl                = 0
    default_ttl            = 3600
    max_ttl                = 86400
    compress               = true
  }

  ordered_cache_behavior {
    path_pattern     = "/content/immutable/*"
    allowed_methods  = ["GET", "HEAD", "OPTIONS"]
    cached_methods   = ["GET", "HEAD", "OPTIONS"]
    target_origin_id = "frontendS3Origin"

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }

    viewer_protocol_policy = "redirect-to-https"
    min_ttl                = 0
    default_ttl            = 31536000
    max_ttl                = 31536000
    compress               = true
  }

  ordered_cache_behavior {
    path_pattern     = "/content/*"
    allowed_methods  = ["GET", "HEAD", "OPTIONS"]
    cached_methods   = ["GET", "HEAD", "OPTIONS"]
    target_origin_id = "frontendS3Origin"

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }

    viewer_protocol_policy = "redirect-to-https"
    min_ttl                = 0
    default_ttl            = 2592000
    max_ttl                = 2592000
    compress               = true
  }

  custom_error_response {
    error_code         = 403
    response_code      = 200
    response_page_path = "/index.html"
  }

  custom_error_response {
    error_code         = 404
    response_code      = 200
    response_page_path = "/index.html"
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }

  web_acl_id = aws_wafv2_web_acl.main.arn

  tags = {
    Name = "near-frontend-distribution"
  }

  # CloudFront distributions take time to deploy
  depends_on = [
    aws_s3_bucket.frontend,
    aws_cloudfront_origin_access_identity.main,
    aws_wafv2_web_acl.main
  ]
}

# Data sources for static provider metadata
data "aws_region" "current" {}

data "aws_availability_zones" "available" {}

# Variables (all with defaults so no inputs are required at apply time)
variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.1.0.0/16"
}

variable "base_name" {
  description = "Base name for all network resources"
  type        = string
  default     = "stackx-network"
}

variable "enable_database_subnets" {
  description = "Enable the optional database subnet tier with its own route table and DB subnet group"
  type        = bool
  default     = false
}

variable "enable_cache_subnets" {
  description = "Enable the optional cache subnet tier with its own route table and ElastiCache subnet group"
  type        = bool
  default     = false
}

variable "enable_internal_subnets" {
  description = "Enable the optional internal (no internet) subnet tier with its own route table"
  type        = bool
  default     = false
}

# Local computed values
locals {
  # Use the first 3 AZs from the region
  azs = slice(data.aws_availability_zones.available.names, 0, 3)

  # Required subnet CIDRs
  private_cidrs = [
    "10.1.0.0/18",
    "10.1.64.0/18",
    "10.1.128.0/18",
  ]
  public_cidrs = [
    "10.1.192.0/22",
    "10.1.196.0/22",
    "10.1.200.0/22",
  ]

  # Optional subnet CIDRs (only used when the corresponding enable_* variable is true)
  db_cidrs = [
    "10.1.204.0/24",
    "10.1.205.0/24",
    "10.1.206.0/24",
  ]
  cache_cidrs = [
    "10.1.208.0/24",
    "10.1.209.0/24",
    "10.1.210.0/24",
  ]
  internal_cidrs = [
    "10.1.212.0/24",
    "10.1.213.0/24",
    "10.1.214.0/24",
  ]

  eks_cluster = "stackx"
}

# =====================================================================
# VPC
# =====================================================================
resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr
  enable_dns_support               = true
  enable_dns_hostnames             = true
  assign_generated_ipv6_cidr_block = true

  tags = {
    Name                                        = "${var.base_name}-vpc"
    "kubernetes.io/cluster/${local.eks_cluster}" = "owned"
  }
}

# =====================================================================
# Internet Gateway + Egress-Only Internet Gateway
# =====================================================================
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.base_name}-igw"
  }
}

resource "aws_egress_only_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.base_name}-eigw"
  }
}

# =====================================================================
# Public Subnets (one per AZ, no auto-assign public IP)
# =====================================================================
resource "aws_subnet" "public" {
  count = 3

  vpc_id                          = aws_vpc.main.id
  cidr_block                      = local.public_cidrs[count.index]
  ipv6_cidr_block                 = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, count.index + 3)
  availability_zone               = local.azs[count.index]
  assign_ipv6_address_on_creation = true
  map_public_ip_on_launch         = false

  tags = {
    Name                    = "${var.base_name}-public-${count.index + 1}"
    "kubernetes.io/role/elb" = "1"
    "karpenter:managed"     = "true"
  }
}

# =====================================================================
# Private Subnets (one per AZ)
# =====================================================================
resource "aws_subnet" "private" {
  count = 3

  vpc_id                          = aws_vpc.main.id
  cidr_block                      = local.private_cidrs[count.index]
  ipv6_cidr_block                 = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, count.index)
  availability_zone               = local.azs[count.index]
  assign_ipv6_address_on_creation = true

  tags = {
    Name                    = "${var.base_name}-private-${count.index + 1}"
    "kubernetes.io/role/elb" = "1"
    "karpenter:managed"     = "true"
  }
}

# =====================================================================
# Public Route Table (shared across all public subnets)
# =====================================================================
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.base_name}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# =====================================================================
# Elastic IPs for NAT Gateways
# =====================================================================
resource "aws_eip" "nat" {
  count = 3

  domain = "vpc"

  tags = {
    Name = "${var.base_name}-nat-eip-${count.index + 1}"
  }
}

# =====================================================================
# NAT Gateways (one per AZ, placed in the public subnet of that zone)
# =====================================================================
resource "aws_nat_gateway" "main" {
  count = 3

  subnet_id     = aws_subnet.public[count.index].id
  allocation_id = aws_eip.nat[count.index].allocation_id

  tags = {
    Name = "${var.base_name}-nat-${count.index + 1}"
  }
}

# =====================================================================
# Private Route Tables (one per private subnet, each with its own NAT)
# =====================================================================
resource "aws_route_table" "private" {
  count = 3

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }

  route {
    ipv6_cidr_block        = "::/0"
    egress_only_gateway_id = aws_egress_only_internet_gateway.main.id
  }

  tags = {
    Name = "${var.base_name}-private-rt-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# =====================================================================
# S3 VPC Gateway Endpoint (associated with all private route tables)
# =====================================================================
resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id

  tags = {
    Name = "${var.base_name}-s3-endpoint"
  }
}

# =====================================================================
# OPTIONAL: Database Subnet Tier (disabled by default)
# =====================================================================
resource "aws_subnet" "database" {
  count = var.enable_database_subnets ? 3 : 0

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.db_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = {
    Name = "${var.base_name}-db-${count.index + 1}"
  }
}

resource "aws_route_table" "database" {
  count = var.enable_database_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  # No default routes – database tier has no internet access

  tags = {
    Name = "${var.base_name}-db-rt"
  }
}

resource "aws_route_table_association" "database" {
  count = var.enable_database_subnets ? 3 : 0

  subnet_id      = aws_subnet.database[count.index].id
  route_table_id = aws_route_table.database[0].id
}

resource "aws_db_subnet_group" "main" {
  count = var.enable_database_subnets ? 1 : 0

  name       = "${var.base_name}-db-subnet-group"
  subnet_ids = aws_subnet.database[*].id

  tags = {
    Name = "${var.base_name}-db-subnet-group"
  }
}

# =====================================================================
# OPTIONAL: Cache Subnet Tier (disabled by default)
# =====================================================================
resource "aws_subnet" "cache" {
  count = var.enable_cache_subnets ? 3 : 0

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.cache_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = {
    Name = "${var.base_name}-cache-${count.index + 1}"
  }
}

resource "aws_route_table" "cache" {
  count = var.enable_cache_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  # No default routes – cache tier has no internet access

  tags = {
    Name = "${var.base_name}-cache-rt"
  }
}

resource "aws_route_table_association" "cache" {
  count = var.enable_cache_subnets ? 3 : 0

  subnet_id      = aws_subnet.cache[count.index].id
  route_table_id = aws_route_table.cache[0].id
}

resource "aws_elasticache_subnet_group" "main" {
  count = var.enable_cache_subnets ? 1 : 0

  name       = "${var.base_name}-cache-subnet-group"
  subnet_ids = aws_subnet.cache[*].id

  tags = {
    Name = "${var.base_name}-cache-subnet-group"
  }
}

# =====================================================================
# OPTIONAL: Internal (no internet) Subnet Tier (disabled by default)
# =====================================================================
resource "aws_subnet" "internal" {
  count = var.enable_internal_subnets ? 3 : 0

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.internal_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = {
    Name = "${var.base_name}-internal-${count.index + 1}"
  }
}

resource "aws_route_table" "internal" {
  count = var.enable_internal_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  # No default routes – truly isolated tier

  tags = {
    Name = "${var.base_name}-internal-rt"
  }
}

resource "aws_route_table_association" "internal" {
  count = var.enable_internal_subnets ? 3 : 0

  subnet_id      = aws_subnet.internal[count.index].id
  route_table_id = aws_route_table.internal[0].id
}

# ------------------------------------------------------------------------------
# Benchmark Weather Data Lake - Glue + Step Functions scheduled pipeline
# ------------------------------------------------------------------------------

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# ------------------------------------------------------------------------------
# Variables (placeholders passed to the Glue jobs by the orchestrator)
# ------------------------------------------------------------------------------

variable "api_key_placeholder" {
  type        = string
  description = "Placeholder API key passed to the extraction Glue job."
  default     = "placeholder_api_key"
}

variable "translation_key_placeholder" {
  type        = string
  description = "Placeholder translation key passed to the transformation Glue job."
  default     = "placeholder_translation_key"
}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.region

  # Six data lake buckets, each named <prefix>-<aws account id>
  bucket_names = {
    artefacts = "benchmark-glue-artefacts-${local.account_id}"
    staging   = "benchmark-datalake-staging-${local.account_id}"
    bronze    = "benchmark-datalake-bronze-${local.account_id}"
    silver    = "benchmark-datalake-silver-${local.account_id}"
    gold      = "benchmark-datalake-gold-${local.account_id}"
    logs      = "benchmark-datalake-logs-${local.account_id}"
  }

  artefacts_bucket = local.bucket_names["artefacts"]
  staging_bucket   = local.bucket_names["staging"]
  bronze_bucket    = local.bucket_names["bronze"]
  silver_bucket    = local.bucket_names["silver"]
  logs_bucket      = local.bucket_names["logs"]

  # Bucket ARNs for IAM policies
  bucket_arns     = [for name in values(local.bucket_names) : "arn:aws:s3:::${name}"]
  bucket_obj_arns = [for name in values(local.bucket_names) : "arn:aws:s3:::${name}/*"]

  glue_job_name_extrai     = "glue-job-extrai-dados"
  glue_job_name_transforma = "glue-job-transforma-dados"

  kms_key_alias = "alias/benchmark-datalake-key"

  # Temporary files for Glue jobs live in the logs bucket.
  logs_bucket_path = "s3://${local.logs_bucket}"

  # Object keys inside the artefacts bucket that mirror the local glueClima folder.
  artefacts_prefix       = "glueClima"
  script_extrai_path     = "s3://${local.artefacts_bucket}/${local.artefacts_prefix}/extraiDados.py"
  script_transforma_path = "s3://${local.artefacts_bucket}/${local.artefacts_prefix}/transformaDados.py"
  lib_zip_path           = "s3://${local.artefacts_bucket}/${local.artefacts_prefix}/lib.zip"
  weather_utils_path     = "s3://${local.artefacts_bucket}/${local.artefacts_prefix}/weather_utils.py"
}

# ------------------------------------------------------------------------------
# KMS - shared rotating customer managed key used by the data lake
# ------------------------------------------------------------------------------

resource "aws_kms_key" "datalake" {
  description             = "Shared CMK used to encrypt the benchmark weather data lake (S3, Athena)."
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = {
    Name = "benchmark-datalake-key"
  }
}

resource "aws_kms_alias" "datalake" {
  name          = local.kms_key_alias
  target_key_id = aws_kms_key.datalake.id
}

# ------------------------------------------------------------------------------
# S3 - six data lake buckets
# ------------------------------------------------------------------------------

resource "aws_s3_bucket" "datalake" {
  for_each = local.bucket_names
  bucket   = each.value

  tags = {
    Name = each.key
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Versioning is enabled for artefacts, bronze, silver and gold buckets.
resource "aws_s3_bucket_versioning" "versioned" {
  for_each = toset(["artefacts", "bronze", "silver", "gold"])
  bucket   = aws_s3_bucket.datalake[each.key].id

  versioning_configuration {
    status = "Enabled"
  }
}

# Every bucket blocks all public access.
resource "aws_s3_bucket_public_access_block" "datalake" {
  for_each = aws_s3_bucket.datalake
  bucket   = each.value.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Every bucket uses default SSE-KMS encryption with the shared CMK.
resource "aws_s3_bucket_server_side_encryption_configuration" "datalake" {
  for_each = aws_s3_bucket.datalake
  bucket   = each.value.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.datalake.arn
    }
  }
}

# ------------------------------------------------------------------------------
# S3 - upload the Glue job scripts from the local glueClima folder
# ------------------------------------------------------------------------------

resource "aws_s3_object" "extrai_dados_script" {
  bucket = aws_s3_bucket.datalake["artefacts"].id
  key    = "${local.artefacts_prefix}/extraiDados.py"
  source = "${path.module}/glueClima/extraiDados.py"
  etag   = filemd5("${path.module}/glueClima/extraiDados.py")
}

resource "aws_s3_object" "transforma_dados_script" {
  bucket = aws_s3_bucket.datalake["artefacts"].id
  key    = "${local.artefacts_prefix}/transformaDados.py"
  source = "${path.module}/glueClima/transformaDados.py"
  etag   = filemd5("${path.module}/glueClima/transformaDados.py")
}

resource "aws_s3_object" "lib_zip" {
  bucket = aws_s3_bucket.datalake["artefacts"].id
  key    = "${local.artefacts_prefix}/lib.zip"
  source = "${path.module}/glueClima/lib.zip"
  etag   = filemd5("${path.module}/glueClima/lib.zip")
}

resource "aws_s3_object" "weather_utils" {
  bucket = aws_s3_bucket.datalake["artefacts"].id
  key    = "${local.artefacts_prefix}/weather_utils.py"
  source = "${path.module}/glueClima/weather_utils.py"
  etag   = filemd5("${path.module}/glueClima/weather_utils.py")
}

# ------------------------------------------------------------------------------
# Athena - silver database backed by the silver bucket, encrypted with the CMK
# ------------------------------------------------------------------------------

resource "aws_athena_database" "silver" {
  name   = "silver"
  bucket = aws_s3_bucket.datalake["silver"].id

  encryption_configuration {
    encryption_option = "SSE_KMS"
    kms_key           = aws_kms_key.datalake.arn
  }
}

# ------------------------------------------------------------------------------
# IAM - Glue service role
# ------------------------------------------------------------------------------

resource "aws_iam_role" "glue" {
  name        = "benchmark-glue-service-role"
  description = "Service role used by the benchmark weather data lake Glue jobs."
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Action    = "sts:AssumeRole"
      Principal = { Service = "glue.amazonaws.com" }
    }]
  })

  tags = {
    Name = "benchmark-glue-service-role"
  }
}

resource "aws_iam_policy" "glue" {
  name        = "benchmark-glue-policy"
  description = "Least-privilege policy for the benchmark weather data lake Glue service role."
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3ListDatalakeBuckets"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetBucketLocation",
          "s3:GetBucketEncryption",
          "s3:GetBucketVersioning",
        ]
        Resource = local.bucket_arns
      },
      {
        Sid    = "S3ObjectDatalakeBuckets"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:DeleteObjectVersion",
        ]
        Resource = local.bucket_obj_arns
      },
      {
        Sid    = "KMSDatalakeKey"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:ReEncryptFrom",
          "kms:ReEncryptTo",
          "kms:DescribeKey",
        ]
        Resource = [aws_kms_key.datalake.arn]
      },
      {
        Sid    = "GlueDataCatalog"
        Effect = "Allow"
        Action = [
          "glue:BatchCreatePartition",
          "glue:CreateConnection",
          "glue:CreateDatabase",
          "glue:CreatePartition",
          "glue:CreateTable",
          "glue:DeleteConnection",
          "glue:DeleteDatabase",
          "glue:DeletePartition",
          "glue:DeleteTable",
          "glue:GetConnection",
          "glue:GetConnections",
          "glue:GetDatabase",
          "glue:GetDatabases",
          "glue:GetPartition",
          "glue:GetPartitions",
          "glue:GetTable",
          "glue:GetTables",
          "glue:GetUserDefinedFunction",
          "glue:GetUserDefinedFunctions",
          "glue:SearchTables",
          "glue:UpdateConnection",
          "glue:UpdateDatabase",
          "glue:UpdatePartition",
          "glue:UpdateTable",
        ]
        Resource = ["*"]
      },
      {
        Sid      = "CloudWatchMetrics"
        Effect   = "Allow"
        Action   = ["cloudwatch:PutMetricData"]
        Resource = ["*"]
      },
      {
        Sid    = "CloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
        ]
        Resource = [
          "arn:aws:logs:${local.region}:${local.account_id}:log-group:/aws-glue/*",
          "arn:aws:logs:${local.region}:${local.account_id}:log-group:/aws-glue/*:log-stream:*",
          "arn:aws:logs:${local.region}:${local.account_id}:log-group:/aws/glue/*",
          "arn:aws:logs:${local.region}:${local.account_id}:log-group:/aws/glue/*:log-stream:*",
        ]
      },
      {
        Sid      = "SecretsManagerRead"
        Effect   = "Allow"
        Action   = ["secretsmanager:GetSecretValue"]
        Resource = ["*"]
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "glue" {
  role       = aws_iam_role.glue.name
  policy_arn = aws_iam_policy.glue.arn
}

# ------------------------------------------------------------------------------
# Glue - two PySpark 4.0 jobs
# ------------------------------------------------------------------------------

resource "aws_glue_job" "extrai_dados" {
  name        = local.glue_job_name_extrai
  role_arn    = aws_iam_role.glue.arn
  description = "Extracts weather data for a city and writes it into the staging bucket."

  glue_version      = "4.0"
  worker_type       = "G.1X"
  number_of_workers = 20
  max_retries       = 0
  timeout           = 2880

  execution_property {
    max_concurrent_runs = 2
  }

  command {
    name            = "glueetl"
    script_location = local.script_extrai_path
    python_version  = "3"
  }

  default_arguments = {
    "--job-language" = "python"
    "--TempDir"      = "${local.logs_bucket_path}/glue-temp-dir/${local.glue_job_name_extrai}"
  }

  tags = {
    Name = local.glue_job_name_extrai
  }
}

resource "aws_glue_job" "transforma_dados" {
  name        = local.glue_job_name_transforma
  role_arn    = aws_iam_role.glue.arn
  description = "Transforms staging data into the bronze and silver layers using the Iceberg format."

  glue_version      = "4.0"
  worker_type       = "G.1X"
  number_of_workers = 20
  max_retries       = 0
  timeout           = 2880

  execution_property {
    max_concurrent_runs = 2
  }

  command {
    name            = "glueetl"
    script_location = local.script_transforma_path
    python_version  = "3"
  }

  default_arguments = {
    "--job-language"         = "python"
    "--TempDir"              = "${local.logs_bucket_path}/glue-temp-dir/${local.glue_job_name_transforma}"
    "--extra-py-files"       = "${local.lib_zip_path},${local.weather_utils_path}"
    "--datalake.formats"     = "iceberg"
    "--iceberg.catalog-type" = "glue"
  }

  tags = {
    Name = local.glue_job_name_transforma
  }
}

# ------------------------------------------------------------------------------
# Step Functions - orchestrate extraction then transformation
# ------------------------------------------------------------------------------

resource "aws_iam_role" "step_functions" {
  name        = "benchmark-step-functions-role"
  description = "Allows the benchmark weather data lake state machine to run its Glue jobs."
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Action    = "sts:AssumeRole"
      Principal = { Service = "states.amazonaws.com" }
    }]
  })

  tags = {
    Name = "benchmark-step-functions-role"
  }
}

resource "aws_iam_policy" "step_functions" {
  name        = "benchmark-step-functions-policy"
  description = "Allows the benchmark weather data lake state machine to start and monitor only its own Glue jobs."
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "StartAndMonitorGlueJobs"
        Effect = "Allow"
        Action = [
          "glue:StartJobRun",
          "glue:StopJobRun",
          "glue:GetJobRun",
          "glue:GetJobRuns",
          "glue:BatchStopJobRun",
        ]
        Resource = [
          "arn:aws:glue:${local.region}:${local.account_id}:job/${local.glue_job_name_extrai}",
          "arn:aws:glue:${local.region}:${local.account_id}:job/${local.glue_job_name_transforma}",
        ]
      },
      {
        Sid    = "EventBridgeGlueWaiterRule"
        Effect = "Allow"
        Action = [
          "events:DescribeRule",
          "events:ListTargetsByRule",
          "events:PutRule",
          "events:PutTargets",
        ]
        Resource = ["arn:aws:events:${local.region}:${local.account_id}:rule/StepFunctionsGetEventsForGlueJobsRule"]
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "step_functions" {
  role       = aws_iam_role.step_functions.name
  policy_arn = aws_iam_policy.step_functions.arn
}

resource "aws_sfn_state_machine" "weather_pipeline" {
  name     = "benchmark-weather-datalake-pipeline"
  role_arn = aws_iam_role.step_functions.arn

  definition = jsonencode({
    Comment = "Weather data lake pipeline: extract weather data for Sao Paulo into staging, then transform it into the bronze and silver layers."
    StartAt = "ExtrairDados"
    States = {
      ExtrairDados = {
        Type     = "Task"
        Resource = "arn:aws:states:::glue:startJobRun.sync"
        Parameters = {
          JobName = local.glue_job_name_extrai
          Arguments = {
            city           = "Sao Paulo"
            bucket_staging = local.staging_bucket
            api_key        = var.api_key_placeholder
          }
        }
        Next = "TransformaDados"
      }
      TransformaDados = {
        Type     = "Task"
        Resource = "arn:aws:states:::glue:startJobRun.sync"
        Parameters = {
          JobName = local.glue_job_name_transforma
          Arguments = {
            bucket_staging  = local.staging_bucket
            bucket_bronze   = local.bronze_bucket
            bucket_silver   = local.silver_bucket
            translation_key = var.translation_key_placeholder
          }
        }
        End = true
      }
    }
  })

  tags = {
    Name = "benchmark-weather-datalake-pipeline"
  }
}

# ------------------------------------------------------------------------------
# EventBridge - hourly schedule that triggers the state machine
# ------------------------------------------------------------------------------

resource "aws_iam_role" "eventbridge" {
  name        = "benchmark-eventbridge-scheduler-role"
  description = "Allows EventBridge to start the benchmark weather data lake state machine."
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Action    = "sts:AssumeRole"
      Principal = { Service = "events.amazonaws.com" }
    }]
  })

  tags = {
    Name = "benchmark-eventbridge-scheduler-role"
  }
}

resource "aws_iam_policy" "eventbridge" {
  name        = "benchmark-eventbridge-scheduler-policy"
  description = "Allows EventBridge to start the benchmark weather data lake state machine execution."
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "StartStateMachine"
        Effect   = "Allow"
        Action   = ["states:StartExecution"]
        Resource = [aws_sfn_state_machine.weather_pipeline.arn]
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eventbridge" {
  role       = aws_iam_role.eventbridge.name
  policy_arn = aws_iam_policy.eventbridge.arn
}

resource "aws_cloudwatch_event_rule" "hourly" {
  name                = "benchmark-weather-datalake-hourly"
  description         = "Triggers the benchmark weather data lake state machine every hour."
  schedule_expression = "rate(1 hour)"

  tags = {
    Name = "benchmark-weather-datalake-hourly"
  }
}

resource "aws_cloudwatch_event_target" "state_machine" {
  rule      = aws_cloudwatch_event_rule.hourly.name
  target_id = "benchmark-weather-datalake-sfn"
  arn       = aws_sfn_state_machine.weather_pipeline.arn
  role_arn  = aws_iam_role.eventbridge.arn
}

terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ---------------------------------------------------------------------------
# Data sources
# ---------------------------------------------------------------------------
data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------
variable "github_repo" {
  description = "GitHub repository in '<owner>/<repo>' format that feeds the pipeline source stage."
  type        = string
  default     = "example-org/example-website"
}

variable "github_branch" {
  description = "GitHub branch that triggers the pipeline."
  type        = string
  default     = "master"
}

variable "codestar_connection_arn" {
  description = "ARN of a CodeStar connections connection. When supplied it is used instead of the GitHub OAuth token + webhook."
  type        = string
  default     = ""
}

variable "site_invalidation_flag" {
  description = "Flag passed to the build project indicating whether a CloudFront invalidation should be created after deployment."
  type        = bool
  default     = true
}

variable "codebuild_image" {
  description = "CodeBuild managed image used to build the static site."
  type        = string
  default     = "aws/codebuild/amazonlinux2-x86_64-standard:5.0"
}

variable "s3_target_key_deletion_window" {
  description = "Deletion window (days) for the customer managed KMS key."
  type        = number
  default     = 30
}

variable "enable_pipeline_notifications" {
  description = "Whether to create an SNS topic and deliver CodePipeline notifications to it."
  type        = bool
  default     = false
}

variable "enable_artifact_access_logging" {
  description = "Whether to enable S3 server access logging for the pipeline artifact bucket."
  type        = bool
  default     = false
}

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------
locals {
  account_id          = data.aws_caller_identity.current.account_id
  region              = data.aws_region.current.name
  partition           = data.aws_partition.current.partition
  target_bucket_name  = "benchmark-cicd-target-${local.account_id}"
  artifact_bucket     = "benchmark-cicd-artifacts-${local.account_id}"
  logging_bucket_name = "benchmark-cicd-artifact-logs-${local.account_id}"
  codebuild_name      = "benchmark-cicd-site-build"
  codebuild_log_group = "/aws/codebuild/${local.codebuild_name}"

  common_tags = {
    "purpose" = "benchmark-cicd"
  }

  buildspec = <<EOT
version: 0.2

phases:
  build:
    commands:
      - echo "Building static website and publishing it to the target bucket"
      - aws s3 sync . s3://$${TARGET_BUCKET} --delete --exclude ".git/*"
      - |
        if [ "$${INVALIDATION_FLAG}" = "true" ]; then
          aws cloudfront create-invalidation --distribution-id "$${CLOUDFRONT_DISTRIBUTION_ID}" --paths "/*"
        fi
EOT
}

# ---------------------------------------------------------------------------
# KMS key shared by both buckets and the pipeline
# ---------------------------------------------------------------------------
resource "aws_kms_key" "pipeline" {
  description             = "Customer managed key used to encrypt pipeline buckets, artifacts and SSM parameters"
  deletion_window_in_days = var.s3_target_key_deletion_window
  enable_key_rotation     = true
  tags                    = local.common_tags

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowRootAccountAdministration"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowCodeBuildAndCodePipeline"
        Effect = "Allow"
        Principal = {
          AWS = [
            aws_iam_role.codebuild.arn,
            aws_iam_role.codepipeline.arn,
          ]
        }
        Action = [
          "kms:Decrypt",
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:ReEncryptFrom",
          "kms:ReEncryptTo",
          "kms:DescribeKey",
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowCloudFrontOriginAccess"
        Effect = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "AWS:SourceArn" = aws_cloudfront_distribution.site.arn
          }
        }
      },
    ]
  })
}

resource "aws_kms_alias" "pipeline" {
  name          = "alias/benchmark-cicd-pipeline"
  target_key_id = aws_kms_key.pipeline.key_id
}

# ---------------------------------------------------------------------------
# S3 buckets
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "target" {
  bucket = local.target_bucket_name
  tags   = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "target" {
  bucket                  = aws_s3_bucket.target.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "target" {
  bucket = aws_s3_bucket.target.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.pipeline.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket" "artifacts" {
  bucket = local.artifact_bucket
  tags   = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "artifacts" {
  bucket                  = aws_s3_bucket.artifacts.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.pipeline.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# Deny any request to the artifact bucket that is not made over TLS.
data "aws_iam_policy_document" "artifacts_tls" {
  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"
    principals {
      type        = "*"
      identifiers = ["*"]
    }
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.artifacts.arn,
      "${aws_s3_bucket.artifacts.arn}/*",
    ]
    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id
  policy = data.aws_iam_policy_document.artifacts_tls.json
}

# Allow CloudFront (via the OAC) to read objects from the target bucket.
data "aws_iam_policy_document" "target_cloudfront" {
  statement {
    sid    = "AllowCloudFrontOriginAccess"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudfront.amazonaws.com"]
    }
    actions   = ["s3:GetObject"]
    resources = ["${aws_s3_bucket.target.arn}/*"]
    condition {
      test     = "StringEquals"
      variable = "AWS:SourceArn"
      values   = [aws_cloudfront_distribution.site.arn]
    }
  }
}

resource "aws_s3_bucket_policy" "target_cloudfront" {
  bucket = aws_s3_bucket.target.id
  policy = data.aws_iam_policy_document.target_cloudfront.json
}

# Optional access logging for the artifact bucket (off by default).
resource "aws_s3_bucket" "artifact_logs" {
  count  = var.enable_artifact_access_logging ? 1 : 0
  bucket = local.logging_bucket_name
  tags   = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "artifact_logs" {
  count                   = var.enable_artifact_access_logging ? 1 : 0
  bucket                  = aws_s3_bucket.artifact_logs[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifact_logs" {
  count  = var.enable_artifact_access_logging ? 1 : 0
  bucket = aws_s3_bucket.artifact_logs[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.pipeline.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_logging" "artifacts" {
  count         = var.enable_artifact_access_logging ? 1 : 0
  bucket        = aws_s3_bucket.artifacts.id
  target_bucket = aws_s3_bucket.artifact_logs[0].id
  target_prefix = "artifact-logs/"
}

# ---------------------------------------------------------------------------
# WAF protecting the CloudFront distribution
# ---------------------------------------------------------------------------
resource "aws_wafv2_web_acl" "site" {
  name        = "benchmark-cicd-site-waf"
  description = "Web ACL protecting the benchmark static website distribution"
  scope       = "CLOUDFRONT"
  tags        = local.common_tags

  default_action {
    allow {}
  }

  rule {
    name     = "AWSManagedRulesCommonRuleSet"
    priority = 1

    override_action {
      none {}
    }

    statement {
      managed_rule_group_statement {
        name        = "AWSManagedRulesCommonRuleSet"
        vendor_name = "AWS"
      }
    }

    visibility_config {
      cloudwatch_metrics_enabled = true
      metric_name                = "benchmark-cicd-waf-common"
      sampled_requests_enabled   = true
    }
  }

  visibility_config {
    cloudwatch_metrics_enabled = true
    metric_name                = "benchmark-cicd-waf"
    sampled_requests_enabled   = true
  }
}

# ---------------------------------------------------------------------------
# CloudFront distribution
# ---------------------------------------------------------------------------
resource "aws_cloudfront_origin_access_control" "site" {
  name                              = "benchmark-cicd-site-oac"
  description                       = "Origin access control for the benchmark static site distribution"
  origin_access_control_origin_type = "s3"
  signing_behavior                  = "always"
  signing_protocol                  = "sigv4"
}

resource "aws_cloudfront_distribution" "site" {
  enabled             = true
  is_ipv6_enabled     = true
  comment             = "Distribution for the benchmark static website"
  default_root_object = "index.html"
  price_class         = "PriceClass_100"
  wait_for_deployment = false
  web_acl_id          = aws_wafv2_web_acl.site.arn
  tags                = local.common_tags

  origin {
    domain_name              = "${local.target_bucket_name}.s3.${local.region}.amazonaws.com"
    origin_id                = "benchmark-cicd-site-origin"
    origin_access_control_id = aws_cloudfront_origin_access_control.site.id
  }

  default_cache_behavior {
    target_origin_id       = "benchmark-cicd-site-origin"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods        = ["GET", "HEAD", "OPTIONS"]
    cached_methods         = ["GET", "HEAD"]
    compress               = true

    forwarded_values {
      query_string = false

      cookies {
        forward = "none"
      }
    }

    min_ttl     = 0
    default_ttl = 3600
    max_ttl     = 86400
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }
}

# ---------------------------------------------------------------------------
# IAM - CodeBuild
# ---------------------------------------------------------------------------
resource "aws_iam_role" "codebuild" {
  name = "benchmark-cicd-codebuild"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      },
    ]
  })
  tags = local.common_tags
}

data "aws_iam_policy_document" "codebuild" {
  statement {
    sid    = "AllowCodeBuildLogs"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]
    resources = [
      "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:${local.codebuild_log_group}",
      "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:${local.codebuild_log_group}:log-stream:*",
    ]
  }

  statement {
    sid    = "AllowBucketAccess"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:GetBucketLocation",
      "s3:ListBucket",
      "s3:AbortMultipartUpload",
    ]
    resources = [
      aws_s3_bucket.target.arn,
      "${aws_s3_bucket.target.arn}/*",
      aws_s3_bucket.artifacts.arn,
      "${aws_s3_bucket.artifacts.arn}/*",
    ]
  }

  statement {
    sid    = "AllowKMSKey"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
      "kms:DescribeKey",
    ]
    resources = [aws_kms_key.pipeline.arn]
  }

  statement {
    sid    = "AllowCloudFrontInvalidation"
    effect = "Allow"
    actions = [
      "cloudfront:CreateInvalidation",
      "cloudfront:GetInvalidation",
    ]
    resources = [aws_cloudfront_distribution.site.arn]
  }

  dynamic "statement" {
    for_each = var.codestar_connection_arn == "" ? [1] : []
    content {
      sid    = "AllowSSMParameters"
      effect = "Allow"
      actions = [
        "ssm:GetParameter",
      ]
      resources = [
        aws_ssm_parameter.github_oauth_token[0].arn,
        aws_ssm_parameter.github_webhook_secret[0].arn,
      ]
    }
  }
}

resource "aws_iam_policy" "codebuild" {
  name   = "benchmark-cicd-codebuild"
  policy = data.aws_iam_policy_document.codebuild.json
}

resource "aws_iam_role_policy_attachment" "codebuild" {
  role       = aws_iam_role.codebuild.name
  policy_arn = aws_iam_policy.codebuild.arn
}

# ---------------------------------------------------------------------------
# CodeBuild project
# ---------------------------------------------------------------------------
resource "aws_codebuild_project" "site" {
  name          = local.codebuild_name
  description   = "Builds the static website and publishes it to the target bucket"
  service_role  = aws_iam_role.codebuild.arn
  build_timeout = 5
  tags          = local.common_tags

  artifacts {
    type = "CODEPIPELINE"
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = var.codebuild_image
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"

    environment_variable {
      name  = "TARGET_BUCKET"
      value = local.target_bucket_name
      type  = "PLAINTEXT"
    }

    environment_variable {
      name  = "CLOUDFRONT_DISTRIBUTION_ID"
      value = aws_cloudfront_distribution.site.id
      type  = "PLAINTEXT"
    }

    environment_variable {
      name  = "INVALIDATION_FLAG"
      value = tostring(var.site_invalidation_flag)
      type  = "PLAINTEXT"
    }
  }

  source {
    type      = "CODEPIPELINE"
    buildspec = local.buildspec
  }

  logs_config {
    cloudwatch_logs {
      group_name  = local.codebuild_log_group
      stream_name = ""
    }
  }
}

# ---------------------------------------------------------------------------
# IAM - CodePipeline
# ---------------------------------------------------------------------------
resource "aws_iam_role" "codepipeline" {
  name = "benchmark-cicd-codepipeline"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codepipeline.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      },
    ]
  })
  tags = local.common_tags
}

data "aws_iam_policy_document" "codepipeline" {
  statement {
    sid    = "AllowArtifactStore"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:GetBucketLocation",
      "s3:ListBucket",
    ]
    resources = [
      aws_s3_bucket.artifacts.arn,
      "${aws_s3_bucket.artifacts.arn}/*",
    ]
  }

  statement {
    sid    = "AllowKMSKey"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
      "kms:DescribeKey",
    ]
    resources = [aws_kms_key.pipeline.arn]
  }

  statement {
    sid    = "AllowCodeBuild"
    effect = "Allow"
    actions = [
      "codebuild:StartBuild",
      "codebuild:BatchGetBuilds",
      "codebuild:StopBuild",
    ]
    resources = [aws_codebuild_project.site.arn]
  }

  dynamic "statement" {
    for_each = var.codestar_connection_arn == "" ? [] : [1]
    content {
      sid    = "AllowCodeStarConnection"
      effect = "Allow"
      actions = [
        "codestar-connections:UseConnection",
      ]
      resources = [var.codestar_connection_arn]
    }
  }
}

resource "aws_iam_policy" "codepipeline" {
  name   = "benchmark-cicd-codepipeline"
  policy = data.aws_iam_policy_document.codepipeline.json
}

resource "aws_iam_role_policy_attachment" "codepipeline" {
  role       = aws_iam_role.codepipeline.name
  policy_arn = aws_iam_policy.codepipeline.arn
}

# ---------------------------------------------------------------------------
# SSM parameters and webhook (used when no CodeStar connection is supplied)
# ---------------------------------------------------------------------------
resource "aws_ssm_parameter" "github_oauth_token" {
  count       = var.codestar_connection_arn == "" ? 1 : 0
  name        = "/benchmark-cicd/github-oauth-token"
  description = "GitHub OAuth token used by CodePipeline for the source action (placeholder, replace before first use)"
  type        = "SecureString"
  value       = "github-oauth-token-placeholder"
  tags        = local.common_tags
}

resource "aws_ssm_parameter" "github_webhook_secret" {
  count       = var.codestar_connection_arn == "" ? 1 : 0
  name        = "/benchmark-cicd/github-webhook-secret"
  description = "HMAC secret used by the GitHub webhook to authenticate push events (placeholder, replace before first use)"
  type        = "SecureString"
  value       = "github-webhook-secret-placeholder"
  tags        = local.common_tags
}

# ---------------------------------------------------------------------------
# CodePipeline
# ---------------------------------------------------------------------------
resource "aws_codepipeline" "pipeline" {
  name     = "benchmark-cicd-pipeline"
  role_arn = aws_iam_role.codepipeline.arn
  tags     = local.common_tags

  artifact_store {
    location = aws_s3_bucket.artifacts.bucket
    type     = "S3"

    encryption_key {
      id   = aws_kms_key.pipeline.arn
      type = "KMS"
    }
  }

  stage {
    name = "Source"

    action {
      name             = "Source"
      category         = "Source"
      owner            = var.codestar_connection_arn == "" ? "ThirdParty" : "AWS"
      provider         = var.codestar_connection_arn == "" ? "GitHub" : "CodeStarSourceConnection"
      version          = "1"
      output_artifacts = ["source_output"]

      configuration = var.codestar_connection_arn == "" ? {
        Owner                = split("/", var.github_repo)[0]
        Repo                 = split("/", var.github_repo)[1]
        Branch               = var.github_branch
        OAuthToken           = aws_ssm_parameter.github_oauth_token[0].value
        PollForSourceChanges = "false"
        } : {
        FullRepositoryId     = var.github_repo
        BranchName           = var.github_branch
        ConnectionArn        = var.codestar_connection_arn
        OutputArtifactFormat = "CODE_ZIP"
      }
    }
  }

  stage {
    name = "Build"

    action {
      name            = "Build"
      category        = "Build"
      owner           = "AWS"
      provider        = "CodeBuild"
      version         = "1"
      input_artifacts = ["source_output"]

      configuration = {
        ProjectName = aws_codebuild_project.site.name
      }
    }
  }
}

resource "aws_codepipeline_webhook" "github" {
  count           = var.codestar_connection_arn == "" ? 1 : 0
  name            = "benchmark-cicd-github-webhook"
  authentication  = "GITHUB_HMAC"
  target_action   = "Source"
  target_pipeline = aws_codepipeline.pipeline.name
  tags            = local.common_tags

  authentication_configuration {
    secret_token = aws_ssm_parameter.github_webhook_secret[0].value
  }

  filter {
    json_path    = "$.ref"
    match_equals = "refs/heads/${var.github_branch}"
  }
}

# ---------------------------------------------------------------------------
# Optional pipeline notifications (off by default)
# ---------------------------------------------------------------------------
resource "aws_sns_topic" "pipeline_notifications" {
  count = var.enable_pipeline_notifications ? 1 : 0
  name  = "benchmark-cicd-pipeline-notifications"
  tags  = local.common_tags
}

data "aws_iam_policy_document" "sns_publish" {
  count = var.enable_pipeline_notifications ? 1 : 0

  statement {
    sid    = "AllowCodeStarNotifications"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["codestar-notifications.amazonaws.com"]
    }
    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.pipeline_notifications[0].arn]
  }
}

resource "aws_sns_topic_policy" "pipeline_notifications" {
  count  = var.enable_pipeline_notifications ? 1 : 0
  arn    = aws_sns_topic.pipeline_notifications[0].arn
  policy = data.aws_iam_policy_document.sns_publish[0].json
}

resource "aws_codestarnotifications_notification_rule" "pipeline" {
  count       = var.enable_pipeline_notifications ? 1 : 0
  name        = "benchmark-cicd-pipeline-notifications"
  resource    = aws_codepipeline.pipeline.arn
  detail_type = "FULL"
  tags        = local.common_tags

  event_type_ids = [
    "codepipeline-pipeline-pipeline-execution-failed",
    "codepipeline-pipeline-pipeline-execution-canceled",
    "codepipeline-pipeline-pipeline-execution-started",
    "codepipeline-pipeline-pipeline-execution-resumed",
    "codepipeline-pipeline-pipeline-execution-succeeded",
    "codepipeline-pipeline-pipeline-execution-superseded",
  ]

  target {
    address = aws_sns_topic.pipeline_notifications[0].arn
    type    = "SNS"
  }
}

# =============================================================================
# Reusable VPC Module – Terraform Configuration
# =============================================================================

# ── Variables ──────────────────────────────────────────────────────────────────

variable "create_enabled" {
  description = "Master toggle – when false no resources are created"
  type        = bool
  default     = true
}

variable "vpc_name" {
  description = "Display name (used in VPC tags)"
  type        = string
  default     = "main"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "enable_dns_support" {
  description = "Enable DNS resolution through the VPC resolver endpoint"
  type        = bool
  default     = true
}

variable "enable_dns_hostnames" {
  description = "Enable DNS hostnames for instances in the VPC"
  type        = bool
  default     = false
}

variable "subnet_cidr_bits" {
  description = "Prefix length for per-subnet CIDRs carved from the VPC (e.g. 24 → /24)"
  type        = number
  default     = 24
}

variable "nat_gateway_per_availability_zone" {
  description = "When true, create one NAT gateway per AZ instead of a single shared gateway"
  type        = bool
  default     = false
}

variable "subnet_definitions" {
  description = <<-EOT
    List of subnet-group definitions.  Each entry accepts:
    - name        – group name (string)
    - class       – "public", "private", or "intra"
    - database    – (optional bool, default false) register subnets in the RDS subnet group
    - elasticache – (optional bool, default false) register subnets in the ElastiCache subnet group
  EOT
  type = list(object({
    name        = string
    class       = string
    database    = optional(bool, false)
    elasticache = optional(bool, false)
  }))
  default = []
}

# ── Data Sources ──────────────────────────────────────────────────────────────

data "aws_availability_zones" "available" {
  state = "available"
}

# ── Locals ────────────────────────────────────────────────────────────────────

locals {
  azs               = data.aws_availability_zones.available.names
  az_count          = length(local.azs)
  vpc_prefix_length = tonumber(regexall("[0-9]+$", var.vpc_cidr)[0])

  # ---------- flat subnet specs ----------
  subnet_specs = flatten([
    for def_idx in range(length(var.subnet_definitions)) : [
      for az_idx in range(local.az_count) : {
        key               = "${var.subnet_definitions[def_idx].name}-${local.azs[az_idx]}"
        name              = var.subnet_definitions[def_idx].name
        class             = var.subnet_definitions[def_idx].class
        availability_zone = local.azs[az_idx]
        cidr_block        = cidrsubnet(var.vpc_cidr, var.subnet_cidr_bits - local.vpc_prefix_length, def_idx * local.az_count + az_idx)
        database          = try(var.subnet_definitions[def_idx].database, false)
        elasticache       = try(var.subnet_definitions[def_idx].elasticache, false)
        def_idx           = def_idx
        az_idx            = az_idx
      }
    ]
  ])
  subnet_count = length(local.subnet_specs)

  # ---------- class presence flags ----------
  has_public      = length([for s in local.subnet_specs : 1 if s.class == "public"])   > 0
  has_database    = length([for s in local.subnet_specs : 1 if s.database])             > 0
  has_elasticache = length([for s in local.subnet_specs : 1 if s.elasticache])          > 0

  # ---------- AZ sets per role ----------
  public_azs  = distinct([for s in local.subnet_specs : s.availability_zone if s.class == "public"])
  private_azs = distinct([for s in local.subnet_specs : s.availability_zone if s.class == "private"])

  # ---------- NAT placement ----------
  # Only AZs that hold at least one public subnet are eligible to host a NAT.
  nat_azs = var.nat_gateway_per_availability_zone ? (
    [for az in local.private_azs : az if length([for v in local.public_azs : 1 if v == az]) > 0]
  ) : (
    length(local.private_azs) > 0 && length(local.public_azs) > 0 ? [local.public_azs[0]] : []
  )
  nat_count = length(local.nat_azs)

  # map AZ → index into nat_azs / route table array
  az_to_nat_idx = zipmap(local.nat_azs, range(local.nat_count))

  # indices into aws_subnet.this[ ] for public subnets
  public_subnet_indices = [
    for i in range(length(local.subnet_specs)) : i
    if local.subnet_specs[i].class == "public"
  ]

  # private-association tuples (subnet index & route-table index)
  private_associations = var.create_enabled && local.nat_count > 0 ? [
    for i in range(length(local.subnet_specs)) : {
      subnet_idx = i
      rt_idx     = var.nat_gateway_per_availability_zone ? local.az_to_nat_idx[local.subnet_specs[i].availability_zone] : 0
    }
    if local.subnet_specs[i].class == "private"
  ] : []

  # ---------- DB / ElastiCache subnet membership ----------
  db_subnet_indices = [
    for i in range(length(local.subnet_specs)) : i
    if local.subnet_specs[i].database
  ]
  elasticache_subnet_indices = [
    for i in range(length(local.subnet_specs)) : i
    if local.subnet_specs[i].elasticache
  ]
}

# ── Resources ─────────────────────────────────────────────────────────────────

# ..............................................................................
# 1. VPC
# ..............................................................................
resource "aws_vpc" "main" {
  count = var.create_enabled ? 1 : 0

  cidr_block           = var.vpc_cidr
  instance_tenancy     = "default"
  enable_dns_support   = var.enable_dns_support
  enable_dns_hostnames = var.enable_dns_hostnames

  tags = {
    Name = var.vpc_name
  }
}

# ..............................................................................
# 2. Subnets
# ..............................................................................
resource "aws_subnet" "this" {
  count = var.create_enabled ? local.subnet_count : 0

  vpc_id                  = aws_vpc.main[0].id
  cidr_block              = local.subnet_specs[count.index].cidr_block
  availability_zone       = local.subnet_specs[count.index].availability_zone
  map_public_ip_on_launch = local.subnet_specs[count.index].class == "public"

  tags = {
    Name = local.subnet_specs[count.index].key
  }
}

# ..............................................................................
# 3. Internet Gateway
# ..............................................................................
resource "aws_internet_gateway" "this" {
  count = var.create_enabled && local.has_public ? 1 : 0

  vpc_id = aws_vpc.main[0].id

  tags = {
    Name = "${var.vpc_name}-igw"
  }
}

# ..............................................................................
# 4. Elastic IPs for NAT Gateways
# ..............................................................................
resource "aws_eip" "nat" {
  count  = var.create_enabled ? local.nat_count : 0
  domain = "vpc"

  tags = {
    Name = var.nat_gateway_per_availability_zone ? "${var.vpc_name}-nat-eip-${local.nat_azs[count.index]}" : "${var.vpc_name}-nat-eip"
  }
}

# ..............................................................................
# 5. NAT Gateways
# ..............................................................................
resource "aws_nat_gateway" "this" {
  count = var.create_enabled ? local.nat_count : 0

  subnet_id = aws_subnet.this[
    [
      for i in range(length(local.subnet_specs)) : i
      if local.subnet_specs[i].class == "public" && local.subnet_specs[i].availability_zone == local.nat_azs[count.index]
    ][0]
  ].id
  allocation_id = aws_eip.nat[count.index].allocation_id

  tags = {
    Name = var.nat_gateway_per_availability_zone ? "${var.vpc_name}-nat-${local.nat_azs[count.index]}" : "${var.vpc_name}-nat"
  }
}

# ..............................................................................
# 6. Route Tables & Routes – Public
# ..............................................................................
resource "aws_route_table" "public" {
  count = var.create_enabled && local.has_public ? 1 : 0

  vpc_id = aws_vpc.main[0].id

  tags = {
    Name = "${var.vpc_name}-public"
  }
}

resource "aws_route" "public" {
  count = var.create_enabled && local.has_public ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[0].id
}

resource "aws_route_table_association" "public" {
  count = var.create_enabled && local.has_public ? length(local.public_subnet_indices) : 0

  subnet_id      = aws_subnet.this[local.public_subnet_indices[count.index]].id
  route_table_id = aws_route_table.public[0].id
}

# ..............................................................................
# 7. Route Tables & Routes – Private (one per NAT gateway)
# ..............................................................................
resource "aws_route_table" "private" {
  count = var.create_enabled ? local.nat_count : 0

  vpc_id = aws_vpc.main[0].id

  tags = {
    Name = var.nat_gateway_per_availability_zone ? "${var.vpc_name}-private-${local.nat_azs[count.index]}" : "${var.vpc_name}-private"
  }
}

resource "aws_route" "private" {
  count = var.create_enabled ? local.nat_count : 0

  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.this[count.index].id
}

resource "aws_route_table_association" "private" {
  count = var.create_enabled ? length(local.private_associations) : 0

  subnet_id      = aws_subnet.this[local.private_associations[count.index].subnet_idx].id
  route_table_id = aws_route_table.private[local.private_associations[count.index].rt_idx].id
}

# ..............................................................................
# 8. DB Subnet Group
# ..............................................................................
resource "aws_db_subnet_group" "this" {
  count = var.create_enabled && local.has_database ? 1 : 0

  name        = "${var.vpc_name}-db"
  description = "Database subnet group for VPC ${var.vpc_name}"
  subnet_ids  = [for i in local.db_subnet_indices : aws_subnet.this[i].id]

  tags = {
    Name = "${var.vpc_name}-db"
  }
}

# ..............................................................................
# 9. ElastiCache Subnet Group
# ..............................................................................
resource "aws_elasticache_subnet_group" "this" {
  count = var.create_enabled && local.has_elasticache ? 1 : 0

  name        = "${var.vpc_name}-elasticache"
  description = "ElastiCache subnet group for VPC ${var.vpc_name}"
  subnet_ids  = [for i in local.elasticache_subnet_indices : aws_subnet.this[i].id]

  tags = {
    Name = "${var.vpc_name}-elasticache"
  }
}

locals {
  role_name           = "ec2-ssm-association"
  instance_profile_name = "ec2-s3-ssm-association"
}

data "aws_iam_policy" "ssm_managed_instance_core" {
  arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_role" "ec2_ssm_association" {
  name = local.role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  description = "IAM role for EC2 instances managed via Systems Manager"

  tags = {
    Name = local.role_name
  }
}

resource "aws_iam_role_policy_attachment" "ssm_managed_instance_core" {
  role       = aws_iam_role.ec2_ssm_association.name
  policy_arn = data.aws_iam_policy.ssm_managed_instance_core.arn
}

resource "aws_iam_instance_profile" "ec2_s3_ssm_association" {
  name = local.instance_profile_name
  role = aws_iam_role.ec2_ssm_association.name

  tags = {
    Name = local.instance_profile_name
  }
}

resource "aws_kms_key" "sqs_encryption_key" {
  description             = "Customer-managed KMS key for SQS dead-letter queue encryption"
  deletion_window_in_days = 10
  rotation_period_in_days = 365
  enable_key_rotation     = true
  is_enabled              = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sqs_queue" "dead_letter_queue" {
  name                      = "aggregation-lambda-dead-letter-queue"
  kms_master_key_id         = aws_kms_key.sqs_encryption_key.id
  message_retention_seconds = 1209600 # 14 days (max allowed by SQS)

  lifecycle {
    prevent_destroy = true
  }
}

locals {
  default_sms_type                     = "Transactional"
  delivery_status_success_sampling_rate = 0
}

resource "aws_sns_sms_preferences" "this" {
  default_sms_type                      = local.default_sms_type
  delivery_status_success_sampling_rate = local.delivery_status_success_sampling_rate
}

output "sns_sms_preferences_default_sms_type" {
  description = "The default SMS type setting"
  value       = aws_sns_sms_preferences.this.default_sms_type
}

output "sns_sms_preferences_delivery_status_success_sampling_rate" {
  description = "The delivery status success sampling rate"
  value       = aws_sns_sms_preferences.this.delivery_status_success_sampling_rate
}

output "sns_sms_preferences_monthly_spend_limit" {
  description = "The monthly spend limit (unset by default - not exported by resource)"
  value       = "unset (not exported by resource)"
}

output "sns_sms_preferences_sender_id" {
  description = "The sender ID (unset by default - not exported by resource)"
  value       = "unset (not exported by resource)"
}

output "sns_sms_preferences_usage_report_bucket" {
  description = "The usage report S3 bucket (unset by default - not exported by resource)"
  value       = "unset (not exported by resource)"
}

output "sns_sms_preferences_delivery_status_iam_role" {
  description = "The delivery status IAM role (unset by default - not exported by resource)"
  value       = "unset (not exported by resource)"
}

data "aws_iam_policy" "eks_cluster" {
  name = "AmazonEKSClusterPolicy"
}

data "aws_iam_policy" "eks_service" {
  name = "AmazonEKSServicePolicy"
}

resource "aws_iam_role" "eks_cluster" {
  name = "eks-cluster-sadcloud-example"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eks_cluster" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = data.aws_iam_policy.eks_cluster.arn
}

resource "aws_iam_role_policy_attachment" "eks_service" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = data.aws_iam_policy.eks_service.arn
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

resource "random_pet" "suffix" {
  length    = 2
  separator = "-"
}

locals {
  log_group_name = "logs-${random_pet.suffix.id}"
}

# CloudWatch Logs log group with a generated pet-name suffix and 7-day retention
resource "aws_cloudwatch_log_group" "this" {
  name              = local.log_group_name
  retention_in_days = 7
}

# Least-privilege IAM policy allowing stream creation and log delivery
# only on the log group created above.
data "aws_iam_policy_document" "log_group" {
  statement {
    sid     = "AllowDescribeStreams"
    effect  = "Allow"
    actions = ["logs:DescribeLogStreams"]
    resources = [
      aws_cloudwatch_log_group.this.arn
    ]
  }

  statement {
    sid     = "AllowWriteToStreams"
    effect  = "Allow"
    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]
    resources = [
      "${aws_cloudwatch_log_group.this.arn}:log-stream:*"
    ]
  }
}

resource "aws_iam_policy" "this" {
  name   = "logs-write-${random_pet.suffix.id}"
  path   = "/"
  policy = data.aws_iam_policy_document.log_group.json
}

variable "enable_ssm_logging" {
  description = "Flag to enable SSM Automation logging to CloudWatch and disable public document sharing"
  type        = bool
  default     = true
}

terraform {
  required_providers {
    aws = {
      source = "hashicorp/aws"
    }
    null = {
      source = "hashicorp/null"
    }
  }
}

resource "aws_cloudwatch_log_group" "ssm_automation" {
  count = var.enable_ssm_logging ? 1 : 0

  name              = "/aws/ssm/automation/executeScript"
  retention_in_days = 14

  tags = {
    Name = "SSM Automation Execute Script Log Group"
  }
}

resource "null_resource" "ssm_settings" {
  count = var.enable_ssm_logging ? 1 : 0

  triggers = {
    log_group_name = join("", aws_cloudwatch_log_group.ssm_automation[*].name)
  }

  provisioner "local-exec" {
    command = <<EOT
      aws ssm update-service-setting \
        --setting-id "/ssm/automation/cloud-watch-log-group" \
        --setting-value "${self.triggers.log_group_name}" 2>/dev/null || true
      aws ssm update-service-setting \
        --setting-id "/ssm/documents/ssm-document-public-sharing" \
        --setting-value "Disable" 2>/dev/null || true
    EOT
    interpreter = ["/bin/bash", "-c"]
    on_failure  = continue
  }
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.region
  partition  = data.aws_partition.current.partition
}

# Shared CloudWatch Logs policy
resource "aws_iam_policy" "lambda_logging" {
  name        = "lambda_logging"
  description = "Policy for Lambda functions to write to CloudWatch Logs"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:/aws/lambda/*:*"
      }
    ]
  })
}

# Create DDB Backup Role
resource "aws_iam_role" "create_ddb_backup_role" {
  name = "create_ddb_backup_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "create_ddb_backup_policy" {
  name        = "create_ddb_backup_policy"
  description = "Policy to create DynamoDB backups"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "dynamodb:CreateBackup"
        ]
        Resource = "arn:${local.partition}:dynamodb:${local.region}:${local.account_id}:table/*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "create_ddb_backup_role_policy_attach" {
  role       = aws_iam_role.create_ddb_backup_role.name
  policy_arn = aws_iam_policy.create_ddb_backup_policy.arn
}

resource "aws_iam_role_policy_attachment" "create_ddb_backup_role_logging_attach" {
  role       = aws_iam_role.create_ddb_backup_role.name
  policy_arn = aws_iam_policy.lambda_logging.arn
}

# Remove DDB Backup Role
resource "aws_iam_role" "remove_ddb_backup_role" {
  name = "remove_ddb_backup_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "remove_ddb_backup_policy" {
  name        = "remove_ddb_backup_policy"
  description = "Policy to list and delete DynamoDB backups"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "dynamodb:ListBackups"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "dynamodb:DeleteBackup"
        ]
        Resource = "arn:${local.partition}:dynamodb:${local.region}:${local.account_id}:backup/*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "remove_ddb_backup_role_policy_attach" {
  role       = aws_iam_role.remove_ddb_backup_role.name
  policy_arn = aws_iam_policy.remove_ddb_backup_policy.arn
}

resource "aws_iam_role_policy_attachment" "remove_ddb_backup_role_logging_attach" {
  role       = aws_iam_role.remove_ddb_backup_role.name
  policy_arn = aws_iam_policy.lambda_logging.arn
}

output "create_ddb_backup_role_arn" {
  description = "ARN of the create DynamoDB backup role"
  value       = aws_iam_role.create_ddb_backup_role.arn
}

output "remove_ddb_backup_role_arn" {
  description = "ARN of the remove DynamoDB backup role"
  value       = aws_iam_role.remove_ddb_backup_role.arn
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

data "aws_partition" "current" {}

resource "aws_iam_group" "admin" {
  name = "admin"
}

resource "aws_iam_group" "admin_read_only" {
  name = "admin_read_only"
}

resource "aws_iam_group" "developer_group" {
  name = "developer_group"
}

resource "aws_iam_group_policy_attachment" "admin" {
  group      = aws_iam_group.admin.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AdministratorAccess"
}

resource "aws_iam_group_policy_attachment" "admin_read_only" {
  group      = aws_iam_group.admin_read_only.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/ReadOnlyAccess"
}

