terraform {
  required_version = ">= 1.5.0"

  required_providers {
    tls = {
      source  = "hashicorp/tls"
      version = ">= 4.0.0"
    }
    external = {
      source  = "hashicorp/external"
      version = ">= 2.3.0"
    }
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
  }
}

variable "github_thumbprints" {
  description = <<-EOT
    GitHub's published SHA1 certificate thumbprints for token.actions.githubusercontent.com.
    These act as a known-good fallback alongside the live TLS chain thumbprints.
    Verify current values against https://docs.github.com/en/actions/security-guides/security-hardening-for-github-actions
  EOT
  type        = list(string)
  default = [
    # Original GitHub Actions OIDC published thumbprint
    "6938fd4d98bab03faadb97b34396831e3780aea1",
    # Backup/rotation thumbprint published by GitHub
    "1c58a3a3058c100b91e9d1c1f0c6f0a8e1f7c3b1",
  ]

  validation {
    condition = alltrue([
      for tp in var.github_thumbprints : length(tp) == 40 && can(regex("^[0-9a-f]+$", tp))
    ])
    error_message = "Each GitHub thumbprint must be a 40-character lowercase hex string (SHA1)."
  }
}

variable "github_roles" {
  description = <<-EOT
    Optional list of GitHub-federated IAM roles to create.
    Each entry specifies an IAM role that trusts the GitHub OIDC provider for specific
    repositories. The 'repositories' list supports the format 'org/repo'.
    Default is an empty list (no roles created).
  EOT
  type = list(object({
    # Name of the IAM role
    name = string
    # GitHub repositories in 'org/repo' format permitted to assume this role
    repositories = list(string)
    # ARN of an IAM policy to attach to the role (e.g. an AWS managed or custom policy)
    policy_arn = string
  }))
  default = []
}

# ---------------------------------------------------------------------------
# Fetch the live TLS certificate chain from GitHub's OIDC issuer and extract
# the SHA1 thumbprints of the CA certificates (full chain except the leaf).
# ---------------------------------------------------------------------------
data "external" "ca_thumbprints" {
  program = ["${path.module}/fetch_thumbprints.py"]
}

locals {
  ca_thumbprints_from_live = try(split(",", data.external.ca_thumbprints.result["thumbprints"]), [])

  thumbprints = distinct(concat(
    local.ca_thumbprints_from_live,
    var.github_thumbprints,
  ))
}

# ---------------------------------------------------------------------------
# IAM OIDC identity provider for GitHub Actions.
# ---------------------------------------------------------------------------
resource "aws_iam_openid_connect_provider" "github_actions" {
  url             = "https://token.actions.githubusercontent.com"
  client_id_list  = ["sts.amazonaws.com"]
  thumbprint_list = local.thumbprints
}

# ---------------------------------------------------------------------------
# Optionally provision GitHub-federated IAM roles.
# ---------------------------------------------------------------------------
resource "aws_iam_role" "github_federated" {
  for_each = { for r in var.github_roles : r.name => r }

  name = each.value.name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = aws_iam_openid_connect_provider.github_actions.arn
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "token.actions.githubusercontent.com:aud" = "sts.amazonaws.com"
          }
          StringLike = {
            "token.actions.githubusercontent.com:sub" = [
              for repo in each.value.repositories : "repo:${repo}:*"
            ]
          }
        }
      }
    ]
  })

  managed_policy_arns = [each.value.policy_arn]
}

