terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

variable "role_name" {
  description = "Name of the IAM role created for GitHub Actions OIDC web identity federation."
  type        = string
  default     = "github-actions-oidc-role"
}

variable "repo_patterns" {
  description = "List of GitHub repository patterns (e.g. \"octo-org/octo-repo\" or \"octo-org/*\") allowed to assume the role. Empty by default, in which case the subject condition denies all repositories until patterns are configured."
  type        = list(string)
  default     = []
}

locals {
  # AWS requires OIDC trust policies to include a sub condition that is not
  # scoped to all. Patterns are matched on the GitHub sub claim
  # (repo:OWNER/REPO:...). An empty pattern list falls back to a sentinel value
  # that matches no real repository, i.e. deny-by-default.
  allowed_subjects = length(var.repo_patterns) > 0 ? [
    for pattern in var.repo_patterns : "repo:${pattern}:*"
  ] : ["repo:no-such-org/no-such-repo:*"]
}

resource "aws_iam_openid_connect_provider" "github" {
  url             = "https://token.actions.githubusercontent.com"
  client_id_list  = ["sts.amazonaws.com"]
  thumbprint_list = ["6938fd4d98bab03faadb97b34396831e3780aea1"]
}

data "aws_iam_policy_document" "github_actions_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:aud"
      values   = ["sts.amazonaws.com"]
    }

    condition {
      test     = "StringLike"
      variable = "token.actions.githubusercontent.com:sub"
      values   = local.allowed_subjects
    }
  }
}

resource "aws_iam_role" "github_actions" {
  name                  = var.role_name
  path                  = "/"
  description           = "IAM role assumed by GitHub Actions workflows through OpenID Connect web identity federation."
  assume_role_policy    = data.aws_iam_policy_document.github_actions_assume_role.json
  force_detach_policies = true
}

output "github_actions_role_arn" {
  description = "ARN of the GitHub Actions OIDC federated IAM role."
  value       = aws_iam_role.github_actions.arn
}

output "github_actions_role_name" {
  description = "Name of the GitHub Actions OIDC federated IAM role."
  value       = aws_iam_role.github_actions.name
}

output "github_actions_role_path" {
  description = "Path of the GitHub Actions OIDC federated IAM role."
  value       = aws_iam_role.github_actions.path
}

output "github_actions_role_unique_id" {
  description = "Stable and unique string identifying the GitHub Actions OIDC federated IAM role."
  value       = aws_iam_role.github_actions.unique_id
}

resource "aws_iam_policy" "managed_force_mfa_policy" {
  name        = "managed-force-mfa-policy"
  path        = "/"
  description = "Allows IAM users to view basic account information and manage their own password and virtual MFA device, and allows MFA deactivation and broader self-inspection only when signed in with MFA."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowViewBasicAccountInformation"
        Effect = "Allow"
        Action = [
          "iam:GetAccountPasswordPolicy",
          "iam:GetAccountSummary",
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowManageOwnPassword"
        Effect = "Allow"
        Action = [
          "iam:ChangePassword",
          "iam:GetUser",
        ]
        Resource = "arn:aws:iam::*:user/$${aws:username}"
      },
      {
        Sid    = "AllowEnableResyncListOwnMFADevice"
        Effect = "Allow"
        Action = [
          "iam:EnableMFADevice",
          "iam:ListMFADevices",
          "iam:ResyncMFADevice",
        ]
        Resource = "arn:aws:iam::*:user/$${aws:username}"
      },
      {
        Sid    = "AllowCreateOwnVirtualMFADevice"
        Effect = "Allow"
        Action = [
          "iam:CreateVirtualMFADevice",
        ]
        Resource = "arn:aws:iam::*:mfa/*"
      },
      {
        Sid    = "AllowListVirtualMFADevices"
        Effect = "Allow"
        Action = [
          "iam:ListVirtualMFADevices",
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowMfaDeactivationAndSelfInspectionWithMfa"
        Effect = "Allow"
        Action = [
          "iam:DeactivateMFADevice",
          "iam:GetAccessKeyLastUsed",
          "iam:GetLoginProfile",
          "iam:ListAccessKeys",
          "iam:ListAttachedUserPolicies",
          "iam:ListGroupsForUser",
          "iam:ListServiceSpecificCredentials",
          "iam:ListSigningCertificates",
          "iam:ListSSHPublicKeys",
        ]
        Resource = "arn:aws:iam::*:user/$${aws:username}"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid    = "DenyAllExceptListedIfNoMfa"
        Effect = "Deny"
        NotAction = [
          "iam:ChangePassword",
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:GetAccountPasswordPolicy",
          "iam:GetAccountSummary",
          "iam:GetUser",
          "iam:ListMFADevices",
          "iam:ListVirtualMFADevices",
          "iam:ResyncMFADevice",
        ]
        Resource = "*"
        Condition = {
          BoolIfExists = {
            "aws:MultiFactorAuthPresent" = "false"
          }
        }
      },
    ]
  })
}

# Random 8-character passwords for each user
resource "random_password" "billing_password" {
  length      = 8
  special     = true
  min_upper   = 1
  min_lower   = 1
  min_numeric = 1
}

resource "random_password" "admin_password" {
  length      = 8
  special     = true
  min_upper   = 1
  min_lower   = 1
  min_numeric = 1
}

resource "random_password" "suport_password" {
  length      = 8
  special     = true
  min_upper   = 1
  min_lower   = 1
  min_numeric = 1
}

# IAM Users
resource "aws_iam_user" "billing" {
  name = "Billing"
}

resource "aws_iam_user" "admin" {
  name = "Admin"
}

resource "aws_iam_user" "suport" {
  name = "Suport"
}

# Custom IAM Policy for BillingGroup - read-only billing, usage, budget, cost reports, pricing
resource "aws_iam_policy" "billing_policy" {
  name        = "BillingPolicy"
  description = "Read-only billing, usage, budget, cost report, and pricing visibility"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "billing:GetBillingDetails",
          "billing:GetBillingData",
          "billing:ViewAccount",
          "billing:ViewBill",
          "billing:ViewUsage",
          "billing:DescribeBillingItems",
          "budgets:ViewBudget",
          "budgets:DescribeBudget",
          "pricing:GetProducts",
          "pricing:GetPricing"
        ]
        Resource = "*"
      }
    ]
  })
}

# Custom IAM Policy for SuportGroup - read-only describe/get/list on EC2, S3, CloudWatch, RDS
resource "aws_iam_policy" "suport_policy" {
  name        = "SuportPolicy"
  description = "Read-only describe/get/list access to EC2, S3, CloudWatch, and RDS"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:Describe*",
          "ec2:Get*",
          "s3:Describe*",
          "s3:Get*",
          "s3:List*",
          "cloudwatch:Describe*",
          "cloudwatch:Get*",
          "cloudwatch:List*",
          "rds:Describe*",
          "rds:Get*",
          "rds:List*"
        ]
        Resource = "*"
      }
    ]
  })
}

# IAM Groups
resource "aws_iam_group" "billing_group" {
  name = "BillingGroup"
}

resource "aws_iam_group" "admin_group" {
  name = "AdminGroup"
}

resource "aws_iam_group" "suport_group" {
  name = "SuportGroup"
}

# Attach policies to groups
resource "aws_iam_group_policy_attachment" "billing_policy_attach" {
  group      = aws_iam_group.billing_group.name
  policy_arn = aws_iam_policy.billing_policy.arn
}

resource "aws_iam_group_policy_attachment" "admin_policy_attach" {
  group      = aws_iam_group.admin_group.name
  policy_arn = "arn:aws:iam::aws:policy/AdministratorAccess"
}

resource "aws_iam_group_policy_attachment" "suport_policy_attach" {
  group      = aws_iam_group.suport_group.name
  policy_arn = aws_iam_policy.suport_policy.arn
}

# Add users to their respective groups
resource "aws_iam_user_group_membership" "billing_membership" {
  user   = aws_iam_user.billing.name
  groups = [aws_iam_group.billing_group.name]
}

resource "aws_iam_user_group_membership" "admin_membership" {
  user   = aws_iam_user.admin.name
  groups = [aws_iam_group.admin_group.name]
}

resource "aws_iam_user_group_membership" "suport_membership" {
  user   = aws_iam_user.suport.name
  groups = [aws_iam_group.suport_group.name]
}

# Create login profiles via CLI for full password control
resource "null_resource" "billing_login_profile" {
  depends_on = [
    aws_iam_user.billing
  ]

  triggers = {
    password_hash = sha256(random_password.billing_password.result)
  }

  provisioner "local-exec" {
    command = "aws iam create-login-profile --user-name ${aws_iam_user.billing.name} --password '${random_password.billing_password.result}' --password-reset-required 2>/dev/null || aws iam update-login-profile --user-name ${aws_iam_user.billing.name} --password '${random_password.billing_password.result}' --password-reset-required"
  }

  provisioner "local-exec" {
    when    = destroy
    command = "aws iam delete-login-profile --user-name Billing 2>/dev/null || true"
  }
}

resource "null_resource" "admin_login_profile" {
  depends_on = [
    aws_iam_user.admin
  ]

  triggers = {
    password_hash = sha256(random_password.admin_password.result)
  }

  provisioner "local-exec" {
    command = "aws iam create-login-profile --user-name ${aws_iam_user.admin.name} --password '${random_password.admin_password.result}' --password-reset-required 2>/dev/null || aws iam update-login-profile --user-name ${aws_iam_user.admin.name} --password '${random_password.admin_password.result}' --password-reset-required"
  }

  provisioner "local-exec" {
    when    = destroy
    command = "aws iam delete-login-profile --user-name Admin 2>/dev/null || true"
  }
}

resource "null_resource" "suport_login_profile" {
  depends_on = [
    aws_iam_user.suport
  ]

  triggers = {
    password_hash = sha256(random_password.suport_password.result)
  }

  provisioner "local-exec" {
    command = "aws iam create-login-profile --user-name ${aws_iam_user.suport.name} --password '${random_password.suport_password.result}' --password-reset-required 2>/dev/null || aws iam update-login-profile --user-name ${aws_iam_user.suport.name} --password '${random_password.suport_password.result}' --password-reset-required"
  }

  provisioner "local-exec" {
    when    = destroy
    command = "aws iam delete-login-profile --user-name Suport 2>/dev/null || true"
  }
}

# Outputs
output "billing_username" {
  value = aws_iam_user.billing.name
}

output "billing_password" {
  value     = random_password.billing_password.result
  sensitive = true
}

output "admin_username" {
  value = aws_iam_user.admin.name
}

output "admin_password" {
  value     = random_password.admin_password.result
  sensitive = true
}

output "suport_username" {
  value = aws_iam_user.suport.name
}

output "suport_password" {
  value     = random_password.suport_password.result
  sensitive = true
}

resource "random_id" "efs_creation_token" {
  byte_length = 8
}

resource "aws_efs_file_system" "shared_storage" {
  creation_token  = random_id.efs_creation_token.hex
  encrypted       = true
  performance_mode = "generalPurpose"
  throughput_mode  = "bursting"

  tags = {
    Name = "shared-storage-test"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_efs_backup_policy" "shared_storage" {
  file_system_id = aws_efs_file_system.shared_storage.id

  backup_policy {
    status = "ENABLED"
  }
}

# ------------------------------------------------------------------------------
# Data sources
# ------------------------------------------------------------------------------
data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  partition       = data.aws_partition.current.partition
  region          = data.aws_region.current.region
  account_id      = data.aws_caller_identity.current.account_id
  nlp_bucket_name = "nlp-pipeline-bucket"
  results_table   = "NLPResults"
  state_machine   = "YourStateMachineName"
}

# ------------------------------------------------------------------------------
# KMS key used to encrypt the Terraform remote state bucket
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid    = "EnableIAMUserPermissions"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
    actions = [
      "kms:CancelKeyDeletion",
      "kms:CreateAlias",
      "kms:CreateGrant",
      "kms:Decrypt",
      "kms:DeleteAlias",
      "kms:DescribeKey",
      "kms:DisableKey",
      "kms:DisableKeyRotation",
      "kms:EnableKey",
      "kms:EnableKeyRotation",
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:GetKeyPolicy",
      "kms:GetKeyRotationStatus",
      "kms:GetParametersForImport",
      "kms:GetPublicKey",
      "kms:ImportKeyMaterial",
      "kms:ListAliases",
      "kms:ListGrants",
      "kms:ListResourceTags",
      "kms:ListRetirableGrants",
      "kms:PutKeyPolicy",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
      "kms:RetireGrant",
      "kms:RevokeGrant",
      "kms:ScheduleKeyDeletion",
      "kms:TagResource",
      "kms:UntagResource",
      "kms:UpdateAlias",
      "kms:UpdateKeyDescription",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AllowS3ServiceUse"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["s3.${local.region}.amazonaws.com"]
    }
  }
}

resource "aws_kms_key" "state" {
  description             = "Customer managed key for encrypting the Terraform remote state bucket"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json
}

# ------------------------------------------------------------------------------
# Versioned S3 bucket for Terraform remote state
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "terraform_state" {
  bucket = "my-terraform-state-bucket-${local.account_id}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.state.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "terraform_state" {
  bucket                  = aws_s3_bucket.terraform_state.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ------------------------------------------------------------------------------
# DynamoDB table used for Terraform state locking
# ------------------------------------------------------------------------------
resource "aws_dynamodb_table" "terraform_locks" {
  name         = "terraform-locks"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Shared S3 object read/write policy for the NLP pipeline bucket
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "s3_object_access" {
  statement {
    sid       = "ListNlpPipelineBucket"
    effect    = "Allow"
    actions   = ["s3:ListBucket"]
    resources = ["arn:${local.partition}:s3:::${local.nlp_bucket_name}"]
  }

  statement {
    sid       = "ReadWriteNlpPipelineObjects"
    effect    = "Allow"
    actions   = ["s3:GetObject", "s3:PutObject"]
    resources = ["arn:${local.partition}:s3:::${local.nlp_bucket_name}/*"]
  }
}

# ------------------------------------------------------------------------------
# AWS Glue service role
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "glue_assume_role_policy" {
  statement {
    sid     = "AllowGlueServiceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["glue.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_iam_role" "glue" {
  name               = "glue-service-role"
  assume_role_policy = data.aws_iam_policy_document.glue_assume_role_policy.json
  description        = "Service role used by AWS Glue for the NLP data pipeline"
}

resource "aws_iam_role_policy_attachment" "glue_aws_managed" {
  role       = aws_iam_role.glue.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSGlueServiceRole"
}

resource "aws_iam_role_policy" "glue_s3" {
  name   = "nlp-pipeline-s3-access"
  role   = aws_iam_role.glue.id
  policy = data.aws_iam_policy_document.s3_object_access.json
}

# ------------------------------------------------------------------------------
# Amazon Comprehend service role
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "comprehend_assume_role_policy" {
  statement {
    sid     = "AllowComprehendServiceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["comprehend.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_iam_role" "comprehend" {
  name               = "comprehend-service-role"
  assume_role_policy = data.aws_iam_policy_document.comprehend_assume_role_policy.json
  description        = "Service role used by Amazon Comprehend for the NLP data pipeline"
}

resource "aws_iam_role_policy" "comprehend_s3" {
  name   = "nlp-pipeline-s3-access"
  role   = aws_iam_role.comprehend.id
  policy = data.aws_iam_policy_document.s3_object_access.json
}

# ------------------------------------------------------------------------------
# Lambda execution role
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "lambda_assume_role_policy" {
  statement {
    sid     = "AllowLambdaServiceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_iam_role" "lambda" {
  name               = "lambda-execution-role"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role_policy.json
  description        = "Execution role used by Lambda functions in the NLP data pipeline"
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

data "aws_iam_policy_document" "lambda_inline_policy" {
  statement {
    sid     = "NlpPipelineS3ReadWrite"
    effect  = "Allow"
    actions = ["s3:ListBucket", "s3:GetObject", "s3:PutObject"]
    resources = [
      "arn:${local.partition}:s3:::${local.nlp_bucket_name}",
      "arn:${local.partition}:s3:::${local.nlp_bucket_name}/*",
    ]
  }

  statement {
    sid       = "WriteNlpResultsTable"
    effect    = "Allow"
    actions   = ["dynamodb:BatchWriteItem", "dynamodb:DeleteItem", "dynamodb:PutItem", "dynamodb:UpdateItem"]
    resources = ["arn:${local.partition}:dynamodb:${local.region}:${local.account_id}:table/${local.results_table}"]
  }

  statement {
    sid       = "StartPipelineStateMachine"
    effect    = "Allow"
    actions   = ["states:StartExecution"]
    resources = ["arn:${local.partition}:states:${local.region}:${local.account_id}:stateMachine:${local.state_machine}"]
  }
}

resource "aws_iam_role_policy" "lambda_inline" {
  name   = "lambda-nlp-pipeline-policy"
  role   = aws_iam_role.lambda.id
  policy = data.aws_iam_policy_document.lambda_inline_policy.json
}

# ------------------------------------------------------------------------------
# AWS Step Functions service role
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "step_functions_assume_role_policy" {
  statement {
    sid     = "AllowStepFunctionsServiceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["states.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_iam_role" "step_functions" {
  name               = "step-functions-service-role"
  assume_role_policy = data.aws_iam_policy_document.step_functions_assume_role_policy.json
  description        = "Service role used by AWS Step Functions for the NLP data pipeline"
}

data "aws_iam_policy_document" "step_functions_inline_policy" {
  statement {
    sid       = "InvokeAnyLambdaFunction"
    effect    = "Allow"
    actions   = ["lambda:InvokeFunction"]
    resources = ["arn:${local.partition}:lambda:${local.region}:${local.account_id}:function:*"]
  }

  statement {
    sid       = "StartAnyGlueJobRun"
    effect    = "Allow"
    actions   = ["glue:StartJobRun"]
    resources = ["arn:${local.partition}:glue:${local.region}:${local.account_id}:job/*"]
  }
}

resource "aws_iam_role_policy" "step_functions_inline" {
  name   = "step-functions-nlp-pipeline-policy"
  role   = aws_iam_role.step_functions.id
  policy = data.aws_iam_policy_document.step_functions_inline_policy.json
}

# Data sources for static provider metadata
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_availability_zones" "available" {}

# Customer-managed KMS key for SSE-KMS encryption, with rotation enabled
resource "aws_kms_key" "artifact_encryption" {
  description             = "KMS key for S3 artifact store SSE-KMS encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  rotation_period_in_days = 90
  is_enabled              = true
  tags = {
    managedBy   = "terraform"
    application = "demo"
  }
}

# S3 artifact store bucket (ACL set at creation time before object ownership is applied)
resource "aws_s3_bucket" "artifact_store" {
  bucket        = "demo-artifact-store-${data.aws_caller_identity.current.account_id}"
  force_destroy = true
  acl           = "private"
  tags = {
    managedBy   = "terraform"
    application = "demo"
  }
}

# Set object ownership to bucket-owner-preferred (BucketOwnerPreferred)
resource "aws_s3_bucket_request_payment_configuration" "artifact_store" {
  bucket = aws_s3_bucket.artifact_store.id
  payer  = "BucketOwner"
}

# Block all public access to the bucket
resource "aws_s3_bucket_public_access_block" "artifact_store" {
  bucket = aws_s3_bucket.artifact_store.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# SSE-KMS default encryption configuration using the KMS key
resource "aws_s3_bucket_server_side_encryption_configuration" "artifact_store" {
  bucket = aws_s3_bucket.artifact_store.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.artifact_encryption.id
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = false
  }
}

# ECR repository for ZenML images
resource "aws_ecr_repository" "zenml" {
  name                 = "zenml-kubernetes"
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  tags = {
    managedBy   = "terraform"
    application = "demo"
  }
}

# Local ZenML stack YAML file
resource "local_file" "zenml_stack" {
  filename = "zenml_stack.yaml"
  content  = <<-EOT
version: '0.12.0'
artifact_store:
  type: s3
  path: s3://${aws_s3_bucket.artifact_store.bucket}
container_registry:
  type: aws
  uri: ${data.aws_caller_identity.current.account_id}.dkr.ecr.${data.aws_region.current.region}.amazonaws.com/${aws_ecr_repository.zenml.name}
secrets_manager:
  type: aws
  EOT
}

locals {
  name_prefix = "nim"
}

resource "aws_iam_role" "ecs_task_execution" {
  name = "${local.name_prefix}-ecs_task_execution-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_task_execution" {
  role       = aws_iam_role.ecs_task_execution.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_secretsmanager_secret" "reposecret" {
  name = "${local.name_prefix}-reposecret-"
}

resource "aws_secretsmanager_secret_version" "reposecret" {
  secret_id = aws_secretsmanager_secret.reposecret.id
  secret_string = jsonencode({
    username = "AWS"
    password = ""
  })
}

resource "aws_iam_role_policy" "ecs_task_access_secrets" {
  name = "ECSTaskAccessSecretsPolicy"
  role = aws_iam_role.ecs_task_execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue"
        ]
        Resource = [
          aws_secretsmanager_secret.reposecret.arn
        ]
      }
    ]
  })
}

terraform {
  required_version = ">= 1.6.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 6.0.0"
    }
  }
}

variable "organizational_unit_paths" {
  description = "List of slash-delimited paths defining OU hierarchy (e.g., ['engineering/backend', 'engineering/frontend', 'finance']). Supports up to 5 levels deep."
  type        = list(string)
  default     = []

  validation {
    condition = alltrue([
      for path in var.organizational_unit_paths : length(split("/", path)) <= 5
    ])
    error_message = "Each OU path may be at most 5 levels deep (5 slash-separated segments)."
  }

  validation {
condition = alltrue([
      for path in var.organizational_unit_paths : can(split("/", path)) && length(split("/", path)) >= 1
    ])
    error_message = "Each OU path must contain at least one segment."
  }
}

data "aws_organizations_organization" "current" {}

locals {
  # Attempt to read the current org ID; will be null when no org exists
  # (e.g. a GREENFIELD account).
  org_id = try(data.aws_organizations_organization.current.id, null)

  # Build all unique ancestor paths from the requested OU paths.
  # e.g., ["a/b/c", "a/d"] -> ["a", "a/b", "a/b/c", "a/d"]
  all_ou_paths = distinct(flatten([
    for path in var.organizational_unit_paths : flatten([
      for i in range(1, length(split("/", path)) + 1) : join("/", slice(split("/", path), 0, i))
    ])
  ]))

  # Name of each OU (last path segment)
  ou_name = tomap({
    for path in local.all_ou_paths : path => split("/", path)[length(split("/", path)) - 1]
  })

  # Paths grouped by depth level
  ou_paths_level1 = [for p in local.all_ou_paths : p if length(split("/", p)) == 1]
  ou_paths_level2 = [for p in local.all_ou_paths : p if length(split("/", p)) == 2]
  ou_paths_level3 = [for p in local.all_ou_paths : p if length(split("/", p)) == 3]
  ou_paths_level4 = [for p in local.all_ou_paths : p if length(split("/", p)) == 4]
  ou_paths_level5 = [for p in local.all_ou_paths : p if length(split("/", p)) == 5]
}

# Conditionally create an organization only when one does not already exist.
resource "aws_organizations_organization" "root" {
  count                        = local.org_id == null ? 1 : 0
  feature_set                  = "ALL"
  aws_service_access_principals = toset([])
  enabled_policy_types         = toset(["AISERVICES_OPT_OUT_POLICY", "BACKUP_POLICY", "SERVICE_CONTROL_POLICY", "TAG_POLICY"])
}

# --------------------------------------------------------------------------
# Organizational Units – defined per depth level so that child OUs can
# reference their parent OU resource without a self-referential block.
# Level 1 OUs are children of the organisation root.
# --------------------------------------------------------------------------

resource "aws_organizations_organizational_unit" "level1" {
  for_each = length(local.ou_paths_level1) > 0 ? {
    for p in local.ou_paths_level1 : p => local.ou_name[p]
  } : {}

  name      = each.value
  parent_id = local.org_id != null ? data.aws_organizations_organization.current.roots[0].id : aws_organizations_organization.root[0].roots[0].id
}

resource "aws_organizations_organizational_unit" "level2" {
  for_each = length(local.ou_paths_level2) > 0 ? {
    for p in local.ou_paths_level2 : p => {
      name        = local.ou_name[p]
      parent_path = join("/", slice(split("/", p), 0, 1))
    }
  } : {}

  name      = each.value.name
  parent_id = aws_organizations_organizational_unit.level1[each.value.parent_path].id
}

resource "aws_organizations_organizational_unit" "level3" {
  for_each = length(local.ou_paths_level3) > 0 ? {
    for p in local.ou_paths_level3 : p => {
      name        = local.ou_name[p]
      parent_path = join("/", slice(split("/", p), 0, 2))
    }
  } : {}

  name      = each.value.name
  parent_id = aws_organizations_organizational_unit.level2[each.value.parent_path].id
}

resource "aws_organizations_organizational_unit" "level4" {
  for_each = length(local.ou_paths_level4) > 0 ? {
    for p in local.ou_paths_level4 : p => {
      name        = local.ou_name[p]
      parent_path = join("/", slice(split("/", p), 0, 3))
    }
  } : {}

  name      = each.value.name
  parent_id = aws_organizations_organizational_unit.level3[each.value.parent_path].id
}

resource "aws_organizations_organizational_unit" "level5" {
  for_each = length(local.ou_paths_level5) > 0 ? {
    for p in local.ou_paths_level5 : p => {
      name        = local.ou_name[p]
      parent_path = join("/", slice(split("/", p), 0, 4))
    }
  } : {}

  name      = each.value.name
  parent_id = aws_organizations_organizational_unit.level4[each.value.parent_path].id
}

resource "aws_vpc" "swe_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    ResourceGroup = "default"
  }
}

locals {
  vpc_cidr_block = aws_vpc.swe_vpc.cidr_block
}

resource "aws_default_network_acl" "swe_vpc_default_acl" {
  default_network_acl_id = aws_vpc.swe_vpc.default_network_acl_id

  # Allow all ingress from VPC's own CIDR
  ingress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = local.vpc_cidr_block
    from_port  = 0
    to_port    = 0
  }

  # Allow all egress to VPC's own CIDR
  egress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = local.vpc_cidr_block
    from_port  = 0
    to_port    = 0
  }

  # Deny inbound SSH from anywhere
  ingress {
    protocol   = "6"
    rule_no    = 200
    action     = "deny"
    cidr_block = "0.0.0.0/0"
    from_port  = 22
    to_port    = 22
  }

  # Deny inbound RDP from anywhere
  ingress {
    protocol   = "6"
    rule_no    = 201
    action     = "deny"
    cidr_block = "0.0.0.0/0"
    from_port  = 3389
    to_port    = 3389
  }

  # Allow all other inbound traffic from anywhere
  ingress {
    protocol   = "-1"
    rule_no    = 300
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  # Allow all other outbound traffic to anywhere
  egress {
    protocol   = "-1"
    rule_no    = 300
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = {
    Name = "swe-vpc-default_acl"
  }
}

resource "aws_default_security_group" "swe_vpc_default_sg" {
  vpc_id = aws_vpc.swe_vpc.id

  tags = {
    Name = "swe-vpc-default_sg"
  }
}

resource "aws_security_group_rule" "allow_ping" {
  type              = "ingress"
  security_group_id = aws_default_security_group.swe_vpc_default_sg.id
  protocol          = "icmp"
  from_port         = -1
  to_port           = -1
  cidr_blocks       = ["0.0.0.0/0"]
}

resource "aws_security_group_rule" "allow_http" {
  type              = "ingress"
  security_group_id = aws_default_security_group.swe_vpc_default_sg.id
  protocol          = "tcp"
  from_port         = 80
  to_port           = 80
  cidr_blocks       = ["0.0.0.0/0"]
}

data "aws_availability_zones" "available" {}

locals {
  az_names = data.aws_availability_zones.available.names

  vpcs = {
    dev = {
      cidr     = "10.16.0.0/16"
      gateway  = "gatway_dev"
      subnet_x = "10.16"
    }
    rec = {
      cidr     = "10.32.0.0/16"
      gateway  = "gatway_rec"
      subnet_x = "10.32"
    }
  }

  subnet_types = {
    public = {
      az_cidrs = { "a" = 12, "b" = 11 }
    }
    internal = {
      az_cidrs = { "a" = 1, "b" = 2 }
    }
    external = {
      az_cidrs = { "a" = 5, "b" = 6 }
    }
  }
}

resource "aws_vpc" "this" {
  for_each = local.vpcs

  cidr_block           = each.value.cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "vpc_${each.key}"
  }
}

resource "aws_internet_gateway" "this" {
  for_each = local.vpcs

  vpc_id = aws_vpc.this[each.key].id

  tags = {
    Name = each.value.gateway
  }
}

resource "aws_subnet" "this" {
  for_each = {
    for pair in flatten([
      for vpc_key, vpc_val in local.vpcs : [
        for type_key, type_val in local.subnet_types : [
          for az_suffix, cidr_octet in type_val.az_cidrs : {
            key        = "${vpc_key}_${type_key}_${az_suffix}"
            vpc_key    = vpc_key
            type       = type_key
            az_suffix  = az_suffix
            cidr_block = "${vpc_val.subnet_x}.${cidr_octet}.0/24"
            az_index   = az_suffix == "a" ? 0 : 1
          }
        ]
      ]
    ])
    : pair.key => pair
  }

  vpc_id            = aws_vpc.this[each.value.vpc_key].id
  cidr_block        = each.value.cidr_block
  availability_zone = local.az_names[each.value.az_index]

  tags = {
    Name = "subnet_${each.value.vpc_key}_${each.value.type}_${each.value.az_suffix}"
  }
}

resource "aws_route" "default_ipv4" {
  for_each = local.vpcs

  route_table_id         = aws_vpc.this[each.key].main_route_table_id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[each.key].id
}

resource "aws_route" "default_ipv6" {
  for_each = local.vpcs

  route_table_id              = aws_vpc.this[each.key].main_route_table_id
  destination_ipv6_cidr_block = "::/0"
  gateway_id                  = aws_internet_gateway.this[each.key].id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
  required_version = ">= 1.0"
}

output "vpc_dev_id" {
  value = aws_vpc.this["dev"].id
}

output "vpc_rec_id" {
  value = aws_vpc.this["rec"].id
}

locals {
  name       = var.name
  namespace  = var.namespace
  stage      = var.stage
  delimiter  = var.delimiter
  attributes = var.attributes
  tags       = var.tags

  context = {
    name       = local.name
    namespace  = local.namespace
    stage      = local.stage
    delimiter  = local.delimiter
    attributes = local.attributes
    tags       = local.tags
  }

  # Standard label components
  label_order = ["namespace", "stage", "name"]

  # Build an ID using the Cloud Posse convention
  id_parts = [
    for label in local.label_order : local.context[label] != "" ? local.context[label] : ""
  ]
  id = join(local.delimiter, compact(local.id_parts))
}

# ---------------------------------------------------------------------------------------------------------------------
# Cloud Posse-style label
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_guardduty_detector" "this" {
  enable                       = true
  finding_publishing_frequency = var.finding_publishing_frequency

  tags = merge(
    local.tags,
    {
      Name       = local.id
      Namespace  = local.namespace
      Stage      = local.stage
    }
  )
}

# Disable S3 protection using the detector feature resource (recommended over deprecated datasources block)
resource "aws_guardduty_detector_feature" "s3_protection" {
  detector_id = aws_guardduty_detector.this.id
  name        = "S3_DATA_EVENTS"
  status      = "DISABLED"
}

# ---------------------------------------------------------------------------------------------------------------------
# Optional: SNS topic for GuardDuty finding notifications
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_sns_topic" "guardduty" {
  count = var.create_sns_topic ? 1 : 0

  name = local.id

  tags = merge(
    local.tags,
    {
      Name       = local.id
      Namespace  = local.namespace
      Stage      = local.stage
    }
  )
}

resource "aws_sns_topic_policy" "guardduty" {
  count = var.create_sns_topic ? 1 : 0

  arn = aws_sns_topic.guardduty[0].arn

  policy = data.aws_iam_policy_document.sns_topic_policy[0].json
}

data "aws_iam_policy_document" "sns_topic_policy" {
  count = var.create_sns_topic ? 1 : 0

  statement {
    sid    = "AllowGuardDutyToPublishFindings"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }

    actions = [
      "SNS:Publish",
    ]

    resources = [
      aws_sns_topic.guardduty[0].arn,
    ]

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = [aws_guardduty_detector.this.arn]
    }
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# Optional: EventBridge rule to forward GuardDuty findings to the SNS topic
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_cloudwatch_event_rule" "guardduty" {
  count = var.create_event_rule ? 1 : 0

  name        = local.id
  description = "GuardDuty finding event rule"

  event_pattern = jsonencode({
    source      = ["aws.guardduty"]
    detail-type = ["GuardDuty Finding"]
  })

  tags = merge(
    local.tags,
    {
      Name       = local.id
      Namespace  = local.namespace
      Stage      = local.stage
    }
  )
}

resource "aws_cloudwatch_event_target" "guardduty" {
  count = var.create_event_rule ? 1 : 0

  rule      = aws_cloudwatch_event_rule.guardduty[0].name
  arn       = aws_sns_topic.guardduty[0].arn
  target_id = "GuardDutySNSTopic"
}

# ---------------------------------------------------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------------------------------------------------
variable "name" {
  description = "Solution name, e.g. 'app' or 'guardduty'"
  type        = string
  default     = "guardduty"
}

variable "namespace" {
  description = "Namespace, e.g. 'company' or 'org'"
  type        = string
  default     = ""
}

variable "stage" {
  description = "Stage, e.g. 'prod', 'staging', 'dev'"
  type        = string
  default     = ""
}

variable "delimiter" {
  description = "Delimiter to be used between parts of the label"
  type        = string
  default     = "-"
}

variable "attributes" {
  description = "Additional attributes (e.g. ['1'])"
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Additional tags (e.g. map('BusinessUnit','XYZ'))"
  type        = map(string)
  default     = {}
}

variable "finding_publishing_frequency" {
  description = "Specifies the frequency of finding publication for GuardDuty. Leave empty for service default."
  type        = string
  default     = null
}

variable "create_sns_topic" {
  description = "Flag to create an SNS topic for GuardDuty finding notifications"
  type        = bool
  default     = false
}

variable "create_event_rule" {
  description = "Flag to create an EventBridge rule that forwards GuardDuty findings to the SNS topic"
  type        = bool
  default     = false
}

# ---------------------------------------------------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------------------------------------------------
output "detector_id" {
  description = "The ID of the GuardDuty detector"
  value       = aws_guardduty_detector.this.id
}

output "detector_arn" {
  description = "The ARN of the GuardDuty detector"
  value       = aws_guardduty_detector.this.arn
}

output "sns_topic_arn" {
  description = "The ARN of the SNS topic (if created)"
  value       = try(aws_sns_topic.guardduty[0].arn, null)
}

output "event_rule_arn" {
  description = "The ARN of the EventBridge rule (if created)"
  value       = try(aws_cloudwatch_event_rule.guardduty[0].arn, null)
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
    }
    random = {
      source = "hashicorp/random"
    }
  }
}

resource "random_string" "suffix" {
  length  = 6
  lower   = true
  upper   = false
  numeric = true
  special = false
}

locals {
  prefix = "sudo-backup-${random_string.suffix.result}"
}

resource "aws_kms_key" "backup" {
  description          = "KMS key for ${local.prefix} backup vault encryption"
  enable_key_rotation  = true
  deletion_window_in_days = 7
  tags = {
    Name = "${local.prefix}-kms-key"
  }
}

resource "aws_backup_vault" "backup" {
  name         = "${local.prefix}-backup-vault"
  kms_key_arn  = aws_kms_key.backup.arn
  force_destroy = true
  tags = {
    Name = "${local.prefix}-backup-vault"
  }
}

resource "aws_backup_plan" "backup" {
  name = "${local.prefix}-backup-plan"
  tags = {
    Name = "${local.prefix}-backup-plan"
  }

  rule {
    rule_name       = "${local.prefix}-backup-rule"
    target_vault_name = aws_backup_vault.backup.name
    schedule        = "cron(0 12 * * ? *)"
    recovery_point_tags = {
      Name = "${local.prefix}-recovery-point"
    }
  }
}

data "aws_iam_policy_document" "backup_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      identifiers = ["backup.amazonaws.com"]
      type        = "Service"
    }
    effect = "Allow"
  }
}

resource "aws_iam_role" "backup" {
  name               = "${local.prefix}-backup-role"
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role.json
  description        = "Role for AWS Backup to assume"
  tags = {
    Name = "${local.prefix}-backup-role"
  }
}

resource "aws_iam_role_policy_attachment" "backup" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_backup_selection" "backup" {
  name         = "${local.prefix}-backup-selection"
  iam_role_arn = aws_iam_role.backup.arn
  plan_id      = aws_backup_plan.backup.id

  selection_tag {
    key   = "backup"
    type  = "STRINGEQUALS"
    value = "true"
  }
}

output "prefix" {
  value = local.prefix
}

# Amazon Cognito authentication for application "coop-tweets"

# --- User Pool ---
resource "aws_cognito_user_pool" "coop_tweets" {
  name = "coop-tweets"

  admin_create_user_config {
    allow_admin_create_user_only = true
  }

  password_policy {
    minimum_length    = 6
    require_numbers   = true
    require_uppercase = true
    require_symbols   = true
  }

  auto_verified_attributes = ["email"]
}

# --- User Pool Client ---
resource "aws_cognito_user_pool_client" "coop_tweets" {
  name         = "coop-tweets-client"
  user_pool_id = aws_cognito_user_pool.coop_tweets.id
  generate_secret = false

  explicit_auth_flows = [
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH",
  ]
}

# --- Hosted UI Domain ---
resource "aws_cognito_user_pool_domain" "coop_tweets" {
  domain       = "coop-tweets-domain"
  user_pool_id = aws_cognito_user_pool.coop_tweets.id
}

# --- Identity Pool ---
resource "aws_cognito_identity_pool" "coop_tweets" {
  identity_pool_name               = "coop tweets"
  allow_unauthenticated_identities = false

  cognito_identity_providers {
    client_id     = aws_cognito_user_pool_client.coop_tweets.id
    provider_name = aws_cognito_user_pool.coop_tweets.endpoint
    server_side_token_check = false
  }
}

# --- IAM Roles ---

locals {
  cognito_federated_identity_service = "cognito-identity.amazonaws.com"
}

# Authenticated role trust: Cognito federated identities for this identity pool only
resource "aws_iam_role" "cognito_auth" {
  name = "coop-tweets_cognito_auth_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Federated = local.cognito_federated_identity_service }
        Action    = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "cognito-identity.amazonaws.com:aud" = aws_cognito_identity_pool.coop_tweets.id
          }
        }
      },
    ]
  })
}

# Unauthenticated role trust: Cognito federated identities for this identity pool only
resource "aws_iam_role" "cognito_unauth" {
  name = "coop-tweets_cognito_unauth_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Federated = local.cognito_federated_identity_service }
        Action    = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "cognito-identity.amazonaws.com:aud" = aws_cognito_identity_pool.coop_tweets.id
          }
        }
      },
    ]
  })
}

# Attach both roles to the identity pool
resource "aws_cognito_identity_pool_roles_attachment" "coop_tweets" {
  identity_pool_id = aws_cognito_identity_pool.coop_tweets.id

  roles = {
    "authenticated"   = aws_iam_role.cognito_auth.arn
    "unauthenticated" = aws_iam_role.cognito_unauth.arn
  }
}

# --- Customer-managed policies ---

# Shared permission set: mobile analytics events + Cognito Sync + Cognito Identity
locals {
  cognito_mobile_policy_statement = [
    {
      Effect   = "Allow"
      Action   = ["mobileanalytics:PutEvents"]
      Resource = "*"
    },
    {
      Effect   = "Allow"
      Action   = ["cognito-sync:*"]
      Resource = "*"
    },
    {
      Effect   = "Allow"
      Action   = ["cognito-identity:*"]
      Resource = "*"
    },
  ]
}

resource "aws_iam_policy" "cognito_kibana_auth" {
  name   = "cognito_kibana_auth_coop-tweets"
  path   = "/"
  policy = jsonencode({
    Version   = "2012-10-17"
    Statement = local.cognito_mobile_policy_statement
  })
}

resource "aws_iam_policy" "cognito_kibana_unauth" {
  name   = "cognito_kibana_unauth_coop-tweets"
  path   = "/"
  policy = jsonencode({
    Version   = "2012-10-17"
    Statement = local.cognito_mobile_policy_statement
  })
}

resource "aws_iam_role_policy_attachment" "cognito_auth" {
  role       = aws_iam_role.cognito_auth.name
  policy_arn = aws_iam_policy.cognito_kibana_auth.arn
}

resource "aws_iam_role_policy_attachment" "cognito_unauth" {
  role       = aws_iam_role.cognito_unauth.name
  policy_arn = aws_iam_policy.cognito_kibana_unauth.arn
}

variable "enable_s3_findings_export" {
  description = "Whether to export GuardDuty findings to an S3 bucket. Disabled by default."
  type        = bool
  default     = false
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  guardduty_service_principal = "guardduty.amazonaws.com"
}

##########################################################################
# GuardDuty detector
##########################################################################

resource "aws_guardduty_detector" "main" {
  enable                       = true
  finding_publishing_frequency = "FIFTEEN_MINUTES"
}

##########################################################################
# Customer-managed KMS key for GuardDuty findings exports
##########################################################################

resource "aws_kms_key" "guardduty" {
  description             = "Customer-managed KMS key used by GuardDuty to encrypt findings exports"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "guardduty-kms-key-policy"
    Statement = [
      {
        Sid    = "Enable full administration of the key by the account"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow GuardDuty to generate data keys for encrypting findings exports"
        Effect = "Allow"
        Principal = {
          Service = local.guardduty_service_principal
        }
        Action = [
          "kms:GenerateDataKey",
          "kms:Decrypt",
        ]
        Resource = "*"
      },
    ]
  })

  tags = {
    Name = "guardduty-kms-key"
  }
}

resource "aws_kms_alias" "guardduty" {
  name          = "alias/guardduty"
  target_key_id = aws_kms_key.guardduty.id
}

##########################################################################
# EventBridge rule matching GuardDuty Finding events
##########################################################################

resource "aws_cloudwatch_event_rule" "guardduty_finding_events" {
  name        = "guardduty-finding-events"
  description = "Matches GuardDuty Finding events"

  event_pattern = jsonencode({
    source      = ["aws.guardduty"]
    detail-type = ["GuardDuty Finding"]
  })
}

##########################################################################
# Optional S3 findings export (disabled by default)
##########################################################################

resource "aws_s3_bucket" "guardduty_findings" {
  count  = var.enable_s3_findings_export ? 1 : 0
  bucket = "guardduty-findings-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.region}"

  tags = {
    Name = "guardduty-findings"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "guardduty_findings" {
  count  = var.enable_s3_findings_export ? 1 : 0
  bucket = aws_s3_bucket.guardduty_findings[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "guardduty_findings" {
  count  = var.enable_s3_findings_export ? 1 : 0
  bucket = aws_s3_bucket.guardduty_findings[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "guardduty_findings" {
  count  = var.enable_s3_findings_export ? 1 : 0
  bucket = aws_s3_bucket.guardduty_findings[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.guardduty.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_policy" "guardduty_findings" {
  count  = var.enable_s3_findings_export ? 1 : 0
  bucket = aws_s3_bucket.guardduty_findings[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "guardduty-findings-bucket-policy"
    Statement = [
      {
        Sid    = "Allow GuardDuty to upload findings to the bucket"
        Effect = "Allow"
        Principal = {
          Service = local.guardduty_service_principal
        }
        Action = [
          "s3:GetBucketLocation",
          "s3:PutObject",
        ]
        Resource = [
          aws_s3_bucket.guardduty_findings[0].arn,
          "${aws_s3_bucket.guardduty_findings[0].arn}/*",
        ]
      },
    ]
  })
}

resource "aws_guardduty_publishing_destination" "s3" {
  count           = var.enable_s3_findings_export ? 1 : 0
  detector_id     = aws_guardduty_detector.main.id
  destination_arn = aws_s3_bucket.guardduty_findings[0].arn
  kms_key_arn     = aws_kms_key.guardduty.arn

  depends_on = [
    aws_s3_bucket_policy.guardduty_findings,
    aws_s3_bucket_public_access_block.guardduty_findings,
  ]
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

resource "random_id" "bucket_suffix" {
  byte_length = 8
}

resource "aws_kms_key" "encryption" {
  description             = "Customer managed key for default encryption of the private S3 bucket"
  enable_key_rotation     = true
  deletion_window_in_days = 7
}

resource "aws_s3_bucket" "private" {
  bucket        = "private-${random_id.bucket_suffix.hex}"
  force_destroy = true
}

resource "aws_s3_bucket_ownership_controls" "private" {
  bucket = aws_s3_bucket.private.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_public_access_block" "private" {
  bucket = aws_s3_bucket.private.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "private" {
  bucket = aws_s3_bucket.private.id

  versioning_configuration {
    status     = "Enabled"
    mfa_delete = "Disabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "private" {
  bucket = aws_s3_bucket.private.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm      = "aws:kms"
      kms_master_key_id = aws_kms_key.encryption.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_acl" "private" {
  depends_on = [aws_s3_bucket_ownership_controls.private]

  bucket = aws_s3_bucket.private.id
  acl    = "private"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

# ──────────────────────────────────────────────
# Customer-managed IAM policies for the roles
# ──────────────────────────────────────────────

resource "aws_iam_policy" "billing_full_access" {
  name        = "billing-full-access"
  path        = "/"
  description = "Grants full access to all billing, usage, payment-method, and budget management actions"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "aws-portal:*",
          "budgets:*",
          "purchase-orders:*",
          "ce:*",
          "cur:*",
          "consolidatedbilling:*",
          "invoicing:*",
          "payments:*",
          "freetier:*",
          "account:*",
          "tax:*",
          "billing:*",
          "cost-optimization-hub:*",
        ]
        Resource = "*"
      },
    ]
  })
}

resource "aws_iam_policy" "billing_view_access" {
  name        = "billing-view-access"
  path        = "/"
  description = "Grants read-only access to billing, usage, account, payment methods, and budgets"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "account:Get*",
          "account:List*",
          "aws-portal:View*",
          "aws-portal:Get*",
          "aws-portal:Describe*",
          "aws-portal:List*",
          "billing:Get*",
          "billing:List*",
          "billing:Describe*",
          "budgets:View*",
          "budgets:Describe*",
          "budgets:Get*",
          "budgets:List*",
          "ce:Describe*",
          "ce:Get*",
          "ce:List*",
          "ce:View*",
          "consolidatedbilling:Get*",
          "consolidatedbilling:List*",
          "consolidatedbilling:Describe*",
          "cur:Describe*",
          "cur:Get*",
          "cur:List*",
          "cur:View*",
          "freetier:Get*",
          "freetier:List*",
          "freetier:Describe*",
          "invoicing:Get*",
          "invoicing:List*",
          "invoicing:Describe*",
          "payments:Get*",
          "payments:List*",
          "payments:Describe*",
          "purchase-orders:View*",
          "purchase-orders:Get*",
          "purchase-orders:Describe*",
          "purchase-orders:List*",
          "tax:Get*",
          "tax:List*",
        ]
        Resource = "*"
      },
    ]
  })
}

# ──────────────────────────────────────────────
# IAM roles
# ──────────────────────────────────────────────

resource "aws_iam_role" "billing_full_access" {
  name                 = "billing-full-access"
  path                 = "/"
  description          = "Role that grants full billing access, assumable only with MFA"
  assume_role_policy   = data.aws_iam_policy_document.billing_full_access_trust.json
  max_session_duration = 3600
}

resource "aws_iam_role" "billing_view_access" {
  name                 = "billing-view-access"
  path                 = "/"
  description          = "Role that grants read-only billing access, assumable only with MFA"
  assume_role_policy   = data.aws_iam_policy_document.billing_view_access_trust.json
  max_session_duration = 3600
}

# Trust policy documents

data "aws_iam_policy_document" "billing_full_access_trust" {
  statement {
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions = ["sts:AssumeRole", "sts:TagSession"]
    condition {
      test     = "BoolIfExists"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

data "aws_iam_policy_document" "billing_view_access_trust" {
  statement {
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions = ["sts:AssumeRole", "sts:TagSession"]
    condition {
      test     = "BoolIfExists"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

# Attach customer-managed policies to roles

resource "aws_iam_role_policy_attachment" "billing_full_access" {
  role       = aws_iam_role.billing_full_access.name
  policy_arn = aws_iam_policy.billing_full_access.arn
}

resource "aws_iam_role_policy_attachment" "billing_view_access" {
  role       = aws_iam_role.billing_view_access.name
  policy_arn = aws_iam_policy.billing_view_access.arn
}

# ──────────────────────────────────────────────
# IAM groups
# ──────────────────────────────────────────────

resource "aws_iam_group" "billing_full_access" {
  name = "billing-full-access"
  path = "/"
}

resource "aws_iam_group" "billing_view_access" {
  name = "billing-view-access"
  path = "/"
}

# Group policies that allow members to assume the matching role

resource "aws_iam_group_policy" "billing_full_access_assume_role" {
  name  = "billing-full-access-assume-role"
  group = aws_iam_group.billing_full_access.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "sts:AssumeRole"
        Resource = aws_iam_role.billing_full_access.arn
      },
    ]
  })
}

resource "aws_iam_group_policy" "billing_view_access_assume_role" {
  name  = "billing-view-access-assume-role"
  group = aws_iam_group.billing_view_access.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "sts:AssumeRole"
        Resource = aws_iam_role.billing_view_access.arn
      },
    ]
  })
}

# ──────────────────────────────────────────────
# Outputs
# ──────────────────────────────────────────────

output "billing_full_access_role_arn" {
  description = "ARN of the billing-full-access IAM role"
  value       = aws_iam_role.billing_full_access.arn
}

output "billing_view_access_role_arn" {
  description = "ARN of the billing-view-access IAM role"
  value       = aws_iam_role.billing_view_access.arn
}

output "billing_full_access_group_arn" {
  description = "ARN of the billing-full-access IAM group"
  value       = aws_iam_group.billing_full_access.arn
}

output "billing_view_access_group_arn" {
  description = "ARN of the billing-view-access IAM group"
  value       = aws_iam_group.billing_view_access.arn
}

# Pet name suffix
resource "random_pet" "suffix" {
  length    = 2
  separator = "-"
}

locals {
  base_name = "cognito-${random_pet.suffix.id}"
  pool_name = replace(local.base_name, "-", "_")
}

# AWS context lookup (helper module equivalent)
data "aws_partition" "current" {}
data "aws_region" "current" {}
data "aws_caller_identity" "current" {}

# Random 16-character uppercase external ID for SMS configuration
resource "random_string" "external_id" {
  length  = 16
  upper   = true
  lower   = false
  numeric = true
  special = false
}

# IAM role for Cognito SMS sending - Cognito assumes this role
resource "aws_iam_role" "cognito_sms" {
  name = "${local.base_name}-sms-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "cognito-idp.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "sts:ExternalId" = random_string.external_id.result
          }
        }
      }
    ]
  })
}

resource "aws_iam_policy" "cognito_sms" {
  name = "${local.base_name}-sms-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sns:Publish"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "cognito_sms" {
  role       = aws_iam_role.cognito_sms.name
  policy_arn = aws_iam_policy.cognito_sms.arn
}

# Identity pool IAM roles
# Signed-users (authenticated) role
resource "aws_iam_role" "signed_users" {
  name = "${local.base_name}-signed-users"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = "cognito-identity.amazonaws.com"
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "cognito-identity.amazonaws.com:aud" = aws_cognito_identity_pool.this.id
          }
        }
      }
    ]
  })
}

resource "aws_iam_policy" "signed_users" {
  name = "${local.base_name}-signed-users-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "cognito-identity:GetId",
          "cognito-identity:GetOpenIdToken",
          "cognito-identity:GetCredentialsForIdentity",
          "cognito-identity:ListIdentities"
        ]
        Resource = aws_cognito_identity_pool.this.arn
      },
      {
        Effect = "Allow"
        Action = [
          "cognito-sync:ListDatasets",
          "cognito-sync:DescribeDataset",
          "cognito-sync:SubscribeToDataset",
          "cognito-sync:UnsubscribeFromDataset",
          "cognito-sync:UpdateRecords",
          "cognito-sync:QueryRecords"
        ]
        Resource = aws_cognito_identity_pool.this.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "signed_users" {
  role       = aws_iam_role.signed_users.name
  policy_arn = aws_iam_policy.signed_users.arn
}

# Anonymous-users (unauthenticated) role
resource "aws_iam_role" "anonymous_users" {
  name = "${local.base_name}-anonymous-users"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = "cognito-identity.amazonaws.com"
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "cognito-identity.amazonaws.com:aud" = aws_cognito_identity_pool.this.id
          }
        }
      }
    ]
  })
}

resource "aws_iam_policy" "anonymous_users" {
  name = "${local.base_name}-anonymous-users-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "cognito-identity:GetId",
          "cognito-identity:GetOpenIdToken",
          "cognito-identity:GetCredentialsForIdentity"
        ]
        Resource = aws_cognito_identity_pool.this.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "anonymous_users" {
  role       = aws_iam_role.anonymous_users.name
  policy_arn = aws_iam_policy.anonymous_users.arn
}

# Cognito User Pool
resource "aws_cognito_user_pool" "this" {
  name = local.pool_name

  mfa_configuration = "OFF"

  auto_verified_attributes = ["email"]

  schema {
    attribute_data_type      = "String"
    developer_only_attribute = false
    mutable                  = false
    name                     = "email"
    required                 = true
  }

  schema {
    attribute_data_type      = "String"
    developer_only_attribute = false
    mutable                  = false
    name                     = "phone_number"
    required                 = false
  }

  schema {
    attribute_data_type      = "String"
    developer_only_attribute = false
    mutable                  = true
    name                     = "profile_id"
    required                 = false
  }

  schema {
    attribute_data_type      = "String"
    developer_only_attribute = false
    mutable                  = true
    name                     = "first_name"
    required                 = false
  }

  schema {
    attribute_data_type      = "String"
    developer_only_attribute = false
    mutable                  = true
    name                     = "last_name"
    required                 = false
  }

  schema {
    attribute_data_type      = "String"
    developer_only_attribute = false
    mutable                  = true
    name                     = "gender"
    required                 = false
  }

  schema {
    attribute_data_type      = "String"
    developer_only_attribute = false
    mutable                  = true
    name                     = "age"
    required                 = false
  }

  schema {
    attribute_data_type      = "String"
    developer_only_attribute = false
    mutable                  = true
    name                     = "persona"
    required                 = false
  }

  sms_configuration {
    external_id    = random_string.external_id.result
    sns_caller_arn = aws_iam_role.cognito_sms.arn
  }
}

# Cognito User Pool Client (no client secret)
resource "aws_cognito_user_pool_client" "this" {
  name                = "${local.base_name}-client"
  user_pool_id        = aws_cognito_user_pool.this.id
  generate_secret     = false
  explicit_auth_flows = ["ALLOW_REFRESH_TOKEN_AUTH", "ALLOW_USER_SRP_AUTH"]
}

# Identity pool that allows unauthenticated identities
resource "aws_cognito_identity_pool" "this" {
  identity_pool_name               = "${local.base_name}-identity-pool"
  allow_unauthenticated_identities = true

  cognito_identity_providers {
    client_id               = aws_cognito_user_pool_client.this.id
    provider_name           = aws_cognito_user_pool.this.endpoint
    server_side_token_check = false
  }
}

# Attach the two roles to the identity pool
resource "aws_cognito_identity_pool_roles_attachment" "this" {
  identity_pool_id = aws_cognito_identity_pool.this.id

  roles = {
    "authenticated"   = aws_iam_role.signed_users.arn
    "unauthenticated" = aws_iam_role.anonymous_users.arn
  }
}

locals {
  workspace_name = terraform.workspace
  name_prefix    = "${local.workspace_name}-batch"
  account_id     = data.aws_caller_identity.current.account_id
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "ecs_optimized" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-ecs-hvm-*"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "192.168.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = local.name_prefix
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "192.168.10.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}-public"
  }
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "192.168.0.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}-private"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-igw"
  }
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "${local.name_prefix}-eip"
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  tags = {
    Name = "${local.name_prefix}-nat"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${local.name_prefix}-public-rtb"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "${local.name_prefix}-private-rtb"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "batch" {
  name        = "${local.name_prefix}-sg"
  description = "Batch compute environment security group"
  vpc_id      = aws_vpc.main.id

  egress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${local.name_prefix}-sg"
  }
}

resource "aws_kms_key" "batch" {
  description             = "Customer-managed KMS key for Batch results bucket"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "${local.name_prefix}-kms"
  }
}

resource "aws_kms_alias" "batch" {
  name          = "alias/${local.name_prefix}-kms"
  target_key_id = aws_kms_key.batch.id
}

resource "aws_s3_bucket" "results" {
  bucket = "benchmark-batch-results-${local.account_id}"

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "${local.name_prefix}-results"
  }
}

resource "aws_s3_bucket_public_access_block" "results" {
  bucket = aws_s3_bucket.results.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "results" {
  bucket = aws_s3_bucket.results.bucket

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.batch.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_iam_role" "ecs_instance" {
  name = "${local.name_prefix}-ecs-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "${local.name_prefix}-ecs-instance-role"
  }
}

resource "aws_iam_role_policy_attachment" "ecs_for_ec2" {
  role       = aws_iam_role.ecs_instance.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2ContainerServiceforEC2Role"
}

resource "aws_iam_policy" "ecs_s3" {
  name        = "${local.name_prefix}-ecs-s3-policy"
  description = "Custom S3 policy for Batch ECS instances"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3GeneralList"
        Effect = "Allow"
        Action = [
          "s3:ListAllMyBuckets",
          "s3:GetBucketLocation"
        ]
        Resource = ["arn:aws:s3:::*"]
      },
      {
        Sid    = "S3ReadListResults"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Resource = [
          "arn:aws:s3:::benchmark-batch-results-${local.account_id}",
          "arn:aws:s3:::benchmark-batch-results-${local.account_id}/*"
        ]
      },
      {
        Sid    = "S3WriteDeleteResults"
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = ["arn:aws:s3:::benchmark-batch-results-${local.account_id}/*"]
      },
      {
        Sid    = "KMSDecryptAndGenerateDataKey"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = [aws_kms_key.batch.arn]
      }
    ]
  })

  tags = {
    Name = "${local.name_prefix}-ecs-s3"
  }
}

resource "aws_iam_role_policy_attachment" "ecs_s3" {
  role       = aws_iam_role.ecs_instance.name
  policy_arn = aws_iam_policy.ecs_s3.arn
}

resource "aws_iam_instance_profile" "ecs" {
  name = "${local.name_prefix}-ecs-instance-profile"
  role = aws_iam_role.ecs_instance.name

  tags = {
    Name = "${local.name_prefix}-ecs-instance-profile"
  }
}

resource "aws_iam_role" "batch_service" {
  name = "${local.name_prefix}-batch-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "batch.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  inline_policy {
    name = "ecs-access"

    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Effect = "Allow"
          Action = [
            "ecs:DescribeClusters",
            "ecs:CreateCluster",
            "ecs:DeleteCluster",
            "ecs:ListClusters",
            "ecs:ListContainerInstances",
            "ecs:DescribeContainerInstances",
            "ecs:RunTask",
            "ecs:StartTask",
            "ecs:StopTask"
          ]
          Resource = ["*"]
        },
        {
          Effect = "Allow"
          Action = "iam:PassRole"
          Resource = [aws_iam_role.ecs_instance.arn]
        }
      ]
    })
  }

  tags = {
    Name = "${local.name_prefix}-batch-service"
  }
}

resource "aws_iam_role_policy_attachment" "batch_service" {
  role       = aws_iam_role.batch_service.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBatchServiceRole"
}

resource "aws_batch_compute_environment" "batch" {
  name = local.name_prefix
  type                     = "MANAGED"
  state                    = "ENABLED"

  compute_resources {
    allocation_strategy = "BEST_FIT"
    instance_type       = ["optimal"]
    image_id           = data.aws_ami.ecs_optimized.id
    instance_role       = aws_iam_instance_profile.ecs.arn
    security_group_ids  = [aws_security_group.batch.id]
    subnets          = [aws_subnet.private.id]
    type                = "EC2"

    min_vcpus = 0
    max_vcpus = 4
  }

  service_role = aws_iam_role.batch_service.arn

  depends_on = [aws_iam_role_policy_attachment.batch_service]

  tags = {
    Name = local.name_prefix
  }
}

resource "aws_batch_job_queue" "batch" {
  name     = "${local.name_prefix}-queue"
  state     = "ENABLED"
  priority  = 1

  compute_environment_order {
    compute_environment = aws_batch_compute_environment.batch.arn
    order               = 0
  }

  tags = {
    Name = "${local.name_prefix}-queue"
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  account_id  = data.aws_caller_identity.current.account_id
  region      = data.aws_region.current.region
  partition   = data.aws_partition.current.partition
  bucket_name = "endpoint-backup-${local.account_id}"
}

# -------------------------------------------------------------------------
# KMS Key for S3 Bucket Encryption
# -------------------------------------------------------------------------

resource "aws_kms_key" "this" {
  description             = "KMS key for endpoint-backup S3 bucket encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_kms_alias" "this" {
  name          = "alias/endpoint-backup-s3-key"
  target_key_id = aws_kms_key.this.key_id
}

# -------------------------------------------------------------------------
# S3 Bucket
# -------------------------------------------------------------------------

resource "aws_s3_bucket" "this" {
  bucket = local.bucket_name

  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.this.arn
    }
  }
}

# Bucket policy
data "aws_iam_policy_document" "bucket_policy" {
  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"
    principals {
      type        = "AWS"
      identifiers = ["*"]
    }
    actions = [
      "s3:*",
    ]
    resources = [
      aws_s3_bucket.this.arn,
      "${aws_s3_bucket.this.arn}/*",
    ]
    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid    = "DenyTLSBelow12"
    effect = "Deny"
    principals {
      type        = "AWS"
      identifiers = ["*"]
    }
    actions = [
      "s3:*",
    ]
    resources = [
      aws_s3_bucket.this.arn,
      "${aws_s3_bucket.this.arn}/*",
    ]
    condition {
      test     = "StringNotEquals"
      variable = "aws:TlsVersion"
      values   = ["TLSv1.2", "TLSv1.3"]
    }
  }

  statement {
    sid    = "DenyComplianceLockOver90Days"
    effect = "Deny"
    principals {
      type        = "AWS"
      identifiers = ["*"]
    }
    actions = [
      "s3:PutObject",
      "s3:PutObjectRetention",
    ]
    resources = [
      "${aws_s3_bucket.this.arn}/*",
    ]
    condition {
      test     = "StringEquals"
      variable = "s3:object-lock-mode"
      values   = ["COMPLIANCE"]
    }
    condition {
      test     = "NumericGreaterThan"
      variable = "s3:object-lock-remaining-retention-days"
      values   = ["90"]
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = data.aws_iam_policy_document.bucket_policy.json
}

# -------------------------------------------------------------------------
# IAM User and Policy
# -------------------------------------------------------------------------

resource "aws_iam_user" "this" {
  name = "endpoint-backup"
}

data "aws_iam_policy_document" "bucket_access" {
  statement {
    sid    = "ListBucket"
    effect = "Allow"
    actions = [
      "s3:ListBucket",
      "s3:ListBucketVersions",
      "s3:GetBucketLocation",
      "s3:GetBucketVersioning",
    ]
    resources = [
      aws_s3_bucket.this.arn,
    ]
  }

  statement {
    sid    = "ReadWriteDeleteVersionRetentionRestore"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:GetObjectRetention",
      "s3:GetObjectLegalHold",
      "s3:PutObject",
      "s3:PutObjectRetention",
      "s3:PutObjectLegalHold",
      "s3:DeleteObject",
      "s3:DeleteObjectVersion",
      "s3:RestoreObject",
    ]
    resources = [
      "${aws_s3_bucket.this.arn}/*",
    ]
  }

  statement {
    sid    = "KMSDecryptDataKey"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
    ]
    resources = [
      aws_kms_key.this.arn,
      "arn:${local.partition}:kms:${local.region}:${local.account_id}:key/aws/s3",
      "arn:${local.partition}:kms:${local.region}:${local.account_id}:alias/aws/s3",
    ]
  }
}

resource "aws_iam_policy" "this" {
  name        = "endpoint-backup-bucket-read-write-access"
  description = "Grants list, read, write, delete, version, retention, and restore access to the endpoint-backup bucket and decrypt/data-key access on the AWS-managed S3 KMS key"
  policy      = data.aws_iam_policy_document.bucket_access.json
}

resource "aws_iam_user_policy_attachment" "this" {
  user       = aws_iam_user.this.name
  policy_arn = aws_iam_policy.this.arn
}

