# ---------------------------------------------------------------------------
# Cognito User Pool
# ---------------------------------------------------------------------------

resource "aws_cognito_user_pool" "this" {
  name = "unity-shared-services-user-pool"

  admin_create_user_config {
    allow_admin_create_user_only = true

    invite_message_template {
      email_message = "You have been invited to join Unity Shared Services. Your username is {username} and your temporary password is {####}. Please sign in to access the platform."
      email_subject = "Invitation to join Unity Shared Services"
      sms_message   = "You have been invited to join Unity Shared Services. Your username is {username} and your temporary password is {####}."
    }
  }

  account_recovery_setting {
    recovery_mechanism {
      name     = "verified_email"
      priority = 1
    }
  }

  username_configuration {
    case_sensitive = false
  }

  auto_verified_attributes = ["email"]

  email_configuration {
    email_sending_account = "COGNITO_DEFAULT"
  }

  verification_message_template {
    default_email_option = "CONFIRM_WITH_LINK"
    email_message        = "Please confirm your account. Your verification code is {####}"
    email_subject        = "Verify your email for Unity Shared Services"
    sms_message          = "Your verification code for Unity Shared Services is {####}"
  }

  schema {
    attribute_data_type      = "String"
    developer_only_attribute = false
    mutable                 = true
    name                    = "email"
    required               = true
  }

  schema {
    attribute_data_type      = "String"
    developer_only_attribute = false
    mutable                 = false
    name                    = "sub"
    required               = true
  }

  tags = {
    Name = "unity-shared-services-user-pool"
  }
}

