variable "app_name" {
  description = "Application name used for resource tagging"
  type        = string
  default     = "terraform"
}

variable "environment" {
  description = "Environment name used for resource tagging"
  type        = string
  default     = "testing"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for the three public subnets (ordered by AZ)"
  type        = list(string)
  default     = ["10.0.10.0/24", "10.0.20.0/24", "10.0.30.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for the three private subnets (ordered by AZ)"
  type        = list(string)
  default     = ["10.0.11.0/24", "10.0.22.0/24", "10.0.33.0/24"]
}

variable "transit_gateway_id" {
  description = "Optional existing transit gateway ID for VPC attachment (disabled by default)"
  type        = string
  default     = null
}

variable "enable_ipv6_egress" {
  description = "Enable IPv6 egress-only internet gateway and assign IPv6 CIDR block to the VPC"
  type        = bool
  default     = false
}

locals {
  name_prefix = "${var.app_name}-${var.environment}"
  azs         = slice(data.aws_availability_zones.available.names, 0, 3)
}

data "aws_availability_zones" "available" {
  state = "available"
}

# ─────────────────────────────────────────────────────────────
# VPC
# ─────────────────────────────────────────────────────────────
resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr
  enable_dns_hostnames             = false
  enable_dns_support               = true
  assign_generated_ipv6_cidr_block = var.enable_ipv6_egress

  tags = {
    Name        = "vpc-${local.name_prefix}"
    App         = var.app_name
    Environment = var.environment
  }
}

# ─────────────────────────────────────────────────────────────
# Public Subnets (one per AZ)
# ─────────────────────────────────────────────────────────────
resource "aws_subnet" "public" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name        = "${local.name_prefix}-public-${count.index + 1}"
    Type        = "public"
    App         = var.app_name
    Environment = var.environment
  }
}

# ─────────────────────────────────────────────────────────────
# Private Subnets (one per AZ)
# ─────────────────────────────────────────────────────────────
resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = {
    Name        = "${local.name_prefix}-private-${count.index + 1}"
    Type        = "private"
    App         = var.app_name
    Environment = var.environment
  }
}

# ─────────────────────────────────────────────────────────────
# Internet Gateway
# ─────────────────────────────────────────────────────────────
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "${local.name_prefix}-igw"
    App         = var.app_name
    Environment = var.environment
  }
}

# ─────────────────────────────────────────────────────────────
# Public Route Table + Default Route + Associations
# ─────────────────────────────────────────────────────────────
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "${local.name_prefix}-public-rt"
    App         = var.app_name
    Environment = var.environment
  }
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ─────────────────────────────────────────────────────────────
# Elastic IP + Single NAT Gateway (in first public subnet)
# ─────────────────────────────────────────────────────────────
resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name        = "${local.name_prefix}-nat-eip"
    App         = var.app_name
    Environment = var.environment
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name        = "${local.name_prefix}-nat"
    App         = var.app_name
    Environment = var.environment
  }

  depends_on = [aws_internet_gateway.main]
}

# ─────────────────────────────────────────────────────────────
# Private Route Table (shared) + NAT Route + Associations
# ─────────────────────────────────────────────────────────────
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "${local.name_prefix}-private-rt"
    App         = var.app_name
    Environment = var.environment
  }
}

resource "aws_route" "private_nat" {
  route_table_id         = aws_route_table.private.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main.id
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# ─────────────────────────────────────────────────────────────
# DB Subnet Group (spans the three private subnets)
# ─────────────────────────────────────────────────────────────
resource "aws_db_subnet_group" "main" {
  name        = "db-subnet-${local.name_prefix}"
  description = "DB subnet group for ${local.name_prefix}"
  subnet_ids  = aws_subnet.private[*].id

  tags = {
    Name        = "db-subnet-${local.name_prefix}"
    App         = var.app_name
    Environment = var.environment
  }
}

# ─────────────────────────────────────────────────────────────
# Optional: Transit Gateway VPC Attachment
# ─────────────────────────────────────────────────────────────
resource "aws_ec2_transit_gateway_vpc_attachment" "main" {
  count              = var.transit_gateway_id != null ? 1 : 0
  transit_gateway_id = var.transit_gateway_id
  vpc_id             = aws_vpc.main.id
  subnet_ids         = aws_subnet.private[*].id

  tags = {
    Name        = "${local.name_prefix}-tgw-attachment"
    App         = var.app_name
    Environment = var.environment
  }
}

# ─────────────────────────────────────────────────────────────
# Optional: IPv6 Egress-only Internet Gateway (disabled by default)
# ─────────────────────────────────────────────────────────────
resource "aws_egress_only_internet_gateway" "main" {
  count  = var.enable_ipv6_egress ? 1 : 0
  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "${local.name_prefix}-eigw"
    App         = var.app_name
    Environment = var.environment
  }
}

resource "aws_route" "private_ipv6_egress" {
  count                           = var.enable_ipv6_egress ? 1 : 0
  route_table_id                  = aws_route_table.private.id
  destination_ipv6_cidr_block     = "::/0"
  egress_only_gateway_id = aws_egress_only_internet_gateway.main[0].id
}

# ─────────────────────────────────────────────────────────────
# Outputs
# ─────────────────────────────────────────────────────────────
output "vpc_id" {
  description = "The ID of the VPC"
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "The CIDR block of the VPC"
  value       = aws_vpc.main.cidr_block
}

output "vpc_default_security_group_id" {
  description = "The ID of the VPC default security group"
  value       = aws_vpc.main.default_security_group_id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets"
  value       = aws_subnet.private[*].id
}

output "public_subnet_cidrs" {
  description = "CIDR blocks of the public subnets"
  value       = aws_subnet.public[*].cidr_block
}

output "private_subnet_cidrs" {
  description = "CIDR blocks of the private subnets"
  value       = aws_subnet.private[*].cidr_block
}

output "nat_gateway_id" {
  description = "The ID of the NAT gateway"
  value       = aws_nat_gateway.main.id
}

output "nat_gateway_public_ip" {
  description = "The public IP address of the NAT gateway"
  value       = aws_eip.nat.public_ip
}

output "db_subnet_group_name" {
  description = "The name of the DB subnet group"
  value       = aws_db_subnet_group.main.name
}

output "transit_gateway_attachment_id" {
  description = "The ID of the transit gateway VPC attachment (null if not created)"
  value       = var.transit_gateway_id != null ? aws_ec2_transit_gateway_vpc_attachment.main[0].id : null
}

output "internet_gateway_id" {
  description = "The ID of the internet gateway"
  value       = aws_internet_gateway.main.id
}

locals {
  user_name           = "gitops-bridge-gitops"
  policy_name         = "gitops-bridge-gitops"
  private_key_path    = pathexpand("~/.ssh/gitops_ssh.pem")
  ssh_config_path     = pathexpand("~/.ssh/config")
  repo_names          = ["gitops-apps", "gitops-platform", "gitops-addons"]
  ssh_config_content  = <<-EOT
Host git-codecommit.*.amazonaws.com
  User ${aws_iam_user_ssh_key.gitops.ssh_public_key_id}
  IdentityFile ${pathexpand("~/.ssh/gitops_ssh.pem")}
EOT
}

# Random suffix for the secret name
resource "random_string" "suffix" {
  length  = 5
  special = false
  upper   = false
}

# Data sources for account/region metadata
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

# TLS RSA key pair (4096-bit)
resource "tls_private_key" "gitops" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

# IAM user for the GitOps bridge
resource "aws_iam_user" "gitops" {
  name = local.user_name
}

# Upload SSH public key to the IAM user
resource "aws_iam_user_ssh_key" "gitops" {
  username   = aws_iam_user.gitops.name
  encoding   = "SSH"
  public_key = tls_private_key.gitops.public_key_openssh
}

# IAM policy granting Git pull/push to only the three repositories
resource "aws_iam_policy" "gitops" {
  name        = local.policy_name
  description = "Grants Git pull and push access to the GitOps bridge repositories"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CodeCommitGitAccess"
        Effect = "Allow"
        Action = [
          "codecommit:GitPull",
          "codecommit:GitPush"
        ]
        Resource = [
          for repo in local.repo_names :
          "arn:${data.aws_partition.current.partition}:codecommit:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:${repo}"
        ]
      }
    ]
  })
}

# Attach the policy to the IAM user
resource "aws_iam_user_policy_attachment" "gitops" {
  user       = aws_iam_user.gitops.name
  policy_arn = aws_iam_policy.gitops.arn
}

# Three CodeCommit repositories
resource "aws_codecommit_repository" "apps" {
  repository_name = "gitops-apps"
  description     = "Argo CD GitOps application definitions"
}

resource "aws_codecommit_repository" "platform" {
  repository_name = "gitops-platform"
  description     = "Argo CD GitOps platform configuration"
}

resource "aws_codecommit_repository" "addons" {
  repository_name = "gitops-addons"
  description     = "Argo CD GitOps add-on definitions"
}

# Secrets Manager secret for the private key
resource "aws_secretsmanager_secret" "gitops_key" {
  name                    = "codecommit-key-${random_string.suffix.result}"
  description             = "SSH private key for gitops-bridge-gitops user to access CodeCommit repositories"
  recovery_window_in_days = 0
}

resource "aws_secretsmanager_secret_version" "gitops_key" {
  secret_id = aws_secretsmanager_secret.gitops_key.id
  secret_string = jsonencode({
    private_key = tls_private_key.gitops.private_key_pem
    public_key  = tls_private_key.gitops.public_key_openssh
    ssh_key_id  = aws_iam_user_ssh_key.gitops.ssh_public_key_id
    user_name   = aws_iam_user.gitops.name
  })
}

# Write the private key to ~/.ssh/gitops_ssh.pem
resource "local_sensitive_file" "private_key" {
  filename        = local.private_key_path
  content         = tls_private_key.gitops.private_key_pem
  file_permission = "0600"
}

# Write SSH config entry for CodeCommit
resource "local_file" "ssh_config" {
  filename        = local.ssh_config_path
  content         = local.ssh_config_content
  file_permission = "0600"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

data "aws_ami" "ubuntu" {
  most_recent = true
  owners      = ["099720109477"]
  filter {
    name   = "name"
    values = ["ubuntu/images/hvm-ssd/ubuntu-jammy-22.04-amd64-server-*"]
  }
  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

variable "ssh_public_key" {
  description = "Public key material for the benchmark SSH key pair"
  type        = string
  default = "ssh-rsa  benchmark-d8bc612be4e0-key"
}

variable "extra_ebs_volumes" {
  description = "Optional list of additional EBS volume definitions to attach to the instance"
  type = list(object({
    device_name = string
    volume_size = number
    volume_type = optional(string, "gp2")
    encrypted   = optional(bool, true)
  }))
  default = []
}

variable "additional_network_interfaces" {
  description = "Optional list of additional network interface configurations with optional Elastic IPs"
  type = list(object({
    subnet_id           = string
    security_group_ids  = list(string)
    associate_public_ip = optional(bool, false)
    create_eip          = optional(bool, false)
  }))
  default = []
}

locals {
  region     = data.aws_region.current.region
  account_id = data.aws_caller_identity.current.account_id
}

resource "aws_vpc" "main" {
  cidr_block           = "10.70.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "benchmark-vpc"
  }
}

resource "aws_subnet" "main" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.70.0.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "benchmark-subnet"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "benchmark-igw"
  }
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "benchmark-route-table"
  }
}

resource "aws_route_table_association" "main" {
  subnet_id      = aws_subnet.main.id
  route_table_id = aws_route_table.main.id
}

resource "aws_security_group" "main" {
  name        = "benchmark-sg"
  description = "Dedicated security group for benchmark instance - egress only to VPC CIDR, no ingress"
  vpc_id      = aws_vpc.main.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "benchmark-sg"
  }
}

resource "aws_key_pair" "benchmark" {
  key_name   = "benchmark-d8bc612be4e0-key"
  public_key = var.ssh_public_key
}

resource "aws_iam_role" "benchmark" {
  name = "benchmark-iam-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "benchmark" {
  name = "benchmark-iam-policy"
  role = aws_iam_role.benchmark.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:DescribeInstances"
        ]
        Resource = [
          "arn:aws:ec2:${local.region}:${local.account_id}:instance/*"
        ]
      }
    ]
  })
}

resource "aws_iam_instance_profile" "benchmark" {
  name = "benchmark-instance-profile"
  role = aws_iam_role.benchmark.name
}

resource "aws_kms_key" "benchmark" {
  description             = "KMS key for benchmark instance EBS volume encryption"
  deletion_window_in_days = 7
}

resource "aws_instance" "benchmark" {
  instance_type              = "t2.micro"
  ami                        = data.aws_ami.ubuntu.id
  subnet_id                  = aws_subnet.main.id
  vpc_security_group_ids     = [aws_security_group.main.id]
  key_name                   = aws_key_pair.benchmark.id
  iam_instance_profile       = aws_iam_instance_profile.benchmark.name
  associate_public_ip_address = true
  monitoring                 = true

  root_block_device {
    volume_type = "gp2"
    volume_size = 10
    encrypted   = true
    kms_key_id  = aws_kms_key.benchmark.id
  }

  metadata_options {
    http_tokens          = "required"
    http_put_response_hop_limit = 1
    http_endpoint        = "enabled"
  }

  tags = {
    Name = "benchmark-instance"
  }
}

resource "aws_eip" "benchmark" {
  domain = "vpc"

  tags = {
    Name = "benchmark-eip"
  }
}

resource "aws_eip_association" "benchmark" {
  instance_id = aws_instance.benchmark.id
  public_ip   = aws_eip.benchmark.public_ip
}

resource "aws_cloudwatch_metric_alarm" "benchmark" {
  alarm_name          = "benchmark-status-check-failed"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = 5
  metric_name         = "StatusCheckFailed_Instance"
  namespace           = "AWS/EC2"
  period              = 60
  statistic           = "Maximum"
  threshold           = 1
  alarm_description   = "Reboot instance when StatusCheckFailed_Instance >= 1 for 5 consecutive 60-second periods"
  alarm_actions       = ["arn:aws:automate:${local.region}:ec2:reboot"]

  dimensions = {
    InstanceId = aws_instance.benchmark.id
  }
}

provider "aws" {
  alias  = "source1"
  region = "us-east-1"
}

provider "aws" {
  alias  = "source2"
  region = "us-west-2"
}

provider "aws" {
  alias  = "replica1"
  region = "eu-west-1"
}

provider "aws" {
  alias  = "replica2"
  region = "ap-southeast-1"
}

locals {
  account_id = data.aws_caller_identity.current.account_id
  source1_region  = "us-east-1"
  source2_region  = "us-west-2"
  replica1_region = "eu-west-1"
  replica2_region = "ap-southeast-1"

  source1_bucket_names = [
    "log1a.veerum-${local.account_id}",
    "log1b.veerum-${local.account_id}",
  ]
  source2_bucket_names = [
    "log2a.veerum-${local.account_id}",
    "log2b.veerum-${local.account_id}",
  ]
  all_source_bucket_names = concat(local.source1_bucket_names, local.source2_bucket_names)

  # Replica bucket names: strip "-<account_id>" suffix, add "-replica1-<account_id>" or "-replica2-<account_id>"
  replica1_bucket_names = [
    for b in local.all_source_bucket_names :
    "${replace(b, "-${local.account_id}", "")}-replica1-${local.account_id}"
  ]
  replica2_bucket_names = [
    for b in local.all_source_bucket_names :
    "${replace(b, "-${local.account_id}", "")}-replica2-${local.account_id}"
  ]

  # Bucket ARN helpers
  source_bucket_arns       = [for b in local.all_source_bucket_names : "arn:aws:s3:::${b}"]
  source_bucket_arn_wild   = [for b in local.all_source_bucket_names : "arn:aws:s3:::${b}/*"]
  replica1_bucket_arn_wild = [for b in local.replica1_bucket_names : "arn:aws:s3:::${b}/*"]
  replica2_bucket_arn_wild = [for b in local.replica2_bucket_names : "arn:aws:s3:::${b}/*"]
}

data "aws_caller_identity" "current" {}

# ---------------------------------------------------------------------------
# IAM role and policy for S3 replication
# ---------------------------------------------------------------------------
resource "aws_iam_role" "replication" {
  name = "s3-replication-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = {
    Env = "dev"
  }
}

resource "aws_iam_policy" "replication" {
  name        = "s3-replication-policy"
  description = "Policy for S3 cross-region replication"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ReadSourceBucketConfig"
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket",
        ]
        Resource = local.source_bucket_arns
      },
      {
        Sid    = "ReadSourceObjectVersions"
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging",
          "s3:GetObjectVersionAttributes",
        ]
        Resource = local.source_bucket_arn_wild
      },
      {
        Sid    = "ReplicateToDestinations"
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
          "s3:GetObjectRetention",
          "s3:PutObjectRetention",
        ]
        Resource = concat(local.replica1_bucket_arn_wild, local.replica2_bucket_arn_wild)
      },
      {
        Sid    = "DecryptSourceKMS"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
        ]
        Resource = [
          "arn:aws:kms:${local.source1_region}:${local.account_id}:key/*",
          "arn:aws:kms:${local.source2_region}:${local.account_id}:key/*",
        ]
      },
      {
        Sid    = "EncryptReplicaKMS"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:GenerateDataKey",
        ]
        Resource = [
          "arn:aws:kms:${local.replica1_region}:${local.account_id}:key/*",
          "arn:aws:kms:${local.replica2_region}:${local.account_id}:key/*",
        ]
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "replication" {
  role       = aws_iam_role.replication.name
  policy_arn = aws_iam_policy.replication.arn
}

# ---------------------------------------------------------------------------
# KMS keys per region
# ---------------------------------------------------------------------------
resource "aws_kms_key" "sourcekey1" {
  provider                = aws.source1
  description             = "Source key 1 for S3 replication"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAdmin"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowReplicationRoleDecrypt"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.replication.arn
        }
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey",
          "kms:GenerateDataKey",
        ]
        Resource = "*"
      },
    ]
  })
  tags = {
    Env = "dev"
  }
}

resource "aws_kms_alias" "sourcekey1" {
  provider      = aws.source1
  name          = "alias/sourcekey1"
  target_key_id = aws_kms_key.sourcekey1.key_id
}

resource "aws_kms_key" "sourcekey2" {
  provider                = aws.source2
  description             = "Source key 2 for S3 replication"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAdmin"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowReplicationRoleDecrypt"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.replication.arn
        }
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey",
          "kms:GenerateDataKey",
        ]
        Resource = "*"
      },
    ]
  })
  tags = {
    Env = "dev"
  }
}

resource "aws_kms_alias" "sourcekey2" {
  provider      = aws.source2
  name          = "alias/sourcekey2"
  target_key_id = aws_kms_key.sourcekey2.key_id
}

resource "aws_kms_key" "replicakey1" {
  provider                = aws.replica1
  description             = "Replica key 1 for S3 replication"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAdmin"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowReplicationRoleEncrypt"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.replication.arn
        }
        Action = [
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey",
        ]
        Resource = "*"
      },
    ]
  })
  tags = {
    Env = "dev"
  }
}

resource "aws_kms_alias" "replicakey1" {
  provider      = aws.replica1
  name          = "alias/replicakey1"
  target_key_id = aws_kms_key.replicakey1.key_id
}

resource "aws_kms_key" "replicakey2" {
  provider                = aws.replica2
  description             = "Replica key 2 for S3 replication"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAdmin"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowReplicationRoleEncrypt"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.replication.arn
        }
        Action = [
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey",
        ]
        Resource = "*"
      },
    ]
  })
  tags = {
    Env = "dev"
