resource "aws_kms_alias" "replicakey2" {
  provider      = aws.replica2
  name          = "alias/replicakey2"
  target_key_id = aws_kms_key.replicakey2.key_id
}

# ---------------------------------------------------------------------------
# Helper: function to map source bucket name to replica bucket name
# ---------------------------------------------------------------------------
locals {
  # For a source bucket "logXx.veerum-<account>", returns "logXx.veerum-replicaN-<account>"
  source_to_replica1 = {
    for b in local.all_source_bucket_names :
    b => "${replace(b, "-${local.account_id}", "")}-replica1-${local.account_id}"
  }
  source_to_replica2 = {
    for b in local.all_source_bucket_names :
    b => "${replace(b, "-${local.account_id}", "")}-replica2-${local.account_id}"
  }
}

# ---------------------------------------------------------------------------
# Source buckets in source region 1 (us-east-1)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "source1" {
  provider = aws.source1
  for_each = toset(local.source1_bucket_names)
  bucket   = each.key
  tags = {
    Env = "dev"
  }
}

resource "aws_s3_bucket_versioning" "source1" {
  provider = aws.source1
  for_each = aws_s3_bucket.source1
  bucket   = each.value.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "source1" {
  provider = aws.source1
  for_each = aws_s3_bucket.source1
  bucket   = each.value.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.sourcekey1.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "source1" {
  provider = aws.source1
  for_each = aws_s3_bucket.source1
  bucket   = each.value.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ---------------------------------------------------------------------------
# Source buckets in source region 2 (us-west-2)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "source2" {
  provider = aws.source2
  for_each = toset(local.source2_bucket_names)
  bucket   = each.key
  tags = {
    Env = "dev"
  }
}

resource "aws_s3_bucket_versioning" "source2" {
  provider = aws.source2
  for_each = aws_s3_bucket.source2
  bucket   = each.value.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "source2" {
  provider = aws.source2
  for_each = aws_s3_bucket.source2
  bucket   = each.value.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.sourcekey2.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "source2" {
  provider = aws.source2
  for_each = aws_s3_bucket.source2
  bucket   = each.value.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ---------------------------------------------------------------------------
# Replica buckets in replica region 1 (eu-west-1)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "replica1" {
  provider = aws.replica1
  for_each = toset(local.replica1_bucket_names)
  bucket   = each.key
  tags = {
    Env = "dev"
  }
}

resource "aws_s3_bucket_versioning" "replica1" {
  provider = aws.replica1
  for_each = aws_s3_bucket.replica1
  bucket   = each.value.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica1" {
  provider = aws.replica1
  for_each = aws_s3_bucket.replica1
  bucket   = each.value.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.replicakey1.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "replica1" {
  provider = aws.replica1
  for_each = aws_s3_bucket.replica1
  bucket   = each.value.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Allow replication from source buckets into replica1 buckets
resource "aws_s3_bucket_policy" "replica1" {
  provider = aws.replica1
  for_each = aws_s3_bucket.replica1
  bucket   = each.value.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3Replication"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
          "s3:ObjectOwnerOverrideToBucketOwner",
        ]
        Resource = "arn:aws:s3:::${each.key}/*"
        Condition = {
          StringEquals = {
            "aws:SourceArn" = local.source_bucket_arns
          }
        }
      },
    ]
  })
}

# ---------------------------------------------------------------------------
# Replica buckets in replica region 2 (ap-southeast-1)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "replica2" {
  provider = aws.replica2
  for_each = toset(local.replica2_bucket_names)
  bucket   = each.key
  tags = {
    Env = "dev"
  }
}

resource "aws_s3_bucket_versioning" "replica2" {
  provider = aws.replica2
  for_each = aws_s3_bucket.replica2
  bucket   = each.value.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica2" {
  provider = aws.replica2
  for_each = aws_s3_bucket.replica2
  bucket   = each.value.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.replicakey2.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "replica2" {
  provider = aws.replica2
  for_each = aws_s3_bucket.replica2
  bucket   = each.value.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Allow replication from source buckets into replica2 buckets
resource "aws_s3_bucket_policy" "replica2" {
  provider = aws.replica2
  for_each = aws_s3_bucket.replica2
  bucket   = each.value.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3Replication"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
          "s3:ObjectOwnerOverrideToBucketOwner",
        ]
        Resource = "arn:aws:s3:::${each.key}/*"
        Condition = {
          StringEquals = {
            "aws:SourceArn" = local.source_bucket_arns
          }
        }
      },
    ]
  })
}

# ---------------------------------------------------------------------------
# Replication rules on source buckets in source region 1 (us-east-1)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_replication_configuration" "source1" {
  provider   = aws.source1
  for_each   = aws_s3_bucket.source1
  bucket     = each.value.id
  role       = aws_iam_role.replication.arn

  rule {
    id       = "replicate-to-replica1"
    status   = "Enabled"
    priority = 1

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = "arn:aws:s3:::${local.source_to_replica1[each.key]}"
      storage_class = "STANDARD"
      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replicakey1.arn
      }
    }
  }

  rule {
    id       = "replicate-to-replica2"
    status   = "Enabled"
    priority = 2

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = "arn:aws:s3:::${local.source_to_replica2[each.key]}"
      storage_class = "STANDARD"
      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replicakey2.arn
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.source1,
    aws_s3_bucket_policy.replica1,
    aws_s3_bucket_policy.replica2,
  ]
}

# ---------------------------------------------------------------------------
# Replication rules on source buckets in source region 2 (us-west-2)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_replication_configuration" "source2" {
  provider   = aws.source2
  for_each   = aws_s3_bucket.source2
  bucket     = each.value.id
  role       = aws_iam_role.replication.arn

  rule {
    id       = "replicate-to-replica1"
    status   = "Enabled"
    priority = 1

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = "arn:aws:s3:::${local.source_to_replica1[each.key]}"
      storage_class = "STANDARD"
      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replicakey1.arn
      }
    }
  }

  rule {
    id       = "replicate-to-replica2"
    status   = "Enabled"
    priority = 2

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = "arn:aws:s3:::${local.source_to_replica2[each.key]}"
      storage_class = "STANDARD"
      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replicakey2.arn
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.source2,
    aws_s3_bucket_policy.replica1,
    aws_s3_bucket_policy.replica2,
  ]
}

# GuardDuty Terraform Configuration
terraform {
  required_providers {
    aws  = { source = "hashicorp/aws", version = "~> 5.0" }
    null = { source = "hashicorp/null", version = "~> 3.0" }
  }
}

# Variables with defaults — none create resources by default
variable "create_findings_filter" {
  description = "Whether to create a GuardDuty findings filter"
  type        = bool
  default     = false
}

variable "create_trusted_ip_set" {
  description = "Whether to create a trusted IP set"
  type        = bool
  default     = false
}

variable "create_threat_intel_set" {
  description = "Whether to create a threat intelligence set"
  type        = bool
  default     = false
}

variable "create_malware_protection_plan" {
  description = "Whether to create a malware protection plan for S3 buckets"
  type        = bool
  default     = false
}

variable "create_export_destination" {
  description = "Whether to create the GuardDuty publishing destination (S3 bucket, KMS key, replication role)"
  type        = bool
  default     = false
}

variable "repo_url" {
  description = "Repository URL used for tagging GuardDuty resources"
  type        = string
  default     = "https://github.com/example/guardduty-terraform"
}

variable "findings_filter_name" {
  description = "Name of the findings filter"
  type        = string
  default     = "default-filter"
}

variable "trusted_ip_set_name" {
  description = "Name of the trusted IP set"
  type        = string
  default     = "default-trusted-ip-set"
}

variable "threat_intel_set_name" {
  description = "Name of the threat intelligence set"
  type        = string
  default     = "default-threat-intel-set"
}

variable "export_bucket_name_prefix" {
  description = "Prefix for the export S3 bucket name"
  type        = string
  default     = "guardduty-export"
}

variable "replication_region" {
  description = "AWS region for cross-region S3 replication"
  type        = string
  default     = "us-west-2"
}

# Data sources for provider metadata
data "aws_region" "current" {}

data "aws_caller_identity" "current" {}



# ---------------------------------------------------------------------------
# 1. GuardDuty Detector
# ---------------------------------------------------------------------------
resource "aws_guardduty_detector" "main" {
  enable                       = true
  finding_publishing_frequency = "FIFTEEN_MINUTES"

  tags = {
    Repo = var.repo_url
  }
}

# ---------------------------------------------------------------------------
# 2. Detector Features
# ---------------------------------------------------------------------------
resource "aws_guardduty_detector_feature" "s3_data_events" {
  detector_id = aws_guardduty_detector.main.id
  name        = "S3_DATA_EVENTS"
  status      = "ENABLED"
}

resource "aws_guardduty_detector_feature" "rds_login_events" {
  detector_id = aws_guardduty_detector.main.id
  name        = "RDS_LOGIN_EVENTS"
  status      = "ENABLED"
}

resource "aws_guardduty_detector_feature" "lambda_network_logs" {
  detector_id = aws_guardduty_detector.main.id
  name        = "LAMBDA_NETWORK_LOGS"
  status      = "ENABLED"
}

resource "aws_guardduty_detector_feature" "eks_audit_logs" {
  detector_id = aws_guardduty_detector.main.id
  name        = "EKS_AUDIT_LOGS"
  status      = "ENABLED"
}

resource "aws_guardduty_detector_feature" "ebs_malware_protection" {
  detector_id = aws_guardduty_detector.main.id
  name        = "EBS_MALWARE_PROTECTION"
  status      = "ENABLED"
}

# Runtime monitoring for EC2, ECS Fargate, and EKS.
# Automatic agent management is disabled; only runtime monitoring is
# activated. RUNTIME_MONITORING = ENABLED turns on runtime monitoring,
# while the additional configurations for agent management are DISABLED.
resource "aws_guardduty_detector_feature" "runtime_monitoring" {
  detector_id = aws_guardduty_detector.main.id
  name        = "RUNTIME_MONITORING"
  status      = "ENABLED"

  additional_configuration {
    name   = "EC2_AGENT_MANAGEMENT"
    status = "DISABLED"
  }
  additional_configuration {
    name   = "ECS_FARGATE_AGENT_MANAGEMENT"
    status = "DISABLED"
  }
  additional_configuration {
    name   = "EKS_ADDON_MANAGEMENT"
    status = "DISABLED"
  }
}

# ---------------------------------------------------------------------------
# 3. AWS CLI command to configure malware scan settings
#    (EBS snapshots not retained)
# ---------------------------------------------------------------------------
resource "null_resource" "configure_malware_scan" {
  depends_on = [aws_guardduty_detector.main]

  provisioner "local-exec" {
    command = "aws guardduty update-malware-scan-settings --detector-id ${aws_guardduty_detector.main.id} --ebs-snapshot-preservation NO_RETENTION"
  }
}

# ---------------------------------------------------------------------------
# 4. Conditional: Findings Filter  (not created by default)
# ---------------------------------------------------------------------------
resource "aws_guardduty_filter" "findings" {
  count       = var.create_findings_filter ? 1 : 0
  detector_id = aws_guardduty_detector.main.id
  name        = var.findings_filter_name
  action      = "ARCHIVE"
  rank        = 1

  finding_criteria {
    criterion {
      field  = "severity"
      equals = ["HIGH"]
    }
  }

  tags = {
    Repo = var.repo_url
  }
}

# ---------------------------------------------------------------------------
# 5. Conditional: Trusted IP Set  (not created by default)
# ---------------------------------------------------------------------------
resource "aws_guardduty_ipset" "trusted" {
  count       = var.create_trusted_ip_set ? 1 : 0
  detector_id = aws_guardduty_detector.main.id
  name        = var.trusted_ip_set_name
  activate    = true
  format      = "TXT"
  location    = "https://example.com/trusted-ips.txt"

  tags = {
    Repo = var.repo_url
  }
}

# ---------------------------------------------------------------------------
# 6. Conditional: Threat Intelligence Set  (not created by default)
# ---------------------------------------------------------------------------
resource "aws_guardduty_threatintelset" "threat" {
  count       = var.create_threat_intel_set ? 1 : 0
  detector_id = aws_guardduty_detector.main.id
  name        = var.threat_intel_set_name
  activate    = true
  format      = "TXT"
  location    = "https://example.com/threat-intel.txt"

  tags = {
    Repo = var.repo_url
  }
}

# ---------------------------------------------------------------------------
# 7. Conditional: Malware Protection Plan for S3  (not created by default)
# ---------------------------------------------------------------------------
resource "aws_guardduty_malware_protection_plan" "s3" {
  count = var.create_malware_protection_plan ? 1 : 0
  # The role is required; in a real deployment this would be an existing role
  # or one created alongside the plan.
  role = data.aws_caller_identity.current.account_id

  protected_resource {
    s3_bucket {
      bucket_name = "placeholder-for-malware-protection"
    }
  }

  tags = {
    Repo = var.repo_url
  }
}

# ---------------------------------------------------------------------------
# 8. Conditional: Export Destination
#    (S3 + KMS + Replication — none created by default)
# ---------------------------------------------------------------------------
locals {
  export_bucket_name = "${var.export_bucket_name_prefix}-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}"
}

resource "aws_kms_key" "export" {
  count                   = var.create_export_destination ? 1 : 0
  description             = "KMS key for GuardDuty export bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = {
    Repo = var.repo_url
  }
}

resource "aws_iam_role" "replication" {
  count = var.create_export_destination ? 1 : 0
  name  = "guardduty-export-replication-${data.aws_region.current.name}"
  path  = "/guardduty/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Repo = var.repo_url
  }
}

resource "aws_s3_bucket" "export" {
  count  = var.create_export_destination ? 1 : 0
  bucket = local.export_bucket_name

  tags = {
    Repo = var.repo_url
  }
}

resource "aws_s3_bucket_public_access_block" "export" {
  count                   = var.create_export_destination ? 1 : 0
  bucket                  = aws_s3_bucket.export[count.index].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "export" {
  count  = var.create_export_destination ? 1 : 0
  bucket = aws_s3_bucket.export[count.index].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_logging" "export" {
  count         = var.create_export_destination ? 1 : 0
  bucket        = aws_s3_bucket.export[count.index].id
  target_bucket = aws_s3_bucket.export_logging[count.index].id
  target_prefix = "access-logs/"
}

resource "aws_s3_bucket_server_side_encryption_configuration" "export" {
  count  = var.create_export_destination ? 1 : 0
  bucket = aws_s3_bucket.export[count.index].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.export[count.index].id
      sse_algorithm     = "AES256"
    }
  }
}

resource "aws_s3_bucket" "export_logging" {
  count  = var.create_export_destination ? 1 : 0
  bucket = "${local.export_bucket_name}-logging"

  tags = {
    Repo = var.repo_url
  }
}

resource "aws_s3_bucket_public_access_block" "export_logging" {
  count                   = var.create_export_destination ? 1 : 0
  bucket                  = aws_s3_bucket.export_logging[count.index].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "export_logging" {
  count  = var.create_export_destination ? 1 : 0
  bucket = aws_s3_bucket.export_logging[count.index].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.export[count.index].id
      sse_algorithm     = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "export_logging" {
  count  = var.create_export_destination ? 1 : 0
  bucket = aws_s3_bucket.export_logging[count.index].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_replication_configuration" "export" {
  count = var.create_export_destination ? 1 : 0
  bucket = aws_s3_bucket.export[count.index].id
  role   = aws_iam_role.replication[count.index].arn

  rule {
    id       = "cross-region-replication"
    status   = "Enabled"
    priority = 10

    destination {
      bucket = "${var.export_bucket_name_prefix}-${data.aws_caller_identity.current.account_id}-${var.replication_region}"
    }
  }
}

resource "aws_guardduty_publishing_destination" "export" {
  count       = var.create_export_destination ? 1 : 0
  detector_id = aws_guardduty_detector.main.id
  destination_type = "S3"
  destination_arn  = aws_s3_bucket.export[count.index].arn
  kms_key_arn      = aws_kms_key.export[count.index].arn
}
